#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_AIN0 0x4000   // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0200 // +/-4.096V gain
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0060  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0010 // Traditional comparator
#define CONFIG_COMP_POL_ACTV_LOW 0x0008 // Active low comparator
#define CONFIG_COMP_LAT_NON_LATCH 0x0004 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the ADS1115
int init_ads1115() {
    // Construct the configuration register value
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_AIN0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_ACTV_LOW | CONFIG_COMP_LAT_NON_LATCH | CONFIG_COMP_QUE_DISABLE;

    // Write the configuration to the ADS1115
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read the conversion result from the ADS1115
int16_t read_ads1115() {
    char buf[1];
    char read_buf[2];

    // Set the pointer register to the conversion register
    buf[0] = ADS1115_REG_CONVERT;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 pointer register: %d\n", result);
        return -1;
    }

    // Read the conversion result (2 bytes)
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t value = (read_buf[0] << 8) | read_buf[1];

    return value;
}

// Function to convert the ADC reading to amperes
float convert_to_amperes(int16_t adc_value) {
    // ADS1115 gain = +/-4.096V, so the full-scale range is 4.096V.
    // Assuming a linear relationship between the sensor output and the current.
    // This is a simplified example and may need calibration for your specific sensor.
    float voltage = (float)adc_value * 4.096 / 32767.0; // Convert ADC value to voltage
    float current = voltage / 0.1; // Assuming 0.1V/A sensitivity (adjust as needed)
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() != 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read the ADC value
        int16_t adc_value = read_ads1115();
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value\n");
        } else {
            // Convert the ADC value to amperes
            float current = convert_to_amperes(adc_value);

            // Log the current value to the console
            printf("Current: %.3f A\n", current);
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

