#include <pigpio.h>
#include <math.h>

// Configuration
#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_VALUE 0xC283 // Single-shot, AIN0, +/-4.096V, 128 SPS
#define TEMP_THRESHOLD 60.0
#define DEBOUNCE_DELAY 50 // milliseconds
#define BUZZER_DURATION 2 // seconds
#define POLLING_INTERVAL 100 // milliseconds

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
int read_flame_sensor();
float read_temperature_sensor();
void activate_buzzer();
void log_event(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int raw_value = gpioRead(FLAME_SENSOR_GPIO);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    int debounced_value = gpioRead(FLAME_SENSOR_GPIO);

    // Return 1 if both reads are low (flame detected), 0 otherwise
    return (raw_value == 0 && debounced_value == 0) ? 1 : 0;
}

// Function to read the temperature sensor from ADS1115
float read_temperature_sensor() {
    char config[3];
    char conversion[2];
    int16_t raw_value;
    float voltage, temperature;

    // Write configuration register
    config[0] = ADS1115_CONFIG_REG;
    config[1] = (ADS1115_CONFIG_VALUE >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_VALUE & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register.\n");
        return -1.0; // Indicate error
    }

    gpioDelay(1000); // Wait for conversion (at least 125ms for 8 SPS)

    // Read conversion register
    config[0] = ADS1115_CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register.\n");
        return -1.0; // Indicate error
    }

    if (i2cReadDevice(i2c_handle, conversion, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register.\n");
        return -1.0; // Indicate error
    }

    raw_value = (conversion[0] << 8) | conversion[1];

    // Convert raw value to voltage (assuming +/- 4.096V range)
    voltage = (float)raw_value * 4.096 / 32768.0;

    // Convert voltage to temperature (Celsius) - Example linear approximation
    temperature = voltage * 100.0; // Replace with actual calibration

    return temperature;
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn on buzzer
    gpioDelay(BUZZER_DURATION * 1000000); // Wait for 2 seconds
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off buzzer
    gpioWrite(BUZZER_GPIO, 0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_detected = read_flame_sensor();
        float temperature = read_temperature_sensor();

        if (temperature < 0) {
            log_event("Error reading temperature sensor.");
        } else {
            if (flame_detected && temperature > TEMP_THRESHOLD) {
                log_event("Fire detected!");
                activate_buzzer();
            } else if (flame_detected) {
                log_event("Flame detected!");
            } else if (temperature > TEMP_THRESHOLD) {
                char temp_str[50];
                snprintf(temp_str, sizeof(temp_str), "Temperature: %.2f C", temperature);
                log_event(temp_str);
            }
        }

        gpioDelay(POLLING_INTERVAL * 1000); // Polling interval
    }

    cleanup();
    return 0;
}

