#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define FAN_GPIO 18
#define CURRENT_THRESHOLD 10.0 // Amperes
#define SENSITIVITY 0.1 // Amperes per ADC unit (example value)
#define OFFSET 0.0 // Amperes (example value)
#define LOG_FILE "current_log.txt"

// Global variables
int spi_fd = -1;
int gpio_initialized = 0;
FILE *log_file = NULL;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_adc(int fd, int channel);
float calculate_current(int adc_value, float sensitivity, float offset);
int log_data(FILE *fp, float current);
int control_fan(int gpio, int state);
void signal_handler(int signal);

// SPI Initialization
int spi_init(const char *device, uint8_t mode, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read ADC value from MCP3008
int read_adc(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message for MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed in read_adc\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Calculate current from ADC value
float calculate_current(int adc_value, float sensitivity, float offset) {
    return adc_value * sensitivity + offset;
}

// Log data to file
int log_data(FILE *fp, float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s, %.2f\n", timestamp, current) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Control fan using pigpio
int control_fan(int gpio, int state) {
    if (!gpio_initialized) {
        fprintf(stderr, "pigpio not initialized. Cannot control fan.\n");
        return -1;
    }
    gpioWrite(gpio, state);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Shutting down...\n", signal);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Turn off fan
    if (gpio_initialized) {
        control_fan(FAN_GPIO, 0); // Turn off fan
        gpioTerminate();
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed. Exiting.\n");
    } else {
        gpio_initialized = 1;
        gpioSetMode(FAN_GPIO, PI_OUTPUT);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        // Continue without logging, but print to stderr
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read ADC value
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Check for sensor absence
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent or malfunctioning. ADC value: %d\n", adc_value);
            if (log_file != NULL) {
                fprintf(log_file, "Sensor absent or malfunctioning. ADC value: %d\n", adc_value);
            }
            sleep(1);
            continue;
        }

        // Calculate current
        float current = calculate_current(adc_value, SENSITIVITY, OFFSET);

        // Log data
        if (log_file != NULL) {
            if (log_data(log_file, current) < 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            printf("Current: %.2f A\n", current);
        }

        // Control fan
        if (gpio_initialized) {
            if (current > CURRENT_THRESHOLD) {
                control_fan(FAN_GPIO, 1); // Turn on fan
            } else {
                control_fan(FAN_GPIO, 0); // Turn off fan
            }
        }

        sleep(1); // Sample every second
    }

    return 0;
}

