#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_DEFAULT 0x4083 // Single-shot, +/-4.096V, 128 SPS, AIN0
#define CO_LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    char *log_file;
    int sample_interval;
} sensor_config_t;

// Function prototypes
int initialize_i2c(int i2c_bus, int ads1115_address);
int read_adc(int i2c_handle);
double calculate_ppm(int raw_reading);
int log_ppm(const char *log_file, double ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c(int i2c_bus, int ads1115_address) {
    i2c_handle = i2cOpen(i2c_bus, ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-shot mode, +/-4.096V, 128 SPS, AIN0
    char config_data[3];
    config_data[0] = ADS1115_CONFIG_REG;
    config_data[1] = (ADS1115_CONFIG_DEFAULT >> 8) & 0xFF;
    config_data[2] = ADS1115_CONFIG_DEFAULT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, config_data, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read ADC value from ADS1115
int read_adc(int i2c_handle) {
    char conversion_data[2];
    int16_t raw_reading;

    // Start a single conversion
    char config_data[3];
    config_data[0] = ADS1115_CONFIG_REG;
    config_data[1] = (ADS1115_CONFIG_DEFAULT >> 8) & 0xFF;
    config_data[2] = ADS1115_CONFIG_DEFAULT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, config_data, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    result = i2cReadDevice(i2c_handle, conversion_data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    raw_reading = (conversion_data[0] << 8) | conversion_data[1];
    return raw_reading;
}

// Calculate CO concentration in ppm using a logarithmic curve
double calculate_ppm(int raw_reading) {
    // Example logarithmic curve (adjust based on sensor datasheet)
    // ppm = 10^((log10(raw_reading) - log10(R0)) / slope)
    // Where R0 is the sensor resistance at a known CO concentration (e.g., 100 ppm)
    // and slope is a constant determined experimentally.

    // Example values (replace with your sensor's calibration data)
    double R0 = 1000.0; // Sensor resistance at 100 ppm
    double slope = 0.5;  // Example slope

    // Ensure raw_reading is positive to avoid log10 errors
    if (raw_reading <= 0) {
        return 0.0; // Or some other appropriate error value
    }

    double ppm = pow(10.0, ((log10((double)raw_reading) - log10(R0)) / slope));
    return ppm;
}

