    if (initialize_i2c(I2C_BUS, ADS1115_ADDR) != 0) {
        cleanup();
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int raw_reading = read_adc(i2c_handle);
        if (raw_reading < 0) {
            fprintf(stderr, "Error reading ADC value\n");
        } else {
