#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CS_PIN 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define temperature sensor calibration parameters
#define ADC_MIN 200
#define ADC_MAX 800
#define TEMP_MIN 20.0
#define TEMP_MAX 80.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
void log_data(int flame_detected, float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS_PIN, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS_PIN, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d): %s\n", result, strerror(errno));
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to temperature
float adc_to_temperature(int adc_value) {
    if (adc_value < ADC_MIN) {
        return TEMP_MIN;
    } else if (adc_value > ADC_MAX) {
        return TEMP_MAX;
    }

    return TEMP_MIN + (float)(adc_value - ADC_MIN) * (TEMP_MAX - TEMP_MIN) / (ADC_MAX - ADC_MIN);
}

// Function to log data to a CSV file
void log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flame Detected,Temperature (C)\n");
    }
    fflush(log_file);

    return 0;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        int flame_detected = read_flame_sensor();
        int adc_value = read_mcp3008(MCP3008_CHANNEL);

        if (adc_value >= 0) {
            float temperature = adc_to_temperature(adc_value);
            log_data(flame_detected, temperature);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

