#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC1_CS 8
#define MIC2_CS 9
#define LED_PIN 27

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define RMS threshold
#define RMS_THRESHOLD 500.0

// Define sampling window
#define SAMPLING_WINDOW_MS 100
#define SAMPLES_PER_CHANNEL 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold audio data
typedef struct {
    int16_t mic1_samples[SAMPLES_PER_CHANNEL];
    int16_t mic2_samples[SAMPLES_PER_CHANNEL];
} AudioData;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
double calculate_rms(int16_t *samples, int num_samples);
void log_data(time_t timestamp, double mic1_rms, double mic2_rms);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MIC1_CS, 0); // Select the chip
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MIC1_CS, 1); // Deselect the chip

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate RMS level
double calculate_rms(int16_t *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to log data to file
void log_data(time_t timestamp, double mic1_rms, double mic2_rms) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp_str, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MIC1_CS, PI_OUTPUT);
    gpioSetMode(MIC2_CS, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    AudioData audio_data;
    time_t start_time, current_time;
    double mic1_rms, mic2_rms;

    printf("Starting audio sampling...\n");

    while (program_running) {
        start_time = time(NULL);

        // Sample audio for 100ms
        for (int i = 0; i < SAMPLES_PER_CHANNEL; i++) {
            // Read microphone 1
            int adc_value1 = read_mcp3008(0); // Channel 0
            if (adc_value1 < 0) {
                fprintf(stderr, "Error reading microphone 1, exiting...\n");
                program_running = 0;
                break;
            }
            audio_data.mic1_samples[i] = (int16_t)adc_value1;

            // Read microphone 2
            int adc_value2 = read_mcp3008(1); // Channel 1
            if (adc_value2 < 0) {
                fprintf(stderr, "Error reading microphone 2, exiting...\n");
                program_running = 0;
                break;
            }
            audio_data.mic2_samples[i] = (int16_t)adc_value2;

            gpioDelay(1); // 1ms delay
        }

        if (!program_running) break;

        // Calculate RMS levels
        mic1_rms = calculate_rms(audio_data.mic1_samples, SAMPLES_PER_CHANNEL);
        mic2_rms = calculate_rms(audio_data.mic2_samples, SAMPLES_PER_CHANNEL);

        // Log data
        log_data(start_time, mic1_rms, mic2_rms);

        // Check for threshold exceedance and control LED
        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            control_led(1); // Turn on LED
            gpioDelay(500);  // Keep LED on for 500ms
            control_led(0); // Turn off LED
        }

        // Wait for the remaining time to complete 100ms window
        current_time = time(NULL);
        long elapsed_time_ms = (current_time - start_time) * 1000; // Convert seconds to milliseconds
        if (elapsed_time_ms < SAMPLING_WINDOW_MS) {
            gpioDelay(SAMPLING_WINDOW_MS - elapsed_time_ms); // Delay to maintain 100ms window
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

