#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define SAMPLE_RATE 10 // Hz
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0 // Amperes
#define VOLTAGE_RANGE 4.096 // Volts (ADS1115 +/- 4.096V)
#define MAX_CURRENT 100.0 // Amperes (Example: 100A full scale)
#define MAX_VOLTAGE VOLTAGE_RANGE // Volts

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int16_t read_adc();
float convert_to_current(int16_t adc_value);
void update_circular_buffer(float current);
float calculate_average_current();
void control_led(int on);
void signal_handler(int signal);

// Structure for ADS1115 configuration
typedef struct {
    uint16_t config;
} ads1115_config_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read the ADC value from the ADS1115
int16_t read_adc() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ADC value: %d\n", result);
        return -1;
    }
    int16_t adc_value = (buf[0] << 8) | buf[1];
    return adc_value;
}

// Function to convert the ADC value to current
float convert_to_current(int16_t adc_value) {
    float voltage = (float)adc_value * VOLTAGE_RANGE / 32767.0; // Assuming 16-bit ADC
    float current = (voltage / MAX_VOLTAGE) * MAX_CURRENT;
    return current;
}

// Function to update the circular buffer
void update_circular_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average current
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115 (Single-ended A0, +/-4.096V, 128 SPS)
    ads1115_config_t config;
    config.config = 0x4003; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    char config_buf[3];
    config_buf[0] = CONFIG_REG;
    config_buf[1] = (config.config >> 8) & 0xFF;
    config_buf[2] = config.config & 0xFF;

    if (i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, config_buf + 1, 2) != 2) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to current
        float current = convert_to_current(adc_value);

        // Update circular buffer
        update_circular_buffer(current);

        // Calculate average current
        float average_current = calculate_average_current();

        // Check threshold and control LED
        if (average_current > CURRENT_THRESHOLD) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        // Wait for the next sample
        gpioDelay(1000 / SAMPLE_RATE); // Delay in milliseconds
    }

    // Cleanup
    control_led(0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

