#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Expected sensor ID
#define TCS34725_EXPECTED_ID 0x44

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init();
int tcs34725_read_raw_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue);
int log_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Initialize TCS34725 sensor
int tcs34725_init() {
    int status;
    int retries = 0;
    unsigned char id;

    // Enable the sensor (power on and enable RGBC)
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03); // PON + AEN
        if (status == 0) break;
        fprintf(stderr, "Error writing to ENABLE register (attempt %d): %s\n", retries + 1, strerror(errno));
        gpioDelay(1000); // Wait 1 ms before retrying
        retries++;
    }
    if (status != 0) {
        fprintf(stderr, "Failed to enable sensor after multiple retries.\n");
        return -1;
    }

    // Set integration time (ATIME) - 2.4ms
    retries = 0;
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5); // 101ms integration time
        if (status == 0) break;
        fprintf(stderr, "Error writing to ATIME register (attempt %d): %s\n", retries + 1, strerror(errno));
        gpioDelay(1000); // Wait 1 ms before retrying
        retries++;
    }
    if (status != 0) {
        fprintf(stderr, "Failed to set integration time after multiple retries.\n");
        return -1;
    }

    // Set gain (AGAIN) - 60x
    retries = 0;
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01); // Gain = 60x
        if (status == 0) break;
        fprintf(stderr, "Error writing to CONTROL register (attempt %d): %s\n", retries + 1, strerror(errno));
        gpioDelay(1000); // Wait 1 ms before retrying
        retries++;
    }
    if (status != 0) {
        fprintf(stderr, "Failed to set gain after multiple retries.\n");
        return -1;
    }

    // Verify sensor ID
    retries = 0;
    while (retries < 3) {
        id = i2cReadByteData(i2c_handle, TCS34725_ID);
        if (id >= 0) break; // Success
        fprintf(stderr, "Error reading ID register (attempt %d): %s\n", retries + 1, strerror(errno));
        gpioDelay(1000); // Wait 1 ms before retrying
        retries++;
    }
    if (id < 0) {
        fprintf(stderr, "Failed to read sensor ID after multiple retries.\n");
        return -1;
    }

    if (id != TCS34725_EXPECTED_ID) {
        fprintf(stderr, "Error: Incorrect sensor ID (0x%02X, expected 0x%02X)\n", id, TCS34725_EXPECTED_ID);
        return -1;
    }

    return 0;
}

// Read raw color data from the sensor
int tcs34725_read_raw_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue) {
    int status;
    int retries = 0;

    while (retries < 3) {
        *clear = i2cReadWordData(i2c_handle, TCS34725_CDATA);
        if (*clear >= 0) break;
        fprintf(stderr, "Error reading clear data (attempt %d): %s\n", retries + 1, strerror(errno));
        gpioDelay(1000); // Wait 1 ms before retrying
        retries++;
    }
    if (*clear < 0) {
        fprintf(stderr, "Failed to read clear data after multiple retries.\n");
        return -1;
    }

    retries = 0;
    while (retries < 3) {
        *red = i2cReadWordData(i2c_handle, TCS34725_RDATA);
        if (*red >= 0) break;
        fprintf(stderr, "Error reading red data (attempt %d): %s\n", retries + 1, strerror(errno));
        gpioDelay(1000); // Wait 1 ms before retrying
        retries++;
    }
    if (*red < 0) {
        fprintf(stderr, "Failed to read red data after multiple retries.\n");
        return -1;
    }

    retries = 0;
    while (retries < 3) {
        *green = i2cReadWordData(i2c_handle, TCS34725_GDATA);
        if (*green >= 0) break;
        fprintf(stderr, "Error reading green data (attempt %d): %s\n", retries + 1, strerror(errno));
        gpioDelay(1000); // Wait 1 ms before retrying
        retries++;
    }
    if (*green < 0) {
        fprintf(stderr, "Failed to read green data after multiple retries.\n");
        return -1;
    }

    retries = 0;
    while (retries < 3) {
        *blue = i2cReadWordData(i2c_handle, TCS34725_BDATA);
        if (*blue >= 0) break;
        fprintf(stderr, "Error reading blue data (attempt %d): %s\n", retries + 1, strerror(errno));
        gpioDelay(1000); // Wait 1 ms before retrying
        retries++;
    }
    if (*blue < 0) {
        fprintf(stderr, "Failed to read blue data after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Log data to CSV file
int log_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp.\n");
        return -1;
    }

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    free(timestamp); // Free the allocated memory
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

int main() {
    int status;
    unsigned int clear, red, green, blue;
    struct timespec sleep_time = {1, 0}; // 1 second
    struct timespec remaining_time;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init() != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read color data
        if (tcs34725_read_raw_data(&clear, &red, &green, &blue) == 0) {
            // Log data
            if (log_data(clear, red, green, blue) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading color data\n");
        }

        // Wait for 1 second using nanosleep
        status = nanosleep(&sleep_time, &remaining_time);
        if (status != 0) {
            if (errno == EINTR) {
                fprintf(stderr, "nanosleep interrupted by signal\n");
            } else {
                fprintf(stderr, "nanosleep error: %s\n", strerror(errno));
            }
        }
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

