    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Moisture sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor values
        int moisture1 = read_mcp3008(MCP3008_CHANNEL_0);
        int moisture2 = read_mcp3008(MCP3008_CHANNEL_1);

