#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define MOTOR_SHUTDOWN_PIN 17
#define ADC_CHANNEL 0
#define ADC_VREF 3.3
#define SENSITIVITY 0.1 // Amperes per Volt
#define OVERCURRENT_THRESHOLD 10.0
#define LOG_FILE "current_log.csv"
#define MAX_RETRIES 3

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(void);
int read_adc(int channel);
float adc_to_amperes(int adc_value);
int log_current(float current);
void overcurrent_protection(float current);
void signal_handler(int sig);
int write_header(void);

// SPI Initialization
int spi_init(void) {
    int ret = 0;
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000; // 1 MHz

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &mode);
    if (ret == -1) {
        perror("Error getting SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error getting bits per word");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting max speed hz");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error getting max speed hz");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;
    int ret, adc_value;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    for (int i = 0; i < MAX_RETRIES; i++) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret > 0) {
            // Extract ADC value (10 bits)
            adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            perror("SPI transaction failed");
            fprintf(stderr, "Retry %d\n", i + 1);
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Convert ADC reading to amperes
float adc_to_amperes(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * ADC_VREF;
    float current = voltage / SENSITIVITY;
    return current;
}

// Log current to file
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a+");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        // Check if the file is empty or doesn't exist, and write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            if (write_header() != 0) {
                fprintf(stderr, "Failed to write header to log file.\n");
                fclose(log_file);
                log_file = NULL;
                return -1;
            }
        }
        fseek(log_file, 0, SEEK_END); // Append mode
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Overcurrent protection
void overcurrent_protection(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        printf("Overcurrent detected! Current: %.2f A\n", current);
        digitalWrite(MOTOR_SHUTDOWN_PIN, LOW); // Disable motor
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,OVERCURRENT,%.2f\n", timestamp, current);
        fflush(log_file);

        sleep(1);
        digitalWrite(MOTOR_SHUTDOWN_PIN, HIGH); // Re-enable motor
        printf("Motor re-enabled.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    keep_running = 0;

    if (spi_fd != -1) {
        close(spi_fd);
