        // Read pressure
        if (read_pressure(&pressure_kPa) == 0) {
            data.pressure_kPa = pressure_kPa;

            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = gmtime(&rawtime);
