            fprintf(stderr, "Failed to read pressure, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            i2cClose(i2c_handle);
            i2c_handle = -1; // Reset handle to force re-initialization
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

