#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_LED 17
#define PRESSURE_SCALE_FACTOR 0.1 // kPa/ADC unit (example value, adjust based on calibration)
#define TEMPERATURE_SCALE_FACTOR 0.01 // °C/ADC unit (example value, adjust based on calibration)
#define TEMPERATURE_OFFSET 25.0 // °C (example value, adjust based on calibration)
#define PRESSURE_THRESHOLD 105.0 // kPa

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_ads1115_channel(int channel);
float calculate_pressure(int adc_value);
float calculate_temperature(int adc_value);
void control_led(int state);
void signal_handler(int signal);

// Structure for ADS1115 configuration
typedef struct {
    unsigned int os : 1;   // Operational status/single-shot start
    unsigned int mux : 3;  // Input multiplexer configuration
    unsigned int pga : 3;  // Programmable gain amplifier configuration
    unsigned int mode : 1; // Device operating mode
    unsigned int dr : 3;   // Data rate
    unsigned int comp_mode : 1; // Comparator mode
    unsigned int comp_pol : 1; // Comparator polarity
    unsigned int comp_lat : 1; // Comparator latch enabled
    unsigned int comp_que : 2; // Comparator queue and disable
} ads1115_config_t;

// Function to read a channel from the ADS1115
int read_ads1115_channel(int channel) {
    int retries = 3;
    int adc_value = 0;
    unsigned char config[3];

    // Configure the ADS1115 for single-ended mode and 4.096V range
    ads1115_config_t config_data;
    config_data.os = 1; // Start a single conversion
    config_data.mux = (channel == 0) ? 4 : 5; // AIN0 or AIN1
    config_data.pga = 1; // +/- 4.096V
    config_data.mode = 1; // Single-shot mode
    config_data.dr = 3; // 128 SPS
    config_data.comp_mode = 0; // Traditional comparator
    config_data.comp_pol = 0; // Active low
    config_data.comp_lat = 0; // Non-latching comparator
    config_data.comp_que = 3; // Disable comparator

    config[0] = CONFIG_REG;
    config[1] = (config_data.os << 7) | (config_data.mux << 4) | (config_data.pga << 1) | config_data.mode;
    config[2] = (config_data.dr << 5) | (config_data.comp_mode << 4) | (config_data.comp_pol << 3) | (config_data.comp_lat << 2) | (config_data.comp_que << 0);

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
            fprintf(stderr, "Error writing to ADS1115 configuration register. Retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
            continue;
        }

        gpioDelay(10); // Wait for conversion (adjust based on data rate)

        char data[2];
        if (i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, data, 2) == 2) {
            adc_value = (data[0] << 8) | data[1];
            return adc_value;
        } else {
            fprintf(stderr, "Error reading from ADS1115 conversion register. Retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read from ADS1115 after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to calculate pressure in kPa
float calculate_pressure(int adc_value) {
    return adc_value * PRESSURE_SCALE_FACTOR;
}

// Function to calculate temperature in °C
float calculate_temperature(int adc_value) {
    return adc_value * TEMPERATURE_SCALE_FACTOR + TEMPERATURE_OFFSET;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(GPIO_LED, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int pressure_adc = read_ads1115_channel(0);
        int temperature_adc = read_ads1115_channel(1);

        if (pressure_adc != -1 && temperature_adc != -1) {
            float pressure = calculate_pressure(pressure_adc);
            float temperature = calculate_temperature(temperature_adc);

            printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

            if (pressure > PRESSURE_THRESHOLD) {
                control_led(1); // Turn LED on
            } else {
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping LED control.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

