#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR_ENABLE_PIN 27
#define SPI_CE_PIN 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define overcurrent threshold
#define OVERCURRENT_THRESHOLD 10.0 // 10 Amperes

// Define sensor sensitivity (adjust based on datasheet)
#define SENSOR_SENSITIVITY 0.1 // Example: 0.1 V/A

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_adc_to_current(int adc_value);
void log_current_reading(float current);
void handle_overcurrent();
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold configuration data
typedef struct {
    int motor_enable_pin;
    int spi_ce_pin;
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int mcp3008_channel;
    float overcurrent_threshold;
    float sensor_sensitivity;
} Config;

Config config = {
    MOTOR_ENABLE_PIN,
    SPI_CE_PIN,
    SPI_CHANNEL,
    SPI_SPEED,
    SPI_MODE,
    MCP3008_CHANNEL,
    OVERCURRENT_THRESHOLD,
    SENSOR_SENSITIVITY
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    while (!terminate) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float current = convert_adc_to_current(adc_value);
        log_current_reading(current);

        if (current > config.overcurrent_threshold) {
            handle_overcurrent();
            break; // Exit the loop after overcurrent
        }

        gpioDelay(100); // Sample every 100 ms
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set motor enable pin as output
    gpioSetMode(config.motor_enable_pin, PI_OUTPUT);
    gpioWrite(config.motor_enable_pin, 0); // Initially LOW

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

float convert_adc_to_current(int adc_value) {
    // Assuming ADC range is 0-1023 (10 bits)
    float voltage = (float)adc_value / 1023.0 * 3.3; // Assuming 3.3V reference
    float current = voltage / config.sensor_sensitivity; // Convert voltage to current
    return current;
}

void log_current_reading(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately
}

void handle_overcurrent() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, OVERCURRENT DETECTED! Current exceeds %.2f A\n", timestamp, config.overcurrent_threshold);
    fflush(log_file);

    gpioWrite(config.motor_enable_pin, 1); // Set HIGH to disable motor
    fprintf(stderr, "OVERCURRENT! Motor disabled.\n");
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.motor_enable_pin, 0); // Set LOW before exiting
    gpioTerminate();
}

