#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SPI_CE0 8
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define ALARM_PIN 4

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define CO sensor parameters
#define VREF 3.3
#define CO_CHANNEL 0

// Define alarm threshold
#define ALARM_THRESHOLD 2.5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
void log_data(float voltage);
void control_alarm(float voltage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold configuration data
typedef struct {
    int spi_ce0;
    int spi_sclk;
    int spi_mosi;
    int spi_miso;
    int alarm_pin;
    int spi_channel;
    int spi_speed;
    int spi_mode;
    float vref;
    float alarm_threshold;
} Config;

Config config = {
    SPI_CE0, SPI_SCLK, SPI_MOSI, SPI_MISO, ALARM_PIN, SPI_CHANNEL, SPI_SPEED, SPI_MODE, VREF, ALARM_THRESHOLD
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(CO_CHANNEL);
        if (adc_value >= 0) {
            float voltage = adc_to_voltage(adc_value);
            log_data(voltage);
            control_alarm(voltage);
        } else {
            fprintf(stderr, "Failed to read ADC value. Retrying in 1 second.\n");
            gpioWrite(config.alarm_pin, 0); // Turn off alarm in case of error
            sleep(1);
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set alarm pin as output
    gpioSetMode(config.alarm_pin, PI_OUTPUT);
    gpioWrite(config.alarm_pin, 0); // Initially turn off the alarm

    // Open log file
    log_file = fopen("co_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

void cleanup() {
    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Turn off alarm
    gpioWrite(config.alarm_pin, 0);

    // Terminate pigpio
    gpioTerminate();
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * config.vref;
}

void log_data(float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
    fflush(log_file); // Ensure data is written to file immediately
}

void control_alarm(float voltage) {
    if (voltage > config.alarm_threshold) {
        gpioWrite(config.alarm_pin, 1); // Turn on alarm
    } else {
        gpioWrite(config.alarm_pin, 0); // Turn off alarm
    }
}

void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

