#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096 // +/- 4.096V
#define MAX_PRESSURE 100.0 // kPa
#define MIN_PRESSURE 0.0   // kPa
#define SAMPLE_RATE 1.0     // Hz
#define SLEEP_TIME (1.0 / SAMPLE_RATE) // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    double reference_voltage;
    double max_pressure;
    double min_pressure;
    double sample_rate;
} config_t;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_adc_value();
double convert_to_pressure(int adc_value);
int validate_pressure(double pressure);
int log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure ADS1115 for single-ended AIN0, +/-4.096V, 128 SPS
int configure_ads1115() {
    uint16_t config = 0x4003; // Single-shot, AIN0, +/-4.096V, 128 SPS, disable comparator

    // Write the configuration register
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read ADC value from ADS1115
int read_adc_value() {
    char buf[1];
    char read_buf[2];
    int16_t adc_value;

    // Set pointer to conversion register
    buf[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to set conversion register pointer\n");
        return -1;
    }

    // Read two bytes from conversion register
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }

    adc_value = (read_buf[0] << 8) | read_buf[1];

    return adc_value;
}

// Convert ADC value to pressure (kPa)
double convert_to_pressure(int adc_value) {
    double voltage = (adc_value / 32767.0) * REF_VOLTAGE; // Assuming 16-bit ADC
    double pressure = (voltage / REF_VOLTAGE) * MAX_PRESSURE;
    return pressure;
}

// Validate pressure reading
int validate_pressure(double pressure) {
    if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
        fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
        return -1;
    }
    return 0;
}

// Log pressure reading to file
int log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Configuration
    config_t config = {
        .i2c_bus = I2C_BUS,
        .ads1115_address = ADS1115_ADDR,
        .reference_voltage = REF_VOLTAGE,
        .max_pressure = MAX_PRESSURE,
        .min_pressure = MIN_PRESSURE,
        .sample_rate = SAMPLE_RATE
    };

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open pressure_log.txt");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        fclose(log_file);
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        fprintf(stderr, "ADS1115 configuration failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc_value();
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %.2f seconds.\n", SLEEP_TIME);
            sleep(SLEEP_TIME);
            continue;
        }

        // Convert to pressure
        double pressure = convert_to_pressure(adc_value);

        // Validate pressure
        if (validate_pressure(pressure) != 0) {
            fprintf(stderr, "Invalid pressure reading. Skipping logging.\n");
            sleep(SLEEP_TIME);
            continue;
        }

        // Log pressure
        if (log_pressure(pressure) != 0) {
            fprintf(stderr, "Failed to log pressure reading.\n");
        }

        // Wait for the next sample
        sleep(SLEEP_TIME);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

