#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0
#define TMP36_VREF 3.3
#define TMP36_SCALE 0.01
#define TMP36_OFFSET -40.0
#define MIN_TEMP -40.0
#define MAX_TEMP 125.0
#define LOG_FILE "temperature_log.csv"

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3208_channel(int fd, int channel);
float adc_to_temperature(int adc_value);
int log_temperature(float temperature);
void signal_handler(int signal);
int setup();
void cleanup();

// SPI open function
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read MCP3208 channel function
int read_mcp3208_channel(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to temperature conversion function
float adc_to_temperature(int adc_value) {
    float voltage = (adc_value / 4095.0) * TMP36_VREF;
    float temperature = (voltage - TMP36_OFFSET) / TMP36_SCALE;
    return temperature;
}

// Log temperature function
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Check if the file is newly created
    FILE *fp = fopen(LOG_FILE, "r");
    int file_exists = (fp != NULL);
    if (fp) fclose(fp);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    if (!file_exists) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fclose(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Setup function
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        gpioTerminate();
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release pigpio resources
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    if (setup() < 0) {
        return 1;
    }

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3208_channel(spi_fd, MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Continue to the next iteration
        }

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);

        // Validate temperature
        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            continue; // Continue to the next iteration
        }

        // Log temperature
        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Error logging temperature\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    cleanup();
    return 0;
}

