#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1172_ADDR 0x49
#define LOG_FILE "biometric_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Si1172 Register Addresses (Example - Refer to Datasheet for correct values)
#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_SEQ_ID 0x02
#define REG_INT_CFG 0x03
#define REG_INT_EN 0x04
#define REG_RSP0_CFG 0x07
#define REG_RSP1_CFG 0x08
#define REG_RSP2_CFG 0x09
#define REG_RSP3_CFG 0x0A
#define REG_IRQ_STATUS 0x0B
#define REG_ALS_VIS_DATA0 0x10
#define REG_ALS_VIS_DATA1 0x11
#define REG_ALS_IR_DATA0 0x12
#define REG_ALS_IR_DATA1 0x13
#define REG_ALS_PS1_DATA0 0x14
#define REG_ALS_PS1_DATA1 0x15
#define REG_ALS_PS2_DATA0 0x16
#define REG_ALS_PS2_DATA1 0x17
#define REG_ALS_PS3_DATA0 0x18
#define REG_ALS_PS3_DATA1 0x19

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1172();
int read_si1172_data(uint16_t *ir, uint16_t *red);
void log_data(time_t timestamp, uint16_t ir, uint16_t red, int error_flag);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize Si1172 sensor
int init_si1172() {
    // Example initialization sequence (Refer to Si1172 datasheet)
    if (i2cWriteByteData(i2c_handle, REG_INT_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to REG_INT_CFG: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_INT_EN, 0x00) < 0) {
        fprintf(stderr, "Error writing to REG_INT_EN: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_RSP0_CFG, 0x01) < 0) {
        fprintf(stderr, "Error writing to REG_RSP0_CFG: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_RSP1_CFG, 0x02) < 0) {
        fprintf(stderr, "Error writing to REG_RSP1_CFG: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_RSP2_CFG, 0x03) < 0) {
        fprintf(stderr, "Error writing to REG_RSP2_CFG: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_RSP3_CFG, 0x04) < 0) {
        fprintf(stderr, "Error writing to REG_RSP3_CFG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read data from Si1172 sensor
int read_si1172_data(uint16_t *ir, uint16_t *red) {
    uint8_t data[4];

    // Read IR data (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, REG_ALS_IR_DATA0, (char *)data, 4) != 4) {
        fprintf(stderr, "Error reading IR data: %s\n", strerror(errno));
        return -1;
    }

    *ir = (data[1] << 8) | data[0];
    *red = (data[3] << 8) | data[2];

    return 0;
}

// Log data to CSV file
void log_data(time_t timestamp, uint16_t ir, uint16_t red, int error_flag) {
    fprintf(log_file, "%ld,%u,%u,%d\n", timestamp, ir, red, error_flag);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize Si1172 sensor
    if (init_si1172() < 0) {
        fprintf(stderr, "Si1172 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,HR,SpO2,error_flag\n");
        fflush(log_file);
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    uint16_t ir, red;
    time_t timestamp;
    int error_flag;

    while (!terminate) {
        timestamp = time(NULL);
        error_flag = 0;

        if (read_si1172_data(&ir, &red) < 0) {
            error_flag = 1; // I2C read error
            ir = 0; // Set default values
            red = 0;
        }

        log_data(timestamp, ir, red, error_flag);

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

