#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICP-10125 I2C address
#define ICP10125_ADDR 0x69

// ICP-10125 register addresses
#define ICP10125_WHO_AM_I 0x0F
#define ICP10125_RESET 0x80
#define ICP10125_MEASURE 0x71
#define ICP10125_PRESSURE_MSB 0x00
#define ICP10125_TEMPERATURE_MSB 0x03

// Calibration data structure
typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
    int32_t c21;
    int32_t c30;
} icp10125_calibration_data_t;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_calibration_data(int i2c_handle, icp10125_calibration_data_t *calibration_data);
int read_raw_data(int i2c_handle, int32_t *pressure, int32_t *temperature);
double calculate_temperature(int32_t raw_temperature, const icp10125_calibration_data_t *calibration_data);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature, const icp10125_calibration_data_t *calibration_data);
int log_data(FILE *log_file, double temperature, double pressure);
void display_data(double temperature, double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, ICP10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data from the sensor
int read_calibration_data(int i2c_handle, icp10125_calibration_data_t *calibration_data) {
    uint8_t buffer[22];
    if (i2cReadI2CBlockData(i2c_handle, 0x10, (char *)buffer, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calibration_data->c0 = (int32_t)((uint32_t)buffer[0] << 8 | buffer[1]);
    calibration_data->c1 = (int32_t)((uint32_t)buffer[2] << 8 | buffer[3]);
    calibration_data->c00 = (int32_t)((uint32_t)buffer[4] << 8 | buffer[5]);
    calibration_data->c10 = (int32_t)((uint32_t)buffer[6] << 8 | buffer[7]);
    calibration_data->c01 = (int32_t)((uint32_t)buffer[8] << 8 | buffer[9]);
    calibration_data->c11 = (int32_t)((uint32_t)buffer[10] << 8 | buffer[11]);
    calibration_data->c20 = (int32_t)((uint32_t)buffer[12] << 8 | buffer[13]);
    calibration_data->c21 = (int32_t)((uint32_t)buffer[14] << 8 | buffer[15]);
    calibration_data->c30 = (int32_t)((uint32_t)buffer[16] << 8 | buffer[17]);

    return 0;
}

// Read raw pressure and temperature data from the sensor
int read_raw_data(int i2c_handle, int32_t *pressure, int32_t *temperature) {
    uint8_t buffer[6];

    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, ICP10125_MEASURE, 0x07) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for conversion (adjust as needed based on sensor datasheet)
    gpioDelay(10); // 10 ms delay

    // Read pressure and temperature data
    if (i2cReadI2CBlockData(i2c_handle, ICP10125_PRESSURE_MSB, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (int32_t)((uint32_t)buffer[0] << 16 | (uint32_t)buffer[1] << 8 | buffer[2]);
    *temperature = (int32_t)((uint32_t)buffer[3] << 16 | (uint32_t)buffer[4] << 8 | buffer[5]);

    return 0;
}

// Calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temperature, const icp10125_calibration_data_t *calibration_data) {
    double temp = (double)raw_temperature;
    double T = calibration_data->c0 / 100.0 + temp * (calibration_data->c1 / 1000000.0);
    return T;
}

// Calculate pressure in Pascals
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature, const icp10125_calibration_data_t *calibration_data) {
    double P = calibration_data->c00 + raw_pressure * (calibration_data->c10 / 100.0) + raw_temperature * (calibration_data->c01 / 100.0) + raw_pressure * raw_temperature * (calibration_data->c11 / 10000.0) + raw_pressure * raw_pressure * (calibration_data->c20 / 1000000.0) + raw_temperature * raw_temperature * (calibration_data->c21 / 1000000.0) + raw_pressure * raw_pressure * raw_pressure * (calibration_data->c30 / 1000000000.0);
    return P;
}

// Log data to CSV file
int log_data(FILE *log_file, double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file);
    return 0;
}

// Display data on the console
void display_data(double temperature, double pressure) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Pressure (Pa)\n");
    }
    rewind(log_file);

    icp10125_calibration_data_t calibration_data;

    while (!terminate) {
        // Initialize I2C
        if (init_i2c() != 0) {
            fprintf(stderr, "I2C initialization failed, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Read calibration data
        if (read_calibration_data(i2c_handle, &calibration_data) != 0) {
            fprintf(stderr, "Calibration data read failed, retrying in 5 seconds...\n");
            i2cClose(i2c_handle);
            sleep(5);
            continue;
        }

        int32_t raw_pressure, raw_temperature;

        // Read raw data
        if (read_raw_data(i2c_handle, &raw_pressure, &raw_temperature) != 0) {
            fprintf(stderr, "Raw data read failed, retrying in 5 seconds...\n");
            i2cClose(i2c_handle);
            sleep(5);
            continue;
        }

        // Calculate temperature and pressure
        double temperature = calculate_temperature(raw_temperature, &calibration_data);
        double pressure = calculate_pressure(raw_pressure, raw_temperature, &calibration_data);

        // Log data
        log_data(log_file, temperature, pressure);

        // Display data
        display_data(temperature, pressure);

        // Close I2C
        i2cClose(i2c_handle);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    cleanup();

    return 0;
}

