#include <pigpio.h>

// Define MCP3008 pins
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1

// Global variables for signal handling
static volatile int running = 1;
static int spi_handle;

// Signal handler function
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read from MCP3008
int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to apply noise cancellation
int noise_cancellation(int sample1, int sample2, float gain1, float gain2)
{
    return (int)(sample1 * gain1 - sample2 * gain2);
}

int main(int argc, char *argv[])
{
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
