#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_PIN 18
#define FLAME_THRESHOLD 0.5 // 50% of VCC
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define MAX_RETRIES 3

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float read_ambient_temperature();
float compensate_voltage(int raw_adc, float ambient_temp);
void log_data(int raw_adc, float voltage, float compensated_voltage, float ambient_temp, int flame_detected);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;
    int retries = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Dummy byte

    while (retries < MAX_RETRIES) {
        if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == 0) {
            adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            } else {
                fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
                log_data(-1, -1.0, -1.0, -1.0, -1); // Log error
                return -1; // Indicate failure
            }
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d): %s\n", retries + 1, strerror(errno));
            log_data(-1, -1.0, -1.0, -1.0, -1); // Log error
            retries++;
            delay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure after all retries
}

// Function to read ambient temperature from file
float read_ambient_temperature() {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open ambient temperature file. Using default value (25.0).\n");
        return 25.0;
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
        fprintf(stderr, "Warning: Could not read ambient temperature from file. Using default value (25.0).\n");
        fclose(fp);
        return 25.0;
    }

    fclose(fp);
    return temperature;
}

// Function to compensate voltage based on ambient temperature
float compensate_voltage(int raw_adc, float ambient_temp) {
    // Simple linear compensation (replace with your actual compensation formula)
    float voltage = (float)raw_adc / 1023.0 * 3.3; // Assuming VCC = 3.3V
    float compensated_voltage = voltage * (1.0 + 0.001 * (ambient_temp - 25.0)); // Example compensation
    return compensated_voltage;
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float ambient_temp, int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    digitalWrite(BUZZER_PIN, LOW); // Turn off buzzer
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Error: wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Set buzzer pin as output
    pinMode(BUZZER_PIN, OUTPUT);
    digitalWrite(BUZZER_PIN, LOW); // Ensure buzzer is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int raw_adc = read_mcp3008(0);
        if (raw_adc != -1) {
            float ambient_temp = read_ambient_temperature();
            float voltage = (float)raw_adc / 1023.0 * 3.3; // Assuming VCC = 3.3V
            float compensated_voltage = compensate_voltage(raw_adc, ambient_temp);
            int flame_detected = (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;

            log_data(raw_adc, voltage, compensated_voltage, ambient_temp, flame_detected);

            if (flame_detected) {
                digitalWrite(BUZZER_PIN, HIGH); // Turn on buzzer
            } else {
                digitalWrite(BUZZER_PIN, LOW); // Turn off buzzer
            }
        } else {
            digitalWrite(BUZZER_PIN, LOW); // Ensure buzzer is off on error
        }

        delay(500); // Sample every 500ms
    }

    cleanup();
    return 0;
}

