#define SLEEP_INTERVAL_US (SLEEP_INTERVAL_MS * 1000)
#define READ_INTERVAL_SEC 5

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_water_level(int adc_value);
void control_led(float water_level);
void write_json(float water_level);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold program state
typedef struct {
    int spi_handle;
    FILE *json_file;
    int led_state;
} ProgramState;

ProgramState state;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(state.spi_handle, tx_buffer, rx_buffer, 3);
    if (result < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate water level percentage
float calculate_water_level(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to control the LED based on water level
void control_led(float water_level) {
    if (water_level > WATER_LEVEL_THRESHOLD_HIGH && state.led_state == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        state.led_state = 1;
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW && state.led_state == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
        state.led_state = 0;
    }
}

// Function to write data to JSON file
void write_json(float water_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), 4, ".%03dZ", (int)(time(NULL) * 1000) % 1000);

    fprintf(state.json_file, "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, water_level);
