    state.json_file = fopen("water_levels.json", "a");
    if (state.json_file == NULL) {
        fprintf(stderr, "Error: Failed to open water_levels.json\n");
        spiClose(state.spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write opening bracket for JSON array if the file is new
    fseek(state.json_file, 0, SEEK_END);
    long file_size = ftell(state.json_file);
    if (file_size == 0) {
        fprintf(state.json_file, "[");
    } else {
        // If the file is not empty, go back one character and replace the closing bracket
        fseek(state.json_file, -1, SEEK_END);
        int last_char = fgetc(state.json_file);
        if (last_char == ']') {
            fseek(state.json_file, -1, SEEK_END);
            fprintf(state.json_file, ",");
        } else {
            fprintf(stderr, "Warning: water_levels.json is not a valid JSON array.\n");
        }
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off LED
    gpioWrite(LED_GPIO, 0);

    // Close SPI channel
    spiClose(state.spi_handle);

    // Close JSON file and write closing bracket
    if (state.json_file != NULL) {
        fprintf(state.json_file, "]");
        fclose(state.json_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", READ_INTERVAL_SEC);
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        // Calculate water level
        float water_level = calculate_water_level(adc_value);

        // Control LED
        control_led(water_level);

        // Write to JSON file
        write_json(water_level);

        // Print water level to stdout
        printf("Water Level: %.2f%%\n", water_level);

        // Sleep for 5 seconds using usleep
        for (int i = 0; i < READ_INTERVAL_SEC * 1000 / SLEEP_INTERVAL_MS; ++i) {
            usleep(SLEEP_INTERVAL_US);
            if (terminate) break;
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

