#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Define GPIO pins
#define CS_PIN 8

// Define sensor parameters
#define VREF 3.3
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0
#define MIN_ADC 0
#define MAX_ADC 1023

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    char timestamp[32];
} sensor_data_t;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float adc_to_pressure(int adc_value);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Convert ADC value to pressure
float adc_to_pressure(int adc_value) {
    if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0;
    }

    float pressure = MIN_PRESSURE + (adc_value - MIN_ADC) * (MAX_PRESSURE - MIN_PRESSURE) / (MAX_ADC - MIN_ADC);
    return pressure;
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", &timeinfo);
    return timestamp_str;
}

// Log data to console
void log_data(sensor_data_t data) {
    printf("%s Pressure: %.2f kPa\n", data.timestamp, data.pressure);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Pressure sensor data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to pressure
        float pressure = adc_to_pressure(adc_value);
        if (pressure < 0) {
            fprintf(stderr, "Failed to convert ADC to pressure\n");
            continue; // Skip to the next iteration
        }

        // Get timestamp
        char timestamp[32];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log data
        sensor_data_t data = {pressure, timestamp};
        log_data(data);

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

