#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define SAMPLE_INTERVAL 5 // seconds
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
int pump_state = 0; // 0 = off, 1 = on
struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_data(int moisture_level, int pump_state);
void print_log_buffer();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    if (state != pump_state) {
        gpioWrite(PUMP_GPIO, state);
        pump_state = state;
        printf("Pump state changed to: %s\n", state ? "ON" : "OFF");
    }
}

// Function to log data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&log_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Moisture: %d, Pump: %s\n", timestamp_str, log_buffer[index].moisture_level, log_buffer[index].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read moisture level from MCP3008
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
        } else {
            printf("Moisture level: %d\n", moisture_level);

            // Control the pump based on moisture level and hysteresis
            if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
                control_pump(1); // Turn pump ON
            } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
                control_pump(0); // Turn pump OFF
            }

            // Log the data
            log_data(moisture_level, pump_state);

            // Print the log buffer
            print_log_buffer();
        }

        // Wait for the next sample interval
        time_sleep(SAMPLE_INTERVAL);
    }

    return 0;
}

