    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// MAX30102 initialization function
int init_max30102() {
    // Check Part ID
    int part_id = i2cReadByteData(i2c_handle, MAX30102_PART_ID);
