#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define RELAY_PIN 17
#define DOOR_SENSOR_PIN 27
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_MS 50
#define SAMPLING_DELAY_MS 200
#define RELAY_PULSE_DURATION_S 3
#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;
static int baseline_threshold = 0; // Calibrated baseline threshold

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_word(int fd, uint8_t reg, uint16_t value);
int calibrate_sensor(int fd);
int read_distance(int fd);
void control_relay(int gpio_pin, int state);
int read_reed_sensor(int gpio_pin);
void log_event(const char *message);
void signal_handler(int sig);

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[3];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// I2C write function
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Calibrate the sensor by taking multiple baseline readings
int calibrate_sensor(int fd) {
    int sum = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int reading = i2c_read_word(fd, CONVERSION_REG);
        if (reading < 0) {
            log_event("Error reading sensor during calibration");
            return -1; // Indicate calibration failure
        }
        sum += reading;
        delay(CALIBRATION_DELAY_MS);
    }
    baseline_threshold = sum / CALIBRATION_SAMPLES;
    printf("Calibration complete. Baseline threshold: %d\n", baseline_threshold);
    return 0; // Indicate calibration success
}

// Read the distance from the sensor
int read_distance(int fd) {
    int reading = i2c_read_word(fd, CONVERSION_REG);
    if (reading < 0) {
        log_event("Error reading sensor");
        return -1; // Indicate read failure
    }
    return reading;
}

// Control the relay (active-high)
void control_relay(int gpio_pin, int state) {
    digitalWrite(gpio_pin, state);
    printf("Relay set to %d\n", state);
}

// Read the reed switch sensor
int read_reed_sensor(int gpio_pin) {
    return digitalRead(gpio_pin);
}

// Log an event to the log file
void log_event(const char *message) {
    if (log_file == NULL) return; // Check if log file is open

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    fprintf(log_file, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received (%d). Terminating...\n", sig);
    terminate = 1;
    control_relay(RELAY_PIN, LOW); // De-energize the relay
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Configure the relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    control_relay(RELAY_PIN, LOW); // Ensure relay is initially de-energized

    // Configure the reed switch pin as input with pull-up
    pinMode(DOOR_SENSOR_PIN, INPUT);
    pullUpDnControl(DOOR_SENSOR_PIN, PUD_UP);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Calibrate the sensor
    if (calibrate_sensor(i2c_fd) != 0) {
        log_event("Sensor calibration failed. Exiting.");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_fd);
        if (distance < 0) {
            log_event("Failed to read distance. Retrying...");
            delay(SAMPLING_DELAY_MS); // Wait before retrying
            continue;
        }

        printf("Distance: %d\n", distance);

        if (distance < baseline_threshold) {
            log_event("Distance below threshold. Activating relay.");
            control_relay(RELAY_PIN, HIGH); // Energize the relay
            delay(RELAY_PULSE_DURATION_S * 1000); // Wait for the pulse duration
            control_relay(RELAY_PIN, LOW);  // De-energize the relay

            // Check the reed switch
            int reed_state = read_reed_sensor(DOOR_SENSOR_PIN);
            if (reed_state == LOW) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }

        delay(SAMPLING_DELAY_MS);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_relay(RELAY_PIN, LOW);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

