#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>

// Define GPIO pins for chip select
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_open(const char *device);
int spi_configure(int fd, uint8_t mode, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_mcp3008(int cs_pin);
void log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int sig);
void cleanup();

// Function to open the SPI device
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }
    return fd;
}

// Function to configure the SPI device
int spi_configure(int fd, uint8_t mode, uint32_t speed) {
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        return -1;
    }

    return 0;
}

// Function to perform SPI transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int cs_pin) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    int adc_value = -1;

    // Build SPI message (MCP3008 single-ended read)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0 (0b10000000)
    tx_buf[2] = 0x00; // Don't care

    digitalWrite(cs_pin, LOW); // Assert chip select
    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) == 0) {
        // Extract ADC value (10 bits)
        adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    } else {
        fprintf(stderr, "SPI transfer failed for CS pin %d\n", cs_pin);
        adc_value = -1; // Indicate error
    }
    digitalWrite(cs_pin, HIGH); // De-assert chip select

    return adc_value;
}

// Function to log data to CSV file
void log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
    fflush(fp); // Ensure data is written to file immediately
}

