#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 0.30
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define MAX_RETRIES 3

// Global variables
static int spi_handle;
static double threshold = DEFAULT_THRESHOLD;
static int pump_duration = DEFAULT_PUMP_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;
static volatile int running = 1;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value = -1;
    int retries = 0;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            log_event("SPI communication error. Retrying...");
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    log_event("Failed to read from MCP3008 after multiple retries.");
    return -1; // Indicate error
}

// Function to calculate moisture level as a percentage
double calculate_moisture_level(int adc_value) {
    return (adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    if (state == 1) {
        log_event("Pump activated.");
    } else {
        log_event("Pump deactivated.");
    }
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("irrigation.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
}

// Cleanup function to release resources
void cleanup() {
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();
    log_event("Program terminated.");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 'd':
                pump_duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0); // Ensure pump is initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started.");

    // Main loop
    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value != -1) {
            double moisture_level = calculate_moisture_level(adc_value);
            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Moisture level: %.2f%% (ADC: %d)", moisture_level, adc_value);
            log_event(log_message);

            if (moisture_level < threshold * 100.0) {
                control_pump(1); // Activate pump
                gpioDelay(pump_duration * 1000); // Wait for pump duration
                control_pump(0); // Deactivate pump
            }
        } else {
            log_event("Failed to read moisture level. Skipping pump cycle.");
        }

        gpioDelay(sleep_interval * 1000); // Sleep for the specified interval
    }

    cleanup();
    return 0;
}

