#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define THRESHOLD 500
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
int detect_peak(int adc_value, int threshold);
void log_event(int adc_value);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int adc_channel;
    int threshold;
    char *log_file;
} Config;

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to detect peaks
int detect_peak(int adc_value, int threshold) {
    return (adc_value > threshold) ? 1 : 0;
}

// Function to log events
void log_event(int adc_value) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d\n", buf, adc_value);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed\n");
            break; // Exit loop on ADC read error
        }

        if (detect_peak(adc_value, THRESHOLD)) {
            log_event(adc_value);
        }

        gpioDelay(10); // 10 ms delay
    }

    cleanup();
    return 0;
}

