#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_PIN 27
#define THRESHOLD 500.0 // Gauss
#define SAMPLE_RATE 1.0 // Hz
#define BUFFER_SIZE 10
#define VOLTAGE_RANGE 3.3 // Volts
#define ADC_RESOLUTION 2048.0 // 2^11 for 11-bit ADC

// Global variables
int i2c_handle;
bool running = true;
double magnetic_field_buffer[BUFFER_SIZE];
int buffer_index = 0;
bool threshold_exceeded = false;

// Function prototypes
int init_i2c();
int read_adc(int i2c_handle);
double voltage_to_gauss(double voltage);
double calculate_rolling_average(double new_value);
void check_threshold(double average_gauss);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C device");
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V range, continuous conversion
    uint16_t config = 0x4003; // Single-ended AIN0, 4.096V, Continuous, 128 SPS
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        log_message(LOG_ERR, "Failed to write to ADS1115 configuration register");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read ADC value from ADS1115
int read_adc(int i2c_handle) {
    char buf[1];
    buf[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        log_message(LOG_ERR, "Failed to write to ADS1115 conversion register");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        log_message(LOG_ERR, "Failed to read from ADS1115 conversion register");
        return -1;
    }

    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];
    return adc_value;
}

// Function to convert voltage to Gauss
double voltage_to_gauss(double voltage) {
    // SS49E sensitivity: 2.5 mV/Gauss
    // Assuming a linear relationship and a zero-field output of V/2
    double gauss = (voltage - (VOLTAGE_RANGE / 2.0)) / 0.0025;
    return gauss;
}

// Function to calculate rolling average
double calculate_rolling_average(double new_value) {
    magnetic_field_buffer[buffer_index] = new_value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += magnetic_field_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to check if threshold is exceeded
void check_threshold(double average_gauss) {
    if (average_gauss > THRESHOLD && !threshold_exceeded) {
        log_message(LOG_WARNING, "Threshold exceeded!");
        gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
        threshold_exceeded = true;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    char log_message_buffer[256];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "%s: %s", timestamp, message);
    syslog(priority, "%s", log_message_buffer);
}

int main() {
    // Initialize syslog
    openlog("magnetic_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_adc(i2c_handle);
        if (adc_value < 0) {
            log_message(LOG_ERR, "Failed to read ADC value, skipping sample");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to voltage
        double voltage = (adc_value / ADC_RESOLUTION) * VOLTAGE_RANGE;

        // Convert voltage to Gauss
        double gauss = voltage_to_gauss(voltage);

        // Calculate rolling average
        double average_gauss = calculate_rolling_average(gauss);

        // Check threshold
        check_threshold(average_gauss);

        // Log data
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "ADC Value: %d, Voltage: %.3f V, Gauss: %.3f G, Average Gauss: %.3f G", adc_value, voltage, gauss, average_gauss);
        log_message(LOG_INFO, log_message_buffer);

        // Wait for the next sample
        sleep(1); // Sample at 1 Hz
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    gpioTerminate();
    closelog();

    return 0;
}

