    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to validate ADC value
int validate_adc_value(int adc_value) {
    if (adc_value < MIN_ADC_VALUE || adc_value > MAX_ADC_VALUE) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1;
    }
    return 0;
}

// Function to control the water pump
int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", PUMP_GPIO);
        return -1;
    }
    return 0;
}

// Function to log watering event
int log_event(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Moisture level: %d\n", timestamp, adc_value);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Shutting down...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("watering_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stdout, "Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Validate ADC value
        if (validate_adc_value(adc_value) != 0) {
            fprintf(stderr, "Error: Invalid ADC value received\n");
            continue; // Skip to the next iteration
        }

        // Check moisture level and activate pump if needed
        if (adc_value < MOISTURE_THRESHOLD) {
            fprintf(stdout, "Moisture level below threshold. Activating pump.\n");
            if (control_pump(1) == 0) { // Turn pump ON
                log_event(adc_value);
                gpioDelay(PUMP_DURATION * 1000000); // Wait for pump duration (microseconds)
                if (control_pump(0) == 0) { // Turn pump OFF
                    fprintf(stdout, "Pump deactivated.\n");
                } else {
                    fprintf(stderr, "Error: Failed to deactivate pump\n");
                }
            } else {
                fprintf(stderr, "Error: Failed to activate pump\n");
            }
        }

        gpioDelay(READ_INTERVAL * 1000000); // Wait for the next reading (microseconds)
    }

    // Cleanup
    fprintf(stdout, "Cleaning up...\n");
    control_pump(0); // Ensure pump is OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stdout, "Soil moisture monitoring stopped.\n");
    return 0;
}

