#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define GAUSS_PER_VOLT 100.0 // Example calibration value, adjust as needed
#define BLINK_DURATION 1000 // milliseconds
#define BLINK_PERIOD 100 // milliseconds

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int16_t *raw_value);
double convert_to_gauss(int16_t raw_value);
void control_led(int on);
void blink_led();
void signal_handler(int signal);
void cleanup();

// Structure for ADS1115 configuration
typedef struct {
    uint16_t config;
} ads1115_config_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the ADS1115 register
int read_ads1115(int16_t *raw_value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ADS1115: %s\n", strerror(errno));
        return -1;
    }

    *raw_value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to convert the raw ADC value to Gauss
double convert_to_gauss(int16_t raw_value) {
    // Assuming PGA gain of 4.096V and +/- 4.096V range
    double voltage = (double)raw_value * 4.096 / 32768.0; // 32768 is 2^15
    return voltage * GAUSS_PER_VOLT;
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Function to blink the LED
void blink_led() {
    for (int i = 0; i < BLINK_DURATION / BLINK_PERIOD; i++) {
        control_led(1);
        gpioDelay(BLINK_PERIOD / 2);
        control_led(0);
        gpioDelay(BLINK_PERIOD / 2);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    control_led(0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure ADS1115 for single-ended AIN0, PGA gain 4.096V, continuous conversion
    ads1115_config_t config;
    config.config = 0x4083; // Single-ended AIN0, 4.096V, Continuous conversion, 128 SPS
    char config_buf[3];
    config_buf[0] = CONFIG_REG;
    config_buf[1] = (config.config >> 8) & 0xFF;
    config_buf[2] = config.config & 0xFF;

    if (i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, config_buf + 1, 2) != 2) {
        fprintf(stderr, "Error writing config to ADS1115: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    int16_t raw_value;
    double gauss_value;
    while (!terminate) {
        if (read_ads1115(&raw_value) == 0) {
            gauss_value = convert_to_gauss(raw_value);
            printf("Magnetic Field: %.2f Gauss\n", gauss_value);

            if (gauss_value > threshold) {
                blink_led();
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

