#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <mosquitto.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define MQTT_USERNAME "your_username" // Replace with your MQTT username
#define MQTT_PASSWORD "your_password" // Replace with your MQTT password
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static int pump_state = 0; // 0 = off, 1 = on

// Function prototypes
int read_mcp3008(int channel);
float adc_to_moisture(int adc_value);
void publish_moisture(float moisture);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int sig);
int mqtt_connect_and_subscribe(void);
void mqtt_disconnect(void);
void cleanup(void);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        syslog(LOG_ERR, "SPI data transfer failed: %s", strerror(errno));
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to convert ADC value to moisture percentage
float adc_to_moisture(int adc_value) {
    // Assuming a linear relationship between ADC value and moisture
    // You may need to calibrate this based on your sensor
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture;
}

// Function to publish moisture value to MQTT
void publish_moisture(float moisture) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL_MOISTURE, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(ret));
    }
}

// MQTT message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        if (strcmp(message->topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
            if (strcmp((char *)message->payload, "pump_on") == 0) {
                if (pump_state == 0) {
                    digitalWrite(PUMP_GPIO, HIGH);
                    pump_state = 1;
                    syslog(LOG_INFO, "Pump turned ON via MQTT");
                }
            } else if (strcmp((char *)message->payload, "pump_off") == 0) {
                if (pump_state == 1) {
                    digitalWrite(PUMP_GPIO, LOW);
                    pump_state = 0;
                    syslog(LOG_INFO, "Pump turned OFF via MQTT");
                }
            } else {
                syslog(LOG_WARNING, "Invalid MQTT message: %s", (char *)message->payload);
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Function to connect to MQTT broker and subscribe to topics
int mqtt_connect_and_subscribe(void) {
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_strerror(ret));
        return -1;
    }

    ret = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP_CONTROL, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT subscription failed: %s", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Function to disconnect from MQTT broker
void mqtt_disconnect(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
}

// Cleanup function to release resources
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up resources...");
    digitalWrite(PUMP_GPIO, LOW); // Ensure pump is off
    mqtt_disconnect();
    closelog();
}

int main(void) {
    openlog("soil_moisture_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting soil moisture sensor program...");

    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        syslog(LOG_ERR, "WiringPi initialization failed: %s", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        syslog(LOG_ERR, "SPI initialization failed: %s", strerror(errno));
        return 1;
    }

    // Set pump GPIO as output
    pinMode(PUMP_GPIO, OUTPUT);
    digitalWrite(PUMP_GPIO, LOW); // Ensure pump is initially off

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT initialization failed");
        return 1;
    }

    mosquitto_username_pw_set(mosq, MQTT_USERNAME, MQTT_PASSWORD);
    mosquitto_message_callback_set(mosq, message_callback);

    if (mqtt_connect_and_subscribe() != 0) {
        cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int adc_value;
    float moisture;
    int last_adc_value = -1; // Initialize to an invalid value

    while (running) {
        adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            syslog(LOG_ERR, "Failed to read ADC value, retrying...");
            sleep(1); // Wait before retrying
            continue;
        }

        // Hysteresis control
        moisture = adc_to_moisture(adc_value);

        if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
            digitalWrite(PUMP_GPIO, HIGH);
            pump_state = 1;
            syslog(LOG_INFO, "Moisture below threshold, turning pump ON (hysteresis)");
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
            digitalWrite(PUMP_GPIO, LOW);
            pump_state = 0;
            syslog(LOG_INFO, "Moisture above threshold, turning pump OFF (hysteresis)");
        }

        // Publish moisture value every 60 seconds
        time_t now = time(NULL);
        if (now % 60 == 0) {
            publish_moisture(moisture);
        }

        // Sensor Absent Condition Check
        if (adc_value == last_adc_value && last_adc_value != -1) {
            syslog(LOG_WARNING, "Sensor absent or malfunctioning (same ADC value for 60 seconds)");
        }
        last_adc_value = adc_value;

        sleep(1); // Check every second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

