// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define PWM_FREQUENCY 100 // Hz
#define PWM_GPIO_1 17
#define PWM_GPIO_2 27
#define NOISE_THRESHOLD 500
#define SAMPLE_INTERVAL_MS 10

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
void set_motor_speed(int gpio, int speed);
void log_event(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int adc_channel;
    int pwm_frequency;
    int pwm_gpio_1;
    int pwm_gpio_2;
    int noise_threshold;
    int sample_interval_ms;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    ADC_CHANNEL,
    PWM_FREQUENCY,
    PWM_GPIO_1,
    PWM_GPIO_2,
    NOISE_THRESHOLD,
    SAMPLE_INTERVAL_MS
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_adc(config.adc_channel);
        if (adc_value < 0) {
            log_event("Error reading ADC value. Skipping iteration.");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        if (adc_value > config.noise_threshold) {
            set_motor_speed(config.pwm_gpio_1, 100); // 100% duty cycle
            set_motor_speed(config.pwm_gpio_2, 100); // 100% duty cycle
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Vibration event detected. ADC value: %d", adc_value);
            log_event(log_message);
        } else {
            set_motor_speed(config.pwm_gpio_1, 0); // Turn off motor
            set_motor_speed(config.pwm_gpio_2, 0); // Turn off motor
        }

        gpioDelay(config.sample_interval_ms * 1000); // Convert ms to us
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        log_event("SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency and GPIO modes
    gpioSetPWMfrequency(config.pwm_gpio_1, config.pwm_frequency);
    gpioSetPWMfrequency(config.pwm_gpio_2, config.pwm_frequency);
    gpioSetMode(config.pwm_gpio_1, PI_OUTPUT);
    gpioSetMode(config.pwm_gpio_2, PI_OUTPUT);

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

void cleanup() {
    // Stop motors
    set_motor_speed(config.pwm_gpio_1, 0);
    set_motor_speed(config.pwm_gpio_2, 0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        log_event("SPI transfer failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

void set_motor_speed(int gpio, int speed) {
    if (speed < 0 || speed > 100) {
        fprintf(stderr, "Invalid PWM duty cycle: %d\n", speed);
        return;
    }
    gpioPWM(gpio, speed);
}

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

