volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_co2(float voltage);
void control_fan(int co2_ppm);
void log_data(time_t timestamp, float co2_ppm, int fan_state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value / 1023.0 * 3.3;
}

// Function to estimate CO2 concentration from voltage
float voltage_to_co2(float voltage) {
    // Linear approximation: CO2 = m * voltage + c
    // Assuming a linear relationship between voltage and CO2 concentration
    // You may need to calibrate these values based on your sensor's datasheet
    float m = (CO2_MAX - CO2_MIN) / (3.3 - 0.0); // Assuming 0V is 0ppm and 3.3V is 2000ppm
    float c = CO2_MIN;
    return m * voltage + c;
}

// Function to control the ventilation fan
void control_fan(int co2_ppm) {
    if (co2_ppm > CO2_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Function to log data to file
void log_data(time_t timestamp, float co2_ppm, int fan_state) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp_str, co2_ppm, fan_state);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Log the error to the file
            time_t now = time(NULL);
            fprintf(log_file, "%ld,ERROR,Failed to read ADC value\n", now);
            fflush(log_file);
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue; // Skip to the next iteration
        }

        // Validate ADC value
        if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
            fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
            // Log the error to the file
            time_t now = time(NULL);
            fprintf(log_file, "%ld,ERROR,Invalid ADC value: %d\n", now, adc_value);
            fflush(log_file);
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Estimate CO2 concentration
        float co2_ppm = voltage_to_co2(voltage);

        // Control the fan
        control_fan((int)co2_ppm);
        int fan_state = gpioRead(FAN_GPIO);

        // Get current timestamp
        time_t now = time(NULL);

        // Log the data
        log_data(now, co2_ppm, fan_state);

        printf("CO2: %.2f ppm, Fan: %s\n", co2_ppm, fan_state ? "ON" : "OFF");

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

