#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define VALVE_GPIO 17
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define LOG_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_average(int sample1, int sample2, int sample3);
int map_adc_to_pwm(float average);
void log_data(int sample1, int sample2, int sample3, float average, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate the average of three samples
float calculate_average(int sample1, int sample2, int sample3) {
    float sum = 0.0;
    int count = 0;

    if (sample1 >= 0) {
        sum += sample1;
        count++;
    }
    if (sample2 >= 0) {
        sum += sample2;
        count++;
    }
    if (sample3 >= 0) {
        sum += sample3;
        count++;
    }

    if (count == 0) {
        return -1.0; // Indicate failure
    }

    return sum / count;
}

// Function to map ADC value to PWM duty cycle
int map_adc_to_pwm(float average) {
    // Linear mapping: 0 ADC -> 100 PWM, 1023 ADC -> 0 PWM
    // This is the opposite of the valve's behavior, so we need to invert it
    int pwm_value = (int)((average / 1023.0) * 100.0);
    return 100 - pwm_value; // Invert the PWM value
}

// Function to log data to file
void log_data(int sample1, int sample2, int sample3, float average, int valve_position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %d, %d, %.2f, %d\n", timestamp, sample1, sample2, sample3, average, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set valve GPIO as output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int sample1 = read_mcp3008(0);
        int sample2 = read_mcp3008(0);
        int sample3 = read_mcp3008(0);

        float average = calculate_average(sample1, sample2, sample3);

        if (average >= 0) {
            int valve_position = map_adc_to_pwm(average);
            gpioPWM(VALVE_GPIO, valve_position);
            log_data(sample1, sample2, sample3, average, valve_position);
        } else {
            fprintf(stderr, "Error: Failed to read ADC values\n");
        }

        sleep(LOG_INTERVAL);
    }

    // Graceful shutdown
    gpioPWM(VALVE_GPIO, 0); // Set valve to 0%
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

