#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define SAMPLE_INTERVAL 5 // seconds
#define MAX_RETRIES 5

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_moisture(int adc_value);
void log_data(float moisture);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int mcp3008_channel;
    char *log_file;
    int sample_interval;
} config_t;

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            // Extract ADC value (10 bits)
            result = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return result;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(1000 * (1 << retries)); // Exponential backoff (1ms, 2ms, 4ms, 8ms, 16ms)
        }
    }

    fprintf(stderr, "Failed to read MCP3008 after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to convert ADC value to moisture percentage
float adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate error
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to a file
void log_data(float moisture) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float moisture = adc_to_moisture(adc_value);
            if (moisture >= 0.0) {
                log_data(moisture);
                printf("Moisture: %.2f%%\n", moisture);
            } else {
                fprintf(stderr, "Error converting ADC value to moisture\n");
            }
        } else {
            // Log error to file
            FILE *fp = fopen(LOG_FILE, "a");
            if (fp != NULL) {
                time_t t = time(NULL);
                struct tm *tm = localtime(&t);
                char timestamp[64];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
                fprintf(fp, "%s, ERROR: Failed to read ADC value\n", timestamp);
                fclose(fp);
            }
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

