#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM parameters
#define PWM_FREQUENCY 440 // Initial frequency
#define PWM_RANGE 1000

// Define Theremin mapping ranges
#define DISTANCE_MIN 2.0  // cm
#define DISTANCE_MAX 20.0 // cm
#define FREQUENCY_MIN 220.0
#define FREQUENCY_MAX 880.0

#define LDR_MIN 0   // ADC value
#define LDR_MAX 1023 // ADC value
#define VOLUME_MIN 0.0
#define VOLUME_MAX 1.0

// Define timeout values
#define ECHO_TIMEOUT 50000 // microseconds

// Global variables
static volatile int echo_start = 0;
static volatile int echo_end = 0;
static volatile int echo_valid = 0;

static int spi_handle;
static int pwm_handle;

static double last_distance = 10.0; // Default distance
static double last_volume = 0.5;    // Default volume

static double distance_calibration = 0.0;
static double ldr_calibration = 0.0;

static FILE *log_file = NULL;

// Function prototypes
void trigger_sensor();
double measure_distance();
int read_ldr();
void set_pwm_frequency(double frequency);
void set_pwm_duty_cycle(double volume);
void signal_handler(int signal);
void echo_callback(int gpio, int level, uint32_t tick);
void load_calibration();
void save_calibration();
void log_message(const char *message);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (gpio == ECHO_PIN)
    {
        if (level == 1) // Rising edge
        {
            echo_start = tick;
            echo_valid = 0; // Reset validity flag
        }
        else if (level == 0) // Falling edge
        {
            echo_end = tick;
            if (echo_start != 0) // Ensure start time is valid
            {
                echo_valid = 1; // Set validity flag
            }
        }
    }
}

// Function to trigger the ultrasonic sensor
void trigger_sensor()
{
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
double measure_distance()
{
    echo_start = 0;
    echo_end = 0;
    echo_valid = 0;

    trigger_sensor();

    // Wait for echo or timeout
    int timeout_count = 0;
    while (!echo_valid && timeout_count < ECHO_TIMEOUT)
    {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
    }

    if (!echo_valid)
    {
        log_message("Error: Ultrasonic sensor timeout");
        return last_distance; // Return last valid distance
    }

    // Calculate pulse width in microseconds
    int pulse_width = echo_end - echo_start;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    double distance = (double)pulse_width / 1000000.0 * 34300.0 / 2.0;

    // Apply calibration
    distance += distance_calibration;

    return distance;
}

// Function to read the LDR value from the MCP3008 ADC
int read_ldr()
{
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // MCP3008 command to read channel 0 (single-ended)
    spi_tx_buf[0] = 0x01;                  // Start bit
    spi_tx_buf[1] = 0x80;                  // Single-ended, channel 0
    spi_tx_buf[2] = 0x00;                  // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0)
    {
        log_message("Error: SPI communication failed");
        return -1; // Indicate error
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    // Apply calibration
    adc_value += (int)ldr_calibration;

    // Clamp the value to the valid range
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    return adc_value;
}

// Function to set the PWM frequency
void set_pwm_frequency(double frequency)
{
    if (frequency < 20.0) frequency = 20.0; // Limit frequency
    if (frequency > 20000.0) frequency = 20000.0;

    int period = 1000000 / (int)frequency; // Period in microseconds
    gpioSetPWMfrequency(PWM_PIN, (int)frequency);
}

// Function to set the PWM duty cycle (volume)
void set_pwm_duty_cycle(double volume)
{
    if (volume < 0.0) volume = 0.0;
    if (volume > 1.0) volume = 1.0;

    int duty_cycle = (int)(volume * PWM_RANGE);
    gpioPWM(PWM_PIN, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    log_message("Received signal, shutting down...");

    // Stop PWM
    gpioPWM(PWM_PIN, 0);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    exit(0);
}

// Function to load calibration parameters from file
void load_calibration()
{
    FILE *fp = fopen("theremin_config.txt", "r");
    if (fp != NULL)
    {
        if (fscanf(fp, "%lf %lf", &distance_calibration, &ldr_calibration) == 2)
        {
            printf("Calibration parameters loaded: distance=%.2f, ldr=%.2f\n", distance_calibration, ldr_calibration);
        }
        else
        {
            printf("Error: Could not read calibration parameters from file\n");
        }
        fclose(fp);
    }
    else
    {
        printf("Calibration file not found, using default values\n");
    }
}

// Function to save calibration parameters to file
void save_calibration()
{
    FILE *fp = fopen("theremin_config.txt", "w");
    if (fp != NULL)
    {
        fprintf(fp, "%lf %lf", distance_calibration, ldr_calibration);
        fclose(fp);
        printf("Calibration parameters saved\n");
    }
    else
    {
        printf("Error: Could not save calibration parameters to file\n");
    }
}

// Function to log messages with timestamps
void log_message(const char *message)
{
    if (log_file != NULL)
    {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file); // Ensure immediate write
    }
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        printf("pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("theremin.log", "a");
    if (log_file == NULL)
    {
        printf("Error: Could not open log file\n");
    }

    // Load calibration parameters
    load_calibration();

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0)
    {
        log_message("Error: SPI initialisation failed");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up callback for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Theremin instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1)
    {
        // Measure distance
        double distance = measure_distance();

        // Read LDR value
        int ldr_value = read_ldr();

        // Map distance to frequency
        double frequency = FREQUENCY_MIN + (distance - DISTANCE_MIN) * (FREQUENCY_MAX - FREQUENCY_MIN) / (DISTANCE_MAX - DISTANCE_MIN);
        if (frequency < FREQUENCY_MIN) frequency = FREQUENCY_MIN;
        if (frequency > FREQUENCY_MAX) frequency = FREQUENCY_MAX;

        // Map LDR value to volume
        double volume = VOLUME_MIN + (ldr_value - LDR_MIN) * (VOLUME_MAX - VOLUME_MIN) / (LDR_MAX - LDR_MIN);
        if (volume < VOLUME_MIN) volume = VOLUME_MIN;
        if (volume > VOLUME_MAX) volume = VOLUME_MAX;

        // Set PWM frequency and duty cycle
        set_pwm_frequency(frequency);
        set_pwm_duty_cycle(volume);

        // Update last valid values
        last_distance = distance;
        last_volume = volume;

        // Small delay
        gpioDelay(50); // 50 ms
    }

    return 0;
}

