#define ADC_CHANNEL 0
#define LOG_FILE "alcohol_log.txt"
#define NUM_RETRIES 3
#define RETRY_DELAY_MS 100
#define SENSOR_ABSENT_THRESHOLD 10

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void log_data(float ppm_value);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    for (int i = 0; i < NUM_RETRIES; ++i) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 3) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d/%d), result = %d\n", i + 1, NUM_RETRIES, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries\n", NUM_RETRIES);
    return -1; // Indicate failure
}

// Function to convert ADC value to PPM (example calibration)
float adc_to_ppm(int adc_value) {
    // This is a placeholder.  Replace with your actual calibration curve.
    // Example: Linear relationship
    return (float)adc_value * 0.1; // Adjust the scaling factor as needed
}

// Function to log data to file
void log_data(float ppm_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f ppm\n", timestamp, ppm_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

