    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor_absent_count = 0;

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Log the error to the file
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
            fprintf(log_file, "%s, ERROR: Failed to read ADC value\n", timestamp);
            fflush(log_file);
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        float ppm_value = adc_to_ppm(adc_value);

        // Sensor absent detection
        if (adc_value == 0 || adc_value == 1023) {
            sensor_absent_count++;
            if (sensor_absent_count >= SENSOR_ABSENT_THRESHOLD) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[30];

                time(&rawtime);
                timeinfo = gmtime(&rawtime);

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
                fprintf(log_file, "%s, ERROR: Sensor absent or disconnected\n", timestamp);
                fflush(log_file);
                sensor_absent_count = SENSOR_ABSENT_THRESHOLD; // Prevent repeated logging
            }
        } else {
            sensor_absent_count = 0; // Reset counter if sensor is present
        }

        // Log data
        log_data(ppm_value);

        // Print classification to console
        if (ppm_value > 50.0) {
            printf("Alcohol detected! Limit exceeded. PPM: %.2f\n", ppm_value);
        } else if (ppm_value < 20.0) {
            printf("Sobriety confirmed. PPM: %.2f\n", ppm_value);
        } else {
            printf("Alcohol level within acceptable range. PPM: %.2f\n", ppm_value);
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

