#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define PWM parameters
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000

// Define motor control parameters
#define ACCELERATION_RATE 50 // PWM increment/decrement per loop
#define DECELERATION_RATE 50 // PWM increment/decrement per loop
#define CONSTANT_SPEED_DURATION 2 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void set_motor_speed(int motor, int speed);
void set_motor_direction(int motor, int direction);
void accelerate_motor(int motor, int target_speed);
void decelerate_motor(int motor);
void reverse_motor_directions();
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        gpioPWM(MOTOR1_ENABLE, speed);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_ENABLE, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
    }
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    if (motor == 1) {
        gpioWrite(MOTOR1_DIRECTION, direction);
    } else if (motor == 2) {
        gpioWrite(MOTOR2_DIRECTION, direction);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
    }
}

// Function to accelerate motor to target speed
void accelerate_motor(int motor, int target_speed) {
    int current_speed = 0;
    while (current_speed < target_speed) {
        current_speed += ACCELERATION_RATE;
        if (current_speed > target_speed) {
            current_speed = target_speed;
        }
        set_motor_speed(motor, current_speed);
        gpioDelay(10000); // 10 ms delay
    }
}

// Function to decelerate motor to zero speed
void decelerate_motor(int motor) {
    int current_speed = gpioGetPWMdutycycle(motor == 1 ? MOTOR1_ENABLE : MOTOR2_ENABLE);
    while (current_speed > 0) {
        current_speed -= DECELERATION_RATE;
        if (current_speed < 0) {
            current_speed = 0;
        }
        set_motor_speed(motor, current_speed);
        gpioDelay(10000); // 10 ms delay
    }
}

// Function to reverse motor directions
void reverse_motor_directions() {
    set_motor_direction(1, !gpioRead(MOTOR1_DIRECTION));
    set_motor_direction(2, !gpioRead(MOTOR2_DIRECTION));
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(MOTOR1_ENABLE, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMfrequency(MOTOR2_ENABLE, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Set initial motor directions (forward)
    set_motor_direction(1, 1);
    set_motor_direction(2, 1);

    return 0;
}

// Cleanup function
void cleanup() {
    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(0);
        int pot2_value = read_mcp3008(1);

        if (pot1_value == -1 || pot2_value == -1) {
            fprintf(stderr, "Error reading potentiometer values, retrying...\n");
            gpioDelay(100000); // 100 ms delay
            continue;
        }

        // Map potentiometer values to motor speeds (0-1000)
        int motor1_speed = pot1_value;
        int motor2_speed = pot2_value;

        // Accelerate motors
        accelerate_motor(1, motor1_speed);
        accelerate_motor(2, motor2_speed);

        // Hold constant speed for 2 seconds
        gpioDelay(CONSTANT_SPEED_DURATION * 1000000); // 2 seconds

        // Decelerate motors
        decelerate_motor(1);
        decelerate_motor(2);

        // Pause for 5 seconds
        gpioDelay(5000000); // 5 seconds

        // Reverse motor directions
        reverse_motor_directions();

        // Accelerate motors
        accelerate_motor(1, motor1_speed);
        accelerate_motor(2, motor2_speed);

        // Hold constant speed for 2 seconds
        gpioDelay(CONSTANT_SPEED_DURATION * 1000000); // 2 seconds

        // Decelerate motors
        decelerate_motor(1);
        decelerate_motor(2);

        // Pause for 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    cleanup();

    return 0;
}

