        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calibrate the baseline noise level
void calibrate_baseline(void) {
    printf("Calibrating baseline noise level for %d seconds...\n", CALIBRATION_DURATION);
    int sum = 0;
    int samples = 0;
    time_t start_time = time(NULL);

    while (time(NULL) - start_time < CALIBRATION_DURATION) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            sum += adc_value;
            samples++;
        } else {
            fprintf(stderr, "Error: Failed to read ADC value during calibration\n");
        }
        gpioDelay(10); // Small delay to avoid overwhelming the ADC
    }

    if (samples > 0) {
        baseline = sum / samples;
        printf("Baseline noise level: %d\n", baseline);
    } else {
