        gpioDelay(10); // Small delay to avoid overwhelming the CPU
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);   // Close SPI
    gpioTerminate();       // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

