#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define ADC_CHANNEL 0
#define LOG_FILE "airflow_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float voltage_to_airflow(int adc_value);
void log_data(float airflow);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for calibration data (example)
typedef struct {
    float voltage;
    float airflow;
} CalibrationPoint;

CalibrationPoint calibration_curve[] = {
    {0.5, 0.0},   // Example calibration points
    {1.5, 20.0},
    {2.5, 40.0},
    {3.5, 60.0},
    {4.5, 80.0}
};

int calibration_curve_size = sizeof(calibration_curve) / sizeof(calibration_curve[0]);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to airflow using linear interpolation
float voltage_to_airflow(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * 5.0; // Assuming 5V reference

    if (voltage <= calibration_curve[0].voltage) {
        return calibration_curve[0].airflow;
    }

    if (voltage >= calibration_curve[calibration_curve_size - 1].voltage) {
        return calibration_curve[calibration_curve_size - 1].airflow;
    }

    for (int i = 0; i < calibration_curve_size - 1; i++) {
        if (voltage >= calibration_curve[i].voltage && voltage <= calibration_curve[i + 1].voltage) {
            float v1 = calibration_curve[i].voltage;
            float v2 = calibration_curve[i + 1].voltage;
            float a1 = calibration_curve[i].airflow;
            float a2 = calibration_curve[i + 1].airflow;

            return a1 + (voltage - v1) * (a2 - a1) / (v2 - v1);
        }
    }

    return -1.0; // Should not reach here
}

// Function to log data to file
void log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s, ERROR: ADC read failed\n", timestamp);
            fflush(log_file);
        } else {
            float airflow = voltage_to_airflow(adc_value);
            if (airflow >= 0) {
                log_data(airflow);
            } else {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[20];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                fprintf(log_file, "%s, ERROR: Airflow calculation failed\n", timestamp);
                fflush(log_file);
            }
        }

        gpioDelay(100); // 100ms delay
    }

    cleanup();
    return 0;
}

