#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PIN 8 // CE0
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE)
#define LOG_FILE "audio_log.txt"
#define NUM_SAMPLES 1000 // Number of samples to acquire before exiting

// GPIO Memory Map
#define BCM2835_PERI_BASE        0x3F000000
#define GPIO_BASE                (BCM2835_PERI_BASE + 0x200000) /* GPIO controller */
#define PAGE_SIZE (4*1024)
#define BLOCK_SIZE (4*1024)

// SPI Configuration
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz

// Global Variables
static volatile uint32_t *gpio_map = NULL;
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int spi_open(const char *device);
int spi_close(int fd);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int spi_set_mode(int fd, uint8_t mode);
int spi_set_bits_per_word(int fd, uint8_t bits);
int spi_set_max_speed(int fd, uint32_t speed);
int read_adc(int channel);
void log_data(uint64_t timestamp_ns, int raw_adc_value);
void signal_handler(int sig);
int setup_gpio_memory();
void cleanup_gpio_memory();

// GPIO Memory Mapping Functions
int setup_gpio_memory() {
    int mem_fd;

    /* open /dev/mem */
    if ((mem_fd = open("/dev/mem", O_RDWR|O_SYNC) ) < 0) {
        perror("can't open /dev/mem");
        return -1;
    }

    /* mmap GPIO */
    gpio_map = (uint32_t *)mmap(
        NULL,             //Any adddress in our space will do
        BLOCK_SIZE,       //Map length
        PROT_READ|PROT_WRITE,// Enable reading & writting to mapped memory
        MAP_SHARED,       //Shared with other processes
        mem_fd,           //File to map
        GPIO_BASE         //Offset to GPIO peripheral
    );

    close(mem_fd); //No need to keep mem_fd open after mmap

    if (gpio_map == MAP_FAILED) {
        perror("mmap error");
        return -1;
    }

    return 0;
}

void cleanup_gpio_memory() {
    if (gpio_map != NULL) {
        if (munmap((void *)gpio_map, BLOCK_SIZE) == -1) {
            perror("munmap error");
        }
        gpio_map = NULL;
    }
}

// GPIO Functions
int gpio_export(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd == -1) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }

    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    write(fd, buffer, bytes_written);
    close(fd);
    return 0;
}

int gpio_unexport(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd == -1) {
        perror("Failed to open /sys/class/gpio/unexport");
        return -1;
    }

    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    write(fd, buffer, bytes_written);
    close(fd);
