            continue; // Continue even if timestamp fails
        }
        uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

        // Log data
        log_data(timestamp_ns, adc_value);

