#include <math.h>

// Define GPIO pins for SPI communication
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// Define ADXL335 sensitivity (300mV/g) and VCC (3.3V)
#define ADXL335_SENSITIVITY 0.300 // 300mV/g
#define VCC 3.3

// Define Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state variables
float x_state = 0.0, y_state = 0.0, z_state = 0.0;
float x_error_covariance = 1.0, y_error_covariance = 1.0, z_error_covariance = 1.0;

// Function prototypes
int initialize_spi();
int read_mcp3008_channel(int channel);
float convert_to_g(int adc_value);
void kalman_filter(float measurement, float *state, float *error_covariance);
void print_acceleration(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI communication
int initialize_spi() {
    // Configure SPI clock and mode
    if (spiOpen(0, 1000000, 0) < 0) { // SPI channel 0, 1MHz, mode 0
        fprintf(stderr, "Error: Could not open SPI channel.\n");
        return -1;
    }
    spi_handle = 0; // SPI channel 0
    return 0;
}

// Read data from MCP3008 channel
int read_mcp3008_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel.\n");
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed.\n");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to acceleration in g
float convert_to_g(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VCC;
    float acceleration = (voltage - (VCC / 2.0)) / ADXL335_SENSITIVITY;
    return acceleration;
}

// Kalman filter implementation
void kalman_filter(float measurement, float *state, float *error_covariance) {
    // Prediction step (no process model, so skip)
    // Update step
    float kalman_gain = *error_covariance / (*error_covariance + MEASUREMENT_NOISE);
    *state = *state + kalman_gain * (measurement - *state);
    *error_covariance = (1 - kalman_gain) * *error_covariance + PROCESS_NOISE;
}

// Print acceleration values
void print_acceleration(float x, float y, float z) {
    printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x, y, z);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI communication
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("ADXL335 Accelerometer Data Acquisition\n");

    // Main loop
    while (!terminate) {
        // Read ADC values from MCP3008 channels
        int x_adc = read_mcp3008_channel(0);
        int y_adc = read_mcp3008_channel(1);
        int z_adc = read_mcp3008_channel(2);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC values to acceleration in g
        float x_acceleration = convert_to_g(x_adc);
        float y_acceleration = convert_to_g(y_adc);
        float z_acceleration = convert_to_g(z_adc);

        // Apply Kalman filter
        kalman_filter(x_acceleration, &x_state, &x_error_covariance);
        kalman_filter(y_acceleration, &y_state, &y_error_covariance);
        kalman_filter(z_acceleration, &z_state, &z_error_covariance);

        // Print acceleration values
        print_acceleration(x_state, y_state, z_state);

        // Delay to achieve 10Hz sampling rate
        gpioDelay(100); // 100ms delay
    }

    // Close SPI connection
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

