#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define the magnetic field sensitivity of the DRV5055VA (mT/V)
#define SENSITIVITY 0.005

// Define the voltage levels
#define HIGH_VOLTAGE 3.3
#define LOW_VOLTAGE 0.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the digital state of a GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid GPIO value read from pin %d\n", gpio_pin);
        return -1; // Indicate an error
    }
    return value;
}

// Function to convert the digital state to a voltage
float digital_to_voltage(int digital_value) {
    return (digital_value == 1) ? HIGH_VOLTAGE : LOW_VOLTAGE;
}

// Function to convert the voltage to a magnetic field strength (mT)
float voltage_to_magnetic_field(float voltage) {
    return voltage * SENSITIVITY;
}

// Function to log the magnetic field values to a file
void log_magnetic_field(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen("magnetic_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open magnetic_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp); // Flush the buffer to ensure data is written to the file
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error: Failed to read sensor values, skipping logging\n");
            gpioDelay(100); // Wait 100 milliseconds
            continue;
        }

        // Convert digital values to voltages
        float sensor1_voltage = digital_to_voltage(sensor1_value);
        float sensor2_voltage = digital_to_voltage(sensor2_value);
        float sensor3_voltage = digital_to_voltage(sensor3_value);

        // Convert voltages to magnetic field strengths
        float sensor1_mT = voltage_to_magnetic_field(sensor1_voltage);
        float sensor2_mT = voltage_to_magnetic_field(sensor2_voltage);
        float sensor3_mT = voltage_to_magnetic_field(sensor3_voltage);

        // Check for out-of-range values
        if (sensor1_mT < -100.0 || sensor1_mT > 100.0) {
            fprintf(stderr, "Warning: Sensor 1 magnetic field out of range: %.2f mT\n", sensor1_mT);
        }
        if (sensor2_mT < -100.0 || sensor2_mT > 100.0) {
            fprintf(stderr, "Warning: Sensor 2 magnetic field out of range: %.2f mT\n", sensor2_mT);
        }
        if (sensor3_mT < -100.0 || sensor3_mT > 100.0) {
            fprintf(stderr, "Warning: Sensor 3 magnetic field out of range: %.2f mT\n", sensor3_mT);
        }

        // Log the magnetic field values
        log_magnetic_field(sensor1_mT, sensor2_mT, sensor3_mT);

        // Wait 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

