// Function to control the LED
void control_led(int led_state) {
    gpioWrite(GPIO_PIN, led_state);
}

// MQTT connect callback
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_error("MQTT connection error: " + result);
    }
}

// MQTT message callback
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        int led_state;
        if (parse_json_payload(message->payload, &led_state) == 0) {
            control_led(led_state);
        } else {
            log_error("Failed to parse JSON payload");
        }
    } else {
        log_error("Empty message received");
    }
}

// MQTT disconnect callback
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_error("Disconnected from MQTT broker with error code: " + rc);
    }
}

int main() {
    int rc = 0;
    int reconnect_delay = 1;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED on startup

    // Initialize libmosquitto
    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_message_callback_set(mosq, message_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to connect to MQTT broker, retrying in " + reconnect_delay + " seconds");
            sleep(reconnect_delay);
            reconnect_delay *= 2;
            if (reconnect_delay > 60) {
                reconnect_delay = 60;
            }
            continue;
        }

        rc = mosquitto_loop_forever(mosq, -1, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT loop error: " + rc);
            mosquitto_reconnect_delay_set(mosq, reconnect_delay, reconnect_delay, false);
            mosquitto_reconnect(mosq);
        }
    }

    // Clean up
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();

    printf("Exiting cleanly\n");
    return 0;
}

