#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_LED_PIN);
        gpioTerminate();
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sound sensor value
        int sound_level = gpioRead(SOUND_SENSOR_PIN);

        // Print sound level
        printf("Sound Level: %d\n", sound_level);

        // Check for sound event (LOW signal)
        if (sound_level == 0) {
            printf("Sound event detected! Triggering alarm.\n");

            // Activate alarm LED
            if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to set GPIO%d HIGH\n", ALARM_LED_PIN);
                program_running = 0; // Exit loop on error
                continue; // Skip the rest of the loop iteration
            }

            // Wait for 1 second
            gpioDelay(1000000); // 1 second = 1000000 microseconds

            // Deactivate alarm LED
            if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to set GPIO%d LOW\n", ALARM_LED_PIN);
                program_running = 0; // Exit loop on error
                continue; // Skip the rest of the loop iteration
            }
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Clean up GPIO resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

