#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIOCHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    static char buf[80];
    strftime(buf, sizeof(buf), TIMESTAMP_FORMAT, tstruct);
    return buf;
}

// Function to log a message to the log file
int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    char *timestamp = get_timestamp();
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Function to execute the shutdown command
int shutdown_system() {
    printf("Shutting down the system...\n");
    int ret = system("sudo shutdown -h now");
    if (ret == -1) {
        perror("Error executing shutdown command");
        return -1;
    }
    return 0;
}

// Function to release the GPIO line
int release_gpio(int fd, int line) {
    struct gpiohandle_request req;
    memset(&req, 0, sizeof(req));
    req.lineoffset = line;
    req.flags = GPIOHANDLE_REQUEST_INPUT;
    strncpy(req.consumer, "vibration-monitor", sizeof(req.consumer) - 1);

    if (ioctl(fd, GPIOHANDLE_RELEASE, &req) == -1) {
        perror("Error releasing GPIO line");
        return -1;
    }
    return 0;
}

// Function to close the GPIO chip
int close_gpio_chip(int fd) {
    if (close(fd) == -1) {
        perror("Error closing GPIO chip");
        return -1;
    }
    return 0;
}

int main() {
    int gpiochip_fd;
    struct gpiochip_info chip_info;
    struct gpiohandle_request req;
    struct gpiohandle_event event;
    char *timestamp;
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    gpiochip_fd = open("/dev/" GPIOCHIP, 0);
    if (gpiochip_fd == -1) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO chip information
    if (ioctl(gpiochip_fd, GPIO_GET_CHIPINFO, &chip_info) == -1) {
        perror("Error getting GPIO chip info");
        close_gpio_chip(gpiochip_fd);
        return 1;
    }

    // Request GPIO line
    memset(&req, 0, sizeof(req));
    req.lineoffset = GPIO_LINE;
    req.flags = GPIOHANDLE_REQUEST_INPUT;
    strncpy(req.consumer, "vibration-monitor", sizeof(req.consumer) - 1);

    if (ioctl(gpiochip_fd, GPIOHANDLE_REQUEST, &req) == -1) {
        perror("Error requesting GPIO line");
        close_gpio_chip(gpiochip_fd);
        return 1;
    }

    // Configure falling edge detection
    if (ioctl(gpiochip_fd, GPIOHANDLE_SET_LINE_FLAGS, &req) == -1) {
        perror("Error setting GPIO line flags");
        release_gpio(gpiochip_fd, GPIO_LINE);
        close_gpio_chip(gpiochip_fd);
        return 1;
    }

    printf("Monitoring vibration sensor on GPIO%d (chip %s)...\n", GPIO_LINE, chip_info.name);

    // Main loop
    while (!terminate) {
        // Wait for a falling edge event
        ret = read(req.fd, &event, sizeof(event));
        if (ret == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            perror("Error reading GPIO event");
            break;
        }

        if (ret == sizeof(event)) {
            // Vibration detected
            timestamp = get_timestamp();
            char log_message_buffer[256];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Vibration detected at %s", timestamp);

            if (log_message(log_message_buffer) == 0) {
                printf("%s\n", log_message_buffer);
            } else {
                fprintf(stderr, "Failed to log message.\n");
            }

            if (shutdown_system() != 0) {
                fprintf(stderr, "Shutdown failed.\n");
            }
            break; // Exit after shutdown is initiated
        } else {
            fprintf(stderr, "Unexpected read size: %d\n", ret);
            break;
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (release_gpio(gpiochip_fd, GPIO_LINE) != 0) {
        fprintf(stderr, "Failed to release GPIO line.\n");
    }
    if (close_gpio_chip(gpiochip_fd) != 0) {
        fprintf(stderr, "Failed to close GPIO chip.\n");
    }

    printf("Exiting.\n");
    return 0;
}

