#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <math.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_ID 0xD0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int init_i2c();
int read_chip_id();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
double calculate_altitude(double pressure);
int log_altitude(double altitude);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read chip ID function
int read_chip_id() {
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading chip ID: %d\n", chip_id);
        return -1;
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%X\n", chip_id);
        return -1;
    }
    printf("BMP280 chip ID: 0x%X\n", chip_id);
    return 0;
}

// Read calibration data function
int read_calibration_data() {
    uint8_t data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)data, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib.dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib.dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib.dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib.dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib.dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib.dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib.dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib.dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib.dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib.dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib.dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw data function
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Temperature compensation function
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double adc_T = (double)raw_temperature;
    double dig_T1 = (double)calib.dig_T1;
    double dig_T2 = (double)calib.dig_T2;
    double dig_T3 = (double)calib.dig_T3;

    var1 = (adc_T / 16384.0 - dig_T1 / 1024.0) * dig_T2;
    var2 = ((adc_T / 131072.0 - dig_T1 / 8192.0) * (adc_T / 131072.0 - dig_T1 / 8192.0)) * dig_T3;
    double t_fine = var1 + var2;
    T = (t_fine / 5120.0);
    return T;
}

// Pressure compensation function
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
    double adc_P = (double)raw_pressure;
    double dig_P1 = (double)calib.dig_P1;
    double dig_P2 = (double)calib.dig_P2;
    double dig_P3 = (double)calib.dig_P3;
    double dig_P4 = (double)calib.dig_P4;
    double dig_P5 = (double)calib.dig_P5;
    double dig_P6 = (double)calib.dig_P6;
    double dig_P7 = (double)calib.dig_P7;
    double dig_P8 = (double)calib.dig_P8;
    double dig_P9 = (double)calib.dig_P9;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * dig_P6 / 32768.0;
    var2 = var2 + var1 * dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (dig_P4 * 65536.0);
    var1 = (dig_P3 * var1 * var1 / 524288.0 + dig_P2 * var1) / 524288.0;
