#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define NUM_SENSORS 3
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
} CircularBuffer;

CircularBuffer sensor_buffers[NUM_SENSORS];

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void add_to_buffer(CircularBuffer *cb, float value);
float get_average_temperature(CircularBuffer *cb);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    return adc_value * 0.48828125; // 10mV/degree C, 1024 steps
}

// Function to add a temperature reading to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
}

// Function to calculate the average temperature from the circular buffer
float get_average_temperature(CircularBuffer *cb) {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += cb->buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffers
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_buffers[i].head = 0;
        for (int j = 0; j < BUFFER_SIZE; j++) {
            sensor_buffers[i].buffer[j] = 0.0; // Initialize with 0
        }
    }

    return 0;
}

// Cleanup function
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    FILE *fp = fopen("temp_log.dat", "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temp_log.dat for writing\n");
    }

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read ADC value from channel %d\n", i);
                continue; // Skip to the next sensor
            }

            float temperature = convert_to_celsius(adc_value);
            add_to_buffer(&sensor_buffers[i], temperature);

            printf("Sensor %d: Temperature: %.2f \u00b0C\n", i, temperature);
        }

        // Write data to file
        if (fp != NULL) {
            for (int i = 0; i < NUM_SENSORS; i++) {
                fwrite(sensor_buffers[i].buffer, sizeof(float), BUFFER_SIZE, fp);
            }
            fflush(fp); // Ensure data is written to disk
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();

    if (fp != NULL) {
        fclose(fp);
    }

    return 0;
}

