#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define MCP3008_CHANNEL 0
#define LOG_FILE "environmental_log.txt"

// Global variables for file descriptors and program state
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_init(const char *bus, int addr);
int spi_init(const char *bus);
float read_bh1750(int fd);
int read_mcp3008(int fd, int channel);
int log_data(FILE *fp, float light, int sound);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int i2c_init(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI initialization function
int spi_init(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI bus");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
