#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define MCP4725_ADDRESS 0x60
#define SAMPLE_INTERVAL_SEC 0.5
#define SPI_SPEED 500000 // 500 kHz
#define VREF 3.3 // Reference voltage for MCP3008

// Global variables
int spi_fd = -1;
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int i2c_init(const char *device, int address);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_mcp3008(int fd, int channel);
float adc_to_celsius(int adc_value);
int write_mcp4725(int fd, uint16_t value);
void log_data(FILE *fp, int adc_value, float temperature, float dac_voltage);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C Initialization
int i2c_init(const char *device, int address) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read MCP3008
int read_mcp3008(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to Celsius Conversion
float adc_to_celsius(int adc_value) {
    float voltage = (adc_value / 1023.0) * VREF;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Write MCP4725
int write_mcp4725(int fd, uint16_t value) {
    uint8_t buf[3];
    buf[0] = 0x40; // Write DAC value command
    buf[1] = (value >> 4) & 0xFF; // Upper 8 bits
    buf[2] = (value << 4) & 0xF0; // Lower 4 bits

    if (write(fd, buf, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Log Data
void log_data(FILE *fp, int adc_value, float temperature, float dac_voltage) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ADC: %d, Temp: %.2f C, DAC: %.2f V\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            adc_value, temperature, dac_voltage);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal Handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

// Cleanup
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE, MCP4725_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert to Celsius
        float temperature = adc_to_celsius(adc_value);

        // Calculate DAC voltage
        float dac_voltage = (temperature / 100.0) * VREF; // Assuming 0-100C range
        uint16_t dac_value = (uint16_t)((dac_voltage / VREF) * 4095.0); // 12-bit DAC

        // Write to DAC
        if (write_mcp4725(i2c_fd, dac_value) < 0) {
            fprintf(stderr, "Error writing to DAC. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Log data
        log_data(log_file, adc_value, temperature, dac_voltage);

        // Print to console
        printf("ADC: %d, Temp: %.2f C, DAC: %.2f V\n", adc_value, temperature, dac_voltage);

        // Wait for next sample
        struct timespec sleep_time;
        sleep_time.tv_sec = (int)SAMPLE_INTERVAL_SEC;
        sleep_time.tv_nsec = (long)((SAMPLE_INTERVAL_SEC - sleep_time.tv_sec) * 1e9);
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

