// Define the GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

// Function to set the state of a relay
int set_relay_state(int gpio_pin, int state) {
    int result = gpioWrite(gpio_pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio_pin, result);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to activate a relay
int activate_relay(int gpio_pin) {
    return set_relay_state(gpio_pin, 1); // HIGH to activate
}

// Function to deactivate a relay
int deactivate_relay(int gpio_pin) {
    return set_relay_state(gpio_pin, 0); // LOW to deactivate
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to the OFF state
    if (deactivate_relay(RELAY1_PIN) != 0 ||
        deactivate_relay(RELAY2_PIN) != 0 ||
        deactivate_relay(RELAY3_PIN) != 0 ||
        deactivate_relay(RELAY4_PIN) != 0) {
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to control the relays
    while (program_running) {
        // Activate and deactivate each relay in sequence
        if (activate_relay(RELAY1_PIN) == 0) {
            sleep(1);
            if (deactivate_relay(RELAY1_PIN) == 0) {
                sleep(1);
            } else {
                break; // Exit loop on error
            }
        } else {
            break; // Exit loop on error
        }

        if (activate_relay(RELAY2_PIN) == 0) {
            sleep(1);
            if (deactivate_relay(RELAY2_PIN) == 0) {
                sleep(1);
            } else {
                break; // Exit loop on error
            }
        } else {
            break; // Exit loop on error
        }

        if (activate_relay(RELAY3_PIN) == 0) {
            sleep(1);
            if (deactivate_relay(RELAY3_PIN) == 0) {
                sleep(1);
            } else {
                break; // Exit loop on error
            }
        } else {
            break; // Exit loop on error
        }

        if (activate_relay(RELAY4_PIN) == 0) {
            sleep(1);
            if (deactivate_relay(RELAY4_PIN) == 0) {
                sleep(1);
            } else {
                break; // Exit loop on error
            }
        } else {
            break; // Exit loop on error
        }
    }

    // Deactivate all relays before exiting
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

