#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Define GPIO pins
#define LED_PIN 16
#define SPI_CE0 8
#define SPI_CE1 7

// Define SPI device paths
#define SPI_DEV0 "/dev/spidev0.0"
#define SPI_DEV1 "/dev/spidev0.1"

// Define SPI mode and speed
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz

// Define sound threshold
#define SOUND_THRESHOLD 500

// Define debounce delay
#define DEBOUNCE_DELAY 200 // milliseconds

// Define LED on time
#define LED_ON_TIME 500 // milliseconds

// Global variables
int spi_fd0 = -1;
int spi_fd1 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
int spi_open(const char *device);
int spi_close(int fd);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_mcp3008(int spi_fd, int channel);
int check_threshold(int adc_value, int threshold);
void log_event(const char *filename);
void debounce_delay(int milliseconds);
void signal_handler(int signal);

// GPIO functions
int gpio_export(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    write(fd, buffer, bytes_written);
    close(fd);
    return 0;
}

int gpio_unexport(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }
    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    write(fd, buffer, bytes_written);
    close(fd);
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open GPIO direction file: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) == -1) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_write(int pin, int value) {
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open GPIO value file: %s\n", strerror(errno));
        return -1;
    }
