#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins for motor control
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor run time
#define MOTOR_RUN_TIME 3000 // 3 seconds

// Define PWM range
#define PWM_RANGE 255

// Define PWM duty cycle
#define PWM_DUTY_CYCLE 150

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
int calculate_rain_level(int adc_value);
void control_motor(int rain_level);
void log_data(int rain_level);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to calculate rain level (example linear mapping)
int calculate_rain_level(int adc_value) {
    // Assuming ADC range is 0-1023
    // Map ADC value to rain level (0-10)
    return (int)(((float)adc_value / 1023.0) * 10.0);
}

// Function to control the motor
void control_motor(int rain_level) {
    if (rain_level > RAIN_THRESHOLD) {
        // Close window
        digitalWrite(MOTOR_IN1, HIGH);
        digitalWrite(MOTOR_IN2, LOW);
        pwmWrite(MOTOR_ENA, PWM_DUTY_CYCLE);
        delay(MOTOR_RUN_TIME);
        pwmWrite(MOTOR_ENA, 0); // Stop motor
    } else {
        // Open window
        digitalWrite(MOTOR_IN1, LOW);
        digitalWrite(MOTOR_IN2, HIGH);
        pwmWrite(MOTOR_ENA, PWM_DUTY_CYCLE);
        delay(MOTOR_RUN_TIME);
        pwmWrite(MOTOR_ENA, 0); // Stop motor
    }
}

// Function to log data to file
void log_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialization function
int initialize() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return -1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return -1;
    }

    // Set motor control pins as output
    pinMode(MOTOR_IN1, OUTPUT);
    pinMode(MOTOR_IN2, OUTPUT);
    pinMode(MOTOR_ENA, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS); // Optional: Set PWM mode
    pwmSetRange(PWM_RANGE);   // Set PWM range
    pwmSetClock(192);        // Set PWM clock (adjust for desired frequency)

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Stop the motor
    pwmWrite(MOTOR_ENA, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() == -1) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value. Retrying.\n");
            delay(1000); // Wait before retrying
            continue;
        }

        // Calculate rain level
        int rain_level = calculate_rain_level(adc_value);

        // Control the motor
        control_motor(rain_level);

        // Log the data
        log_data(rain_level);

        // Wait for 1 second
        delay(1000);
    }

    // Cleanup and exit
    cleanup();
    printf("Rain sensor monitoring stopped.\n");
    return 0;
}

