        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Stop the motor
    pwmWrite(MOTOR_ENA, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() == -1) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value. Retrying.\n");
            delay(1000); // Wait before retrying
            continue;
        }

        // Calculate rain level
        int rain_level = calculate_rain_level(adc_value);

        // Control the motor
        control_motor(rain_level);

        // Log the data
        log_data(rain_level);

        // Wait for 1 second
        delay(1000);
    }

    // Cleanup and exit
    cleanup();
    printf("Rain sensor monitoring stopped.\n");
    return 0;
}

