#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"

static volatile int terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    terminate = 1;
}

// Function to read the digital value from the GPIO pin
int read_distance() {
    return gpioRead(GPIO_PIN);
}

// Function to log the distance reading to a file
void log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Distance: %d\n", timestamp, distance);
    fclose(fp);
}

// Function to print the appropriate message based on the distance
void print_status(int distance) {
    if (distance == 0) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Distance sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int distance = read_distance();
        log_distance(distance);
        print_status(distance);
        gpioDelay(100000); // 100ms delay
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

