#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PIN 17
#define CSV_FILE "current_log.txt"
#define VREF 5.0  // Reference voltage for MCP3008
#define SENSITIVITY 0.1 // Sensor sensitivity in V/A

// Global variables
int spi_fd = -1;
int gpio_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device);
int spi_transfer(int fd, unsigned char *data, int len);
int gpio_export(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_unexport(int pin);
float read_current();
int log_data(float current);
void signal_handler(int sig);

// SPI open function
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI bits per word
    int bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI max speed
    int speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, unsigned char *data, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)data,
        .rx_buf = (unsigned long)data,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO export function
int gpio_export(int pin) {
    char buffer[3];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/export");
        return -1;
    }
    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        perror("Error writing to /sys/class/gpio/export");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }
    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        perror("Error writing to GPIO direction file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO set value function
int gpio_set_value(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }
    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);
    if (write(fd, val_str, 1) != 1) {
        perror("Error writing to GPIO value file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO unexport function
int gpio_unexport(int pin) {
    char buffer[3];
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/unexport");
        return -1;
    }
    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        perror("Error writing to /sys/class/gpio/unexport");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Read current from sensor
float read_current() {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value;
    float current;

    // MCP3008 command to read channel 0 (single-ended)
    tx_buf[0] = 0x01;  // Start bit
    tx_buf[1] = 0x80;  // Single-ended, channel 0
    tx_buf[2] = 0x00;  // Don't care

    if (spi_transfer(spi_fd, tx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1.0;
    }

    // Extract ADC value from response
    adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    // Convert ADC value to voltage
    float voltage = (float)adc_value * VREF / 1024.0;

    // Convert voltage to current
    current = voltage / SENSITIVITY;

    return current;
}

// Log data to CSV file
int log_data(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO export failed\n");
        return 1;
    }
    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        fprintf(stderr, "GPIO set direction failed\n");
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Enable sensor
        if (gpio_set_value(GPIO_PIN, 1) < 0) {
            fprintf(stderr, "GPIO set value failed\n");
            break;
        }

        // Read current
        float current = read_current();
        if (current < 0) {
            fprintf(stderr, "Failed to read current\n");
        } else {
            // Log data
            if (log_data(current) < 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }

        // Disable sensor
        if (gpio_set_value(GPIO_PIN, 0) < 0) {
            fprintf(stderr, "GPIO set value failed\n");
            break;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    close(spi_fd);
    gpio_unexport(GPIO_PIN);
    fclose(log_file);

    return 0;
}

