#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 2

// Number of debounce readings
#define DEBOUNCE_READINGS 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read a sensor with debouncing
int read_sensor(int gpio_pin) {
    int readings[DEBOUNCE_READINGS];
    int sum = 0;

    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(gpio_pin);
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
        sum += readings[i];
    }

    // Determine the majority value
    if (sum < (DEBOUNCE_READINGS / 2) + 1) {
        return 0; // Object present (active low)
    } else {
        return 1; // No object
    }
}

// Function to log the sensor states
void log_sensor_states(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_state, sensor2_state);

    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Enable pull-up resistors (though the sensors have internal pull-ups)
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int sensor1_state = read_sensor(SENSOR_1_GPIO);
        int sensor2_state = read_sensor(SENSOR_2_GPIO);

        log_sensor_states(sensor1_state, sensor2_state);

        gpioDelay(1000000); // Delay for 1 second (1000000 microseconds)
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

