#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DIR "/home/pi/security_cam/"
#define ISO8601_TIMESTAMP_SIZE 25

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to read the PIR sensor state
int read_pir_sensor() {
    return gpioRead(PIR_GPIO);
}

// Function to apply a debounce delay
void debounce_delay() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
}

// Function to get the current timestamp in ISO 8601 format
int get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    if (strftime(timestamp, ISO8601_TIMESTAMP_SIZE, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        syslog(LOG_ERR, "Failed to format timestamp");
        return -1;
    }
    return 0;
}

// Function to construct the filename for the captured image
int construct_filename(char *filename, size_t filename_size, const char *timestamp) {
    if (snprintf(filename, filename_size, "%s%s.jpg", CAPTURE_DIR, timestamp) >= filename_size) {
        syslog(LOG_ERR, "Filename buffer overflow");
        return -1;
    }
    return 0;
}

// Function to check if the capture directory exists, create it if it doesn't
int check_and_create_directory() {
    struct stat st = {0};

    if (stat(CAPTURE_DIR, &st) == -1) {
        if (mkdir(CAPTURE_DIR, 0777) == -1) {
            syslog(LOG_ERR, "Failed to create directory: %s", strerror(errno));
            return -1;
        }
        syslog(LOG_INFO, "Created directory: %s", CAPTURE_DIR);
    }
    return 0;
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    pid_t pid = fork();

    if (pid == 0) {
        // Child process
        char *args[] = {"libcamera-still", "-o", (char *)filename, NULL};
        execvp("libcamera-still", args);
        // execvp only returns on error
        syslog(LOG_ERR, "execvp failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        // Fork failed
        syslog(LOG_ERR, "Fork failed: %s", strerror(errno));
        return -1;
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status)) {
            int exit_status = WEXITSTATUS(status);
            if (exit_status != 0) {
                syslog(LOG_ERR, "libcamera-still exited with status %d", exit_status);
                return -1;
            }
        } else {
            syslog(LOG_ERR, "libcamera-still terminated abnormally");
            return -1;
        }
    }
    return 0;
}

int main() {
    // Open syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Set PIR GPIO as input with pull-down resistor
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    syslog(LOG_INFO, "Security camera started");

    // Main loop
    while (program_running) {
        // Read PIR sensor
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            syslog(LOG_INFO, "Motion detected");

            // Debounce
            debounce_delay();
            int pir_value_confirmed = read_pir_sensor();

            if (pir_value_confirmed == 1) {
                syslog(LOG_INFO, "Motion confirmed");

                // Get timestamp
                char timestamp[ISO8601_TIMESTAMP_SIZE];
                if (get_iso8601_timestamp(timestamp) != 0) {
                    syslog(LOG_ERR, "Failed to get timestamp, skipping capture");
                    continue;
                }

                // Construct filename
                char filename[256];
                if (construct_filename(filename, sizeof(filename), timestamp) != 0) {
                    syslog(LOG_ERR, "Failed to construct filename, skipping capture");
                    continue;
                }

                // Check/create directory
                if (check_and_create_directory() != 0) {
                    syslog(LOG_ERR, "Failed to check/create directory, skipping capture");
                    continue;
                }

                // Capture image
                if (capture_image(filename) != 0) {
                    syslog(LOG_ERR, "Image capture failed");
                } else {
                    syslog(LOG_INFO, "Image captured: %s", filename);
                }
            }
        }

        // Wait before next poll
        gpioDelay(50 * 1000); // 50ms
    }

    // Cleanup
    gpioTerminate();
    syslog(LOG_INFO, "Security camera stopped");
    closelog();

    return 0;
}

