#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void   *start;
    size_t  length;
};

static int              fd                  = -1;
static struct buffer    *buffers             = NULL;
static unsigned int     n_buffers           = 0;
static int              frame_count         = 0;
static char             *device_name         = "/dev/video0";
static int              image_width         = 640;
static int              image_height        = 480;
static int              running             = 1;

void signal_handler(int signum) {
    running = 0;
    printf("Caught signal %d, stopping...\n", signum);
}

int xioctl(int fh, int request, void *arg) {
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    if (-1 == r) {
        fprintf(stderr, "Error: ioctl %d failed: %s\n", request, strerror(errno));
    }

    return r;
}

int main(int argc, char *argv[]) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct timeval tv;
    fd_set fds;
    int r, i;

    // Parse command-line arguments
    if (argc > 1) {
        device_name = argv[1];
    }
    if (argc > 3) {
        image_width = atoi(argv[2]);
        image_height = atoi(argv[3]);
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error: Cannot open '%s': %s\n", device_name, strerror(errno));
        return 1;
    }

    // Query device capabilities
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error: VIDIOC_QUERYCAP failed\n");
        goto err;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", device_name);
        goto err;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", device_name);
        goto err;
    }

    // Set image format
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = image_width;
    fmt.fmt.pix.height = image_height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error: VIDIOC_S_FMT failed\n");
        goto err;
    }

    // Request buffers
    CLEAR(req);
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error: VIDIOC_REQBUFS failed\n");
        goto err;
    }

    if (req.count < 1) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        goto err;
    }

    // Allocate buffers
    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Error: Out of memory\n");
        goto err;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        CLEAR(buf);

        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error: VIDIOC_QUERYBUF failed\n");
            goto err;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            fprintf(stderr, "Error: mmap failed\n");
            goto err;
        }
    }

    // Queue buffers
    for (i = 0; i < n_buffers; ++i) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error: VIDIOC_QBUF failed\n");
            goto err;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error: VIDIOC_STREAMON failed\n");
        goto err;
    }

    // Capture loop
    while (running) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (-1 == r) {
            if (EINTR == errno) {
                continue; // Interrupted by signal
            }
            fprintf(stderr, "Error: select failed\n");
            goto err;
        }

        if (0 == r) {
            fprintf(stderr, "Error: select timeout\n");
            continue; // Timeout occurred
        }

        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (EAGAIN == errno) {
                continue; // No buffer available
            }
            fprintf(stderr, "Error: VIDIOC_DQBUF failed\n");
            goto err;
        }

        // Save frame to file
        char filename[64];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", ++frame_count);
        FILE *fp = fopen(filename, "wb");
        if (!fp) {
            fprintf(stderr, "Error: Cannot open '%s': %s\n", filename, strerror(errno));
            goto err;
        }

        fprintf(fp, "P5\n%d %d\n255\n", image_width, image_height);
        fwrite(buffers[buf.index].start, 1, buf.bytesused, fp);
        fclose(fp);

        // Requeue buffer
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error: VIDIOC_QBUF failed\n");
            goto err;
        }
    }

    // Stop streaming
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error: VIDIOC_STREAMOFF failed\n");
        goto err;
    }

err:
    // Unmap buffers
    for (i = 0; i < n_buffers; ++i) {
        if (buffers[i].start != MAP_FAILED) {
            if (munmap(buffers[i].start, buffers[i].length) < 0) {
                fprintf(stderr, "Error: munmap failed: %s\n", strerror(errno));
            }
        }
    }

    // Free buffers
    free(buffers);

    // Close device
    if (fd != -1) {
        close(fd);
    }

    return 0;
}

