#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define LOG_FILE "frame_log.txt"
#define NUM_BUFFERS 4

// Structure to hold buffer information
struct buffer {
    void   *start;
    size_t  length;
};

static int                  fd                  = -1;
static struct buffer        *buffers             = NULL;
static unsigned int         n_buffers           = 0;
static FILE                 *log_file            = NULL;
static volatile sig_atomic_t stop_flag           = 0;

// Signal handler for graceful shutdown
static void signal_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        stop_flag = 1;
    }
}

// Function to log the current timestamp to a file
static int log_timestamp(void) {
    struct timeval tv;
    if (gettimeofday(&tv, NULL) == -1) {
        perror("gettimeofday");
        return -1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%ld.%06ld\n", tv.tv_sec, tv.tv_usec);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
    return 0;
}

// Function to initialize the video device
static int init_device(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        return -1;
    }

    // Set video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type               = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width      = 640; // Example width
    fmt.fmt.pix.height     = 480; // Example height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field      = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count              = NUM_BUFFERS;
    req.type               = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory             = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    // Allocate buffers
    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
