#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4
#define UDP_PAYLOAD_SIZE 65000

// Structure to hold frame data and buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

buffer *buffers = NULL;
int              fd = -1;             /* File descriptor */
int              sockfd = -1;          /* Socket file descriptor */
struct sockaddr_in servaddr;           /* Server address */
int              frame_index = 0;      /* Current frame index */
volatile sig_atomic_t stop_flag = 0;  /* Flag to signal program termination */

// Function prototypes
int  open_device(const char *device_name);
int  init_device(int fd, int width, int height);
int  start_capturing(int fd);
int  stop_capturing(int fd);
int  uninit_device(int fd);
int  close_device(int fd);
int  create_socket(const char *ip_address, int port);
void close_socket(int sockfd);
int  capture_frame(int fd, int index);
int  send_udp_packet(int sockfd, const void *data, size_t size, int frame_index, int fragment_index, int total_fragments);
void signal_handler(int sig);

// Signal handler to catch SIGINT and SIGTERM
void signal_handler(int sig) {
    fprintf(stderr, "Signal caught, stopping...\n");
    stop_flag = 1;
}

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to initialize the video device
int init_device(int fd, int width, int height) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    // Allocate buffers
    buffers = calloc(req.count, sizeof(buffer));
    if (!buffers) {
        fprintf(stderr, "Error allocating buffers\n");
        return -1;
    }

    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Function to start capturing
int start_capturing(int fd) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to uninitialize the device
int uninit_device(int fd) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    free(buffers);
    return 0;
}

// Function to close the device
int close_device(int fd) {
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to create a UDP socket
int create_socket(const char *ip_address, int port) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_address, &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Function to close the socket
void close_socket(int sockfd) {
    if (close(sockfd) < 0) {
        fprintf(stderr, "Error closing socket: %s\n", strerror(errno));
    }
}

// Function to capture a frame
int capture_frame(int fd, int index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to send a UDP packet
int send_udp_packet(int sockfd, const void *data, size_t size, int frame_index, int fragment_index, int total_fragments) {
    unsigned char header[12];
    header[0] = (frame_index >> 24) & 0xFF;
    header[1] = (frame_index >> 16) & 0xFF;
    header[2] = (frame_index >> 8) & 0xFF;
    header[3] = frame_index & 0xFF;
    header[4] = (fragment_index >> 24) & 0xFF;
    header[5] = (fragment_index >> 16) & 0xFF;
    header[6] = (fragment_index >> 8) & 0xFF;
    header[7] = fragment_index & 0xFF;
    header[8] = (total_fragments >> 24) & 0xFF;
    header[9] = (total_fragments >> 16) & 0xFF;
    header[10] = (total_fragments >> 8) & 0xFF;
    header[11] = total_fragments & 0xFF;

    unsigned char *packet = malloc(size + 12);
    if (!packet) {
        fprintf(stderr, "Error allocating packet\n");
        return -1;
    }

    memcpy(packet, header, 12);
    memcpy(packet + 12, data, size);

    ssize_t sent_bytes = sendto(sockfd, packet, size + 12, 0, (struct sockaddr *)&servaddr, sizeof(servaddr));
    if (sent_bytes < 0) {
        fprintf(stderr, "Error sending packet: %s\n", strerror(errno));
        free(packet);
        return -1;
    }

    free(packet);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <ip_address> <port>\n", argv[0]);
        return 1;
    }

    const char *ip_address = argv[1];
    int port = atoi(argv[2]);

    // Install signal handlers
    signal(SIGINT, signal_handler);
