            if (stop_flag) break;

            if (ioctl(fd, VIDIOC_QBUF, &((struct v4l2_buffer){.type = V4L2_BUF_TYPE_VIDEO_CAPTURE, .memory = V4L2_MEMORY_MMAP, .index = i})) < 0) {
                fprintf(stderr, "Error requeuing buffer: %s\n", strerror(errno));
                stop_flag = 1;
                break;
            }

            frame_index++;
        }
    }

    // Stop capturing
    if (stop_capturing(fd) < 0) {
        fprintf(stderr, "Error stopping capturing during cleanup.\n");
    }

    // Uninitialize the device
    if (uninit_device(fd) < 0) {
        fprintf(stderr, "Error uninitializing device during cleanup.\n");
    }

