#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON 6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON 8
#define PAN_RIGHT_BUTTON 9

// Define PWM frequency and range
#define PWM_FREQUENCY 50
#define PWM_RANGE 1000

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 1000 // 1ms
#define SERVO_MAX_PULSE_WIDTH 2000 // 2ms

// Define initial servo position
#define INITIAL_SERVO_POSITION 75

// Define button press increment/decrement
#define SERVO_INCREMENT 5

// Global variables for servo positions
int pan_position = INITIAL_SERVO_POSITION;
int tilt_position = INITIAL_SERVO_POSITION;

// Function prototypes
int initialize_gpio();
void set_servo_position(int gpio_pin, int pulse_width);
int read_button(int gpio_pin);
void handle_button_press(int button_pin, int *servo_position, int increment);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Set servos to a safe position (e.g., center)
    set_servo_position(PAN_SERVO_PIN, (SERVO_MIN_PULSE_WIDTH + SERVO_MAX_PULSE_WIDTH) / 2);
    set_servo_position(TILT_SERVO_PIN, (SERVO_MIN_PULSE_WIDTH + SERVO_MAX_PULSE_WIDTH) / 2);
    gpioTerminate();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set servo pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set button pins as inputs with pull-up resistors
    gpioSetMode(TILT_UP_BUTTON, PI_INPUT);
    gpioSetPullUpDown(TILT_UP_BUTTON, PI_PUD_UP);
    gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT);
    gpioSetPullUpDown(TILT_DOWN_BUTTON, PI_PUD_UP);
    gpioSetMode(PAN_LEFT_BUTTON, PI_INPUT);
    gpioSetPullUpDown(PAN_LEFT_BUTTON, PI_PUD_UP);
    gpioSetMode(PAN_RIGHT_BUTTON, PI_INPUT);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON, PI_PUD_UP);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    return 0; // Indicate success
}

// Set servo position using PWM
void set_servo_position(int gpio_pin, int pulse_width) {
    // Ensure pulse width is within limits
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    } else if (pulse_width > SERVO_MAX_PULSE_WIDTH) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    }

    // Calculate duty cycle (0-1000)
    int duty_cycle = (pulse_width - SERVO_MIN_PULSE_WIDTH) * 1000 / (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH);

    gpioPWM(gpio_pin, duty_cycle);
}

// Read button state
int read_button(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Handle button press and update servo position
void handle_button_press(int button_pin, int *servo_position, int increment) {
    if (read_button(button_pin) == 0) { // Button is pressed (active low)
        *servo_position += increment;

        // Clamp servo position to valid range
        if (*servo_position < 25) {
            *servo_position = 25;
        } else if (*servo_position > 125) {
            *servo_position = 125;
        }

        // Calculate pulse width based on servo position
        int pulse_width = SERVO_MIN_PULSE_WIDTH + (*servo_position - 25) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / (125 - 25);

        // Set servo position
        if (button_pin == TILT_UP_BUTTON || button_pin == TILT_DOWN_BUTTON) {
            set_servo_position(TILT_SERVO_PIN, pulse_width);
        } else {
            set_servo_position(PAN_SERVO_PIN, pulse_width);
        }

        gpioDelay(200); // Debounce delay
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Set initial servo positions
    set_servo_position(PAN_SERVO_PIN, SERVO_MIN_PULSE_WIDTH + (pan_position - 25) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / (125 - 25));
    set_servo_position(TILT_SERVO_PIN, SERVO_MIN_PULSE_WIDTH + (tilt_position - 25) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / (125 - 25));

    printf("Pan-Tilt control program running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        handle_button_press(TILT_UP_BUTTON, &tilt_position, SERVO_INCREMENT);
        handle_button_press(TILT_DOWN_BUTTON, &tilt_position, -SERVO_INCREMENT);
        handle_button_press(PAN_LEFT_BUTTON, &pan_position, -SERVO_INCREMENT);
        handle_button_press(PAN_RIGHT_BUTTON, &pan_position, SERVO_INCREMENT);

        gpioDelay(50); // Poll buttons every 50ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

