#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <jpeglib.h>

#define DEVICE_NAME "/dev/video0"
#define NUM_BUFFERS 4
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75

typedef struct {
    void   *start;
    size_t  length;
} buffer;

buffer *buffers = NULL;
int fd = -1;
int num_buffers = 0;

// Function to handle errors
void error_exit(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, cleaning up...\n");
        // Cleanup resources
        if (fd != -1) {
            // Stop streaming
            if (ioctl(fd, VIDIOC_STREAMOFF, &buffers[0].start) == -1) {
                perror("VIDIOC_STREAMOFF");
            }

            // Unmap buffers
            for (int i = 0; i < num_buffers; i++) {
                if (munmap(buffers[i].start, buffers[i].length) == -1) {
                    perror("munmap");
                }
            }

            // Free buffers
            free(buffers);

            // Close device
            close(fd);
        }
        exit(0);
    }
}

// Function to convert YUYV to RGB24
void yuyv_to_rgb24(unsigned char *yuyv, unsigned char *rgb24, int width, int height) {
    for (int i = 0; i < width * height; i++) {
        unsigned char y = yuyv[i * 2];
        unsigned char u = yuyv[i * 2 + 1];
        unsigned char v = yuyv[(i * 2) % (width * height) + 2];

        int r = y + 1.370705 * (v - 128);
        int g = y - 0.698001 * (v - 128) - 0.336331 * (u - 128);
        int b = y + 1.732446 * (u - 128);

        r = (r < 0) ? 0 : ((r > 255) ? 255 : r);
        g = (g < 0) ? 0 : ((g > 255) ? 255 : g);
        b = (b < 0) ? 0 : ((b > 255) ? 255 : b);

        rgb24[i * 3] = r;
        rgb24[i * 3 + 1] = g;
        rgb24[i * 3 + 2] = b;
    }
}

// Function to apply a simple blur filter
void blur_image(unsigned char *image, int width, int height) {
    unsigned char *temp_image = (unsigned char *)malloc(width * height * 3);
    if (temp_image == NULL) {
        error_exit("Failed to allocate memory for temporary image");
    }

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int r = 0, g = 0, b = 0;
            int count = 0;

            for (int i = -BLUR_RADIUS; i <= BLUR_RADIUS; i++) {
                for (int j = -BLUR_RADIUS; j <= BLUR_RADIUS; j++) {
                    int nx = x + i;
                    int ny = y + j;

                    if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                        r += image[(ny * width + nx) * 3];
                        g += image[(ny * width + nx) * 3 + 1];
                        b += image[(ny * width + nx) * 3 + 2];
                        count++;
                    }
                }
            }

            temp_image[(y * width + x) * 3] = r / count;
            temp_image[(y * width + x) * 3 + 1] = g / count;
            temp_image[(y * width + x) * 3 + 2] = b / count;
        }
