void signal_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, cleaning up...\n");
        // Cleanup resources
        if (fd != -1) {
            // Stop streaming
            if (ioctl(fd, VIDIOC_STREAMOFF, &buffers[0].start) == -1) {
                perror("VIDIOC_STREAMOFF");
            }

            // Unmap buffers
