#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"

// Function to check if a device exists
int device_exists(const char *device_name) {
    struct stat st;
    return (stat(device_name, &st) == 0);
}

// Function to open the device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_capabilities(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus Info: %s\n", cap.bus_info);
    printf("Version: %u.%u.%u\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("Capabilities: 0x%08x\n", cap.capabilities);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming\n");
        return -1;
    }

    return 0;
}

// Function to enumerate frame sizes
int enum_frame_sizes(int fd) {
    struct v4l2_frmsizeenum frmsize;
    frmsize.pixel_format = V4L2_PIX_FMT_YUYV; // Example pixel format
    frmsize.index = 0;

    printf("\nSupported Frame Sizes:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        printf("  Index: %d, Type: %d, Width: %d, Height: %d\n", frmsize.index, frmsize.type, frmsize.discrete.width, frmsize.discrete.height);
        frmsize.index++;
    }

    if (errno != EINVAL) {
        perror("Error enumerating frame sizes");
        return -1;
    }

    return 0;
}

// Function to enumerate frame intervals
int enum_frame_intervals(int fd, int width, int height) {
    struct v4l2_frmivalenum frmival;
    frmival.pixel_format = V4L2_PIX_FMT_YUYV; // Example pixel format
    frmival.width = width;
    frmival.height = height;
    frmival.index = 0;

    printf("    Supported Frame Intervals (Width: %d, Height: %d):\n", width, height);
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
            printf("      Index: %d, Type: Discrete, Numerator: %d, Denominator: %d\n", frmival.index, frmival.discrete.numerator, frmival.discrete.denominator);
        } else if (frmival.type == V4L2_FRMIVAL_TYPE_CONTINUOUS || frmival.type == V4L2_FRMIVAL_TYPE_STEPWISE) {
            printf("      Index: %d, Type: Continuous/Stepwise (Not fully implemented in this example)\n", frmival.index);
        }
        frmival.index++;
    }

    if (errno != EINVAL) {
        perror("Error enumerating frame intervals");
        return -1;
    }

    return 0;
}

// Function to check for autofocus capability
int check_autofocus(int fd) {
    struct v4l2_queryctrl queryctrl;
    queryctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == 0) {
        printf("\nAutofocus is supported.\n");
        return 1;
    } else {
        if (errno == EINVAL) {
            printf("\nAutofocus is not supported.\n");
        } else {
            perror("Error querying autofocus capability");
        }
        return 0;
    }
}

int main() {
    int fd;

    // Check if the device exists
    if (!device_exists(DEVICE_NAME)) {
        fprintf(stderr, "Error: Device %s does not exist\n", DEVICE_NAME);
        return 1;
    }

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return 1;
    }

    // Query device capabilities
    if (query_capabilities(fd) < 0) {
        close(fd);
        return 1;
    }

    // Enumerate frame sizes
    if (enum_frame_sizes(fd) < 0) {
        close(fd);
        return 1;
    }

    // Enumerate frame intervals (example for one size)
    // In a real application, you would iterate through all sizes obtained in enum_frame_sizes
    enum_frame_intervals(fd, 640, 480); // Example size

    // Check for autofocus capability
    check_autofocus(fd);

    // Close the device
    close(fd);

    return 0;
}

