#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define pulse width limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500

// Define pulse width increment/decrement
#define PULSE_WIDTH_STEP 10

// Global variables for pulse widths
volatile int pan_pulse_width = CENTER_PULSE_WIDTH;
volatile int tilt_pulse_width = CENTER_PULSE_WIDTH;

// Function prototypes
int initialize_gpio();
void set_servo_pulse_width(int gpio_pin, int pulse_width);
int read_button_state(int gpio_pin);
void handle_button_press(int button_pin, int *pulse_width, int min_pulse, int max_pulse, int step);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Stop PWM on both servo pins
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set servo pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set button pins as inputs with pull-up resistors
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to set servo pulse width
void set_servo_pulse_width(int gpio_pin, int pulse_width) {
    // Clamp pulse width to limits
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }

    // Calculate PWM duty cycle (0-1000000)
    int duty_cycle = (pulse_width * 1000000) / 20000; // 20ms period

    // Set PWM duty cycle
    gpioPWM(gpio_pin, duty_cycle);
}

// Function to read button state
int read_button_state(int gpio_pin) {
    return !gpioRead(gpio_pin); // Active-low buttons
}

// Function to handle button press
void handle_button_press(int button_pin, int *pulse_width, int min_pulse, int max_pulse, int step) {
    if (read_button_state(button_pin)) {
        *pulse_width += step;
        if (*pulse_width > max_pulse) {
            *pulse_width = max_pulse;
        }
        set_servo_pulse_width((button_pin == UP_BUTTON_PIN || button_pin == DOWN_BUTTON_PIN) ? TILT_SERVO_PIN : PAN_SERVO_PIN, *pulse_width);
        gpioDelay(50000); // Debounce delay (50ms)
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Print startup message
    printf("Pan-Tilt Control Program\n");
    printf("Pan Servo: GPIO%d, Tilt Servo: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("UP: GPIO%d, DOWN: GPIO%d, LEFT: GPIO%d, RIGHT: GPIO%d\n", UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Center Position: Pan = %d, Tilt = %d\n", CENTER_PULSE_WIDTH, CENTER_PULSE_WIDTH);

    // Main loop
    while (1) {
        handle_button_press(UP_BUTTON_PIN, &tilt_pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH, PULSE_WIDTH_STEP);
        handle_button_press(DOWN_BUTTON_PIN, &tilt_pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH, -PULSE_WIDTH_STEP);
        handle_button_press(LEFT_BUTTON_PIN, &pan_pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH, -PULSE_WIDTH_STEP);
        handle_button_press(RIGHT_BUTTON_PIN, &pan_pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH, PULSE_WIDTH_STEP);

        gpioDelay(50000); // Delay 50ms
    }

    return 0;
}

