int initialize_gpio() {
  if (wiringPiSetupGpio() == -1) {
    fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
    return -1;
  }
  pinMode(PIR_PIN, INPUT);
  pullUpDnControl(PIR_PIN, PUD_DOWN);
  return 0;
}

// Function to capture a JPEG image using raspistill
int capture_image(char *filename) {
  char command[256];
  snprintf(command, sizeof(command), "raspistill -o %s -q %d", filename, JPEG_QUALITY);
  int status = system(command);
  if (status == -1) {
    fprintf(stderr, "system() failed: %s\n", strerror(errno));
    return -1;
  }
  if (WEXITSTATUS(status) != 0) {
    fprintf(stderr, "raspistill failed with exit code %d\n", WEXITSTATUS(status));
    return -1;
  }
  return 0;
}

// Function to create the motion_captures directory if it doesn't exist
int create_capture_directory() {
  struct stat st = {0};
  if (stat(MOTION_CAPTURE_DIR, &st) == -1) {
    if (mkdir(MOTION_CAPTURE_DIR, 0777) == -1) {
      fprintf(stderr, "mkdir failed: %s\n", strerror(errno));
      return -1;
    }
  }
  return 0;
}

// Function to generate a filename with an ISO 8601 timestamp
int generate_filename(char *filename, size_t filename_size) {
  time_t rawtime;
  struct tm *timeinfo;
  struct timespec ts;

  clock_gettime(CLOCK_REALTIME, &ts);
  time(&rawtime);
  timeinfo = localtime(&rawtime);

  strftime(filename, filename_size, MOTION_CAPTURE_DIR "/motion_%Y-%m-%dT%H-%M-%S", timeinfo);
  snprintf(filename + strlen(filename), filename_size - strlen(filename), ".%06ld.jpg", ts.tv_nsec / 1000);
  return 0;
}

// Function to create the JSON payload
json_t *create_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
  json_t *root = json_object();
  json_object_set_new(root, "filename", json_string(filename));
  json_object_set_new(root, "timestamp", json_string(timestamp));
  json_object_set_new(root, "motion_status", json_integer(motion_status));
  json_object_set_new(root, "gpio_pin", json_integer(gpio_pin));
  return root;
}

// Function to get the current timestamp with microseconds
int get_timestamp(char *timestamp, size_t timestamp_size) {
  time_t rawtime;
  struct tm *timeinfo;
  struct timespec ts;

  clock_gettime(CLOCK_REALTIME, &ts);
  time(&rawtime);
  timeinfo = localtime(&rawtime);

  strftime(timestamp, timestamp_size, "%Y-%m-%dT%H:%M:%S", timeinfo);
  snprintf(timestamp + strlen(timestamp), timestamp_size - strlen(timestamp), ".%06ldZ", ts.tv_nsec / 1000);
  return 0;
}

// Function to send the HTTP POST request
int send_http_post(const char *filename, const char *timestamp, int motion_status, int gpio_pin, const char *server_ip, int server_port) {
  CURL *curl;
  CURLcode res;
  char url[256];
  char json_string[1024];
  json_t *json_payload;
  struct curl_slist *headers = NULL;
  FILE *fp;
  long filesize;
  char *image_data;
  struct MemoryStruct chunk;

  // Create the JSON payload
  json_payload = create_json_payload(filename, timestamp, motion_status, gpio_pin);
  json_dumpf(json_payload, stdout, JSON_INDENT(4));
  json_dumpf(json_payload, (json_dump_callback_t)snprintf, json_string, sizeof(json_string), JSON_INDENT(4));
  json_decref(json_payload);

  // Read the image file
  fp = fopen(filename, "rb");
  if (fp == NULL) {
    fprintf(stderr, "fopen failed: %s\n", strerror(errno));
    return -1;
  }

  fseek(fp, 0, SEEK_END);
  filesize = ftell(fp);
  fseek(fp, 0, SEEK_SET);

  image_data = malloc(filesize);
  if (image_data == NULL) {
    fprintf(stderr, "malloc failed: %s\n", strerror(errno));
    fclose(fp);
    return -1;
  }

  fread(image_data, 1, filesize, fp);
  fclose(fp);

  // Initialize libcurl
  curl_global_init(CURL_GLOBAL_ALL);
  curl = curl_easy_init();
  if (curl) {
    // Construct the URL
    snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);

    // Set the URL
    curl_easy_setopt(curl, CURLOPT_URL, url);

    // Set the HTTP method to POST
    curl_easy_setopt(curl, CURLOPT_POST, 1L);

    // Set the POST fields
    curl_mime *mime = curl_mime_init(curl);
    curl_mimepart *part = curl_mime_addpart(mime);
    curl_mime_name(part, "json");
    curl_mime_data(part, json_string, CURL_ZERO_TERMINATED);

    part = curl_mime_addpart(mime);
    curl_mime_name(part, "image");
    curl_mime_data(part, image_data, filesize);
    curl_mime_filename(part, filename);
    curl_mime_type(part, "image/jpeg");

    curl_easy_setopt(curl, CURLOPT_MIMEPOST, mime);

    // Set the headers
    headers = curl_slist_append(headers, "Expect:");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Set the write callback function
    chunk.memory = malloc(1);
    chunk.size = 0;
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

    // Perform the request
    res = curl_easy_perform(curl);

    // Check for errors
    if (res != CURLE_OK) {
      fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    } else {
      // Print the response
      printf("%lu bytes retrieved\n", (unsigned long)chunk.size);
      printf("%s\n", chunk.memory);
    }

    // Clean up
    curl_easy_cleanup(curl);
    curl_slist_free_all(headers);
    curl_mime_free(mime);
    free(chunk.memory);
  }
  curl_global_cleanup();
  free(image_data);
  return (res == CURLE_OK) ? 0 : -1;
}

// Signal handler function
void signal_handler(int signal) {
  program_running = 0;
  printf("Caught signal %d, exiting...\n", signal);
}

int main(int argc, char *argv[]) {
  int motion_detected = 0;
  time_t last_motion_time = 0;
  char filename[256];
  char timestamp[64];

  // Check command-line arguments
  if (argc != 3) {
    fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
    return 1;
  }

  server_ip = argv[1];
  server_port = atoi(argv[2]);

  // Initialize wiringPi
  if (initialize_gpio() == -1) {
    return 1;
  }

  // Create the capture directory
  if (create_capture_directory() == -1) {
    return 1;
  }

  // Set up signal handling
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  printf("Motion detection started. Press Ctrl+C to exit.\n");

  // Main loop
  while (program_running) {
    int pir_value = digitalRead(PIR_PIN);

    if (pir_value == HIGH) {
      time_t current_time = time(NULL);
      if (!motion_detected || (current_time - last_motion_time) * 1000 >= DEBOUNCE_DELAY_MS) {
        motion_detected = 1;
        last_motion_time = current_time;

        // Generate filename
        if (generate_filename(filename, sizeof(filename)) == -1) {
          fprintf(stderr, "Failed to generate filename\n");
          continue;
        }

        // Capture image
        if (capture_image(filename) == -1) {
          fprintf(stderr, "Failed to capture image\n");
          continue;
        }

        // Get timestamp
        if (get_timestamp(timestamp, sizeof(timestamp)) == -1) {
          fprintf(stderr, "Failed to get timestamp\n");
          continue;
        }

        // Send HTTP POST request
        if (send_http_post(filename, timestamp, 1, PIR_PIN, server_ip, server_port) == -1) {
          fprintf(stderr, "Failed to send HTTP POST request\n");
        }
      }
    } else {
      motion_detected = 0;
    }

    delay(POLL_DELAY_MS);
  }

  printf("Exiting cleanly.\n");

  return 0;
}

