#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"
#define DEBOUNCE_DELAY_MS 50
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int gpio_fd = -1;
int log_fd = -1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_edge(int pin, const char *edge);
int gpio_read_value(int pin);
int capture_image(const char *filename);
int log_event(const char *message);
void signal_handler(int signum);

// Helper function to get current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y%m%d_%H%M%S", timeinfo);
}

// Function to export the GPIO pin
int gpio_export(int pin)
{
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd == -1) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }

    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    write(fd, buffer, bytes_written);
    close(fd);
    return 0;
}

// Function to unexport the GPIO pin
int gpio_unexport(int pin)
{
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd == -1) {
        perror("Failed to open /sys/class/gpio/unexport");
        return -1;
    }

    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    write(fd, buffer, bytes_written);
    close(fd);
    return 0;
}

// Function to set the GPIO direction (in or out)
int gpio_set_direction(int pin, const char *direction)
{
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) == -1) {
        perror("Failed to write to GPIO direction file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the GPIO edge trigger (rising, falling, both, none)
int gpio_set_edge(int pin, const char *edge)
{
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/edge", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open GPIO edge file");
        return -1;
    }

    if (write(fd, edge, strlen(edge)) == -1) {
        perror("Failed to write to GPIO edge file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the GPIO value (0 or 1)
int gpio_read_value(int pin)
{
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (read(fd, value_str, 3) == -1) {
        perror("Failed to read GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to capture an image using raspistill
int capture_image(const char *filename)
{
    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s -w 640 -h 480 -q 85 -t 2000 --nopreview", filename);
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspistill command");
        return -1;
    }
    return status;
}

// Function to log an event to the log file
int log_event(const char *message)
{
    char timestamp[20];
    get_timestamp(timestamp);

    if (log_fd == -1) {
        log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
        if (log_fd == -1) {
            perror("Failed to open log file");
            return -1;
        }
    }

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s\n", timestamp, message);

    if (write(log_fd, log_message, strlen(log_message)) == -1) {
        perror("Failed to write to log file");
        return -1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int signum)
{
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signum);

    // Unexport GPIO pin
    if (gpio_fd != -1) {
        gpio_unexport(GPIO_PIN);
    }

    // Close log file
    if (log_fd != -1) {
        close(log_fd);
    }

    exit(0);
}

int main()
{
    char filename[128];
    char timestamp[20];
    int motion_detected = 0;
    struct timespec start_time, current_time;
    long elapsed_time_ms;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) == -1) {
        log_event("Failed to export GPIO pin");
        return 1;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") == -1) {
        log_event("Failed to set GPIO direction to input");
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Set GPIO edge to falling
    if (gpio_set_edge(GPIO_PIN, "falling") == -1) {
        log_event("Failed to set GPIO edge to falling");
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read GPIO value
        int value = gpio_read_value(GPIO_PIN);
        if (value == -1) {
            log_event("Failed to read GPIO value");
            sleep(1); // Avoid spamming the log
            continue;
        }

        // Check for motion detection
        if (value == 0 && !motion_detected) {
            motion_detected = 1;
            clock_gettime(CLOCK_MONOTONIC, &start_time);

            // Debounce
            do {
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                elapsed_time_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000;
                if (gpio_read_value(GPIO_PIN) == 1) {
                    motion_detected = 0;
                    break;
                }
                usleep(1000); // Check every 1ms
            } while (elapsed_time_ms < DEBOUNCE_DELAY_MS);

            if (motion_detected) {
                // Generate filename
                get_timestamp(timestamp);
                snprintf(filename, sizeof(filename), "%s/%s_mmm.jpg", IMAGE_DIR, timestamp);

                // Capture image
                int capture_status = capture_image(filename);
                if (capture_status == 0) {
                    char log_message[256];
                    snprintf(log_message, sizeof(log_message), "Motion detected and image captured: %s", filename);
                    log_event(log_message);
                } else {
                    char log_message[256];
                    snprintf(log_message, sizeof(log_message), "Failed to capture image (exit code %d)", capture_status);
                    log_event(log_message);
                }
                motion_detected = 0; // Reset motion detection flag
            }
        } else if (value == 1) {
            motion_detected = 0; // Reset motion detection flag if no motion is detected
        }

        usleep(10000); // Check every 10ms
    }

    // Unexport GPIO pin
    gpio_unexport(GPIO_PIN);

    // Close log file
    if (log_fd != -1) {
        close(log_fd);
    }

    return 0;
}

