#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define OUTPUT_FILE "cropped.yuv"

static int fd = -1; // File descriptor for the video device
static void *buffer = NULL; // Memory-mapped buffer
static size_t buffer_size = 0; // Size of the memory-mapped buffer
static volatile sig_atomic_t stop_flag = 0; // Flag to signal program termination

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    (void)signum; // Suppress unused parameter warning
    stop_flag = 1;
    fprintf(stderr, "\nSignal received, stopping...\n");
}

// Function to handle errors and exit
void handle_error(const char *message) {
    perror(message);
    if (fd != -1) {
        close(fd);
    }
    if (buffer != NULL) {
        munmap(buffer, buffer_size);
    }
    exit(EXIT_FAILURE);
}

// Function to query device capabilities
int query_device_capabilities(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        handle_error("VIDIOC_QUERYCAP failed");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    printf("Device capabilities:\n");
    printf("  Driver: %s\n", cap.driver);
    printf("  Card: %s\n", cap.card);
    printf("  Bus info: %s\n", cap.bus_info);
    printf("  Version: %u.%u.%u\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("  Capabilities: %x\n", cap.capabilities);

    return 0;
}

// Function to set the video format
int set_video_format(int fd, int width, int height, enum v4l2_field field) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = field;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        handle_error("VIDIOC_S_FMT failed");
        return -1;
    }

    // Verify the format
    if (ioctl(fd, VIDIOC_G_FMT, &fmt) == -1) {
        handle_error("VIDIOC_G_FMT failed");
        return -1;
    }

    if (fmt.fmt.pix.width != width || fmt.fmt.pix.height != height || fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Error: Could not set the requested format\n");
        return -1;
    }

    printf("Video format set to:\n");
    printf("  Width: %d\n", fmt.fmt.pix.width);
    printf("  Height: %d\n", fmt.fmt.pix.height);
    printf("  Pixel format: %x\n", fmt.fmt.pix.pixelformat);
    printf("  Field: %d\n", fmt.fmt.pix.field);

    return 0;
}

// Function to request a buffer
int request_buffer(int fd, unsigned int *buffer_size) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Request only one buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        handle_error("VIDIOC_REQBUFS failed");
        return -1;
    }

    if (req.count != 1) {
        fprintf(stderr, "Error: Could not allocate requested buffer\n");
        return -1;
    }

    *buffer_size = req.count * sizeof(struct v4l2_buffer);

    return 0;
}

// Function to map the buffer
int map_buffer(int fd, void **buffer, size_t *buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        handle_error("VIDIOC_QUERYBUF failed");
        return -1;
    }

    *buffer_size = buf.length;
    *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*buffer == MAP_FAILED) {
        handle_error("mmap failed");
        return -1;
    }

    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        handle_error("VIDIOC_STREAMON failed");
        return -1;
    }
    return 0;
}

// Function to capture a frame
int capture_frame(int fd) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "select() interrupted by signal\n");
            return -1; // Indicate that the select was interrupted
        }
        handle_error("select() failed");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "select() timeout\n");
        return -1; // Indicate timeout
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        handle_error("VIDIOC_DQBUF failed");
        return -1;
    }

    return 0;
}

// Function to crop the image
void crop_image(const void *src, void *dst, int src_width, int src_height, int crop_width, int crop_height, int crop_x, int crop_y) {
    const unsigned char *src_ptr = (const unsigned char *)src + (crop_y * src_width * 2) + (crop_x * 2); // YUYV format
    unsigned char *dst_ptr = (unsigned char *)dst;

    for (int i = 0; i < crop_height; i++) {
        memcpy(dst_ptr + (i * crop_width * 2), src_ptr + (i * src_width * 2), crop_width * 2);
    }
}

// Function to write the cropped image to a file
int write_to_file(const void *data, size_t size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        handle_error("fopen failed");
        return -1;
    }

    size_t bytes_written = fwrite(data, 1, size, fp);
    if (bytes_written != size) {
        fprintf(stderr, "Error: fwrite wrote %zu bytes, expected %zu\n", bytes_written, size);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) == EOF) {
        handle_error("fclose failed");
        return -1;
    }

    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        handle_error("VIDIOC_STREAMOFF failed");
        return -1;
    }
    return 0;
}

// Function to unmap the buffer
int unmap_buffer(void *buffer, size_t buffer_size) {
    if (munmap(buffer, buffer_size) == -1) {
        handle_error("munmap failed");
        return -1;
    }
    return 0;
}

// Function to release the buffer
int release_buffer(int fd) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 0; // Release all buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        handle_error("VIDIOC_REQBUFS (release) failed");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal failed");
        return EXIT_FAILURE;
    }

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        handle_error("open failed");
        return EXIT_FAILURE;
    }

    // Query device capabilities
    if (query_device_capabilities(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the video format
    if (set_video_format(fd, WIDTH, HEIGHT, V4L2_FIELD_NONE) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Request a buffer
    if (request_buffer(fd, &buffer_size) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffer
    if (map_buffer(fd, &buffer, &buffer_size) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(fd) == -1) {
        unmap_buffer(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Capture a frame
    if (capture_frame(fd) == -1) {
        stop_streaming(fd);
        unmap_buffer(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Crop the image
    unsigned char *cropped_image = (unsigned char *)malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (cropped_image == NULL) {
        perror("malloc failed");
        stop_streaming(fd);
        unmap_buffer(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    crop_image(buffer, cropped_image, WIDTH, HEIGHT, CROP_WIDTH, CROP_HEIGHT, (WIDTH - CROP_WIDTH) / 2, (HEIGHT - CROP_HEIGHT) / 2);

    // Write the cropped image to a file
    if (write_to_file(cropped_image, CROP_WIDTH * CROP_HEIGHT * 2, OUTPUT_FILE) == -1) {
        free(cropped_image);
        stop_streaming(fd);
        unmap_buffer(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    // Clean up
    free(cropped_image);
    if (stop_streaming(fd) == -1) {
        unmap_buffer(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }
    if (unmap_buffer(buffer, buffer_size) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }
    if (release_buffer(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }
    close(fd);

    printf("Cropped image saved to %s\n", OUTPUT_FILE);

    return EXIT_SUCCESS;
}

