#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define OLED_ADDRESS 0x3C
#define FONT_WIDTH 5
#define FONT_HEIGHT 7
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Font data (5x7 bitmap font - example '0' and '1')
const unsigned char font[][5] = {
    {0x3E, 0x51, 0x49, 0x45, 0x3E}, // '0'
    {0x00, 0x42, 0x7F, 0x40, 0x00}  // '1'
};

// Function prototypes
int i2c_init(int bus, int address);
int i2c_write(int fd, unsigned char reg, unsigned char *data, int len);
int oled_init(int fd);
int oled_clear(int fd);
int oled_draw_pixel(int fd, int x, int y, int color);
int oled_draw_char(int fd, int x, int y, char c);
int oled_draw_string(int fd, int x, int y, char *str);
char* read_cpu_temp();
char* read_cpu_usage();
void signal_handler(int sig);

// I2C initialization function
int i2c_init(int bus, int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char reg, unsigned char *data, int len) {
    unsigned char buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(fd, buf, len + 1) != len + 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// OLED initialization function
int oled_init(int fd) {
    // Initialization sequence (SSD1306 datasheet)
    unsigned char init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100 fps)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting (0x14 = enable)
        0x20, 0x00, // Memory addressing mode (0x00 = horizontal)
        0xA1,       // Segment remap
        0xC8,       // COM scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Precharge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF (0xA4 = normal)
        0xA6,       // Normal/Inverse display (0xA6 = normal)
        0xAF        // Display on
    };
    if (i2c_write(fd, 0x00, init_commands, sizeof(init_commands)) < 0) {
        return -1;
    }
    return 0;
}

// OLED clear function
int oled_clear(int fd) {
    unsigned char buffer[1025]; // 128 bytes * 8 pages + 1 command byte
    buffer[0] = 0x40; // Data command
    memset(buffer + 1, 0x00, 1024); // Fill with 0 (black)
    if (i2c_write(fd, 0x40, buffer + 1, 1024) < 0) {
        return -1;
    }
    return 0;
}

// OLED draw pixel function
int oled_draw_pixel(int fd, int x, int y, int color) {
    if (x < 0 || x >= SCREEN_WIDTH || y < 0 || y >= SCREEN_HEIGHT) {
        return 0; // Out of bounds
    }

    int page = y / 8;
    int bit = y % 8;
    int byte_index = x + page * SCREEN_WIDTH;

    unsigned char buffer[2];
    buffer[0] = 0x40; // Data command
    buffer[1] = (1 << bit) & color;

    // Set the bit in the buffer
    unsigned char data[1];
    data[0] = (1 << bit) & color;

    // Calculate the correct address to write to
    unsigned char address[3];
    address[0] = 0x00; // Command
    address[1] = 0xB0 + page; // Set page address
    address[2] = 0x00 + (x & 0x0F); // Set lower column address
    address[3] = 0x10 + ((x >> 4) & 0x0F); // Set higher column address

    if (i2c_write(fd, 0x00, address + 1, 1) < 0) return -1; // Set page
    if (i2c_write(fd, 0x00, address + 2, 1) < 0) return -1; // Set lower column
    if (i2c_write(fd, 0x00, address + 3, 1) < 0) return -1; // Set higher column

    if (i2c_write(fd, 0x40, data, 1) < 0) {
        return -1;
    }

    return 0;
}

// OLED draw character function
int oled_draw_char(int fd, int x, int y, char c) {
    if (c < '0' || c > '1') return 0; // Only draw '0' and '1' for now
    c -= '0'; // Index into font array

    for (int i = 0; i < FONT_WIDTH; i++) {
        for (int j = 0; j < FONT_HEIGHT; j++) {
            if ((font[c][i] >> j) & 0x01) {
                oled_draw_pixel(fd, x + i, y + j, 1); // Draw pixel if bit is set
            }
        }
    }
    return 0;
}

// OLED draw string function
int oled_draw_string(int fd, int x, int y, char *str) {
    int current_x = x;
    while (*str) {
        oled_draw_char(fd, current_x, y, *str);
        current_x += FONT_WIDTH + 1; // Add space between characters
        str++;
    }
    return 0;
}

// Read CPU temperature function
char* read_cpu_temp() {
    int fd = open("/sys/class/thermal/thermal_zone0/temp", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening CPU temperature file: %s\n", strerror(errno));
        return "Error reading temp";
    }
    char buffer[10];
    if (read(fd, buffer, sizeof(buffer) - 1) < 0) {
        fprintf(stderr, "Error reading CPU temperature: %s\n", strerror(errno));
        close(fd);
        return "Error reading temp";
    }
    close(fd);
    buffer[sizeof(buffer) - 1] = 0; // Null-terminate
    int temp_milli_celsius = atoi(buffer);
    float temp_celsius = (float)temp_milli_celsius / 1000.0;
    char *result = malloc(20);
    if (result == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return "Memory error";
    }
    snprintf(result, 20, "Temp: %.1f C", temp_celsius);
    return result;
}

// Read CPU usage function
char* read_cpu_usage() {
    int fd = open("/proc/stat", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return "Error reading CPU";
    }
    char buffer[1024];
    if (read(fd, buffer, sizeof(buffer) - 1) < 0) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        close(fd);
        return "Error reading CPU";
    }
    close(fd);
    buffer[sizeof(buffer) - 1] = 0; // Null-terminate

    char *line = strstr(buffer, "cpu ");
    if (line == NULL) {
        return "Error parsing CPU";
    }
    line += 4; // Move past "cpu "

    unsigned long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (sscanf(line, "%lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        return "Error parsing CPU";
    }

    unsigned long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    fd = open("/proc/stat", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return "Error reading CPU";
    }
    if (read(fd, buffer, sizeof(buffer) - 1) < 0) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        close(fd);
        return "Error reading CPU";
    }
    close(fd);
    buffer[sizeof(buffer) - 1] = 0; // Null-terminate

    line = strstr(buffer, "cpu ");
    if (line == NULL) {
        return "Error parsing CPU";
    }
    line += 4; // Move past "cpu "

    if (sscanf(line, "%lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        return "Error parsing CPU";
    }

    unsigned long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long prev_idle_total = prev_idle + prev_iowait;
    unsigned long idle_total = idle + iowait;
    unsigned long totald = total - prev_total;
    unsigned long idled = idle_total - prev_idle_total;

    float cpu_usage = (float)(totald - idled) / totald * 100.0;

    char *result = malloc(20);
    if (result == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return "Memory error";
    }
    snprintf(result, 20, "CPU: %.1f%%", cpu_usage);
    return result;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, OLED_ADDRESS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize OLED
    if (oled_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read CPU temperature and usage
        char *temp_str = read_cpu_temp();
        char *cpu_str = read_cpu_usage();

        // Clear the display
        oled_clear(i2c_fd);

        // Draw the strings
        oled_draw_string(i2c_fd, 0, 0, temp_str);
        oled_draw_string(i2c_fd, 0, 10, cpu_str);

        // Free allocated memory
        free(temp_str);
        free(cpu_str);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    close(i2c_fd);

    return 0;
}

