    if (i2c_write(fd, 0x00, address + 1, 1) < 0) return -1; // Set page
    if (i2c_write(fd, 0x00, address + 2, 1) < 0) return -1; // Set lower column
    if (i2c_write(fd, 0x00, address + 3, 1) < 0) return -1; // Set higher column

    if (i2c_write(fd, 0x40, data, 1) < 0) {
        return -1;
    }

    return 0;
}

// OLED draw character function
int oled_draw_char(int fd, int x, int y, char c) {
    if (c < '0' || c > '1') return 0; // Only draw '0' and '1' for now
    c -= '0'; // Index into font array

    for (int i = 0; i < FONT_WIDTH; i++) {
        for (int j = 0; j < FONT_HEIGHT; j++) {
            if ((font[c][i] >> j) & 0x01) {
                oled_draw_pixel(fd, x + i, y + j, 1); // Draw pixel if bit is set
            }
        }
    }
    return 0;
}

// OLED draw string function
int oled_draw_string(int fd, int x, int y, char *str) {
    int current_x = x;
    while (*str) {
        oled_draw_char(fd, current_x, y, *str);
        current_x += FONT_WIDTH + 1; // Add space between characters
        str++;
    }
    return 0;
}

// Read CPU temperature function
char* read_cpu_temp() {
    int fd = open("/sys/class/thermal/thermal_zone0/temp", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening CPU temperature file: %s\n", strerror(errno));
        return "Error reading temp";
    }
    char buffer[10];
    if (read(fd, buffer, sizeof(buffer) - 1) < 0) {
        fprintf(stderr, "Error reading CPU temperature: %s\n", strerror(errno));
        close(fd);
        return "Error reading temp";
    }
    close(fd);
    buffer[sizeof(buffer) - 1] = 0; // Null-terminate
    int temp_milli_celsius = atoi(buffer);
    float temp_celsius = (float)temp_milli_celsius / 1000.0;
    char *result = malloc(20);
    if (result == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return "Memory error";
    }
    snprintf(result, 20, "Temp: %.1f C", temp_celsius);
    return result;
}

// Read CPU usage function
char* read_cpu_usage() {
    int fd = open("/proc/stat", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return "Error reading CPU";
    }
    char buffer[1024];
    if (read(fd, buffer, sizeof(buffer) - 1) < 0) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        close(fd);
        return "Error reading CPU";
    }
    close(fd);
    buffer[sizeof(buffer) - 1] = 0; // Null-terminate

    char *line = strstr(buffer, "cpu ");
    if (line == NULL) {
        return "Error parsing CPU";
    }
    line += 4; // Move past "cpu "

    unsigned long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (sscanf(line, "%lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        return "Error parsing CPU";
    }

    unsigned long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    fd = open("/proc/stat", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return "Error reading CPU";
    }
    if (read(fd, buffer, sizeof(buffer) - 1) < 0) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        close(fd);
        return "Error reading CPU";
    }
    close(fd);
    buffer[sizeof(buffer) - 1] = 0; // Null-terminate

    line = strstr(buffer, "cpu ");
    if (line == NULL) {
        return "Error parsing CPU";
    }
    line += 4; // Move past "cpu "

    if (sscanf(line, "%lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        return "Error parsing CPU";
    }

    unsigned long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long prev_idle_total = prev_idle + prev_iowait;
    unsigned long idle_total = idle + iowait;
    unsigned long totald = total - prev_total;
    unsigned long idled = idle_total - prev_idle_total;

    float cpu_usage = (float)(totald - idled) / totald * 100.0;

    char *result = malloc(20);
    if (result == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return "Memory error";
    }
    snprintf(result, 20, "CPU: %.1f%%", cpu_usage);
    return result;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, OLED_ADDRESS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize OLED
    if (oled_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read CPU temperature and usage
        char *temp_str = read_cpu_temp();
        char *cpu_str = read_cpu_usage();

        // Clear the display
        oled_clear(i2c_fd);

        // Draw the strings
        oled_draw_string(i2c_fd, 0, 0, temp_str);
        oled_draw_string(i2c_fd, 0, 10, cpu_str);

        // Free allocated memory
        free(temp_str);
        free(cpu_str);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    close(i2c_fd);

    return 0;
}

