#define LCD_ADDR 0x27 // Default I2C address of PCF8574 LCD backpack
#define PULSES_PER_LITER 450.0
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulses);
double calculate_volume(double flow_rate);
void lcd_init();
void lcd_clear();
void lcd_print(int row, int col, const char *text);
void lcd_update(double flow_rate, double total_volume);
void signal_handler(int signal);
void cleanup();

// Function to handle pulses from the flow sensor
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to calculate flow rate in liters per minute
double calculate_flow_rate(int pulses) {
    return (double)pulses / PULSES_PER_LITER * 60.0;
}

// Function to calculate total volume in liters
double calculate_volume(double flow_rate) {
    static double last_flow_rate = 0.0;
    static double accumulated_volume = 0.0;
    double time_interval = 1.0; // seconds
    accumulated_volume += flow_rate * time_interval / 60.0; // Convert L/min to L/s and accumulate
    last_flow_rate = flow_rate;
    return accumulated_volume;
}

// Function to initialize the LCD
void lcd_init() {
    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        exit(1);
    }

    // Initialize LCD (4-bit mode)
    gpioDelay(50); // Wait for LCD to power up
    i2cWriteByte(i2c_handle, 0x03); // Function set
    gpioDelay(5); // Wait
    i2cWriteByte(i2c_handle, 0x03); // Function set
    gpioDelay(1); // Wait
    i2cWriteByte(i2c_handle, 0x03); // Function set
    gpioDelay(1); // Wait
    i2cWriteByte(i2c_handle, 0x02); // Function set to 4-bit mode
    gpioDelay(1); // Wait

    i2cWriteByte(i2c_handle, 0x28); // Function set: 4-bit mode, 2 lines, 5x8 font
    gpioDelay(1); // Wait
    i2cWriteByte(i2c_handle, 0x08); // Display off
    gpioDelay(1); // Wait
    i2cWriteByte(i2c_handle, 0x01); // Clear display
    gpioDelay(2); // Wait
    i2cWriteByte(i2c_handle, 0x06); // Entry mode set: increment cursor, no shift
    gpioDelay(1); // Wait
    i2cWriteByte(i2c_handle, 0x0C); // Display on, cursor off, blink off
    gpioDelay(1); // Wait
}

// Function to clear the LCD
void lcd_clear() {
    i2cWriteByte(i2c_handle, 0x01); // Clear display
    gpioDelay(2); // Wait
}

// Function to print text to the LCD at a specific row and column
void lcd_print(int row, int col, const char *text) {
    int addr;
    if (row == 0) {
        addr = 0x80 + col; // First line
    } else {
        addr = 0xC0 + col; // Second line
    }

    i2cWriteByte(i2c_handle, addr); // Set cursor position
    for (int i = 0; text[i] != '\0'; i++) {
        i2cWriteByte(i2c_handle, text[i]);
    }
}

// Function to update the LCD with flow rate and total volume
void lcd_update(double flow_rate, double total_volume) {
    char flow_str[17];
    char volume_str[17];

    snprintf(flow_str, sizeof(flow_str), "Flow: %.2f L/min", flow_rate);
    snprintf(volume_str, sizeof(volume_str), "Volume: %.2f L", total_volume);

    lcd_clear();
    lcd_print(0, 0, flow_str);
    lcd_print(1, 0, volume_str);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up interrupt handler for rising edge detection
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_lcd_update = time(NULL);

    // Main loop
    while (!terminate) {
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next second

        double flow_rate = calculate_flow_rate(current_pulse_count);
        total_volume = calculate_volume(flow_rate);

        printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);

        time_t current_time = time(NULL);
        if (difftime(current_time, last_lcd_update) >= 10.0) {
            lcd_update(flow_rate, total_volume);
            last_lcd_update = current_time;
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

