#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <wiringPiI2C.h>

// Constants
#define ANEMOMETER_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define I2C_ADDR 0x27      // PCF8574 I2C address
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500
#define WIND_SPEED_SCALE 2.4 // m/s per pulse (example value, adjust as needed)
#define WIND_DIRECTION_MIN_ADC 50  // Minimum ADC value for wind direction
#define WIND_DIRECTION_MAX_ADC 950 // Maximum ADC value for wind direction

// Global variables
volatile int pulse_count = 0;
int spi_fd = -1;
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void anemometer_interrupt(void);
float calculate_wind_speed(int pulse_count, float sample_time_s);
int read_wind_direction(void);
char *convert_wind_direction_to_string(int adc_value);
int lcd_init(int i2c_fd);
int lcd_clear(int i2c_fd);
int lcd_set_cursor(int i2c_fd, int row, int col);
int lcd_write_string(int i2c_fd, const char *string);
void signal_handler(int signal);
int safe_spi_transfer(int channel, unsigned char *data, int len);
int safe_i2c_read(int fd, int reg);
int safe_i2c_write(int fd, int reg, int val);

// Anemometer interrupt handler
void anemometer_interrupt(void) {
    pulse_count++;
}

// Calculate wind speed in m/s
float calculate_wind_speed(int pulse_count, float sample_time_s) {
    return (float)pulse_count / sample_time_s * WIND_SPEED_SCALE;
}

// Read wind direction from MCP3008 ADC
int read_wind_direction(void) {
    unsigned char data[3];
    int adc_value;

    data[0] = 0x01;                           // Start bit
    data[1] = (0x08 | SPI_CHANNEL) << 4; // Single-ended mode, channel selection
    data[2] = 0x00;                           // Don't care

    if (safe_spi_transfer(SPI_CHANNEL, data, 3) < 0) {
        fprintf(stderr, "Error: SPI transfer failed in read_wind_direction\n");
        return -1; // Indicate error
    }

    adc_value = ((data[1] & 0x03) << 8) + data[2];

    // Validate ADC value
    if (adc_value <= WIND_DIRECTION_MIN_ADC || adc_value >= WIND_DIRECTION_MAX_ADC) {
        fprintf(stderr, "Warning: ADC value out of range: %d\n", adc_value);
        return -1; // Indicate error
    }

    return adc_value;
}

// Convert ADC value to wind direction string
char *convert_wind_direction_to_string(int adc_value) {
    static char direction[10]; // Static buffer to hold the direction string

    if (adc_value < 0) {
        strcpy(direction, "Err");
        return direction;
    }

    // Linear mapping from ADC value to wind direction (example)
    float angle = (float)(adc_value - WIND_DIRECTION_MIN_ADC) / (WIND_DIRECTION_MAX_ADC - WIND_DIRECTION_MIN_ADC) * 360.0;

    if (angle >= 337.5 || angle < 22.5) {
        strcpy(direction, "N");
    } else if (angle >= 22.5 && angle < 67.5) {
        strcpy(direction, "NE");
    } else if (angle >= 67.5 && angle < 112.5) {
        strcpy(direction, "E");
    } else if (angle >= 112.5 && angle < 157.5) {
        strcpy(direction, "SE");
    } else if (angle >= 157.5 && angle < 202.5) {
        strcpy(direction, "S");
    } else if (angle >= 202.5 && angle < 247.5) {
        strcpy(direction, "SW");
    } else if (angle >= 247.5 && angle < 292.5) {
        strcpy(direction, "W");
    } else {
        strcpy(direction, "NW");
    }

    return direction;
}

// LCD initialization (PCF8574 backpack)
int lcd_init(int i2c_fd) {
    // Initialization sequence (adjust based on your LCD and backpack)
    safe_i2c_write(i2c_fd, 0, 0x00); // Clear display
    delay(2);                           // Wait for > 1.53 ms
    safe_i2c_write(i2c_fd, 0, 0x00); // Clear display
    delay(1);                           // Wait for > 4.1 ms
    safe_i2c_write(i2c_fd, 0, 0x00); // Clear display
    delay(1);                           // Wait for > 4.1 ms
    safe_i2c_write(i2c_fd, 0, 0x08); // Function set: 4-bit mode, 2 lines, 5x8 font
    safe_i2c_write(i2c_fd, 0, 0x0C); // Display control: Display on, cursor off, blink off
    safe_i2c_write(i2c_fd, 0, 0x06); // Entry mode set: Increment cursor, no shift
    lcd_clear(i2c_fd);
    return 0;
}

// Clear LCD display
int lcd_clear(int i2c_fd) {
    safe_i2c_write(i2c_fd, 0, 0x01); // Clear display command
    delay(2);                           // Wait for > 1.53 ms
    return 0;
}

// Set LCD cursor position
int lcd_set_cursor(int i2c_fd, int row, int col) {
    int addr;
    if (row == 0) {
        addr = 0x00 + col;
    } else {
        addr = 0x40 + col;
    }
    safe_i2c_write(i2c_fd, 0, 0x80 | addr); // Set DDRAM address
    return 0;
}

// Write string to LCD
int lcd_write_string(int i2c_fd, const char *string) {
    int i;
    for (i = 0; string[i] != 0; i++) {
        safe_i2c_write(i2c_fd, 0, 0x40 | string[i]); // Write data to DDRAM
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);
}

// Safe SPI transfer with error handling
int safe_spi_transfer(int channel, unsigned char *data, int len) {
    int result = wiringPiSPIDataRW(channel, data, len);
    if (result < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
