float calculate_wind_speed(int pulse_count, float sample_time_s) {
    return (float)pulse_count / sample_time_s * WIND_SPEED_SCALE;
}

// Read wind direction from MCP3008 ADC
int read_wind_direction(void) {
    unsigned char data[3];
    int adc_value;

    data[0] = 0x01;                           // Start bit
    data[1] = (0x08 | SPI_CHANNEL) << 4; // Single-ended mode, channel selection
    data[2] = 0x00;                           // Don't care

    if (safe_spi_transfer(SPI_CHANNEL, data, 3) < 0) {
        fprintf(stderr, "Error: SPI transfer failed in read_wind_direction\n");
        return -1; // Indicate error
    }

    adc_value = ((data[1] & 0x03) << 8) + data[2];

    // Validate ADC value
    if (adc_value <= WIND_DIRECTION_MIN_ADC || adc_value >= WIND_DIRECTION_MAX_ADC) {
        fprintf(stderr, "Warning: ADC value out of range: %d\n", adc_value);
        return -1; // Indicate error
    }

    return adc_value;
