char *convert_wind_direction_to_string(int adc_value) {
    static char direction[10]; // Static buffer to hold the direction string

    if (adc_value < 0) {
        strcpy(direction, "Err");
        return direction;
    }

    // Linear mapping from ADC value to wind direction (example)
    float angle = (float)(adc_value - WIND_DIRECTION_MIN_ADC) / (WIND_DIRECTION_MAX_ADC - WIND_DIRECTION_MIN_ADC) * 360.0;

    if (angle >= 337.5 || angle < 22.5) {
        strcpy(direction, "N");
    } else if (angle >= 22.5 && angle < 67.5) {
        strcpy(direction, "NE");
    } else if (angle >= 67.5 && angle < 112.5) {
        strcpy(direction, "E");
    } else if (angle >= 112.5 && angle < 157.5) {
        strcpy(direction, "SE");
    } else if (angle >= 157.5 && angle < 202.5) {
        strcpy(direction, "S");
    } else if (angle >= 202.5 && angle < 247.5) {
        strcpy(direction, "SW");
    } else if (angle >= 247.5 && angle < 292.5) {
        strcpy(direction, "W");
    } else {
