#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27 // Default I2C address of LCD1602
#define PULSES_PER_LITER 450.0 // YF-S201 calibration value
#define NO_PULSE_TIMEOUT 5 // Seconds

// Global variables
volatile int pulse_count = 0;
int lcd_fd;
FILE *log_file;
int running = 1;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
float calculate_flow_rate(int pulses);
void display_flow_rate(float flow_rate);
void log_flow_rate(float flow_rate);
void signal_handler(int signal);
int lcd_init();
void lcd_send_command(int command);
void lcd_send_data(int data);
void lcd_string(const char *str);
void lcd_clear();

// Callback function for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge
    {
        pulse_count++;
    }
}

// Function to calculate flow rate in L/min
float calculate_flow_rate(int pulses)
{
    return (float)pulses / PULSES_PER_LITER * 60.0;
}

// Function to display flow rate on LCD
void display_flow_rate(float flow_rate)
{
    char buffer[20];
    lcd_clear();
    lcd_string("Flow Rate:");
    sprintf(buffer, "%.2f L/min", flow_rate);
    lcd_send_command(0xC0); // Move cursor to the second line
    lcd_string(buffer);
}

// Function to log flow rate to file
void log_flow_rate(float flow_rate)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow Rate: %.2f L/min\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    gpioTerminate();
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    exit(0);
}

// LCD initialization function
int lcd_init()
{
    lcd_fd = wiringPiI2CSetup(LCD_ADDR);
    if (lcd_fd == -1)
    {
        fprintf(stderr, "Error initializing I2C LCD. Check address and bus.\n");
        return -1;
    }

    // Initialization sequence (adjust as needed for your LCD)
    lcd_send_command(0x33); // Initialize
    lcd_send_command(0x32); // Initialize
    lcd_send_command(0x06); // Cursor move direction
    lcd_send_command(0x0C); // Display On,Cursor Off, Blink Off
    lcd_send_command(0x28); // Data length, number of lines, font size
    lcd_send_command(0x01); // Clear display
    gpioDelay(2000);        // Wait for clear display to complete
    return 0;
}

// Function to send a command to the LCD
void lcd_send_command(int command)
{
    int upper = command & 0xF0;
    int lower = (command << 4) & 0xF0;

    wiringPiI2CWriteReg8(lcd_fd, 0, upper | 0x04 | 0x08); // Enable pulse
    wiringPiI2CWriteReg8(lcd_fd, 0, upper | 0x08);       // Disable pulse
    wiringPiI2CWriteReg8(lcd_fd, 0, lower | 0x04 | 0x08); // Enable pulse
    wiringPiI2CWriteReg8(lcd_fd, 0, lower | 0x08);       // Disable pulse
}

// Function to send data to the LCD
void lcd_send_data(int data)
{
    int upper = (data & 0xF0);
    int lower = ((data << 4) & 0xF0);

    wiringPiI2CWriteReg8(lcd_fd, 0, upper | 0x05 | 0x08); // Enable pulse, RS = 1
    wiringPiI2CWriteReg8(lcd_fd, 0, upper | 0x01 | 0x08);       // Disable pulse
    wiringPiI2CWriteReg8(lcd_fd, 0, lower | 0x05 | 0x08); // Enable pulse, RS = 1
    wiringPiI2CWriteReg8(lcd_fd, 0, lower | 0x01 | 0x08);       // Disable pulse
}

// Function to send a string to the LCD
void lcd_string(const char *str)
{
    while (*str)
    {
        lcd_send_data(*str++);
    }
}

// Function to clear the LCD
void lcd_clear()
{
    lcd_send_command(0x01); // Clear display command
    gpioDelay(2000);        // Wait for clear display to complete
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up interrupt callback for rising edge detection
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL) != 0)
    {
        fprintf(stderr, "Error setting up interrupt callback\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0)
    {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_pulse_time = time(NULL);
    int no_pulse_count = 0;

    // Main loop
    while (running)
    {
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next second

        float flow_rate = calculate_flow_rate(current_pulse_count);
        display_flow_rate(flow_rate);
        log_flow_rate(flow_rate);

        time_t current_time = time(NULL);
        if (current_pulse_count == 0)
        {
            no_pulse_count++;
            if (no_pulse_count >= NO_PULSE_TIMEOUT)
            {
                fprintf(stderr, "Warning: No pulses detected for %d seconds. Check sensor connection.\n", NO_PULSE_TIMEOUT);
                lcd_clear();
                lcd_string("No Pulse");
                lcd_send_command(0xC0);
                lcd_string("Check Sensor");
                no_pulse_count = NO_PULSE_TIMEOUT; // Prevent repeated warnings
            }
        } else {
            no_pulse_count = 0; // Reset the counter if pulses are detected
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    fclose(log_file);

    return 0;
}

