    for (int row = 0; row < num_pins; row++) {
        // Set row pin HIGH (common anode)
        if (gpio_set_value(row_pins[row], 1) != 0) {
            fprintf(stderr, "Error setting row %d HIGH\n", row_pins[row]);
            return;
        }

        for (int col = 0; col < num_pins; col++) {
