    for (int row = 0; row < num_pins; row++) {
        for (int col = 0; col < num_pins; col++) {
            // Calculate the LED state based on the frame and column
            if ((col + frame) % num_pins == row) {
                // Turn on the LED
                if (gpio_set_value(col_pins[col], 0) != 0) {
