#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows and columns
const int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};
const int num_pins = 8;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio(int pin, int state)
{
    int result = gpioWrite(pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", pin, result);
        return -1;
    }
    return 0;
}

// Function to clear the LED matrix (set all columns HIGH and rows LOW)
void clear_matrix()
{
    for (int i = 0; i < num_pins; i++) {
        if (set_gpio(col_pins[i], 1) != 0) return; // Error handling
        if (set_gpio(row_pins[i], 0) != 0) return; // Error handling
    }
}

// Function to display a column of the wave
void display_column(int col_index, int wave_height)
{
    // Clear the matrix first
    clear_matrix();

    // Set the column cathode LOW
    if (set_gpio(col_pins[col_index], 0) != 0) return; // Error handling

    // Light up the LEDs in the column up to the wave height
    for (int i = 0; i < wave_height; i++) {
        if (set_gpio(row_pins[i], 1) != 0) return; // Error handling
    }
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO pins as output
    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting row pin %d as output\n", row_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetMode(col_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting column pin %d as output\n", col_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Wave animation loop
    int wave_height = 0;
    int direction = 1; // 1 for increasing, -1 for decreasing

    while (!terminate) {
        for (int col = 0; col < num_pins; col++) {
            display_column(col, wave_height);
            gpioDelay(150); // Delay for 150ms
        }

        // Update wave height
        wave_height += direction;
        if (wave_height >= num_pins) {
            wave_height = num_pins - 2;
            direction = -1;
        } else if (wave_height < 0) {
            wave_height = 1;
            direction = 1;
        }
    }

    // Clean up GPIO pins before exiting
    clear_matrix();
    gpioTerminate();

    return 0;
}

