            return 1;
        }
    }

    // Wave animation loop
    int wave_height = 0;
    int direction = 1; // 1 for increasing, -1 for decreasing

    while (!terminate) {
        for (int col = 0; col < num_pins; col++) {
            display_column(col, wave_height);
            gpioDelay(150); // Delay for 150ms
        }

        // Update wave height
        wave_height += direction;
        if (wave_height >= num_pins) {
            wave_height = num_pins - 2;
            direction = -1;
        } else if (wave_height < 0) {
            wave_height = 1;
            direction = 1;
        }
    }

    // Clean up GPIO pins before exiting
    clear_matrix();
    gpioTerminate();

    return 0;
}

