#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX75031_ADDR 0x4A
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILE "depth_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration (example)
typedef struct {
    uint8_t config_reg1;
    uint8_t config_reg2;
} sensor_config_t;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_distance(int i2c_handle);
int log_data(FILE *log_file, int distance);
void signal_handler(int signal);
int reopen_i2c(int i2c_handle);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the MLX75031 sensor
int initialize_sensor(int i2c_handle) {
    // Example configuration (replace with actual initialization sequence)
    uint8_t init_data[] = {0x00, 0x01}; // Example register and value
    int result = i2cWriteDevice(i2c_handle, (char *)init_data, sizeof(init_data));
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read distance data from the MLX75031 sensor
int read_distance(int i2c_handle) {
    uint8_t command = 0x01; // Example command to trigger a reading
    uint8_t buffer[2]; // Example buffer to store the distance data
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)&command, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Small delay for the sensor to process the command

    result = i2cReadDevice(i2c_handle, (char *)buffer, sizeof(buffer));
    if (result != sizeof(buffer)) {
        fprintf(stderr, "Error reading from sensor: %d\n", result);
        return -1;
    }

    // Convert the raw data to distance (example)
    int distance = (buffer[0] << 8) | buffer[1];

    return distance;
}

// Function to log data to the CSV file
int log_data(FILE *log_file, int distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to reopen the I2C connection
int reopen_i2c(int i2c_handle) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error reopening I2C: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, attempting to reopen I2C...\n");
            log_data(log_file, -1); // Log error
            i2c_handle = reopen_i2c(i2c_handle);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reopen I2C, exiting...\n");
                break; // Exit loop if reopening fails
            }
            gpioDelay(SAMPLE_INTERVAL_MS); // Wait before retrying
            continue; // Skip logging and delay
        }

        log_data(log_file, distance);
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

