// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Define log file name
#define LOG_FILE "proximity.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor();
void blink_led();
void log_detection();
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Structure to hold GPIO configuration
typedef struct {
    int sensor_pin;
    int led_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(100);       // Wait 100ms
    gpioWrite(LED_PIN, 0); // Turn LED off
}

// Function to log the detection event
void log_detection() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Object detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    int last_state = 1; // Assume initial state is HIGH

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = read_sensor();

        if (current_state == 0 && last_state == 1) {
            // Falling edge detected
            log_detection();
            blink_led();
        }

        last_state = current_state;
        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit
    fclose(log_file);
    cleanup_gpio();

    printf("Exiting.\n");
    return 0;
}

