// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x24

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_read_register(int handle, uint8_t reg);
int si1145_write_register(int handle, uint8_t reg, uint8_t value);
int si1145_init(int handle);
int si1145_read_proximity(int handle);
int si1145_read_ambient_light(int handle);
void log_data(FILE *fp, int proximity, int ambient_light);
void signal_handler(int signal);

// Function to read a single byte from a Si1145 register
int si1145_read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to a Si1145 register
int si1145_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

