#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 30000       // Timeout in microseconds (30ms)
#define MIN_DISTANCE 2.0       // Minimum valid distance in cm
#define MAX_DISTANCE 400.0     // Maximum valid distance in cm
#define WATERING_THRESHOLD 15.0 // Distance threshold for watering in cm
#define LOG_INTERVAL_S 60       // Logging interval in seconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
long long measure_pulse_width();
double calculate_distance(long long pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long long measure_pulse_width() {
    long long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pin did not rise within timeout.\n");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pin did not fall within timeout.\n");
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF + 1; // Handle tick rollover
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
double calculate_distance(long long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log the distance to a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }

    if (distance >= 0 && distance < WATERING_THRESHOLD) {
        fprintf(log_file, "%s, Time to water the plant!\n", timestamp);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    return 0; // Indicate success
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        cleanup_gpio();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        long long pulse_width = measure_pulse_width();
        double distance = calculate_distance(pulse_width);

        if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
            log_distance(distance);
        } else if (distance < 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
            fprintf(log_file, "%s, Error: Invalid distance reading or timeout.\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(LOG_INTERVAL_S * 1000); // Wait for the logging interval
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("Program terminated.\n");
    return 0;
}

