    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read proximity data from the sensor
int read_proximity_data(int *prox_data) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PROX_DATA_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }
    *prox_data = (buf[1] << 8) | buf[0]; // Assuming big-endian
    return 0;
}

// Function to calculate BPM (replace with actual algorithm)
float calculate_bpm(int prox_data) {
