// I2C read byte function
int i2c_read_byte(int fd, uint8_t reg) {
  uint8_t buf[1];
  buf[0] = reg;

  if (write(fd, buf, 1) != 1) {
    perror("Failed to write register address");
    return -1;
  }

  if (read(fd, buf, 1) != 1) {
    perror("Failed to read byte");
    return -1;
  }

  return buf[0];
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = data;

  if (write(fd, buf, 2) != 2) {
    perror("Failed to write byte");
    return -1;
  }

  return 0;
}

