// VL53L0X start ranging function
int vl53l0x_start_ranging(int fd) {
  if (i2c_write_byte(fd, VL53L0X_REG_SYSTEM_START, 0x01) < 0) {
    fprintf(stderr, "Error starting ranging\n");
    return -1;
  }
  return 0;
}

// VL53L0X read distance function
int vl53l0x_read_distance(int fd) {
  int distance = -1;
  int timeout_count = 0;
  int range_status;

  // Start a new measurement
  if (i2c_write_byte(fd, VL53L0X_REG_SYSRANGE_START, 0x01) < 0) {
    fprintf(stderr, "Error starting measurement\n");
    return -1;
  }

  // Wait for interrupt (polling)
  while (1) {
    int interrupt_status = i2c_read_byte(fd, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
    if (interrupt_status < 0) {
      fprintf(stderr, "Error reading interrupt status\n");
      return -1;
    }

    if (interrupt_status & 0x07) {
      break;
    }

    usleep(10000); // 10ms
    timeout_count++;
    if (timeout_count > 100) {
      fprintf(stderr, "Timeout waiting for interrupt\n");
      return -1;
    }
  }

  // Read range status
  range_status = i2c_read_byte(fd, VL53L0X_REG_RESULT_RANGE_STATUS);
  if (range_status < 0) {
    fprintf(stderr, "Error reading range status\n");
    return -1;
  }

  // Read distance
  int distance_msb = i2c_read_byte(fd, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
  if (distance_msb < 0) {
    fprintf(stderr, "Error reading distance MSB\n");
    return -1;
  }

  int distance_lsb = i2c_read_byte(fd, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);
  if (distance_lsb < 0) {
    fprintf(stderr, "Error reading distance LSB\n");
    return -1;
  }

  distance = (distance_msb << 8) | distance_lsb;

  // Clear interrupt
  if (i2c_write_byte(fd, VL53L0X_REG_RESULT_INTERRUPT_STATUS, 0x07) < 0) {
    fprintf(stderr, "Error clearing interrupt\n");
    return -1;
  }

  return distance;
}

// Interrupt handler function
void interrupt_handler(void) {
  int distance;
  time_t rawtime;
  struct tm *timeinfo;
  char timestamp[20];

  // Read distance
  distance = vl53l0x_read_distance(i2c_fd);
  if (distance < 0) {
    fprintf(stderr, "Error reading distance in interrupt handler\n");
    return;
  }

  // Get timestamp
  time(&rawtime);
  timeinfo = localtime(&rawtime);
  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

  // Log distance to file
  fprintf(log_file, "%s,%d\n", timestamp, distance);
  fflush(log_file);

  printf("Distance: %d mm\n", distance);
}

// Signal handler function
void signal_handler(int signal) {
  printf("Caught signal %d, exiting gracefully...\n", signal);
  program_running = 0;

  // Close I2C device
  if (i2c_fd != -1) {
    close(i2c_fd);
  }

  // Close log file
  if (log_file != NULL) {
    fclose(log_file);
  }

  exit(0);
}

int main() {
  // Initialize WiringPi
  if (wiringPiSetupGpio() == -1) {
    fprintf(stderr, "WiringPi initialization failed\n");
    return 1;
  }

  // Set GPIO pin as input with pull-up resistor
  pinMode(GPIO_PIN, INPUT);
  pullUpDnControl(GPIO_PIN, PUD_UP);

  // Open I2C device
  char i2c_device[20];
  snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
  i2c_fd = open(i2c_device, O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C device");
    return 1;
  }

  // Set I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
    return 1;
  }

  // Initialize VL53L0X sensor
  if (vl53l0x_init(i2c_fd) < 0) {
    fprintf(stderr, "VL53L0X initialization failed\n");
    close(i2c_fd);
    return 1;
  }

  // Start ranging
  if (vl53l0x_start_ranging(i2c_fd) < 0) {
    fprintf(stderr, "VL53L0X start ranging failed\n");
    close(i2c_fd);
    return 1;
  }

  // Open log file
  log_file = fopen("distance_log.txt", "a");
  if (log_file == NULL) {
    perror("Failed to open log file");
    close(i2c_fd);
    return 1;
  }

  // Set up signal handler for Ctrl+C
  signal(SIGINT, signal_handler);

  // Set up interrupt handler
  if (wiringPiISR(GPIO_PIN, INT_EDGE_FALLING, interrupt_handler) < 0) {
    fprintf(stderr, "Unable to setup ISR\n");
    fclose(log_file);
    close(i2c_fd);
    return 1;
  }

  printf("VL53L0X distance measurement started. Press Ctrl+C to exit.\n");

  // Main loop
  while (program_running) {
    pause(); // Wait for signals
  }

  return 0;
}

