#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

// Define the log file name
#define LOG_FILE "obstacle_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the sensor data to a file
void log_data(int sensor1_value, int sensor2_value, char* timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_value, sensor2_value);
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        // Get the current timestamp
        char* timestamp = get_timestamp();
        if (timestamp == NULL) {
            continue; // Skip logging if timestamp allocation failed
        }

        // Log the data if sensor readings were successful
        if (sensor1_value != -1 && sensor2_value != -1) {
            log_data(sensor1_value, sensor2_value, timestamp);
        }

        free(timestamp); // Free the allocated memory for the timestamp

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

