#define ICU20201_ADDR 0x6A // Default I2C address
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20.0 // cm
#define SAMPLE_INTERVAL_MS 100

// ICU-20201 Register Addresses (Example - Refer to datasheet for correct values)
#define ICU20201_REG_WHO_AM_I 0x0F
#define ICU20201_REG_DISTANCE_HIGH 0x51
#define ICU20201_REG_DISTANCE_LOW 0x52
#define ICU20201_REG_CONFIG 0x00 // Example config register

// Global variables
