    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Sensor initialization function
int init_sensor() {
    // Example: Check WHO_AM_I register (replace with actual register and value)
    char buf[1];
    buf[0] = ICU20201_REG_WHO_AM_I;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to WHO_AM_I register\n");
        return -1;
    }
    gpioDelay(1000); // Small delay after write

    char read_buf[1];
    if (i2cReadDevice(i2c_handle, read_buf, 1) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    // Add more initialization steps here based on the ICU-20201 datasheet
    // For example, writing configuration registers

    return 0;
}

// Function to read distance from the sensor
float read_distance() {
    char high_byte_buf[1];
    char low_byte_buf[1];
    char distance_high_reg = ICU20201_REG_DISTANCE_HIGH;
    char distance_low_reg = ICU20201_REG_DISTANCE_LOW;
    uint16_t distance_raw;
    float distance_cm;

    // Write register address for high byte
    if (i2cWriteDevice(i2c_handle, &distance_high_reg, 1) != 0) {
        fprintf(stderr, "Error writing to distance high register\n");
        return -1.0;
    }
    gpioDelay(1000); // Small delay after write

    // Read high byte
    if (i2cReadDevice(i2c_handle, high_byte_buf, 1) != 1) {
        fprintf(stderr, "Error reading distance high byte\n");
        return -1.0;
    }

    // Write register address for low byte
    if (i2cWriteDevice(i2c_handle, &distance_low_reg, 1) != 0) {
        fprintf(stderr, "Error writing to distance low register\n");
        return -1.0;
    }
    gpioDelay(1000); // Small delay after write

    // Read low byte
    if (i2cReadDevice(i2c_handle, low_byte_buf, 1) != 1) {
        fprintf(stderr, "Error reading distance low byte\n");
        return -1.0;
    }

    distance_raw = (high_byte_buf[0] << 8) | low_byte_buf[0];

    // Convert raw data to distance in centimeters (replace with actual conversion formula)
    distance_cm = (float)distance_raw * 0.1; // Example conversion

    return distance_cm;
}

// Function to control the LED
void control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Function to log the distance to a file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Set GPIO back to input mode
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    printf("Starting distance measurement...\n");

    // Main loop
    while (!terminate) {
        float distance = read_distance();
        if (distance >= 0) {
            control_led(distance);
            log_distance(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

