#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x08
#define ALS_REG 0x0A
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, int *proximity, int *als);
int log_data(FILE *log_file, int proximity, int als);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data with retries
int read_sensor_data(int i2c_handle, int *proximity, int *als) {
    int retries = RETRY_COUNT;
    int status;

    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, PROXIMITY_REG);
        if (status >= 0) {
            *proximity = status;
            break;
        } else {
            fprintf(stderr, "Error reading proximity data: %d, retries remaining: %d\n", status, retries);
            retries--;
            gpioDelay(10); // Small delay before retrying
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read proximity data after multiple retries.\n");
        return -1;
    }

    retries = RETRY_COUNT;
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, ALS_REG);
        if (status >= 0) {
            *als = status;
            break;
        } else {
            fprintf(stderr, "Error reading ALS data: %d, retries remaining: %d\n", status, retries);
            retries--;
            gpioDelay(10); // Small delay before retrying
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(FILE *log_file, int proximity, int als) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Proximity: %d, ALS: %d\n", timestamp, proximity, als) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    int proximity, als;

    // Initialize pigpio
