#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A // Default I2C address
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0x41
#define DISTANCE_REG 0x00 // Example register address for distance
#define DISTANCE_HIGH_REG 0x01 // Example register address for distance high byte
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100 // mm

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int distance_threshold;
} sensor_config_t;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_distance(int i2c_handle);
void control_led(int gpio_pin, int state);
void log_data(FILE *log_file, int distance);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[], sensor_config_t *config);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to initialize the sensor
int initialize_sensor(int i2c_handle) {
    int who_am_i;

    // Verify WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    printf("Sensor initialized successfully. WHO_AM_I: 0x%02X\n", who_am_i);
    return 0;
}

// Function to read distance from the sensor
int read_distance(int i2c_handle) {
    int distance_low, distance_high;
    int distance;

    distance_low = i2cReadByteData(i2c_handle, DISTANCE_REG);
    if (distance_low < 0) {
        fprintf(stderr, "Error reading distance low byte: %d\n", distance_low);
        return -1;
    }

    distance_high = i2cReadByteData(i2c_handle, DISTANCE_HIGH_REG);
    if (distance_high < 0) {
        fprintf(stderr, "Error reading distance high byte: %d\n", distance_high);
        return -1;
    }

    distance = (distance_high << 8) | distance_low; // Combine high and low bytes

    return distance;
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to a file
void log_data(FILE *log_file, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[], sensor_config_t *config) {
    if (argc > 1) {
        config->distance_threshold = atoi(argv[1]);
        if (config->distance_threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default threshold: %d mm\n", DEFAULT_THRESHOLD);
            config->distance_threshold = DEFAULT_THRESHOLD;
        }
    } else {
        config->distance_threshold = DEFAULT_THRESHOLD;
    }

    config->i2c_address = ICU20201_ADDR; // Default I2C address

    return 0;
}

int main(int argc, char *argv[]) {
    sensor_config_t sensor_config;

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &sensor_config) != 0) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, sensor_config.i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("tof_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            log_data(log_file, distance);

            if (distance < sensor_config.distance_threshold) {
                control_led(LED_GPIO, 1); // Turn LED on
            } else {
                control_led(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(50); // 50 ms polling interval
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioSetMode(LED_GPIO, PI_INPUT); // Reset GPIO mode
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

