float calculate_average_distance(uint16_t *distances, int num_samples);
int log_intrusion(float average_distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    uint8_t command[] = MEASUREMENT_COMMAND;
    int result = i2cWriteDevice(i2c_handle, (char *)command, sizeof(command));
    if (result != sizeof(command)) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 15);
    if (result != 15) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Verify header
int verify_header(uint8_t *data) {
    if (data[0] != HEADER_VALUE) {
        fprintf(stderr, "Error: Invalid header value (0x%02X, expected 0x%02X)\n", data[0], HEADER_VALUE);
        return -1;
    }
    return 0;
}

// Extract distance
uint16_t extract_distance(uint8_t *data) {
    return (uint16_t)((data[11] << 8) | data[12]);
}

// Calculate average distance
float calculate_average_distance(uint16_t *distances, int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return sum / num_samples;
}

// Log intrusion
int log_intrusion(float average_distance) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s, Average Distance: %.2f mm\n", buf, average_distance);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint16_t distances[NUM_SAMPLES];
    uint8_t sensor_data[15];

    printf("Starting intrusion detection...\n");

    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        gpioDelay(10); // Wait 10ms

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Verify header
        if (verify_header(sensor_data) != 0) {
            fprintf(stderr, "Error verifying header, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Extract distance
        distances[0] = extract_distance(sensor_data);

        // Take additional samples
        for (int i = 1; i < NUM_SAMPLES; i++) {
            gpioDelay(SAMPLE_DELAY_MS);
            if (send_measurement_command() != 0) {
                fprintf(stderr, "Error sending measurement command during sampling, skipping sample.\n");
                distances[i] = 0; // Assign a default value
                continue;
            }
            gpioDelay(10);
            if (read_sensor_data(sensor_data) != 0) {
                fprintf(stderr, "Error reading sensor data during sampling, skipping sample.\n");
                distances[i] = 0; // Assign a default value
                continue;
            }
            if (verify_header(sensor_data) != 0) {
                fprintf(stderr, "Error verifying header during sampling, skipping sample.\n");
                distances[i] = 0; // Assign a default value
                continue;
            }
            distances[i] = extract_distance(sensor_data);
        }

        // Calculate average distance
        float average_distance = calculate_average_distance(distances, NUM_SAMPLES);

        // Check for intrusion
        if (average_distance < INTRUSION_THRESHOLD_MM) {
            printf("Intrusion detected! Average distance: %.2f mm\n", average_distance);
            if (log_intrusion(average_distance) != 0) {
                fprintf(stderr, "Error logging intrusion.\n");
            }
        } else {
            printf("No intrusion detected. Average distance: %.2f mm\n", average_distance);
        }

        gpioDelay(1000); // Delay between cycles
    }

    // Cleanup
    cleanup();

    printf("Program terminated.\n");
    return 0;
}

