        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read the proximity data from the sensor
        int prox_data = i2cReadWordData(i2c_handle, SI1182_PROX_DATA_REG);
        if (prox_data < 0) {
            fprintf(stderr, "Failed to read proximity data: %d\n", prox_data);
            // Attempt to re-initialize the I2C connection
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C device: %d\n", i2c_handle);
                // If re-initialization fails, exit the program
                gpioTerminate();
                return 1;
