            // Wait before retrying
            gpioDelay(100000); // 100ms
            continue; // Skip to the next iteration
        }

        // Print the proximity data to the console
        printf("Proximity: %d\n", prox_data);

        // Wait for 500ms
        gpioDelay(500000);
    }

    // The program should never reach this point, but it's good practice to include cleanup code
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

