#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define TIMEOUT_DURATION 200 // milliseconds

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse duration on the echo pin
long measure_pulse_duration() {
    long start_tick, end_tick, pulse_duration;

    // Wait for the echo pin to go high (rising edge)
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_DURATION * 1000) {
        gpioDelay(1); // Check every microsecond
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_DURATION * 1000) {
        fprintf(stderr, "Error: Echo rising edge timeout\n");
        return -1; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (falling edge)
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_DURATION * 1000) {
        gpioDelay(1); // Check every microsecond
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_DURATION * 1000) {
        fprintf(stderr, "Error: Echo falling edge timeout\n");
        return -1; // Indicate timeout
    }

    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;

    // Handle tick rollover
    if (end_tick < start_tick) {
        pulse_duration += 0xFFFFFFFF; // Add the maximum possible tick value
    }

    return pulse_duration;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_duration) {
    if (pulse_duration <= 0 || pulse_duration > 38000) {
        fprintf(stderr, "Error: Invalid pulse duration: %ld\n", pulse_duration);
        return -1.0; // Indicate invalid duration
    }

    return (float)pulse_duration * 0.0343 / 2.0;
}

// Function to log the distance with a timestamp
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        long pulse_duration = measure_pulse_duration();

        if (pulse_duration > 0) {
            float distance = calculate_distance(pulse_duration);
            if (distance >= 0) {
                log_distance(distance);
            }
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

