#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define NUM_BINS 64
#define DISTANCE_THRESHOLD 1.0 // meters
#define ALERT_LED_GPIO 17
#define ALERT_DURATION 2 // seconds
#define LOG_FILE "intrusion_log.csv"

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_uart_data(int fd, unsigned char *buffer, int size);
int decode_range_profile(const unsigned char *buffer, int *distance_bins);
float calculate_distance(int bin_index);
int detect_target(const int *distance_bins, int num_bins, float threshold);
int log_intrusion(float distance);
int activate_alert_led(int gpio_pin, int duration_seconds);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// UART initialization function
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;  // Clear size bits
    tty.c_cflag |= CS8;   // 8 data bits

    tty.c_lflag = 0; // No signaling chars, no echo, no canonical processing
    tty.c_oflag = 0; // No remapping, no delays
    tty.c_cc[VMIN] = 0;  // Read non-blocking
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// UART data reading function
int read_uart_data(int fd, unsigned char *buffer, int size) {
    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read == -1) {
        fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        return -1;
    } else if (bytes_read == 0) {
        //fprintf(stderr, "Timeout reading from UART\n"); //Commented out to reduce verbosity
        return 0; // Timeout
    }
    return (int)bytes_read;
}

// Range profile decoding function
int decode_range_profile(const unsigned char *buffer, int *distance_bins) {
    if (buffer == NULL || distance_bins == NULL) {
        fprintf(stderr, "Error: Null pointer passed to decode_range_profile\n");
        return -1;
    }

    for (int i = 0; i < NUM_BINS; i++) {
        distance_bins[i] = (int16_t)((buffer[i * 2 + 0] << 0) | (buffer[i * 2 + 1] << 8));
    }
    return 0;
}

// Distance calculation function
float calculate_distance(int bin_index) {
    // Assuming a linear relationship between bin index and distance
    // Adjust the scaling factor as needed based on the radar configuration
    float scaling_factor = 0.01; // Example: 1 cm per bin
    return (float)bin_index * scaling_factor;
}

// Target detection function
int detect_target(const int *distance_bins, int num_bins, float threshold) {
    if (distance_bins == NULL) {
        fprintf(stderr, "Error: Null pointer passed to detect_target\n");
        return -1;
    }

    for (int i = 0; i < num_bins; i++) {
        float distance = calculate_distance(i);
        if (distance <= threshold) {
            return 1; // Target detected
        }
    }
    return 0; // No target detected
}

// Intrusion logging function
int log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Alert LED activation function
int activate_alert_led(int gpio_pin, int duration_seconds) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
