    if (result != 0) {
        fprintf(stderr, "Error writing to buzzer: %d\n", result);
    }
}

// Function to log events to a file
void log_event(int sensor_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

