#define ICU20201_ADDR 0x70
#define DISTANCE_REG 0x00 // Example register address, check datasheet
#define ALERT_GPIO 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
