    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    float distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);

            if (distance < DISTANCE_THRESHOLD) {
                set_alert(1); // Activate alert
            } else {
                set_alert(0); // Deactivate alert
            }
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

