#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L1X_REG_START_STOP_CONTROL 0x0000

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID (example)
    char data[2];
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    if (data[0] != 0xEA) {
        fprintf(stderr, "Error: Incorrect sensor ID (0x%02X)\n", data[0]);
        return -1;
    }

    // Start continuous ranging (example)
    data[0] = VL53L1X_REG_START_STOP_CONTROL;
    data[1] = 0x04; // Start ranging
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    char data[2];
    uint8_t distance_bytes[2];
    int distance;

    // Check if data is ready
    data[0] = VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY;
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
