#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x70
#define LED_GPIO 18
#define BLINK_FREQUENCY_MIN 0.5f  // Hz
#define BLINK_FREQUENCY_MAX 5.0f  // Hz
#define BLINK_PERIOD_MIN (1.0f / BLINK_FREQUENCY_MAX) // seconds
#define BLINK_PERIOD_MAX (1.0f / BLINK_FREQUENCY_MIN) // seconds
#define DISTANCE_MIN 10.0f  // cm
#define DISTANCE_MAX 100.0f // cm
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_distance(float *distance);
float calculate_blink_period(float distance);
void blink_led(float blink_period);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold program state
typedef struct {
    int i2c_handle;
    int led_gpio;
    float blink_period;
    float distance;
} ProgramState;

ProgramState state;

// Function to initialize the program
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize blink period to a default value
    state.blink_period = BLINK_PERIOD_MAX;

    return 0;
}

// Function to read distance from the sensor with retries
int read_distance(float *distance) {
    char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit value
            uint16_t raw_distance = (buf[0] << 8) | buf[1];

            // Convert raw value to distance in centimeters (example conversion)
            *distance = (float)raw_distance * 0.1f; // Adjust scaling as needed

            // Validate distance
            if (*distance >= DISTANCE_MIN && *distance <= DISTANCE_MAX) {
                return 0; // Success
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", *distance);
                return -1; // Indicate invalid reading
            }
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", RETRY_COUNT - retries + 1, strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries\n");
    return -1; // Indicate failure after retries
}

// Function to calculate the LED blink period based on distance
float calculate_blink_period(float distance) {
    // Map distance to blink period
    float blink_period = BLINK_PERIOD_MIN + (distance - DISTANCE_MIN) * (BLINK_PERIOD_MAX - BLINK_PERIOD_MIN) / (DISTANCE_MAX - DISTANCE_MIN);

    // Clamp the blink period within the defined range
    if (blink_period < BLINK_PERIOD_MIN) {
        blink_period = BLINK_PERIOD_MIN;
    } else if (blink_period > BLINK_PERIOD_MAX) {
        blink_period = BLINK_PERIOD_MAX;
    }

    return blink_period;
}

// Function to blink the LED
void blink_led(float blink_period) {
    static int led_state = 0; // 0 = off, 1 = on
    static struct timespec last_toggle_time;
    struct timespec current_time;
    long time_diff_us;

    clock_gettime(CLOCK_MONOTONIC, &current_time);

    // Calculate time difference since last toggle
    time_diff_us = (current_time.tv_sec - last_toggle_time.tv_sec) * 1000000L + (current_time.tv_nsec - last_toggle_time.tv_nsec) / 1000L;

    // Toggle LED if half the blink period has passed
    if (time_diff_us >= (long)(blink_period * 500000.0f)) {
        led_state = !led_state;
        gpioWrite(LED_GPIO, led_state);
        clock_gettime(CLOCK_MONOTONIC, &last_toggle_time);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to clean up resources before exiting
void cleanup() {
    // Turn off the LED
    gpioWrite(LED_GPIO, 0);

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the program
    if (initialize() != 0) {
        return 1;
    }

    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 ms

    float distance;

    // Main loop
    while (!terminate) {
        // Read distance from the sensor
        if (read_distance(&distance) == 0) {
            // Calculate the blink period
            state.blink_period = calculate_blink_period(distance);

            // Blink the LED
            blink_led(state.blink_period);

            // Get current timestamp
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

            // Log the data
            printf("%ld,%.2f,%.6f\n", timestamp_ms, distance, state.blink_period);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

