#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define the log file name
#define LOG_FILE "proximity_log.txt"

// Structure to hold sensor data
typedef struct {
    int gpio;
    int sensor_id;
    int last_state;
    unsigned long last_change_time;
} sensor_data_t;

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio);
int debounce(int gpio, int current_state, unsigned long last_change_time);
void log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to read the sensor value
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to debounce the sensor reading
int debounce(int gpio, int current_state, unsigned long last_change_time) {
    unsigned long now = gpioTick();
    if (now - last_change_time > DEBOUNCE_TIME * 1000) {
        return current_state;
    } else {
        return -1; // Indicate that the reading is still debouncing
    }
}

// Function to log the event to the file
void log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Initialize sensor data
    sensor_data_t sensor1 = {SENSOR_1_GPIO, 1, -1, 0};
    sensor_data_t sensor2 = {SENSOR_2_GPIO, 2, -1, 0};

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor 1
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        if (sensor1_value != -1) {
            int debounced_value = debounce(SENSOR_1_GPIO, sensor1_value, sensor1.last_change_time);
            if (debounced_value != -1 && debounced_value != sensor1.last_state) {
                if (debounced_value == 0) {
                    log_event(sensor1.sensor_id, "DETECTED");
                } else {
                    log_event(sensor1.sensor_id, "CLEARED");
                }
                sensor1.last_state = debounced_value;
                sensor1.last_change_time = gpioTick();
            }
        }

        // Read sensor 2
        int sensor2_value = read_sensor(SENSOR_2_GPIO);
        if (sensor2_value != -1) {
            int debounced_value = debounce(SENSOR_2_GPIO, sensor2_value, sensor2.last_change_time);
            if (debounced_value != -1 && debounced_value != sensor2.last_state) {
                if (debounced_value == 0) {
                    log_event(sensor2.sensor_id, "DETECTED");
                } else {
                    log_event(sensor2.sensor_id, "CLEARED");
                }
                sensor2.last_state = debounced_value;
                sensor2.last_change_time = gpioTick();
            }
        }

        gpioDelay(10); // Poll every 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

