#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define CH101_ADDR 0x50
#define MEAS_STATUS_REG 0x00
#define DISTANCE_REG 0x01
#define MEAS_STATUS_VALID 0x01
#define CSV_FILE "distance_log.csv"
#define I2C_RETRY_COUNT 3

// Global variables
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_register(int fd, uint8_t reg, uint8_t data);
int read_distance(int fd, uint16_t *distance);
void log_distance(FILE *fp, uint16_t distance);
void signal_handler(int signal);
int initialize_i2c(int bus, int addr);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// I2C read register function
int i2c_read_register(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance from sensor
int read_distance(int fd, uint16_t *distance) {
    uint8_t status;
    uint8_t distance_bytes[2];
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        if (i2c_read_register(fd, MEAS_STATUS_REG, &status, 1) != 0) {
            fprintf(stderr, "Error reading MEAS_STATUS_REG, retrying...\n");
            gpioDelay(10); // Small delay before retry
            retries--;
            continue;
        }

        if ((status & MEAS_STATUS_VALID) != 0) {
            if (i2c_read_register(fd, DISTANCE_REG, distance_bytes, 2) != 0) {
                fprintf(stderr, "Error reading DISTANCE_REG, retrying...\n");
                gpioDelay(10); // Small delay before retry
                retries--;
                continue;
            }
            *distance = (distance_bytes[0] << 8) | distance_bytes[1];
            return 0; // Success
        } else {
            fprintf(stderr, "MEAS_STATUS not valid, retrying...\n");
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure
}

// Log distance to CSV file
void log_distance(FILE *fp, uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance);
    fflush(fp); // Ensure data is written to disk immediately
}

// Initialize I2C
int initialize_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = initialize_i2c(I2C_BUS, CH101_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    uint16_t distance;
    while (!terminate) {
        if (read_distance(i2c_fd, &distance) == 0) {
            log_distance(csv_file, distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }
        gpioDelay(500); // Wait 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

