    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the VL53L5CX sensor
    if (init_vl53l5cx(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize VL53L5CX sensor\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and log zone distances
    uint16_t distances[NUM_ZONES];
    struct timespec sleep_time = {0, 500000000}; // 500 ms
    while (1) {
        // Read the zone distances
        if (read_zone_distances(i2c_fd, distances) == 0) {
            // Log the zone distances to the console
            for (int i = 0; i < NUM_ZONES; i++) {
                printf("Zone %d: %d mm", i, distances[i]);
                if (i < NUM_ZONES - 1) {
                    printf(", ");
                }
            }
            printf("\n");
        } else {
            fprintf(stderr, "Failed to read zone distances\n");
        }

        // Sleep for 500 ms
        nanosleep(&sleep_time, NULL);
    }

    // Close the I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

