#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L4CX_REG_RESULT_SPAD_NB_DETECTED 0x0022
#define VL53L4CX_REG_RESULT_SIGNAL_RATE 0x001E
#define VL53L4CX_REG_RESULT_AMBIENT_RATE 0x0020
#define VL53L4CX_REG_RESULT_DISTANCE 0x001A
#define VL53L4CX_REG_INTERRUPT_STATUS 0x0081
#define VL53L4CX_REG_INTERRUPT_CLEAR 0x0080
#define VL53L4CX_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L4CX_REG_FIRMWARE_SYSTEM_STATUS 0x00E5

// Interrupt status bit
