// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L4CX_REG_RESULT_SPAD_NB_DETECTED 0x0022
#define VL53L4CX_REG_RESULT_SIGNAL_RATE 0x001E
#define VL53L4CX_REG_RESULT_AMBIENT_RATE 0x0020
#define VL53L4CX_REG_RESULT_DISTANCE 0x001A
#define VL53L4CX_REG_INTERRUPT_STATUS 0x0081
#define VL53L4CX_REG_INTERRUPT_CLEAR 0x0080
#define VL53L4CX_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L4CX_REG_FIRMWARE_SYSTEM_STATUS 0x00E5

// Interrupt status bit
#define VL53L4CX_INTERRUPT_STATUS_BIT 0x01

// I2C bus number
#define I2C_BUS 1

// Global variables
static int i2c_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l4cx_init(int fd);
int vl53l4cx_read_distance(int fd, uint16_t *distance);
int vl53l4cx_clear_interrupt(int fd);
int vl53l4cx_check_interrupt(int fd);
void signal_handler(int sig);
int i2c_write_byte(int fd, uint8_t reg, uint8_t data);
int i2c_read_byte(int fd, uint8_t reg, uint8_t *data);
int i2c_read_word(int fd, uint8_t reg, uint16_t *data);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read byte function
int i2c_read_byte(int fd, uint8_t reg, uint8_t *data) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (address) error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read word function
int i2c_read_word(int fd, uint8_t reg, uint16_t *data) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "I2C write (address) error: %s\n", strerror(errno));
        return -1;
    }
    uint8_t read_buf[2];
    if (read(fd, read_buf, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

