#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm
#define BUZZER_DURATION 200 // ms
#define READ_INTERVAL 500 // ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_buzzer(int activate);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_RANGING_MODE 0x0081
#define VL53L1X_REG_START_STOP 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust as needed)
    // This is a simplified example and might not be complete
    // Refer to the VL53L1X datasheet for the full initialization sequence

    // Check sensor ID
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", model_id);
        return -1;
    }

    // Set ranging mode to continuous
    char ranging_mode = 0x02; // Continuous mode
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_RANGING_MODE, &ranging_mode, 1) != 1) {
        fprintf(stderr, "Error setting ranging mode: %s\n", strerror(errno));
        return -1;
    }

    // Start continuous ranging
    char start_ranging = 0x01;
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_START_STOP, &start_ranging, 1) != 1) {
        fprintf(stderr, "Error starting ranging: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    char range_status;
    char distance_bytes[2];
    int distance;

    // Read range status
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status, 1) != 1) {
        fprintf(stderr, "Error reading range status: %s\n", strerror(errno));
        return -1;
    }

    // Read distance (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, distance_bytes, 2) != 2) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    // Combine bytes to form the distance value
    distance = (distance_bytes[0] << 8) | distance_bytes[1];

    return distance;
}

// Control the buzzer
void control_buzzer(int activate) {
    gpioWrite(BUZZER_GPIO, activate);
    if (activate) {
        gpioDelay(BUZZER_DURATION * 1000); // Delay in microseconds
        gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer after delay
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance > 0) {
            printf("Distance: %d mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                control_buzzer(1); // Activate buzzer
            }
        } else {
            fprintf(stderr, "Error reading distance, skipping iteration\n");
        }

        gpioDelay(READ_INTERVAL * 1000); // Delay in microseconds
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

