#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 400.0     // Maximum distance in cm
#define MIN_ANGLE -90.0       // Minimum servo angle in degrees
#define MAX_ANGLE 90.0        // Maximum servo angle in degrees
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)

// Global variables
static volatile int running = 1;
FILE *log_file = NULL;

// Function prototypes
float measure_distance();
float map_distance_to_angle(float distance);
void set_servo_angle(float angle);
void log_data(float distance, float angle);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    set_servo_angle(0.0); // Stop the servo
    cleanup_gpio();        // Release GPIO resources
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

// Measure distance using the HC-SR04 sensor
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Timeout error
    }
    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Timeout error
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm

    return distance;
}

// Map distance to servo angle
float map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Set servo angle using pigpio
void set_servo_angle(float angle) {
    // Convert angle to pulse width (500-2500 us)
    int pulse_width = (int)(500 + (angle + 90.0) * (2000.0 / 180.0));
    gpioServo(SERVO_PIN, pulse_width);
}

// Log data to file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %.2f degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();

        if (distance > 0) {
            float angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance reading.\n");
        }

        gpioDelay(200); // 200 ms delay
    }

    // Cleanup resources before exiting (in case the loop exits normally)
    set_servo_angle(0.0);
    cleanup_gpio();
    fclose(log_file);

    return 0;
}

