#include <mqueue.h>
#include <pigpio.h>
#include <stdbool.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define TIMING_BUDGET 50 // ms
#define MESSAGE_QUEUE_NAME "/distance_queue"
#define MAX_MSG_SIZE 10 // Maximum message size in mm
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
mqd_t mq;
bool running = true;

// Function prototypes
int init_vl53l1x();
int read_distance();
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);
void cleanup();

// VL53L1X register addresses (Example - adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Helper function to write a byte to a VL53L1X register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Helper function to read a byte from a VL53L1X register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    deactivate_buzzer(); // Ensure buzzer is off initially

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    // Configure message queue attributes
    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = 10; // Maximum number of messages in the queue
    attr.mq_msgsize = sizeof(int); // Size of each message (distance in mm)
    attr.mq_curmsgs = 0;

    // Create message queue
    mq = mq_open(MESSAGE_QUEUE_NAME, O_CREAT | O_WRONLY | O_NONBLOCK, 0644, &attr);
    if (mq == (mqd_t)-1) {
        perror("mq_open failed");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int distance = read_distance();
        if (distance >= 0) {
            // Log distance to message queue
            if (mq_send(mq, (const char *)&distance, sizeof(int), 0) == -1) {
                perror("mq_send failed");
            }

            // Activate buzzer if distance is below threshold
            if (distance < DISTANCE_THRESHOLD) {
                activate_buzzer();
            } else {
                deactivate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(50); // 50 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Implement VL53L1X initialization sequence here
    // This is a simplified example and may need adjustments based on the datasheet
    // and your specific sensor configuration.

    // Example: Check sensor ID (replace with actual register and expected value)
    uint8_t sensor_id;
    if (read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &sensor_id) != 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return -1;
    }

    if (sensor_id != 0xEACC) { // Example ID, check the datasheet
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Set timing budget (example)
    if (write_register(i2c_handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD, TIMING_BUDGET) != 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        return -1;
    }

    // Start continuous ranging (example)
    if (write_register(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x40) != 0) {
        fprintf(stderr, "Failed to start continuous ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    uint8_t range_status;
    uint8_t distance_msb, distance_lsb;
    int distance;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Read range status
        if (read_register(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
            fprintf(stderr, "Failed to read range status (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(1); // Small delay before retry
            continue;
        }

        // Read distance (MSB and LSB)
        if (read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_msb) != 0) {
            fprintf(stderr, "Failed to read distance MSB (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(1);
            continue;
        }
        if (read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &distance_lsb) != 0) {
            fprintf(stderr, "Failed to read distance LSB (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(1);
            continue;
        }

        distance = (distance_msb << 8) | distance_lsb;

        // Basic data validation
        if (distance < 0 || distance > 2000) { // Reasonable range
            fprintf(stderr, "Invalid distance reading: %d\n", distance);
            retries++;
            gpioDelay(1);
            continue;
        }

        return distance;
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Set GPIO high
}

// Deactivate buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0); // Set GPIO low
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    running = false;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (mq != (mqd_t)-1) {
        mq_close(mq);
        mq_unlink(MESSAGE_QUEUE_NAME);
    }
    deactivate_buzzer();
    gpioTerminate();
}

