#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds (50ms)
#define MIN_DISTANCE 2.0       // Minimum valid distance in cm
#define MAX_DISTANCE 400.0     // Maximum valid distance in cm
#define BUZZER_THRESHOLD 30.0  // Distance threshold for buzzer activation in cm

// Global variables
volatile uint32_t start_tick = 0;
volatile uint32_t end_tick = 0;
volatile int echo_received = 0;
volatile int terminate = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t start, uint32_t end);
void control_buzzer(double distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 0; // Reset flag for new measurement
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t start, uint32_t end) {
    uint32_t diff = end - start;
    if (end < start) {
        // Handle tick wraparound
        diff = (0xFFFFFFFF - start) + end + 1;
    }

    double time_taken = (double)diff / 1000000.0; // Time in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm
    return distance;
}

// Function to control the buzzer based on distance
void control_buzzer(double distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        trigger_pulse(); // Send trigger pulse
        gpioDelay(50);   // Wait for echo

        if (!echo_received) {
            printf("Sensor absent or timeout\n");
        } else {
            double distance = calculate_distance(start_tick, end_tick);

            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                printf("Invalid reading: %.2f cm\n", distance);
            } else {
                printf("Distance: %.2f cm\n", distance);
                control_buzzer(distance);
            }
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup (should not reach here if signal handler works)
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();

    return 0;
}

