#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define OPEN_ANGLE 180
#define CLOSE_ANGLE 0
#define DISTANCE_THRESHOLD 200 // mm
#define PWM_FREQUENCY 50 // Hz
#define PWM_RANGE 1000000 // pigpio range
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void set_servo_angle(int angle);
void log_event(const char *message);
void signal_handler(int signal);
void force_open();
void force_close();
void status_request();

// Driver API callbacks
void (*driver_force_open)(void) = NULL;
void (*driver_force_close)(void) = NULL;
void (*driver_status_request)(void) = NULL;

// Helper function to convert angle to pulse width
int angle_to_pulse_width(int angle) {
    // Map angle (0-180) to pulse width (SERVO_MIN_PULSE_WIDTH - SERVO_MAX_PULSE_WIDTH)
    return SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // VL53L1X initialization sequence (simplified)
    // Refer to the VL53L1X datasheet for the complete sequence
    unsigned char data[2];
    int status;

    // Example initialization steps (replace with actual sequence)
    data[0] = 0x00; // Register address
    data[1] = 0x01; // Register value
    status = i2cWriteDevice(i2c_handle, (char *)data, 2);
    if (status != 0) {
        log_event("VL53L1X init failed: Write 1");
        return -1;
    }
    gpioDelay(1000); // 1ms delay

    data[0] = 0x01; // Register address
    data[1] = 0x02; // Register value
    status = i2cWriteDevice(i2c_handle, (char *)data, 2);
    if (status != 0) {
        log_event("VL53L1X init failed: Write 2");
        return -1;
    }
    gpioDelay(1000); // 1ms delay

    log_event("VL53L1X initialized");
    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance() {
    unsigned char cmd[1];
    unsigned char data[2];
    int distance;
    int status;

    // Start a single measurement
    cmd[0] = 0x00; // Example command to start measurement
    status = i2cWriteDevice(i2c_handle, (char *)cmd, 1);
    if (status != 0) {
        log_event("VL53L1X read failed: Start measurement");
        return -1;
    }
    gpioDelay(1000); // Wait for measurement to complete

    // Read the distance data (2 bytes)
    cmd[0] = 0x14; // Register address for distance
    status = i2cWriteDevice(i2c_handle, (char *)cmd, 1);
    if (status != 0) {
        log_event("VL53L1X read failed: Write register address");
        return -1;
    }

    status = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (status != 2) {
        log_event("VL53L1X read failed: Read distance");
        return -1;
    }

    distance = (data[0] << 8) | data[1];

    return distance;
}

// Function to set the servo angle using hardware PWM
void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = angle_to_pulse_width(angle);
    gpioPWM(SERVO_PIN, pulse_width); // Set PWM duty cycle
    char message[100];
    sprintf(message, "Servo angle set to %d degrees (pulse width: %d us)", angle, pulse_width);
    log_event(message);
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Signal received, shutting down...");
}

// Remote control command handlers
void force_open() {
    log_event("Force open command received");
    set_servo_angle(OPEN_ANGLE);
}

void force_close() {
    log_event("Force close command received");
    set_servo_angle(CLOSE_ANGLE);
}

void status_request() {
    log_event("Status request command received");
    int distance = read_distance();
    if (distance > 0) {
        char message[100];
        sprintf(message, "Distance: %d mm", distance);
        log_event(message);
    } else {
        log_event("Failed to read distance for status request");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("I2C open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        log_event("VL53L1X initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure servo pin for PWM output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_PIN, PWM_RANGE);

    // Set initial servo position (closed)
    set_servo_angle(CLOSE_ANGLE);

    // Main loop
    int distance;
    while (program_running) {
        distance = read_distance();
        if (distance > 0) {
            char message[100];
            sprintf(message, "Distance: %d mm", distance);
            log_event(message);

            if (distance < DISTANCE_THRESHOLD) {
                // Object detected, open the gate
                if (driver_force_open != NULL) {
                    driver_force_open();
                } else {
                    log_event("Driver force_open callback not set");
                    set_servo_angle(OPEN_ANGLE);
                }
            } else {
                // No object detected, close the gate
                if (driver_force_close != NULL) {
                    driver_force_close();
                } else {
                    log_event("Driver force_close callback not set");
                    set_servo_angle(CLOSE_ANGLE);
                }
            }
        } else {
            log_event("Failed to read distance");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

