            if (distance < DISTANCE_THRESHOLD) {
                // Object detected, open the gate
                if (driver_force_open != NULL) {
                    driver_force_open();
                } else {
                    log_event("Driver force_open callback not set");
                    set_servo_angle(OPEN_ANGLE);
