#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define TRIGGER_INTERVAL 200      // milliseconds
#define MIN_PULSE_WIDTH 100       // microseconds
#define MAX_PULSE_WIDTH 30000     // microseconds
#define TIMEOUT_DURATION 60       // milliseconds

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_valid = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rising_tick = tick;
        echo_valid = 0; // Reset echo_valid on rising edge
    } else if (level == 0) {
        falling_tick = tick;
        echo_valid = 1; // Set echo_valid on falling edge
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return pulse_width * 0.0343 / 2.0;
}

// Function to log distance with timestamp
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);
    fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (1) {
        trigger_pulse();
        gpioDelay(TRIGGER_INTERVAL);

        uint32_t start_time = gpioTick();
        uint32_t pulse_width = 0;

        // Wait for a valid echo or timeout
        while (!echo_valid && (gpioTick() - start_time) < TIMEOUT_DURATION * 1000) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (!echo_valid) {
            fprintf(stderr, "Timeout waiting for echo!\n");
            fprintf(log_file, "Timeout waiting for echo!\n");
            fflush(log_file);
        } else {
            // Calculate pulse width, handling tick wraparound
            if (falling_tick > rising_tick) {
                pulse_width = falling_tick - rising_tick;
            } else {
                pulse_width = (0xFFFFFFFF - rising_tick) + falling_tick + 1;
            }

            if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
                fprintf(stderr, "Invalid pulse width: %u microseconds\n", pulse_width);
                fprintf(log_file, "Invalid pulse width: %u microseconds\n", pulse_width);
                fflush(log_file);
            } else {
                double distance = calculate_distance(pulse_width);
                log_distance(distance);
            }
        }
    }

    return 0;
}

