#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define constants
#define VL53L1X_ADDR 0x29
#define SHUTDOWN_PIN 23
#define SERVO_PIN 18
#define OPEN_DISTANCE 500 // mm
#define CLOSE_DISTANCE 600 // mm
#define SERVO_OPEN_PWM 2000 // Adjust as needed
#define SERVO_CLOSED_PWM 1000 // Adjust as needed
#define PWM_RANGE 2000
#define PWM_CLOCK 192 // For 50Hz PWM frequency (20ms period)

// Global variables
int i2c_fd;
FILE *log_file;
bool gate_open = false;

// Function prototypes
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *event, int distance);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x08A

// Helper function to write to a VL53L1X register
int write_vl53l1x_reg(int reg, int value) {
    int result = wiringPiI2CWriteReg8(i2c_fd, reg, value);
    if (result == -1) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Helper function to read from a VL53L1X register
int read_vl53l1x_reg(int reg) {
    int result = wiringPiI2CReadReg8(i2c_fd, reg);
    if (result == -1) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(VL53L1X_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        return 1;
    }

    // Configure servo motor pin as PWM output
    pinMode(SERVO_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(PWM_CLOCK);

    // Initialize log file
    log_file = fopen("parking_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int distance = read_distance();
        if (distance == -1) {
            fprintf(stderr, "Failed to read distance.\n");
            delay(100); // Avoid spamming errors
            continue;
        }

        if (distance < OPEN_DISTANCE && !gate_open) {
            open_gate();
            log_event("OPEN", distance);
            gate_open = true;
        } else if (distance > CLOSE_DISTANCE && gate_open) {
            close_gate();
            log_event("CLOSE", distance);
            gate_open = false;
        }

        delay(100); // Delay to avoid excessive CPU usage
    }

    return 0;
}

int init_vl53l1x() {
    // Check VL53L1X model ID
    int model_id = read_vl53l1x_reg(VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect VL53L1X model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Set I2C address (example)
    if (write_vl53l1x_reg(VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR << 1) != 0) {
        return -1;
    }

    // Start continuous ranging (example)
    if (write_vl53l1x_reg(VL53L1X_REG_SYSRANGE_START, 0x01) != 0) {
        return -1;
    }

    return 0;
}

int read_distance() {
    // Check if data is ready
    int data_ready = read_vl53l1x_reg(VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY);
    if (data_ready != 0x04) {
        return -1; // Data not ready
    }

    // Read distance
    int distance = read_vl53l1x_reg(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance == -1) {
        return -1;
    }

    // Clear data ready bit (example - might not be needed depending on sensor config)
    if (write_vl53l1x_reg(VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, 0x00) != 0) {
        return -1;
    }

    return distance;
}

void open_gate() {
    pwmWrite(SERVO_PIN, SERVO_OPEN_PWM);
}

void close_gate() {
    pwmWrite(SERVO_PIN, SERVO_CLOSED_PWM);
}

void log_event(const char *event, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d - Gate %s, Distance: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the gate
    close_gate();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Reset GPIO pins (optional, but good practice)
    pinMode(SERVO_PIN, INPUT); // Set servo pin to input
    digitalWrite(SHUTDOWN_PIN, LOW); // Set shutdown pin to low

    exit(0);
}

