    status |= i2cWriteByteData(i2c_handle, VL53L1X_REG_GPIO_HV_MUX_CTRL, 0x01); // GPIO1 high
    status |= i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_GPIO1, 0x10); // GPIO1 mode = New Sample Ready

