#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18
#define GPIO_TRIGGER 24
#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300
#define MAX_RETRIES 3

// VL53L1X register addresses (Example - adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile int running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(uint16_t *distance);
void motor_forward();
void motor_backward();
void motor_stop();
void distance_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
void log_message(const char *message);

// Helper function for exponential backoff
void delay_ms(int ms) {
    gpioDelay(ms * 1000); // pigpio uses microseconds
}

// VL53L1X initialization function
int vl53l1x_init() {
    int retries = 0;
    int status = 0;

    // Soft reset (Example - adjust based on datasheet)
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, 0x0000, 0x01); // Example reset command
        if (status == 0) break;
        log_message("VL53L1X soft reset failed. Retrying...");
        delay_ms(10 << retries); // Exponential backoff
        retries++;
    }
    if (status != 0) {
        log_message("VL53L1X soft reset failed after multiple retries.");
        return -1;
    }
    delay_ms(1); // Wait for reset to complete

    // Start continuous ranging (Example - adjust based on datasheet)
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01); // Start ranging
        if (status == 0) break;
        log_message("VL53L1X start ranging failed. Retrying...");
        delay_ms(10 << retries); // Exponential backoff
        retries++;
    }
    if (status != 0) {
        log_message("VL53L1X start ranging failed after multiple retries.");
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(uint16_t *distance) {
    int retries = 0;
    int status = 0;
    uint8_t range_status;

    while (retries < MAX_RETRIES) {
        // Poll for data ready (Example - adjust based on datasheet)
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status < 0) {
            log_message("VL53L1X read range status failed. Retrying...");
            delay_ms(10 << retries); // Exponential backoff
            retries++;
            continue;
        }
        range_status = (uint8_t)status;

        if ((range_status & 0x01) == 0) { // Check data ready bit (example)
            delay_ms(1); // Wait a bit before retrying
            retries++;
            continue;
        }

        // Read distance (Example - adjust based on datasheet)
        status = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (status < 0) {
            log_message("VL53L1X read distance failed. Retrying...");
            delay_ms(10 << retries); // Exponential backoff
            retries++;
            continue;
        }
        *distance = (uint16_t)status;
        return 0; // Success
    }

    log_message("VL53L1X read distance failed after multiple retries.");
    return -1; // Failure
}

// Motor control functions
void motor_forward() {
    gpioWrite(GPIO_MOTOR_FORWARD, 1);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    log_message("Motor: Forward");
}

void motor_backward() {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 1);
    log_message("Motor: Backward");
}

void motor_stop() {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    log_message("Motor: Stopped");
}

// Distance callback function
void distance_callback(int gpio, int level, uint32_t tick, void *user_data) {
    uint16_t distance;
    int status;

    status = vl53l1x_read_distance(&distance);
    if (status == 0) {
        char message[100];
        snprintf(message, sizeof(message), "Distance: %d mm", distance);
        log_message(message);

        if (distance < DISTANCE_THRESHOLD_LOW) {
            motor_forward();
        } else if (distance > DISTANCE_THRESHOLD_HIGH) {
            motor_backward();
        } else {
            motor_stop();
        }
    } else {
        log_message("Failed to read distance in callback.");
    }
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    log_message("Signal received, stopping...");
    motor_stop();
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Logging function
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C bus.");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        log_message("VL53L1X initialization failed.");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_DOWN); // Optional pull-down resistor

    // Set up interrupt on GPIO_TRIGGER (rising edge)
    if (gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, distance_callback, NULL) != 0) {
        log_message("Failed to set up interrupt.");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program started.");

    // Main loop
    while (running) {
        gpioDelay(100000); // Sleep for 100ms (100000 microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    motor_stop();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

