}

void motor_backward() {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 1);
    log_message("Motor: Backward");
}

void motor_stop() {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    log_message("Motor: Stopped");
}

// Distance callback function
void distance_callback(int gpio, int level, uint32_t tick, void *user_data) {
    uint16_t distance;
    int status;

    status = vl53l1x_read_distance(&distance);
    if (status == 0) {
        char message[100];
        snprintf(message, sizeof(message), "Distance: %d mm", distance);
        log_message(message);

        if (distance < DISTANCE_THRESHOLD_LOW) {
            motor_forward();
        } else if (distance > DISTANCE_THRESHOLD_HIGH) {
            motor_backward();
        } else {
            motor_stop();
        }
    } else {
        log_message("Failed to read distance in callback.");
    }
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    log_message("Signal received, stopping...");
    motor_stop();
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Logging function
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C bus.");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        log_message("VL53L1X initialization failed.");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_DOWN); // Optional pull-down resistor

    // Set up interrupt on GPIO_TRIGGER (rising edge)
    if (gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, distance_callback, NULL) != 0) {
        log_message("Failed to set up interrupt.");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program started.");

    // Main loop
    while (running) {
        gpioDelay(100000); // Sleep for 100ms (100000 microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    motor_stop();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

