#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define LED_GPIO_0 17
#define LED_GPIO_1 18
#define LED_GPIO_2 27
#define LED_GPIO_3 22
#define POLL_INTERVAL_MS 50

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void set_led_pattern(uint16_t touch_status);
void log_event(uint16_t touch_status);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Release GPIO pins
    gpioSetMode(LED_GPIO_0, PI_INPUT); // Set to input to release
    gpioSetMode(LED_GPIO_1, PI_INPUT);
    gpioSetMode(LED_GPIO_2, PI_INPUT);
    gpioSetMode(LED_GPIO_3, PI_INPUT);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

// MPR121 Initialization function
int mpr121_init() {
    int result;

    // Soft reset
    result = i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x00); // Reset
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure Electrode Configuration Register (ECR)
    result = i2cWriteByteData(i2c_handle, MPR121_ECR, 0x0C); // Enable all 12 electrodes
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 ECR configuration failed: %s\n", strerror(errno));
        return -1;
    }

    // Verify sensor presence by reading back a register
    int read_value = i2cReadByteData(i2c_handle, MPR121_ECR);
    if (read_value < 0) {
        fprintf(stderr, "Error: MPR121 verification failed: %s\n", strerror(errno));
        return -1;
    }
    if (read_value != 0x0C) {
        fprintf(stderr, "Error: MPR121 verification failed: Read value mismatch\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to read touch status: %s\n", strerror(errno));
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to set LED pattern based on touch status
void set_led_pattern(uint16_t touch_status) {
    // Define LED patterns for each electrode
    const int led_patterns[12] = {
        0b0001, 0b0010, 0b0011, 0b0100, 0b0101, 0b0110,
        0b0111, 0b1000, 0b1001, 0b1010, 0b1011, 0b1100
    };

    // Iterate through electrodes and set LEDs accordingly
    for (int i = 0; i < 12; i++) {
        if (touch_status & (1 << i)) {
            int pattern = led_patterns[i];
            gpioWrite(LED_GPIO_0, (pattern >> 0) & 1);
            gpioWrite(LED_GPIO_1, (pattern >> 1) & 1);
            gpioWrite(LED_GPIO_2, (pattern >> 2) & 1);
            gpioWrite(LED_GPIO_3, (pattern >> 3) & 1);
            break; // Only set the pattern for the first touched electrode
        }
    }
}

// Function to log events to file
void log_event(uint16_t touch_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Touch Status: 0x%04X\n", timestamp, touch_status);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

