    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for LEDs
    gpioSetMode(LED_GPIO_0, PI_OUTPUT);
    gpioSetMode(LED_GPIO_1, PI_OUTPUT);
    gpioSetMode(LED_GPIO_2, PI_OUTPUT);
    gpioSetMode(LED_GPIO_3, PI_OUTPUT);

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            set_led_pattern(touch_status);
            log_event(touch_status);
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        gpioDelay(POLL_INTERVAL_MS); // Delay for 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

