#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTHRES 0x24
#define MPR121_BASELINETHRES 0x25
#define MPR121_ELECTRODECONFIG 0x5E
#define MPR121_SOFTRESET 0x80

// GPIO pin for LED
#define LED_PIN 27

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
void led_on();
void led_off();
void log_proximity_event(int electrode);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure MPR121 registers
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTHRES, 0x10) < 0) {
        fprintf(stderr, "Error: Failed to write FiltThres\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINETHRES, 0x05) < 0) {
        fprintf(stderr, "Error: Failed to write BaselineThres\n");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODECONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to write ElectrodeConfig\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int mpr121_read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to turn LED on
void led_on() {
    gpioWrite(LED_PIN, 1);
}

// Function to turn LED off
void led_off() {
    gpioWrite(LED_PIN, 0);
}

// Function to log proximity event
void log_proximity_event(int electrode) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Proximity detected on electrode %d\n", timestamp, electrode);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status = 0;
    uint16_t last_touch_status = 0;

    // Main loop
    while (!terminate) {
        if (mpr121_read_touch_status(&touch_status) == 0) {
            // Check for proximity events
            for (int i = 0; i < 12; i++) {
                if ((touch_status & (1 << i)) && !(last_touch_status & (1 << i))) {
                    printf("Proximity detected on electrode %d\n", i);
                    led_on();
                    log_proximity_event(i);
                    gpioDelay(1000); // LED on for 1 second
                    led_off();
                }
            }
            last_touch_status = touch_status;
        } else {
            fprintf(stderr, "Error reading touch status, retrying...\n");
        }
        gpioDelay(50); // Delay to avoid excessive CPU usage
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

