#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // 30 ms

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
long long measure_pulse_width();
double calculate_distance(long long pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100); // Give it some time to settle

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

// Trigger pulse function
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure pulse width function
long long measure_pulse_width() {
    long long start_tick, end_tick, pulse_width;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF + 1; // Handle tick rollover
    }

    return pulse_width;
}

// Calculate distance function
double calculate_distance(long long pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // cm
}

// Log distance function
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(log_file, "%s,ERROR: Distance out of range (%.2f cm)\n", timestamp, distance);
        fflush(log_file);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_pulse();
        long long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            double distance = calculate_distance(pulse_width);
            log_distance(distance);
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
            fprintf(log_file, "%s,ERROR: Invalid pulse width\n", timestamp);
            fflush(log_file);
        }

        sleep(1);
    }

    // Close log file
    fclose(log_file);

    // Cleanup GPIO
    cleanup_gpio();

    printf("Distance measurement stopped.\n");

    return 0;
}

