#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 30000       // 30ms timeout
#define MOVING_AVG_SIZE 5

// Global variables
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    double pulse_width;
    int new_pulse;
} sensor_data_t;

// Structure to hold moving average filter data
typedef struct {
    double samples[MOVING_AVG_SIZE];
    int index;
    double sum;
} moving_average_filter_t;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(double pulse_width);
void set_servo_angle(int angle);
void log_data(double distance, int angle);
void signal_handler(int signal);
void initialize_moving_average_filter(moving_average_filter_t *filter);
double update_moving_average_filter(moving_average_filter_t *filter, double new_sample);

// Global sensor data
sensor_data_t sensor_data = {0.0, 0};

// Function to initialize the moving average filter
void initialize_moving_average_filter(moving_average_filter_t *filter) {
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        filter->samples[i] = 0.0;
    }
    filter->index = 0;
    filter->sum = 0.0;
}

// Function to update the moving average filter
double update_moving_average_filter(moving_average_filter_t *filter, double new_sample) {
    filter->sum -= filter->samples[filter->index];
    filter->samples[filter->index] = new_sample;
    filter->sum += new_sample;
    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;
    return filter->sum / MOVING_AVG_SIZE;
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t start_tick = 0;

    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        if (start_tick != 0) {
            uint32_t end_tick = tick;
            double pulse_width = (double)(end_tick - start_tick); // Pulse width in microseconds

            // Handle tick wrap-around
            if (end_tick < start_tick) {
                pulse_width = (double)((0xFFFFFFFF - start_tick) + end_tick);
            }

            sensor_data.pulse_width = pulse_width;
            sensor_data.new_pulse = 1;
        }
    }
}

// Function to calculate distance in centimeters
double calculate_distance(double pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to set the servo angle
void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    gpioServo(SERVO_PIN, 500 + (angle * 2000 / 180)); // Map angle (0-180) to pulse width (500-2500)
}

// Function to log data to CSV file
void log_data(double distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
    fflush(log_file);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register interrupt callback for echo pin
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register interrupt callback\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Angle (degrees)\n");
    }
    fflush(log_file);

    // Initialize moving average filter
    moving_average_filter_t distance_filter;
    initialize_moving_average_filter(&distance_filter);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for echo or timeout
        int timeout_counter = 0;
        while (!sensor_data.new_pulse && timeout_counter < TIMEOUT_US) {
            gpioDelay(1); // Check every 1us
            timeout_counter++;
        }

        // Process the data
        if (sensor_data.new_pulse) {
            double distance = calculate_distance(sensor_data.pulse_width);
            double filtered_distance = update_moving_average_filter(&distance_filter, distance);

            // Validate distance
            if (filtered_distance >= 2.0 && filtered_distance <= 400.0) {
                // Set servo angle (example: map distance to angle)
                int angle = (int)((filtered_distance - 2.0) * (180.0 / (400.0 - 2.0))); // Map 2-400cm to 0-180 degrees
                set_servo_angle(angle);
                log_data(filtered_distance, angle);
            } else {
                // Invalid distance, set servo to 90 degrees
                set_servo_angle(90);
                log_data(-1.0, 90);
            }

            // Reset new_pulse flag
            sensor_data.new_pulse = 0;
        } else {
            // No echo received, set servo to 90 degrees
            set_servo_angle(90);
            log_data(-1.0, 90);
        }

        gpioDelay(100000); // 100ms delay
    }

    // Stop the servo
