#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// GPIO pin for the warning LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 10

// I2C handle
int i2c_handle;

// Circular buffer for distance readings
int distance_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void update_led(int distance);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR  0x0027
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN 0x0024
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_START_STOP_MEASURE 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Helper function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int reg, int data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Helper function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int reg, char *data) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Helper function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int reg, short *data) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for word read 0x%02X\n", reg);
        return -1;
    }
    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading word from register 0x%02X\n", reg);
        return -1;
    }
    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read distance from VL53L1X sensor
        int distance = vl53l1x_read_distance();

        // Update LED based on distance
        update_led(distance);

        // Store distance in circular buffer
        distance_buffer[buffer_index] = distance;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Wait 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    return 0;
}

