#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"

// Global variables
static int i2c_handle;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int threshold = DEFAULT_THRESHOLD;
static FILE *log_file = NULL;
static volatile int interrupt_flag = 0;

// Function prototypes
int init_i2c(int address);
int init_gpio(int pin);
int configure_sensor(int handle);
int read_proximity(int handle);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_data(int proximity_value, const char *status);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting GPIO pull-down\n");
        return -1;
    }
    return 0;
}

// Function to configure the Si1102 sensor
int configure_sensor(int handle) {
    // Example configuration (adjust based on Si1102 datasheet)
    if (i2cWriteByteData(handle, 0x02, 0x01) < 0) { // Enable interrupt on GPIO27
        fprintf(stderr, "Error writing to I2C\n");
        return -1;
    }
    if (i2cWriteByteData(handle, 0x03, 0x0F) < 0) { // Set interrupt threshold
        fprintf(stderr, "Error writing to I2C\n");
        return -1;
    }
    return 0;
}

// Function to read the proximity value from the sensor
int read_proximity(int handle) {
    int proximity_value = i2cReadWordData(handle, 0x04); // Register address for proximity
    if (proximity_value < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }
    return proximity_value;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) { // Rising edge
        interrupt_flag = 1;
    }
}

// Function to log data to a file
void log_data(int proximity_value, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity_value, status);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (interrupt_flag) {
            int proximity_value = read_proximity(i2c_handle);
            if (proximity_value >= 0) {
                const char *status = (proximity_value > threshold) ? "ALERT" : "SAFE";
                log_data(proximity_value, status);
            }
            interrupt_flag = 0; // Reset the flag
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

