#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000       // Timeout in microseconds (200ms)
#define MIN_DISTANCE 2.0        // Minimum distance in cm
#define MAX_DISTANCE 200.0      // Maximum distance in cm
#define MIN_FREQUENCY 200.0     // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0    // Maximum frequency in Hz

// Global variables
volatile sig_atomic_t terminate = 0;
double last_frequency = MIN_FREQUENCY; // Initialize to minimum frequency

// Function prototypes
void trigger_sensor();
long pulse_in(int pin, int level, int timeout);
double calculate_distance(long pulse_duration);
double map_distance_to_frequency(double distance);
void set_pwm_frequency(double frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse duration on a GPIO pin
long pulse_in(int pin, int level, int timeout) {
    long start_time = 0, end_time = 0;
    long pulse_duration = 0;

    // Wait for the pulse to start
    int count = 0;
    while (gpioRead(pin) != level) {
        if (count > timeout) {
            return -1; // Timeout
        }
        gpioDelay(1); // Check every microsecond
        count++;
    }

    start_time = gpioTick();

    // Wait for the pulse to end
    count = 0;
    while (gpioRead(pin) == level) {
        if (count > timeout) {
            return -1; // Timeout
        }
        gpioDelay(1); // Check every microsecond
        count++;
    }

    end_time = gpioTick();

    pulse_duration = end_time - start_time;
    return pulse_duration;
}

// Function to calculate the distance from the pulse duration
double calculate_distance(long pulse_duration) {
    if (pulse_duration < 0) return -1.0; // Indicate error
    return (double)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map distance to frequency logarithmically
double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Indicate error
    }

    // Logarithmic mapping
    double frequency = MIN_FREQUENCY * pow(MAX_FREQUENCY / MIN_FREQUENCY, (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));
    return frequency;
}

// Function to set the PWM frequency
void set_pwm_frequency(double frequency) {
    if (frequency < 0) return; // Do nothing if frequency is invalid

    int gpio_status = gpioSetPWMfrequency(PWM_PIN, (int)frequency);
    if (gpio_status != 0) {
        fprintf(stderr, "Error setting PWM frequency: %d\n", gpio_status);
    } else {
        last_frequency = frequency; // Update last valid frequency
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range and duty cycle
    gpioSetPWMrange(PWM_PIN, 1000); // Adjust range as needed
    gpioPWM(PWM_PIN, 500);          // 50% duty cycle

    // Set initial PWM frequency
    set_pwm_frequency(MIN_FREQUENCY);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse duration
        long pulse_duration = pulse_in(ECHO_PIN, 1, TIMEOUT_US);

        // Calculate the distance
        double distance = calculate_distance(pulse_duration);

        // Map the distance to a frequency
        double frequency = map_distance_to_frequency(distance);

        // Set the PWM frequency
        if (frequency > 0) {
            set_pwm_frequency(frequency);
        } else {
            set_pwm_frequency(last_frequency); // Use last valid frequency
        }

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Stop PWM
    gpioPWM(PWM_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Theremin terminated.\n");
    return 0;
}

