volatile sig_atomic_t terminate = 0;
double last_valid_distance = 50.0; // Initialize to max distance

// Function prototypes
void triggerSensor();
double measureDistance();
double mapDistanceToFrequency(double distance);
void setBuzzerFrequency(double frequency);
void signalHandler(int signal);

