    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us delay
    gpioWrite(TRIGGER_PIN, 0);

    // Measure the echo pulse duration
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        end_tick = gpioTick();
        diff_tick = end_tick - start_tick;
        if (diff_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        diff_tick = end_tick - start_tick;
        if (diff_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

