// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0 // SPI mode 0
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"
#define MIN_DISTANCE 200
#define MAX_DISTANCE 5000

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(uint16_t *distance);
int log_data(uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Initialize the sensor
int initialize_sensor() {
    // Placeholder for sensor initialization logic
    // Replace with actual initialization sequence from the ICU-20201 datasheet
    // This example just returns success
    printf("Initializing sensor...\n");
    // Add your initialization code here
    return 0; // Success
}

// Read distance from the sensor
int read_distance(uint16_t *distance) {
    char tx_buffer[2] = {0x00, 0x00}; // Example transmit buffer
    char rx_buffer[2] = {0x00, 0x00}; // Example receive buffer

    // Transfer data over SPI
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Failure
    }

    // Convert received data to distance (example conversion)
    *distance = (uint16_t)((rx_buffer[0] << 8) | rx_buffer[1]);

    // Validate distance
    if (*distance < MIN_DISTANCE || *distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Invalid distance value: %d\n", *distance);
        return -1; // Failure
    }

    return 0; // Success
}

// Log data to file
int log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Log data
            if (log_data(distance) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

