#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_DATA0 0x22
#define SI1120_REG_PS_DATA0 0x24
#define SI1120_REG_RESET 0x07

// Si1120 reset command
#define SI1120_RESET_CMD 0x01

// Expected Part ID
#define SI1120_PART_ID 0x20

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1120_init();
int si1120_read_data(uint16_t *als, uint16_t *prox);
void log_data(uint16_t als, uint16_t prox);
void signal_handler(int signal);
char* get_timestamp();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to initialize the Si1120 sensor
int si1120_init() {
    int retries = 3;
    int result;

    // Reset the sensor
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, SI1120_REG_RESET, SI1120_RESET_CMD);
        if (result == 0) break;
        fprintf(stderr, "Error resetting Si1120 (attempt %d): %s\n", 4 - retries, strerror(errno));
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
        return -1;
    }

    gpioDelay(10000); // Wait for reset to complete

    // Verify Part ID
    retries = 3;
    uint8_t part_id;
    while (retries > 0) {
        part_id = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
        if (part_id >= 0) break; // Success
        fprintf(stderr, "Error reading Part ID (attempt %d): %s\n", 4 - retries, strerror(errno));
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read Part ID after multiple retries.\n");
        return -1;
    }

    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Error: Incorrect Part ID (0x%02X, expected 0x%02X)\n", part_id, SI1120_PART_ID);
        return -1;
    }

    printf("Si1120 initialized successfully.\n");
    return 0;
}

// Function to read ALS and proximity data from the Si1120
int si1120_read_data(uint16_t *als, uint16_t *prox) {
    int retries = 3;
    int result;

    // Read ALS data
    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, SI1120_REG_ALS_DATA0);
        if (result >= 0) {
            *als = (uint16_t)result;
            break;
        }
        fprintf(stderr, "Error reading ALS data (attempt %d): %s\n", 4 - retries, strerror(errno));
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
        return -1;
    }

    // Read proximity data
    retries = 3;
    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, SI1120_REG_PS_DATA0);
        if (result >= 0) {
            *prox = (uint16_t)result;
            break;
        }
        fprintf(stderr, "Error reading proximity data (attempt %d): %s\n", 4 - retries, strerror(errno));
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read proximity data after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to log data to a file
void log_data(uint16_t als, uint16_t prox) {
    char *timestamp = get_timestamp();
    fprintf(log_file, "%s, ALS: %u, Proximity: %u\n", timestamp, als, prox);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize Si1120 sensor
    if (si1120_init() != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t als, prox;

    // Main loop
    while (!terminate) {
        if (si1120_read_data(&als, &prox) == 0) {
            log_data(als, prox);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        gpioDelay(500000); // 500ms delay
    }

    // Close resources before exiting
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

