#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_I2C_ADDR 0x60
#define SI1182_PART_ID_REG 0x00
#define SI1182_MEAS_RATE_REG 0x08
#define SI1182_ALS_DATA_REG 0x22
#define SI1182_PS_DATA_REG 0x24

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int si1182_init(int fd);
int read_sensor_data(int fd, float *lux, uint16_t *proximity);
void log_data(FILE *fp, float lux, uint16_t proximity);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
  uint8_t buf[1];
  buf[0] = reg;

  if (write(fd, buf, 1) != 1) {
    fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
    return -1;
  }

  if (read(fd, buf, 1) != 1) {
    fprintf(stderr, "Error reading register value: %s\n", strerror(errno));
    return -1;
  }

  *value = buf[0];
  return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = value;

  if (write(fd, buf, 2) != 2) {
    fprintf(stderr, "Error writing register: %s\n", strerror(errno));
    return -1;
  }

  return 0;
}

// Si1182 initialization function
int si1182_init(int fd) {
  uint8_t part_id;

  // Verify sensor presence
  if (i2c_read_reg(fd, SI1182_PART_ID_REG, &part_id) != 0) {
