// Read sensor data function
int read_sensor_data(int fd, float *lux, uint16_t *proximity) {
  uint8_t als_data[2];
  uint8_t ps_data[2];

  // Read ALS data
  if (i2c_read_reg(fd, SI1182_ALS_DATA_REG, &als_data[0]) != 0) {
    fprintf(stderr, "Error reading ALS Data MSB\n");
    return -1;
  }
  if (i2c_read_reg(fd, SI1182_ALS_DATA_REG + 1, &als_data[1]) != 0) {
    fprintf(stderr, "Error reading ALS Data LSB\n");
    return -1;
  }

  // Read Proximity data
  if (i2c_read_reg(fd, SI1182_PS_DATA_REG, &ps_data[0]) != 0) {
    fprintf(stderr, "Error reading Proximity Data MSB\n");
    return -1;
  }
  if (i2c_read_reg(fd, SI1182_PS_DATA_REG + 1, &ps_data[1]) != 0) {
    fprintf(stderr, "Error reading Proximity Data LSB\n");
    return -1;
  }

  // Combine the bytes to form 16-bit values
  *lux = (float)((als_data[0] << 8) | als_data[1]);
  *proximity = (ps_data[0] << 8) | ps_data[1];

  return 0;
}

