void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        echo_start_tick = tick;
        echo_valid = 0; // Reset validity flag on rising edge
    } else if (level == 0) {
        // Falling edge
        echo_end_tick = tick;
        echo_valid = 1; // Set validity flag on falling edge
    }
}

// Function to calculate distance in centimeters
double calculate_distance(int start_tick, int end_tick) {
    double pulse_width = (double)(end_tick - start_tick); // Pulse width in microseconds
    double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Distance in cm
    return distance;
}

// Function to control the buzzer
void control_buzzer(double distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
    }
}

// Function to print the distance to stdout
void print_distance(double distance) {
    printf("Distance: %.2f cm\n", distance);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set up interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse(); // Generate trigger pulse
        gpioDelay(50); // Wait for echo

        if (echo_valid) {
            double distance = calculate_distance(echo_start_tick, echo_end_tick);
            print_distance(distance);
            control_buzzer(distance);
        } else {
            printf("Invalid echo pulse\n");
        }

        time_sleep(1.0); // Wait for 1 second
    }

    return 0;
}

