// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Constants for distance calculation
#define SOUND_SPEED 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000      // Timeout for echo pulse in microseconds

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to measure distance using the HC-SR04 sensor
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse width
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SOUND_SPEED / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to set the servo angle
void set_servo_angle(int angle) {
    // Map angle (0-180) to pulse width (500-2500 us)
    int pulse_width = (int)(500.0 + (float)angle * (2000.0 / 180.0));
    gpioServo(SERVO_PIN, pulse_width);
}

// Function to map distance to servo angle
int map_distance_to_angle(float distance) {
    // Define the linear relationship between distance and angle
    float slope = (180.0 - 0.0) / (20.0 - 200.0);
    float intercept = 180.0 - slope * 20.0;

    // Calculate the angle
    int angle = (int)(slope * distance + intercept);

    // Clamp the angle to the valid range (0-180)
    if (angle < 0) {
        angle = 0;
    } else if (angle > 180) {
        angle = 180;
    }

    return angle;
}

