#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MODEL_ID_REG 0x00C0
#define TIMING_BUDGET_REG 0x0081
#define DISTANCE_REG 0x0089
#define GPIO_SERVO 18
#define PWM_FREQUENCY 50 // Hz
#define PWM_RANGE 20000   // pigpio range for PWM (0-20000)
#define DISTANCE_CLOSE_THRESHOLD 200 // mm
#define DISTANCE_FAR_THRESHOLD 250   // mm
#define PULSE_WIDTH_CLOSE 2000 // us
#define PULSE_WIDTH_FAR 1000   // us
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(uint16_t *distance);
void set_servo_pulse_width(int pulse_width);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check Model ID
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, MODEL_ID_REG, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading Model ID\n");
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect Model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Set Timing Budget (e.g., 50ms)
    char timing_budget = 0x32; // 50ms
    if (i2cWriteI2CBlockData(i2c_handle, TIMING_BUDGET_REG, &timing_budget, 1) != 1) {
        fprintf(stderr, "Error writing Timing Budget\n");
        return -1;
    }

    return 0;
}

// Read the distance from the VL53L1X sensor
int read_distance(uint16_t *distance) {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buffer, 2) != 2) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }
    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Set the servo pulse width using hardware PWM
void set_servo_pulse_width(int pulse_width) {
    gpioPWM(GPIO_SERVO, pulse_width * PWM_RANGE / 2000); // Convert us to pigpio range (0-20000)
}

// Log an event to the log file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(GPIO_SERVO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_SERVO, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_SERVO, PWM_RANGE);

    // Set initial pulse width (far position)
    set_servo_pulse_width(PULSE_WIDTH_FAR);
    log_event("Gate initialized, starting far position");

    // Install signal handler
    signal(SIGINT, signal_handler);

    uint16_t distance;
    int current_pulse_width = PULSE_WIDTH_FAR;
    int previous_pulse_width = PULSE_WIDTH_FAR;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            int new_pulse_width;

            if (distance < DISTANCE_CLOSE_THRESHOLD) {
                new_pulse_width = PULSE_WIDTH_CLOSE;
            } else if (distance > DISTANCE_FAR_THRESHOLD) {
                new_pulse_width = PULSE_WIDTH_FAR;
            } else {
                // Hysteresis: maintain current position
                new_pulse_width = current_pulse_width;
            }

            // Smooth transition
            if (new_pulse_width != current_pulse_width) {
                int step = (new_pulse_width > current_pulse_width) ? 10 : -10; // Adjust step size as needed
                while (current_pulse_width != new_pulse_width) {
                    current_pulse_width += step;
                    if ((step > 0 && current_pulse_width > new_pulse_width) || (step < 0 && current_pulse_width < new_pulse_width)) {
                        current_pulse_width = new_pulse_width; // Ensure we reach the target
                    }
                    set_servo_pulse_width(current_pulse_width);
                    gpioDelay(10); // Delay for smooth transition
                }

                if (new_pulse_width == PULSE_WIDTH_CLOSE) {
                    log_event("Gate opened");
                } else {
                    log_event("Gate closed");
                }
                previous_pulse_width = current_pulse_width;
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }
        gpioDelay(50); // Delay between readings
    }

    // Cleanup
    set_servo_pulse_width(PULSE_WIDTH_FAR); // Set to far position before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

