#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // 50 ms timeout in microseconds
#define MIN_DISTANCE 2.0       // Minimum valid distance in cm
#define MAX_DISTANCE 400.0     // Maximum valid distance in cm
#define MIN_ANGLE 0.0          // Minimum servo angle in degrees
#define MAX_ANGLE 180.0        // Maximum servo angle in degrees
#define MIN_PULSE_WIDTH 500    // Minimum pulse width in microseconds
#define MAX_PULSE_WIDTH 2500   // Maximum pulse width in microseconds

// Global variables
static volatile int running = 1; // Flag to control the main loop
static volatile uint32_t start_tick = 0; // Timestamp for the rising edge
static volatile uint32_t end_tick = 0;   // Timestamp for the falling edge

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float measure_distance();
float map_distance_to_angle(float distance);
void set_servo_angle(float angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down gracefully...\n");
        running = 0; // Stop the main loop
        set_servo_angle(0.0); // Set servo to 0 degrees
        gpioTerminate(); // Terminate pigpio
        exit(0); // Exit the program
    }
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin high
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin low
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            // Rising edge
            start_tick = tick;
        } else if (level == 0) {
            // Falling edge
            end_tick = tick;
        }
    }
}

// Function to measure distance using the HC-SR04 sensor
float measure_distance() {
    start_tick = 0; // Reset start time
    end_tick = 0;   // Reset end time

    trigger_pulse(); // Send trigger pulse

    // Wait for echo or timeout
    uint32_t start_time = gpioTick();
    while (gpioTick() - start_time < TIMEOUT_US && (start_tick == 0 || end_tick == 0)) {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Check for timeout
    if (start_tick == 0 || end_tick == 0) {
