#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si7005 I2C address
#define SI7005_ADDR 0x40

// Si7005 register addresses
#define CONFIG_REG 0x00
#define TEMP_MSB_REG 0x01
#define TEMP_LSB_REG 0x02
#define HUMID_MSB_REG 0x03
#define HUMID_LSB_REG 0x04

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the Si7005 sensor
int init_si7005() {
    // Configure the sensor for continuous conversion mode
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONFIG_REG\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms
    return 0;
}

// Function to read temperature and humidity data from the Si7005
int read_si7005(float *temperature, float *humidity) {
    unsigned char data[4];

    // Read temperature data
    if (i2cWriteByteData(i2c_handle, TEMP_MSB_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to TEMP_MSB_REG\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms
    if (i2cReadI2CBlockData(i2c_handle, TEMP_MSB_REG, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }
    int temp_raw = (data[0] << 8) | data[1];
    *temperature = (float)temp_raw / 100.0;

    // Read humidity data
    if (i2cWriteByteData(i2c_handle, HUMID_MSB_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to HUMID_MSB_REG\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms
    if (i2cReadI2CBlockData(i2c_handle, HUMID_MSB_REG, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }
    int humid_raw = (data[0] << 8) | data[1];
    *humidity = (float)humid_raw / 100.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si7005() < 0) {
        fprintf(stderr, "Si7005 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_si7005(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            gpioDelay(100000); // Wait 100ms
            i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_si7005() < 0) {
                    fprintf(stderr, "Si7005 re-initialization failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }
        gpioDelay(2000000); // Wait 2 seconds
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

