#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 command for high repeatability measurement
#define SHT40_MEASURE_HIGH 0xFD

// I2C bus number
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle = -1;

// Function prototypes
int i2c_open(int i2c_bus, int i2c_address);
int i2c_write_byte(int i2c_handle, int data);
int i2c_read_device(int i2c_handle, char *buf, int count);
void i2c_close(int i2c_handle);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(uint8_t data[], int len);
int read_sht40(int i2c_handle, float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to open the I2C bus
int i2c_open(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to write a byte to the I2C device
int i2c_write_byte(int i2c_handle, int data) {
    int result = i2cWriteByte(i2c_handle, data);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the I2C device
int i2c_read_device(int i2c_handle, char *buf, int count) {
    int result = i2cReadDevice(i2c_handle, buf, count);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return result;
}

// Function to close the I2C bus
void i2c_close(int i2c_handle) {
    i2cClose(i2c_handle);
}

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate the CRC checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc_calculated = crc8(data, len - 1);
    if (crc_calculated != data[len - 1]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the SHT40 sensor
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];

    // Send measurement command
    if (i2c_write_byte(i2c_handle, SHT40_MEASURE_HIGH) < 0) {
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    if (i2c_read_device(i2c_handle, (char *)data, 6) < 0) {
        return -1;
    }

    // Validate CRC for temperature
    if (validate_crc(data, 3) < 0) {
        return -1;
    }

    // Validate CRC for humidity
    if (validate_crc(data + 3, 3) < 0) {
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    uint16_t temp_raw = (data[0] << 8) | data[1];
    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;

    // Convert raw data to humidity (%RH)
    uint16_t humidity_raw = (data[3] << 8) | data[4];
    *humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Function to log the temperature and humidity data
void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm * timeinfo;
    time (&rawtime);
    timeinfo = localtime (&rawtime);
    char timestamp[80];
    strftime(timestamp,sizeof(timestamp),"%Y-%m-%d %H:%M:%S",timeinfo);
    printf("[%s] Temperature: %.2f °C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    if (i2c_handle >= 0) {
        i2c_close(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        float temperature, humidity;

        // Open I2C bus
        i2c_handle = i2c_open(I2C_BUS, SHT40_ADDR);
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to open I2C bus, retrying in 5 seconds...\n");
            gpioDelay(5000000); // 5 seconds
            continue;
        }

        // Read temperature and humidity
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            // Log the data
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read SHT40 data, retrying in 5 seconds...\n");
        }

        // Close I2C bus
        i2c_close(i2c_handle);
        i2c_handle = -1; // Reset handle

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    return 0;
}

