#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *ambient_temp, float *object_temp);
float convert_to_celsius(unsigned int raw_temp);
int log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from the sensor
int read_temperature(float *ambient_temp, float *object_temp) {
    unsigned int raw_ambient, raw_object;

    raw_ambient = i2cReadWordData(i2c_handle, AMBIENT_TEMP_REG);
    if (raw_ambient < 0) {
        fprintf(stderr, "Error reading ambient temperature: %d\n", raw_ambient);
        return -1;
    }

    raw_object = i2cReadWordData(i2c_handle, OBJECT_TEMP_REG);
    if (raw_object < 0) {
        fprintf(stderr, "Error reading object temperature: %d\n", raw_object);
        return -1;
    }

    *ambient_temp = convert_to_celsius(raw_ambient);
    *object_temp = convert_to_celsius(raw_object);

    return 0;
}

// Convert raw temperature to Celsius
float convert_to_celsius(unsigned int raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Log temperature to file
int log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float ambient_temp, object_temp;

    // Main loop
    while (!terminate) {
        if (read_temperature(&ambient_temp, &object_temp) == 0) {
            if (log_temperature(ambient_temp, object_temp) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, retrying I2C initialization...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

