// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_HIGH_REP 0x2C06
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sts30(float *temperature);
void log_temperature(float temperature);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for grouping I2C data
typedef struct {
    int handle;
    int bus;
    int address;
} I2CConfig;

// Structure for grouping file data
typedef struct {
    FILE *log_file;
    FILE *error_file;
} FileConfig;

I2CConfig i2c_config = { .handle = -1, .bus = I2C_BUS, .address = STS30_ADDR };
FileConfig file_config = { .log_file = NULL, .error_file = NULL };

// Function to initialize I2C
int init_i2c() {
    i2c_config.handle = i2cOpen(i2c_config.bus, i2c_config.address, 0);
    if (i2c_config.handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Function to read temperature from STS30
int read_sts30(float *temperature) {
    char cmd[2] = {(MEASURE_HIGH_REP >> 8) & 0xFF, MEASURE_HIGH_REP & 0xFF};
    char buf[6];
    int result;

    result = i2cWriteDevice(i2c_config.handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return -1;
    }

    gpioDelay(20); // Wait for measurement (datasheet specifies 15ms)

    result = i2cReadDevice(i2c_config.handle, buf, 6);
    if (result != 6) {
        log_error("Failed to read temperature data");
        return -1;
    }

    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);

    return 0;
}

