#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_CMD 0x362F
#define DATA_FRAME_SIZE 9
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc8(const uint8_t *data, size_t len);
int validate_crc(const uint8_t *data, size_t len);
int parse_sensor_data(const uint8_t *data, sensor_data_t *sensor_data);
int log_data(const sensor_data_t *sensor_data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = calculate_crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the sensor for continuous measurement
int configure_sensor() {
    uint8_t cmd[2] = {(MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to configure sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_FRAME_SIZE);
    if (result != DATA_FRAME_SIZE) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Parse sensor data
int parse_sensor_data(const uint8_t *data, sensor_data_t *sensor_data) {
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor = (data[6] << 8) | data[7];

    // Extract scale factor
    float scale_factor = (float)raw_scale_factor / 65536.0f;

    // Convert to physical units
    sensor_data->pressure = (float)raw_pressure * scale_factor;
    sensor_data->temperature = (float)raw_temperature * scale_factor;

    return 0;
}

// Log data to file
int log_data(const sensor_data_t *sensor_data) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure,temperature\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, sensor_data->pressure, sensor_data->temperature);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t data[DATA_FRAME_SIZE];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        uint8_t cmd[2] = {0x00, 0x00}; // Dummy command to trigger measurement
        i2cWriteDevice(i2c_handle, (char *)cmd, 2);

        // Wait for at least 1 ms
        gpioDelay(1000); // 1000 microseconds = 1 millisecond

        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate CRC for pressure
            if (validate_crc(data, 3)) {
                // Validate CRC for temperature
                if (validate_crc(data + 3, 3)) {
                    // Validate CRC for scale factor
                    if (validate_crc(data + 6, 3)) {
                        // Parse sensor data
                        if (parse_sensor_data(data, &sensor_data) == 0) {
                            // Log data
                            log_data(&sensor_data);
                        } else {
                            fprintf(stderr, "Failed to parse sensor data\n");
                        }
                    } else {
                        fprintf(stderr, "CRC validation failed for scale factor\n");
                    }
                } else {
                    fprintf(stderr, "CRC validation failed for temperature\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed for pressure\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

