    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Function to convert raw humidity data to relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Function to log data to file and console
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI7015_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint16_t raw_temp, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_sensor_data(i2c_handle, TEMP_CMD, &raw_temp) == 0) {
            temperature = convert_temperature(raw_temp);
        } else {
            temperature = -999.0; // Indicate error
        }

        // Read humidity
        if (read_sensor_data(i2c_handle, HUMID_CMD, &raw_humidity) == 0) {
            humidity = convert_humidity(raw_humidity);
        } else {
            humidity = -999.0; // Indicate error
        }

        // Log data
        if (temperature != -999.0 && humidity != -999.0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

