// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define TRIGGER_COMMAND 0x362F
#define DATA_LENGTH 9
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
int validate_crc(uint8_t data[], uint8_t crc);
SensorData process_sensor_data(uint8_t *data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to trigger continuous measurement
int trigger_measurement() {
    uint8_t command[2] = {(TRIGGER_COMMAND >> 8) & 0xFF, TRIGGER_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

