    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");

    // Trigger measurement
    if (trigger_measurement() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    uint8_t sensor_data[DATA_LENGTH];
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, sensor_data[2]) &&
                validate_crc(sensor_data + 3, sensor_data[5]) &&
                validate_crc(sensor_data + 6, sensor_data[8])) {

                // Process sensor data
                SensorData processed_data = process_sensor_data(sensor_data);

                // Log data
                log_data(processed_data);
            } else {
                fprintf(stderr, "CRC validation failed!\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

