        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t raw_temperature;
        float temperature;

        // Trigger measurement
        if (sts30_trigger_measurement(i2c_handle) != 0) {
            log_error("Failed to trigger measurement");
            continue; // Retry
        }

        // Wait for conversion (at least 15ms)
        gpioDelay(15000); // 15ms

        // Read measurement
        if (sts30_read_measurement(i2c_handle, &raw_temperature) != 0) {
            log_error("Failed to read measurement");
            continue; // Retry
        }

        // Convert temperature
        temperature = convert_temperature(raw_temperature);

        // Log temperature
        if (log_temperature(temperature) != 0) {
            log_error("Failed to log temperature");
        }

        // Wait before next measurement (e.g., 5 seconds)
        gpioDelay(5000000); // 5 seconds
    }

    return 0;
}

// Initialize I2C
int i2c_init(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "Failed to open I2C device: %d", handle);
        log_error(error_message);
        return -1;
    }
    return handle;
}

// Write data to I2C
int i2c_write(int handle, const char *data, int count) {
    int result = i2cWriteDevice(handle, data, count);
    if (result != count) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "I2C write failed: %d", result);
        log_error(error_message);
        return -1;
    }
    return 0;
}

// Read data from I2C
int i2c_read(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "I2C read failed: %d", result);
        log_error(error_message);
        return -1;
    }
    return 0;
}

// Trigger a single-shot high repeatability measurement
int sts30_trigger_measurement(int handle) {
    char cmd[2] = {STS30_MEASURE_CMD_MSB, STS30_MEASURE_CMD_LSB};
    return i2c_write(handle, cmd, 2);
}

// Read the temperature measurement
int sts30_read_measurement(int handle, uint16_t *temperature) {
    char data[3];

    if (i2c_read(handle, data, 3) != 0) {
        return -1;
    }

    // CRC check
    if (crc8((uint8_t *)data, 2) != data[2]) {
        log_error("CRC check failed");
        return -1;
    }

    *temperature = (data[0] << 8) | data[1];
    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return -45.0 + (175.0 * (float)raw_temperature / 65535.0);
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (temp_log_file != NULL) {
        fprintf(temp_log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(temp_log_file); // Ensure data is written immediately
        return 0;
    } else {
        return -1;
    }
}

// Log error to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s, %s\n", timestamp, message);
        fflush(error_log_file); // Ensure data is written immediately
        return 0;
    } else {
        return -1;
    }
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log files
    if (temp_log_file != NULL) {
        fclose(temp_log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

