int i2c_handle = -1;
FILE *log_file = NULL;

// CRC-8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sht40(sensor_data_t *data);
uint8_t crc8(const uint8_t *data, size_t len);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // I2C bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from SHT40
int read_sht40(sensor_data_t *data) {
    uint8_t buf[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 8.5 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate CRC for temperature
    uint8_t temp_data[2] = {buf[0], buf[1]};
    uint8_t temp_crc = buf[2];
    if (crc8(temp_data, 2) != temp_crc) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Validate CRC for humidity
    uint8_t hum_data[2] = {buf[3], buf[4]};
    uint8_t hum_crc = buf[5];
    if (crc8(hum_data, 2) != hum_crc) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    data->temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;

    // Convert raw data to humidity (%RH)
    uint16_t hum_raw = (buf[3] << 8) | buf[4];
    data->humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

