#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Structure for storing temperature readings and timestamps
typedef struct {
    float temperature;
    time_t timestamp;
} Reading;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
float read_temperature();
void control_fan(float temperature);
void add_reading(float temperature);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from the Si7021 sensor
float read_temperature() {
    unsigned char cmd[1] = {0xE3}; // Command to measure temperature, no hold master
    unsigned char data[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, cmd, 1);
        if (result == 0) {
            gpioDelay(50); // Wait for measurement (datasheet specifies 20ms)
            result = i2cReadDevice(i2c_handle, data, 2);
            if (result == 2) {
                // Convert raw data to temperature (Celsius)
                unsigned int raw_temperature = (data[0] << 8) | data[1];
                float temperature = (175.72 * raw_temperature / 65536.0) - 46.85;
                return temperature;
            } else {
                fprintf(stderr, "Error reading temperature data: %d\n", result);
            }
        } else {
            fprintf(stderr, "Error writing temperature command: %d\n", result);
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS);
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
    return -100.0; // Indicate error
}

// Function to control the cooling fan
void control_fan(float temperature) {
    static int fan_on = 0; // Track fan state

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON\n");
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

