    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially off

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -99.0) { // Check for valid temperature reading
            printf("Temperature: %.2f °C\n", temperature);
            add_reading(temperature);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Check sensor connection.\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

