#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xE4B8
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int len);
int verify_crc(uint8_t data[], int len, uint8_t crc);
int read_scd40_data(int handle, sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the SCD40
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Function to read data from the SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to verify CRC checksum
int verify_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC check failed: calculated 0x%02X, received 0x%02X\n", calculated_crc, crc);
        return -1;
    }
    return 0;
}

// Function to read CO2, temperature, and humidity data from the SCD40
int read_scd40_data(int handle, sensor_data_t *data) {
    uint8_t read_ready_cmd[2] = {0xE4, 0xB8};
    uint8_t data_ready_flag[3];
    uint8_t sensor_data[9];

    // Check data ready flag
    if (send_command(handle, CMD_READ_MEASUREMENT) != 0) {
        return -1;
    }
    gpioDelay(1); // Small delay after sending the command

    if (read_data(handle, data_ready_flag, 3) != 0) {
        return -1;
    }

    if (data_ready_flag[2] != 0x00) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    // Read sensor data
    if (send_command(handle, CMD_READ_MEASUREMENT) != 0) {
        return -1;
    }
    gpioDelay(1); // Small delay after sending the command

    if (read_data(handle, sensor_data, 9) != 0) {
        return -1;
    }

    // Verify CRC for CO2
    if (verify_crc(sensor_data, 2, sensor_data[2]) != 0) {
        return -1;
    }

    // Verify CRC for Temperature
    if (verify_crc(sensor_data + 3, 2, sensor_data[5]) != 0) {
        return -1;
    }

    // Verify CRC for Humidity
    if (verify_crc(sensor_data + 6, 2, sensor_data[8]) != 0) {
        return -1;
    }

    // Extract data
    data->co2 = (sensor_data[0] << 8) | sensor_data[1];
    data->temperature = -45 + 175 * ((float)((sensor_data[3] << 8) | sensor_data[4])) / 65535;
    data->humidity = 100 * ((float)((sensor_data[6] << 8) | sensor_data[7])) / 65535;

    return 0;
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait for the first measurement

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_scd40_data(i2c_handle, &sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(5000); // Wait 5 seconds
    }

    // Stop periodic measurement
    if (send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

