#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// SCD40 I2C address
#define SCD40_I2C_ADDRESS 0x62

// GPIO pin for CO2 warning LED
#define CO2_WARNING_LED_PIN 17

// Circular buffer size
#define CIRCULAR_BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_scd40();
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, size_t len);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
sensor_data_t get_latest_data(const circular_buffer_t *buffer);
void control_led(int co2_level);
void signal_handler(int signal);
void stop_scd40();

// Initialize the circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, SCD40_I2C_ADDRESS, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize SCD40 sensor
int init_scd40() {
    // Start periodic measurement command
    uint8_t start_measurement_cmd[] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, (char *)start_measurement_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for the command to be processed
    return 0;
}

// Read data from SCD40 sensor
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t read_measurement_cmd[] = {0xE4, 0xB8};
    uint8_t data[9];
    int result;

    // Send read measurement command
    result = i2cWriteDevice(i2c_handle, (char *)read_measurement_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending read measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait for the command to be processed

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Validate CRC for each 2-byte data word
    if (crc8(data, 2) != data[2] ||
        crc8(data + 3, 2) != data[5] ||
        crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract CO2, temperature, and humidity values
    *co2 = (uint16_t)data[0] << 8 | data[1];
    *temperature = -45 + 175 * ((float)((uint16_t)data[3] << 8 | data[4])) / 65535;
    *humidity = 100 * ((float)((uint16_t)data[6] << 8 | data[7])) / 65535;

    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    size_t i, j;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % CIRCULAR_BUFFER_SIZE;
    if (buffer->count < CIRCULAR_BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get the latest data from the circular buffer
sensor_data_t get_latest_data(const circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        // Return a default value if the buffer is empty
        sensor_data_t default_data = {0, 0.0, 0.0};
        return default_data;
    }
    int index = (buffer->head - 1 + CIRCULAR_BUFFER_SIZE) % CIRCULAR_BUFFER_SIZE;
    return buffer->data[index];
}

// Control the CO2 warning LED
void control_led(int co2_level) {
    if (co2_level > 1000) {
        gpioWrite(CO2_WARNING_LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(CO2_WARNING_LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Stop SCD40 measurement
void stop_scd40() {
    uint8_t stop_measurement_cmd[] = {0x3F, 0x86};
    int result = i2cWriteDevice(i2c_handle, (char *)stop_measurement_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error stopping periodic measurement: %d\n", result);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(CO2_WARNING_LED_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
