    if (init_scd40() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&buffer);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t co2;
    float temperature;
    float humidity;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read data from SCD40 sensor
        if (read_scd40_data(&co2, &temperature, &humidity) == 0) {
            // Print the data
            printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", co2, temperature, humidity);

            // Add data to the circular buffer
            sensor_data.co2 = co2;
            sensor_data.temperature = temperature;
            sensor_data.humidity = humidity;
            add_to_buffer(&buffer, sensor_data);

            // Control the LED
            control_led(co2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Stop SCD40 measurement
    stop_scd40();

    // Close I2C handle
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(CO2_WARNING_LED_PIN, 0); // Turn LED off
    gpioSetMode(CO2_WARNING_LED_PIN, PI_INPUT); // Set back to input

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

