#define MIN_TEMP -40.0
#define MAX_TEMP 150.0
#define MAX_FAILURES 3

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int failure_count = 0;

// Structure to hold timestamps
typedef struct {
    uint32_t rising_edge;
    uint32_t falling_edge;
    uint32_t total_cycle;
} pulse_data_t;

// Function prototypes
int initialize_gpio();
pulse_data_t measure_pulse_width();
float calculate_temperature(pulse_data_t pulse_data);
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

// Measure pulse width
pulse_data_t measure_pulse_width() {
    pulse_data_t pulse_data = {0, 0, 0};
    uint32_t start_tick, end_tick, current_tick;
    int timeout_count = 0;

    // Wait for rising edge with timeout
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0 && running) {
        current_tick = gpioTick();
        if (current_tick - start_tick > TIMEOUT_US) {
            timeout_count++;
            if (timeout_count > 10) { // Retry multiple times
                pulse_data.rising_edge = 0; // Indicate timeout
                return pulse_data;
            }
            gpioDelay(1); // Small delay before retrying
            start_tick = gpioTick();
        }
    }

    if (!running) {
        pulse_data.rising_edge = 0;
        return pulse_data;
    }

    pulse_data.rising_edge = gpioTick();

    // Wait for falling edge with timeout
    start_tick = gpioTick();
    timeout_count = 0;
    while (gpioRead(GPIO_PIN) == 1 && running) {
        current_tick = gpioTick();
        if (current_tick - start_tick > TIMEOUT_US) {
            timeout_count++;
            if (timeout_count > 10) { // Retry multiple times
                pulse_data.falling_edge = 0; // Indicate timeout
                return pulse_data;
            }
            gpioDelay(1); // Small delay before retrying
            start_tick = gpioTick();
        }
    }

    if (!running) {
        pulse_data.falling_edge = 0;
        return pulse_data;
    }

    pulse_data.falling_edge = gpioTick();

    // Calculate total cycle width
    end_tick = gpioTick();
    pulse_data.total_cycle = end_tick - pulse_data.rising_edge;

    return pulse_data;
}

// Calculate temperature
float calculate_temperature(pulse_data_t pulse_data) {
    float temperature = -999.0; // Default error value

    if (pulse_data.rising_edge == 0 || pulse_data.falling_edge == 0 || pulse_data.total_cycle == 0) {
        return -999.0; // Indicate error
    }

    uint32_t high_time = pulse_data.falling_edge - pulse_data.rising_edge;
    uint32_t low_time = pulse_data.total_cycle - high_time;

    if (low_time == 0) {
        fprintf(stderr, "Error: Low time is zero, cannot divide.\n");
        return -999.0;
    }

    temperature = (float)high_time / (float)low_time * 100.0;

    return temperature;
}

// Log temperature
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (temperature >= MIN_TEMP && temperature <= MAX_TEMP) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to file immediately
        printf("%s, %.2f\n", timestamp, temperature);
    } else {
        fprintf(log_file, "%s, ERROR: Temperature out of range (%.2f)\n", timestamp, temperature);
        fflush(log_file);
        printf("%s, ERROR: Temperature out of range (%.2f)\n", timestamp, temperature);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        pulse_data_t pulse_data = measure_pulse_width();

        if (pulse_data.rising_edge == 0 || pulse_data.falling_edge == 0 || pulse_data.total_cycle == 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s, ERROR: Timeout waiting for pulse.\n", timestamp);
            fflush(log_file);
            printf("%s, ERROR: Timeout waiting for pulse.\n", timestamp);
            failure_count++;
        } else {
            float temperature = calculate_temperature(pulse_data);

            if (temperature == -999.0) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[30];

                time(&rawtime);
                timeinfo = gmtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                fprintf(log_file, "%s, ERROR: Temperature calculation failed.\n", timestamp);
                fflush(log_file);
                printf("%s, ERROR: Temperature calculation failed.\n", timestamp);
                failure_count++;
            } else {
                log_temperature(temperature);
                failure_count = 0; // Reset failure count on success
            }
        }

        if (failure_count >= MAX_FAILURES) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s, SENSOR MALFUNCTION\n", timestamp);
            fflush(log_file);
            printf("%s, SENSOR MALFUNCTION\n", timestamp);
            failure_count = 0; // Reset failure count after logging
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay for sample interval
    }

    // Cleanup and exit
    cleanup();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

