#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define LOG_FILE "environmental_data.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 1000
#define SAMPLE_INTERVAL_S 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize();
int read_sensor_data(uint16_t *temperature, uint16_t *humidity);
uint8_t calculate_crc(const uint8_t data[], int nbrOfBytes);
SensorData process_sensor_data(uint16_t raw_temperature, uint16_t raw_humidity);
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity data from the sensor
int read_sensor_data(uint16_t *temperature, uint16_t *humidity) {
    char cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    char buffer[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }

    gpioDelay(15); // Wait for at least 15ms

    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    // Extract temperature and humidity
    *temperature = (buffer[0] << 8) | buffer[1];
    *humidity = (buffer[3] << 8) | buffer[4];

    return 0;
}

// Function to calculate the CRC checksum
uint8_t calculate_crc(const uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Function to process raw sensor data and apply sinusoidal offset
SensorData process_sensor_data(uint16_t raw_temperature, uint16_t raw_humidity) {
    SensorData data;
    float temperature, humidity;
    time_t now = time(NULL);
    double time_elapsed = difftime(now, (time_t)0); // Use epoch time for offset calculation

    // Convert raw temperature to Celsius
    temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);

    // Convert raw humidity to percent relative humidity
    humidity = 100.0 * (float)raw_humidity / 65535.0;

    // Apply sinusoidal offset
    temperature += 2.0 * sin(2 * M_PI * time_elapsed / 3600.0); // 2 degrees offset over 1 hour
    humidity += 5.0 * sin(2 * M_PI * time_elapsed / 3600.0);    // 5% RH offset over 1 hour

    data.temperature = temperature;
    data.humidity = humidity;

    return data;
}

// Function to log data to a file
void log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    uint16_t raw_temperature, raw_humidity;
    SensorData data;
    int retries;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    fprintf(stdout, "Environmental data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        retries = 0;
        result = -1; // Initialize to failure

        while (retries < RETRY_COUNT && result != 0) {
            result = read_sensor_data(&raw_temperature, &raw_humidity);
            if (result != 0) {
                fprintf(stderr, "Read failed, retrying (%d/%d)\n", retries + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS);
                retries++;
            }
        }

        if (result == 0) {
            // CRC Check
            uint8_t data_temp[2] = {raw_temperature >> 8, raw_temperature & 0xFF};
            uint8_t data_hum[2] = {raw_humidity >> 8, raw_humidity & 0xFF};

            uint8_t crc_temp = calculate_crc(data_temp, 2);
            uint8_t crc_hum = calculate_crc(data_hum, 2);

            if (crc_temp != ((uint8_t)((raw_temperature >> 8) & 0xFF)) || crc_hum != ((uint8_t)((raw_humidity >> 8) & 0xFF))) {
                fprintf(stderr, "CRC check failed\n");
                data.temperature = NAN;
                data.humidity = NAN;
            } else {
                data = process_sensor_data(raw_temperature, raw_humidity);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after multiple retries\n");
            data.temperature = NAN;
            data.humidity = NAN;
        }

        log_data(data);
        gpioDelay(SAMPLE_INTERVAL_S * 1000); // Delay for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    fprintf(stdout, "Environmental data logger stopped.\n");
    return 0;
}

