#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_CMD 0x362F
#define CSV_FILE "airflow.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// CRC-8 lookup table
const uint8_t crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xC4, 0xF5, 0xA6, 0x97, 0xB9, 0x88, 0xDB, 0xEA, 0x7D, 0x4C, 0x1F, 0x2E
};

// Function prototypes
int init_i2c();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc8(const uint8_t *data, size_t len);
int validate_crc(const uint8_t *data, size_t len);
int convert_data(const uint8_t *data, float *pressure, float *temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int16_t pressure_raw;
    int16_t temperature_raw;
    uint16_t scale_factor;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    rewind(csv_file);

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        float pressure, temperature;

        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue; // Retry
        }

        // Wait for conversion time
        gpioDelay(45000); // 45 ms

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue; // Retry
        }

        // Validate CRC
        if (validate_crc(data, 9) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Retry
        }

        // Convert data
        if (convert_data(data, &pressure, &temperature) != 0) {
            fprintf(stderr, "Data conversion failed\n");
            continue; // Retry
        }

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    uint8_t cmd[2] = {(MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return 1;
    }
    return 0;
}

