#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define HUMID_MEASURE_CMD 0xE5
#define RESET_CMD 0xFE
#define CRC_POLYNOMIAL 0x98
#define CRC_INIT 0x00
#define LOG_FILE "environment.log"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(int i2c_bus, int i2c_address);
int i2c_read_bytes(int i2c_handle, char *buffer, int count);
int i2c_write_byte(int i2c_handle, char data);
void i2c_close(int i2c_handle);
int read_temperature(int i2c_handle, float *temperature);
int read_humidity(int i2c_handle, float *humidity);
uint8_t calculate_crc(uint8_t data[], int len);
void log_data(const char *timestamp, const char *temperature, const char *humidity);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Function to open the I2C device
int i2c_open(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "ERROR: Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read bytes from the I2C device
int i2c_read_bytes(int i2c_handle, char *buffer, int count) {
    int bytes_read = i2cReadDevice(i2c_handle, buffer, count);
    if (bytes_read != count) {
        fprintf(stderr, "ERROR: Failed to read %d bytes from I2C device: %d\n", count, bytes_read);
        return -1;
    }
    return bytes_read;
}

// Function to write a byte to the I2C device
int i2c_write_byte(int i2c_handle, char data) {
    int result = i2cWriteDevice(i2c_handle, &data, 1);
    if (result != 0) {
        fprintf(stderr, "ERROR: Failed to write byte to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to close the I2C device
void i2c_close(int i2c_handle) {
    i2cClose(i2c_handle);
}

// Function to read temperature from the Si7021 sensor
int read_temperature(int i2c_handle, float *temperature) {
    char buffer[3];
    int retries = 3;

    while (retries > 0) {
        if (i2c_write_byte(i2c_handle, TEMP_MEASURE_CMD) != 0) {
            fprintf(stderr, "ERROR: Failed to write temperature measurement command.\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        gpioDelay(50000); // Wait for measurement (50ms)

        if (i2c_read_bytes(i2c_handle, buffer, 3) != 3) {
            fprintf(stderr, "ERROR: Failed to read temperature data.\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        uint8_t crc = buffer[2];
        uint8_t data[2] = {buffer[0], buffer[1]};
        uint8_t calculated_crc = calculate_crc(data, 2);

        if (crc != calculated_crc) {
            fprintf(stderr, "ERROR: Temperature CRC check failed. Expected 0x%02X, got 0x%02X\n", crc, calculated_crc);
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        uint16_t raw_temperature = (buffer[0] << 8) | buffer[1];
        *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;
        return 0; // Success
    }

    fprintf(stderr, "ERROR: Failed to read temperature after multiple retries.\n");
    return -1; // Failure
}

// Function to read humidity from the Si7021 sensor
int read_humidity(int i2c_handle, float *humidity) {
    char buffer[3];
    int retries = 3;

    while (retries > 0) {
        if (i2c_write_byte(i2c_handle, HUMID_MEASURE_CMD) != 0) {
            fprintf(stderr, "ERROR: Failed to write humidity measurement command.\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        gpioDelay(50000); // Wait for measurement (50ms)

        if (i2c_read_bytes(i2c_handle, buffer, 3) != 3) {
            fprintf(stderr, "ERROR: Failed to read humidity data.\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
