#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define SAMPLE_DELAY_MS 1000
#define DATA_FILE "airflow.dat"

// Global variables
int i2c_handle = -1;
FILE *data_file = NULL;
volatile sig_atomic_t terminate = 0;

// CRC-8 lookup table
const uint8_t crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xC4, 0xF5, 0xA6, 0x97, 0xB9, 0x88, 0xDB, 0xEA, 0x7D, 0x4C, 0x1F, 0x2E
};

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *buffer, int count);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len, uint8_t crc);
int16_t convert_pressure(uint8_t msb, uint8_t lsb);
float convert_temperature(uint8_t msb, uint8_t lsb);
int log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Write command to the sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *buffer, int count) {
    int result = i2cReadDevice(handle, (char *)buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        crc = (crc >> 4) ^ crc8_table[crc & 0x0F];
        crc = (crc >> 4) ^ crc8_table[crc & 0x0F];
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Convert raw pressure data to Pascals
int16_t convert_pressure(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

// Convert raw temperature data to Celsius
float convert_temperature(uint8_t msb, uint8_t lsb) {
    int16_t raw_temperature = (int16_t)((msb << 8) | lsb);
    return (float)raw_temperature / 200.0f;
}

// Log data to file
int log_data(float pressure, float temperature) {
    size_t elements_written = fwrite(&pressure, sizeof(float), 1, data_file);
    elements_written += fwrite(&temperature, sizeof(float), 1, data_file);

    if (elements_written != 2) {
        fprintf(stderr, "Failed to write data to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Open data file in append binary mode
    data_file = fopen(DATA_FILE, "ab");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (write_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for conversion time (adjust as needed)
        gpioDelay(50); // 50ms delay

        // Read data from sensor
        uint8_t data[9];
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC for pressure
        if (!validate_crc(data, 2, data[2])) {
            fprintf(stderr, "Pressure CRC validation failed\n");
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(data + 3, 2, data[5])) {
            fprintf(stderr, "Temperature CRC validation failed\n");
            continue;
        }

        // Convert data
        int16_t raw_pressure = convert_pressure(data[0], data[1]);
        float temperature = convert_temperature(data[3], data[4]);
        float pressure = (float)raw_pressure / 10.0f; // Scale pressure to Pa

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait before next sample
        gpioDelay(SAMPLE_DELAY_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

