#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, uint16_t *raw_data);
float convert_to_pressure(uint16_t raw_data);
float calculate_flow_rate(float pressure);
int set_fan_speed(int gpio, float flow_rate);
int log_data(FILE *log_file, float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to read sensor data from I2C
int read_sensor_data(int i2c_handle, uint16_t *raw_data) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *raw_data = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw data to pressure (Pa)
float convert_to_pressure(uint16_t raw_data) {
    // Assuming a linear relationship between raw data and pressure
    // This needs to be calibrated based on the sensor's datasheet
    // Example: 0 raw = 0 Pa, 65535 raw = 100 Pa
    return (float)raw_data * (100.0 / 65535.0);
}

// Function to calculate flow rate (LPM) from pressure (Pa)
float calculate_flow_rate(float pressure) {
    // Assuming a linear relationship between pressure and flow rate
    // This needs to be calibrated based on the sensor's datasheet
    // Example: 0 Pa = 0 LPM, 100 Pa = 10 LPM
    return pressure * (10.0 / 100.0);
}

// Function to set fan speed using hardware PWM
int set_fan_speed(int gpio, float flow_rate) {
    // Map flow rate to PWM duty cycle (0-1000000)
    int duty_cycle = (int)(flow_rate * (1000000.0 / 10.0)); // Assuming max flow rate is 10 LPM

    // Clamp duty cycle to 0-1000000
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 1000000) {
        duty_cycle = 1000000;
    }

    gpioPWM(gpio, duty_cycle);
    return 0;
}

// Function to log data to file
int log_data(FILE *log_file, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x28, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_data;
    float pressure, flow_rate;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &raw_data) == 0) {
            // Convert to pressure
            pressure = convert_to_pressure(raw_data);

            // Calculate flow rate
            flow_rate = calculate_flow_rate(pressure);

            // Set fan speed
            set_fan_speed(FAN_GPIO, flow_rate);

            // Log data
            log_data(log_file, pressure);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    gpioPWM(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

