#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5C

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
static volatile sig_atomic_t terminate = 0;
static int i2c_handle;
static FILE *log_file;

// Signal handler for SIGINT
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the LPS33HW sensor
int init_lps33hw(int i2c_handle) {
    // Enable continuous data acquisition (ODR = 1 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x10) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read pressure and temperature data from the LPS33HW sensor
int read_lps33hw(int i2c_handle, float *pressure, float *temperature) {
    char buffer[5];
    int32_t raw_pressure;
    int16_t raw_temperature;

    // Read pressure data (3 bytes)
    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3) != 3) {
        fprintf(stderr, "Error reading pressure data: %s\n", strerror(errno));
        return -1;
    }

    raw_pressure = (int32_t)buffer[0] | ((int32_t)buffer[1] << 8) | ((int32_t)buffer[2] << 16);
    *pressure = (float)raw_pressure / 4096.0; // Convert to hPa

    // Read temperature data (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }

    raw_temperature = (int16_t)buffer[0] | ((int16_t)buffer[1] << 8);
    *temperature = (float)raw_temperature / 100.0; // Convert to °C

    return 0;
}

// Function to log data to a file
void log_data(FILE *log_file, float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm time_info;
    char timestamp[20];

    localtime_r(&now, &time_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &time_info);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    float pressure, temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5C, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the LPS33HW sensor
    if (init_lps33hw(i2c_handle) < 0) {
        fprintf(stderr, "LPS33HW initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read pressure and temperature data
        if (read_lps33hw(i2c_handle, &pressure, &temperature) == 0) {
            // Log the data
            log_data(log_file, pressure, temperature);
        } else {
            time_t now = time(NULL);
            struct tm time_info;
            char timestamp[20];

            localtime_r(&now, &time_info);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &time_info);

            fprintf(stderr, "%s, Error reading sensor data.\n", timestamp);
            fprintf(log_file, "%s, Error reading sensor data.\n", timestamp);
            fflush(log_file);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

