#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(float average_temperature);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from STLM75 sensor
float read_temperature() {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", bytes_read);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert the raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = (float)(raw_temp >> 5) * 0.125;

    return temperature;
}

// Add temperature reading to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the running average of the temperature readings
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control the LED based on the average temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer temp_buffer;
    init_circular_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();

        // If temperature reading was successful, add to buffer and calculate average
        if (temperature > -999.0) {
            add_to_buffer(&temp_buffer, temperature);
            float average_temperature = calculate_average(&temp_buffer);

            // Control LED
            control_led(average_temperature);

            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping this iteration.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

