#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define SCD30_CMD_GET_DATA_READY 0x0202

// Global variables
int i2c_handle;
FILE *log_file;
bool running = true;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int write_command(int command);
int read_data(float *co2, float *temperature, float *humidity);
int get_data_ready();
int stop_periodic_measurement();
int log_data(float co2, float temperature, float humidity);
void signal_handler(int signal);
void cleanup();
unsigned char crc8(const unsigned char *data, int len);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0); // Bus 1, address 0x61, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to write a command to the SCD30
int write_command(int command) {
    unsigned char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Function to read data from the SCD30
int read_data(float *co2, float *temperature, float *humidity) {
    unsigned char buf[18];
    int result = i2cReadDevice(i2c_handle, (char *)buf, 18);
    if (result != 18) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // CRC check
    for (int i = 0; i < 6; i++) {
        unsigned char data[2];
        data[0] = buf[i * 3];
        data[1] = buf[i * 3 + 1];
        unsigned char crc = buf[i * 3 + 2];
        if (crc8(data, 2) != crc) {
            fprintf(stderr, "CRC mismatch for data %d\n", i);
            return -1;
        }
    }

    // Convert data to float
    unsigned int co2_int = (buf[0] << 8) | buf[1];
    unsigned int temperature_int = (buf[3] << 8) | buf[4];
    unsigned int humidity_int = (buf[6] << 8) | buf[7];

    *co2 = *((float *)&co2_int);
    *temperature = *((float *)&temperature_int);
    *humidity = *((float *)&humidity_int);

    return 0;
}

// Function to get data ready status
int get_data_ready() {
    unsigned char buf[2];
    buf[0] = (SCD30_CMD_GET_DATA_READY >> 8) & 0xFF;
    buf[1] = SCD30_CMD_GET_DATA_READY & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write data ready command: %d\n", result);
        return -1;
    }

    unsigned char read_buf[3];
    result = i2cReadDevice(i2c_handle, (char *)read_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read data ready status: %d\n", result);
        return -1;
    }

    unsigned char data[2];
    data[0] = read_buf[0];
    data[1] = read_buf[1];
    unsigned char crc = read_buf[2];

    if (crc8(data, 2) != crc) {
        fprintf(stderr, "CRC mismatch for data ready status\n");
        return -1;
    }

    unsigned int ready = (read_buf[0] << 8) | read_buf[1];
    return ready;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    return write_command(SCD30_CMD_STOP_PERIODIC_MEASUREMENT);
}

// Function to log data to a file
int log_data(float co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

// Cleanup function
void cleanup() {
    stop_periodic_measurement();
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

// CRC8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (write_command(SCD30_CMD_START_PERIODIC_MEASUREMENT) != 0) {
        cleanup();
        return 1;
    }

    float co2, temperature, humidity;
    int data_ready;

    // Main loop
    while (running) {
        data_ready = get_data_ready();
        if (data_ready > 0) {
            if (read_data(&co2, &temperature, &humidity) == 0) {
                log_data(co2, temperature, humidity);

                // Ventilation control logic
                if (co2 < 800) {
                    printf("Ventilation: OFF\n");
                } else if (co2 >= 800 && co2 < 1200) {
                    printf("Ventilation: LOW\n");
                } else {
                    printf("Ventilation: HIGH\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else if (data_ready < 0) {
            fprintf(stderr, "Failed to get data ready status\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

