    if (crc8(data, 2) != crc) {
        fprintf(stderr, "CRC mismatch for data ready status\n");
        return -1;
    }

    unsigned int ready = (read_buf[0] << 8) | read_buf[1];
    return ready;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    return write_command(SCD30_CMD_STOP_PERIODIC_MEASUREMENT);
}

// Function to log data to a file
int log_data(float co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

// Cleanup function
void cleanup() {
    stop_periodic_measurement();
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

// CRC8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (write_command(SCD30_CMD_START_PERIODIC_MEASUREMENT) != 0) {
        cleanup();
        return 1;
    }

    float co2, temperature, humidity;
    int data_ready;

    // Main loop
    while (running) {
        data_ready = get_data_ready();
        if (data_ready > 0) {
            if (read_data(&co2, &temperature, &humidity) == 0) {
                log_data(co2, temperature, humidity);

                // Ventilation control logic
                if (co2 < 800) {
                    printf("Ventilation: OFF\n");
                } else if (co2 >= 800 && co2 < 1200) {
                    printf("Ventilation: LOW\n");
                } else {
                    printf("Ventilation: HIGH\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else if (data_ready < 0) {
            fprintf(stderr, "Failed to get data ready status\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

