#define TRIGGER_COMMAND 0x362F
#define READ_LENGTH 9
#define SAMPLE_INTERVAL_MS 45
#define LOG_INTERVAL_S 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_handle, float *pressure, float *temperature) {
    uint8_t buffer[READ_LENGTH];
    int result;

    // Send trigger command
    result = i2cWriteWordData(i2c_handle, 0x00, TRIGGER_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Error writing trigger command: %d\n", result);
        return -1;
    }

    // Wait for conversion
    gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds

    // Read data
    result = i2cReadDevice(i2c_handle, (char *)buffer, READ_LENGTH);
    if (result != READ_LENGTH) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Validate CRC for pressure
    uint8_t pressure_data[3] = {buffer[0], buffer[1], buffer[2]};
    uint8_t pressure_crc = buffer[2];
    if (crc8(pressure_data, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }

    // Validate CRC for temperature
    uint8_t temperature_data[3] = {buffer[3], buffer[4], buffer[5]};
    uint8_t temperature_crc = buffer[5];
    if (crc8(temperature_data, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    // Validate CRC for scale factors
    uint8_t scale_factor_data[3] = {buffer[6], buffer[7], buffer[8]};
    uint8_t scale_factor_crc = buffer[8];
    if (crc8(scale_factor_data, 2) != scale_factor_crc) {
        fprintf(stderr, "Scale factor CRC mismatch\n");
        return -1;
    }

    // Extract pressure and temperature
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    // Extract scale factors
    uint16_t pressure_scale_factor = (buffer[6] << 8) | buffer[7];
    uint16_t temperature_scale_factor = (buffer[6] << 8) | buffer[7];

    // Convert to physical units (example values, adjust based on datasheet)
    *pressure = (float)raw_pressure / pressure_scale_factor; // Pa
    *temperature = (float)raw_temperature / temperature_scale_factor; // °C

    return 0;
}

