// Define the register address for reading pressure data (adjust as needed)
#define PRESSURE_REG 0x00 // Example register address

// Global variable for the I2C handle
int i2c_handle = -1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read pressure data from the MLX90833 sensor
int read_pressure(int i2c_handle, float *pressure) {
    char buf[2]; // Buffer to store the pressure data (adjust size as needed)
    int result;

    // Write the register address to the sensor
    result = i2cWriteByteData(i2c_handle, PRESSURE_REG, 0); // Send a dummy byte to initiate read
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Read the pressure data from the sensor
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2); // Read 2 bytes
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert the raw data to a pressure value (adjust conversion as needed)
    int16_t raw_pressure = (buf[0] << 8) | buf[1]; // Combine the two bytes
    *pressure = (float)raw_pressure / 10.0; // Example conversion

    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(1, MLX90833_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

