#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICP-10101 I2C address
#define ICP10101_ADDR 0x69

// ICP-10101 Register Addresses
#define ICP10101_REG_PRODUCT_ID 0x71
#define ICP10101_REG_RESET 0x80
#define ICP10101_REG_MEASURE 0x06
#define ICP10101_REG_TEMP_MSB 0x03
#define ICP10101_REG_TEMP_LSB 0x04
#define ICP10101_REG_PRESS_MSB 0x00
#define ICP10101_REG_PRESS_LSB 0x01

// Default values for sensor check
#define DEFAULT_TEMP 0x8000
#define DEFAULT_PRESS 0x8000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int init_icp10101();
int read_sensor_data(sensor_data_t *data);
void print_sensor_data(sensor_data_t data);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return buffer;
}

// Function to initialize the ICP-10101 sensor
int init_icp10101() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, ICP10101_REG_RESET, 0x80) < 0) {
        fprintf(stderr, "%s - Error resetting sensor\n", get_iso8601_timestamp());
        return -1;
    }
    gpioDelay(10000); // Wait 10ms for reset to complete

    // Check Product ID
    int product_id = i2cReadByteData(i2c_handle, ICP10101_REG_PRODUCT_ID);
    if (product_id < 0) {
        fprintf(stderr, "%s - Error reading product ID\n", get_iso8601_timestamp());
        return -1;
    }
    if (product_id != 0x41) {
        fprintf(stderr, "%s - Incorrect product ID: 0x%02X\n", get_iso8601_timestamp(), product_id);
        return -1;
    }

    return 0;
}

// Function to read temperature and pressure data from the sensor
int read_sensor_data(sensor_data_t *data) {
    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, ICP10101_REG_MEASURE, 0x07) < 0) {
        fprintf(stderr, "%s - Error triggering measurement\n", get_iso8601_timestamp());
        return -1;
    }
    gpioDelay(7000); // Wait 7ms for measurement to complete

    // Read pressure data
    int press_msb = i2cReadByteData(i2c_handle, ICP10101_REG_PRESS_MSB);
    int press_lsb = i2cReadByteData(i2c_handle, ICP10101_REG_PRESS_LSB);

    if (press_msb < 0 || press_lsb < 0) {
        fprintf(stderr, "%s - Error reading pressure data\n", get_iso8601_timestamp());
        return -1;
    }

    int32_t raw_pressure = (press_msb << 8) | press_lsb;

    // Read temperature data
    int temp_msb = i2cReadByteData(i2c_handle, ICP10101_REG_TEMP_MSB);
    int temp_lsb = i2cReadByteData(i2c_handle, ICP10101_REG_TEMP_LSB);

    if (temp_msb < 0 || temp_lsb < 0) {
        fprintf(stderr, "%s - Error reading temperature data\n", get_iso8601_timestamp());
        return -1;
    }

    int32_t raw_temperature = (temp_msb << 8) | temp_lsb;

    // Check for default values
    if (raw_temperature == DEFAULT_TEMP && raw_pressure == DEFAULT_PRESS) {
        fprintf(stderr, "%s - Sensor absent or error\n", get_iso8601_timestamp());
        return -1;
    }

    // Convert raw data to temperature and pressure (example formulas, adjust as needed)
    data->temperature = (float)raw_temperature / 100.0; // Example conversion
    data->pressure = (float)raw_pressure * 10.0; // Example conversion

    return 0;
}

// Function to print the sensor data with timestamp
void print_sensor_data(sensor_data_t data) {
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", get_iso8601_timestamp(), data.temperature, data.pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_icp10101() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            print_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "%s - Failed to read sensor data\n", get_iso8601_timestamp());
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

