#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define SAMPLE_INTERVAL_MS 1000
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t buffer[9];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement (45ms)
    gpioDelay(45000);

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC for pressure
    uint8_t crc_pressure = crc8(buffer, 2);
    if (crc_pressure != buffer[2]) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        return -1;
    }

    // Validate CRC for temperature
    uint8_t crc_temperature = crc8(buffer + 3, 2);
    if (crc_temperature != buffer[5]) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    // Convert data to pressure and temperature
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    *pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    *temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return 0;
}

// Function to log data to file
int log_data(const char *filename, float pressure, float temperature) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float pressure, temperature;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &pressure, &temperature) == 0) {
            if (log_data(LOG_FILE, pressure, temperature) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 1 second
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

