#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define TRIGGER_COMMAND 0x362F
#define LOG_FILE "airflow_log.csv"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(sensor_data_t *data);
int verify_crc(const uint8_t *data, uint8_t crc);
float convert_pressure(int16_t raw_pressure);
int log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    char command[2] = {(TRIGGER_COMMAND >> 8) & 0xFF, TRIGGER_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(8); // Wait at least 8 ms
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    data->pressure = (buffer[0] << 8) | buffer[1];
    data->crc = buffer[2];
    return 0;
}

// Verify CRC checksum
int verify_crc(const uint8_t *data, uint8_t crc) {
    uint8_t calculated_crc = crc8(data, 2);
    return (calculated_crc == crc);
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / 240.0; // Sensitivity from datasheet
}

// Log data to file
int log_data(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Pressure(Pa)\n");
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write data to file
    fprintf(fp, "%s,%.3f\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() == 0) {
            // Read sensor data
            if (read_sensor_data(&sensor_data) == 0) {
                // Verify CRC
                uint8_t data[2] = {sensor_data.pressure >> 8, sensor_data.pressure & 0xFF};
                if (verify_crc(data, sensor_data.crc)) {
                    // Convert pressure
                    float pressure = convert_pressure(sensor_data.pressure);

                    // Log data
                    if (log_data(pressure) != 0) {
                        fprintf(stderr, "Error logging data\n");
                    }
                } else {
                    fprintf(stderr, "CRC verification failed\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else {
            fprintf(stderr, "Failed to trigger measurement\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Sample every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

