// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1MB
#define MEASUREMENT_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
SensorData read_sensor_data();
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();
int check_log_size();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from the sensor
SensorData read_sensor_data() {
    SensorData data = {0.0, 0.0};
    unsigned char buf[4];
    int result;

    // Trigger measurement
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Wait for measurement to complete (at least 40ms)
    gpioDelay(50000); // 50ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: %d\n", result);
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Validate status bits
    int status = (buf[0] >> 6) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Error: Invalid status bits: %d\n", status);
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Convert data
    unsigned int humidity_raw = ((buf[0] & 0x3F) << 8) | buf[1];
    unsigned int temperature_raw = (buf[2] << 6) | (buf[3] >> 2);

    data.humidity = ((float)humidity_raw / 16383) * 100;
    data.temperature = ((float)temperature_raw / 16383) * 165 - 40;

    return data;
}

// Log data to file with ISO 8601 timestamp
void log_data(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fclose(fp);
}

// Check log file size and truncate if necessary
int check_log_size() {
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        // File doesn't exist, no need to truncate
        return 0;
    }

    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    fclose(fp);

    if (size > LOG_FILE_SIZE_LIMIT) {
        fp = fopen(LOG_FILE, "w"); // Truncate the file
        if (fp == NULL) {
            fprintf(stderr, "Error truncating log file!\n");
            return -1;
        }
        fclose(fp);
        printf("Log file truncated.\n");
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Environmental data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        SensorData data = read_sensor_data();

        if (data.temperature != -999.0) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        check_log_size();

        sleep(MEASUREMENT_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

