#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pin for SENT signal
#define SENT_GPIO 4

// Define log file name
#define LOG_FILE "pressure_log.txt"

// Define error log file name
#define ERROR_LOG_FILE "error_log.txt"

// Define timeout in seconds
#define TIMEOUT 1

// Define SENT parameters
#define SENT_SYNC_PULSE_TICKS 56
#define SENT_MIN_PULSE_WIDTH 12
#define SENT_MAX_PULSE_WIDTH 271

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

// Structure to hold SENT data
typedef struct {
    unsigned int status;
    unsigned int data1;
    unsigned int data2;
    unsigned int data3;
    unsigned int checksum;
} SENTData;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
int read_sent_data(SENTData *data);
int validate_sent_data(const SENTData *data);
float calculate_pressure(const SENTData *data);
int log_pressure_data(float pressure);
void log_error(const char *message);
void signal_handler(int signal);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioTerminate();
}

// Function to read SENT data
int read_sent_data(SENTData *data) {
    int i;
    unsigned int pulse_widths[8];
    unsigned int start_time, end_time;

    // Read 8 pulse widths
    for (i = 0; i < 8; i++) {
        // Wait for rising edge
        while (gpioRead(SENT_GPIO) == 0) {
            // Timeout check
            if (gpioTick() > start_time + TIMEOUT * 1000000) {
                log_error("Timeout waiting for rising edge");
                return 1; // Timeout
            }
        }
        start_time = gpioTick();

        // Wait for falling edge
        while (gpioRead(SENT_GPIO) == 1) {
            // Timeout check
            if (gpioTick() > start_time + TIMEOUT * 1000000) {
                log_error("Timeout waiting for falling edge");
                return 1; // Timeout
            }
        }
        end_time = gpioTick();

        pulse_widths[i] = end_time - start_time;

        // Validate pulse width
        if (pulse_widths[i] < SENT_MIN_PULSE_WIDTH || pulse_widths[i] > SENT_MAX_PULSE_WIDTH) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Invalid pulse width: %u ticks", pulse_widths[i]);
            log_error(error_message);
            return 1; // Invalid pulse width
        }
    }

    // Decode nibbles
    data->status = pulse_widths[0] / 3; // Convert ticks to nibble value
    data->data1 = pulse_widths[1] / 3;
    data->data2 = pulse_widths[2] / 3;
    data->data3 = pulse_widths[3] / 3;
    data->checksum = pulse_widths[4] / 3;

    return 0;
}

// Function to validate SENT data
