#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (High Precision)
#define MEASURE_CMD 0xFD

// Global variables for I2C handle and file pointer
int i2c_handle = -1;
FILE *log_file = NULL;

// CRC-8 polynomial (0x31) and initial value (0xFF)
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

// Function to calculate CRC-8
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 8.5 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate CRC for temperature
    uint8_t temp_data[2] = {data[0], data[1]};
    uint8_t temp_crc = data[2];
    if (crc8(temp_data, 2) != temp_crc) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Validate CRC for humidity
    uint8_t hum_data[2] = {data[3], data[4]};
    uint8_t hum_crc = data[5];
    if (crc8(hum_data, 2) != hum_crc) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert temperature to Celsius
    uint16_t temp_raw = (data[0] << 8) | data[1];
    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;

    // Convert humidity to percentage
    uint16_t hum_raw = (data[3] << 8) | data[4];
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

// Function to log data to file
int log_data(FILE *log_file, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }

    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        result = read_sht40(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            log_data(log_file, temperature, humidity);
        } else {
            fprintf(stderr, "Error reading SHT40 data\n");
        }

        sleep(5);
    }

    return 0;
}

