// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 command for normal mode, clock stretching disabled
#define SHTC3_MEASURE_CMD 0x7866

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Structure to hold temperature and humidity data
typedef struct {
    float temperature;
    float humidity;
} shtc3_data_t;

// Function prototypes
int shtc3_init();
int shtc3_read_data(uint16_t *temperature, uint16_t *humidity);
uint8_t crc8(const uint8_t *data, size_t len, uint8_t initial);
int validate_data(uint16_t temperature, uint16_t humidity);
shtc3_data_t convert_data(uint16_t temperature, uint16_t humidity);
int log_data(shtc3_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the SHTC3 sensor
int shtc3_init() {
    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the SHTC3 sensor
int shtc3_read_data(uint16_t *temperature, uint16_t *humidity) {
    char cmd[2] = {(SHTC3_MEASURE_CMD >> 8) & 0xFF, SHTC3_MEASURE_CMD & 0xFF};
    char buffer[6];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(15000); // Wait 15 ms for measurement

    if (i2cReadDevice(i2c_handle, buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *temperature = (buffer[0] << 8) | buffer[1];
    *humidity = (buffer[3] << 8) | buffer[4];

    return 0;
}

// Calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, size_t len, uint8_t initial) {
    uint8_t crc = initial;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate temperature and humidity data
int validate_data(uint16_t temperature, uint16_t humidity) {
    uint8_t temp_data[2] = {(temperature >> 8) & 0xFF, temperature & 0xFF};
    uint8_t hum_data[2] = {(humidity >> 8) & 0xFF, humidity & 0xFF};

    uint8_t temp_crc = crc8(temp_data, 2, CRC8_INITIAL);
    uint8_t hum_crc = crc8(hum_data, 2, CRC8_INITIAL);

    if (temp_crc != (temperature & 0xFF)) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    if (hum_crc != (humidity & 0xFF)) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    float temp_celsius = 175.0f * temperature / 65535.0f - 45.0f;
    float humidity_percent = 100.0f * humidity / 65535.0f;

    if (temp_celsius < -40.0f || temp_celsius > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f\n", temp_celsius);
        return -1;
    }

    if (humidity_percent < 0.0f || humidity_percent > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.2f\n", humidity_percent);
        return -1;
    }

    return 0;
}

// Convert raw data to Celsius and percentage relative humidity
shtc3_data_t convert_data(uint16_t temperature, uint16_t humidity) {
    shtc3_data_t data;
    data.temperature = 175.0f * temperature / 65535.0f - 45.0f;
    data.humidity = 100.0f * humidity / 65535.0f;
    return data;
}

// Log data to file
int log_data(shtc3_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to file immediately

    printf("%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SHTC3 sensor
    if (shtc3_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t temperature, humidity;
    shtc3_data_t data;

    // Main loop
    while (!terminate) {
        if (shtc3_read_data(&temperature, &humidity) == 0) {
            if (validate_data(temperature, humidity) == 0) {
                data = convert_data(temperature, humidity);
                log_data(data);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

