#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define CONFIG_REG 0x01
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp117_address;
    const char *log_file_name;
} config_t;

config_t config = {I2C_BUS, TMP117_ADDR, "temperature_log.txt"};

int main() {
    float temperature;
    int retries = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed after multiple retries. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Attempting to re-initialize I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1; // Reset handle
            retries++;
            if (retries > RETRY_COUNT) {
                fprintf(stderr, "I2C re-initialization failed after multiple retries. Exiting.\n");
                break;
            }
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C initialisation failed after multiple retries. Exiting.\n");
                break;
            }
            retries = 0; // Reset retries after successful re-initialization
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.tmp117_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure TMP117 for continuous conversion mode (optional, but good practice)
    char config_data[3];
    config_data[0] = CONFIG_REG;
    config_data[1] = 0x00; // Continuous conversion mode
    config_data[2] = 0x00;

    if (i2cWriteDevice(i2c_handle, config_data, 3) != 0) {
        fprintf(stderr, "Failed to write to config register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return 1;
    }

    return 0;
}

