    char buf[2];
    int16_t raw_temp;
    int result;

    // Read two bytes from temperature register
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return 1;
    }

    // Convert raw data to temperature (Celsius)
    raw_temp = (buf[0] << 8) | buf[1];
    *temperature = raw_temp * 0.0078125;

    return 0;
}

