#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FLOW_LOG_FILE "flow_log.txt"
#define NUM_DISCARD_READS 2 // Number of initial reads to discard

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint32_t *raw_data);
float convert_flow(uint32_t raw_flow);
float convert_temperature(uint32_t raw_temp);
int log_data(float flow_slpm, float temperature_c);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float flow_slpm;
    float temperature_c;
} sensor_data_t;

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(uint32_t *raw_data) {
    char buffer[4];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }

    *raw_data = ((uint32_t)buffer[0] << 24) | ((uint32_t)buffer[1] << 16) | ((uint32_t)buffer[2] << 8) | (uint32_t)buffer[3];
    return 0;
}

// Function to convert raw flow data to SLPM
float convert_flow(uint32_t raw_flow) {
    // Extract the 14-bit flow value from the 32-bit data
    uint16_t flow_value = (raw_flow >> 18) & 0x3FFF; // Shift right by 18 bits and mask with 0x3FFF
    return (float)flow_value * 25.0 / 16383.0; // Scale to 0-25 SLPM
}

// Function to convert raw temperature data to Celsius
float convert_temperature(uint32_t raw_temp) {
    // Extract the 12-bit temperature value from the 32-bit data
    uint16_t temp_value = (raw_temp >> 6) & 0xFFF; // Shift right by 6 bits and mask with 0xFFF
    return (float)temp_value * 165.0 / 4095.0 - 40.0; // Scale to -40-125 Celsius
}

// Function to log the data to a file
int log_data(float flow_slpm, float temperature_c) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f SLPM, %.2f °C\n", timestamp, flow_slpm, temperature_c);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", FLOW_LOG_FILE);
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Discard initial reads
    uint32_t discard_data;
    for (int i = 0; i < NUM_DISCARD_READS; i++) {
        if (read_sensor_data(&discard_data) != 0) {
            fprintf(stderr, "Error during initial read, discarding.\n");
        }
        gpioDelay(100); // Small delay between discard reads
    }

    // Main loop
    uint32_t raw_data;
    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor_data(&raw_data) == 0) {
            sensor_data.flow_slpm = convert_flow(raw_data);
            sensor_data.temperature_c = convert_temperature(raw_data);

            if (log_data(sensor_data.flow_slpm, sensor_data.temperature_c) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

