#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define MAX_TIMINGS 85
#define MIN_INTERVAL 2000000 // 2 seconds in microseconds

static volatile int running = 1;
static unsigned int last_read_time = 0;

// Structure to hold DHT11 data
typedef struct {
    int humidity_integer;
    int humidity_decimal;
    int temperature_integer;
    int temperature_decimal;
    int checksum;
} DHT11Data;

// Function prototypes
int initialize_gpio();
int generate_start_signal();
int read_dht11_data(int data[]);
int decode_dht11_data(int data[], DHT11Data *dht_data);
int validate_checksum(const DHT11Data *dht_data);
int log_data(const DHT11Data *dht_data);
int log_error(const char *message, int status_code);
void signal_handler(int signal);
void cleanup();

int main() {
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int data[MAX_TIMINGS] = {0};
    DHT11Data dht_data;

    while (running) {
        unsigned int current_time = gpioTick();
        if (current_time - last_read_time < MIN_INTERVAL) {
            usleep(MIN_INTERVAL - (current_time - last_read_time));
        }

        if (generate_start_signal() != 0) {
            log_error("Failed to generate start signal.", 1);
            usleep(1000000); // Wait 1 second before retrying
            continue;
        }

        if (read_dht11_data(data) != 0) {
            log_error("Failed to read DHT11 data.", 2);
            usleep(1000000); // Wait 1 second before retrying
            continue;
        }

        if (decode_dht11_data(data, &dht_data) != 0) {
            log_error("Failed to decode DHT11 data.", 3);
            usleep(1000000); // Wait 1 second before retrying
            continue;
        }

        if (validate_checksum(&dht_data) != 0) {
            log_error("Checksum validation failed.", 4);
            usleep(1000000); // Wait 1 second before retrying
            continue;
        }

        if (log_data(&dht_data) != 0) {
            log_error("Failed to log data.", 5);
        }

        last_read_time = gpioTick();
        usleep(1000000); // Wait 1 second
    }

    cleanup();
    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    return 0;
}

int generate_start_signal() {
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18000); // 18ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(20); // Small delay after releasing the line
    return 0;
}

int read_dht11_data(int data[]) {
    int last_state = PI_HIGH;
    int j = 0;

    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // Wait for the DHT11 response (80us low, 80us high)
    int timeout = 0;
    while (gpioRead(DHT11_GPIO) == PI_HIGH) {
        timeout++;
        if (timeout > 100) { // Timeout after 100 loops (adjust as needed)
            log_error("DHT11 response timeout (initial high).", 6);
            gpioSetMode(DHT11_GPIO, PI_OUTPUT);
            return 1;
        }
        gpioDelay(1); // Small delay
    }

    timeout = 0;
    while (gpioRead(DHT11_GPIO) == PI_LOW) {
        timeout++;
        if (timeout > 100) { // Timeout after 100 loops (adjust as needed)
            log_error("DHT11 response timeout (initial low).", 7);
            gpioSetMode(DHT11_GPIO, PI_OUTPUT);
            return 1;
        }
        gpioDelay(1); // Small delay
    }

    timeout = 0;
    while (gpioRead(DHT11_GPIO) == PI_HIGH) {
        timeout++;
        if (timeout > 100) { // Timeout after 100 loops (adjust as needed)
            log_error("DHT11 response timeout (initial high after low).", 8);
            gpioSetMode(DHT11_GPIO, PI_OUTPUT);
            return 1;
        }
        gpioDelay(1); // Small delay
    }

    // Read the 40 bits of data
    for (int i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == PI_LOW) {
            timeout++;
            if (timeout > 100) { // Timeout after 100 loops (adjust as needed)
                log_error("DHT11 data bit timeout (low).", 9);
                gpioSetMode(DHT11_GPIO, PI_OUTPUT);
                return 1;
            }
            gpioDelay(1); // Small delay
        }

        unsigned int t = gpioTick();
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == PI_HIGH) {
            timeout++;
            if (timeout > 100) { // Timeout after 100 loops (adjust as needed)
                log_error("DHT11 data bit timeout (high).", 10);
                gpioSetMode(DHT11_GPIO, PI_OUTPUT);
                return 1;
            }
            gpioDelay(1); // Small delay
        }

        if ((gpioTick() - t) > 40) {
            data[j++] = 1;
        } else {
            data[j++] = 0;
        }
    }

    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    return 0;
}

int decode_dht11_data(int data[], DHT11Data *dht_data) {
    unsigned int humidity_integer = 0;
    unsigned int humidity_decimal = 0;
    unsigned int temperature_integer = 0;
    unsigned int temperature_decimal = 0;
    unsigned int checksum = 0;

    for (int i = 0; i < 8; i++) {
        humidity_integer <<= 1;
        humidity_integer |= data[i];
    }

    for (int i = 8; i < 16; i++) {
        humidity_decimal <<= 1;
        humidity_decimal |= data[i];
    }

    for (int i = 16; i < 24; i++) {
        temperature_integer <<= 1;
        temperature_integer |= data[i];
    }

    for (int i = 24; i < 32; i++) {
        temperature_decimal <<= 1;
        temperature_decimal |= data[i];
    }

    for (int i = 32; i < 40; i++) {
        checksum <<= 1;
        checksum |= data[i];
    }

    dht_data->humidity_integer = humidity_integer;
    dht_data->humidity_decimal = humidity_decimal;
    dht_data->temperature_integer = temperature_integer;
    dht_data->temperature_decimal = temperature_decimal;
    dht_data->checksum = checksum;

    return 0;
}

int validate_checksum(const DHT11Data *dht_data) {
    unsigned int sum = dht_data->humidity_integer + dht_data->humidity_decimal + dht_data->temperature_integer + dht_data->temperature_decimal;
    if (sum != dht_data->checksum) {
        return 1;
    }
    return 0;
}

int log_data(const DHT11Data *dht_data) {
    FILE *fp = fopen("dht11_readings.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing!\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Humidity: %d.%d, Temperature: %d.%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            dht_data->humidity_integer, dht_data->humidity_decimal,
            dht_data->temperature_integer, dht_data->temperature_decimal);

    fclose(fp);
    return 0;
}

int log_error(const char *message, int status_code) {
    FILE *fp = fopen("dht11_readings.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing!\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ERROR: %s, Status Code: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            message, status_code);

    fclose(fp);
    return 0;
}

void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

void cleanup() {
    gpioTerminate();
    printf("pigpio terminated.\n");
}

