    }

    // Close I2C handles
    if (i2c_handle_1 != -1) {
        i2cClose(i2c_handle_1);
    }
    if (i2c_handle_2 != -1) {
        i2cClose(i2c_handle_2);
    }

    // Terminate pigpio
    gpioTerminate();

