#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0
#define HYSTERESIS 2.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_pigpio();
int open_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_fan(float average_temperature);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature from LM75B sensor
float read_temperature() {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        return -100.0; // Indicate error with a very low temperature
    }

    // Convert the raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    float temperature = raw_temp * 0.125;

    return temperature;
}

// Add temperature reading to circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate running average of temperature readings
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control the cooling fan based on average temperature
void control_fan(float average_temperature) {
    static int fan_on = 0; // Track fan state

    if (average_temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Avg Temp: %.2f)\n", average_temperature);
    } else if (average_temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Avg Temp: %.2f)\n", average_temperature);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer temp_buffer;
    init_circular_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();

        if (temperature > -99.0) { // Check for read error
            // Add to circular buffer
            add_to_buffer(&temp_buffer, temperature);

            // Calculate running average
            float average_temperature = calculate_average(&temp_buffer);

            // Control fan
            control_fan(average_temperature);
        } else {
            fprintf(stderr, "Error reading temperature, skipping this cycle.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

