#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define LOG_FILE "airflow.log"
#define PRESSURE_THRESHOLD 5.0

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
uint8_t crc8(const uint8_t *data, int len);
void log_data(sensor_data_t data);
void check_pressure_threshold(float pressure);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    uint8_t buffer[9];

    if (i2cWriteDevice(i2c_handle, (char *)command, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(45000); // Wait 45 ms

    if (i2cReadDevice(i2c_handle, (char *)buffer, 9) != 9) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5] || crc8(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }

    // Convert data
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data->differential_pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    data->temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return 0;
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f\n", timestamp, data.differential_pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check pressure threshold
void check_pressure_threshold(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        fprintf(stderr, "Warning: Differential pressure exceeds threshold (%.3f Pa > %.3f Pa)\n", pressure, PRESSURE_THRESHOLD);
    }
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
            check_pressure_threshold(sensor_data.differential_pressure);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

