#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define TEMP_REG 0x00 // Temperature register address

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
void control_led(float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);

    i2c_handle = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read temperature from STTS2004 sensor
float read_temperature() {
    int raw_temp;
    int retries = 3;

    while (retries > 0) {
        raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
        if (raw_temp >= 0) {
            // Success
            break;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", 4 - retries, strerror(errno));
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature after multiple retries\n");
        return -1000.0; // Indicate error
    }

    // Convert raw temperature to Celsius (STTS2004 datasheet)
    float temperature = (float)(raw_temp >> 4) * 0.0625;
    return temperature;
}

// Control LED based on temperature
void control_led(float temperature) {
    static int led_state = 0; // 0 = off, 1 = on

    if (temperature > TEMP_THRESHOLD_HIGH && led_state == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        led_state = 1;
        printf("LED ON\n");
    } else if (temperature < TEMP_THRESHOLD_LOW && led_state == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
        led_state = 0;
        printf("LED OFF\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            printf("Temperature: %.2f °C\n", temperature);
            control_led(temperature);
        } else {
            fprintf(stderr, "Error reading temperature, skipping LED control.\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    cleanup();
    return 0;
}

