#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_HUMIDITY_CMD 0xE5
#define MEASURE_TEMP_CMD 0xE3
#define READ_TEMP_CMD 0xE0
#define MAX_RETRIES 3
#define LOG_FILE "environment.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(sensor_data_t data);
void signal_handler(int signal);
int validate_sensor();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[2];
    int retries = 0;
    int result;

    // Measure Humidity
    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, MEASURE_HUMIDITY_CMD);
        if (result == 0) break;
        retries++;
        gpioDelay(1000); // 1ms delay
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error writing humidity command after %d retries\n", MAX_RETRIES);
        return -1;
    }
    gpioDelay(20000); // 20ms delay

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) break;
        retries++;
        gpioDelay(1000); // 1ms delay
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error reading humidity data after %d retries\n", MAX_RETRIES);
        return -1;
    }
    uint16_t raw_humidity = (buf[0] << 8) | buf[1];
    data->humidity = convert_humidity(raw_humidity);

    // Measure Temperature
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, MEASURE_TEMP_CMD);
        if (result == 0) break;
        retries++;
        gpioDelay(1000); // 1ms delay
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error writing temperature command after %d retries\n", MAX_RETRIES);
        return -1;
    }
