int trigger_measurement() {
    char config_data[2] = {0x00, 0x00}; // Configure for temperature and humidity measurement
    int result = i2cWriteI2CBlockData(i2c_handle, CONFIGURATION_REG, config_data, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to write configuration: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait 20ms for conversion
    return 0;
}

