int read_data(uint16_t *temperature, uint16_t *humidity) {
    char data[4];
    int result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, data, 4);
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    *temperature = (data[0] << 8) | data[1];
    *humidity = (data[2] << 8) | data[3];

    return 0;
}

