    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    printf("HDC1080 sensor logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_temperature, raw_humidity;
        sensor_data_t sensor_data;

        // Trigger measurement
        if (trigger_measurement() == 0) {
            // Read data
            if (read_data(&raw_temperature, &raw_humidity) == 0) {
                // Convert data
                sensor_data = convert_data(raw_temperature, raw_humidity);

                // Log data
                if (log_data(sensor_data) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else {
            fprintf(stderr, "Failed to trigger measurement\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

