#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdbool.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(const char *bus);
int i2c_set_slave_address(int fd, int address);
int i2c_write_byte(int fd, uint8_t data);
int i2c_read_bytes(int fd, uint8_t *data, int len);
uint8_t crc8(const uint8_t *data, int len);
float convert_to_celsius(uint16_t raw_temperature);
char *get_iso8601_timestamp(char *timestamp_buffer, size_t buffer_size);
int log_temperature(const char *timestamp, float temperature);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// I2C set slave address function
int i2c_set_slave_address(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t data) {
    if (write(fd, &data, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t *data, int len) {
    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading from I2C device: %s (read %zd bytes, expected %d)\n", strerror(errno), bytes_read, len);
        return -1;
    }
    return 0;
}

// CRC8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Temperature conversion function
float convert_to_celsius(uint16_t raw_temperature) {
    return -45.0 + (175.0 * (float)raw_temperature / 65535.0);
}

// Timestamp generation function
char *get_iso8601_timestamp(char *timestamp_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_buffer;
}

// Logging function
int log_temperature(const char *timestamp, float temperature) {
    if (log_fp == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    if (fprintf(log_fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (i2c_set_slave_address(i2c_fd, STS40_ADDR) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

