#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define LOG_FILE "hvac_pressure_log.txt"
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 lookup table
const uint8_t crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xC4, 0xF5, 0xA6, 0x97, 0xB9, 0x88, 0xDB, 0xEA, 0x7D, 0x4C, 0x1F, 0x2E
};

// Function prototypes
int initialize();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int validate_crc(const uint8_t *data, size_t len);
float convert_pressure(const uint8_t *data);
float convert_temperature(const uint8_t *data);
int log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to trigger a measurement on the SDP810
int trigger_measurement() {
    char command[2] = {(MEASURE_COMMAND >> 8) & 0xFF, MEASURE_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data from the SDP810
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate the CRC-8 checksum
int validate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        crc = crc8_table[crc];
    }
    return (crc == data[len]);
}

// Function to convert raw pressure data to Pascals
float convert_pressure(const uint8_t *data) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t scale_factor = (data[6] << 8) | data[7] | (data[8] << 16);
    return (float)raw_pressure / (float)scale_factor;
}

// Function to convert raw temperature data to Celsius
float convert_temperature(const uint8_t *data) {
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t scale_factor = (data[6] << 8) | data[7] | (data[8] << 16);
    return (float)raw_temperature / (float)scale_factor;
}

// Function to log data to the CSV file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    printf("HVAC Pressure Monitoring Started. Press Ctrl+C to exit.\n");

    uint8_t sensor_data[9];
    float pressure, temperature;

    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,I2C write error during trigger\n", timestamp);
            fflush(log_file);
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for at least 50ms
        gpioDelay(50);

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,I2C read error\n", timestamp);
            fflush(log_file);
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC for pressure data
        if (!validate_crc(sensor_data, 2)) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,Pressure CRC error\n", timestamp);
            fflush(log_file);
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC for temperature data
        if (!validate_crc(sensor_data + 3, 2)) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,Temperature CRC error\n", timestamp);
            fflush(log_file);
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        pressure = convert_pressure(sensor_data);
        temperature = convert_temperature(sensor_data);

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

