#define SCD40_CMD_READ_MEASUREMENT 0xec05
#define SCD40_CMD_STOP_PERIODIC_MEASUREMENT 0x3f86

// Circular buffer size
#define BUFFER_SIZE 100

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
static volatile sig_atomic_t running = 1;
static int i2c_handle;
static circular_buffer_t buffer;
static pthread_t logging_thread;

// Function prototypes
int init_i2c();
int start_periodic_measurement();
int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity);
int stop_periodic_measurement();
uint8_t crc8(const uint8_t *data, int len);
void buffer_init(circular_buffer_t *buffer);
int buffer_add(circular_buffer_t *buffer, sensor_data_t data);
int buffer_read(circular_buffer_t *buffer, sensor_data_t *data, int index);
