#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_temperature(int reg, float *temperature);
float convert_to_celsius(uint16_t raw_temp);
int log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO and I2C
    if (init_gpio() != 0 || init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read temperatures
        if (read_temperature(AMBIENT_TEMP_REG, &sensor_data.ambient_temp) == 0 &&
            read_temperature(OBJECT_TEMP_REG, &sensor_data.object_temp) == 0) {

            // Log temperatures
            if (log_temperature(sensor_data.ambient_temp, sensor_data.object_temp) != 0) {
                fprintf(stderr, "Error logging temperature data.\n");
            }

            // Control fan
            control_fan(sensor_data.object_temp);
        } else {
            fprintf(stderr, "Error reading temperature data.\n");
        }

        // Wait 2 seconds
        gpioDelay(2000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature from sensor
int read_temperature(int reg, float *temperature) {
    uint16_t raw_temp;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        raw_temp = i2cReadWordData(i2c_handle, reg);
        if (raw_temp >= 0) {
            *temperature = convert_to_celsius(raw_temp);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X), retrying...\n", reg);
            gpioDelay(RETRY_DELAY_MS);
            retries++;
        }
    }

    fprintf(stderr, "Failed to read temperature from register 0x%02X after %d retries.\n", reg, RETRY_COUNT);
    return 1; // Failure
}

// Convert raw temperature to Celsius
float convert_to_celsius(uint16_t raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Log temperature to file
int log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (ambient_temp < -50.0 || ambient_temp > 100.0 || object_temp < -50.0 || object_temp > 100.0) {
        fprintf(stderr, "Invalid temperature reading: Ambient=%.2f, Object=%.2f\n", ambient_temp, object_temp);
        return 1;
    }

    fprintf(log_file, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Control fan with hysteresis
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Object Temp: %.2f C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Object Temp: %.2f C)\n", object_temp);
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off
    gpioTerminate();
}

