#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define SERVER_PORT 8080
#define MAX_RETRIES 3

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Global variables for I2C handle and socket
int i2c_handle = -1;
int server_socket = -1;

// Function prototypes
int read_sht40(int i2c_handle, float *temperature, float *humidity);
int create_server_socket(int port);
void handle_client(int client_socket);
void signal_handler(int signal);
void log_error(const char *message);

// Function to read data from SHT40 sensor
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    char buf[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Send measurement command
        result = i2cWriteByteData(i2c_handle, MEASURE_HIGH_PRECISION, 0);
        if (result != 0) {
            log_error("Failed to send measurement command");
            retries++;
            gpioDelay(10000); // Wait 10ms before retry
            continue;
        }

        gpioDelay(10000); // Wait 10ms for measurement

        // Read 6 bytes of data
        result = i2cReadI2CBlockData(i2c_handle, 0, buf, 6);
        if (result != 6) {
            log_error("Failed to read data from sensor");
            retries++;
            gpioDelay(10000); // Wait 10ms before retry
            continue;
        }

        // Convert data to temperature and humidity
        unsigned short temperature_raw = (buf[0] << 8) | buf[1];
        unsigned short humidity_raw = (buf[3] << 8) | buf[4];

        *temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
        *humidity = 100.0 * (float)humidity_raw / 65535.0;

