#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x02
#define MEASUREMENT_CONFIG_REG 0x0F

// I2C bus
#define I2C_BUS 1

// Retry count for I2C operations
#define MAX_RETRIES 3

// Timeout for measurement in milliseconds
#define MEASUREMENT_TIMEOUT 500

// Global variables
static volatile sig_atomic_t terminate = 0;
static int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the HDC2010 for temperature and humidity measurement
int configure_hdc2010() {
    char buf[2];
    buf[0] = MEASUREMENT_CONFIG_REG;
    buf[1] = 0x00; // Configure for temperature and humidity measurement

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG_REG: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the temperature and humidity registers
int read_temperature_humidity(float *temperature, float *humidity) {
    char buf[4];
    int result;

    // Read temperature and humidity registers
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading temperature and humidity registers: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (buf[0] << 8) | buf[1];
    uint16_t raw_humidity = (buf[2] << 8) | buf[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

// Function to read the MEASUREMENT_CONFIG register
int read_measurement_config(uint8_t *config) {
    char buf[1];
    int result;

    buf[0] = MEASUREMENT_CONFIG_REG;

    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG_REG for read: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading MEASUREMENT_CONFIG_REG: %d\n", result);
        return -1;
    }

    *config = buf[0];
    return 0;
}

// Function to wait for the measurement to complete
int wait_for_measurement() {
    uint8_t config;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read_measurement_config(&config) == 0) {
            if ((config & 0x01) == 0) {
                return 0; // Measurement complete
            }
        } else {
            fprintf(stderr, "Error reading measurement config, retrying...\n");
        }
        gpioDelay(10); // Wait 10ms
        retries++;
    }

    fprintf(stderr, "Timeout waiting for measurement to complete\n");
    return -1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure HDC2010
    if (configure_hdc2010() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;

    while (!terminate) {
        // Start measurement
        if (configure_hdc2010() != 0) {
            fprintf(stderr, "Failed to start measurement, retrying in 5 seconds...\n");
            gpioDelay(5000); // Wait 5 seconds
            continue;
        }

        // Wait for measurement to complete
        if (wait_for_measurement() != 0) {
            fprintf(stderr, "Measurement failed, retrying in 5 seconds...\n");
            gpioDelay(5000); // Wait 5 seconds
            continue;
        }

        // Read temperature and humidity
        if (read_temperature_humidity(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity, retrying in 5 seconds...\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

