// I2C address of the SDP800-500Pa sensor
#define SDP800_I2C_ADDRESS 0x25

// I2C bus number (typically 1 on Raspberry Pi)
#define I2C_BUS 1

// Measurement command (continuous measurement without averaging)
#define MEASURE_COMMAND 0x362F

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// CRC-8 checksum calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Send measurement command
    char command[2] = {(MEASURE_COMMAND >> 8) & 0xFF, MEASURE_COMMAND & 0xFF};
    int write_result = i2cWriteDevice(i2c_handle, command, 2);
    if (write_result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", write_result);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for measurement to complete (45ms)
        gpioDelay(45000); // 45ms

