            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Extract pressure and temperature values
        int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

        // CRC validation
        unsigned char pressure_crc = buffer[2];
        unsigned char temperature_crc = buffer[5];

        unsigned char calculated_pressure_crc = crc8((unsigned char *)buffer, 2);
        unsigned char calculated_temperature_crc = crc8((unsigned char *)buffer + 3, 2);

        if (calculated_pressure_crc != pressure_crc) {
            fprintf(stderr, "Pressure CRC check failed!\n");
        } else if (calculated_temperature_crc != temperature_crc) {
