#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_PROFILE_LENGTH 100
#define MAX_PROFILE_TIME 300 // Maximum profile time in seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// PID parameters
double Kp = 1.0;
double Ki = 0.1;
double Kd = 0.01;
double integral = 0.0;
double previous_error = 0.0;

// Target temperature profile
double target_temperatures[MAX_PROFILE_LENGTH];
double target_times[MAX_PROFILE_LENGTH];
int profile_length = 0;

// Function prototypes
int initialize();
void cleanup();
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_relay_duty_cycle(double duty_cycle);
void log_temperature(double temperature);
int load_profile();
void signal_handler(int signal);
double linear_interpolate(double time, int profile_length, double *times, double *temperatures);

// Structure to hold PID parameters
typedef struct {
    double Kp;
    double Ki;
    double Kd;
} PIDParams;

// Structure to hold temperature profile data
typedef struct {
    double time;
    double temperature;
} ProfilePoint;

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially turn off the relay

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
    }
    rewind(log_file);

    if (load_profile() != 0) {
        fprintf(stderr, "Failed to load temperature profile\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

// Function to read temperature from MAX6675
double read_temperature() {
    char buffer[2];
    int result = spiRead(spi_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "SPI read failed\n");
        return -1000.0; // Indicate error
    }

    // Check for fault bit (bit 2 of byte 1)
    if (buffer[1] & 0x04) {
        fprintf(stderr, "Thermocouple fault detected\n");
        return -1000.0; // Indicate error
    }

    // Extract temperature data (bits 3-14 of byte 0 and byte 1)
    int raw_temp = ((buffer[0] << 8) | buffer[1]) >> 3;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;

    integral += error;
    // Anti-windup: limit the integral term
    double integral_limit = 100.0; // Adjust as needed
    if (integral > integral_limit) integral = integral_limit;
    if (integral < -integral_limit) integral = -integral_limit;

    double derivative = error - previous_error;

    double output = Kp * error + Ki * integral + Kd * derivative;

    previous_error = error;

    // Limit the output to 0-1 range
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Function to set the relay duty cycle
void set_relay_duty_cycle(double duty_cycle) {
    gpioPWM(RELAY_GPIO, (int)(duty_cycle * 255)); // pigpio PWM range is 0-255
}

// Function to log temperature to file
void log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load the temperature profile from file
int load_profile() {
    FILE *profile = fopen(PROFILE_FILE, "r");
    if (profile == NULL) {
        fprintf(stderr, "Failed to open profile file\n");
        return 1;
    }

    char line[256];
    int i = 0;
    while (fgets(line, sizeof(line), profile)) {
        if (i >= MAX_PROFILE_LENGTH) {
            fprintf(stderr, "Profile too long, maximum length is %d\n", MAX_PROFILE_LENGTH);
            fclose(profile);
            return 1;
        }

        if (sscanf(line, "%lf,%lf", &target_times[i], &target_temperatures[i]) == 2) {
            i++;
        } else {
            fprintf(stderr, "Invalid line in profile file: %s", line);
            fclose(profile);
            return 1;
        }
    }

    profile_length = i;
    fclose(profile);

    // Validate profile data
    if (profile_length == 0) {
        fprintf(stderr, "Profile is empty\n");
        return 1;
    }

    if (target_times[0] != 0.0) {
        fprintf(stderr, "First time in profile must be 0.0\n");
        return 1;
    }

    for (int j = 1; j < profile_length; j++) {
        if (target_times[j] <= target_times[j - 1]) {
            fprintf(stderr, "Times in profile must be strictly increasing\n");
            return 1;
        }
    }

    if (target_times[profile_length - 1] > MAX_PROFILE_TIME) {
        fprintf(stderr, "Profile time exceeds maximum allowed time (%d seconds)\n", MAX_PROFILE_TIME);
        return 1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Function to perform linear interpolation
double linear_interpolate(double time, int profile_length, double *times, double *temperatures) {
    if (time <= times[0]) {
        return temperatures[0];
    }
    if (time >= times[profile_length - 1]) {
        return temperatures[profile_length - 1];
    }

    for (int i = 0; i < profile_length - 1; i++) {
        if (time >= times[i] && time <= times[i + 1]) {
            double fraction = (time - times[i]) / (times[i + 1] - times[i]);
            return temperatures[i] + fraction * (temperatures[i + 1] - temperatures[i]);
        }
    }

    return -1.0; // Should not reach here
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    double current_time = 0.0;
    double setpoint_temperature = 0.0;
    double actual_temperature = 0.0;
    double pid_output = 0.0;

    printf("Reflow oven controller started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        actual_temperature = read_temperature();

        if (actual_temperature < -900.0) { // Error reading temperature
            fprintf(stderr, "Error reading temperature, skipping PID and relay control\n");
        } else {
            setpoint_temperature = linear_interpolate(current_time, profile_length, target_times, target_temperatures);
            pid_output = calculate_pid(setpoint_temperature, actual_temperature);
            set_relay_duty_cycle(pid_output);
        }

        log_temperature(actual_temperature);
        printf("Time: %.2f, Setpoint: %.2f, Actual: %.2f, PID Output: %.2f\n", current_time, setpoint_temperature, actual_temperature, pid_output);

        current_time += 1.0;
        sleep(1);
    }

    cleanup();
    return 0;
}

