            setpoint_temperature = linear_interpolate(current_time, profile_length, target_times, target_temperatures);
            pid_output = calculate_pid(setpoint_temperature, actual_temperature);
            set_relay_duty_cycle(pid_output);
        }

        log_temperature(actual_temperature);
        printf("Time: %.2f, Setpoint: %.2f, Actual: %.2f, PID Output: %.2f\n", current_time, setpoint_temperature, actual_temperature, pid_output);

        current_time += 1.0;
        sleep(1);
    }

    cleanup();
    return 0;
}

