#include <sys/time.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000000  // 0-1000000 for 0-100%
#define LOG_FILE "greenhouse.log"
#define LOG_INTERVAL 5 // seconds

// GPIO pins
#define RELAY_PIN 17
#define PWM_PIN 18

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static float setpoint = 25.0; // Default setpoint
static float Kp = 1.0;       // Default Kp
static float Ki = 0.1;       // Default Ki
static float Kd = 0.01;      // Default Kd

// Structure to hold sensor data
typedef struct {
    char id[20];
    float temperature;
    int valid;
} sensor_data_t;

// Function prototypes
int read_temperature(const char *sensor_id, float *temperature);
float calculate_average_temperature(sensor_data_t *sensors, int num_sensors);
float pid_control(float setpoint, float actual_temperature, float Kp, float Ki, float Kd, float *integral, float *previous_error);
void set_pwm_duty_cycle(int duty_cycle);
void set_relay_state(int state);
void log_data(float average_temperature, float setpoint, float pid_output, int pwm_duty_cycle);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
int parse_arguments(int argc, char *argv[]);

// Function to read temperature from a DS18B20 sensor
int read_temperature(const char *sensor_id, float *temperature) {
    char filepath[100];
    snprintf(filepath, sizeof(filepath), "%s%s/w1_slave", W1_DEVICES_DIR, sensor_id);

    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        perror("Error opening w1_slave file");
        return -1;
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read < 0) {
        perror("Error reading w1_slave file");
        return -1;
    }
    buffer[bytes_read] = '\0';

    // Check for CRC error
    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1;
    }

    // Extract temperature
    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found for sensor %s\n", sensor_id);
        return -1;
    }

    long temp_value = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_value / 1000.0;

    return 0;
}

// Function to calculate the average temperature
float calculate_average_temperature(sensor_data_t *sensors, int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;
    for (int i = 0; i < num_sensors; i++) {
        if (sensors[i].valid) {
            sum += sensors[i].temperature;
            valid_count++;
        }
    }

    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return 0.0; // Or some other error value
    }
}

// Function to implement the PID controller
float pid_control(float setpoint, float actual_temperature, float Kp, float Ki, float Kd, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set the PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000000) duty_cycle = 1000000;
    gpioPWM(PWM_PIN, duty_cycle);
}

// Function to set the relay state
void set_relay_state(int state) {
    gpioWrite(RELAY_PIN, state);
}

// Function to log data to a file
void log_data(float average_temperature, float setpoint, float pid_output, int pwm_duty_cycle) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[256];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, tv.tv_usec);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f, %d\n", buf, average_temperature, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    set_relay_state(0); // Turn off relay
    set_pwm_duty_cycle(0); // Set PWM to 0
    gpioTerminate();
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return -1;
    }

    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);

    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (parse_arguments(argc, argv) != 0) {
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Find DS18B20 sensors
    DIR *dir;
    struct dirent *ent;
    sensor_data_t sensors[10]; // Assuming a maximum of 10 sensors
    int num_sensors = 0;

    dir = opendir(W1_DEVICES_DIR);
    if (dir != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strstr(ent->d_name, "28-") != NULL) {
                strncpy(sensors[num_sensors].id, ent->d_name, sizeof(sensors[num_sensors].id) - 1);
                sensors[num_sensors].id[sizeof(sensors[num_sensors].id) - 1] = '\0'; // Ensure null termination
                sensors[num_sensors].valid = 0; // Initially invalid
                num_sensors++;
                if (num_sensors >= 10) break; // Limit to 10 sensors
            }
        }
        closedir(dir);
    } else {
        perror("Error opening w1 devices directory");
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }

    // PID variables
    float integral = 0.0;
    float previous_error = 0.0;

    // Main loop
    while (running) {
        // Read temperatures from sensors
        for (int i = 0; i < num_sensors; i++) {
            if (read_temperature(sensors[i].id, &sensors[i].temperature) == 0) {
                sensors[i].valid = 1;
            } else {
                sensors[i].valid = 0;
            }
        }

        // Calculate average temperature
        float average_temperature = calculate_average_temperature(sensors, num_sensors);

        // Calculate PID output
        float pid_output = pid_control(setpoint, average_temperature, Kp, Ki, Kd, &integral, &previous_error);

        // Calculate PWM duty cycle (map PID output to 0-1000000)
        int pwm_duty_cycle = (int)(pid_output * 1000000.0); // Scale PID output to PWM range
        if (pwm_duty_cycle < 0) pwm_duty_cycle = 0;
        if (pwm_duty_cycle > 1000000) pwm_duty_cycle = 1000000;

        // Set PWM duty cycle
        set_pwm_duty_cycle(pwm_duty_cycle);

        // Set relay state (on if PWM > 0, off otherwise)
        set_relay_state(pwm_duty_cycle > 0 ? 1 : 0);

        // Log data
        log_data(average_temperature, setpoint, pid_output, pwm_duty_cycle);

        // Wait for the next iteration
        sleep(LOG_INTERVAL);
    }

    // Cleanup and exit
    cleanup_gpio();
    fclose(log_file);
    return 0;
}

