#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define GPIO_RELAY 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
float calculate_humidity(const uint8_t *data);
void control_relay(float humidity);
void log_data(float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off initially
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    uint8_t command[3] = {0xAC, 0x33, 0x00};
    int result = i2cWriteDevice(i2c_handle, command, 3);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(80); // Wait 80ms
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate humidity
float calculate_humidity(const uint8_t *data) {
    // Check status byte
    if ((data[0] & 0x80) != 0) {
        fprintf(stderr, "Sensor is busy\n");
        return -1.0;
    }
    if ((data[0] & 0x08) == 0) {
        fprintf(stderr, "Sensor is not calibrated\n");
        return -1.0;
    }

    uint32_t humidity_data = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    float humidity = ((float)humidity_data / 0x100000) * 100;
    return humidity;
}

// Control relay
void control_relay(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(GPIO_RELAY, 1); // Activate relay
        printf("Humidity above threshold, activating dehumidifier\n");
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(GPIO_RELAY, 0); // Deactivate relay
        printf("Humidity below threshold, deactivating dehumidifier\n");
    }
}

// Log data
void log_data(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Humidity: %.2f %%\n", timestamp, humidity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t sensor_data[6];
    float humidity;
    int retries;

    printf("AHT20 Humidity Monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        retries = 0;
        while (retries < 3) {
            if (trigger_measurement() == 0 && read_sensor_data(sensor_data) == 0) {
                humidity = calculate_humidity(sensor_data);
                if (humidity >= 0) {
                    log_data(humidity);
                    control_relay(humidity);
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Humidity calculation failed, retrying...\n");
                }
            } else {
                fprintf(stderr, "Sensor read failed, retrying...\n");
            }
            retries++;
            gpioDelay(10); // 10ms delay
        }

        if (retries == 3) {
            fprintf(stderr, "Failed to read sensor data after multiple retries\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Wait 5 seconds
    }

    // Clean up
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

