int read_temperature(int i2c_handle, float *temperature);
unsigned char calculate_crc(unsigned short data);
int post_humidity_data(const char *json_data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    closelog();
    exit(0);
}

// CRC calculation function
unsigned char calculate_crc(unsigned short data) {
    unsigned char crc = 0xFF;
    unsigned char bit;

    for (int i = 0; i < 16; i++) {
        bit = data >> (15 - i) & 0x01;
        if ((crc >> 7) ^ bit) {
            crc = (crc << 1) ^ 0x98;
        } else {
            crc = (crc << 1);
        }
    }
    return crc;
}

// Function to read humidity from HTU21D
int read_humidity(int i2c_handle, float *humidity) {
    unsigned char data[3];
    int result;

    result = i2cWriteByte(i2c_handle, TRIGGER_HUMID_MEASURE);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to trigger humidity measurement: %d", result);
        return -1;
    }

    gpioDelay(50); // Wait for measurement (datasheet specifies 50ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        syslog(LOG_ERR, "Failed to read humidity data: %d", result);
        return -1;
    }

    unsigned short raw_humidity = (data[0] << 8) | data[1];
    unsigned char crc = data[2];

    if (calculate_crc(raw_humidity) != crc) {
        syslog(LOG_ERR, "CRC mismatch for humidity data");
        return -1;
    }

    *humidity = -6.0 + 125.0 * ((float)raw_humidity / 65536.0);
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

