        syslog(LOG_ERR, "Socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80); // HTTP port

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr) <= 0) { // Replace with actual API server IP
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection Failed");
        close(sockfd);
        return -1;
    }

    // Construct HTTP POST request
    char request[4096];
    snprintf(request, sizeof(request), 
             "POST %s HTTP/1.1\r\n" \
             "Host: api.example.com\r\n" \
             "Content-Type: application/json\r\n" \
             "Content-Length: %zu\r\n" \
             "Connection: close\r\n" \
             "\r\n" \
             "%s", API_ENDPOINT, json_len, json_data);

    // Send HTTP POST request
    bytes_sent = send(sockfd, request, strlen(request), 0);
    if (bytes_sent < 0) {
        syslog(LOG_ERR, "Send failed");
        close(sockfd);
        return -1;
    }

    // Receive response (basic handling, can be improved)
    bytes_received = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Receive failed");
        close(sockfd);
        return -1;
    }
    buffer[bytes_received] = '\0';
    syslog(LOG_INFO, "HTTP Response: %s", buffer);

    close(sockfd);
    return 0;
}

