            timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Create JSON data
            snprintf(json_data, sizeof(json_data), 
                     "{\"timestamp\": \"%s\", \"humidity\": %.2f, \"temperature\": %.2f}", 
