    // Create the initial log file
    if (create_log_file() != 0) {
        fprintf(stderr, "Failed to create initial log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (1) {
        // Read sensor data
        if (read_tmp117(&sensor_data.temperature) != 0) {
            fprintf(stderr, "Failed to read temperature\n");
            sensor_data.temperature = -999.0; // Indicate error
        }
        if (read_aht20(&sensor_data.humidity) != 0) {
            fprintf(stderr, "Failed to read humidity\n");
            sensor_data.humidity = -999.0; // Indicate error
        }
        if (read_pir(&sensor_data.motion_detected) != 0) {
            fprintf(stderr, "Failed to read PIR sensor\n");
            sensor_data.motion_detected = -1; // Indicate error
        }

        // Get timestamp
        char *timestamp = get_timestamp();

        // Log data
        if (log_data(timestamp, sensor_data.temperature, sensor_data.humidity, sensor_data.motion_detected) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        free(timestamp);

        // Sleep for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0); // Open with TMP117 address first
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device for TMP117: %d\n", i2c_handle);
        return 1;
    }

    // Attempt to read TMP117 to confirm it's present
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) < 0) {
        fprintf(stderr, "TMP117 not found, attempting AHT20\n");
        i2cClose(i2c_handle);
        i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to open I2C device for AHT20: %d\n", i2c_handle);
            return 1;
        }
        // Attempt to read AHT20 to confirm it's present
        if (i2cReadDevice(i2c_handle, buf, 2) < 0) {
            fprintf(stderr, "AHT20 not found\n");
            return 1;
        }
    }

    return 0;
}

int init_gpio() {
    pir_gpio_handle = gpioSetMode(PIR_GPIO, PI_INPUT);
    if (pir_gpio_handle != 0) {
        fprintf(stderr, "Failed to set GPIO mode: %d\n", pir_gpio_handle);
        return 1;
    }
    return 0;
}

int read_tmp117(float *temperature) {
    char buf[2];
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Success
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = raw_temp * 0.0078125;
            return 0;
        } else {
            fprintf(stderr, "I2C read error (TMP117): %d, retries left: %d\n", result, retries);
            gpioDelay(RETRY_DELAY_MS);
            retries--;
        }
    }
    return 1; // Failure after retries
}

int read_aht20(float *humidity) {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    char read_cmd[1] = {0xAC};
    char buf[6];
    int retries = RETRY_COUNT;
    int result;

    // Send initialization command
    result = i2cWriteDevice(i2c_handle, init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "AHT20 init error: %d\n", result);
        return 1;
    }
    gpioDelay(10); // Wait for initialization

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, read_cmd, 1);
    if (result != 0) {
        fprintf(stderr, "AHT20 measurement error: %d\n", result);
        return 1;
    }
    gpioDelay(80); // Wait for measurement

    // Read data
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result == 6) {
            // Success
            uint32_t raw_humidity = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | (buf[3] >> 4);
            *humidity = ((float)raw_humidity / 0x100000) * 100;
            return 0;
        } else {
            fprintf(stderr, "I2C read error (AHT20): %d, retries left: %d\n", result, retries);
            gpioDelay(RETRY_DELAY_MS);
            retries--;
        }
    }
    return 1; // Failure after retries
}

int read_pir(int *motion_detected) {
    *motion_detected = gpioRead(PIR_GPIO);
    return 0;
}

char* get_timestamp() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char *timestamp = malloc(20 * sizeof(char)); // Allocate memory for timestamp
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to allocate memory for timestamp\n");
        return NULL;
    }
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", t);
    return timestamp;
}

int log_data(const char *timestamp, float temperature, float humidity, int motion_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);

    // Check if it's a new day
    if (t->tm_yday != last_midnight) {
        fclose(log_file);
        if (create_log_file() != 0) {
            fprintf(stderr, "Failed to create new log file\n");
            return 1;
        }
        last_midnight = t->tm_yday;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int create_log_file() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char filename[100];
    strftime(filename, sizeof(filename), "%Y-%m-%d.csv", t);

    char filepath[200];
    snprintf(filepath, sizeof(filepath), "%s/%s", LOG_DIR, filename);

    log_file = fopen(filepath, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", filepath);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    }

    return 0;
}

