// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control constants
#define MOTOR_FORWARD 1
#define MOTOR_STOP 0

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction);
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, stopping motor and cleaning up...");
    control_motor(MOTOR_STOP); // Stop the motor
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

// Function to read the rain sensor
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        log_message("Error reading rain sensor.");
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to control the motor
void control_motor(int direction) {
    if (direction == MOTOR_FORWARD) {
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioWrite(MOTOR_ENA_PIN, 1); // Enable the motor
        log_message("Motor started.");
    } else if (direction == MOTOR_STOP) {
        gpioWrite(MOTOR_ENA_PIN, 0); // Disable the motor
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        log_message("Motor stopped.");
    } else {
        log_message("Invalid motor direction.");
    }
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set pull-up resistor on the rain sensor pin
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program started.");

    // Main loop
    while (program_running) {
        int rain_detected = (read_rain_sensor() == 0); // Rain detected if sensor is LOW

        if (rain_detected) {
            log_message("Rain detected!");
            control_motor(MOTOR_FORWARD);
            gpioDelay(5000); // Run motor for 5 seconds
            control_motor(MOTOR_STOP);
        }

        gpioDelay(2000); // Poll every 2 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

