#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, cleaning up and exiting...\n");
    terminate = 1;
}

// Function to read CPU load from /proc/stat
float get_cpu_load()
{
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float load;

    // Read previous CPU stats
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat\n");
        return -1.0; // Indicate error
    }
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat\n");
        fclose(fp);
        return -1.0; // Indicate error
    }
    fclose(fp);

    // Wait for 500ms
    gpioDelay(500000); // 500ms = 500000 microseconds

    // Read current CPU stats
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat\n");
        return -1.0; // Indicate error
    }
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat\n");
        fclose(fp);
        return -1.0; // Indicate error
    }
    fclose(fp);

    // Calculate CPU load
    unsigned long long prev_idle_all = prev_idle + prev_iowait;
    unsigned long long idle_all = idle + iowait;
    unsigned long long prev_non_idle = prev_user + prev_nice + prev_system + prev_irq + prev_softirq + prev_steal;
    unsigned long long non_idle = user + nice + system + irq + softirq + steal;
    unsigned long long prev_total = prev_idle_all + prev_non_idle;
    unsigned long long total = idle_all + non_idle;

    unsigned long long totald = total - prev_total;
    unsigned long long idled = idle_all - prev_idle_all;

    load = (float)(totald - idled) / totald * 100.0;

    return load;
}

// Function to map CPU load to RGB color values
void map_load_to_color(float load, int *red, int *green, int *blue)
{
    if (load < 0.0 || load > 100.0) {
        fprintf(stderr, "Invalid CPU load value: %f\n", load);
        *red = 0; *green = 0; *blue = 0; // Set to black as error
        return;
    }

    if (load <= 50.0) {
        // Green to Yellow
        *red = (int)(load * 255.0 / 50.0);
        *green = 255;
        *blue = 0;
    } else {
        // Yellow to Red
        *red = 255;
        *green = (int)((100.0 - load) * 255.0 / 50.0);
        *blue = 0;
    }
}

// Function to set RGB LED color using PWM
void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float cpu_load;
    int red, green, blue;

    // Main loop
    while (!terminate) {
        // Get CPU load
        cpu_load = get_cpu_load();
        if (cpu_load < 0.0) {
            fprintf(stderr, "Error getting CPU load, using default color\n");
            red = 0; green = 0; blue = 0; // Default to off
        } else {
            // Map CPU load to color
            map_load_to_color(cpu_load, &red, &green, &blue);
        }

        // Set LED color
        set_led_color(red, green, blue);

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Turn off LED before exiting
    set_led_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

