#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define SPI_MODE 0
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 255
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature);
int calculate_duty_cycle(float temperature);
void update_fan_speed(int duty_cycle);
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    unsigned char data[4];
    int result = spiRead(spi_handle, (char *)data, 4);

    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1;
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -1;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1;
    }

    // Extract temperature data (ignoring the fault bit)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 3; // Shift right by 3 to remove fault bit
    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature < 40.0) {
        duty_cycle = (int)((temperature - 25.0) / (40.0 - 25.0) * 50.0);
