#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS = 3)
#define BMP180_OSS 3

// GPIO pin for interrupt
#define INTERRUPT_PIN 2

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile int logging_enabled = 0;
static int ac1, ac2, ac3, b1, b2, mb, mc, md;
static unsigned int ac4, ac5, ac6;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int read_calibration_data(int fd);
int read_raw_temperature(int fd);
int read_raw_pressure(int fd);
float calculate_temperature(int raw_temp);
float calculate_pressure(int raw_pressure, int raw_temp);
float calculate_altitude(float pressure);
void log_data(float temperature, float pressure);
void interrupt_handler(void);
void signal_handler(int signal);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
  if (write(fd, &reg, 1) != 1) {
    perror("Failed to write register address");
    return -1;
  }
  if (read(fd, data, len) != len) {
    perror("Failed to read data");
    return -1;
  }
  return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = value;
  if (write(fd, buf, 2) != 2) {
    perror("Failed to write data");
    return -1;
  }
  return 0;
}

// Read calibration data from BMP180
int read_calibration_data(int fd) {
  uint8_t data[22];
  if (i2c_read_bytes(fd, BMP180_REG_CAL_AC1, data, 22) != 0) {
    fprintf(stderr, "Failed to read calibration data\n");
    return -1;
  }

  ac1 = (data[0] << 8) | data[1];
  ac2 = (data[2] << 8) | data[3];
  ac3 = (data[4] << 8) | data[5];
  ac4 = (data[6] << 8) | data[7];
  ac5 = (data[8] << 8) | data[9];
  ac6 = (data[10] << 8) | data[11];
  b1 = (data[12] << 8) | data[13];
  b2 = (data[14] << 8) | data[15];
  mb = (data[16] << 8) | data[17];
  mc = (data[18] << 8) | data[19];
  md = (data[20] << 8) | data[21];

  return 0;
}

// Read raw temperature value
int read_raw_temperature(int fd) {
  uint8_t data[2];
  if (i2c_write_byte(fd, BMP180_REG_CONTROL, 0x2E) != 0) {
    fprintf(stderr, "Failed to write temperature conversion command\n");
    return -1;
  }
  delay(5); // Wait for conversion (at least 4.5ms)
  if (i2c_read_bytes(fd, BMP180_REG_MSB, data, 2) != 0) {
    fprintf(stderr, "Failed to read raw temperature data\n");
    return -1;
  }
  return (data[0] << 8) | data[1];
}

// Read raw pressure value
int read_raw_pressure(int fd) {
  uint8_t data[3];
  if (i2c_write_byte(fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
    fprintf(stderr, "Failed to write pressure conversion command\n");
    return -1;
  }
  delay(26); // Wait for conversion (25.5ms for OSS = 3)
  if (i2c_read_bytes(fd, BMP180_REG_MSB, data, 3) != 0) {
    fprintf(stderr, "Failed to read raw pressure data\n");
    return -1;
  }
  return ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
}

// Calculate temperature in Celsius
float calculate_temperature(int raw_temp) {
  long x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
  long x2 = ((long)mc << 11) / (x1 + md);
  long b5 = x1 + x2;
  float temperature = ((b5 + 8) >> 4) / 10.0f;
  return temperature;
}

// Calculate pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temp) {
  long x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
  long x2 = ((long)mc << 11) / (x1 + md);
  long b5 = x1 + x2;
  long b6 = b5 - 4000;
  long x3 = ((long)b2 * (b6 * b6) >> 12) >> 11;
  long x4 = ((long)ac2 * b6) >> 11;
  long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
  unsigned long x1_pressure = ((long)ac3 * b6) >> 13;
  unsigned long x2_pressure = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
  unsigned long b4 = ((unsigned long)x1_pressure + x2_pressure + 32768) * ac4 >> 15;
  unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
  long pressure;
  if (b7 < 0x80000000) {
    pressure = (b7 * 2) / b4;
  } else {
    pressure = (b7 / b4) * 2;
  }
  x1_pressure = (pressure >> 8) * (pressure >> 8);
  x1_pressure = (x1_pressure * 3038) >> 16;
  x2_pressure = (-7357 * pressure) >> 16;
  pressure = pressure + (x1_pressure + x2_pressure + 3791) >> 4;
  return pressure;
}

// Calculate altitude in meters
float calculate_altitude(float pressure) {
  float altitude = 44330.0 * (1.0 - pow(pressure / 101325.0, 0.1903));
  return altitude;
}

// Log data to file
void log_data(float temperature, float pressure) {
  time_t now = time(NULL);
  struct tm *t = localtime(&now);
  char timestamp[64];
  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

  fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
  fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler
void interrupt_handler(void) {
  logging_enabled = !logging_enabled;
  printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
  printf("Caught signal %d, cleaning up...\n", signal);
  if (i2c_fd != -1) {
    close(i2c_fd);
  }
  if (log_file != NULL) {
    fclose(log_file);
  }
  wiringPiSetup(); // Reinitialize wiringPi to release GPIO
  pinMode(INTERRUPT_PIN, INPUT); // Set pin to input to release it
  digitalWrite(INTERRUPT_PIN, LOW); // Set low to avoid floating pin
  exit(0);
}

int main() {
  // Initialize WiringPi
  if (wiringPiSetup() == -1) {
    fprintf(stderr, "Failed to initialize WiringPi\n");
    return 1;
  }

  // Set up interrupt pin
  pinMode(INTERRUPT_PIN, INPUT);
  pullUpDnControl(INTERRUPT_PIN, PUD_UP);
  if (wiringPiISR(INTERRUPT_PIN, INT_EDGE_FALLING, &interrupt_handler) < 0) {
    fprintf(stderr, "Unable to setup ISR\n");
    return 1;
  }

  // Open I2C device
  i2c_fd = open("/dev/i2c-1", O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C device");
    return 1;
  }

  // Set I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
    return 1;
  }

  // Read calibration data
  if (read_calibration_data(i2c_fd) != 0) {
    close(i2c_fd);
    return 1;
  }

  // Open log file
  log_file = fopen("altitude_log.txt", "a");
  if (log_file == NULL) {
    perror("Failed to open log file");
    close(i2c_fd);
    return 1;
  }

  // Set up signal handler for Ctrl+C
  signal(SIGINT, signal_handler);

  // Main loop
  while (1) {
    if (logging_enabled) {
      // Read raw temperature and pressure
      int raw_temp = read_raw_temperature(i2c_fd);
      int raw_pressure = read_raw_pressure(i2c_fd);

      if (raw_temp != -1 && raw_pressure != -1) {
        // Calculate temperature and pressure
        float temperature = calculate_temperature(raw_temp);
        float pressure = calculate_pressure(raw_pressure, raw_temp);

        // Log data
        log_data(temperature, pressure);
      } else {
        fprintf(stderr, "Failed to read sensor data\n");
      }
    }
    delay(1000); // Wait for 1 second
  }

  return 0;
}

