  unsigned long x2_pressure = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
  unsigned long b4 = ((unsigned long)x1_pressure + x2_pressure + 32768) * ac4 >> 15;
  unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
  long pressure;
  if (b7 < 0x80000000) {
    pressure = (b7 * 2) / b4;
  } else {
    pressure = (b7 / b4) * 2;
  }
  x1_pressure = (pressure >> 8) * (pressure >> 8);
  x1_pressure = (x1_pressure * 3038) >> 16;
  x2_pressure = (-7357 * pressure) >> 16;
  pressure = pressure + (x1_pressure + x2_pressure + 3791) >> 4;
  return pressure;
}

// Calculate altitude in meters
float calculate_altitude(float pressure) {
  float altitude = 44330.0 * (1.0 - pow(pressure / 101325.0, 0.1903));
  return altitude;
}

// Log data to file
void log_data(float temperature, float pressure) {
  time_t now = time(NULL);
  struct tm *t = localtime(&now);
  char timestamp[64];
  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

  fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
  fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler
void interrupt_handler(void) {
  logging_enabled = !logging_enabled;
  printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
  printf("Caught signal %d, cleaning up...\n", signal);
  if (i2c_fd != -1) {
    close(i2c_fd);
  }
  if (log_file != NULL) {
    fclose(log_file);
  }
  wiringPiSetup(); // Reinitialize wiringPi to release GPIO
  pinMode(INTERRUPT_PIN, INPUT); // Set pin to input to release it
  digitalWrite(INTERRUPT_PIN, LOW); // Set low to avoid floating pin
  exit(0);
}

int main() {
  // Initialize WiringPi
  if (wiringPiSetup() == -1) {
    fprintf(stderr, "Failed to initialize WiringPi\n");
    return 1;
  }

  // Set up interrupt pin
  pinMode(INTERRUPT_PIN, INPUT);
  pullUpDnControl(INTERRUPT_PIN, PUD_UP);
  if (wiringPiISR(INTERRUPT_PIN, INT_EDGE_FALLING, &interrupt_handler) < 0) {
    fprintf(stderr, "Unable to setup ISR\n");
    return 1;
  }

  // Open I2C device
  i2c_fd = open("/dev/i2c-1", O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C device");
    return 1;
  }

  // Set I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
    return 1;
  }

  // Read calibration data
  if (read_calibration_data(i2c_fd) != 0) {
    close(i2c_fd);
    return 1;
  }

  // Open log file
  log_file = fopen("altitude_log.txt", "a");
  if (log_file == NULL) {
    perror("Failed to open log file");
    close(i2c_fd);
    return 1;
  }

  // Set up signal handler for Ctrl+C
  signal(SIGINT, signal_handler);

  // Main loop
  while (1) {
    if (logging_enabled) {
      // Read raw temperature and pressure
      int raw_temp = read_raw_temperature(i2c_fd);
      int raw_pressure = read_raw_pressure(i2c_fd);

      if (raw_temp != -1 && raw_pressure != -1) {
        // Calculate temperature and pressure
        float temperature = calculate_temperature(raw_temp);
        float pressure = calculate_pressure(raw_pressure, raw_temp);

        // Log data
        log_data(temperature, pressure);
      } else {
        fprintf(stderr, "Failed to read sensor data\n");
      }
    }
    delay(1000); // Wait for 1 second
  }

  return 0;
}

