#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RTD_NOMINAL 100.0 // PT100
#define RREF 430.0
#define A 0.0039083
#define B -0.0000005775
#define C -0.00000000041830119

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int read_rtd_value(int handle);
float calculate_temperature(int rtd_value);
void log_temperature(float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    float rtd_nominal;
    float rref;
} config_t;

// Function to read a register from the MAX31865
int spi_read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Set MSB for read
    tx[1] = 0x00;       // Dummy byte

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X\n", reg);
        return -1;
    }

    return rx[1];
}

// Function to write a register in the MAX31865
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2];
    tx[0] = reg & 0x7F; // Clear MSB for write
    tx[1] = value;

    if (spiWrite(handle, tx, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// Function to read the RTD value from the MAX31865
int read_rtd_value(int handle) {
    int rtd_msb, rtd_lsb;

    rtd_msb = spi_read_register(handle, 0x01);
    if (rtd_msb < 0) return -1;

    rtd_lsb = spi_read_register(handle, 0x02);
    if (rtd_lsb < 0) return -1;

    return ((rtd_msb << 8) | rtd_lsb) >> 1; // Remove fault bit
}

// Function to calculate the temperature using the Callendar-Van Dusen equation
float calculate_temperature(int rtd_value) {
    float rtd_resistance = (rtd_value * RREF) / 32768.0;
    float temperature = (rtd_resistance - RTD_NOMINAL) / (RTD_NOMINAL * (A + B * rtd_resistance + C * rtd_resistance * rtd_resistance));
    return temperature;
}

// Function to log the temperature to a file
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Configure MAX31865 (Enable bias, 3-wire, auto conversion)
    if (spi_write_register(spi_handle, 0x00, 0xC2) < 0) { // Enable bias, 3-wire, auto conversion
        fprintf(stderr, "Error: MAX31865 configuration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("rtd_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
    }
    fflush(log_file);

    return 0;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() < 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        int rtd_value = read_rtd_value(spi_handle);
        if (rtd_value < 0) {
            fprintf(stderr, "Error: Failed to read RTD value\n");
        } else {
            float temperature = calculate_temperature(rtd_value);
            log_temperature(temperature);
            printf("Temperature: %.2f C\n", temperature);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

