#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_CHIPID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA_PRESS_MSB 0xF7
#define BME280_REG_DATA_PRESS_LSB 0xF8
#define BME280_REG_DATA_PRESS_XLSB 0xF9
#define BME280_REG_DATA_TEMP_MSB 0xFA
#define BME280_REG_DATA_TEMP_LSB 0xFB
#define BME280_REG_DATA_TEMP_XLSB 0xFC
#define BME280_REG_DATA_HUM_MSB 0xFD
#define BME280_REG_DATA_HUM_LSB 0xFE

// Calibration data registers
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int bme280_init();
int bme280_read_data(float *temperature, float *humidity, float *pressure);
void log_data(float temperature, float humidity, float pressure);
void signal_handler(int signal);
int read_calibration_data();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// BME280 initialization function
int bme280_init() {
    // Check if pigpio is initialized
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BME280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Check the chip ID
    int chip_id = i2cReadByteData(i2c_handle, BME280_REG_CHIPID);
    if (chip_id < 0) {
        fprintf(stderr, "Failed to read chip ID: %d\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%X\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set humidity oversampling to 1x
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Failed to write humidity control register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Failed to write control measurement register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BME280
int read_calibration_data() {
    uint8_t buffer[26];
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_00, (char *)buffer, 26) < 0) {
        fprintf(stderr, "Failed to read calibration data block 1\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib.dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib.dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib.dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib.dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib.dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib.dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib.dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib.dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib.dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib.dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib.dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);
    calib.dig_H1 = buffer[25];

    uint8_t buffer2[7];
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_26, (char *)buffer2, 7) < 0) {
        fprintf(stderr, "Failed to read calibration data block 2\n");
        return -1;
    }

    calib.dig_H2 = (int16_t)buffer2[0] | ((int16_t)buffer2[1] << 8);
    calib.dig_H3 = buffer2[2];
    calib.dig_H4 = (int16_t)((buffer2[3] << 4) | (buffer2[4] & 0x0F));
    calib.dig_H5 = (int16_t)((buffer2[5] << 4) | (buffer2[4] >> 4));
    calib.dig_H6 = (int8_t)buffer2[6];

    return 0;
}

// BME280 data reading function
int bme280_read_data(float *temperature, float *humidity, float *pressure) {
    uint8_t buffer[8];

    // Read pressure, temperature and humidity data
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_DATA_PRESS_MSB, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Failed to read data block\n");
        return -1;
    }

    int32_t raw_pressure = (int32_t)buffer[0] << 12 | (int32_t)buffer[1] << 4 | (int32_t)buffer[2] >> 4;
    int32_t raw_temperature = (int32_t)buffer[3] << 12 | (int32_t)buffer[4] << 4 | (int32_t)buffer[5] >> 4;
    int32_t raw_humidity = (int32_t)buffer[6] << 8 | (int32_t)buffer[7];

    // Temperature compensation
    double var1 = (raw_temperature / 16384.0 - calib.dig_T1 / 1024.0) * calib.dig_T2;
    double var2 = ((raw_temperature / 131072.0 - calib.dig_T1 / 8192.0) * (raw_temperature / 131072.0 - calib.dig_T1 / 8192.0)) * calib.dig_T3;
    double t_fine = var1 + var2;
    *temperature = (t_fine / 5120.0);

    // Pressure compensation
    double var3 = (t_fine / 2.0) - 64000.0;
    double var4 = var3 * var3 * calib.dig_P6 / 32768.0;
    double var5 = var4 + var3 * calib.dig_P5 * 2.0;
    double var6 = (var5 / 4.0) + (calib.dig_P4 * 65536.0);
    double var7 = calib.dig_P3 * var3 * var3 / 524288.0;
    double var8 = calib.dig_P2 * var3 / 524288.0;
    double var9 = (1.0 + var7 + var8) * calib.dig_P1;
    *pressure = 1048576.0 - raw_pressure;
    *pressure = (*pressure - var6 / 4096.0) * 6250.0 / var9;
    var3 = calib.dig_P9 * (*pressure) * (*pressure) / 2147483648.0;
    var4 = (*pressure) * calib.dig_P8 / 32768.0;
    *pressure = *pressure + (var3 + var4 + calib.dig_P7) / 16.0;

    // Humidity compensation
    double var_H = (t_fine - 76800.0);
    var_H = (raw_humidity - (calib.dig_H4 * 64.0 + calib.dig_H5 / 16384.0 * var_H)) * (calib.dig_H2 / 65536.0 * (1.0 + calib.dig_H6 / 67108864.0 * var_H * (1.0 + calib.dig_H3 / 67108864.0 * var_H)));
    *humidity = var_H * (1.0 - calib.dig_H1 * var_H / 524288.0);
    if (*humidity > 100.0)
        *humidity = 100.0;
    else if (*humidity < 0.0)
