#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // Oss = 0
#define BMP180_CMD_PRESSURE1 0x74 // Oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 // Oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 // Oss = 3

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// GPIO pin for alert
#define ALERT_GPIO 24

// Circular buffer size (60 seconds * 20 samples/second = 1200)
#define BUFFER_SIZE 1200

// Structure to hold timestamped pressure value
typedef struct {
    time_t timestamp;
    float pressure;
} PressureReading;

// Circular buffer
PressureReading pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int oss, int *raw_pressure);
float calculate_pressure(int raw_temp, int raw_pressure, int oss);
void add_pressure_reading(float pressure);
float calculate_rolling_average();
void check_pressure_deviation(float current_pressure, float rolling_average);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // I2C bus 1, BMP180 address
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) {
        fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature: %s\n", strerror(errno));
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int oss, int *raw_pressure) {
    char buf[3];
    char cmd;

    switch (oss) {
        case 0: cmd = BMP180_CMD_PRESSURE0; break;
        case 1: cmd = BMP180_CMD_PRESSURE1; break;
        case 2: cmd = BMP180_CMD_PRESSURE2; break;
        case 3: cmd = BMP180_CMD_PRESSURE3; break;
        default: cmd = BMP180_CMD_PRESSURE0; break; // Default to oss = 0
    }

    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, cmd) != 0) {
        fprintf(stderr, "Error writing pressure command: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(2 + (3 << oss)) ; // Wait for conversion

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure: %s\n", strerror(errno));
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - oss);
    return 0;
}

// Function to calculate pressure in hPa
float calculate_pressure(int raw_temp, int raw_pressure, int oss) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 / pow(2, 12))) / pow(2, 11);
    x2 = ac2 * b6 / pow(2, 11);
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << oss) + 2) / 4;

    x1 = ac3 * b6 / pow(2, 13);
    x2 = (b1 * (b6 * b6 / pow(2, 12))) / pow(2, 16);
    x3 = ((x1 + x2) + 2) / pow(2, 2);
    b4 = (ac4 * (unsigned long)(x3 + 32768)) / pow(2, 15);

    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> oss);
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    p = p + (x1 + x2 + 3791) / pow(2, 4);

    return (float)p / 100.0; // Convert to hPa
}

// Function to add a pressure reading to the circular buffer
void add_pressure_reading(float pressure) {
    time_t now = time(NULL);
    pressure_buffer[buffer_index].timestamp = now;
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average of pressure readings
float calculate_rolling_average() {
    float sum = 0.0;
    int count = 0;
    time_t now = time(NULL);

    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (pressure_buffer[i].timestamp != 0) {
            if (difftime(now, pressure_buffer[i].timestamp) <= 60.0) {
                sum += pressure_buffer[i].pressure;
                count++;
            }
        }
    }

    if (count > 0) {
        return sum / count;
    } else {
        return 0.0;
    }
}

// Function to check for pressure deviation and trigger alert
void check_pressure_deviation(float current_pressure, float rolling_average) {
    float deviation = fabs(current_pressure - rolling_average);
    if (deviation > 5.0) {
        fprintf(stderr, "Alert: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa, Deviation: %.2f hPa\n",
                current_pressure, rolling_average, deviation);
        gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
        gpioDelay(1000000);       // Wait 1 second
        gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Ensure GPIO is LOW
    gpioSetMode(ALERT_GPIO, PI_INPUT); // Reset GPIO mode
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure it starts LOW

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_temp, raw_pressure;
        float pressure;
        int oss = 3; // Oversampling setting

        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temp) != 0 || read_raw_pressure(oss, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Calculate pressure
        pressure = calculate_pressure(raw_temp, raw_pressure, oss);

        // Add pressure reading to the buffer
        add_pressure_reading(pressure);

        // Calculate rolling average
        float rolling_average = calculate_rolling_average();

        // Check for pressure deviation
        check_pressure_deviation(pressure, rolling_average);

        // Wait 50ms
        gpioDelay(50000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

