    gpioDelay(2 + (3 << oss)) ; // Wait for conversion

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure: %s\n", strerror(errno));
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - oss);
    return 0;
