float calculate_pressure(int raw_temp, int raw_pressure, int oss) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
