void add_pressure_reading(float pressure) {
    time_t now = time(NULL);
    pressure_buffer[buffer_index].timestamp = now;
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
