        pressure = calculate_pressure(raw_temp, raw_pressure, oss);

        // Add pressure reading to the buffer
        add_pressure_reading(pressure);

        // Calculate rolling average
        float rolling_average = calculate_rolling_average();

        // Check for pressure deviation
        check_pressure_deviation(pressure, rolling_average);

