#define LOG_FILE "fan_log.txt"
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Global variables for signal handling
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
float read_cpu_temp();
int map_temp_to_duty_cycle(float temp);
int set_fan_speed(int duty_cycle);
int log_data(float temp, int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Stop the fan
    set_fan_speed(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_raw;
    float temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_raw) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_raw / 1000.0;
    return temp_celsius;
}

// Function to map temperature to duty cycle
int map_temp_to_duty_cycle(float temp) {
    int duty_cycle;

    if (temp < 40.0) {
        duty_cycle = 0;
    } else if (temp > 70.0) {
        duty_cycle = 255;
    } else {
        duty_cycle = (int)((temp - 40.0) * (255.0 / 30.0));
    }

    return duty_cycle;
}

// Function to set fan speed using PWM
int set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(float temp, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temp, duty_cycle);

    fclose(log_file);
    log_file = NULL; // Reset log_file after closing
    return 0;
}

