    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(FAN_GPIO, 255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read CPU temperature
        temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
            // Consider using a default or previous temperature value here
            temp = 50.0; // Example default temperature
        }

        // Map temperature to duty cycle
        duty_cycle = map_temp_to_duty_cycle(temp);

        // Set fan speed
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed.\n");
        }

        // Log data
        if (log_data(temp, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_fan_speed(0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

