void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize BMP280 sensor
int init_bmp280() {
    // Check if pigpio is initialized
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Check the sensor ID
    char id;
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_ID, &id, 1) != 1) {
        fprintf(stderr, "Failed to read sensor ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (id != 0x58) {
        fprintf(stderr, "Incorrect sensor ID: 0x%x\n", id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set the sensor to forced mode
    char ctrl_meas = 0b00100011; // Oversampling x1, forced mode
    if (i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CTRL_MEAS, &ctrl_meas, 1) != 1) {
        fprintf(stderr, "Failed to write control register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
