    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Check the sensor ID
    char id;
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_ID, &id, 1) != 1) {
        fprintf(stderr, "Failed to read sensor ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (id != 0x58) {
        fprintf(stderr, "Incorrect sensor ID: 0x%x\n", id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set the sensor to forced mode
    char ctrl_meas = 0b00100011; // Oversampling x1, forced mode
    if (i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CTRL_MEAS, &ctrl_meas, 1) != 1) {
        fprintf(stderr, "Failed to write control register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read calibration data from the sensor
