            }
        } else {
            fprintf(stderr, "Failed to read raw data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

