#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pthread.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define LED_PIN 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define TEMP_HYSTERESIS 27.5
#define RETRY_DELAY_SEC 1

// Global variables
static int i2c_fd = -1;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int bus, int addr);
int read_temperature(int fd, float *temperature);
void add_to_buffer(float temperature);
float calculate_average();
void *alert_led_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int fd = wiringPiI2CSetupInterface(bus, addr);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read temperature from LM75 sensor
int read_temperature(int fd, float *temperature) {
    int raw_temp = wiringPiI2CReadReg16(fd, 0); // Read temperature register
    if (raw_temp == -1) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw temperature to Celsius (LM75 format)
    raw_temp = ((raw_temp >> 8) | (raw_temp << 8)); // Byte swap
    raw_temp = raw_temp >> 5; // Shift to get the 11-bit temperature value
    *temperature = (float)raw_temp * 0.125;

    return 0;
}

// Function to add temperature to the circular buffer
void add_to_buffer(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to calculate the running average of the temperature buffer
float calculate_average() {
    float sum = 0.0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / BUFFER_SIZE;
}

// Function for the alert LED thread
void *alert_led_thread(void *arg) {
    float average_temp;
    while (program_running) {
        average_temp = calculate_average();
        if (average_temp > TEMP_THRESHOLD) {
            digitalWrite(LED_PIN, HIGH); // Turn LED on
        } else if (average_temp < TEMP_HYSTERESIS) {
            digitalWrite(LED_PIN, LOW);  // Turn LED off
        }
        delay(100); // Check every 100ms
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    digitalWrite(LED_PIN, LOW); // Turn off LED
    pthread_mutex_destroy(&buffer_mutex);
}

int main() {
    // Initialize WiringPi with GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW); // Initially turn LED off

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, LM75_ADDR);
    if (i2c_fd == -1) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create alert LED thread
    pthread_t alert_thread;
    if (pthread_create(&alert_thread, NULL, alert_led_thread, NULL) != 0) {
        fprintf(stderr, "Error creating alert thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    float temperature;
    // Main loop
    while (program_running) {
        if (read_temperature(i2c_fd, &temperature) == 0) {
            add_to_buffer(temperature);
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, calculate_average());
        } else {
            fprintf(stderr, "Error reading temperature, attempting to re-initialize I2C.\n");
            close(i2c_fd);
            delay(RETRY_DELAY_SEC * 1000); // Wait before retrying
            i2c_fd = init_i2c(I2C_BUS, LM75_ADDR);
            if (i2c_fd == -1) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                program_running = 0; // Exit if re-initialization fails
            }
        }
        delay(1000); // Read temperature every 1 second
    }

    // Clean up and exit
    pthread_join(alert_thread, NULL);
    cleanup();
    return 0;
}

