#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <cjson/cJSON.h>

// Configuration structure
typedef struct {
    float target_temperature;
    float kp;
    float ki;
    float kd;
    int pwm_frequency;
    int pwm_range;
    int spi_channel;
    int spi_speed;
    int failsafe_temperature;
    char log_file_path[256];
} Config;

// Global variables
static volatile int running = 1;
static int spi_handle;
static Config config;

// Function prototypes
int load_config(const char *filename, Config *config);
float read_temperature();
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error, float kp, float ki, float kd);
void set_pwm_duty_cycle(int duty_cycle);
void failsafe();
void signal_handler(int signal);
void log_message(const char *message);

// Function to load configuration from JSON file
int load_config(const char *filename, Config *config) {
    FILE *fp;
    long len;
    char *data;
    cJSON *json;

    // Set default values
    config->target_temperature = 25.0;
    config->kp = 1.0;
    config->ki = 0.1;
    config->kd = 0.01;
    config->pwm_frequency = 1000;
    config->pwm_range = 1000;
    config->spi_channel = 0;
    config->spi_speed = 500000;
    config->failsafe_temperature = 80;
    strcpy(config->log_file_path, "heater.log");

    fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config file %s\n", filename);
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    len = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    data = (char *)malloc(len + 1);
    if (data == NULL) {
        fprintf(stderr, "Error: Could not allocate memory for config file\n");
        fclose(fp);
        return 1;
    }

    fread(data, 1, len, fp);
    data[len] = '\0';
    fclose(fp);

    json = cJSON_Parse(data);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            fprintf(stderr, "Error: JSON parse error: %s\n", error_ptr);
        }
        free(data);
        return 1;
    }

    cJSON *target_temperature = cJSON_GetObjectItemCaseSensitive(json, "target_temperature");
    if (cJSON_IsNumber(target_temperature)) {
        config->target_temperature = target_temperature->valuedouble;
    }

    cJSON *kp = cJSON_GetObjectItemCaseSensitive(json, "kp");
    if (cJSON_IsNumber(kp)) {
        config->kp = kp->valuedouble;
    }

    cJSON *ki = cJSON_GetObjectItemCaseSensitive(json, "ki");
    if (cJSON_IsNumber(ki)) {
        config->ki = ki->valuedouble;
    }

    cJSON *kd = cJSON_GetObjectItemCaseSensitive(json, "kd");
    if (cJSON_IsNumber(kd)) {
        config->kd = kd->valuedouble;
    }

    cJSON *pwm_frequency = cJSON_GetObjectItemCaseSensitive(json, "pwm_frequency");
    if (cJSON_IsNumber(pwm_frequency)) {
        config->pwm_frequency = pwm_frequency->valueint;
    }

    cJSON *pwm_range = cJSON_GetObjectItemCaseSensitive(json, "pwm_range");
    if (cJSON_IsNumber(pwm_range)) {
        config->pwm_range = pwm_range->valueint;
    }

    cJSON *spi_channel = cJSON_GetObjectItemCaseSensitive(json, "spi_channel");
    if (cJSON_IsNumber(spi_channel)) {
        config->spi_channel = spi_channel->valueint;
    }

    cJSON *spi_speed = cJSON_GetObjectItemCaseSensitive(json, "spi_speed");
    if (cJSON_IsNumber(spi_speed)) {
        config->spi_speed = spi_speed->valueint;
    }

    cJSON *failsafe_temperature = cJSON_GetObjectItemCaseSensitive(json, "failsafe_temperature");
    if (cJSON_IsNumber(failsafe_temperature)) {
        config->failsafe_temperature = failsafe_temperature->valueint;
    }

    cJSON *log_file_path = cJSON_GetObjectItemCaseSensitive(json, "log_file_path");
    if (cJSON_IsString(log_file_path) && (log_file_path->valuestring != NULL)) {
        strcpy(config->log_file_path, log_file_path->valuestring);
    }

    cJSON_Delete(json);
    free(data);

    return 0;
}

// Function to read temperature from MAX31865
float read_temperature() {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int rtd_raw;
    float rtd_resistance;
    float temperature;

    // Read RTD MSB and LSB registers (0x01 and 0x02)
    tx_buf[0] = 0x01; // Read RTD MSB
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        log_message("Error: SPI read failed (RTD MSB/LSB)");
        failsafe();
        return -1.0;
    }

    rtd_raw = ((rx_buf[1] << 8) | rx_buf[2]) >> 1; // Combine MSB and LSB, remove fault bit

    // Check for fault
    if (rtd_raw & 0x01) {
        log_message("Error: MAX31865 fault detected");
        failsafe();
        return -1.0;
    }

    // Convert RTD raw value to resistance (PT100)
    rtd_resistance = ((float)rtd_raw * 430.0) / 32768.0;

    // Convert resistance to temperature (using linear approximation)
    temperature = (rtd_resistance - 100.0) / 0.385;

    return temperature;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error, float kp, float ki, float kd) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > config.pwm_range) duty_cycle = config.pwm_range;
    gpioPWM(18, duty_cycle);
}

// Failsafe function
void failsafe() {
    log_message("Failsafe triggered!");
    set_pwm_duty_cycle(0);
    gpioTerminate();
    exit(1);
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    log_message("Signal received, shutting down...");
}

// Function to log messages with timestamps
void log_message(const char *message) {
