// Configuration structure
typedef struct {
    float target_temperature;
    float kp;
    float ki;
    float kd;
    int pwm_frequency;
    int pwm_range;
    int spi_channel;
    int spi_speed;
    int failsafe_temperature;
    char log_file_path[256];
} Config;

// Global variables
