#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 //oss = 0
#define BMP180_CMD_PRESSURE1 0x74 //oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 //oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 //oss = 3

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature();
int read_raw_pressure(int oss);
long calculate_temperature(int ut);
long calculate_pressure(int up, int oss);
void log_breach(const char *message);
void signal_handler(int signal);
int i2c_read_retry(int handle, int reg, char *buf, int count);
int i2c_write_retry(int handle, int reg, char *buf, int count);

// Function to read a 16-bit value from the I2C bus
int16_t read_i2c_word(int handle, int reg)
{
    char buf[2];
    if (i2c_read_retry(handle, reg, buf, 2) != 0) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the I2C bus
uint16_t read_i2c_uword(int handle, int reg)
{
    char buf[2];
    if (i2c_read_retry(handle, reg, buf, 2) != 0) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B1);
    b2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B2);
    mb = read_i2c_word(i2c_handle, BMP180_REG_CAL_MB);
    mc = read_i2c_word(i2c_handle, BMP180_REG_CAL_MC);
    md = read_i2c_word(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature()
{
    char buf[1];
    buf[0] = BMP180_CMD_TEMP;

    if (i2c_write_retry(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 0) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    return read_i2c_word(i2c_handle, BMP180_REG_MSB);
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int oss)
{
    char buf[1];
    buf[0] = (oss == 0) ? BMP180_CMD_PRESSURE0 :
           (oss == 1) ? BMP180_CMD_PRESSURE1 :
           (oss == 2) ? BMP180_CMD_PRESSURE2 : BMP180_CMD_PRESSURE3;

    if (i2c_write_retry(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 0) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    gpioDelay(2 + (3 << oss)) ; // Wait for conversion

    char data[3];
    if (i2c_read_retry(i2c_handle, BMP180_REG_MSB, data, 3) != 0) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    return ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | (int32_t)data[2]) >> (8 - oss);
}

// Function to calculate the temperature in degrees Celsius
long calculate_temperature(int ut)
{
    long x1 = (((long)ut - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    long t = (b5 + 8) >> 4;
    return t;
}

// Function to calculate the pressure in Pascals
long calculate_pressure(int up, int oss)
{
    long x1, x2, x3, b3, b6, p;
    unsigned long b4, b7;

    long ut = read_raw_temperature();
    if (ut == -1) return -1;

    long x1_temp = (((long)ut - (long)ac6) * (long)ac5) >> 15;
    long x2_temp = ((long)mc << 11) / (x1_temp + md);
    long b5 = x1_temp + x2_temp;

    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << oss) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (unsigned long)(x3 + 32768)) >> 15;

    b7 = ((unsigned long)up - b3) * (50000 >> oss);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return p;
}

// Function to log a breach to the log file
void log_breach(const char *message)
{
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// I2C read with retry
int i2c_read_retry(int handle, int reg, char *buf, int count)
{
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, reg, buf, count);
        if (result >= 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C read error (reg 0x%02X, count %d), retrying...\n", reg, count);
        gpioDelay(10000); // Wait 10ms
        retries--;
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X, count %d)\n", reg, count);
    return -1; // Failure
}

// I2C write with retry
int i2c_write_retry(int handle, int reg, char *buf, int count)
{
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cWriteI2CBlockData(handle, reg, buf, count);
        if (result >= 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write error (reg 0x%02X, count %d), retrying...\n", reg, count);
        gpioDelay(10000); // Wait 10ms
        retries--;
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, count %d)\n", reg, count);
    return -1; // Failure
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int ut = read_raw_temperature();
        int up = read_raw_pressure(3); // Use oss = 3 for highest accuracy
        if (ut != -1 && up != -1) {
            long temperature = calculate_temperature(ut);
            long pressure = calculate_pressure(up, 3);

            if (temperature > 3000) {
                char message[100];
                snprintf(message, sizeof(message), "Temperature breach: %.2f C", (float)temperature / 10.0);
                log_breach(message);
            }

            if (pressure < 95000) {
                char message[100];
                snprintf(message, sizeof(message), "Pressure breach: %.2f hPa", (float)pressure / 100.0);
                log_breach(message);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

