#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define HEATER_GPIO 17
#define PWM_FREQUENCY 1000 // 1 kHz
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 0.8
#define Kp 1.0
#define Ki 0.1
#define LOG_FILE "heater_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature);
void set_heater_duty_cycle(int gpio_pin, float duty_cycle);
float pi_controller(float target_temperature, float current_temperature, float *integral);
void log_data(FILE *log_file, float temperature, float duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold PI controller state
typedef struct {
    float integral;
} PIControllerState;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set heater GPIO as output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle\n");
    }

    return 0;
}

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    char buffer[4];
    int result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read failed\n");
        return 1;
    }

    // Check for fault bits
    if (buffer[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return 2;
    }
    if (buffer[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return 3;
    }
    if (buffer[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return 4;
    }

    // Extract temperature data
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(int gpio_pin, float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    int pwm_value = (int)(duty_cycle * 255.0);
    gpioPWM(gpio_pin, pwm_value);
}

// Function to implement PI controller
float pi_controller(float target_temperature, float current_temperature, float *integral) {
    float error = target_temperature - current_temperature;
    *integral += error;

    // Anti-windup
    if (*integral > 100) *integral = 100;
    if (*integral < -100) *integral = -100;

    float output = Kp * error + Ki * (*integral);
    return output;
}

