void log_data(FILE *log_file, float temperature, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    // Turn off heater
    set_heater_duty_cycle(HEATER_GPIO, 0.0);

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    float temperature;
    float duty_cycle = 0.0;
    float integral = 0.0;
    PIControllerState pi_state = {0.0};

    // Main loop
    while (!terminate) {
        // Read temperature
        int read_result = read_max31855(spi_handle, &temperature);
        if (read_result != 0) {
            // Handle error: set duty cycle to 0 and log error
            set_heater_duty_cycle(HEATER_GPIO, 0.0);
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s,ERROR,MAX31855 Fault: %d\n", timestamp, read_result);
            fflush(log_file);
            duty_cycle = 0.0; // Ensure duty cycle is 0 after error
        } else {
            // Calculate duty cycle using PI controller
            float pi_output = pi_controller(TARGET_TEMPERATURE, temperature, &integral);
            duty_cycle = pi_output;

            // Set heater duty cycle
            set_heater_duty_cycle(HEATER_GPIO, duty_cycle);

            // Log data
            log_data(log_file, temperature, duty_cycle);
        }

        // Wait for a short period
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

