#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature file path
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temp = 0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1; // Indicate error
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        if (ferror(fp)) {
            fprintf(stderr, "Error: Could not read temperature from file.\n");
            fclose(fp);
            return -1; // Indicate error
        } else {
            fprintf(stderr, "Error: Empty temperature file.\n");
            fclose(fp);
            return -1; // Indicate error
        }
    }

    fclose(fp);

    // Convert string to integer
    char *endptr;
    temp = strtol(buffer, &endptr, 10);

    // Check for conversion errors
    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Invalid temperature value.\n");
        return -1; // Indicate error
    }

    return temp;
}

// Function to set RGB LED color using PWM
int set_led_color(int red, int green, int blue) {
    int result;

    result = gpioPWM(RED_PIN, 255 - red);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set red PWM value. pigpio error code: %d\n", result);
        return -1;
    }

    result = gpioPWM(GREEN_PIN, 255 - green);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set green PWM value. pigpio error code: %d\n", result);
        return -1;
    }

    result = gpioPWM(BLUE_PIN, 255 - blue);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set blue PWM value. pigpio error code: %d\n", result);
        return -1;
    }

    return 0;
}

int main() {
    int temperature;
    int red, green, blue;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temperature = read_cpu_temp();

        if (temperature != -1) {
            // Determine LED color based on temperature
            if (temperature < 40000) {
                red = 0;
                green = 0;
                blue = 255;
            } else if (temperature < 60000) {
                red = 0;
                green = 255;
                blue = 0;
            } else {
                red = 255;
                green = 0;
                blue = 0;
            }

            // Set LED color
            if (set_led_color(red, green, blue) != 0) {
                // Error already printed in set_led_color
                terminate = 1; // Exit loop on error
            }

            // Print temperature and PWM values
            printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temperature, red, green, blue);
        } else {
            fprintf(stderr, "Error: Failed to read temperature. Skipping this cycle.\n");
        }

        // Wait for 0.5 seconds
        usleep(500000); // 500000 microseconds = 0.5 seconds
    }

    // Turn off all channels
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

