#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 5

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int error_code;
} DHT22Data;

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read DHT22 data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int bit_idx = 0;
    int byte_idx = 0;
    unsigned int data_buffer[5] = {0, 0, 0, 0, 0};
    int i;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); //30us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the DHT22 to pull the line low (response signal)
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
        gpioDelay(1); // Check every 1us
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (low)\n");
        data.error_code = -1; // Timeout error
        return data;
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (high)\n");
        data.error_code = -1; // Timeout error
        return data;
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (end)\n");
        data.error_code = -1; // Timeout error
        return data;
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
            gpioDelay(1);
            timeout++;
        }

        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for bit start (low)\n");
            data.error_code = -1; // Timeout error
            return data;
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
            gpioDelay(1);
            timeout++;
        }

        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for bit end (high)\n");
            data.error_code = -1; // Timeout error
            return data;
        }

        long end = gpioTick();
        if ((end - start) > 40) {
            data_buffer[byte_idx] |= (1 << (7 - bit_idx));
        }

        bit_idx++;
        if (bit_idx == 8) {
            bit_idx = 0;
            byte_idx++;
        }
    }

    // Validate checksum
    if ((data_buffer[0] + data_buffer[1] + data_buffer[2] + data_buffer[3]) != data_buffer[4]) {
        fprintf(stderr, "DHT22: Checksum mismatch\n");
        data.error_code = -2; // Checksum error
        return data;
    }

    // Convert data to temperature and humidity
