#include <wiringPi.h>
#include <wiringPiI2C.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define OSS 3

// GPIO pin for button
#define BUTTON_PIN 4

// I2C bus
#define I2C_BUS 1

// Global variables
static int i2c_fd;
static volatile int logging_enabled = 0;
static volatile unsigned long last_interrupt_time = 0;
static int ac1, ac2, ac3, b1, b2, mb, mc, md;
static unsigned int ac4, ac5, ac6;

// Function prototypes
int init_i2c(int bus, int addr);
int read_calibration_data(int fd);
int read_raw_temperature(int fd);
int read_raw_pressure(int fd);
long calculate_true_temperature(int ut);
long calculate_true_pressure(int up, int ut);
void log_pressure(float pressure);
void button_interrupt_handler(void);
void signal_handler(int sig);

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

// Function to read calibration data from BMP180
int read_calibration_data(int fd) {
    ac1 = wiringPiI2CReadReg16(fd, BMP180_REG_CAL_AC1); if (ac1 == -1) { fprintf(stderr, "Error reading AC1\n"); return -1; }
    ac2 = wiringPiI2CReadReg16(fd, BMP180_REG_CAL_AC2); if (ac2 == -1) { fprintf(stderr, "Error reading AC2\n"); return -1; }
    ac3 = wiringPiI2CReadReg16(fd, BMP180_REG_CAL_AC3); if (ac3 == -1) { fprintf(stderr, "Error reading AC3\n"); return -1; }
    ac4 = wiringPiI2CReadReg16(fd, BMP180_REG_CAL_AC4); if (ac4 == -1) { fprintf(stderr, "Error reading AC4\n"); return -1; }
    ac5 = wiringPiI2CReadReg16(fd, BMP180_REG_CAL_AC5); if (ac5 == -1) { fprintf(stderr, "Error reading AC5\n"); return -1; }
    ac6 = wiringPiI2CReadReg16(fd, BMP180_REG_CAL_AC6); if (ac6 == -1) { fprintf(stderr, "Error reading AC6\n"); return -1; }
    b1 = wiringPiI2CReadReg16(fd, BMP180_REG_CAL_B1); if (b1 == -1) { fprintf(stderr, "Error reading B1\n"); return -1; }
    b2 = wiringPiI2CReadReg16(fd, BMP180_REG_CAL_B2); if (b2 == -1) { fprintf(stderr, "Error reading B2\n"); return -1; }
    mb = wiringPiI2CReadReg16(fd, BMP180_REG_CAL_MB); if (mb == -1) { fprintf(stderr, "Error reading MB\n"); return -1; }
    mc = wiringPiI2CReadReg16(fd, BMP180_REG_CAL_MC); if (mc == -1) { fprintf(stderr, "Error reading MC\n"); return -1; }
    md = wiringPiI2CReadReg16(fd, BMP180_REG_CAL_MD); if (md == -1) { fprintf(stderr, "Error reading MD\n"); return -1; }

    // Validate calibration data (example: check if AC1 is zero, which is unlikely)
    if (ac1 == 0 || ac2 == 0 || ac3 == 0 || ac4 == 0 || ac5 == 0 || ac6 == 0) {
        fprintf(stderr, "Error: Invalid calibration data. Sensor may be faulty.\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature value
int read_raw_temperature(int fd) {
    wiringPiI2CWriteReg8(fd, BMP180_REG_CONTROL, 0x2E);
    delay(5); // Wait 4.5ms
    int msb = wiringPiI2CReadReg8(fd, BMP180_REG_MSB); if (msb == -1) { fprintf(stderr, "Error reading temperature MSB\n"); return -1; }
    int lsb = wiringPiI2CReadReg8(fd, BMP180_REG_LSB); if (lsb == -1) { fprintf(stderr, "Error reading temperature LSB\n"); return -1; }
    return (msb << 8) | lsb;
}

// Function to read raw pressure value
int read_raw_pressure(int fd) {
    wiringPiI2CWriteReg8(fd, BMP180_REG_CONTROL, 0x34 + (OSS << 6));
    delay(27); // Wait 25.5ms for OSS = 3
    int msb = wiringPiI2CReadReg8(fd, BMP180_REG_MSB); if (msb == -1) { fprintf(stderr, "Error reading pressure MSB\n"); return -1; }
    int lsb = wiringPiI2CReadReg8(fd, BMP180_REG_LSB); if (lsb == -1) { fprintf(stderr, "Error reading pressure LSB\n"); return -1; }
    int xlsb = wiringPiI2CReadReg8(fd, BMP180_REG_XLSB); if (xlsb == -1) { fprintf(stderr, "Error reading pressure XLSB\n"); return -1; }
    return ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
}

// Function to calculate true temperature
long calculate_true_temperature(int ut) {
    long x1 = (((long)ut - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    return (b5 + 8) >> 4;
}

// Function to calculate true pressure
long calculate_true_pressure(int up, int ut) {
    long x1 = (((long)ut - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    long b6 = b5 - 4000;
    long x3 = ((long)b2 * ((b6 * b6) >> 12)) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1) * 4 + x3) << OSS) + 2) >> 2;
    unsigned long x1_pressure = ((long)ac3 * b6) >> 13;
    unsigned long x2_pressure = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
    unsigned long b4 = ((unsigned long)ac4 * (x1_pressure + x2_pressure + 32768)) >> 15;
    unsigned long b7 = ((unsigned long)up - b3) * (50000 >> OSS);
    long p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

// Function to log pressure to file
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

// Button interrupt handler
void button_interrupt_handler(void) {
    unsigned long current_time = millis();
    if (current_time - last_interrupt_time > 200000) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = current_time;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Exiting...\n");
    close(i2c_fd);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BMP180_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd) == -1) {
        close(i2c_fd);
        return 1;
    }

    // Set up button interrupt
    pinMode(BUTTON_PIN, INPUT);
    pullUpDnControl(BUTTON_PIN, PUD_UP);
    if (wiringPiISR(BUTTON_PIN, INT_EDGE_FALLING, button_interrupt_handler) < 0) {
        fprintf(stderr, "Error setting up button interrupt: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("BMP180 pressure logger started. Press button to toggle logging.\n");

    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            int ut = read_raw_temperature(i2c_fd);
            int up = read_raw_pressure(i2c_fd);

            if (ut != -1 && up != -1) {
                // Calculate true temperature and pressure
                long true_temperature = calculate_true_temperature(ut);
                long true_pressure = calculate_true_pressure(up, ut);

                // Convert pressure to hPa
                float pressure_hpa = (float)true_pressure / 100.0;

                // Log pressure
                log_pressure(pressure_hpa);
            } else {
                fprintf(stderr, "Error reading temperature or pressure. Skipping logging.\n");
            }
        }
        delay(2000); // Wait 2 seconds
    }

    return 0;
}

