#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <curl/curl.h>
#include <getopt.h>
#include <pigpio.h>

// Configuration
#define DEFAULT_URL "http://your-librarys-api-call.com/api/humidity"
#define GPIO_PIN 4
#define MAX_RETRIES 3
#define RETRY_BACKOFF_SECONDS 2
#define READ_INTERVAL_SECONDS 10

// Global variables
static volatile int running = 1;
static char *api_url = DEFAULT_URL;

// Structure to hold DHT22 data
typedef struct {
    float humidity;
    float temperature;
} DHT22Data;

// Function prototypes
int read_dht22(DHT22Data *data);
int validate_checksum(const unsigned char *data);
int post_data(const char *url, const char *json_data);
void signal_handler(int signal);
void cleanup();

// Helper function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    static char timestamp[20]; // Ensure it's static to persist after function returns
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to read DHT22 data
int read_dht22(DHT22Data *data) {
    int i, j;
    unsigned char raw_data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);
    gpioDelay(1000); // 1ms
    gpioWrite(GPIO_PIN, 1);
    gpioDelay(30); // 20-40us

    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Wait for the DHT22 to pull the line low (response signal)
    int timeout = 0;
    while (gpioRead(GPIO_PIN) == 1 && timeout < 100) {
        gpioDelay(1); // Check every 1us
        timeout++;
    }

    if (timeout >= 100) {
        syslog(LOG_ERR, "%s DHT22 response timeout (initial low).", get_timestamp());
        return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(GPIO_PIN) == 0 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= 100) {
        syslog(LOG_ERR, "%s DHT22 response timeout (initial high).", get_timestamp());
        return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(GPIO_PIN) == 1 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= 100) {
        syslog(LOG_ERR, "%s DHT22 response timeout (data start).", get_timestamp());
        return -1; // Timeout
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(GPIO_PIN) == 0 && timeout < 100) {
            gpioDelay(1);
            timeout++;
        }

        if (timeout >= 100) {
            syslog(LOG_ERR, "%s DHT22 response timeout (bit start low).", get_timestamp());
            return -1; // Timeout
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(GPIO_PIN) == 1 && timeout < 100) {
            gpioDelay(1);
            timeout++;
        }

        if (timeout >= 100) {
            syslog(LOG_ERR, "%s DHT22 response timeout (bit high).", get_timestamp());
            return -1; // Timeout
        }

        long end = gpioTick();
        int duration = end - start;

        raw_data[i / 8] <<= 1;
        if (duration > 40) { // Adjust threshold as needed
            raw_data[i / 8] |= 1;
        }
    }

    // Validate checksum
    if (validate_checksum(raw_data) != 0) {
        syslog(LOG_ERR, "%s DHT22 checksum validation failed.", get_timestamp());
        return -1;
    }

    // Convert data to humidity and temperature
    data->humidity = (float)(((raw_data[0] << 8) | raw_data[1])) / 10.0;
    data->temperature = (float)(((raw_data[2] << 8) | raw_data[3]) & 0x7FFF) / 10.0;
    if (raw_data[2] & 0x80) {
        data->temperature *= -1;
    }

    return 0;
}

// Function to validate the checksum
int validate_checksum(const unsigned char *data) {
    return (data[0] + data[1] + data[2] + data[3]) & 0xFF;
}

// Function to post data to the API
int post_data(const char *url, const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "%s curl_easy_perform() failed: %s", get_timestamp(), curl_easy_strerror(res));
            curl_slist_free_all(headers);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            return -1;
        }

        long response_code;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
        if (response_code < 200 || response_code >= 300) {
            syslog(LOG_ERR, "%s HTTP POST failed with code: %ld", get_timestamp(), response_code);
            curl_slist_free_all(headers);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            return -1;
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        curl_global_cleanup();
        return 0;
    } else {
        syslog(LOG_ERR, "%s curl_easy_init() failed", get_timestamp());
        curl_global_cleanup();
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "%s Received signal %d, shutting down...", get_timestamp(), signal);
    running = 0;
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "%s Cleaning up and exiting...", get_timestamp());
    gpioTerminate();
    curl_global_cleanup();
    closelog();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;
    DHT22Data dht22_data;
    char json_data[100]; // Buffer for JSON data
    int read_retries, post_retries;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "%s pigpio initialisation failed", get_timestamp());
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "%s Starting DHT22 monitor, API URL: %s", get_timestamp(), api_url);

    // Main loop
    while (running) {
        read_retries = 0;
        post_retries = 0;

        // Read DHT22 data with retries
        while (read_retries < MAX_RETRIES) {
            if (read_dht22(&dht22_data) == 0) {
                syslog(LOG_INFO, "%s DHT22 read successful: Humidity = %.1f%%, Temperature = %.1f°C", get_timestamp(), dht22_data.humidity, dht22_data.temperature);

                // Format data as JSON
                snprintf(json_data, sizeof(json_data), "{\"humidity\": %.1f, \"temperature\": %.1f}", dht22_data.humidity, dht22_data.temperature);

                // Post data to API with retries
                while (post_retries < MAX_RETRIES) {
                    if (post_data(api_url, json_data) == 0) {
                        syslog(LOG_INFO, "%s Data posted successfully to %s", get_timestamp(), api_url);
                        break; // Exit post retries
                    } else {
                        post_retries++;
                        syslog(LOG_WARNING, "%s HTTP POST failed, retrying (%d/%d)...", get_timestamp(), post_retries, MAX_RETRIES);
                        sleep(RETRY_BACKOFF_SECONDS * post_retries);
                    }
                }

                if (post_retries == MAX_RETRIES) {
                    syslog(LOG_ERR, "%s HTTP POST failed after %d retries, giving up.", get_timestamp(), MAX_RETRIES);
                }

                break; // Exit read retries
            } else {
                read_retries++;
                syslog(LOG_WARNING, "%s DHT22 read failed, retrying (%d/%d)...", get_timestamp(), read_retries, MAX_RETRIES);
                sleep(RETRY_BACKOFF_SECONDS * read_retries);
            }
        }

        if (read_retries == MAX_RETRIES) {
            syslog(LOG_ERR, "%s DHT22 read failed after %d retries, giving up.", get_timestamp(), MAX_RETRIES);
        }

        sleep(READ_INTERVAL_SECONDS);
    }

    cleanup();
    return 0;
}

