#include <errno.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"

volatile sig_atomic_t program_running = 1;

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to read current fan state from file
int read_fan_state() {
    FILE *fp;
    int state = -1;

    fp = fopen(FAN_STATE_FILE, "r");
    if (fp == NULL) {
        perror("Error opening fan state file");
        return -1;
    }

    if (fscanf(fp, "%d", &state) != 1) {
        fprintf(stderr, "Error reading fan state from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return state;
}

// Function to write fan state to file
int write_fan_state(int state) {
    FILE *fp;

    fp = fopen(FAN_STATE_FILE, "w");
    if (fp == NULL) {
        perror("Error opening fan state file for writing");
        return -1;
    }

    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to read max fan state from file
int read_max_fan_state() {
    FILE *fp;
    int max_state = -1;

    fp = fopen(MAX_STATE_FILE, "r");
    if (fp == NULL) {
        perror("Error opening max fan state file");
        return -1;
    }

    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max fan state from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return max_state;
}

// Function to determine fan state based on temperature
int determine_fan_state(int temp, int max_state) {
    if (temp < 45000) {
        return 0;
    } else if (temp < 55000) {
        return 1;
    } else if (temp < 65000) {
        return 2;
    } else {
        return max_state;
    }
}

// Function to log fan state changes
int log_fan_state_change(int new_state) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: Fan state changed to %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, new_state);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    program_running = 0;
    printf("Caught signal %d, shutting down...\n", signum);
}

int main() {
    int current_temp, current_fan_state, new_fan_state, max_fan_state;
    struct timespec sleep_time = {5, 0}; // 5 seconds

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read max fan state
    max_fan_state = read_max_fan_state();
    if (max_fan_state == -1) {
        fprintf(stderr, "Failed to read max fan state. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read current temperature
        current_temp = read_cpu_temp();
        if (current_temp == -1) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in 5 seconds.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Determine new fan state
        new_fan_state = determine_fan_state(current_temp, max_fan_state);

        // Read current fan state
        current_fan_state = read_fan_state();
        if (current_fan_state == -1) {
            fprintf(stderr, "Failed to read current fan state. Assuming 0 and setting to new state.\n");
            current_fan_state = 0; // Assume off if we can't read
        }

        // Update fan state if necessary
        if (new_fan_state != current_fan_state) {
            if (write_fan_state(new_fan_state) == 0) {
                if (log_fan_state_change(new_fan_state) != 0) {
                    fprintf(stderr, "Failed to log fan state change.\n");
                }
            } else {
                fprintf(stderr, "Failed to write new fan state.\n");
            }
        }

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Shutdown sequence
    printf("Shutting down fan...\n");
    if (write_fan_state(0) == 0) {
        if (log_fan_state_change(0) != 0) {
            fprintf(stderr, "Failed to log fan shutdown.\n");
        }
    } else {
        fprintf(stderr, "Failed to shut down fan.\n");
    }

    printf("Exiting.\n");
    return 0;
}

