#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000000 // 0-100% duty cycle
#define TARGET_TEMPERATURE 50.0
#define LOG_FILE "heater_log.txt"

// PID Gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Function Prototypes
int initialize_gpio();
int initialize_spi();
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error);
int set_pwm_duty_cycle(double duty_cycle);
int log_data(double temperature, double duty_cycle, double pid_output);
void signal_handler(int signal);
void cleanup();

// Signal Handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Read Temperature from MAX31855
double read_temperature() {
    char buffer[4];
    int status = spiRead(spi_handle, buffer, 4);
    if (status != 4) {
        fprintf(stderr, "SPI read failed\n");
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (buffer[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return -1000.0;
    }
    if (buffer[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1000.0;
    }
    if (buffer[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1000.0;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Calculate PID Output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Set PWM Duty Cycle
int set_pwm_duty_cycle(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;

    int pwm_value = (int)(duty_cycle * PWM_RANGE / 100.0);
    gpioPWM(HEATER_GPIO, pwm_value);
    return 0;
}

// Log Data to File
int log_data(double temperature, double duty_cycle, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Cleanup Resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioPWM(HEATER_GPIO, 0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize_gpio() != 0) return 1;
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    double integral = 0.0;
    double previous_error = 0.0;
    double duty_cycle = 0.0;
    double pid_output = 0.0;
    double temperature = 0.0;

    printf("Temperature Control System Started\n");

    while (running) {
        temperature = read_temperature();

        if (temperature < -999.0) {
            fprintf(stderr, "Error reading temperature, disabling heater.\n");
            set_pwm_duty_cycle(0.0);
            log_data(temperature, 0.0, 0.0);
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Failsafe: Disable heater if temperature is out of range
        if (temperature > 100.0 || temperature < 0.0) {
            fprintf(stderr, "Temperature out of range (%.2f), disabling heater.\n", temperature);
            set_pwm_duty_cycle(0.0);
            log_data(temperature, 0.0, 0.0);
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        pid_output = calculate_pid(TARGET_TEMPERATURE, temperature, &integral, &previous_error);
        duty_cycle = pid_output;

        set_pwm_duty_cycle(duty_cycle);
        log_data(temperature, duty_cycle, pid_output);

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

