#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel connected to LM35
#define PWM_FREQUENCY 25000 // 25 kHz
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define DUTY_MIN 0.0
#define DUTY_MAX 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
static volatile int keepRunning = 1;
static FILE *logFile = NULL;

// Function prototypes
float readTemperature();
float mapTemperatureToDutyCycle(float temperature);
int setFanSpeed(float dutyCycle);
int logData(float temperature, float dutyCycle);
void signalHandler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MCP3008 via SPI
float readTemperature() {
    unsigned char buffer[3];
    int adcValue;
    float temperature;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | MCP3008_CHANNEL) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "Error: SPI data read failed: %s\n", strerror(errno));
        return -1.0; // Indicate error
    }

    adcValue = ((buffer[1] & 0x03) << 8) + buffer[2];

    // Convert ADC value to temperature (assuming 10mV/°C, 0°C offset)
    temperature = (float)adcValue * 0.01; // LM35 outputs 10mV/°C

    return temperature;
}

// Function to map temperature to duty cycle
float mapTemperatureToDutyCycle(float temperature) {
    float dutyCycle;

    if (temperature <= TEMP_MIN) {
        dutyCycle = DUTY_MIN;
    } else if (temperature >= TEMP_MAX) {
        dutyCycle = DUTY_MAX;
    } else {
