#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

// Define I2C bus
#define I2C_BUS 1

// Define multiplexer control pins (example, adjust as needed)
#define MUX_SELECT_PIN 4 // GPIO pin connected to multiplexer select input

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int i2c_handle, int sensor_address, float *flow_rate);
unsigned char crc8(const unsigned char *data, int len);
void log_data(float flow1, float flow2);
void signal_handler(int signal);
int select_sensor(int sensor_address);

// Structure to hold sensor data
typedef struct {
    float flow_rate;
