    if (sensor_address == SENSOR1_ADDR) {
        gpioWrite(MUX_SELECT_PIN, 0); // Select sensor 1
    } else if (sensor_address == SENSOR2_ADDR) {
        gpioWrite(MUX_SELECT_PIN, 1); // Select sensor 2
    } else {
        fprintf(stderr, "Error: Invalid sensor address: 0x%02X\n", sensor_address);
        return -1;
    }
    gpioDelay(10); // Small delay to allow multiplexer to settle
    return 0;
}

// Function to read data from a sensor
int read_sensor(int i2c_handle, int sensor_address, float *flow_rate) {
    unsigned char data[3];
    int retries = 3;
    int result;

    while (retries > 0) {
        if (select_sensor(sensor_address) != 0) {
            fprintf(stderr, "Error selecting sensor 0x%02X\n", sensor_address);
            return -1;
        }

        result = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (result == 3) {
            // CRC check
            unsigned char crc = crc8(data, 2);
            if (crc == data[2]) {
                // Convert data to flow rate (example conversion, adjust as needed)
                int raw_flow = (data[0] << 8) | data[1];
                *flow_rate = (float)raw_flow / 100.0; // Example scaling
                return 0; // Success
            } else {
                fprintf(stderr, "CRC check failed for sensor 0x%02X\n", sensor_address);
                return -1; // CRC failure
            }
        } else {
            fprintf(stderr, "I2C read error for sensor 0x%02X, result: %d\n", sensor_address, result);
            retries--;
            gpioDelay(10); // Small delay before retry
        }
    }

    fprintf(stderr, "Failed to read sensor 0x%02X after multiple retries\n", sensor_address);
    return -1; // Failure after retries
}

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

