    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen("flow_log.txt", "a");
    if (fp != NULL) {
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening log file!\n");
    }
}

