    gpioSetMode(MUX_SELECT_PIN, PI_OUTPUT);

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow1, flow2;

    // Main loop
    while (program_running) {
        if (read_sensor(i2c_handle1, SENSOR1_ADDR, &flow1) == 0 &&
            read_sensor(i2c_handle2, SENSOR2_ADDR, &flow2) == 0) {
            log_data(flow1, flow2);
        } else {
            fprintf(stderr, "Failed to read data from one or more sensors\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

