#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A 17
#define ENCODER_B 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
volatile int encoder_position = 0;
volatile int last_encoder_position = 0;
volatile int running = 1;

// Function prototypes
int initialize_gpio();
int read_encoder_state();
void update_encoder_position(int new_state);
float calculate_angle(int position);
int log_position(float angle);
void signal_handler(int signal);
void cleanup();

// Structure to hold the last encoder state
struct {
    int last_state;
} encoder_state = {0};

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ENCODER_A, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A, PI_PUD_UP);
    gpioSetMode(ENCODER_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B, PI_PUD_UP);

    return 0;
}

// Function to read the current state of the encoder
int read_encoder_state() {
    int a = gpioRead(ENCODER_A);
    int b = gpioRead(ENCODER_B);

    return (a << 1) | b;
}

// Function to update the encoder position based on the new state
void update_encoder_position(int new_state) {
    int delta = new_state - encoder_state.last_state;

    if (delta == 1 || delta == -3) {
        encoder_position = (encoder_position + 1) % PULSES_PER_REVOLUTION;
    } else if (delta == 3 || delta == -1) {
        encoder_position = (encoder_position - 1 + PULSES_PER_REVOLUTION) % PULSES_PER_REVOLUTION;
    } else if (delta == 2 || delta == -2) {
        // Invalid state transition, ignore
        return;
    }

    encoder_state.last_state = new_state;
}

// Function to calculate the angle in degrees
float calculate_angle(int position) {
    return (float)position / PULSES_PER_REVOLUTION * 360.0;
}

// Function to log the position to a file
int log_position(float angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", s, angle);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int current_state = read_encoder_state();
        update_encoder_position(current_state);

        if (encoder_position != last_encoder_position) {
            float angle = calculate_angle(encoder_position);
            if (log_position(angle) != 0) {
                fprintf(stderr, "Error logging position\n");
            }
            last_encoder_position = encoder_position;
        }

        gpioDelay(1000); // Delay for 1ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

