#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

// Global variables
static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int pulses);
int log_rpm(double rpm);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine (ISR)
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate RPM
double calculate_rpm(int pulses) {
    return (double)pulses * 60.0; // Assuming one pulse per revolution
}

// Function to log RPM to file
int log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f RPM\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written immediately
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    // Disable interrupt handler
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        cleanup();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Reset pulse count
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate RPM
        double rpm = calculate_rpm(current_pulse_count);

        // Log RPM
        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Error logging RPM\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    cleanup();
    printf("RPM monitoring stopped.\n");
    return 0;
}

