#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void control_led(uint16_t ir_value);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// GPIO initialization function
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Logging initialization function
int init_logging() {
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, RED_REG, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    data->red = (buf[1] << 8) | buf[0];
    data->ir = (buf[3] << 8) | buf[2];

    return 0;
}

// Function to log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%u,%u\n", timestamp, data.red, data.ir);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the LED
void control_led(uint16_t ir_value) {
    if (ir_value > IR_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
            control_led(sensor_data.ir);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpio uses microseconds
    }

    cleanup();
    return 0;
}

