    gpioSetMode(AUDIO_PIN, PI_INPUT);
    gpioSetMode(GAIN_PIN, PI_OUTPUT);

    // Set gain to 60dB (LOW)
    gpioWrite(GAIN_PIN, 0);

    return 0;
}

// Function to detect rising edge
int detect_rising_edge() {
    int current_level = gpioRead(AUDIO_PIN);
    gpioDelay(1); // Small delay to avoid reading the same value
    int next_level = gpioRead(AUDIO_PIN);

    if (current_level == 0 && next_level == 1) {
        return 1; // Rising edge detected
    }
    return 0; // No rising edge
}

// Function to log event to file
