    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s 1\n", s);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Audio event logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (detect_rising_edge()) {
            if (log_event() != 0) {
                fprintf(stderr, "Error logging event!\n");
            }
        }
        gpioDelay(10); // Poll every 10ms
    }

    // Clean up GPIO
    gpioTerminate();
    printf("Audio event logger stopped.\n");
    return 0;
}

