#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_LOG_FILE "flow_log.csv"
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define FLOW_SCALE_FACTOR 0.0625 // uL/min per raw unit (example value, check datasheet)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    uint16_t raw_value;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int initialize();
int read_sensor_data(sensor_data_t *data);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(sensor_data_t *data);
float convert_to_flow_rate(uint16_t raw_value);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data from I2C
int read_sensor_data(sensor_data_t *data) {
    char buf[3];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1;
    }

    data->raw_value = (buf[0] << 8) | buf[1];
    data->crc = buf[2];

    return 0;
}

// Calculate CRC8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(sensor_data_t *data) {
    uint8_t data_to_crc[2];
    data_to_crc[0] = (data->raw_value >> 8) & 0xFF; // MSB
    data_to_crc[1] = data->raw_value & 0xFF;      // LSB

    uint8_t calculated_crc = calculate_crc(data_to_crc, 2);
    if (calculated_crc != data->crc) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", calculated_crc, data->crc);
        return -1;
    }
    return 0;
}

// Convert raw value to flow rate (uL/min)
float convert_to_flow_rate(uint16_t raw_value) {
    return (float)raw_value * FLOW_SCALE_FACTOR;
}

// Log flow rate to CSV file
int log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    sensor_data_t sensor_data;
    float flow_rate;

    printf("Monitoring flow rate... Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (validate_crc(&sensor_data) == 0) {
                flow_rate = convert_to_flow_rate(sensor_data.raw_value);
                log_flow_rate(flow_rate);
                printf("Flow rate: %.2f uL/min\n", flow_rate);
            } else {
                fprintf(stderr, "CRC validation failed. Skipping reading.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(1000); // Wait 1000 ms
    }

    cleanup();
    return 0;
}

