void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    data->tvoc = (buf[0] << 8) | buf[1];
    data->eco2 = (buf[2] << 8) | buf[3];

    return 0;
}

