#define GPIO_PIN 17
#define TAMPER_LABEL "ttp223_tamper"
#define TOUCH_THRESHOLD_SEC 5
#define POLL_INTERVAL_MS 100

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to log an intrusion alert with a timestamp
void log_intrusion() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("Intrusion detected at: %s\n", buf);
}

// Function to perform cleanup before exiting
void cleanup() {
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set back to input
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Or PI_PUD_UP if needed

    // Set consumer label
    gpioSetUserFuncEx(GPIO_PIN, 0, NULL, NULL); // Remove any existing user function
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Remove any existing alert function
    gpioSetMode(GPIO_PIN, PI_INPUT); // Ensure it's an input
    gpioSetMode(GPIO_PIN, PI_INPUT); // Ensure it's an input

    // Variables for touch detection
    int touch_count = 0;
    time_t touch_start_time = 0;
    int touch_state = 0; // 0 = released, 1 = touched

    printf("Tamper detection system started. Monitoring GPIO %d...\n", GPIO_PIN);

