        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        if (sensor_value == 1) { // Sensor is touched (HIGH)
            if (touch_state == 0) { // Transition from released to touched
                touch_state = 1;
                touch_start_time = time(NULL);
                touch_count = 1; // Start counting
            } else { // Already touched, keep counting
                touch_count++;
            }
        } else { // Sensor is released (LOW)
            if (touch_state == 1) { // Transition from touched to released
                touch_state = 0;
                touch_count = 0; // Reset count
            }
        }

        if (touch_state == 1 && (time(NULL) - touch_start_time) >= TOUCH_THRESHOLD_SEC) {
            log_intrusion();
            touch_state = 0; // Reset state after logging
            touch_count = 0; // Reset count
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for 100ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

