#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

#define AUDIO_DEVICE "default" // Or "hw:0,0" if needed
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define SAMPLE_SIZE 2 // Bytes per sample (16-bit)
#define GPIO_PIN 17
#define FILENAME "audio_capture.pcm"

static volatile int keep_running = 1;
static FILE *audio_file = NULL;
static snd_pcm_t *pcm_handle = NULL;

void signal_handler(int sig);
int initialize_alsa(snd_pcm_t **pcm_handle);
int initialize_gpio(int gpio_pin);
int set_gpio_output(int gpio_pin, int value);
int capture_audio(snd_pcm_t *pcm_handle, FILE *audio_file);
void cleanup(snd_pcm_t *pcm_handle, FILE *audio_file);

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        keep_running = 0;
    }
}

int initialize_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, AUDIO_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device %s: %s\n", AUDIO_DEVICE, snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

int initialize_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_OUTPUT);
    return 0;
}

int set_gpio_output(int gpio_pin, int value) {
    gpioWrite(gpio_pin, value);
    return 0;
}

int capture_audio(snd_pcm_t *pcm_handle, FILE *audio_file) {
    int err;
    int frames = 1024; // Number of frames to read at a time
    short *buffer = (short *) malloc(frames * NUM_CHANNELS * SAMPLE_SIZE);
    if (!buffer) {
        fprintf(stderr, "Failed to allocate buffer\n");
        return -1;
    }

    while (keep_running) {
        err = snd_pcm_readi(pcm_handle, buffer, frames);
        if (err == -EPIPE) {
            /* EPIPE means overrun */
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading PCM: %s\n", snd_strerror(err));
            break;
        } else if (err != frames) {
            fprintf(stderr, "Short read, read %d frames\n", err);
        }

        // Select left channel (GPIO low)
        if (set_gpio_output(GPIO_PIN, 0) != 0) {
            fprintf(stderr, "Error setting GPIO output\n");
            break;
        }

        size_t bytes_written = fwrite(buffer, 1, frames * NUM_CHANNELS * SAMPLE_SIZE, audio_file);
        if (bytes_written != frames * NUM_CHANNELS * SAMPLE_SIZE) {
            fprintf(stderr, "Error writing to file\n");
            break;
        }

        // Select right channel (GPIO high)
        if (set_gpio_output(GPIO_PIN, 1) != 0) {
            fprintf(stderr, "Error setting GPIO output\n");
            break;
        }

        bytes_written = fwrite(buffer, 1, frames * NUM_CHANNELS * SAMPLE_SIZE, audio_file);
        if (bytes_written != frames * NUM_CHANNELS * SAMPLE_SIZE) {
            fprintf(stderr, "Error writing to file\n");
            break;
        }

    }

    free(buffer);
    return 0;
}

void cleanup(snd_pcm_t *pcm_handle, FILE *audio_file) {
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    if (audio_file) {
        fclose(audio_file);
    }
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);

    if (initialize_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    if (initialize_alsa(&pcm_handle) != 0) {
        fprintf(stderr, "ALSA initialization failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    audio_file = fopen(FILENAME, "wb");
    if (!audio_file) {
        fprintf(stderr, "Error opening file %s for writing\n", FILENAME);
        cleanup(pcm_handle, NULL);
        return 1;
    }

    if (capture_audio(pcm_handle, audio_file) != 0) {
        fprintf(stderr, "Audio capture failed. Exiting.\n");
    }

    cleanup(pcm_handle, audio_file);

    return 0;
}

