#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define sensor absent timeout in seconds
#define SENSOR_ABSENT_TIMEOUT 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_flame_sensor();
void start_fan();
void stop_fan();
void log_event(const char *event_type);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Structure to hold program state
typedef struct {
    int flame_detected;
    time_t last_valid_reading;
} ProgramState;

ProgramState state = {0, 0};

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int reading = gpioRead(FLAME_SENSOR_PIN);
    if (reading < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", reading);
        return -1; // Indicate error
    }
    return reading;
}

// Function to start the cooling fan
void start_fan() {
    gpioPWM(FAN_PIN, 128); // 50% duty cycle
    log_event("FAN_START");
}

// Function to stop the cooling fan
void stop_fan() {
    gpioPWM(FAN_PIN, 0); // 0% duty cycle
    log_event("FAN_STOP");
}

// Function to log events with ISO 8601 timestamps
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", buf, event_type);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

