#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FLAME_SENSOR_GPIO 20
#define LOG_FILE "flame_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
int get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *info;
    struct timespec ts;

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    time(&rawtime);
    info = gmtime(&rawtime);

    if (info == NULL) {
        perror("gmtime");
        return -1;
    }

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", info);
    return 0;
}

// Function to log the flame state to a file
int log_flame_state(const char *timestamp, int state) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d\n", timestamp, state) < 0) {
        perror("fprintf");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    int current_state, previous_state = -1; // Initialize to an invalid state
    char timestamp[30];

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO20 as an input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        current_state = gpioRead(FLAME_SENSOR_GPIO);

        if (current_state != previous_state) {
            if (get_iso8601_timestamp(timestamp) == 0) {
                if (log_flame_state(timestamp, current_state) != 0) {
                    fprintf(stderr, "Error logging flame state.\n");
                }
            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }
            previous_state = current_state;
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

