#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_CONTINUOUS 0xCC10 // Continuous conversion mode, auto range
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LUX_CONVERSION_FACTOR 0.01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_sensor();
float read_lux();
char* get_iso8601_timestamp();
int log_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int config_sensor() {
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (CONFIG_CONTINUOUS >> 8) & 0xFF; // MSB
    buf[2] = CONFIG_CONTINUOUS & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read lux value from the sensor
float read_lux() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1.0;
    }

    uint16_t raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)(raw_value & 0x0FFF) * LUX_CONVERSION_FACTOR;
    return lux;
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(float lux_value) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp); // Free the allocated memory
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (config_sensor() != 0) {
        cleanup();
        return 1;
    }

    printf("Starting data logging...\n");

    // Main loop
    while (!terminate) {
        float lux_value = read_lux();
        if (lux_value >= 0) {
            if (log_data(lux_value) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

