#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the touch sensor channels
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a single GPIO pin
int read_gpio(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log the sensor data to the console
void log_sensor_data(int sensor_states[]) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        return; // Exit if timestamp allocation failed
    }

    printf("%s - ", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf("%d", sensor_states[i]);
    }
    printf("\n");

    free(timestamp); // Free the allocated memory
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Configure GPIO pins as inputs
    for (int i = 0; i < num_channels; i++) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as input\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop to read and log sensor data
    while (program_running) {
        int sensor_states[num_channels];

        // Read the state of each sensor channel
        for (int i = 0; i < num_channels; i++) {
            int value = read_gpio(gpio_pins[i]);
            if (value < 0) {
                // Error reading GPIO, exit the loop
                program_running = 0;
                break;
            }
            sensor_states[i] = value;
        }

        // Log the sensor data if no error occurred during reading
        if (program_running) {
            log_sensor_data(sensor_states);
        }

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

