const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the state of all sensor channels
int read_sensor_channels(int *channel_states)
{
    for (int i = 0; i < num_sensors; i++)
    {
        int level = gpioRead(sensor_pins[i]);
        if (level < 0) {
            fprintf(stderr, "Error reading pin %d: %d\n", sensor_pins[i], level);
            return -1; // Indicate an error
        }
        channel_states[i] = level;
    }
    return 0; // Indicate success
}

// Function to format the current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    for (int i = 0; i < num_sensors; i++)
    {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0)
        {
            fprintf(stderr, "Failed to set pin %d as input\n", sensor_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Install the SIGINT signal handler
    signal(SIGINT, sigint_handler);

    // Main loop to read sensor data and print to console
    while (!terminate)
    {
        int channel_states[num_sensors];
        if (read_sensor_channels(channel_states) == 0) {
            char timestamp[21];
            get_iso8601_timestamp(timestamp);

            printf("%s,%d,%d,%d,%d,%d,%d,%d,%d,%d\n",
                   timestamp,
                   channel_states[0],
                   channel_states[1],
                   channel_states[2],
                   channel_states[3],
                   channel_states[4],
                   channel_states[5],
                   channel_states[6],
                   channel_states[7]);
        } else {
            fprintf(stderr, "Error reading sensor channels, retrying...\n");
        }

        gpioDelay(50); // Wait 50 milliseconds
    }

    // Release GPIO resources and terminate the pigpio library
    gpioTerminate();

    return 0;
}

