#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TILT_SENSOR_GPIO 4 // BCM GPIO 7

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int tilt_state;

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO4 as input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    printf("Tilt Sensor Monitoring Program\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the GPIO pin
        gpio_status = gpioRead(TILT_SENSOR_GPIO);

        if (gpio_status == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", TILT_SENSOR_GPIO);
            gpioTerminate();
            return 1;
        } else if (gpio_status == PI_NOT_INITIALISED) {
            fprintf(stderr, "pigpio not initialised\n");
            gpioTerminate();
            return 1;
        } else if (gpio_status == PI_INIT_FAILED) {
            fprintf(stderr, "pigpio initialisation failed\n");
            gpioTerminate();
            return 1;
        } else {
            // Determine tilt state
            if (gpio_status == 0) {
                tilt_state = 0; // Tilted
            } else {
                tilt_state = 1; // Not Tilted
            }

            // Print the tilt state
            if (tilt_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout); // Flush stdout to ensure immediate output
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

