#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define UV_INDEX_REG 0x2C
#define ALS_VIS_REG 0x22
#define CSV_FILE "uv_als_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int *uv_index, int *als_visible);
void process_sensor_data(int raw_uv, int raw_als, float *uv_index, float *als_visible);
int log_data(float uv_index, float als_visible);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    float uv_index;
    float als_visible;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int *uv_index, int *als_visible) {
    char buf[2];

    // Read UV index
    if (i2cReadI2CBlockData(i2c_handle, UV_INDEX_REG, buf, 1) != 1) {
        fprintf(stderr, "Error reading UV index: %d\n", i2c_handle);
        return -1;
    }
    *uv_index = buf[0];

    // Read ALS visible
    if (i2cReadI2CBlockData(i2c_handle, ALS_VIS_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading ALS visible: %d\n", i2c_handle);
        return -1;
    }
    *als_visible = (buf[1] << 8) | buf[0];

    return 0;
}

// Function to process sensor data
void process_sensor_data(int raw_uv, int raw_als, float *uv_index, float *als_visible) {
    *uv_index = (float)raw_uv / 10.0; // UV index is stored as 1/10th of the actual value
    *als_visible = (float)raw_als; // ALS visible is in lux
}

// Function to log data to CSV file
int log_data(float uv_index, float als_visible) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(CSV_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
        fprintf(log_file, "timestamp,uv_index,als_visible\n"); // Write header if file is new
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Si1145 sensor logging started. Press Ctrl+C to exit.\n");

    int uv_index_raw, als_visible_raw;
    float uv_index, als_visible;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&uv_index_raw, &als_visible_raw) == 0) {
            // Process sensor data
            process_sensor_data(uv_index_raw, als_visible_raw, &uv_index, &als_visible);

            // Log data
            if (log_data(uv_index, als_visible) != 0) {
                fprintf(stderr, "Error logging data\n");
