#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define ALARM_GPIO 17
#define FLOW_RATE_SCALE 0.0625 // ml/min per unit
#define START_COMMAND 0x3608
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

// Global variables
int i2c_handle1, i2c_handle2;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int handle;
    int address;
    char *name;
} sensor_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_flow_rate(int handle, float *flow_rate);
uint8_t calculate_crc(uint8_t data[], int len);
void log_data(float avg_flow_rate);
void set_alarm(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read flow rate from the sensor
int read_flow_rate(int handle, float *flow_rate) {
    uint8_t buffer[3];
    int result;

    // Send start command
    result = i2cWriteWordData(handle, 0x00, START_COMMAND);
    if (result < 0) {
        fprintf(stderr, "Error writing start command: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait 100ms

    // Read 3 bytes of data
    result = i2cReadDevice(handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // CRC validation
    uint8_t crc_data[2] = {buffer[0], buffer[1]};
    uint8_t crc = calculate_crc(crc_data, 2);
    if (crc != buffer[2]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert to flow rate
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    *flow_rate = (float)raw_flow * FLOW_RATE_SCALE;

    return 0;
}

// Function to calculate CRC
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to log data to file
void log_data(float avg_flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Average Flow Rate: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, avg_flow_rate);
    fflush(log_file);
}

// Function to set the alarm state
void set_alarm(int state) {
    gpioWrite(ALARM_GPIO, state);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    set_alarm(0); // Turn off alarm
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle1 < 0 || i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    set_alarm(0); // Initially off

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    float flow_rate1, flow_rate2, avg_flow_rate;
    int valid_readings;

    // Main loop
    while (!terminate) {
        valid_readings = 0;
        flow_rate1 = 0.0;
        flow_rate2 = 0.0;

        // Read from sensor 1
        if (read_flow_rate(i2c_handle1, &flow_rate1) == 0) {
            valid_readings++;
        } else {
            fprintf(stderr, "Error reading from sensor 1\n");
        }

        // Read from sensor 2
        if (read_flow_rate(i2c_handle2, &flow_rate2) == 0) {
            valid_readings++;
        } else {
            fprintf(stderr, "Error reading from sensor 2\n");
        }

        // Calculate average flow rate
        if (valid_readings > 0) {
            avg_flow_rate = (flow_rate1 + flow_rate2) / valid_readings;
        } else {
            avg_flow_rate = 0.0;
        }

        // Log data
        log_data(avg_flow_rate);

        // Set alarm
        if (avg_flow_rate < 0.5) {
            set_alarm(1);
        } else {
            set_alarm(0);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

