#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and sensor value
typedef struct {
    time_t timestamp;
    int sensor_value;
} SensorData;

// Circular buffer
SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(time_t timestamp, int sensor_value);
void dump_buffer();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor value
        int sensor_value = read_sensor();

        // Get current timestamp
        time_t current_time = time(NULL);

        // Add data to the circular buffer
        add_to_buffer(current_time, sensor_value);

        // Check for obstacle detection (LOW signal)
        if (sensor_value == 0) {
            // Get current time for alert message
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print alert message
            printf("Obstacle detected at: %s\n", timestamp);
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // Delay in microseconds
    }

    // Dump the buffer before exiting
    dump_buffer();

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

// Function to initialize the pigpio library and configure the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, int sensor_value) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].sensor_value = sensor_value;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to dump the contents of the buffer to stdout
void dump_buffer() {
    printf("\n--- Sensor Data Dump ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Correct index calculation
        struct tm *timeinfo = localtime(&buffer[index].timestamp);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("Timestamp: %s, Sensor Value: %d\n", timestamp, buffer[index].sensor_value);
    }
    printf("--- End of Data Dump ---\n");
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

