#define MODE_CONTINUOUS 0x01
#define X_REG 0x02
#define Y_REG 0x04
#define Z_REG 0x06
#define CSV_FILE "fan_health.csv"
#define SAMPLE_INTERVAL_MS 500
#define ACTIVATION_TIMEOUT_MS 1000

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int set_sensor_mode(int fd, uint8_t mode);
int read_sensor_data(int fd, sensor_data_t *data);
int write_csv_header(FILE *fp);
int write_csv_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);
int wait_for_sensor_activation(int fd);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (register select) error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (register select) error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "I2C read block error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Set sensor mode function
int set_sensor_mode(int fd, uint8_t mode) {
    return i2c_write_reg(fd, MODE_REG, mode);
}

// Read sensor data function
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t raw_data[6];
    if (i2c_read_block(fd, X_REG, raw_data, 6) != 0) {
        return -1;
    }

    data->x = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    data->y = (int16_t)((raw_data[2] << 8) | raw_data[3]);
    data->z = (int16_t)((raw_data[4] << 8) | raw_data[5]);

    return 0;
}

