    uint8_t status;
    int retries = 0;
    const int max_retries = ACTIVATION_TIMEOUT_MS / 10; // Check every 10ms

    while (retries < max_retries) {
        if (i2c_read_reg(fd, 0x01, &status) == 0) { // Assuming status register is 0x01
            if (status & 0x01) { // Assuming bit 0 indicates active status
                return 0; // Sensor is active
            }
        } else {
            fprintf(stderr, "Error reading sensor status, retrying...\n");
        }
        gpioDelay(10); // Wait 10ms
        retries++;
