    i2c_fd = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set sensor mode to continuous
    if (set_sensor_mode(i2c_fd, MODE_CONTINUOUS) != 0) {
        fprintf(stderr, "Error setting sensor mode\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Wait for sensor activation
    if (wait_for_sensor_activation(i2c_fd) != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        if (write_csv_header(csv_file) != 0) {
            fclose(csv_file);
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }
    rewind(csv_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            if (write_csv_data(csv_file, sensor_data) != 0) {
                fprintf(stderr, "Error writing data to CSV, continuing...\n");
            }
            fflush(csv_file); // Flush the buffer to ensure data is written
        } else {
            fprintf(stderr, "Error reading sensor data, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    // Cleanup
    fclose(csv_file);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

