#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18

// Define the stall detection threshold (in seconds)
#define STALL_THRESHOLD 2

// Define the log file name
#define LOG_FILE "stall_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold the last stall time
struct StallData {
    time_t last_stall_time;
};

struct StallData stall_data = {0};

// Function prototypes
int read_sensor(int gpio_pin);
int is_stalled(int sensor1_value, int sensor2_value);
void log_stall(time_t timestamp);
void signal_handler(int signal);
int initialize_gpio();
void cleanup();

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid sensor reading on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to determine if a stall has occurred
int is_stalled(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
}

// Function to log a stall event to the log file
void log_stall(time_t timestamp) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the log file is open
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    // Check for duplicate entries
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size > 0) {
        fseek(log_file, -20, SEEK_END); // Read the last 20 characters (timestamp length)
        char last_line[21];
        fread(last_line, 1, 20, log_file);
        last_line[20] = '\0';
        if (strcmp(last_line, timestamp_str) == 0) {
            printf("Duplicate stall event detected. Not logging.\n");
            return;
        }
    }

    fprintf(log_file, "%s\n", timestamp_str);
    fflush(log_file); // Ensure the data is written to the file immediately
    printf("Stall logged: %s\n", timestamp_str);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    running = 0;
}

// Function to initialize the pigpio library and set up GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);

    return 0;
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Error reading sensor, skip this iteration
            gpioDelay(100); // Small delay to avoid busy-waiting
            continue;
        }

        if (is_stalled(sensor1_value, sensor2_value)) {
            time_t current_time = time(NULL);
            if (difftime(current_time, stall_data.last_stall_time) >= STALL_THRESHOLD) {
                log_stall(current_time);
                stall_data.last_stall_time = current_time;
            }
        } else {
            stall_data.last_stall_time = 0; // Reset stall time if not stalled
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

