#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TMAG5170 I2C address
#define TMAG5170_ADDR 0x08

// TMAG5170 register addresses
#define REG_X_AXIS 0x00
#define REG_Y_AXIS 0x02
#define REG_Z_AXIS 0x04
#define REG_CONFIG 0x09

// Configuration values
#define CONFIG_CONTINUOUS_MODE 0x00 // Continuous conversion mode
#define CONFIG_ALL_AXES_ENABLED 0x07 // All three axes enabled
#define CONFIG_50MT_RANGE 0x00      // 50 mT range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int config_sensor();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0); // I2C bus 1, address 0x08, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Sensor configuration function
int config_sensor() {
    char config_data[2];
    config_data[0] = REG_CONFIG;
    config_data[1] = (CONFIG_CONTINUOUS_MODE << 6) | (CONFIG_ALL_AXES_ENABLED << 3) | CONFIG_50MT_RANGE;

    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error configuring sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char reg_addr;
    char raw_data[2];
    int16_t raw_value;
    float sensitivity = 0.0001; // 100 uT/LSB = 0.0001 T/LSB

    // Read X axis
    reg_addr = REG_X_AXIS;
    if (i2cWriteDevice(i2c_handle, &reg_addr, 1) != 0) {
        fprintf(stderr, "Error writing X axis register address\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, raw_data, 2) != 2) {
        fprintf(stderr, "Error reading X axis data\n");
        return -1;
    }
    raw_value = (raw_data[0] << 8) | raw_data[1];
    data->x = (float)raw_value * sensitivity;

    // Read Y axis
    reg_addr = REG_Y_AXIS;
    if (i2cWriteDevice(i2c_handle, &reg_addr, 1) != 0) {
        fprintf(stderr, "Error writing Y axis register address\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, raw_data, 2) != 2) {
        fprintf(stderr, "Error reading Y axis data\n");
        return -1;
    }
    raw_value = (raw_data[0] << 8) | raw_data[1];
    data->y = (float)raw_value * sensitivity;

    // Read Z axis
    reg_addr = REG_Z_AXIS;
    if (i2cWriteDevice(i2c_handle, &reg_addr, 1) != 0) {
        fprintf(stderr, "Error writing Z axis register address\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, raw_data, 2) != 2) {
        fprintf(stderr, "Error reading Z axis data\n");
        return -1;
    }
    raw_value = (raw_data[0] << 8) | raw_data[1];
    data->z = (float)raw_value * sensitivity;

    return 0;
}

// Function to log data to CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (config_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

