#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile int running = 1;

// Function to get current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log messages to the log file
void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(fp, "%s\n", message);
    fclose(fp);
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Enable pull-down resistor
    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to handle the alert (print to stdout and log to file)
void handle_alert() {
    char *timestamp = get_timestamp();
    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "%s ALERT: Water detected", timestamp);

    printf("%s\n", log_message_buffer);
    log_message(log_message_buffer);

    free(timestamp);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Water level sensor daemon started. Monitoring GPIO %d...\n", GPIO_PIN);

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            handle_alert();
        } else if (sensor_value < 0) {
            char *timestamp = get_timestamp();
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "%s ERROR: GPIO read failed", timestamp);
            log_message(error_message);
            free(timestamp);

            gpioTerminate(); // Terminate pigpio
            sleep(REINIT_DELAY_SEC);
            if (initialize_gpio() != 0) {
                fprintf(stderr, "GPIO re-initialization failed. Exiting.\n");
                running = 0; // Exit the loop if re-initialization fails
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    // Clean up and exit
    gpioTerminate();
    printf("Water level sensor daemon stopped.\n");
    return 0;
}

