#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
int running = 1;
FILE *log_file = NULL;

// Function to get current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure static allocation

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to calculate RPM
float calculate_rpm(int pulses) {
    return (float)pulses * 60.0; // Assuming one pulse per revolution
}

// Function to log RPM data to file and stdout
void log_rpm(float rpm) {
    char* timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s %.2f\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
    }
    printf("%s %.2f\n", timestamp, rpm);
}

// Interrupt handler for rising edge detection
void pulse_callback(int gpio, int level, uint32_t tick) {
    __sync_fetch_and_add(&pulse_count, 1); // Atomic increment
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt handler
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

