#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define quadrature states
typedef enum {
    STATE_00 = 0,
    STATE_01 = 1,
    STATE_11 = 2,
    STATE_10 = 3
} QuadratureState;

// Structure to hold the program state
typedef struct {
    QuadratureState current_state;
    FILE *log_file;
    pthread_mutex_t mutex;
    volatile sig_atomic_t terminate;
} ProgramState;

// Global program state
ProgramState state;

// Function prototypes
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_rotation(const char *direction);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int sensor_a_value, sensor_b_value;
    QuadratureState next_state;

    // Read the current state of both sensors
    sensor_a_value = gpioRead(SENSOR_A_PIN);
    sensor_b_value = gpioRead(SENSOR_B_PIN);

    // Determine the next state based on the current state and sensor values
    switch (state.current_state) {
        case STATE_00:
            next_state = (sensor_a_value == 1) ? STATE_01 : STATE_10;
            break;
        case STATE_01:
            next_state = (sensor_b_value == 1) ? STATE_11 : STATE_00;
            break;
        case STATE_11:
            next_state = (sensor_a_value == 0) ? STATE_10 : STATE_01;
            break;
        case STATE_10:
            next_state = (sensor_b_value == 0) ? STATE_00 : STATE_11;
            break;
        default:
            next_state = STATE_00; // Should not happen, but handle it anyway
            break;
    }

    // Determine the direction of rotation
    const char *direction;
    if (next_state == STATE_01 || next_state == STATE_10) {
        direction = "clockwise";
    } else {
        direction = "counter-clockwise";
    }

    // Log the rotation event
    log_rotation(direction);

    // Update the current state
    state.current_state = next_state;
}

// Function to log rotation events to a file
void log_rotation(const char *direction) {
    struct timespec ts;
    char timestamp[30];

    // Get the current time with millisecond precision
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    // Format the timestamp
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    // Lock the mutex before accessing the shared resource (log file)
    pthread_mutex_lock(&state.mutex);

    // Write the log entry to the file
    fprintf(state.log_file, "%s %s\n", timestamp, direction);
    fflush(state.log_file); // Ensure the data is written to disk immediately

    // Unlock the mutex
    pthread_mutex_unlock(&state.mutex);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    state.terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    // Initialize the quadrature state
    state.current_state = STATE_00;

    // Open the log file
    state.log_file = fopen(LOG_FILE, "a");
    if (state.log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Initialize the mutex
    if (pthread_mutex_init(&state.mutex, NULL) != 0) {
        perror("pthread_mutex_init");
        fclose(state.log_file);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handlers for both sensors
    if (gpioSetISRFuncEx(SENSOR_A_PIN, EITHER_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for SENSOR_A_PIN\n");
        pthread_mutex_destroy(&state.mutex);
        fclose(state.log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(SENSOR_B_PIN, EITHER_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for SENSOR_B_PIN\n");
        pthread_mutex_destroy(&state.mutex);
        fclose(state.log_file);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Disable interrupts
    gpioSetISRFuncEx(SENSOR_A_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(SENSOR_B_PIN, EITHER_EDGE, 0, NULL, NULL);

    // Close the log file
    if (state.log_file != NULL) {
        fclose(state.log_file);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&state.mutex);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the program
    if (initialize() != 0) {
        return 1;
    }

    printf("Rotation logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!state.terminate) {
        // Sleep for a short interval to avoid busy-waiting
        gpioDelay(100); // Sleep for 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Rotation logger terminated.\n");
    return 0;
}

