#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

int main() {
    // Initialize syslog
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    syslog(LOG_INFO, "Program started");

    // Main loop
    while (program_running) {
        // Read touch sensor value
        int touch_value = gpioRead(TOUCH_SENSOR_PIN);

        // Control LED based on touch sensor value
        if (touch_value == 1) {
            gpioWrite(LED_PIN, 1); // Turn LED on
        } else {
            gpioWrite(LED_PIN, 0); // Turn LED off
        }

        // Log touch event
        if (touch_value == 1) {
            syslog(LOG_INFO, "Touch detected");
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Cleanup
    syslog(LOG_INFO, "Program shutting down");
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate(); // Terminate pigpio

    closelog(); // Close syslog

    return 0;
}

