#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initialize LED to LOW

    // Set touch sensor pin as input
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);

    return 0;
}

// Function to toggle the LED state
void toggle_led() {
    int current_level = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_level);
}

// Function to implement software debounce
void debounce() {
    gpioDelay(DEBOUNCE_TIME * 1000); // Convert milliseconds to microseconds
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Touch sensor and LED control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read touch sensor state
        int touch_detected = gpioRead(TOUCH_SENSOR_PIN);

        // If touch is detected, toggle the LED and debounce
        if (touch_detected == 1) {
            toggle_led();
            debounce();
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup GPIO resources before exiting
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

