#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/rain_events.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to log the event with a timestamp
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", buf, message);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    int current_state = 1; // Initialize to no rain (HIGH)
    int previous_state = 1;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = read_sensor();

        if (current_state != previous_state) {
            if (current_state == 0) {
                log_event("Rain Detected");
            } else {
                log_event("No Rain");
            }
            previous_state = current_state;
        }

        gpioDelay(500); // Poll every 500ms
    }

    // Cleanup
    printf("Cleaning up and exiting.\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

