#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the Hall Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int gpio;
    int last_state;
    unsigned long last_change;
} sensor_t;

// Function prototypes
int initialize_gpio();
int open_log_file();
void close_log_file();
void signal_handler(int signal);
int read_sensor(int gpio);
int debounce(int gpio, int current_state, unsigned long last_change);
void log_data(int sensor1_state, int sensor2_state);
void calculate_rpm(int sensor1_state, int sensor2_state);
void cleanup();

// Sensor instances
sensor_t sensor1 = {SENSOR1_GPIO, 0, 0};
sensor_t sensor2 = {SENSOR2_GPIO, 0, 0};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    // Open the log file
    if (open_log_file() != 0) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Debounce the sensor readings
        int debounced_sensor1_state = debounce(SENSOR1_GPIO, sensor1_state, sensor1.last_change);
        int debounced_sensor2_state = debounce(SENSOR2_GPIO, sensor2_state, sensor2.last_change);

        // Log the data
        log_data(debounced_sensor1_state, debounced_sensor2_state);

        // Calculate and print RPM
        calculate_rpm(debounced_sensor1_state, debounced_sensor2_state);

        // Update sensor states and last change times
        if (debounced_sensor1_state != sensor1.last_state) {
            sensor1.last_state = debounced_sensor1_state;
            sensor1.last_change = gpioTick();
        }
        if (debounced_sensor2_state != sensor2.last_state) {
            sensor2.last_state = debounced_sensor2_state;
            sensor2.last_change = gpioTick();
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1); // 1 ms delay
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

// Initialize pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    return 0;
}

// Open the log file for appending
int open_log_file() {
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Close the log file
void close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Debounce the sensor reading
int debounce(int gpio, int current_state, unsigned long last_change) {
    unsigned long now = gpioTick();
    if (now - last_change > DEBOUNCE_TIME * 1000) { // Convert ms to us
        return current_state;
    } else {
        return (gpio == SENSOR1_GPIO) ? sensor1.last_state : sensor2.last_state; // Return previous state
    }
}

// Log the data to the CSV file
void log_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Calculate and print the RPM
void calculate_rpm(int sensor1_state, int sensor2_state) {
    static unsigned long last_tick = 0;
    unsigned long current_tick = gpioTick();
    unsigned long diff = current_tick - last_tick;

    // Assuming one pulse per revolution (PPR = 1)
    // and that the sensors are 90 degrees apart.
    // Each state change represents 1/4 of a revolution.
    // So, two state changes represent one revolution.

    if (last_tick != 0 && (sensor1_state != sensor2_state)) {
        // Calculate RPM based on time difference
        double time_diff_seconds = (double)diff / 1000000.0; // Convert microseconds to seconds
        double rpm = 60.0 / (time_diff_seconds * 4.0); // Revolutions per minute

        printf("RPM: %.2f\n", rpm);
    }

    last_tick = current_tick;
}

// Cleanup resources before exiting
void cleanup() {
    close_log_file();
    gpioTerminate();
}

