#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define HEART_RATE_REG 0x24 // Example register address for Heart Rate
#define SPO2_REG 0x26       // Example register address for SpO2
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, int *heart_rate, int *spo2);
int log_data(FILE *log_file, int heart_rate, int spo2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to read heart rate and SpO2 data from the Si1182 sensor
int read_sensor_data(int i2c_handle, int *heart_rate, int *spo2) {
    char buf[2];
    int result;

    // Read Heart Rate
    result = i2cReadI2CBlockData(i2c_handle, HEART_RATE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading Heart Rate: %d\n", result);
        return -1;
    }
    *heart_rate = (buf[0] << 8) | buf[1];

    // Read SpO2
    result = i2cReadI2CBlockData(i2c_handle, SPO2_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading SpO2: %d\n", result);
        return -1;
    }
    *spo2 = (buf[0] << 8) | buf[1];

    return 0;
}

// Function to log data to a file
int log_data(FILE *log_file, int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
