// Define tilt threshold (in milliseconds)
#define TILT_THRESHOLD 2000

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int pin);
int log_event(const char *event_type);
int activate_alarm();
int deactivate_alarm();
void signal_handler(int signal);
int initialize_gpio();
int cleanup_gpio();

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to log events with ISO 8601 timestamp
int log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, event_type);
        fflush(log_file); // Ensure immediate write to file
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

// Function to activate the alarm
int activate_alarm() {
    gpioWrite(ALARM_PIN, 1); // Set alarm pin HIGH
    return 0;
}

// Function to deactivate the alarm
int deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0); // Set alarm pin LOW
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

