        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    int sensor1_state = 0;
    int sensor2_state = 0;
    int alarm_active = 0;
    time_t tilt_start_time1 = 0;
    time_t tilt_start_time2 = 0;

    printf("Monitoring bridge integrity...\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value == 1 && sensor1_state == 0) {
            log_event("Tilt Start - Sensor 1");
            sensor1_state = 1;
            tilt_start_time1 = time(NULL);
        } else if (sensor1_value == 0 && sensor1_state == 1) {
            log_event("Tilt End - Sensor 1");
            sensor1_state = 0;
            alarm_active = 0; // Reset alarm state when tilt ends
            deactivate_alarm(); // Deactivate alarm when tilt ends
        }

        if (sensor2_value == 1 && sensor2_state == 0) {
            log_event("Tilt Start - Sensor 2");
            sensor2_state = 1;
            tilt_start_time2 = time(NULL);
