            log_event("Tilt End - Sensor 2");
            sensor2_state = 0;
            alarm_active = 0; // Reset alarm state when tilt ends
            deactivate_alarm(); // Deactivate alarm when tilt ends
        }

        if (sensor1_state == 1 && (time(NULL) - tilt_start_time1) * 1000 >= TILT_THRESHOLD) {
            log_event("Threshold Exceeded - Sensor 1");
            alarm_active = 1;
        }

        if (sensor2_state == 1 && (time(NULL) - tilt_start_time2) * 1000 >= TILT_THRESHOLD) {
            log_event("Threshold Exceeded - Sensor 2");
            alarm_active = 1;
        }

        if (alarm_active) {
            activate_alarm();
        } else {
            deactivate_alarm();
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit
    printf("Cleaning up...\n");
    fclose(log_file);
    cleanup_gpio();

    return 0;
}

