#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define D7S_A0011_ADDR 0x4C
#define CTRL1_REG 0x20
#define CTRL1_POWER_DOWN 0x00
#define CTRL1_NORMAL_MODE 0x01
#define X_AXIS_REG 0x28
#define Y_AXIS_REG 0x2A
#define Z_AXIS_REG 0x2C
#define THRESHOLD 500
#define ALERT_LED_GPIO 17
#define LOG_FILE "seismic_events.log"
#define POLL_INTERVAL_MS 100
#define ALERT_DURATION_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
sensor_data_t read_sensor_data();
double calculate_magnitude(sensor_data_t data);
int log_event(double magnitude);
void trigger_alert();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, D7S_A0011_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the D7S-A0011 sensor
int init_sensor() {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, CTRL1_REG, CTRL1_NORMAL_MODE) >= 0) {
            return 0; // Success
        }
        fprintf(stderr, "Error writing to CTRL1_REG, retrying...\n");
        gpioDelay(1000); // Wait 1ms before retrying
        retries--;
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int retries = 3;
    char buffer[6];

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, X_AXIS_REG, buffer, 6) == 6) {
            data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
            data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
            data.z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return data;
        }
        fprintf(stderr, "Error reading sensor data, retrying...\n");
        gpioDelay(1000); // Wait 1ms before retrying
        retries--;
    }

    // Return default values if reading fails
    data.x = 0;
    data.y = 0;
    data.z = 0;
    return data;
}

// Calculate Euclidean magnitude
double calculate_magnitude(sensor_data_t data) {
    return sqrt(pow(data.x, 2) + pow(data.y, 2) + pow(data.z, 2));
}

// Log event to file
int log_event(double magnitude) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", buf, magnitude);
    fclose(log_file);
    return 0;
}

// Trigger alert (LED)
void trigger_alert() {
    gpioWrite(ALERT_LED_GPIO, 1); // Turn LED on
    gpioDelay(ALERT_DURATION_MS);  // Wait for 1 second
    gpioWrite(ALERT_LED_GPIO, 0); // Turn LED off
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(ALERT_LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set GPIO17 as output for the alert LED
    gpioSetMode(ALERT_LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        double magnitude = calculate_magnitude(data);

        if (magnitude > THRESHOLD) {
            printf("Earthquake-like event detected! Magnitude: %.2f\n", magnitude);
            log_event(magnitude);
            trigger_alert();
        }

        gpioDelay(POLL_INTERVAL_MS); // Poll every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

