#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <gpiod.h>

// Define GPIO pins for the flame sensors
const int gpio_pins[] = {2, 3, 4, 17, 27};
const int num_sensors = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Define the log file path
const char *log_file = "/var/log/flame_events.log";

// Define debounce delay in milliseconds
const int debounce_delay_ms = 50;

// Global variables
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[5] = {NULL, NULL, NULL, NULL, NULL};
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int pin);
int debounce(int pin);
int log_event(int pin);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_USER | LOG_INFO, "Received signal %d, terminating...", sig);
    terminate = 1;
}

// Function to read the sensor value
int read_sensor(int pin) {
    int value = -1; // Initialize to an invalid value
    struct gpiod_line *line = NULL;
    int i;

    for (i = 0; i < num_sensors; i++) {
        if (gpio_pins[i] == pin) {
            line = lines[i];
            break;
        }
    }

    if (line == NULL) {
        syslog(LOG_USER | LOG_ERR, "Error: Invalid GPIO pin %d", pin);
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_USER | LOG_ERR, "Error reading GPIO pin %d: %s", pin, strerror(errno));
        return -1;
    }

    return value;
}

// Function to perform debouncing
int debounce(int pin) {
    int initial_value = read_sensor(pin);
    if (initial_value < 0) {
        return -1; // Error reading sensor
    }

    if (initial_value == 1) {
        // Flame detected, perform debounce
        usleep(debounce_delay_ms * 1000); // Convert ms to microseconds
        int debounced_value = read_sensor(pin);
        if (debounced_value < 0) {
            return -1; // Error reading sensor
        }

        if (debounced_value == 0) {
            return 1; // Flame confirmed
        } else {
            return 0; // Flame not confirmed
        }
    } else {
        return 0; // No flame detected
    }
}

// Function to log the event to a file
int log_event(int pin) {
    FILE *fp = NULL;
    time_t rawtime;
    struct tm *info;
    char timestamp[30];
    char log_message[256];

    // Get current time
    time(&rawtime);
    info = gmtime(&rawtime);

    // Format timestamp in ISO 8601 UTC format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", info);

    // Create log message
    snprintf(log_message, sizeof(log_message), "%s - Sensor ID: %d (GPIO %d) - Flame Detected", timestamp, pin, pin);

    // Open log file for appending
    fp = fopen(log_file, "a");
    if (fp == NULL) {
        syslog(LOG_USER | LOG_ERR, "Error opening log file %s: %s", log_file, strerror(errno));
        return -1;
    }

    // Acquire exclusive lock on the file
    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_USER | LOG_ERR, "Error acquiring lock on log file %s: %s", log_file, strerror(errno));
        fclose(fp);
        return -1;
    }

    // Write log message to file
    fprintf(fp, "%s\n", log_message);
    fflush(fp); // Ensure data is written to disk

    // Release lock on the file
    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_USER | LOG_ERR, "Error releasing lock on log file %s: %s", log_file, strerror(errno));
    }

    // Close log file
    fclose(fp);

    return 0;
}

// Function to setup GPIO lines
int setup_gpio(void) {
    int i;
    char chipname[20];

    // Open GPIO chip
    snprintf(chipname, sizeof(chipname), "gpiochip0");
    chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        syslog(LOG_USER | LOG_ERR, "Error opening GPIO chip %s: %s", chipname, strerror(errno));
        return -1;
    }

    // Get lines for each sensor
    for (i = 0; i < num_sensors; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            syslog(LOG_USER | LOG_ERR, "Error getting GPIO line %d: %s", gpio_pins[i], strerror(errno));
            return -1;
        }

        // Request line for input
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "flame_monitor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            syslog(LOG_USER | LOG_ERR, "Error requesting GPIO line %d: %s", gpio_pins[i], strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    int i;

    // Release lines
    for (i = 0; i < num_sensors; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int i;

    // Open syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Log program start
    syslog(LOG_USER | LOG_INFO, "Flame monitor started");

    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() < 0) {
        syslog(LOG_USER | LOG_ERR, "GPIO setup failed, exiting");
        closelog();
        return 1;
    }

    // Main loop
    while (!terminate) {
        for (i = 0; i < num_sensors; i++) {
            int pin = gpio_pins[i];
            int result = debounce(pin);

            if (result == 1) {
                if (log_event(pin) == 0) {
                    syslog(LOG_USER | LOG_INFO, "Flame detected on GPIO %d", pin);
                } else {
                    syslog(LOG_USER | LOG_ERR, "Error logging event for GPIO %d", pin);
                }
            } else if (result < 0) {
                syslog(LOG_USER | LOG_ERR, "Error during debounce for GPIO %d", pin);
            }
        }

        sleep(1); // Poll every 1 second
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Log program termination
    syslog(LOG_USER | LOG_INFO, "Flame monitor terminated");

    // Close syslog
    closelog();

    return 0;
}

