const int num_channels = sizeof(touch_pins) / sizeof(touch_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the touch sensor state
int read_touch_sensor(int pin)
{
    return gpioRead(pin);
}

// Function to log touch events with ISO 8601 timestamp
void log_touch_event(int channel, int pin, int state)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - Channel %d (BCM GPIO %d): %s\n", timestamp, channel, pin, state ? "Touched" : "Released");
}

