{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as inputs
    for (int i = 0; i < num_channels; i++)
    {
        gpioSetMode(touch_pins[i], PI_INPUT);
    }

    // Install signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Array to store the previous state of each channel
    int previous_states[num_channels];
    for (int i = 0; i < num_channels; i++)
    {
        previous_states[i] = read_touch_sensor(touch_pins[i]);
    }

    // Main loop
    while (!terminate)
    {
        for (int i = 0; i < num_channels; i++)
        {
            int current_state = read_touch_sensor(touch_pins[i]);

            if (current_state != previous_states[i])
            {
                log_touch_event(i, touch_pins[i], current_state);
                previous_states[i] = current_state;
            }
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

