#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for touch sensors
#define TOUCH_PIN_1 2
#define TOUCH_PIN_2 3
#define TOUCH_PIN_3 4
#define TOUCH_PIN_4 5
#define TOUCH_PIN_5 6
#define TOUCH_PIN_6 7
#define TOUCH_PIN_7 8
#define TOUCH_PIN_8 9

// Define GPIO pin for alert LED
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static int led_state = 0; // 0 = off, 1 = on

// Function prototypes
int read_touch_sensor(int pin);
int debounce(int pin, int *last_state, unsigned long *last_time);
void log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
    control_led(0); // Turn off LED
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

// Function to read the state of a touch sensor pin
int read_touch_sensor(int pin) {
    return gpioRead(pin);
}

// Function to debounce a touch sensor input
int debounce(int pin, int *last_state, unsigned long *last_time) {
    int current_state = read_touch_sensor(pin);
    unsigned long now = gpioTick();

    if (current_state != *last_state) {
        if (now - *last_time > DEBOUNCE_TIME * 1000) { // Convert ms to us
            *last_state = current_state;
            *last_time = now;
            return 1; // State changed and debounced
        }
    }
    return 0; // No change or not debounced
}

// Function to log a touch event to a file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_message[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(log_message, sizeof(log_message), "%s – Channel %d Touched\n", timestamp, channel);

    FILE *fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening touch_log.txt for writing!\n");
        return;
    }

    if (fputs(log_message, fp) == EOF) {
        fprintf(stderr, "Error writing to touch_log.txt!\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing touch_log.txt!\n");
    }
}

// Function to control the alert LED
void control_led(int state) {
    if (state != led_state) {
        gpioWrite(LED_PIN, state);
        led_state = state;
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins for touch sensors as inputs with pull-down resistors
    gpioSetMode(TOUCH_PIN_1, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_1, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_2, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_2, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_3, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_3, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_4, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_4, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_5, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_5, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_6, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_6, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_7, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_7, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_8, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_8, PI_PUD_DOWN);

    // Set GPIO pin for alert LED as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize debounce variables
    int last_state_1 = 0, last_state_2 = 0, last_state_3 = 0, last_state_4 = 0;
    int last_state_5 = 0, last_state_6 = 0, last_state_7 = 0, last_state_8 = 0;
    unsigned long last_time_1 = 0, last_time_2 = 0, last_time_3 = 0, last_time_4 = 0;
    unsigned long last_time_5 = 0, last_time_6 = 0, last_time_7 = 0, last_time_8 = 0;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int any_touched = 0;

        if (debounce(TOUCH_PIN_1, &last_state_1, &last_time_1)) {
            if (read_touch_sensor(TOUCH_PIN_1)) {
                log_touch_event(1);
                any_touched = 1;
            }
        }
        if (debounce(TOUCH_PIN_2, &last_state_2, &last_time_2)) {
            if (read_touch_sensor(TOUCH_PIN_2)) {
                log_touch_event(2);
                any_touched = 1;
            }
        }
        if (debounce(TOUCH_PIN_3, &last_state_3, &last_time_3)) {
            if (read_touch_sensor(TOUCH_PIN_3)) {
                log_touch_event(3);
                any_touched = 1;
            }
        }
        if (debounce(TOUCH_PIN_4, &last_state_4, &last_time_4)) {
            if (read_touch_sensor(TOUCH_PIN_4)) {
                log_touch_event(4);
                any_touched = 1;
            }
        }
        if (debounce(TOUCH_PIN_5, &last_state_5, &last_time_5)) {
            if (read_touch_sensor(TOUCH_PIN_5)) {
                log_touch_event(5);
                any_touched = 1;
            }
        }
        if (debounce(TOUCH_PIN_6, &last_state_6, &last_time_6)) {
            if (read_touch_sensor(TOUCH_PIN_6)) {
                log_touch_event(6);
                any_touched = 1;
            }
        }
        if (debounce(TOUCH_PIN_7, &last_state_7, &last_time_7)) {
            if (read_touch_sensor(TOUCH_PIN_7)) {
                log_touch_event(7);
                any_touched = 1;
            }
        }
        if (debounce(TOUCH_PIN_8, &last_state_8, &last_time_8)) {
            if (read_touch_sensor(TOUCH_PIN_8)) {
                log_touch_event(8);
                any_touched = 1;
            }
        }

        // Control the LED based on touch events
        if (any_touched) {
            control_led(1);
        } else {
            // Check if all channels are released
            if (!read_touch_sensor(TOUCH_PIN_1) &&
                !read_touch_sensor(TOUCH_PIN_2) &&
                !read_touch_sensor(TOUCH_PIN_3) &&
                !read_touch_sensor(TOUCH_PIN_4) &&
                !read_touch_sensor(TOUCH_PIN_5) &&
                !read_touch_sensor(TOUCH_PIN_6) &&
                !read_touch_sensor(TOUCH_PIN_7) &&
                !read_touch_sensor(TOUCH_PIN_8)) {
                control_led(0);
            }
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    gpioTerminate();
    return 0;
}

