#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_CONVERSION_FACTOR 0.01
#define CONFIG_VALUE 0xCB01 // Continuous mode, 100ms conversion time

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
float read_lux();
int log_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    float lux;
    time_t timestamp;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to configure the OPT3001 sensor
int configure_sensor() {
    uint16_t config_big_endian = (CONFIG_VALUE >> 8) | (CONFIG_VALUE << 8); // Byte swap
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_big_endian >> 8) & 0xFF; // MSB
    buf[2] = config_big_endian & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait 100ms
    return 0;
}

// Function to read the lux value from the OPT3001
float read_lux() {
    char buf[1];
    buf[0] = RESULT_REG;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C (result reg): %s\n", strerror(errno));
        return -1.0;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1.0;
    }

    uint16_t raw_result = (read_buf[0] << 8) | read_buf[1]; // Combine bytes
    uint16_t exponent = (raw_result >> 12) & 0x0F;
    uint16_t result_value = raw_result & 0x0FFF;

    float lux = result_value * LUX_CONVERSION_FACTOR * (1 << exponent);
    return lux;
}

// Function to log the data to a file and stdout
int log_data(float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk

    printf("%s, %.2f\n", timestamp, lux_value);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float lux_value = read_lux();
        if (lux_value >= 0) {
            log_data(lux_value);
        } else {
            fprintf(stderr, "Error reading lux value, skipping iteration.\n");
        }
        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

