#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure static allocation

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log touch events to a file
int log_touch_event(const char *event_type) {
    char *timestamp = get_timestamp();
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", timestamp);
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", timestamp);
        return -1;
    }

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int last_state = 0; // 0 = released, 1 = pressed
    int current_state;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Re-read the pin after the delay
            if (gpioRead(GPIO_PIN) == current_state) {
                if (current_state == 1) {
                    if (log_touch_event("Touch Detected") != 0) {
                        running = 0; // Stop if logging fails
                    }
                } else {
                    if (log_touch_event("Touch Released") != 0) {
                        running = 0; // Stop if logging fails
                    }
                }
                last_state = current_state;
            }
        }

        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup
    fprintf(stderr, "Cleaning up and exiting.\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

