// Define GPIO pins for the sensors
#define LEFT_SENSOR 17
#define MIDDLE_SENSOR 27
#define RIGHT_SENSOR 22

// Global variables
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int read_sensor(int gpio_pin);
char* get_iso8601_timestamp();
int write_to_csv(FILE *fp, char *timestamp, int left, int middle, int right);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        running = false;
    }
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to write the sensor data to a CSV file
int write_to_csv(FILE *fp, char *timestamp, int left, int middle, int right) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        perror("Failed to write to CSV file");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    // Open the CSV file for writing
    log_file = fopen("path_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open path_log.csv");
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,left,middle,right\n");
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR);
        int middle_value = read_sensor(MIDDLE_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        // Get the current timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping iteration\n");
            gpioDelay(50000); // Wait 50ms
            continue;
        }

        // Write the data to the CSV file
        if (write_to_csv(log_file, timestamp, left_value, middle_value, right_value) != 0) {
            fprintf(stderr, "Failed to write data to CSV, skipping iteration\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for 50ms
        gpioDelay(50000);
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    return 0;
}

