#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 4
#define LOG_FILE "flame_events.txt"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log flame detection event
void log_flame_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Flame detected at: %s\n", timestamp);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "Flame detected at: %s\n", timestamp);
    fclose(fp);
}

// Callback function for flame detection
void flame_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge detected (flame detected)
        log_flame_event();
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Set pull-up resistor (optional, depending on sensor module)
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Set alert function for falling edge detection
    if (gpioSetAlertFunc(FLAME_SENSOR_GPIO, flame_detected_callback) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Check every 100ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

