#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <stdbool.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "alert_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_sensor_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_flame_sensor(void);
void activate_buzzer(void);
void log_event(const char *message);
void cleanup(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get flame sensor line
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request flame sensor line for input
    ret = gpiod_line_request(flame_sensor_line, "flame_alert", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request buzzer line for output
    ret = gpiod_line_request(buzzer_line, "flame_alert", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting buzzer line: %s\n", strerror(errno));
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read flame sensor value
int read_flame_sensor(void) {
    int value = gpiod_line_get_value(flame_sensor_line);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Activate buzzer for 2 seconds
void activate_buzzer(void) {
    int ret;
    for (int i = 0; i < 20; i++) {
        ret = gpiod_line_set_value(buzzer_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
            return;
        }
        usleep(100000); // 100ms

        ret = gpiod_line_set_value(buzzer_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
            return;
        }
        usleep(100000); // 100ms
    }
}

// Log event to file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0); // Turn off buzzer
        gpiod_line_release(buzzer_line);
    }
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int ret;
    int prev_flame_value = 1; // Initialize to HIGH (no flame)
    int current_flame_value;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_event("System started");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        current_flame_value = read_flame_sensor();
        if (current_flame_value < 0) {
            log_event("Error reading flame sensor, exiting");
            break;
        }

        // Check for HIGH-to-LOW transition (flame detected)
        if (prev_flame_value == 1 && current_flame_value == 0) {
            log_event("FLAME DETECTED");
            activate_buzzer();
        }

        prev_flame_value = current_flame_value;

        usleep(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    log_event("System stopped");
    return EXIT_SUCCESS;
}

