// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_led();
int log_touch_event();
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int led_state;
    unsigned long last_touch_time;
} ProgramState;

ProgramState state = {0, 0}; // Initialize LED state to off and last touch time to 0

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read touch sensor
        if (read_touch_sensor() == 1) {
            // Debounce
            unsigned long current_time = gpioTick();
            if (current_time - state.last_touch_time > DEBOUNCE_TIME * 1000) {
                // Toggle LED
                toggle_led();

                // Log touch event
                if (log_touch_event() != 0) {
                    fprintf(stderr, "Warning: Failed to log touch event.\n");
                }

                // Update last touch time
                state.last_touch_time = current_time;
            }
        }

        // Delay for 10ms
        gpioDelay(10000); // 10ms = 10000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, state.led_state); // Ensure LED is off initially

    return 0;
}

// Read touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Toggle LED state
void toggle_led() {
    state.led_state = !state.led_state;
    gpioWrite(LED_PIN, state.led_state);
}

// Log touch event with timestamp
int log_touch_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup resources
void cleanup() {
    // Turn off LED
    gpioWrite(LED_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

