    previous_states.sensor2_state = read_sensor(SENSOR2_PIN);
    previous_states.sensor3_state = read_sensor(SENSOR3_PIN);

    if (previous_states.sensor1_state == -1 || previous_states.sensor2_state == -1 || previous_states.sensor3_state == -1) {
        fprintf(stderr, "Error reading initial sensor states. Exiting.\n");
        cleanup();
        return 1;
