        current_states.sensor1_state = read_sensor(SENSOR1_PIN);
        current_states.sensor2_state = read_sensor(SENSOR2_PIN);
        current_states.sensor3_state = read_sensor(SENSOR3_PIN);

        // Log events if states have changed
        if (current_states.sensor1_state != previous_states.sensor1_state && current_states.sensor1_state != -1) {
            log_event(1, current_states.sensor1_state);
            previous_states.sensor1_state = current_states.sensor1_state;
        }
        if (current_states.sensor2_state != previous_states.sensor2_state && current_states.sensor2_state != -1) {
            log_event(2, current_states.sensor2_state);
