#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define HEART_RATE_REG 0x24
#define MOVING_AVG_SIZE 5
#define BPM_MIN 30
#define BPM_MAX 220
#define CSV_FILE "heart_rate.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    uint8_t part_id;
    uint8_t hw_rev;
} sensor_config_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t reg);
int write_sensor_data(uint8_t reg, uint8_t value);
int configure_sensor();
int read_heart_rate();
double moving_average(int new_value);
int validate_bpm(double bpm);
int log_data(double bpm);
void signal_handler(int signal);
void cleanup();

// Moving average filter buffer
int heart_rate_buffer[MOVING_AVG_SIZE];
int buffer_index = 0;

// Initialize the moving average buffer
void init_moving_average_buffer() {
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        heart_rate_buffer[i] = 0; // Initialize with a default value
    }
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(uint8_t reg) {
    int retries = 3;
    int data = -1;
    while (retries > 0) {
        data = i2cReadByteData(i2c_handle, reg);
        if (data >= 0) {
            return data;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X), retrying...\n", reg);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to read from register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to write data to the sensor
int write_sensor_data(uint8_t reg, uint8_t value) {
    int retries = 3;
    int result = -1;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X), retrying...\n", reg, value);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to configure the sensor
int configure_sensor() {
    // Example configuration (replace with actual Si1182 configuration)
    if (write_sensor_data(0x18, 0x0F) != 0) return -1; // Example register and value
    if (write_sensor_data(0x19, 0x01) != 0) return -1; // Example register and value
    if (write_sensor_data(0x1A, 0x00) != 0) return -1; // Example register and value
    return 0;
}

// Function to read heart rate data
int read_heart_rate() {
    int heart_rate = read_sensor_data(HEART_RATE_REG);
    if (heart_rate < 0) {
        fprintf(stderr, "Error reading heart rate data.\n");
        return -1;
    }
    return heart_rate;
}

// Function to apply moving average filter
double moving_average(int new_value) {
    heart_rate_buffer[buffer_index] = new_value;
    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;

    double sum = 0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += heart_rate_buffer[i];
    }
    return sum / MOVING_AVG_SIZE;
}

// Function to validate BPM
int validate_bpm(double bpm) {
    if (bpm >= BPM_MIN && bpm <= BPM_MAX) {
        return 0; // Valid
    } else {
        fprintf(stderr, "Invalid BPM value: %.2f\n", bpm);
        return -1; // Invalid
    }
}

// Function to log data to CSV file
int log_data(double bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify sensor presence and configuration
    int part_id = read_sensor_data(PART_ID_REG);
    int hw_rev = read_sensor_data(HW_REV_REG);

    if (part_id != 0x82 || hw_rev != 0x01) {
        fprintf(stderr, "Sensor not found or incorrect configuration (PART_ID: 0x%02X, HW_REV: 0x%02X)\n", part_id, hw_rev);
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        return 1;
    }

    // Initialize moving average buffer
    init_moving_average_buffer();

    // Main loop
    while (!terminate) {
        // Read heart rate data
        int heart_rate = read_heart_rate();
        if (heart_rate >= 0) {
            // Apply moving average filter
            double filtered_heart_rate = moving_average(heart_rate);

            // Validate BPM
            if (validate_bpm(filtered_heart_rate) == 0) {
                // Log data
                log_data(filtered_heart_rate);
            }
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

