#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define SENSOR_PINS {5, 6, 7, 8, 9, 10, 11, 12}
#define COUNTER_PINS {17, 18, 19, 20, 21, 22, 23, 24}

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_lines[8];
static struct gpiod_line *counter_lines[8];
static int counter_value = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor_channels(int *channel_states);
int increment_counter(void);
int update_counter_output(void);
int log_event(int channel);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int sensor_pins[] = SENSOR_PINS;
    int counter_pins[] = COUNTER_PINS;
    int i, ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get sensor lines
    for (i = 0; i < 8; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            perror("Error getting sensor line");
            goto cleanup;
        }

        ret = gpiod_line_request_input(sensor_lines[i], "touch_counter");
        if (ret < 0) {
            perror("Error requesting sensor line as input");
            goto cleanup;
        }
    }

    // Get counter lines
    for (i = 0; i < 8; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, counter_pins[i]);
        if (!counter_lines[i]) {
            perror("Error getting counter line");
            goto cleanup;
        }

        ret = gpiod_line_request_output(counter_lines[i], "touch_counter", 0);
        if (ret < 0) {
            perror("Error requesting counter line as output");
            goto cleanup;
        }
    }

    return 0;

cleanup:
    cleanup_gpio();
    return -1;
}

// Read sensor channels
int read_sensor_channels(int *channel_states) {
    int i, value, ret;

    for (i = 0; i < 8; i++) {
        ret = gpiod_line_get_value(sensor_lines[i]);
        if (ret < 0) {
            fprintf(stderr, "Error reading sensor line %d: %s\n", i + 1, strerror(errno));
            channel_states[i] = -1; // Indicate error
        } else {
            channel_states[i] = ret;
        }
    }
    return 0;
}

// Increment counter
int increment_counter(void) {
    counter_value = (counter_value + 1) % 256;
    return 0;
}

// Update counter output
int update_counter_output(void) {
    int i, ret;

    for (i = 0; i < 8; i++) {
        ret = gpiod_line_set_value(counter_lines[i], (counter_value >> i) & 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting counter line %d: %s\n", i + 17, strerror(errno));
        }
    }
    return 0;
}

// Log event
int log_event(int channel) {
    time_t rawtime;
    struct tm *info;
    char buffer[80];

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, 80, "%Y-%m-%dT%H:%M:%SZ", info);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", buffer, channel, counter_value);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Warning: Log file not opened, writing to stdout only.\n");
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter_value);
    return 0;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    int i;

    // Release sensor lines
    for (i = 0; i < 8; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }

    // Release counter lines
    for (i = 0; i < 8; i++) {
        if (counter_lines[i]) {
            gpiod_line_set_value(counter_lines[i], 0); // Set to 0 before releasing
            gpiod_line_release(counter_lines[i]);
        }
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int channel_states[8];
    int i, prev_channel_states[8] = {0};
    struct timespec sleep_time = {0, 10000000}; // 10ms

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    }

    // Initial stabilization delay
    usleep(200000); // 200ms

    // Main loop
    while (!terminate) {
        // Read sensor channels
        if (read_sensor_channels(channel_states) < 0) {
            fprintf(stderr, "Error reading sensor channels. Continuing.\n");
            usleep(100000); // Small delay before retrying
            continue;
        }

        // Check for rising edges
        for (i = 0; i < 8; i++) {
            if (channel_states[i] == 1 && prev_channel_states[i] == 0) {
                // Rising edge detected
                increment_counter();
                update_counter_output();
                log_event(i + 1);
            }
            prev_channel_states[i] = channel_states[i];
        }

        // Sleep for 10ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

