#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

// Global variables
FILE *log_file = NULL;
int pigpio_initialized = 0;

// Function prototypes
int read_sensor(int gpio_pin);
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int sensor3_value, int sensor4_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    // Close the log file if it's open
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }

    // Terminate pigpio if it's initialized
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }

    exit(0);
}

// Function to read the sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the data to a CSV file
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int sensor3_value, int sensor4_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value, sensor4_value) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1; // Indicate an error
    }
    fflush(fp); // Flush the buffer to ensure data is written immediately
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetMode(SENSOR4_PIN, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen("tracking_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);
        int sensor4_value = read_sensor(SENSOR4_PIN);

        // Log the data if sensor readings were successful
        if (sensor1_value != -1 && sensor2_value != -1 && sensor3_value != -1 && sensor4_value != -1) {
            if (log_data(log_file, sensor1_value, sensor2_value, sensor3_value, sensor4_value) != 0) {
                fprintf(stderr, "Error logging data, exiting\n");
                break; // Exit the loop if logging fails
            }
        } else {
            fprintf(stderr, "Error reading sensors, skipping log\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

