#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling period (in microseconds)
#define SAMPLING_PERIOD 125

// Define LED on time (in milliseconds)
#define LED_ON_TIME 100

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0; // Indicate success
}

// Function to sample the microphone and detect peaks
void sample_microphone() {
    struct timespec ts;
    int last_state = 0; // Store the last state of the microphone pin

    while (!terminate) {
        int current_state = gpioRead(MIC_PIN);

        if (current_state == 1 && last_state == 0) {
            // Rising edge detected (sound peak)
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("%ld.%03ld\n", ts.tv_sec, ts.tv_nsec / 1000000);

            // Turn on the LED
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_TIME * 1000); // Delay for 100ms
            gpioWrite(LED_PIN, 0); // Turn off the LED
        }

        last_state = current_state;
        gpioDelay(SAMPLING_PERIOD); // Delay for the sampling period
    }
}

// Function to clean up GPIO resources before exiting
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio
    fprintf(stderr, "pigpio terminated\n");
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Sample the microphone until termination is signaled
    sample_microphone();

    // Clean up GPIO resources
    cleanup_gpio();

    return 0;
}

