#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor state
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT) failed");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM) failed");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LEFT_SENSOR_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for LEFT_SENSOR_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for CENTER_SENSOR_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for CENTER_SENSOR_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for RIGHT_SENSOR_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for RIGHT_SENSOR_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Main loop to read and log sensor data
    while (program_running) {
        int left_state = read_sensor(LEFT_SENSOR_PIN);
        int center_state = read_sensor(CENTER_SENSOR_PIN);
        int right_state = read_sensor(RIGHT_SENSOR_PIN);

        if (left_state == -1 || center_state == -1 || right_state == -1) {
            fprintf(stderr, "Error reading sensor data, exiting...\n");
            break; // Exit the loop if there's an error
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        gpioDelay(100); // Wait for 100 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

