#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read ALS data from Si1175
int read_als_data(int i2c_handle) {
    int lsb, msb;
    int als_value;

    // Read LSB
    lsb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_DATA0);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB: %d\n", lsb);
        return -1;
    }

    // Read MSB
    msb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_VIS_DATA1);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB: %d\n", msb);
        return -1;
    }

    // Combine LSB and MSB into 16-bit value
    als_value = (msb << 8) | lsb;

    return als_value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int als_value = read_als_data(i2c_handle);
        if (als_value >= 0) {
            printf("ALS Value: %d\n", als_value);
        } else {
            fprintf(stderr, "Error reading ALS data\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

