#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for each channel
#define CH1_PIN 5
#define CH2_PIN 6
#define CH3_PIN 13
#define CH4_PIN 19
#define CH5_PIN 26
#define CH6_PIN 12
#define CH7_PIN 16
#define CH8_PIN 20

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register SIGINT handler.\n");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register SIGTERM handler.\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(CH1_PIN, PI_INPUT);
    gpioSetMode(CH2_PIN, PI_INPUT);
    gpioSetMode(CH3_PIN, PI_INPUT);
    gpioSetMode(CH4_PIN, PI_INPUT);
    gpioSetMode(CH5_PIN, PI_INPUT);
    gpioSetMode(CH6_PIN, PI_INPUT);
    gpioSetMode(CH7_PIN, PI_INPUT);
    gpioSetMode(CH8_PIN, PI_INPUT);

    // Main loop
    while (!terminate) {
        // Read sensor values
        int ch1_val = gpioRead(CH1_PIN);
        int ch2_val = gpioRead(CH2_PIN);
        int ch3_val = gpioRead(CH3_PIN);
        int ch4_val = gpioRead(CH4_PIN);
        int ch5_val = gpioRead(CH5_PIN);
        int ch6_val = gpioRead(CH6_PIN);
        int ch7_val = gpioRead(CH7_PIN);
        int ch8_val = gpioRead(CH8_PIN);

        // Get current time
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            fprintf(stderr, "Error: Could not get monotonic time.\n");
            terminate = 1; // Exit loop on error
            continue;       // Skip to next iteration to allow cleanup
        }

        // Print sensor data with timestamp
        printf("[%ld.%03lds] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               ts.tv_sec, ts.tv_nsec / 1000000, ch1_val, ch2_val, ch3_val, ch4_val, ch5_val, ch6_val, ch7_val, ch8_val);

        // Wait for 200ms
        gpioDelay(200000); // Delay in microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

