#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// PWM frequency
#define PWM_FREQUENCY 1000

// Interpolation steps
#define INTERPOLATION_STEPS 50

// Interpolation duration (seconds)
#define INTERPOLATION_DURATION 5

// Structure to represent an RGB color
typedef struct {
    uint8_t red;
    uint8_t green;
    uint8_t blue;
} rgb_color_t;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to set GPIO pin mode
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d mode", pin);
        return -1;
    }
    return 0;
}

// Function to set PWM frequency
int set_pwm_frequency(int pin, int frequency) {
    if (gpioSetPWMfrequency(pin, frequency) != frequency) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GPIO %d", pin);
        return -1;
    }
    return 0;
}

// Function to set PWM range
int set_pwm_range(int pin, int range) {
    if (gpioSetPWMrange(pin, range) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for GPIO %d", pin);
        return -1;
    }
    return 0;
}

// Function to set PWM duty cycle
int set_pwm_dutycycle(int pin, int dutycycle) {
    if (gpioPWM(pin, dutycycle) != 0) {
        syslog(LOG_ERR, "Failed to set PWM duty cycle for GPIO %d", pin);
        return -1;
    }
    return 0;
}

// Function to generate a random RGB color
rgb_color_t generate_random_color() {
    rgb_color_t color;
    color.red   = (uint8_t)rand();
    color.green = (uint8_t)rand();
    color.blue  = (uint8_t)rand();
    return color;
}

// Function to interpolate between two colors
void interpolate_colors(rgb_color_t start_color, rgb_color_t end_color, rgb_color_t *interpolated_colors, int num_steps) {
    float red_diff   = (float)(end_color.red   - start_color.red)   / num_steps;
    float green_diff = (float)(end_color.green - start_color.green) / num_steps;
    float blue_diff  = (float)(end_color.blue  - start_color.blue)  / num_steps;

    for (int i = 0; i < num_steps; i++) {
        interpolated_colors[i].red   = (uint8_t)(start_color.red   + (red_diff   * i));
        interpolated_colors[i].green = (uint8_t)(start_color.green + (green_diff * i));
        interpolated_colors[i].blue  = (uint8_t)(start_color.blue  + (blue_diff  * i));
    }
}

// Function to set the RGB LED color
int set_led_color(int red_pin, int green_pin, int blue_pin, uint8_t red_value, uint8_t green_value, uint8_t blue_value) {
    if (set_pwm_dutycycle(red_pin,   red_value)   != 0) return -1;
    if (set_pwm_dutycycle(green_pin, green_value) != 0) return -1;
    if (set_pwm_dutycycle(blue_pin,  blue_value)  != 0) return -1;
    return 0;
}

// Function to turn off the RGB LED
int turn_off_led(int red_pin, int green_pin, int blue_pin) {
    if (set_pwm_dutycycle(red_pin,   0) != 0) return -1;
    if (set_pwm_dutycycle(green_pin, 0) != 0) return -1;
    if (set_pwm_dutycycle(blue_pin,  0) != 0) return -1;
    return 0;
}

// Function to cleanup pigpio
int cleanup_pigpio() {
    if (gpioTerminate() != 0) {
        syslog(LOG_ERR, "pigpio termination failed");
        return -1;
    }
    return 0;
}

int main() {
    // Open syslog
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator with /dev/urandom
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd == -1) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        closelog();
        return 1;
    }
    unsigned int seed;
    if (read(fd, &seed, sizeof(seed)) != sizeof(seed)) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom");
        close(fd);
        closelog();
        return 1;
    }
    close(fd);
    srand(seed);

    // Install signal handlers
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        closelog();
        return 1;
    }

    // Set GPIO pin modes
    if (set_gpio_mode(RED_PIN,   PI_OUTPUT) != 0 ||
        set_gpio_mode(GREEN_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(BLUE_PIN,  PI_OUTPUT) != 0) {
        cleanup_pigpio();
        closelog();
        return 1;
    }

    // Set PWM frequency and range
    if (set_pwm_frequency(RED_PIN,   PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(GREEN_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(BLUE_PIN,  PWM_FREQUENCY) != 0 ||
        set_pwm_range(RED_PIN,   255) != 0 ||
        set_pwm_range(GREEN_PIN, 255) != 0 ||
        set_pwm_range(BLUE_PIN,  255) != 0) {
        cleanup_pigpio();
        closelog();
        return 1;
    }

    rgb_color_t current_color = generate_random_color();
    rgb_color_t next_color;
