#include <errno.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Enable Register Values
#define TCS34725_PON             (0x01)
#define TCS34725_AEN             (0x02)

// Integration Time
#define TCS34725_INTEGRATIONTIME_154MS (0xD5) // 154ms

// GPIO Pin for LED
#define LED_GPIO                (17)

// Red Value Threshold
#define RED_THRESHOLD           (200)

// Global Variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int tcs34725_init();
int tcs34725_read_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear);
void control_led(uint16_t red_value);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// TCS34725 Initialization
int tcs34725_init() {
    // Power on the sensor
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_PON) < 0) {
        fprintf(stderr, "Error writing PON: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(3); // Wait 3ms

    // Enable RGBC
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_PON | TCS34725_AEN) < 0) {
        fprintf(stderr, "Error writing AEN: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, TCS34725_INTEGRATIONTIME_154MS) < 0) {
        fprintf(stderr, "Error writing ATIME: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// TCS34725 Data Reading
int tcs34725_read_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    uint8_t buffer[8];

    if (i2cReadI2CBlockData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CDATA, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    *clear = (buffer[1] << 8) | buffer[0];
    *red   = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue  = (buffer[7] << 8) | buffer[6];

    return 0;
}

// LED Control
void control_led(uint16_t red_value) {
    if (red_value > RED_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init() < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, green, blue, clear;

    // Main loop
    while (!terminate) {
        if (tcs34725_read_data(&red, &green, &blue, &clear) == 0) {
            printf("Red: %u, Green: %u, Blue: %u, Clear: %u\n", red, green, blue, clear);
            control_led(red);
        } else {
            fprintf(stderr, "Error reading sensor data, re-initializing...\n");
            i2cClose(i2c_handle);
            gpioDelay(100); // Wait 100ms before re-initializing
            i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                terminate = 1; // Exit loop if re-initialization fails
            } else if (tcs34725_init() < 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(200); // Wait 200ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

