        fprintf(stderr, "Failed to read BH1750 after multiple retries.\n");
    }

    return lux;
}

// Function to map lux value to brightness level (logarithmic scale)
float map_lux_to_brightness(float lux) {
    // Define a reasonable lux range for mapping
    float min_lux = 0.01; // Minimum lux value
    float max_lux = 1000.0; // Maximum lux value

    // Clamp lux value to the defined range
    if (lux < min_lux) {
        lux = min_lux;
    } else if (lux > max_lux) {
        lux = max_lux;
    }

    // Logarithmic mapping
    float brightness = log10(lux / min_lux) / log10(max_lux / min_lux);

    // Scale brightness to the range 0-1
    brightness = brightness * (1.0 - 0.0) + 0.0; // Scale to 0-1

    return brightness;
}

// Function to set the brightness of the LED strip using hardware PWM
void set_led_brightness(int gpio_pin, float brightness) {
    // Define PWM parameters
    int frequency = 800000; // 800 kHz
    int dutycycle = (int)(brightness * 1000000); // Duty cycle (0-1000000)

    // Set PWM frequency and dutycycle
    gpioSetPWMfrequency(gpio_pin, frequency);
    gpioPWM(gpio_pin, dutycycle / 10000); // pigpio PWM range is 0-1000
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read lux value from BH1750 sensor
        int lux = read_bh1750(i2c_handle);

        if (lux != -1) {
            // Map lux value to brightness level
            float brightness = map_lux_to_brightness((float)lux);

            // Set LED brightness
            set_led_brightness(GPIO_PIN, brightness);

            printf("Lux: %d, Brightness: %.2f\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Clean up and terminate
    i2cClose(i2c_handle);
    gpioPWM(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

