// I2C initialization function
int i2c_init(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    // BH1750 address
    int addr = 0x23;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI initialization function
int spi_init(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI bus");
        return -1;
    }

    // SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // SPI bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 read lux function
int bh1750_read_lux(int fd) {
    uint8_t config[1] = {0x10}; // Continuous high resolution mode
    if (write(fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(120000); // Wait 120ms

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    unsigned int raw_value = (data[0] << 8) | data[1];
    float lux = (float)raw_value / 1.2; // BH1750 datasheet formula

    return (int)lux;
}

// APA102 set brightness function
void apa102_set_brightness(int fd, int brightness) {
    uint8_t start_frame[START_FRAME_SIZE] = {0x00, 0x00, 0x00, 0x00};
    uint8_t end_frame[END_FRAME_SIZE] = {0xFF, 0xFF, 0xFF, 0xFF};

    uint8_t led_data[NUM_LEDS * LED_FRAME_SIZE];
    for (int i = 0; i < NUM_LEDS; i++) {
        led_data[i * LED_FRAME_SIZE + 0] = 0xE0 | (brightness & 0x1F); // Global brightness
        led_data[i * LED_FRAME_SIZE + 1] = 0x00; // Blue
        led_data[i * LED_FRAME_SIZE + 2] = 0x00; // Green
        led_data[i * LED_FRAME_SIZE + 3] = 0x00; // Red
    }

    apa102_send_data(fd, start_frame, START_FRAME_SIZE);
    apa102_send_data(fd, led_data, NUM_LEDS * LED_FRAME_SIZE);
    apa102_send_data(fd, end_frame, END_FRAME_SIZE);
}

// APA102 send data function
void apa102_send_data(int fd, uint8_t *data, int data_len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)data,
        .len = data_len,
        .delay_usecs = 0,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI data");
    }
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        // Turn off all LEDs by sending a start frame, NUM_LEDS frames with brightness 0, and an end frame
        uint8_t start_frame[START_FRAME_SIZE] = {0x00, 0x00, 0x00, 0x00};
        uint8_t led_data[NUM_LEDS * LED_FRAME_SIZE];
        for (int i = 0; i < NUM_LEDS; i++) {
            led_data[i * LED_FRAME_SIZE + 0] = 0xE0 | (0 & 0x1F); // Global brightness 0
            led_data[i * LED_FRAME_SIZE + 1] = 0x00; // Blue
            led_data[i * LED_FRAME_SIZE + 2] = 0x00; // Green
            led_data[i * LED_FRAME_SIZE + 3] = 0x00; // Red
        }
        uint8_t end_frame[END_FRAME_SIZE] = {0xFF, 0xFF, 0xFF, 0xFF};

        apa102_send_data(spi_fd, start_frame, START_FRAME_SIZE);
        apa102_send_data(spi_fd, led_data, NUM_LEDS * LED_FRAME_SIZE);
        apa102_send_data(spi_fd, end_frame, END_FRAME_SIZE);

        close(spi_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed, exiting...\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_BUS);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed, exiting...\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read light level
        int lux = bh1750_read_lux(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Error reading light level, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Scale brightness
        int brightness = (int)(((float)lux / 1000.0) * MAX_BRIGHTNESS); // Assuming max lux is 1000
        if (brightness < 0) brightness = 0;
        if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;

        // Set LED brightness
        apa102_set_brightness(spi_fd, brightness);

        usleep(50000); // Wait 50ms
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

