#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 10
#define TARGET_BRIGHTNESS 100
#define FADE_DURATION 500 // milliseconds
#define READ_DELAY 180 // milliseconds

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
int i2c_handle_3 = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_bh1750(int handle);
float average_light(int light1, int light2, int light3);
void init_spi(int channel, int speed);
void set_apa102_brightness(int brightness);
void fade_brightness(int target_brightness, int current_brightness);
void cleanup(int signal);

// Signal handler
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;

    // Turn off LED strip
    set_apa102_brightness(0);

    // Close I2C handles
    if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
    if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
    if (i2c_handle_3 >= 0) i2cClose(i2c_handle_3);

    // Close SPI handle
    if (spi_handle >= 0) spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read light level from BH1750 sensor
int read_bh1750(int handle) {
    if (handle < 0) return -1; // Invalid handle

    // Send start measurement command (High Resolution Mode)
    if (i2cWriteByteData(handle, 0x00, 0x10) < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", handle);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(READ_DELAY * 1000); // pigpioDelay takes microseconds

    // Read two bytes of data
    int light_level = i2cReadWordData(handle, 0x00);
    if (light_level < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", light_level);
        return -1;
    }

    // BH1750 returns data in big-endian format, need to swap bytes
    light_level = ((light_level & 0xFF) << 8) | ((light_level & 0xFF00) >> 8);

    return light_level;
}

// Average light levels
float average_light(int light1, int light2, int light3) {
    int count = 0;
    float sum = 0.0;

    if (light1 >= 0) {
        sum += light1;
        count++;
    }
    if (light2 >= 0) {
        sum += light2;
        count++;
    }
    if (light3 >= 0) {
        sum += light3;
        count++;
    }

    if (count == 0) {
        return 0.0; // Avoid division by zero
    }

    return sum / count;
}

// Initialize SPI
void init_spi(int channel, int speed) {
    spi_handle = spiOpen(channel, speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        exit(1);
    }
}

// Set APA102 brightness
void set_apa102_brightness(int brightness) {
    if (spi_handle < 0) return; // SPI not initialized

    // APA102 start frame (32 zero bits)
    char start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    spiWrite(spi_handle, start_frame, 4);

    // LED data frames (global brightness, R, G, B)
    for (int i = 0; i < NUM_LEDS; i++) {
        char led_data[4] = {0xE0 | brightness, 0x00, 0x00, 0x00}; // Blue color
        spiWrite(spi_handle, led_data, 4);
    }

    // APA102 end frame (at least (NUM_LEDS + 1) / 2 bytes of 0xFF)
    int end_frame_size = (NUM_LEDS + 1) / 2;
    char *end_frame = malloc(end_frame_size);
    if (end_frame == NULL) {
        fprintf(stderr, "Memory allocation error for end frame\n");
        return;
    }
    for (int i = 0; i < end_frame_size; i++) {
        end_frame[i] = 0xFF;
    }
    spiWrite(spi_handle, end_frame, end_frame_size);
    free(end_frame);
}

// Fade brightness
void fade_brightness(int target_brightness, int current_brightness) {
    int diff = target_brightness - current_brightness;
    int step = diff / (FADE_DURATION / 100); // 100ms steps
    int direction = (diff > 0) ? 1 : -1; // 1 for increasing, -1 for decreasing

    for (int i = 0; i < FADE_DURATION / 100; i++) {
        current_brightness += direction * step;
        if (direction > 0 && current_brightness > target_brightness) {
            current_brightness = target_brightness;
        } else if (direction < 0 && current_brightness < target_brightness) {
            current_brightness = target_brightness;
        }
        set_apa102_brightness(current_brightness);
        gpioDelay(100000); // 100ms
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler
    signal(SIGINT, cleanup);

    // Initialize I2C
    i2c_handle_1 = init_i2c(I2C_BUS, BH1750_ADDR_1);
    i2c_handle_2 = init_i2c(I2C_BUS, BH1750_ADDR_2);
    i2c_handle_3 = init_i2c(I2C_BUS, BH1750_ADDR_1); // Try the same address again if the first one failed

    // Initialize SPI
    init_spi(SPI_CHANNEL, SPI_SPEED);

    int current_brightness = 0;

    // Main loop
    while (!terminate) {
        // Read light levels
        int light1 = read_bh1750(i2c_handle_1);
        int light2 = read_bh1750(i2c_handle_2);
        int light3 = read_bh1750(i2c_handle_3);

        // Average light levels
        float avg_light = average_light(light1, light2, light3);

        // Map light level to brightness (0-255)
        int target_brightness = (int)(avg_light / 100.0); // Adjust scaling as needed
        if (target_brightness > 255) target_brightness = 255;
        if (target_brightness < 0) target_brightness = 0;

        // Fade brightness
        fade_brightness(target_brightness, current_brightness);
        current_brightness = target_brightness; // Update current brightness

        // Delay
        gpioDelay(100000); // 100ms
    }

    return 0;
}

