#include <math.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS 0x04
#define VEML7700_WHITE 0x05
#define VEML7700_POWER_SAVE 0x06

// WS2812B GPIO pin
#define WS2812B_GPIO 18

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize the VEML7700 sensor
int init_veml7700() {
    // Configuration: Gain = 2, Integration Time = 100ms, Continuous mode
    uint16_t config = 0x0000; // Default configuration
    config |= (0x02 << 11); // Gain 2
    config |= (0x03 << 6);  // Integration time 100ms
    config |= (0x00 << 1);  // Continuous mode

    // Write the configuration to the sensor
    char buf[3];
    buf[0] = VEML7700_ALS_CONF;
    buf[1] = config & 0xFF;
    buf[2] = (config >> 8) & 0xFF;

    int retries = 3;
    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, buf, 3) == 0) {
            return 0; // Success
        }
        fprintf(stderr, "Error writing to VEML7700, retrying...\n");
        gpioDelay(100000); // 100ms delay
        retries--;
    }
    fprintf(stderr, "Failed to initialize VEML7700 after multiple retries.\n");
    return -1; // Failure
}

// Function to read the ambient light value from the VEML7700 sensor
int read_veml7700(uint16_t *als_data) {
    char buf[1];
    char data[2];

    buf[0] = VEML7700_ALS;

    int retries = 3;
    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, buf, 1) == 0) {
            if (i2cReadDevice(i2c_handle, data, 2) == 2) {
                *als_data = (data[1] << 8) | data[0];
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading ALS data, retrying...\n");
            }
        } else {
            fprintf(stderr, "Error writing to VEML7700 (ALS register), retrying...\n");
        }
        gpioDelay(100000); // 100ms delay
        retries--;
    }
    fprintf(stderr, "Failed to read VEML7700 ALS data after multiple retries.\n");
    return -1; // Failure
}

// Function to convert ALS data to lux
float als_to_lux(uint16_t als_data) {
    // VEML7700 lux calculation (example, adjust based on gain and integration time)
    // This is a simplified example and may need calibration
    float lux = (float)als_data * 0.0576; // Example conversion factor
    return lux;
}

// Function to apply gamma correction
float gamma_correct(float lux) {
    // Gamma correction formula (example, adjust as needed)
    float gamma = 2.2;
    float brightness = powf(lux / 1000.0, 1.0 / gamma); // Normalize to 0-1 range
    if (brightness > 1.0) brightness = 1.0; // Clamp to 1.0
    if (brightness < 0.0) brightness = 0.0; // Clamp to 0.0
    return brightness;
}

// Function to set the brightness of the WS2812B LED strip
void set_led_brightness(float brightness) {
    // Map brightness (0.0-1.0) to RGB values (0-255)
    uint8_t red = (uint8_t)(brightness * 255.0);
    uint8_t green = (uint8_t)(brightness * 255.0);
    uint8_t blue = (uint8_t)(brightness * 255.0);

    // Bit-banging the data line
    for (int i = 0; i < 24; i++) {
        // Green
        if ((green >> (23 - i)) & 0x01) {
            gpioWrite(WS2812B_GPIO, 1);
            gpioDelay(0.8); // 0.8us
            gpioWrite(WS2812B_GPIO, 0);
            gpioDelay(0.45); // 0.45us
        } else {
            gpioWrite(WS2812B_GPIO, 1);
            gpioDelay(0.4); // 0.4us
            gpioWrite(WS2812B_GPIO, 0);
            gpioDelay(0.85); // 0.85us
        }

        // Red
        if ((red >> (23 - i)) & 0x01) {
            gpioWrite(WS2812B_GPIO, 1);
            gpioDelay(0.8); // 0.8us
            gpioWrite(WS2812B_GPIO, 0);
            gpioDelay(0.45); // 0.45us
        } else {
            gpioWrite(WS2812B_GPIO, 1);
            gpioDelay(0.4); // 0.4us
            gpioWrite(WS2812B_GPIO, 0);
            gpioDelay(0.85); // 0.85us
        }

        // Blue
        if ((blue >> (23 - i)) & 0x01) {
            gpioWrite(WS2812B_GPIO, 1);
            gpioDelay(0.8); // 0.8us
            gpioWrite(WS281_GPIO, 0);
            gpioDelay(0.45); // 0.45us
        } else {
            gpioWrite(WS2812B_GPIO, 1);
            gpioDelay(0.4); // 0.4us
            gpioWrite(WS2812B_GPIO, 0);
            gpioDelay(0.85); // 0.85us
        }
    }
    gpioDelay(50); // Reset time
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t als_data;
        if (read_veml7700(&als_data) == 0) {
            float lux = als_to_lux(als_data);
            float brightness = gamma_correct(lux);
            set_led_brightness(brightness);

            printf("Lux: %.2f, Brightness: %.2f\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(200000); // 200ms delay
    }

    // Cleanup
    set_led_brightness(0.0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

