#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define constants
#define SELF_TEST_SAMPLES 5
#define SELF_TEST_INTERVAL_MS 100
#define MAIN_LOOP_INTERVAL_MS 50
#define ERROR_BLINK_INTERVAL_MS 100
#define ERROR_BLINK_CYCLES 5
#define BUZZER_SHORT_MS 200
#define BUZZER_LONG_MS 600
#define BUZZER_REPEATS 3

// Global variable for program termination flag
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor();
void control_buzzer(int state);
void control_led(int state);
void log_event(const char *event_type);
void self_test();
void main_loop();
void signal_handler(int signal);

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to control the buzzer
void control_buzzer(int state) {
    int result = gpioWrite(BUZZER_PIN, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to buzzer: %d\n", result);
    }
}

// Function to control the LED
void control_led(int state) {
    int result = gpioWrite(LED_PIN, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to LED: %d\n", result);
    }
}

// Function to log events with timestamps
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] %s\n", timestamp, event_type);
}

// Function to perform the self-test
void self_test() {
    printf("Starting self-test...\n");
    int flame_detected = 1; // Assume flame detected initially
    for (int i = 0; i < SELF_TEST_SAMPLES; i++) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == -1) {
            fprintf(stderr, "Error during self-test, exiting.\n");
            exit(1);
        }
        if (sensor_value == 1) { // Flame not detected
            flame_detected = 0;
        }
        gpioDelay(SELF_TEST_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    if (flame_detected) {
        printf("Self-test failed: Flame detected during startup.\n");
        log_event("ERROR: Flame detected during startup.");
        // Blink LED rapidly
        for (int i = 0; i < ERROR_BLINK_CYCLES; i++) {
            control_led(1);
            gpioDelay(ERROR_BLINK_INTERVAL_MS * 1000);
            control_led(0);
            gpioDelay(ERROR_BLINK_INTERVAL_MS * 1000);
        }

        // Sound buzzer with short-short-long-short pattern
        for (int i = 0; i < BUZZER_REPEATS; i++) {
            control_buzzer(1);
            gpioDelay(BUZZER_SHORT_MS * 1000);
            control_buzzer(0);
            gpioDelay(BUZZER_SHORT_MS * 1000);
            control_buzzer(1);
            gpioDelay(BUZZER_SHORT_MS * 1000);
            control_buzzer(0);
            gpioDelay(BUZZER_LONG_MS * 1000);
            control_buzzer(1);
            gpioDelay(BUZZER_SHORT_MS * 1000);
            control_buzzer(0);
        }

        exit(1);
    } else {
        printf("Self-test passed.\n");
        log_event("Self-test passed.");
    }

    // Blink LED twice (500ms on, 500ms off)
    for (int i = 0; i < 2; i++) {
        control_led(1);
        gpioDelay(500 * 1000);
        control_led(0);
        gpioDelay(500 * 1000);
    }
}

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("Signal received, cleaning up and exiting...\n");
    program_running = 0;
    control_buzzer(0);
    control_led(0);
    gpioTerminate();
    exit(0);
}

// Main loop function
void main_loop() {
    int flame_detected = 0;
    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == -1) {
            fprintf(stderr, "Error reading flame sensor in main loop, exiting.\n");
            log_event("ERROR: Reading flame sensor in main loop.");
            exit(1);
        }

        if (sensor_value == 0 && !flame_detected) { // Flame detected
            printf("Flame detected!\n");
            log_event("Flame detected");
            control_buzzer(1);
            control_led(1);
            flame_detected = 1;
        } else if (sensor_value == 1 && flame_detected) { // Flame cleared
            printf("Flame cleared!\n");
