#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define MIN_FREQUENCY 0.5
#define MAX_FREQUENCY 5.0
#define MAX_LUX 1000.0

// Global variables
static int i2c_fd = -1;
static int gpio_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int i2c_setup(const char *bus);
int bh1750_read_lux(int fd);
void gpio_setup(int pin);
void gpio_set_value(int pin, int value);
void gpio_cleanup(int pin);
void circular_buffer_init(CircularBuffer *cb);
void circular_buffer_add(CircularBuffer *cb, float value);
float circular_buffer_average(const CircularBuffer *cb);
float calculate_frequency(float average_lux);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 read lux function
int bh1750_read_lux(int fd) {
    uint8_t config[1] = {0x10}; // Continuous high-resolution mode
    uint8_t data[2];
    int lux = -1;

    if (write(fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(180000); // Wait for measurement (at least 180ms)

    if (read(fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    lux = (data[0] << 8) | data[1];
    return lux;
}

// GPIO setup function
void gpio_setup(int pin) {
    char buffer[64];
    int len;

    // Export GPIO pin
    gpio_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening /sys/class/gpio/export");
        exit(1);
    }
    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(gpio_fd, buffer, len) != len) {
        perror("Error writing to /sys/class/gpio/export");
        close(gpio_fd);
        exit(1);
    }
    close(gpio_fd);

    // Set GPIO direction to output
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", pin);
    gpio_fd = open(buffer, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO direction file");
        exit(1);
    }
    if (write(gpio_fd, "out", 3) != 3) {
        perror("Error writing to GPIO direction file");
        close(gpio_fd);
        exit(1);
    }
    close(gpio_fd);
}

// GPIO set value function
void gpio_set_value(int pin, int value) {
    char buffer[64];
    int len;

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", pin);
    gpio_fd = open(buffer, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO value file");
        return;
    }
    len = snprintf(buffer, sizeof(buffer), "%d", value);
    if (write(gpio_fd, buffer, len) != len) {
        perror("Error writing to GPIO value file");
    }
    close(gpio_fd);
}

// GPIO cleanup function
void gpio_cleanup(int pin) {
    char buffer[64];
    int len;

    // Unexport GPIO pin
    gpio_fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening /sys/class/gpio/unexport");
        return;
    }
    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(gpio_fd, buffer, len) != len) {
        perror("Error writing to /sys/class/gpio/unexport");
    }
    close(gpio_fd);
}

// Circular buffer initialization function
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Circular buffer add function
void circular_buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Circular buffer average function
float circular_buffer_average(const CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Calculate frequency function
float calculate_frequency(float average_lux) {
    float frequency = MIN_FREQUENCY + (average_lux / MAX_LUX) * (MAX_FREQUENCY - MIN_FREQUENCY);
    if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }
    return frequency;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

int main() {
    CircularBuffer lux_buffer;
    struct timespec sleep_time;
    float average_lux;
    float frequency;
    int lux;

    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize GPIO
    gpio_setup(GPIO_PIN);

    // Initialize circular buffer
    circular_buffer_init(&lux_buffer);

    // Main loop
    while (!terminate) {
        // Read lux value
        lux = bh1750_read_lux(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Add lux value to circular buffer
        circular_buffer_add(&lux_buffer, (float)lux);

        // Calculate average lux
        average_lux = circular_buffer_average(&lux_buffer);

        // Calculate frequency
        frequency = calculate_frequency(average_lux);

        // Calculate period in nanoseconds
        long period_ns = (long)((1.0 / frequency) * 1000000000.0);

        // Blink LED with calculated frequency
        gpio_set_value(GPIO_PIN, 1);
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = period_ns / 2;
        nanosleep(&sleep_time, NULL);

        gpio_set_value(GPIO_PIN, 0);
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = period_ns / 2;
        nanosleep(&sleep_time, NULL);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    gpio_cleanup(GPIO_PIN);
    close(i2c_fd);

    return 0;
}

