#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define the digit '5' pattern (a, b, c, d, e, f, g, dp)
const unsigned char digit5_pattern = 0x6D; // 0b01101101

// Function prototypes
int initialize_gpio();
void shift_out(unsigned char data);
void latch_data();
void display_digit5();
void blink_display();
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Cleaning up and exiting.\n");
        program_running = 0;
        cleanup_gpio();
        exit(0);
    }
}

// Initializes the pigpio library and sets the GPIO pins as outputs.
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set DATA_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set CLOCK_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LATCH_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Sends the 8-bit data to the shift register, MSB first.
void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        // Extract the i-th bit (MSB first)
        int bit = (data >> i) & 1;

        // Set the data pin
        gpioWrite(DATA_PIN, bit);

        // Clock the data in
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1); // Small delay for setup time
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1); // Small delay for hold time
    }
}

// Latches the data from the shift register to the output pins.
void latch_data() {
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1); // Small delay for setup time
    gpioWrite(LATCH_PIN, 0);
    gpioDelay(1); // Small delay for hold time
}

// Shifts out the pattern for the digit '5' and latches it.
void display_digit5() {
    shift_out(digit5_pattern);
    latch_data();
}

// Blinks the display on for 500ms and off for 500ms.
void blink_display() {
    gpioWrite(LATCH_PIN, 1); // Turn on the display
    gpioDelay(500);          // On for 500ms
    gpioWrite(LATCH_PIN, 0); // Turn off the display
    gpioDelay(500);          // Off for 500ms
}

// Terminates the pigpio library.
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Displaying digit '5' on seven-segment display. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        display_digit5();
        blink_display();
    }

    // Cleanup GPIO before exiting (should not reach here if signal handler works)
    cleanup_gpio();

    return 0;
}

