#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define GPIOCHIP "gpiochip0"
#define LED_PIN 17
#define BUTTON_PIN 18

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to blink the LED
void blink_led(struct gpiod_line *line)
{
    int ret;

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Error setting LED value");
        return;
    }
    struct timespec on_time = {1, 0}; // 1 second
    nanosleep(&on_time, NULL);

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("Error setting LED value");
        return;
    }
    struct timespec off_time = {1, 0}; // 1 second
    nanosleep(&off_time, NULL);
}

// Function to handle button press event
void button_event_handler(struct gpiod_line *line)
{
    int ret;
    int value;

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        perror("Error getting button value");
        return;
    }
    value = ret;

    if (value == 0) { // Assuming button is active low
        printf("Button pressed!\n");
        keep_running = 0; // Stop the blinking loop
    }
}

int main()
{
    int ret;
    struct gpiod_line_request_config led_config;
    struct gpiod_line_request_config button_config;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Request LED line as output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    memset(&led_config, 0, sizeof(led_config));
    led_config.consumer = "blink_led";
    led_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    led_config.flags = 0; // No flags needed for output

    ret = gpiod_line_request(led_line, &led_config, 0); // Initial value 0 (off)
    if (ret < 0) {
        perror("Error requesting LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request button line as input with pull-up and falling edge detection
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    memset(&button_config, 0, sizeof(button_config));
    button_config.consumer = "button_input";
    button_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    button_config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP | GPIOD_LINE_REQUEST_FLAG_EVENT_FALLING_EDGE;

    ret = gpiod_line_request(button_line, &button_config, 0);
    if (ret < 0) {
        perror("Error requesting button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        blink_led(led_line);
        button_event_handler(button_line);
    }

    // Cleanup
    gpiod_line_set_value(led_line, 0); // Turn off LED
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

