        printf("LED OFF\n");
        fflush(stdout);
        gpioDelay(750000); // 750ms
    }

    // Clean up and exit
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();       // Terminate pigpio

    printf("Program terminated gracefully.\n");
    return 0;
}

