#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Set button pin as input with pull-down resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", BUTTON_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", BUTTON_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(500000);      // Wait 500ms
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioDelay(500000);      // Wait 500ms
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button state
        int button_state = gpioRead(BUTTON_PIN);

        // If button is pressed (HIGH)
        if (button_state == 1) {
            blink_led();
        } else {
            gpioWrite(LED_PIN, 0); // Ensure LED is off when button is not pressed
            gpioDelay(10000);       // Small delay to avoid busy-waiting
        }
    }

    // Cleanup GPIO
    gpioWrite(LED_PIN, 0); // Turn off LED before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

