#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// PWM frequency (Hz)
#define PWM_FREQUENCY 100

// PWM period (seconds)
#define PWM_PERIOD (1.0 / PWM_FREQUENCY)

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Set all GPIO pins to LOW (off)
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm(int pin, int duty_cycle) {
    // Calculate the on-time and off-time for the PWM signal
    double period = PWM_PERIOD;
    double on_time = (double)duty_cycle / 100.0 * period;
    double off_time = period - on_time;

    // Convert times to nanoseconds
    long on_time_ns = (long)(on_time * 1000000000.0);
    long off_time_ns = (long)(off_time * 1000000000.0);

    // Set the pin HIGH for the on-time
    gpioWrite(pin, 1);
    struct timespec on_sleep = {0, on_time_ns};
    clock_nanosleep(CLOCK_REALTIME, 0, &on_sleep, NULL);

    // Set the pin LOW for the off-time
    gpioWrite(pin, 0);
    struct timespec off_sleep = {0, off_time_ns};
    clock_nanosleep(CLOCK_REALTIME, 0, &off_sleep, NULL);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Generate random intensity values for each color
        int red_intensity = rand() % 101;
        int green_intensity = rand() % 101;
        int blue_intensity = rand() % 101;

        // Set PWM duty cycles for each color
        set_pwm(RED_PIN, red_intensity);
        set_pwm(GREEN_PIN, green_intensity);
        set_pwm(BLUE_PIN, blue_intensity);

        // Wait for 100ms
        struct timespec sleep_time = {0, 100000000}; // 100ms
        clock_nanosleep(CLOCK_REALTIME, 0, &sleep_time, NULL);
    }

    return 0;
}

