#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define ALS_LSB_REG 0x00
#define ALS_MSB_REG 0x01
#define RED_LSB_REG 0x02
#define RED_MSB_REG 0x03
#define GREEN_LSB_REG 0x04
#define GREEN_MSB_REG 0x05
#define BLUE_LSB_REG 0x06
#define BLUE_MSB_REG 0x07
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
uint16_t combine_bytes(uint8_t lsb, uint8_t msb);
void set_led_brightness(uint16_t als_value);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    uint8_t buffer[2];
    int result;

    // Read ALS data
    result = i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
        data.als = 0; // Set to 0 to avoid using uninitialized data
    } else {
        data.als = combine_bytes(buffer[0], buffer[1]);
    }

    // Read Red data
    result = i2cReadI2CBlockData(i2c_handle, RED_LSB_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading Red data: %s\n", strerror(errno));
        data.red = 0; // Set to 0 to avoid using uninitialized data
    } else {
        data.red = combine_bytes(buffer[0], buffer[1]);
    }

    // Read Green data
    result = i2cReadI2CBlockData(i2c_handle, GREEN_LSB_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading Green data: %s\n", strerror(errno));
        data.green = 0; // Set to 0 to avoid using uninitialized data
    } else {
        data.green = combine_bytes(buffer[0], buffer[1]);
    }

    // Read Blue data
    result = i2cReadI2CBlockData(i2c_handle, BLUE_LSB_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading Blue data: %s\n", strerror(errno));
        data.blue = 0; // Set to 0 to avoid using uninitialized data
    } else {
        data.blue = combine_bytes(buffer[0], buffer[1]);
    }

    return data;
}

// Function to combine two bytes into a 16-bit unsigned integer
uint16_t combine_bytes(uint8_t lsb, uint8_t msb) {
    return (uint16_t)((msb << 8) | lsb);
}

// Function to set LED brightness using PWM
void set_led_brightness(uint16_t als_value) {
    // Map ALS value to PWM duty cycle (0-1000000)
    int duty_cycle = (int)(((float)als_value / 65535.0) * 1000000.0); // Assuming max ALS value is 65535
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000000) duty_cycle = 1000000;
    gpioPWM(LED_GPIO, duty_cycle);
}

// Function to log data to CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data.als, data.red, data.green, data.blue);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Set GPIO back to input mode
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        set_led_brightness(data.als);
        log_data(data);
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

