#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define WHO_AM_I_VALUE 0xD3
#define SAMPLE_RATE 20 // Hz
#define SAMPLE_PERIOD 50 // ms
#define ALERT_THRESHOLD 50.0 // dps

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int read_register(int reg);
int write_register(int reg, int value);
int calibrate_gyro(float *x_offset, float *y_offset, float *z_offset);
gyro_data_t read_gyro_data(float x_offset, float y_offset, float z_offset);
char* get_iso8601_timestamp();
void log_data(char *timestamp, float x, float y, float z);
void log_alert(char *timestamp, float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = read_register(WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%X (expected 0x%X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 100Hz, enable all axes)
    if (write_register(CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4 (2000 dps full scale)
    if (write_register(CTRL_REG4, 0x20) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read a single register
int read_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a single register
int write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to calibrate the gyroscope
int calibrate_gyro(float *x_offset, float *y_offset, float *z_offset) {
    int16_t x, y, z;
    long x_sum = 0, y_sum = 0, z_sum = 0;
    int num_samples = 100;

    printf("Calibrating gyroscope...\n");

    for (int i = 0; i < num_samples; i++) {
        // Read raw gyroscope data
        int x_l = read_register(OUT_X_L);
        int x_h = read_register(OUT_X_L + 1);
        int y_l = read_register(OUT_X_L + 2);
        int y_h = read_register(OUT_X_L + 3);
        int z_l = read_register(OUT_X_L + 4);
        int z_h = read_register(OUT_X_L + 5);

        if (x_l < 0 || x_h < 0 || y_l < 0 || y_h < 0 || z_l < 0 || z_h < 0) {
            fprintf(stderr, "Error reading gyroscope data during calibration\n");
            return -1;
        }

        x = (int16_t)((x_h << 8) | x_l);
        y = (int16_t)((y_h << 8) | y_l);
        z = (int16_t)((z_h << 8) | z_l);

        x_sum += x;
        y_sum += y;
        z_sum += z;

        gpioDelay(10); // Small delay between samples
    }

    *x_offset = (float)x_sum / num_samples;
    *y_offset = (float)y_sum / num_samples;
    *z_offset = (float)z_sum / num_samples;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", *x_offset, *y_offset, *z_offset);
    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data(float x_offset, float y_offset, float z_offset) {
    gyro_data_t data;
    int16_t raw_x, raw_y, raw_z;

    // Read raw gyroscope data
    int x_l = read_register(OUT_X_L);
    int x_h = read_register(OUT_X_L + 1);
    int y_l = read_register(OUT_X_L + 2);
    int y_h = read_register(OUT_X_L + 3);
    int z_l = read_register(OUT_X_L + 4);
    int z_h = read_register(OUT_X_L + 5);

    if (x_l < 0 || x_h < 0 || y_l < 0 || y_h < 0 || z_l < 0 || z_h < 0) {
        data.x = 0.0; // Set to 0 to avoid using uninitialized data
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    raw_x = (int16_t)((x_h << 8) | x_l);
    raw_y = (int16_t)((y_h << 8) | y_l);
    raw_z = (int16_t)((z_h << 8) | z_l);

    // Apply calibration offsets
    data.x = (float)raw_x - x_offset;
    data.y = (float)raw_y - y_offset;
    data.z = (float)raw_z - z_offset;

    return data;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

// Function to log data to file
void log_data(char *timestamp, float x, float y, float z) {
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to log alert to file
void log_alert(char *timestamp, float x, float y, float z) {
    fprintf(log_file, "%s,ALERT,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file);
    fprintf(stderr, "ALERT: Timestamp=%s, X=%.2f, Y=%.2f, Z=%.2f\n", timestamp, x, y, z);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    float x_offset, y_offset, z_offset;
    gyro_data_t gyro_data;
    char *timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Calibrate the gyroscope
    if (calibrate_gyro(&x_offset, &y_offset, &z_offset) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        gyro_data = read_gyro_data(x_offset, y_offset, z_offset);

        // Get timestamp
        timestamp = get_iso8601_timestamp();

        // Log data
        log_data(timestamp, gyro_data.x, gyro_data.y, gyro_data.z);

        // Check for alert condition
        if (fabs(gyro_data.x) > ALERT_THRESHOLD || fabs(gyro_data.y) > ALERT_THRESHOLD || fabs(gyro_data.z) > ALERT_THRESHOLD) {
            log_alert(timestamp, gyro_data.x, gyro_data.y, gyro_data.z);
        }

        // Delay for 50ms (20Hz sampling rate)
        gpioDelay(SAMPLE_PERIOD * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

