#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

// LSM303DLHC I2C addresses
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

// LSM303DLHC register addresses
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A  0x28
#define LSM303_MAG_MR_REG_M     0x02
#define LSM303_MAG_OUT_X_H_M  0x03

// Scaling factors
#define ACCEL_SCALE 0.001 // 1 mg/LSB
#define MAG_SCALE   0.001 // 1 mGauss/LSB

// Global variables
int i2c_handle_accel = -1;
int i2c_handle_mag = -1;
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int init_i2c();
int init_accel();
int init_mag();
int read_accel(float *x, float *y, float *z);
int read_mag(float *x, float *y, float *z);
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
int log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize accelerometer and magnetometer
    if (init_accel() != 0 || init_mag() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }
    rewind(log_file);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (running) {
        // Read sensor data
        if (read_accel(&sensor_data.accel_x, &sensor_data.accel_y, &sensor_data.accel_z) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue; // Continue to the next iteration
        }
        if (read_mag(&sensor_data.mag_x, &sensor_data.mag_y, &sensor_data.mag_z) != 0) {
            fprintf(stderr, "Failed to read magnetometer data\n");
            continue; // Continue to the next iteration
        }

        // Calculate heading
        sensor_data.heading = calculate_heading(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, sensor_data.mag_x, sensor_data.mag_y, sensor_data.mag_z);

        // Log data
        if (log_data(sensor_data.heading, sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, sensor_data.mag_x, sensor_data.mag_y, sensor_data.mag_z) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

int init_i2c() {
    // Open I2C bus for accelerometer
    i2c_handle_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Failed to open I2C device for accelerometer: %s\n", strerror(errno));
        return -1;
    }

    // Open I2C bus for magnetometer
    i2c_handle_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Failed to open I2C device for magnetometer: %s\n", strerror(errno));
        i2cClose(i2c_handle_accel);
        return -1;
    }

    return 0;
}

int init_accel() {
    // Enable accelerometer (100 Hz, normal mode)
    if (i2cWriteByteData(i2c_handle_accel, LSM303_ACCEL_CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG1_A: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int init_mag() {
    // Enable magnetometer (continuous conversion mode)
    if (i2cWriteByteData(i2c_handle_mag, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to magnetometer MR_REG_M: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_accel(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_accel, LSM303_ACCEL_OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes, convert to g
    *x = (float)((int16_t)(buffer[1] << 8 | buffer[0])) * ACCEL_SCALE;
    *y = (float)((int16_t)(buffer[3] << 8 | buffer[2])) * ACCEL_SCALE;
    *z = (float)((int16_t)(buffer[5] << 8 | buffer[4])) * ACCEL_SCALE;

    return 0;
}

int read_mag(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, LSM303_MAG_OUT_X_H_M, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read magnetometer data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes, convert to gauss
    *x = (float)((int16_t)(buffer[0] << 8 | buffer[1])) * MAG_SCALE;
    *y = (float)((int16_t)(buffer[2] << 8 | buffer[3])) * MAG_SCALE;
    *z = (float)((int16_t)(buffer[4] << 8 | buffer[5])) * MAG_SCALE;

    return 0;
}

float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float mag_x_comp = mag_x * cos(pitch) + mag_z * sin(pitch);
    float mag_y_comp = mag_x * sin(roll) * sin(pitch) + mag_y * cos(roll) - mag_z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;

    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

int log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
