#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define SAMPLE_INTERVAL_MS 10
#define SAMPLE_INTERVAL_US (SAMPLE_INTERVAL_MS * 1000)
#define CSV_FILENAME "audio_log.dat"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1;
    int16_t sensor2;
    long sec;
    long nsec;
} SensorData;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_sensor_data(int handle, int16_t *data);
double calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data);
int log_data(FILE *fp, SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read sensor data
int read_sensor_data(int handle, int16_t *data) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }
    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Calculate TDOA (simplified)
double calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data) {
    // This is a placeholder.  A real TDOA calculation would involve
    // cross-correlation and knowledge of the speed of sound and microphone
    // geometry.
    return (double)(sensor1_data - sensor2_data) / 1000.0; // Example scaling
}

// Log data to CSV file
int log_data(FILE *fp, SensorData data) {
    if (fprintf(fp, "%ld,%ld,%d,%d,%.6f\n", data.sec, data.nsec, data.sensor1, data.sensor2, calculate_tdoa(data.sensor1, data.sensor2)) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        SensorData data;
        struct timespec ts;

        // Read sensor data
        if (i2c_handle1 < 0) {
            i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
        }
        if (i2c_handle1 >= 0) {
            if (read_sensor_data(i2c_handle1, &data.sensor1) != 0) {
                i2cClose(i2c_handle1);
                i2c_handle1 = -1;
            }
        } else {
            data.sensor1 = 0; // Or some error value
        }

        if (i2c_handle2 < 0) {
            i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
        }
        if (i2c_handle2 >= 0) {
            if (read_sensor_data(i2c_handle2, &data.sensor2) != 0) {
                i2cClose(i2c_handle2);
                i2c_handle2 = -1;
            }
        } else {
            data.sensor2 = 0; // Or some error value
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            data.sec = 0; // Or some error value
            data.nsec = 0; // Or some error value
        } else {
            data.sec = ts.tv_sec;
            data.nsec = ts.tv_nsec;
        }

        // Log data
        if (log_data(log_file, data) != 0) {
            terminate = 1; // Stop if logging fails
        }

        // Delay
        usleep(SAMPLE_INTERVAL_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

