// ADIS16488A Register Addresses
#define ADIS16488A_REG_GYRO_XOUT 0x04
#define ADIS16488A_REG_GYRO_YOUT 0x06
#define ADIS16488A_REG_GYRO_ZOUT 0x08
#define ADIS16488A_REG_ACCEL_XOUT 0x0A
#define ADIS16488A_REG_ACCEL_YOUT 0x0C
#define ADIS16488A_REG_ACCEL_ZOUT 0x0E

// Sensitivity values
#define GYRO_SENSITIVITY 0.005f
#define ACCEL_SENSITIVITY 0.00025f

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Function prototypes
int read_register(int handle, uint8_t reg_addr, int16_t *data);
int write_register(int handle, uint8_t reg_addr, uint16_t data);
void convert_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps, float *accel_x_g, float *accel_y_g, float *accel_z_g);
