// Function to read a register from the ADIS16488A
int read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (reg_addr << 1) | 0x00; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed in read_register\n");
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Function to write a register to the ADIS16488A
int write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (reg_addr << 1) | 0x01; // Write command
    tx_buf[1] = data & 0xFF; // LSB

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed in write_register\n");
        return -1;
    }

    tx_buf[0] = ((reg_addr + 1) << 1) | 0x01; // Write command for MSB
