#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCEL_OUT 0x0A
#define YACCEL_OUT 0x0C
#define ZACCEL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05f
#define ACCEL_SCALE 0.00025f

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_MODE 0

int spi_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting.\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a register from the ADIS16448
int16_t read_register(int handle, uint8_t reg_addr) {
    char tx[2];
    char rx[2];
    int result;

    // Set the read command (MSB = 1)
    tx[0] = reg_addr | 0x80; // Read command
    tx[1] = 0x00; // Dummy byte

    result = spiXfer(handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return 0; // Return 0 on error
    }

    // Combine the received bytes into a 16-bit value
    return (int16_t)((rx[0] << 8) | rx[1]);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read gyroscope and accelerometer data
        int16_t gyro_x_raw = read_register(spi_handle, XGYRO_OUT);
        int16_t gyro_y_raw = read_register(spi_handle, YGYRO_OUT);
        int16_t gyro_z_raw = read_register(spi_handle, ZGYRO_OUT);
        int16_t accel_x_raw = read_register(spi_handle, XACCEL_OUT);
        int16_t accel_y_raw = read_register(spi_handle, YACCEL_OUT);
        int16_t accel_z_raw = read_register(spi_handle, ZACCEL_OUT);

