#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read a 16-bit value from the MPU-6886
int16_t read_mpu6886_axis(int handle, uint8_t reg)
{
    char buf[2];
    int result, retries = 0;

    while (retries < 3) {
        result = i2cReadI2CBlockData(handle, reg, buf, 2);
        if (result == 2) {
            return (int16_t)((buf[0] << 8) | buf[1]);
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %d. Retry %d\n", reg, result, retries + 1);
            retries++;
            gpioDelay(1000); // 1 ms delay
        }
    }

    fprintf(stderr, "Failed to read MPU-6886 after multiple retries.\n");
    return 0; // Return 0 on failure
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU-6886
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Read accelerometer and gyroscope values
        int16_t accel_x = read_mpu6886_axis(i2c_handle, ACCEL_XOUT_H);
        int16_t accel_y = read_mpu6886_axis(i2c_handle, ACCEL_XOUT_H + 2);
        int16_t accel_z = read_mpu6886_axis(i2c_handle, ACCEL_XOUT_H + 4);
        int16_t gyro_x  = read_mpu6886_axis(i2c_handle, GYRO_XOUT_H);
        int16_t gyro_y  = read_mpu6886_axis(i2c_handle, GYRO_XOUT_H + 2);
        int16_t gyro_z  = read_mpu6886_axis(i2c_handle, GYRO_XOUT_H + 4);

        // Print the values
        printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        gpioDelay(50000); // 50 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

