#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define LED_GPIO 17
#define THRESHOLD 2.5f
#define LED_ON_TIME 500 // milliseconds
#define SAMPLE_RATE 10000 // microseconds (10ms)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
void cleanup();
void signal_handler(int signal);
int read_adxl345(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z, float magnitude);
void control_led(int on);

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
    float magnitude;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, 0x00);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%X\n", device_id);
        return -1;
    }

    // Set data format to full resolution, +/- 2g range
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Function to initialize logging
int init_logging() {
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Function to read accelerometer data
int read_adxl345(float *x, float *y, float *z) {
    char raw_data[6];
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes, convert to g-force
    *x = (float)((int16_t)((raw_data[1] << 8) | raw_data[0])) / 256.0f;
    *y = (float)((int16_t)((raw_data[3] << 8) | raw_data[2])) / 256.0f;
    *z = (float)((int16_t)((raw_data[5] << 8) | raw_data[4])) / 256.0f;

    return 0;
}

// Function to calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Function to log impact event
void log_impact(float x, float y, float z, float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g, Magnitude: %.3f g\n",
            timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
    if (on) {
        gpioDelay(LED_ON_TIME * 1000); // Convert ms to microseconds
        gpioWrite(LED_GPIO, 0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring accelerometer... Press Ctrl+C to exit.\n");

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_adxl345(&sensor_data.x, &sensor_data.y, &sensor_data.z) == 0) {
            sensor_data.magnitude = calculate_magnitude(sensor_data.x, sensor_data.y, sensor_data.z);

            if (sensor_data.magnitude > THRESHOLD) {
                printf("Impact detected! Magnitude: %.3f g\n", sensor_data.magnitude);
                log_impact(sensor_data.x, sensor_data.y, sensor_data.z, sensor_data.magnitude);
                control_led(1); // Turn on LED
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(SAMPLE_RATE); // Delay for 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

