#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x2A
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_Y_MSB 0x03
#define OUT_Z_MSB 0x05
#define LED_PIN 17
#define G_THRESHOLD 2.0
#define G_SCALE 1024.0
#define LOG_FILE "impact_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_register(int fd, int reg);
int write_register(int fd, int reg, int value);
int verify_sensor_id(int fd);
int read_acceleration(int fd, int *x, int *y, int *z);
bool check_threshold(int x, int y, int z);
void log_data(FILE *fp, int x, int y, int z);
void control_led(int pin, int state);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(int bus, int addr) {
    int fd = wiringPiI2CSetupInterface(bus, addr);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Read a single register from the I2C device
int read_register(int fd, int reg) {
    int value = wiringPiI2CReadReg8(fd, reg);
    if (value == -1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Write a single register to the I2C device
int write_register(int fd, int reg, int value) {
    int result = wiringPiI2CWriteReg8(fd, reg, value);
    if (result == -1) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Verify the sensor's ID
int verify_sensor_id(int fd) {
    int id = read_register(fd, WHO_AM_I_REG);
    if (id == -1) {
        return -1;
    }
    if (id != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", id, WHO_AM_I_VALUE);
        return -1;
    }
    return 0;
}

// Read acceleration data from the sensor
int read_acceleration(int fd, int *x, int *y, int *z) {
    int x_msb = read_register(fd, OUT_X_MSB);
    int y_msb = read_register(fd, OUT_Y_MSB);
    int z_msb = read_register(fd, OUT_Z_MSB);

    if (x_msb == -1 || y_msb == -1 || z_msb == -1) {
        return -1;
    }

    *x = (int8_t)x_msb;
    *y = (int8_t)y_msb;
    *z = (int8_t)z_msb;

    return 0;
}

// Check if the acceleration magnitude exceeds the threshold
bool check_threshold(int x, int y, int z) {
    double x_g = (double)x / G_SCALE;
    double y_g = (double)y / G_SCALE;
    double z_g = (double)z / G_SCALE;

    return (fabs(x_g) > G_THRESHOLD || fabs(y_g) > G_THRESHOLD || fabs(z_g) > G_THRESHOLD);
}

// Log data to the file
void log_data(FILE *fp, int x, int y, int z) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Control the LED
void control_led(int pin, int state) {
    digitalWrite(pin, state);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, MMA8451Q_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id(i2c_fd) == -1) {
        close(i2c_fd);
        return 1;
    }

    // Set accelerometer to active mode
    if (write_register(i2c_fd, CTRL_REG1, 0x01) == -1) {
        close(i2c_fd);
        return 1;
    }

    // Configure LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int x, y, z;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == -1) {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
            delay(100); // Small delay before retrying
            continue;
        }

        // Check for threshold exceedance
        if (check_threshold(x, y, z)) {
            // Log data
            log_data(log_file, x, y, z);

            // Turn on LED
            control_led(LED_PIN, HIGH);
            delay(500);

            // Turn off LED
            control_led(LED_PIN, LOW);
        }

        // Delay
        delay(100);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    control_led(LED_PIN, LOW);

    return 0;
}

