#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_DEVICE_ID 0xE5
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_SOURCE 0x30
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37
#define ADXL345_THRESH_FF 0x28
#define ADXL345_TIME_FF 0x29

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 50

// Global variables
static int i2c_fd = -1;
static int log_fd = -1;
static volatile bool freefall_active = false;
static volatile unsigned long last_interrupt_time = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int adxl345_init(int fd);
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
void interrupt_handler(int gpio, int level, unsigned int tick, void *user_data);
void signal_handler(int signal);
int setup_gpio_interrupt(int gpio_pin);
int setup_i2c(const char *bus);
int setup_log_file(const char *filename);
void cleanup();

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    // Verify device ID
    int device_id = i2c_read_reg(fd, 0x00);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    if (device_id != ADXL345_DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x%02X)\n", device_id, ADXL345_DEVICE_ID);
        return -1;
    }

    // Place in standby mode
    if (i2c_write_reg(fd, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error setting standby mode\n");
        return -1;
    }

    // Configure free-fall threshold and time
    if (i2c_write_reg(fd, ADXL345_THRESH_FF, 0x0A) < 0) { // Example threshold
        fprintf(stderr, "Error setting free-fall threshold\n");
        return -1;
    }
    if (i2c_write_reg(fd, ADXL345_TIME_FF, 0x0C) < 0) { // Example time
        fprintf(stderr, "Error setting free-fall time\n");
        return -1;
    }

    // Enable free-fall interrupt
    if (i2c_write_reg(fd, ADXL345_INT_ENABLE, 0x40) < 0) {
        fprintf(stderr, "Error enabling free-fall interrupt\n");
        return -1;
    }

    // Start measurement
    if (i2c_write_reg(fd, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error starting measurement\n");
        return -1;
    }

    return 0;
}

// ADXL345 read acceleration function
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x0, x1, y0, y1, z0, z1;

    x0 = i2c_read_reg(fd, ADXL345_DATAX0);
    x1 = i2c_read_reg(fd, ADXL345_DATAX1);
    y0 = i2c_read_reg(fd, ADXL345_DATAY0);
    y1 = i2c_read_reg(fd, ADXL345_DATAY1);
    z0 = i2c_read_reg(fd, ADXL345_DATAZ0);
    z1 = i2c_read_reg(fd, ADXL345_DATAZ1);

    if (x0 < 0 || x1 < 0 || y0 < 0 || y1 < 0 || z0 < 0 || z1 < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((x1 << 8) | x0);
    *y = (int16_t)((y1 << 8) | y0);
    *z = (int16_t)((z1 << 8) | z0);

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    // Debounce the interrupt
    if (current_time - last_interrupt_time < DEBOUNCE_DELAY_MS * 1000) {
        return;
    }
    last_interrupt_time = current_time;

    // Read interrupt source
    int int_source = i2c_read_reg(i2c_fd, ADXL345_INT_SOURCE);
    if (int_source < 0) {
        fprintf(stderr, "Error reading interrupt source\n");
        return;
    }

    // Check if free-fall interrupt occurred
    if (int_source & 0x40) {
        freefall_active = true;
    } else {
        freefall_active = false;
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// GPIO interrupt setup function
int setup_gpio_interrupt(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        perror("Failed to set GPIO mode");
        return -1;
    }

    if (gpioSetPullUpDown(gpio_pin, PI_PUD_UP) != 0) {
        perror("Failed to set GPIO pull-up");
        return -1;
    }

    if (gpioSetISRFuncEx(gpio_pin, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        perror("Failed to set GPIO interrupt");
        return -1;
    }

    return 0;
}

// I2C setup function
int setup_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

// Log file setup function
int setup_log_file(const char *filename) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("Failed to open log file");
        return -1;
    }

    // Write header if the file is newly created
    struct stat st;
    if (fstat(fd, &st) == 0 && st.st_size == 0) {
        const char *header = "Timestamp,X,Y,Z\n";
        if (write(fd, header, strlen(header)) < 0) {
            perror("Failed to write header to log file");
            close(fd);
            return -1;
        }
    }

    return fd;
}

// Cleanup function
void cleanup() {
    // Disable interrupts
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_fd != -1) {
        close(log_fd);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup I2C
    i2c_fd = setup_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    // Setup GPIO interrupt
    if (setup_gpio_interrupt(GPIO_PIN) < 0) {
        cleanup();
        return 1;
    }

    // Setup log file
    log_fd = setup_log_file("freefall_log.csv");
    if (log_fd < 0) {
        cleanup();
        return 1;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (freefall_active) {
            int16_t x, y, z;
            if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                // Get timestamp
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                char timestamp[30];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

                // Format data
                char data[100];
                snprintf(data, sizeof(data), "%s,%d,%d,%d\n", timestamp, x, y, z);

                // Write to log file
                if (write(log_fd, data, strlen(data)) < 0) {
                    perror("Failed to write to log file");
                } else {
                    fsync(log_fd); // Ensure data is written to disk
                }
            }
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

