#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_CTRL1_XL 0x10
#define LSM6DSR_CTRL2_G 0x11
#define LSM6DSR_OUTX_L_G 0x22
#define LSM6DSR_OUTX_L_XL 0x28

// Accelerometer and gyroscope ranges
#define ACCEL_RANGE 2.0f  // ±2g
#define GYRO_RANGE 250.0f // ±250 dps

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define DETECTION_WINDOW 1.0f // 1 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_lsm6dsr();
sensor_data_t read_sensor_data();
float calculate_acceleration_magnitude(sensor_data_t data);
void log_data(sensor_data_t data, float acceleration_magnitude);
void fall_detection(float acceleration_magnitude);
void signal_handler(int signal);

// Fall detection state machine variables
enum { IDLE, FREEFALL, IMPACT } fall_state = IDLE;
double freefall_start_time = 0.0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, LSM6DSR_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x69, got 0x%x\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: ±2g, 104 Hz
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL1_XL, 0x60) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: ±250 dps, 104 Hz
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL2_G, 0x60) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[12];

    // Read accelerometer and gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_G, buffer, 12) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        // Return default values in case of error
        data.accel_x = data.accel_y = data.accel_z = 0.0f;
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0f;
        return data;
    }

    // Combine high and low bytes for gyroscope data
    int16_t gyro_x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t gyro_y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t gyro_z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Combine high and low bytes for accelerometer data
    int16_t accel_x_raw = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t accel_y_raw = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t accel_z_raw = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert raw data to g and dps
    data.gyro_x = (float)gyro_x_raw / 65535.0f * GYRO_RANGE;
    data.gyro_y = (float)gyro_y_raw / 65535.0f * GYRO_RANGE;
    data.gyro_z = (float)gyro_z_raw / 65535.0f * GYRO_RANGE;
    data.accel_x = (float)accel_x_raw / 65535.0f * ACCEL_RANGE;
    data.accel_y = (float)accel_y_raw / 65535.0f * ACCEL_RANGE;
    data.accel_z = (float)accel_z_raw / 65535.0f * ACCEL_RANGE;

    return data;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_acceleration_magnitude(sensor_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Function to log sensor data to a CSV file
void log_data(sensor_data_t data, float acceleration_magnitude) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(log_file, "%.9f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z, data.gyro_x, data.gyro_y, data.gyro_z, acceleration_magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to implement the fall detection state machine
void fall_detection(float acceleration_magnitude) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double current_time = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    switch (fall_state) {
        case IDLE:
            if (acceleration_magnitude < FREEFALL_THRESHOLD) {
                fall_state = FREEFALL;
                freefall_start_time = current_time;
            }
            break;
        case FREEFALL:
            if (acceleration_magnitude > IMPACT_THRESHOLD) {
                if (current_time - freefall_start_time <= DETECTION_WINDOW) {
                    fall_state = IMPACT;
                    printf("FALL DETECTED!\n");
                } else {
                    fall_state = IDLE;
                }
            } else if (current_time - freefall_start_time > DETECTION_WINDOW) {
                fall_state = IDLE;
            }
            break;
        case IMPACT:
            fall_state = IDLE;
            break;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z,acceleration_magnitude\n");

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t data = read_sensor_data();

        // Calculate acceleration magnitude
        float acceleration_magnitude = calculate_acceleration_magnitude(data);

        // Log data
        log_data(data, acceleration_magnitude);

        // Fall detection
        fall_detection(acceleration_magnitude);

        // Delay to achieve 104 Hz sampling rate (approximately 9.6 ms)
        gpioDelay(9600); // 9600 microseconds = 9.6 milliseconds
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

