#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define ADIS16266_WHO_AM_I 0x02
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 3       // SPI mode 3 (CPOL=1, CPHA=1)

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
int verify_who_am_i(int handle);
int read_gyro_data(int handle, float *x, float *y, float *z);
int log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// Function to read a register from the ADIS16266
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00;             // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Function to write a register in the ADIS16266
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data & 0xFF;      //LSB

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

// Function to verify the WHO_AM_I register
int verify_who_am_i(int handle) {
    uint16_t who_am_i;

    if (spi_read_register(handle, ADIS16266_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x4052) {
        fprintf(stderr, "Error: WHO_AM_I check failed. Expected 0x4052, got 0x%04X\n", who_am_i);
        return -1;
    }

    printf("WHO_AM_I check passed. Device ID: 0x%04X\n", who_am_i);
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int handle, float *x, float *y, float *z) {
    uint16_t raw_x, raw_y, raw_z;

    if (spi_read_register(handle, ADIS16266_XGYRO_OUT, &raw_x) != 0) {
        fprintf(stderr, "Error: Failed to read X gyro data\n");
        return -1;
    }

    if (spi_read_register(handle, ADIS16266_YGYRO_OUT, &raw_y) != 0) {
        fprintf(stderr, "Error: Failed to read Y gyro data\n");
        return -1;
    }

    if (spi_read_register(handle, ADIS16266_ZGYRO_OUT, &raw_z) != 0) {
        fprintf(stderr, "Error: Failed to read Z gyro data\n");
        return -1;
    }

    // Convert raw data to degrees per second
    *x = (float)((int16_t)raw_x) * 0.0305;
    *y = (float)((int16_t)raw_y) * 0.0305;
    *z = (float)((int16_t)raw_z) * 0.0305;

    return 0;
