#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SAMPLE_RATE_MS 10
#define SENSITIVITY 114.285

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_dps(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps);
int log_data(float x_dps, float y_dps, float z_dps);
void signal_handler(int signal);

// Structure for grouping gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function to initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int status;

    // Verify WHO_AM_I register
    while (retries > 0) {
        char buf[1];
        status = i2cReadI2CBlockData(i2c_handle, WHO_AM_I_REG, buf, 1);
        if (status == 1) {
            if (buf[0] == WHO_AM_I_VALUE) {
                printf("Gyroscope WHO_AM_I value verified.\n");
                break;
            } else {
                fprintf(stderr, "Error: Incorrect WHO_AM_I value (0x%02X, expected 0x%02X). Retrying...\n", buf[0], WHO_AM_I_VALUE);
            }
        } else {
            fprintf(stderr, "Error reading WHO_AM_I register: %d. Retrying...\n", status);
        }
        retries--;
        gpioDelay(10000); // 10ms delay
    }

    if (retries == 0) {
        fprintf(stderr, "Error: WHO_AM_I verification failed after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 100Hz, enable all axes)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F); //0x0F
        if (status == 0) {
            printf("CTRL_REG1 configured.\n");
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1: %d. Retrying...\n", status);
        }
        retries--;
        gpioDelay(10000); // 10ms delay
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to configure CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG4 (2000 dps full scale)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x20); //0x20
        if (status == 0) {
            printf("CTRL_REG4 configured.\n");
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG4: %d. Retrying...\n", status);
        }
        retries--;
        gpioDelay(10000); // 10ms delay
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to configure CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to read raw gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int status = i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buf, 6); // Enable auto-increment

    if (status != 6) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to convert raw data to degrees per second
void convert_to_dps(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / SENSITIVITY;
    *y_dps = (float)y / SENSITIVITY;
    *z_dps = (float)z / SENSITIVITY;
}

// Function to log data to a CSV file
int log_data(float x_dps, float y_dps, float z_dps) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_dps, y_dps, z_dps);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x_dps, y_dps, z_dps;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            convert_to_dps(raw_x, raw_y, raw_z, &x_dps, &y_dps, &z_dps);
            log_data(x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Error reading or logging data. Continuing...\n");
        }
        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 10ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

