#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the Hall Effect sensors
#define HALL_SENSOR_1 17
#define HALL_SENSOR_2 27

// Define the log file name
#define LOG_FILE "conveyor_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, terminating program...\n", signal);
}

// Function to read the state of a Hall Effect sensor
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log the sensor data to a file
void log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(fp, "%ld,%d,%d\n", timestamp_ms, sensor1_state, sensor2_state);
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(HALL_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(HALL_SENSOR_1, PI_PUD_UP);
    gpioSetMode(HALL_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(HALL_SENSOR_2, PI_PUD_UP);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the state of the Hall Effect sensors
        int sensor1_state = read_sensor(HALL_SENSOR_1);
        int sensor2_state = read_sensor(HALL_SENSOR_2);

        // Log the sensor data
        log_data(sensor1_state, sensor2_state);

        // Check if both sensors are HIGH
        if (sensor1_state == 1 && sensor2_state == 1) {
            printf("Conveyor Halted!\n");
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("Conveyor monitoring stopped.\n");

    return 0;
}

