#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x2A
#define CTRL_REG1 0x2A
#define DATA_START_REG 0x01
#define DATA_LENGTH 6
#define TILT_THRESHOLD 45.0f
#define LOG_FILE "fall_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int init_accelerometer(int fd);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt(int16_t x, int16_t y, int16_t z);
int log_fall_event(int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Accelerometer initialization function
int init_accelerometer(int fd) {
    int who_am_i = i2c_read_reg(fd, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    // Place in standby mode
    if (i2c_write_reg(fd, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error setting standby mode\n");
        return -1;
    }

    // Set data rate to 100 Hz
    if (i2c_write_reg(fd, CTRL_REG1, 0x02) < 0) {
        fprintf(stderr, "Error setting data rate\n");
        return -1;
    }

    // Enable active mode
    if (i2c_write_reg(fd, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error setting active mode\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data function
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[DATA_LENGTH];
    if (i2c_read_block(fd, DATA_START_REG, data, DATA_LENGTH) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = ((int16_t)data[0] << 8 | data[1]) >> 4;
    *y = ((int16_t)data[2] << 8 | data[3]) >> 4;
    *z = ((int16_t)data[4] << 8 | data[5]) >> 4;

    return 0;
}

// Calculate tilt function
float calculate_tilt(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 8192.0f; // Assuming +/- 2g range
    float y_g = (float)y / 8192.0f;
    float z_g = (float)z / 8192.0f;

    float tilt_x = atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0f / M_PI;
    float tilt_y = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0f / M_PI;

    return fmax(fabs(tilt_x), fabs(tilt_y));
}

// Log fall event function
int log_fall_event(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    running = false;
    fprintf(stderr, "Caught signal %d, exiting...\n", sig);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
