    }

    // Initialize accelerometer
    if (init_accelerometer(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing accelerometer\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
