    }

    int16_t x, y, z;
    float tilt;

    // Main loop
    while (running) {
        // Read accelerometer data
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate tilt
            tilt = calculate_tilt(x, y, z);

            // Check for fall event
            if (tilt > TILT_THRESHOLD) {
                log_fall_event(x, y, z);
            }
