#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_CTRL_REG4 0x23
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration constants
#define OFFSET_X 0.0
#define OFFSET_Y 0.0
#define OFFSET_Z 0.0
#define SCALE_X 1.0
#define SCALE_Y 1.0
#define SCALE_Z 1.0

// Metal detection threshold (mG)
#define METAL_THRESHOLD 800.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int initialize_magnetometer();
magnetometer_data_t read_magnetometer_data();
float calculate_magnitude(magnetometer_data_t data);
void log_data(magnetometer_data_t data);
void metal_detection_alert(float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the LIS3MDL magnetometer
int initialize_magnetometer() {
    // Configure CTRL_REG1: 10 Hz data rate, continuous conversion mode
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG3: Continuous conversion mode
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG3\n");
        return -1;
    }

    // Configure CTRL_REG4: ±4 gauss full scale
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    // Read all six bytes at once
    if (i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes, convert to milliGauss, and apply calibration
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    data.x = (float)raw_x * 0.146 * SCALE_X + OFFSET_X;
    data.y = (float)raw_y * 0.146 * SCALE_Y + OFFSET_Y;
    data.z = (float)raw_z * 0.146 * SCALE_Z + OFFSET_Z;

    return data;
}

// Function to calculate the magnitude of the magnetic field
float calculate_magnitude(magnetometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to log data to a file
void log_data(magnetometer_data_t data) {
    fprintf(log_file, "%.3f,%.3f,%.3f\n", data.x, data.y, data.z);
    fflush(log_file);
}

// Function to handle metal detection alert
void metal_detection_alert(float magnitude) {
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detected! Magnitude: %.3f mG\n", magnitude);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LIS3MDL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize magnetometer with retries
    int init_attempts = 0;
    while (initialize_magnetometer() != 0 && init_attempts < 3) {
        fprintf(stderr, "Magnetometer initialization failed, retrying...\n");
        init_attempts++;
        gpioDelay(1000); // Wait 1 second before retrying
    }

    if (init_attempts >= 3) {
        fprintf(stderr, "Magnetometer initialization failed after multiple attempts\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t data = read_magnetometer_data();

        // Calculate magnitude
        float magnitude = calculate_magnitude(data);

        // Log data
        log_data(data);

        // Check for metal detection
        metal_detection_alert(magnitude);

        // Delay to achieve 10 Hz sampling rate
        gpioDelay(100); // 100 ms delay
    }

    // Close log file and I2C bus
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

