// ADXL354B Register Addresses
#define ADXL354B_RESET_REG 0x00
#define ADXL354B_POWER_CTL_REG 0x2D
#define ADXL354B_STATUS_REG 0x04
#define ADXL354B_PARTID_REG 0x02
#define ADXL354B_XDATA_L 0x08
#define ADXL354B_XDATA_M 0x09
#define ADXL354B_XDATA_H 0x0A
#define ADXL354B_YDATA_L 0x0B
#define ADXL354B_YDATA_M 0x0C
#define ADXL354B_YDATA_H 0x0D
#define ADXL354B_ZDATA_L 0x0E
#define ADXL354B_ZDATA_M 0x0F
#define ADXL354B_ZDATA_H 0x10

// ADXL354B Reset Value
#define ADXL354B_RESET_VALUE 0x52

// ADXL354B Part ID
#define ADXL354B_PARTID 0xAD

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg, uint8_t data);
int adxl354b_reset(int handle);
int adxl354b_verify_partid(int handle);
int adxl354b_read_acceleration(int handle, int32_t *x, int32_t *y, int32_t *z);
void log_data(FILE *fp, int32_t x, int32_t y, int32_t z);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];
    tx_buf[0] = reg | 0x80; // Set MSB for read
    memset(tx_buf + 1, 0, len); // Fill with dummy data for reading

    int result = spiXfer(handle, tx_buf, rx_buf, len + 1);
    if (result != len + 1) {
