#include <unistd.h>
#include <pigpio.h>

// ADIS16362 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCEL_OUT 0x0A
#define Y_ACCEL_OUT 0x0C
#define Z_ACCEL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05f
#define ACCEL_SCALE 0.0025f

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_MODE 3

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float x_gyro;
    float y_gyro;
    float z_gyro;
    float x_accel;
    float y_accel;
    float z_accel;
} imu_data_t;

// Function prototypes
int spi_init();
int spi_read_register(uint8_t address, int16_t *data);
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from a specific register
int spi_read_register(uint8_t address, int16_t *data) {
    char tx_buffer[2];
    char rx_buffer[2];

    tx_buffer[0] = address | 0x80; // Set MSB for read operation
    tx_buffer[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    *data = (rx_buffer[0] << 8) | rx_buffer[1];
    return 0;
}

// Read IMU data from all registers
imu_data_t read_imu_data() {
    imu_data_t data;
    int16_t raw_data;

    if (spi_read_register(X_GYRO_OUT, &raw_data) == 0) {
        data.x_gyro = (float)raw_data * GYRO_SCALE;
    } else {
        data.x_gyro = 0.0f; // Set to 0 on error
    }

    if (spi_read_register(Y_GYRO_OUT, &raw_data) == 0) {
        data.y_gyro = (float)raw_data * GYRO_SCALE;
    } else {
        data.y_gyro = 0.0f; // Set to 0 on error
    }

    if (spi_read_register(Z_GYRO_OUT, &raw_data) == 0) {
        data.z_gyro = (float)raw_data * GYRO_SCALE;
    } else {
        data.z_gyro = 0.0f; // Set to 0 on error
    }

    if (spi_read_register(X_ACCEL_OUT, &raw_data) == 0) {
        data.x_accel = (float)raw_data * ACCEL_SCALE;
    } else {
        data.x_accel = 0.0f; // Set to 0 on error
    }

    if (spi_read_register(Y_ACCEL_OUT, &raw_data) == 0) {
        data.y_accel = (float)raw_data * ACCEL_SCALE;
    } else {
        data.y_accel = 0.0f; // Set to 0 on error
    }

    if (spi_read_register(Z_ACCEL_OUT, &raw_data) == 0) {
        data.z_accel = (float)raw_data * ACCEL_SCALE;
    } else {
        data.z_accel = 0.0f; // Set to 0 on error
    }

    return data;
}

// Log data to CSV file
void log_data(imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            ts.tv_sec, ts.tv_nsec,
            data.x_gyro, data.y_gyro, data.z_gyro,
            data.x_accel, data.y_accel, data.z_accel);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources before exiting
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        imu_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(10000); // 10ms delay (100Hz sampling rate)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

