#include <string.h>

// Define the GPIO pin connected to the sensor
#define SENSOR_PIN 17

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

