void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Function to simulate the self-parking sequence
void self_parking_sequence() {
    log_message("Self-parking sequence started");
    // Simulate the parking routine (e.g., 5 seconds)
    gpioDelay(5000000); // 5 seconds
    log_message("Self-parking sequence completed");
}

