#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// ADIS16266 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Scale factor
#define SCALE_FACTOR 0.02

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_gyro_data(int reg_addr, int *data);
void log_data(int x, int y, int z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read gyroscope data from ADIS16266
int read_gyro_data(int reg_addr, int *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer: address byte (MSB set) + two dummy bytes
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    // Perform the SPI transfer
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract the data from the receive buffer
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0; // Indicate success
}

// Function to log the gyroscope data
void log_data(int x, int y, int z) {
    printf("X: %.2f deg/sec, Y: %.2f deg/sec, Z: %.2f deg/sec\n",
           x * SCALE_FACTOR, y * SCALE_FACTOR, z * SCALE_FACTOR);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int x_data, y_data, z_data;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(XGYRO_OUT, &x_data) != 0) {
            fprintf(stderr, "Error reading X gyro data\n");
        }
        if (read_gyro_data(YGYRO_OUT, &y_data) != 0) {
            fprintf(stderr, "Error reading Y gyro data\n");
        }
        if (read_gyro_data(ZGYRO_OUT, &z_data) != 0) {
            fprintf(stderr, "Error reading Z gyro data\n");
        }

        // Log the data
        log_data(x_data, y_data, z_data);

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

