#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1F

// FXOS8700 register addresses
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_DATA_START 0x01

// Expected WHO_AM_I value
#define FXOS8700_WHO_AM_I_VALUE 0xC7

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a register with retry
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, reg, (char *)value, 1);
        if (result == 1) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X), retrying...\n", reg);
            gpioDelay(1000); // 1 ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X)\n", reg);
    return -1; // Failure
}

// Function to write a register with retry
int write_register(int handle, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteI2CBlockData(handle, reg, (char *)&value, 1);
        if (result == 1) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X), retrying...\n", reg, value);
            gpioDelay(1000); // 1 ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X)\n", reg, value);
    return -1; // Failure
}

// Function to initialize the FXOS8700
int init_fxos8700(int handle) {
    uint8_t who_am_i;

    // Verify device ID
    if (read_register(handle, FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != FXOS8700_WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, FXOS8700_WHO_AM_I_VALUE);
        return -1;
    }

    // Set accelerometer range to +/- 2g
    if (write_register(handle, FXOS8700_XYZ_DATA_CFG, 0x00) != 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG register\n");
        return -1;
    }

    // Set to active mode, 100 Hz data rate
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x01) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 register\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char data[12];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, FXOS8700_DATA_START, data, 12);
        if (result == 12) {
            // Extract accelerometer data (14-bit left-aligned)
            *accel_x = ((int16_t)data[0] << 2) | ((data[1] >> 6) & 0x03);
            *accel_y = ((int16_t)data[2] << 2) | ((data[3] >> 6) & 0x03);
            *accel_z = ((int16_t)data[4] << 2) | ((data[5] >> 6) & 0x03);

            // Extract magnetometer data (16-bit)
            *mag_x = (int16_t)((data[6] << 8) | data[7]);
            *mag_y = (int16_t)((data[8] << 8) | data[9]);
            *mag_z = (int16_t)((data[10] << 8) | data[11]);

            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (data block), retrying...\n");
            gpioDelay(1000); // 1 ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (data block)\n");
    return -1; // Failure
}

