#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <stdbool.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "access_log.txt"

// Define security code range
#define MIN_CODE 100000
#define MAX_CODE 999999

// Define unlock duration (seconds)
#define UNLOCK_DURATION 5

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *door_a_line;
static struct gpiod_line *door_b_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int generate_security_code();
int read_user_input(char *input_buffer, size_t buffer_size);
bool validate_input(const char *input);
bool compare_codes(int generated_code, const char *user_input);
int log_access(int code);
int unlock_door(int door_pin);
void lock_doors();
void signal_handler(int sig);
int setup_gpio();
void cleanup_gpio();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to generate a random six-digit security code
int generate_security_code() {
    return (rand() % (MAX_CODE - MIN_CODE + 1)) + MIN_CODE;
}

// Function to read user input from stdin
int read_user_input(char *input_buffer, size_t buffer_size) {
    if (fgets(input_buffer, buffer_size, stdin) == NULL) {
        fprintf(stderr, "Error reading input: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to validate user input (check if it's a number)
bool validate_input(const char *input) {
    for (size_t i = 0; i < strlen(input); i++) {
        if (input[i] < '0' || input[i] > '9') {
            return false;
        }
    }
    return true;
}

// Function to compare the generated code with the user input
bool compare_codes(int generated_code, const char *user_input) {
    int user_code = atoi(user_input);
    return (generated_code == user_code);
}

// Function to log access to a file
int log_access(int code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d\n", timestamp, code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to unlock a door
int unlock_door(int door_pin) {
    struct gpiod_line *line;
    if (door_pin == DOOR_A_PIN) {
        line = door_a_line;
    } else if (door_pin == DOOR_B_PIN) {
        line = door_b_line;
    } else {
        fprintf(stderr, "Error: Invalid door pin: %d\n", door_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", door_pin, strerror(errno));
        return -1;
    }

    sleep(UNLOCK_DURATION);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", door_pin, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to lock both doors
void lock_doors() {
    if (gpiod_line_set_value(door_a_line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", DOOR_A_PIN, strerror(errno));
    }
    if (gpiod_line_set_value(door_b_line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", DOOR_B_PIN, strerror(errno));
    }
}

// Function to setup GPIO lines
int setup_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_A_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_B_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        return -1;
    }

    if (gpiod_line_request_output(door_a_line, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", DOOR_A_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        return -1;
    }

    if (gpiod_line_request_output(door_b_line, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", DOOR_B_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio() {
    if (chip) {
        if (door_a_line) {
            gpiod_line_release(door_a_line);
        }
        if (door_b_line) {
            gpiod_line_release(door_b_line);
        }
        gpiod_chip_close(chip);
    }
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Generate security code
        int security_code = generate_security_code();
        printf("Security Code: %d\n", security_code);

        // Read user input
        char user_input[7]; // Allow for 6 digits + null terminator
        if (read_user_input(user_input, sizeof(user_input)) < 0) {
            continue; // Skip to the next iteration if input fails
        }

        // Validate input
        if (!validate_input(user_input)) {
            fprintf(stderr, "Invalid input. Please enter a six-digit number.\n");
            continue; // Skip to the next iteration if input is invalid
        }

        // Compare codes
        if (compare_codes(security_code, user_input)) {
            printf("Access granted!\n");

            // Log access
            if (log_access(security_code) < 0) {
                fprintf(stderr, "Failed to log access.\n");
            }

            // Unlock door A
            if (unlock_door(DOOR_A_PIN) < 0) {
                fprintf(stderr, "Failed to unlock door A.\n");
            }

            // Unlock door B
            if (unlock_door(DOOR_B_PIN) < 0) {
                fprintf(stderr, "Failed to unlock door B.\n");
            }

        } else {
            printf("Access denied\n");
        }
    }

    // Lock doors before exiting
    lock_doors();

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Cleanup GPIO
    cleanup_gpio();

    return EXIT_SUCCESS;
}

