#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define LUX_CONVERSION_FACTOR 1.2
#define LOG_FILE "light_log.txt"
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_bh1750(float *lux_value);
int log_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illuminance from BH1750 sensor
int read_bh1750(float *lux_value) {
    char config_mode = CONTINUOUS_HIGH_RES_MODE;
    char buffer[2];
    int result;

    result = i2cWriteByteData(i2c_handle, 0x00, config_mode); // Send configuration command
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(180); // Wait for conversion (180ms)

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2); // Read 2 bytes of data
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux_value = (float)raw_value / LUX_CONVERSION_FACTOR;

    return 0;
}

// Log data to file
int log_data(float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
    fclose(log_file);

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Light sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float lux_value;

        if (read_bh1750(&lux_value) == 0) {
            if (log_data(lux_value) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading light sensor data.\n");
        }

        sleep(SLEEP_DURATION);
    }

    // Cleanup and exit
    cleanup();
    printf("Light sensor logging stopped.\n");
    return 0;
}

