#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_PIN 18
#define PWM_FREQUENCY 4000
#define PWM_RANGE 1000000 // 1 MHz
#define TCP_PORT 12345
#define AUTH_MESSAGE "MOTION_DETECTED:MySecretKey"
#define SAMPLE_INTERVAL_MS 20
#define PLAYBACK_DURATION_S 5

// Global variables
int i2c_handle;
int tcp_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_data(int *touch_values);
int authenticate_message(const char *message);
int set_pwm_frequency(int frequency);
void log_frequency(int frequency);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (tcp_socket >= 0) {
        close(tcp_socket);
    }
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioSetMode(PWM_PIN, PI_INPUT); // Set pin to input to avoid spurious output
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        perror("Failed to reset MPR121");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set Electrode Configuration
        perror("Failed to configure MPR121 electrodes");
        return -1;
    }

    // Configure touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch threshold
            perror("Failed to set touch threshold");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release threshold
            perror("Failed to set release threshold");
            return -1;
        }
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) {
        perror("Failed to enable electrodes");
        return -1;
    }

    return 0;
}

// Read touch data from MPR121
int read_touch_data(int *touch_values) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        perror("Failed to read touch data");
        return -1;
    }

    int touch_status = (buf[1] << 8) | buf[0];
    for (int i = 0; i < 12; i++) {
        touch_values[i] = (touch_status >> i) & 1;
    }

    return 0;
}

// Authenticate message
int authenticate_message(const char *message) {
    return (strncmp(message, AUTH_MESSAGE, strlen(AUTH_MESSAGE)) == 0);
}

// Set PWM frequency
int set_pwm_frequency(int frequency) {
    // Map touch values to frequency range (e.g., 200Hz - 2000Hz)
    if (frequency < 200 || frequency > 2000) {
        fprintf(stderr, "Invalid frequency: %d\n", frequency);
        return -1;
    }

    // Calculate duty cycle (50%)
    int duty_cycle = (int)(((float)frequency / PWM_FREQUENCY) * PWM_RANGE / 2.0);

    gpioPWM(PWM_PIN, duty_cycle);
    return 0;
}

// Log frequency to file
void log_frequency(int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Frequency = %d Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM pin as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Open log file
    log_file = fopen("frequency_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create TCP socket
    tcp_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (tcp_socket < 0) {
        perror("Failed to create socket");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);

    if (bind(tcp_socket, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Failed to bind socket");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(tcp_socket, 1) < 0) {
        perror("Failed to listen on socket");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", TCP_PORT);

    // Main loop
    while (!terminate) {
        // Accept connection
        int client_socket = accept(tcp_socket, NULL, NULL);
        if (client_socket < 0) {
            perror("Failed to accept connection");
            continue; // Continue listening
        }

        printf("Connection accepted\n");

        // Read message from client
        char buffer[256];
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("Failed to receive data");
            close(client_socket);
            continue;
        }
        buffer[bytes_received] = '\0';

        printf("Received: %s\n", buffer);

        // Authenticate message
        if (authenticate_message(buffer)) {
            printf("Authentication successful\n");

            // Play tone
            int touch_values[12];
            for (int i = 0; i < (PLAYBACK_DURATION_S * 1000) / SAMPLE_INTERVAL_MS; i++) {
                if (read_touch_data(touch_values) < 0) {
                    fprintf(stderr, "Failed to read touch data during playback\n");
                    break;
                }

                // Calculate frequency based on touch values (example mapping)
                int frequency = 200; // Base frequency
                for (int j = 0; j < 12; j++) {
                    if (touch_values[j]) {
                        frequency += (j + 1) * 50; // Increment frequency based on electrode
                    }
                }

                if (set_pwm_frequency(frequency) < 0) {
                    fprintf(stderr, "Failed to set PWM frequency during playback\n");
                    break;
                }

                log_frequency(frequency);
                gpioDelay(SAMPLE_INTERVAL_MS); // Delay for sampling interval
            }

            gpioPWM(PWM_PIN, 0); // Stop PWM after playback
        } else {
            fprintf(stderr, "Authentication failed\n");
        }

        // Close client socket
        close(client_socket);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

