#include <pigpio.h>
#include <string.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define LSM303_OUT_X_L_M 0x08
#define LSM303_OUT_X_H_M 0x09
#define LSM303_OUT_Y_L_M 0x0A
#define LSM303_OUT_Y_H_M 0x0B
#define LSM303_OUT_Z_L_M 0x0C
#define LSM303_OUT_Z_H_M 0x0D

// GPIO pin for LED
#define LED_PIN 17

// I2C bus
#define I2C_BUS 1

// PWM frequency
#define PWM_FREQUENCY 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int init_i2c();
magnetometer_data_t read_magnetometer_data();
int16_t calculate_z_magnitude(magnetometer_data_t data);
void set_led_brightness(int16_t z_magnitude);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LSM303_OUT_X_L_M, buffer, 6) != 6) {
        log_error("Failed to read magnetometer data");
        data.x = 0; data.y = 0; data.z = 0; // Return default values on error
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calculate Z-axis magnitude
int16_t calculate_z_magnitude(magnetometer_data_t data) {
    return data.z;
}

// Set LED brightness using PWM
void set_led_brightness(int16_t z_magnitude) {
    // Scale the Z-axis magnitude to the PWM range (0-1000000)
    int duty_cycle = (int)((float)z_magnitude / 32768.0 * 1000000.0); // Assuming max magnitude is 32767

    // Clamp the duty cycle to the valid range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 1000000) {
        duty_cycle = 1000000;
    }

    gpioPWM(LED_PIN, duty_cycle);
}

// Log errors to file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioPWM(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_PIN, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("magnetometer.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Magnetometer data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        magnetometer_data_t data = read_magnetometer_data();
        int16_t z_magnitude = calculate_z_magnitude(data);
        set_led_brightness(z_magnitude);
        gpioDelay(100); // Sample every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

