// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold running average data
typedef struct {
    int16_t x[100];
    int16_t y[100];
    int16_t z[100];
    int index;
} running_average_t;

// Function prototypes
int init_hmc5883l();
magnetometer_data_t read_magnetometer_data();
void update_running_average(running_average_t *avg, magnetometer_data_t data);
magnetometer_data_t calculate_offsets(running_average_t *avg);
magnetometer_data_t apply_offsets(magnetometer_data_t data, magnetometer_data_t offsets);
void print_data(magnetometer_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize HMC5883L
int init_hmc5883l() {
    // Configuration register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A: %s\n", strerror(errno));
        return -1;
    }

    // Configuration register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B: %s\n", strerror(errno));
        return -1;
    }

    // Mode register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data: %s\n", strerror(errno));
        data.x = 0; // Set to 0 to avoid garbage values
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Update running average
void update_running_average(running_average_t *avg, magnetometer_data_t data) {
    avg->x[avg->index] = data.x;
    avg->y[avg->index] = data.y;
    avg->z[avg->index] = data.z;
    avg->index = (avg->index + 1) % 100;
}

// Calculate offsets
magnetometer_data_t calculate_offsets(running_average_t *avg) {
    magnetometer_data_t offsets;
    long sum_x = 0, sum_y = 0, sum_z = 0;

    for (int i = 0; i < 100; i++) {
        sum_x += avg->x[i];
        sum_y += avg->y[i];
        sum_z += avg->z[i];
    }

    offsets.x = (int16_t)(sum_x / 100);
    offsets.y = (int16_t)(sum_y / 100);
    offsets.z = (int16_t)(sum_z / 100);

    return offsets;
}

// Apply offsets
magnetometer_data_t apply_offsets(magnetometer_data_t data, magnetometer_data_t offsets) {
    magnetometer_data_t corrected_data;
    corrected_data.x = data.x - offsets.x;
    corrected_data.y = data.y - offsets.y;
    corrected_data.z = data.z - offsets.z;
    return corrected_data;
}

// Print data
void print_data(magnetometer_data_t data) {
    printf("X: %d, Y: %d, Z: %d\n", data.x, data.y, data.z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    running_average_t running_avg = {{0}, {0}, {0}, 0};
    magnetometer_data_t offsets;
    magnetometer_data_t raw_data;
    magnetometer_data_t corrected_data;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        raw_data = read_magnetometer_data();

        // Update running average
        update_running_average(&running_avg, raw_data);

        // Calculate offsets after 10 seconds (20 * 500ms)
        if (running_avg.index == 0) {
            offsets = calculate_offsets(&running_avg);
            printf("Offsets calculated: X: %d, Y: %d, Z: %d\n", offsets.x, offsets.y, offsets.z);
        }

        // Apply offsets
        corrected_data = apply_offsets(raw_data, offsets);

        // Print data
        print_data(corrected_data);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

