#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1_A 0x20
#define INT1_CFG 0x30
#define INT1_THS_L 0x32
#define INT1_THS_H 0x33
#define INT1_DURATION 0x34
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// GPIO pin for INT1
#define INT1_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelData;

// Circular buffer
AccelData accel_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int init_lsm303d();
void read_acceleration(AccelData *data);
void dump_buffer();
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Global variable to track program state for signal handler
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize LSM303D
    if (init_lsm303d() != 0) {
        fprintf(stderr, "LSM303D initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set INT1 pin as input with pull-up resistor
    gpioSetMode(INT1_PIN, PI_INPUT);
    gpioSetPullUpDown(INT1_PIN, PI_PUD_UP);

    // Set interrupt handler for rising edge on INT1 pin
    if (gpioSetISRFuncEx(INT1_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set interrupt handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        AccelData data;
        read_acceleration(&data);
        gpioDelay(10); // 10ms delay
    }

    // Cleanup
    gpioTerminate();
    return 0;
}

// Initialize LSM303D
int init_lsm303d() {
    // Open I2C device
    i2c_handle = i2cOpen(1, LSM303D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return 1;
    }
    if (who_am_i != 0x49) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        return 1;
    }

    // Configure CTRL_REG1_A (100Hz, enable all axes)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1_A register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return 1;
    }

    // Configure INT1_CFG (enable interrupt on any axis)
    if (i2cWriteByteData(i2c_handle, INT1_CFG, 0x2A) < 0) {
        fprintf(stderr, "Failed to write INT1_CFG register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return 1;
    }

    // Configure INT1_THS_L and INT1_THS_H (2000mg threshold)
    uint16_t threshold = 2000 / 0.061; // Convert mg to LSB
    if (i2cWriteByteData(i2c_handle, INT1_THS_L, threshold & 0xFF) < 0) {
        fprintf(stderr, "Failed to write INT1_THS_L register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, INT1_THS_H, (threshold >> 8) & 0xFF) < 0) {
        fprintf(stderr, "Failed to write INT1_THS_H register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return 1;
    }

    // Configure INT1_DURATION (0ms duration)
    if (i2cWriteByteData(i2c_handle, INT1_DURATION, 0x00) < 0) {
        fprintf(stderr, "Failed to write INT1_DURATION register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read acceleration data from LSM303D
void read_acceleration(AccelData *data) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read acceleration data: %s\n", strerror(errno));
        return;
    }

    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Store data in circular buffer
    accel_buffer[buffer_index] = *data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Dump the last 10 samples from the circular buffer
void dump_buffer() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: ", timestamp);
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("(%d, %d, %d) ", accel_buffer[index].x, accel_buffer[index].y, accel_buffer[index].z);
    }
    printf("\n");
}

