    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Store data in circular buffer
    accel_buffer[buffer_index] = *data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Dump the last 10 samples from the circular buffer
void dump_buffer() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: ", timestamp);
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("(%d, %d, %d) ", accel_buffer[index].x, accel_buffer[index].y, accel_buffer[index].z);
    }
    printf("\n");
}

// Interrupt handler
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    dump_buffer();
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;

    // Disable accelerometer
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x00) < 0) {
        fprintf(stderr, "Failed to disable accelerometer: %s\n", strerror(errno));
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

