// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Global variable to track the currently active solenoid
int active_solenoid = 0; // 0: none, 1: solenoid 1, 2: solenoid 2

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    // Deactivate both solenoids
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    // Ensure both solenoids are initially off
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Activate solenoid 1
        gpioWrite(SOLENOID_1_PIN, 1);
        gpioWrite(SOLENOID_2_PIN, 0);
        active_solenoid = 1;

        // Delay for 500ms
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&delay, NULL);

        // Activate solenoid 2
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 1);
        active_solenoid = 2;

        // Delay for 500ms
        delay.tv_sec = 0;
        delay.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&delay, NULL);
    }

    return 0;
}

