#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 27

// Define UART devices
#define UART0_DEVICE "/dev/serial0"
#define UART1_DEVICE "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define timeout in seconds
#define TIMEOUT_SEC 5

// Define the expected code
#define EXPECTED_CODE "123456"

// Define the code length
#define CODE_LENGTH 6

// Global variables for UART file descriptors
int uart0_fd = -1;
int uart1_fd = -1;

// Function prototypes
int initialize_uart(const char *device);
int read_code(int fd, char *code, size_t code_len);
int constant_time_compare(const char *a, const char *b, size_t len);
void activate_relay(int gpio);
void deactivate_relay(int gpio);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Cleaning up and exiting.\n", signal);

    // Deactivate relays
    deactivate_relay(RELAY1_GPIO);
    deactivate_relay(RELAY2_GPIO);

    // Close UART ports
    if (uart0_fd != -1) {
        close(uart0_fd);
    }
    if (uart1_fd != -1) {
        close(uart1_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize a UART port
int initialize_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes for %s: %s\n", device, strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 9600 baud, 8N1, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = TIMEOUT_SEC * 10; // Timeout in deciseconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes for %s: %s\n", device, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a 6-digit code from a UART port
int read_code(int fd, char *code, size_t code_len) {
    char buffer[1];
    size_t i = 0;

    while (i < code_len) {
        ssize_t bytes_read = read(fd, buffer, 1);
        if (bytes_read > 0) {
            if (buffer[0] >= '0' && buffer[0] <= '9') {
                code[i++] = buffer[0];
            } else {
                // Reset the code buffer on any non-digit character
                memset(code, 0, code_len);
                i = 0;
            }
        } else if (bytes_read < 0) {
            if (errno != EAGAIN && errno != EWOULDBLOCK) {
                fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
                return -1; // Indicate an error
            } else {
                // Timeout occurred, return 0 to indicate no code read
                return 0;
            }
        } else {
            // Timeout occurred, return 0 to indicate no code read
            return 0;
        }
    }

    code[code_len] = '\0'; // Null-terminate the code
    return 1; // Indicate a code was read successfully
}

// Function to perform a constant-time string comparison
int constant_time_compare(const char *a, const char *b, size_t len) {
    unsigned int result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return (result == 0);
}

// Function to activate a relay
void activate_relay(int gpio) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", gpio, strerror(errno));
    }
}

// Function to deactivate a relay
void deactivate_relay(int gpio) {
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", gpio, strerror(errno));
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);

    // Initialize UART ports
    uart0_fd = initialize_uart(UART0_DEVICE);
    if (uart0_fd == -1) {
        gpioTerminate();
        return 1;
    }

    uart1_fd = initialize_uart(UART1_DEVICE);
    if (uart1_fd == -1) {
        close(uart0_fd);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char code0[CODE_LENGTH + 1] = {0}; // +1 for null terminator
    char code1[CODE_LENGTH + 1] = {0};

    // Main loop
    while (1) {
        // Read codes from UART ports
        int result0 = read_code(uart0_fd, code0, CODE_LENGTH);
        int result1 = read_code(uart1_fd, code1, CODE_LENGTH);

        if (result0 < 0 || result1 < 0) {
            // Error occurred during read, exit the loop
            break;
        }

        // Check if both codes are valid and match the expected code
        if (result0 == 1 && result1 == 1) {
            if (constant_time_compare(code0, EXPECTED_CODE, CODE_LENGTH) &&
                constant_time_compare(code1, EXPECTED_CODE, CODE_LENGTH)) {
                // Activate relays
                activate_relay(RELAY1_GPIO);
                activate_relay(RELAY2_GPIO);

                // Wait for 2 seconds
                gpioDelay(2000000); // 2 seconds in microseconds

                // Deactivate relays
                deactivate_relay(RELAY1_GPIO);
                deactivate_relay(RELAY2_GPIO);

                // Reset code buffers
                memset(code0, 0, sizeof(code0));
                memset(code1, 0, sizeof(code1));
            }
        }

        // Small delay to prevent busy-waiting
        usleep(10000); // 10 milliseconds
    }

    // Cleanup (in case of error)
    signal_handler(0); // Call signal handler to perform cleanup

    return 0;
}

