                gpioDelay(RELAY_ON_TIME * 1000); // Keep relay on for 1 second
                deactivate_relay();
            }
        } else {
            // No motion detected
            motion_start_time = 0; // Reset motion start time
        }

        gpioDelay(POLL_INTERVAL); // Poll every 50ms
    }

    cleanup(); // Clean up before exiting

    return 0;
}

