#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define constants for irrigation cycle
#define RELAY_ON_TIME 300 // seconds
#define RELAY_OFF_TIME 60  // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int current_relay = 1; // Start with relay 1

// Function prototypes
void signal_handler(int signal);
void timer_callback(void *userdata);
int initialize_gpio(void);
void cleanup_gpio(void);
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

// Timer callback function
void timer_callback(void *userdata) {
    static int state = 0; // 0: off, 1: on
    static time_t start_time = 0;

    time_t current_time = time(NULL);

    switch (state) {
        case 0: // Relay is off, turn it on
            activate_relay(current_relay);
            start_time = current_time;
            state = 1;
            break;
        case 1: // Relay is on, turn it off
            deactivate_relay(current_relay);
            start_time = current_time;
            state = 0;

            // Move to the next relay
            current_relay++;
            if (current_relay > 4) {
                current_relay = 1;
            }
            break;
    }
}

// Initialize GPIO pins
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1; // Indicate failure
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0; // Indicate success
}

// Cleanup GPIO pins
void cleanup_gpio(void) {
    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    gpioTerminate();
}

// Activate a relay
void activate_relay(int relay_number) {
    int pin;
    char message[100];

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            log_message(LOG_ERR, "Invalid relay number");
            return;
    }

    gpioWrite(pin, 0); // Activate relay (LOW)
    snprintf(message, sizeof(message), "Relay %d activated", relay_number);
    log_message(LOG_INFO, message);
}

// Deactivate a relay
void deactivate_relay(int relay_number) {
    int pin;
    char message[100];

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            log_message(LOG_ERR, "Invalid relay number");
            return;
    }

    gpioWrite(pin, 1); // Deactivate relay (HIGH)
    snprintf(message, sizeof(message), "Relay %d deactivated", relay_number);
    log_message(LOG_INFO, message);
}

// Log a message to syslog
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_message_buffer[256];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "%s: %s", timestamp, message);
    syslog(priority, "%s", log_message_buffer);
}

int main() {
    // Open syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    // Set up timer
    gpioSetTimerFuncEx(0, 60, timer_callback, NULL); // Timer 0, every 60 seconds

    log_message(LOG_INFO, "Irrigation system started");

    // Main loop
    while (program_running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup
    cleanup_gpio();
    log_message(LOG_INFO, "Irrigation system stopped");
    closelog();

    return 0;
}

