#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/timerfd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/syslog.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define PWR_MGMT_1 0x6B
#define SAMPLE_RATE 100 // Hz
#define BUFFER_SIZE 100
#define SYSFS_PATH "/sys/kernel/mpu6050_accel/latest"

// Data structure for accelerometer readings
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_data_t;

// Circular buffer structure
typedef struct {
    accel_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd = -1;
int timer_fd = -1;
circular_buffer_t accel_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
void buffer_init(circular_buffer_t *buffer);
void buffer_add(circular_buffer_t *buffer, accel_data_t data);
accel_data_t buffer_get_latest(circular_buffer_t *buffer);
void timer_handler(union sigval sv);
void signal_handler(int sig);
int create_sysfs_file();
int write_to_sysfs(accel_data_t data);
int remove_sysfs_file();

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Circular buffer initialization
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Circular buffer add function
void buffer_add(circular_buffer_t *buffer, accel_data_t data) {
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Circular buffer get latest function
accel_data_t buffer_get_latest(circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        accel_data_t empty = {0, 0, 0};
        return empty;
    }
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->buffer[index];
}

// Timer handler function
void timer_handler(union sigval sv) {
    accel_data_t data;
    int16_t x, y, z;

    x = i2c_read_word(i2c_fd, ACCEL_XOUT_H);
    y = i2c_read_word(i2c_fd, ACCEL_XOUT_H + 2);
    z = i2c_read_word(i2c_fd, ACCEL_XOUT_H + 4);

    if (x == -1 || y == -1 || z == -1) {
        syslog(LOG_ERR, "Failed to read accelerometer data");
        return;
    }

    data.x = x;
    data.y = y;
    data.z = z;

    buffer_add(&accel_buffer, data);
    write_to_sysfs(data);
}

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, terminating...", sig);
    terminate = 1;
}

// Create sysfs file
int create_sysfs_file() {
    int fd;
    struct stat st;

    if (stat(SYSFS_PATH, &st) == -1) {
        fd = open(SYSFS_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0666);
        if (fd == -1) {
            syslog(LOG_ERR, "Failed to create sysfs file: %s", strerror(errno));
            return -1;
        }
        close(fd);
    }
    return 0;
}

// Write to sysfs file
int write_to_sysfs(accel_data_t data) {
    int fd;
    char buffer[100];

    fd = open(SYSFS_PATH, O_WRONLY);
    if (fd == -1) {
        syslog(LOG_ERR, "Failed to open sysfs file: %s", strerror(errno));
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%d,%d,%d", data.x, data.y, data.z);
    if (write(fd, buffer, strlen(buffer)) == -1) {
        syslog(LOG_ERR, "Failed to write to sysfs file: %s", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Remove sysfs file
int remove_sysfs_file() {
    if (unlink(SYSFS_PATH) == -1) {
        syslog(LOG_ERR, "Failed to remove sysfs file: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize syslog
    openlog("mpu6050_accel", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize circular buffer
    buffer_init(&accel_buffer);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) == -1) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
