#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define prime number intervals for each relay (in seconds)
#define RELAY1_INTERVAL 2
#define RELAY2_INTERVAL 3
#define RELAY3_INTERVAL 5
#define RELAY4_INTERVAL 7

// Global variables to store the last toggle times for each relay
static volatile struct timespec lastToggleTime1, lastToggleTime2, lastToggleTime3, lastToggleTime4;

// Function prototypes
int initializeGPIO();
void toggleRelay(int pin, int interval, struct timespec *lastToggleTime);
void cleanupGPIO();
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanupGPIO();
    exit(0);
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initializeGPIO() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY3_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY4_PIN);
        gpioTerminate();
        return 1;
    }

    // Initialize last toggle times
    clock_gettime(CLOCK_MONOTONIC, &lastToggleTime1);
    clock_gettime(CLOCK_MONOTONIC, &lastToggleTime2);
    clock_gettime(CLOCK_MONOTONIC, &lastToggleTime3);
    clock_gettime(CLOCK_MONOTONIC, &lastToggleTime4);

    return 0; // Indicate success
}

// Function to toggle a relay based on the specified interval
void toggleRelay(int pin, int interval, struct timespec *lastToggleTime) {
    struct timespec currentTime;
    clock_gettime(CLOCK_MONOTONIC, &currentTime);

    // Calculate the time difference in seconds
    double timeDiff = (currentTime.tv_sec - lastToggleTime->tv_sec) +
                      (currentTime.tv_nsec - lastToggleTime->tv_nsec) / 1000000000.0;

    // Check if the interval has passed
    if (timeDiff >= interval) {
        // Toggle the relay state
        int currentState = gpioRead(pin);
        gpioWrite(pin, !currentState);

        // Update the last toggle time
        *lastToggleTime = currentTime;
    }
}

// Function to cleanup the pigpio library and set all relays to OFF
void cleanupGPIO() {
    // Turn off all relays
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Initialize GPIO
    if (initializeGPIO() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Toggle each relay
        toggleRelay(RELAY1_PIN, RELAY1_INTERVAL, &lastToggleTime1);
        toggleRelay(RELAY2_PIN, RELAY2_INTERVAL, &lastToggleTime2);
        toggleRelay(RELAY3_PIN, RELAY3_INTERVAL, &lastToggleTime3);
        toggleRelay(RELAY4_PIN, RELAY4_INTERVAL, &lastToggleTime4);

        // Sleep for a short interval to avoid busy-waiting
        gpioDelay(100); // Sleep for 100 milliseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

