// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define RELAY_ACTIVATION_TIME 3 // seconds
#define DEBOUNCE_TIME 1 // seconds

// Global variables
static volatile int running = 1;
static volatile time_t last_activation_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int activate_relay();
int log_event();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay
int activate_relay() {
    time_t now = time(NULL);
    if (difftime(now, last_activation_time) < DEBOUNCE_TIME) {
        printf("Debounce active, skipping relay activation.\n");
        return 0; // Skip activation
    }

    printf("Activating relay.\n");
    gpioWrite(RELAY_PIN, 1); // Turn relay on
    gpioDelay(RELAY_ACTIVATION_TIME * 1000000); // Wait for 3 seconds
    gpioWrite(RELAY_PIN, 0); // Turn relay off
    last_activation_time = now;
    return 0;
}

// Log the event to a file
int log_event() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: Sound event detected and relay activated.\n", timestamp);
    fclose(fp);
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up GPIO.\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_sound_sensor() == 1) {
            printf("Sound detected!\n");
            activate_relay();
            log_event();
        }
        gpioDelay(100000); // 100ms delay
    }

    return 0;
}

