#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor for gyroscope (±250°/s range)
#define GYRO_SCALE 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c(int address);
int read_gyro_data(int fd, float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void add_to_buffer(float x, float y, float z);
void check_threshold(float magnitude);
void signal_handler(int signal);

// Callback function (example)
void threshold_exceeded_callback(float magnitude) {
    printf("Threshold exceeded! Magnitude: %.2f deg/s\n", magnitude);
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep mode bit)
    uint8_t wake_up_data = 0x00;
    if (write(fd, &wake_up_data, 1) != 1) {
        perror("Error writing to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buffer[6];
    int16_t gyro_x, gyro_y, gyro_z;

    // Read 6 bytes of gyroscope data (X, Y, Z)
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine high and low bytes for each axis
    gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees per second
    *x = (float)gyro_x / GYRO_SCALE;
    *y = (float)gyro_y / GYRO_SCALE;
    *z = (float)gyro_z / GYRO_SCALE;

    return 0;
}

// Calculate the magnitude of the angular velocity vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Add data to the circular buffer
void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check if the magnitude exceeds the threshold
void check_threshold(float magnitude) {
    if (magnitude > 50.0) {
        threshold_exceeded_callback(magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    close(i2c_fd);
    exit(0);
}

int main() {
    float gyro_x, gyro_y, gyro_z;
    float magnitude;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(gyro_x, gyro_y, gyro_z);

            // Add data to buffer
            add_to_buffer(gyro_x, gyro_y, gyro_z);

            // Check threshold
            check_threshold(magnitude);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying.\n");
            // Attempt to re-initialize I2C
            close(i2c_fd);
            i2c_fd = init_i2c(MPU6050_ADDR);
            if (i2c_fd < 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                program_running = 0; // Exit loop if re-initialization fails
            }
        }

        // Delay for a short period
        usleep(10000); // 10ms
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

