#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/ioctl.h>

// Define constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B9600
#define RESPONSE_LENGTH 9
#define SAMPLE_INTERVAL 5 // seconds
#define TIMEOUT 1 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;
FILE *error_file = NULL;

// Structure to hold sensor data
typedef struct {
    long long timestamp;
    int ppm;
    int error_flag;
} sensor_data_t;

// Function prototypes
int init_uart(const char *device, speed_t baud_rate);
int read_sensor_data(int fd, unsigned char *data);
int validate_checksum(const unsigned char *data);
int parse_co2_data(const unsigned char *data, int *ppm);
int log_data(FILE *fp, const sensor_data_t *data);
int log_error(FILE *fp, const char *message);
void signal_handler(int signal);
void close_resources();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Initialize UART
int init_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 10; // 1 second timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data with timeout and retry
int read_sensor_data(int fd, unsigned char *data) {
    fd_set readfds;
    struct timeval timeout;
    int bytes_read = 0;
    unsigned char buffer[1];

    while (bytes_read < RESPONSE_LENGTH && program_running) {
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        timeout.tv_sec = TIMEOUT;
        timeout.tv_usec = 0;

        int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

        if (retval == -1) {
            perror("select() error");
            return -1;
        } else if (retval == 0) {
            fprintf(stderr, "Timeout reading from UART\n");
            return -1; // Timeout
        } else {
            if (read(fd, buffer, 1) == 1) {
                data[bytes_read++] = buffer[0];
            } else {
                perror("Error reading from UART");
                return -1;
            }
        }
    }

    return bytes_read;
}

// Validate checksum
int validate_checksum(const unsigned char *data) {
    unsigned char checksum = 0;
    for (int i = 1; i < RESPONSE_LENGTH - 1; i++) {
        checksum += data[i];
    }
    checksum = 0xFF - checksum + 1;

    if (checksum != data[RESPONSE_LENGTH - 1]) {
        fprintf(stderr, "Checksum mismatch: calculated 0x%02X, received 0x%02X\n", checksum, data[RESPONSE_LENGTH - 1]);
        return -1;
    }

    return 0;
}

// Parse CO2 data
int parse_co2_data(const unsigned char *data, int *ppm) {
    if (data[0] != 0xFF || data[1] != 0x86) {
        fprintf(stderr, "Invalid response header: 0x%02X 0x%02X\n", data[0], data[1]);
        return -1;
    }

    *ppm = (data[2] << 8) | data[3];
    return 0;
}

// Log data to file
int log_data(FILE *fp, const sensor_data_t *data) {
    if (fp == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(fp, "{\"timestamp\": %lld, \"ppm\": %d, \"error_flag\": %d}\n", data->timestamp, data->ppm, data->error_flag);
    fflush(fp);
    return 0;
}

// Log error to file
int log_error(FILE *fp, const char *message) {
    if (fp == NULL) {
        fprintf(stderr, "Error: Error log file is not open\n");
        return -1;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fflush(fp);
    return 0;
}

// Close resources
void close_resources() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    // Open log files
    log_file = fopen("co2_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening co2_log.json");
        close_resources();
        return EXIT_FAILURE;
    }

    error_file = fopen("co2_error.log", "a");
    if (error_file == NULL) {
        perror("Error opening co2_error.log");
        close_resources();
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        unsigned char response[RESPONSE_LENGTH];
        int ppm = 0;
        int error_flag = 0;
        sensor_data_t sensor_data;

        // Send command to sensor
        unsigned char command[9] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
        if (write(uart_fd, command, 9) != 9) {
            perror("Error writing to UART");
            log_error(error_file, "Error writing to UART");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Read sensor data
        int bytes_read = read_sensor_data(uart_fd, response);
        if (bytes_read != RESPONSE_LENGTH) {
            fprintf(stderr, "Error reading sensor data: %d bytes read\n", bytes_read);
            log_error(error_file, "Error reading sensor data");
            error_flag = 1;
        } else {
            // Validate checksum
            if (validate_checksum(response) != 0) {
                fprintf(stderr, "Checksum validation failed\n");
                log_error(error_file, "Checksum validation failed");
                error_flag = 1;
            } else {
                // Parse CO2 data
                if (parse_co2_data(response, &ppm) != 0) {
                    fprintf(stderr, "Error parsing CO2 data\n");
                    log_error(error_file, "Error parsing CO2 data");
                    error_flag = 1;
                }
            }
        }

        // Get timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        sensor_data.timestamp = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
        sensor_data.ppm = ppm;
        sensor_data.error_flag = error_flag;

        // Log data
        if (log_data(log_file, &sensor_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Print data to stdout
        printf("{\"timestamp\": %lld, \"ppm\": %d, \"error_flag\": %d}\n", sensor_data.timestamp, sensor_data.ppm, sensor_data.error_flag);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Close resources before exiting
    close_resources();

    return EXIT_SUCCESS;
}

