// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Hard iron compensation offsets
#define HARD_IRON_X_OFFSET 100
#define HARD_IRON_Y_OFFSET -50

// Target heading
#define TARGET_HEADING 90.0

// GPIO pin for output
#define GPIO_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_hmc5883l();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
float compensate_heading(float heading);
void add_to_buffer(CircularBuffer *cb, float value);
float get_latest_heading(CircularBuffer *cb);
void set_gpio_output(int state);
void signal_handler(int signal);
void init_circular_buffer(CircularBuffer *cb);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get the latest value from the circular buffer
float get_latest_heading(CircularBuffer *cb) {
    if (cb->count > 0) {
        int index = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
        return cb->buffer[index];
    } else {
        return 0.0; // Or some other default value
    }
}

// Initialize the HMC5883L
int init_hmc5883l() {
    // Configuration register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configuration register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Mode register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2((float)y, (float)x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Apply hard iron compensation
float compensate_heading(float heading) {
    return heading; // No compensation in this implementation
}

// Set GPIO output
void set_gpio_output(int state) {
    gpioWrite(GPIO_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer heading_buffer;
    init_circular_buffer(&heading_buffer);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading, compensated_heading;
    float latest_heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Calculate heading
            heading = calculate_heading(x, y);

            // Apply hard iron compensation
            compensated_heading = compensate_heading(heading);

            // Add to circular buffer
            add_to_buffer(&heading_buffer, compensated_heading);

            // Get the latest heading from the buffer
            latest_heading = get_latest_heading(&heading_buffer);

            // Check for deviation from target heading
            if (fabs(latest_heading - TARGET_HEADING) > 10.0) {
                set_gpio_output(1); // Set GPIO high
            } else {
                set_gpio_output(0); // Set GPIO low
            }

            printf("Heading: %.2f, Compensated Heading: %.2f, Latest Heading: %.2f\n", heading, compensated_heading, latest_heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        gpioDelay(100); // Sample at 100 ms interval
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Set GPIO low before exiting
    gpioTerminate();

    return 0;
}

