#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_MED 150
#define LUX_THRESHOLD_HIGH 300

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void control_relays(float lux);
int log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read BH1750 sensor
int read_bh1750(float *lux) {
    char config[1] = {CONTINUOUS_HIGH_RES_MODE};
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, config, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(120); // Wait 120ms

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Control RGB relays
void control_relays(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < LUX_THRESHOLD_LOW) {
        gpioWrite(RED_GPIO, 1); // Turn on RED
        red_state = 1;
    } else {
        gpioWrite(RED_GPIO, 0); // Turn off RED
    }

    if (lux >= LUX_THRESHOLD_LOW && lux < LUX_THRESHOLD_MED) {
        gpioWrite(GREEN_GPIO, 1); // Turn on GREEN
        green_state = 1;
    } else {
        gpioWrite(GREEN_GPIO, 0); // Turn off GREEN
    }

    if (lux >= LUX_THRESHOLD_MED && lux < LUX_THRESHOLD_HIGH) {
        gpioWrite(BLUE_GPIO, 1); // Turn on BLUE
        blue_state = 1;
    } else {
        gpioWrite(BLUE_GPIO, 0); // Turn off BLUE
    }

    if (lux >= LUX_THRESHOLD_HIGH) {
        gpioWrite(RED_GPIO, 1); // Turn on RED
        gpioWrite(GREEN_GPIO, 1); // Turn on GREEN
        gpioWrite(BLUE_GPIO, 1); // Turn on BLUE
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    log_data(lux, red_state, green_state, blue_state);
}

// Log data to file
int log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RED_GPIO, 0);
    gpioWrite(GREEN_GPIO, 0);
    gpioWrite(BLUE_GPIO, 0);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RED_GPIO, PI_OUTPUT);
    gpioSetMode(GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(BLUE_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;

    // Main loop
    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            control_relays(lux);
        } else {
            fprintf(stderr, "Error reading sensor, retrying...\n");
        }
        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

