#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define SERVO_GPIO 18
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD 2000000 // 20ms (50Hz)
#define PWM_DUTY_MIN 1000000 // 1ms
#define PWM_DUTY_MAX 2000000 // 2ms
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5

// Global variables
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int mpu6050_init(int fd);
int mpu6050_read_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll);
int set_servo_angle(int angle);
int log_data(float pitch, float roll, int angle);
void signal_handler(int sig);

// I2C read function with retry and exponential backoff
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 0;
    int delay_ms = 10;
    int result;

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            fprintf(stderr, "Error: Could not set I2C slave address: %s\n", strerror(errno));
            return -1;
        }

        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error: Could not write register address: %s\n", strerror(errno));
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }

    fprintf(stderr, "Error: I2C read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C write function with retry and exponential backoff
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    int retries = 0;
    int delay_ms = 10;
    uint8_t buf[2];
    int result;

    buf[0] = reg;
    buf[1] = data;

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            fprintf(stderr, "Error: Could not set I2C slave address: %s\n", strerror(errno));
            return -1;
        }

        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C write failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }

    fprintf(stderr, "Error: I2C write failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU6050 (clear sleep bit)
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }
    gpioDelay(10000); // Short delay after wake-up
    return 0;
}

// MPU6050 data reading function
int mpu6050_read_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[14];

    if (i2c_read_reg(fd, ACCEL_XOUT_H, buffer, 14) < 0) {
        fprintf(stderr, "Error: Could not read MPU6050 data\n");
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

// Pitch and roll calculation function
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll) {
    float accel_x_g = (float)accel_x / 16384.0; // Assuming sensitivity of +/- 2g
    float accel_y_g = (float)accel_y / 16384.0;
    float accel_z_g = (float)accel_z / 16384.0;

    *pitch = atan2(accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180 / M_PI;
