// I2C read function with retry and exponential backoff
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 0;
    int delay_ms = 10;
    int result;

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            fprintf(stderr, "Error: Could not set I2C slave address: %s\n", strerror(errno));
            return -1;
        }

        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error: Could not write register address: %s\n", strerror(errno));
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }

    fprintf(stderr, "Error: I2C read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

