#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Define the fade duration in seconds
#define FADE_DURATION 1800

// Define the PWM frequency in Hz
#define PWM_FREQUENCY 100

// Define the number of relays
#define NUM_RELAYS 4

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state; // 0 for off, 1 for on
} schedule_entry_t;

// Global variables
static volatile int running = 1;
static int current_states[NUM_RELAYS] = {0}; // 0 = off, 1 = on
static int target_states[NUM_RELAYS] = {0};  // 0 = off, 1 = on
static int fade_directions[NUM_RELAYS] = {0}; // -1 = fading down, 1 = fading up, 0 = no fade
static int duty_cycles[NUM_RELAYS] = {0};    // Current duty cycle for each relay

// Function prototypes
int read_schedule(const char *filename, schedule_entry_t *schedule, int *num_entries);
int parse_schedule_entry(const char *line, schedule_entry_t *entry);
int set_relay_state(int relay_number, int state);
void fade_relay(int relay_number, int target_state);
void signal_handler(int signal);
void cleanup();

// Function to read the schedule from a file
int read_schedule(const char *filename, schedule_entry_t *schedule, int *num_entries) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL && i < 100) { // Limit to 100 entries
        if (parse_schedule_entry(line, &schedule[i]) == 0) {
            i++;
        } else {
            fprintf(stderr, "Error parsing schedule entry: %s", line);
        }
    }

    fclose(fp);
    *num_entries = i;
    return 0;
}

// Function to parse a schedule entry from a line
int parse_schedule_entry(const char *line, schedule_entry_t *entry) {
    if (sscanf(line, "%d:%d:%d,%d,%d", &entry->hour, &entry->minute, &entry->second, &entry->relay_number, &entry->state) == 5) {
        if (entry->relay_number >= 1 && entry->relay_number <= NUM_RELAYS) {
            return 0; // Success
        } else {
            fprintf(stderr, "Invalid relay number: %d\n", entry->relay_number);
            return -1; // Invalid relay number
        }
    } else {
        fprintf(stderr, "Invalid schedule entry format: %s\n", line);
        return -1; // Invalid format
    }
}

// Function to set the state of a relay
int set_relay_state(int relay_number, int state) {
    int pin;
    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return -1;
    }

    gpioWrite(pin, state);
    return 0;
}

// Function to fade a relay to a target state
void fade_relay(int relay_number, int target_state) {
    int pin;
    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    int current_state = current_states[relay_number - 1];
    int current_duty_cycle = duty_cycles[relay_number - 1];

    if (current_state == target_state) {
