#define FADE_DURATION 1800

// Define the PWM frequency in Hz
#define PWM_FREQUENCY 100

// Define the number of relays
#define NUM_RELAYS 4

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state; // 0 for off, 1 for on
} schedule_entry_t;

// Global variables
static volatile int running = 1;
static int current_states[NUM_RELAYS] = {0}; // 0 = off, 1 = on
static int target_states[NUM_RELAYS] = {0};  // 0 = off, 1 = on
static int fade_directions[NUM_RELAYS] = {0}; // -1 = fading down, 1 = fading up, 0 = no fade
static int duty_cycles[NUM_RELAYS] = {0};    // Current duty cycle for each relay

// Function prototypes
int read_schedule(const char *filename, schedule_entry_t *schedule, int *num_entries);
int parse_schedule_entry(const char *line, schedule_entry_t *entry);
int set_relay_state(int relay_number, int state);
void fade_relay(int relay_number, int target_state);
void signal_handler(int signal);
void cleanup();

// Function to read the schedule from a file
int read_schedule(const char *filename, schedule_entry_t *schedule, int *num_entries) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL && i < 100) { // Limit to 100 entries
        if (parse_schedule_entry(line, &schedule[i]) == 0) {
            i++;
        } else {
            fprintf(stderr, "Error parsing schedule entry: %s", line);
        }
    }

    fclose(fp);
    *num_entries = i;
    return 0;
}

// Function to parse a schedule entry from a line
int parse_schedule_entry(const char *line, schedule_entry_t *entry) {
    if (sscanf(line, "%d:%d:%d,%d,%d", &entry->hour, &entry->minute, &entry->second, &entry->relay_number, &entry->state) == 5) {
        if (entry->relay_number >= 1 && entry->relay_number <= NUM_RELAYS) {
            return 0; // Success
        } else {
            fprintf(stderr, "Invalid relay number: %d\n", entry->relay_number);
