#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_FREQUENCY 200.0   // Minimum buzzer frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum buzzer frequency in Hz
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds (50ms)
#define MIN_DISTANCE 2.0       // Minimum measurable distance in cm
#define MAX_DISTANCE 200.0      // Maximum measurable distance in cm

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measurePulse() {
    long start_tick, end_tick, diff;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (start)\n");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (end)\n");
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    if (diff < 0) {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }

    return diff;
}

// Function to calculate distance from pulse duration
float calculateDistance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Distance in cm
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MAX_FREQUENCY; // Closest distance -> highest frequency
    } else if (distance > MAX_DISTANCE) {
        return MIN_FREQUENCY; // Farthest distance -> lowest frequency
    } else {
        // Linear mapping
        return MAX_FREQUENCY - (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the buzzer frequency
void setBuzzerFrequency(float frequency) {
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range and frequency (initial values)
    gpioSetPWMrange(BUZZER_PIN, 1000); // Adjust as needed
    gpioSetPWMfrequency(BUZZER_PIN, 440); // Initial frequency

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse duration
        long pulse_duration = measurePulse();

        // Calculate the distance
        float distance = calculateDistance(pulse_duration);

        // Map the distance to a frequency
        float frequency = mapDistanceToFrequency(distance);

        // Set the buzzer frequency
        setBuzzerFrequency(frequency);

        // Delay to achieve approximately 50 Hz loop rate (20 ms)
        gpioDelay(20000); // 20 ms
    }

    // Clean up and exit
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Terminate pigpio

    return 0;
}

