#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the RGB color using PWM
void set_rgb_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to calculate RGB values based on proximity value
void calculate_rgb(float proximity, int *red, int *green, int *blue) {
    // Map proximity value to RGB color space
    *red   = (int)(255.0 * proximity);   // Red increases with proximity
    *green = (int)(255.0 * (1.0 - proximity)); // Green decreases with proximity
    *blue  = (int)(127.5 * sin(proximity * M_PI)); // Blue varies with sine wave
}

int main() {
    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Main loop
    float proximity = 0.0;
    int red, green, blue;
    while (!terminate) {
        // Calculate RGB values based on proximity
        calculate_rgb(proximity, &red, &green, &blue);

        // Set RGB color
        set_rgb_color(red, green, blue);

        // Update proximity value (sine wave)
        proximity += 0.01; // Increment by 0.01 each iteration
        if (proximity > 1.0) {
            proximity = 0.0; // Reset to 0.0 after reaching 1.0
        }

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Turn off LED and terminate pigpio
    set_rgb_color(0, 0, 0);
    gpioTerminate();

    return 0;
}

