#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_GPIO 17
#define BUZZER_GPIO 18

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define melody structure
typedef struct {
    int frequency;
    int duration;
} Note;

// Define melody lookup table
const Note melody[] = {
    {440, 200},  // A4
    {494, 200},  // B4
    {523, 200},  // C5
    {587, 200},  // D5
    {659, 200},  // E5
    {698, 200},  // F5
    {784, 200},  // G5
    {880, 200}   // A5
};

const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int button_pressed = 0;
volatile int melody_playing = 0;
int melody_index = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user_data);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

// Button interrupt service routine
void button_isr(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    // Debounce the button
    if (current_tick - last_tick > DEBOUNCE_TIME * 1000) {
        if (level == 0) { // Button pressed (active low)
            button_pressed = 1;
        }
        last_tick = current_tick;
    }
}

// Function to play the melody
void play_melody() {
    if (melody_playing) return; // Prevent re-entry

    melody_playing = 1;
    melody_index = 0;

    while (melody_playing && melody_index < melody_length) {
        if (button_pressed) {
            stop_melody();
            break;
        }

        int frequency = melody[melody_index].frequency;
        int duration = melody[melody_index].duration;

        gpioPWM(BUZZER_GPIO, 128); // 50% duty cycle
        gpioSetPWMfrequency(BUZZER_GPIO, frequency);
        gpioDelay(duration * 1000); // Convert milliseconds to microseconds

        melody_index++;
    }

    stop_melody();
}

// Function to stop the melody
void stop_melody() {
    gpioPWM(BUZZER_GPIO, 0); // Stop PWM
    melody_playing = 0;
    button_pressed = 0; // Reset button press flag
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Enable pull-up resistor on button GPIO
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(BUZZER_GPIO, 255);

    // Set PWM duty cycle to 0 initially
    gpioPWM(BUZZER_GPIO, 0);

    // Set up interrupt service routine for button
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell program running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (button_pressed) {
            play_melody();
        }
        gpioDelay(1000); // Check every 1ms
    }

    return 0;
}

