#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT 1000 // milliseconds

// Structure to hold program state
typedef struct {
    int timeout;
    FILE *log_file;
    volatile sig_atomic_t terminate;
} ProgramState;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log events to file
void log_event(ProgramState *state, int value) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp for log entry.\n");
        return;
    }

    if (state->log_file != NULL) {
        fprintf(state->log_file, "%s,%d\n", timestamp, value);
        fflush(state->log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    free(timestamp);
}

// Function to check for earthquake alert
void check_earthquake_alert(int *window) {
    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (window[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= 3) {
        char *timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            printf("EARTHQUAKE ALERT: %s\n", timestamp);
            free(timestamp);
        } else {
            fprintf(stderr, "Error getting timestamp for earthquake alert.\n");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    ProgramState *state = (ProgramState*)malloc(sizeof(ProgramState));
    if (state == NULL) {
        perror("Failed to allocate memory for ProgramState in signal handler");
        exit(1);
    }

    state->terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);

    gpioTerminate(); // Release GPIO resources

    if (state->log_file != NULL) {
        fclose(state->log_file); // Close the log file
    }

    free(state);
    exit(0);
}

int main(int argc, char *argv[]) {
    ProgramState state;
    state.terminate = 0;
    state.log_file = NULL;
    state.timeout = DEFAULT_TIMEOUT;

    // Parse command-line argument for timeout
    if (argc > 1) {
        char *endptr;
        long timeout = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || timeout <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT);
        } else {
            state.timeout = (int)timeout;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file
    state.log_file = fopen("vibration_events.log", "a");
    if (state.log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int window[WINDOW_SIZE] = {0}; // Initialize sliding window
    int window_index = 0;

    // Main loop
    while (!state.terminate) {
        int value = gpioRead(GPIO_PIN);

        // Update sliding window
        window[window_index] = value;
        window_index = (window_index + 1) % WINDOW_SIZE;

        // Log the event
        log_event(&state, value);

        // Check for earthquake alert
        check_earthquake_alert(window);

        // Wait for a short period
        gpioDelay(state.timeout * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    if (state.log_file != NULL) {
        fclose(state.log_file);
    }

    return 0;
}

