        // Update sliding window
        window[window_index] = value;
        window_index = (window_index + 1) % WINDOW_SIZE;

        // Log the event
        log_event(&state, value);

        // Check for earthquake alert
        check_earthquake_alert(window);

        // Wait for a short period
        gpioDelay(state.timeout * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    if (state.log_file != NULL) {
        fclose(state.log_file);
    }

    return 0;
