#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Hard-iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
void calibrate_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
float calculate_heading(float x, float y);
const char *map_heading_to_compass(float heading);
int log_data(time_t timestamp, float calibrated_x, float calibrated_y, float calibrated_z, float heading);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // I2C bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure magnetometer (example configuration)
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x18) < 0) { // Set to 75 Hz
        fprintf(stderr, "Error writing to CRA_REG_M: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) { // Continuous conversion mode
        fprintf(stderr, "Error writing to MR_REG_M: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read raw magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", i2c_handle);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calibrate magnetometer data
void calibrate_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)x - X_OFFSET;
    *calibrated_y = (float)y - Y_OFFSET;
    *calibrated_z = (float)z - Z_OFFSET;
}

// Calculate heading in degrees
float calculate_heading(float x, float y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Map heading to compass direction
const char *map_heading_to_compass(float heading) {
    if (heading >= 337.5 || heading < 22.5) {
        return "N";
    } else if (heading >= 22.5 && heading < 67.5) {
        return "NE";
    } else if (heading >= 67.5 && heading < 112.5) {
        return "E";
    } else if (heading >= 112.5 && heading < 157.5) {
        return "SE";
    } else if (heading >= 157.5 && heading < 202.5) {
        return "S";
    } else if (heading >= 202.5 && heading < 247.5) {
        return "SW";
    } else if (heading >= 247.5 && heading < 292.5) {
        return "W";
    } else {
        return "NW";
    }
}

// Log data to CSV file
int log_data(time_t timestamp, float calibrated_x, float calibrated_y, float calibrated_z, float heading) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp_str, calibrated_x, calibrated_y, calibrated_z, heading);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }
    rewind(log_file);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float calibrated_x, calibrated_y, calibrated_z;
    float heading;
    const char *compass_direction;
    time_t current_time;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&raw_x, &raw_y, &raw_z) == 0) {
            // Calibrate data
            calibrate_data(raw_x, raw_y, raw_z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Map heading to compass direction
            compass_direction = map_heading_to_compass(heading);

            // Get current timestamp
            current_time = time(NULL);

            // Log data
            log_data(current_time, calibrated_x, calibrated_y, calibrated_z, heading);

            // Print to console
            printf("Compass: %s, Heading: %.2f\n", compass_direction, heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Skipping sample.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

