#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function prototypes
void touch_callback(int gpio, int level, unsigned int tick, void *user_data);
void signal_handler(int signal);
int log_relay_state(int state);

// Function to log relay state to JSON file
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    char json_string[100];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (state == 0) {
        snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s\", \"relay_state\": \"OFF\"}\n", timestamp);
    } else {
        snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s\", \"relay_state\": \"ON\"}\n", timestamp);
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s", json_string) < 0) {
            perror("Error writing to log file");
            return -1;
        }
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    return 0;
}

// Interrupt service routine for touch sensor
void touch_callback(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    // Check if the touch is valid (rising edge and debounce time has passed)
    if (level == 1) {
        if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) { // Convert ms to us
            // Toggle the relay state
            relay_state = !relay_state;

            // Set the relay pin
            gpioWrite(RELAY_PIN, relay_state);

            // Log the relay state
            if (log_relay_state(relay_state) != 0) {
                fprintf(stderr, "Error logging relay state.\n");
            }

            // Update the last touch time
            last_touch_time = current_time;
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Turn off the relay
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Log the final state
    if (log_relay_state(relay_state) != 0) {
        fprintf(stderr, "Error logging final relay state.\n");
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Initialize the relay to OFF state
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Open the log file
    log_file = fopen("relay_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt service routine for touch sensor
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

