#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define VALVE_GPIO 17
#define NOZZLE_GPIO 18

// Define moisture levels
#define MOISTURE_THRESHOLD 50
#define MOISTURE_SEQUENCE {20, 40, 60, 80, 100}
#define MOISTURE_SEQUENCE_LENGTH 5

// Define servo pulse widths (microseconds)
#define VALVE_CLOSED 500
#define VALVE_OPEN 1500
#define NOZZLE_ANGLES {500, 1000, 1500, 2000, 2500}
#define NOZZLE_ANGLES_LENGTH 5

// Define watering cycle parameters
#define NOZZLE_DELAY 2 // seconds
#define SPRAY_DURATION 5 // seconds
#define CYCLE_DELAY 5 // seconds

// Global variables
volatile sig_atomic_t terminate = 0;
int moisture_index = 0;

// Function prototypes
int set_servo_pulse(int gpio, int pulse_width);
int open_valve();
int close_valve();
int set_nozzle_angle(int angle);
void signal_handler(int signal);
int simulate_moisture_sensor();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);

    // Stop servos
    set_servo_pulse(VALVE_GPIO, 0);
    set_servo_pulse(NOZZLE_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to set servo pulse width
int set_servo_pulse(int gpio, int pulse_width) {
    int retries = 0;
    int result;

    while (retries < 3) {
        result = gpioServo(gpio, pulse_width);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error setting servo pulse on GPIO %d: %d. Retrying...\n", gpio, result);
            gpioDelay(100); // 100ms backoff
            retries++;
        }
    }

    fprintf(stderr, "Fatal error setting servo pulse on GPIO %d after multiple retries. Exiting.\n", gpio);
    gpioTerminate();
    exit(1);
}

// Function to open the valve
int open_valve() {
    int result = set_servo_pulse(VALVE_GPIO, VALVE_OPEN);
    if (result != 0) {
        fprintf(stderr, "Critical error: Failed to open valve.\n");
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to close the valve
int close_valve() {
    int result = set_servo_pulse(VALVE_GPIO, VALVE_CLOSED);
    if (result != 0) {
        fprintf(stderr, "Warning: Failed to close valve.\n");
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to set the nozzle angle
int set_nozzle_angle(int angle) {
    int pulse_width = 500 + (angle * 2000 / 180); // Map angle (0-180) to pulse width (500-2500)
    int result = set_servo_pulse(NOZZLE_GPIO, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set nozzle angle to %d degrees.\n", angle);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to simulate moisture sensor readings
int simulate_moisture_sensor() {
    int moisture_levels[] = MOISTURE_SEQUENCE;
    int current_moisture = moisture_levels[moisture_index];
    moisture_index = (moisture_index + 1) % MOISTURE_SEQUENCE_LENGTH;
    return current_moisture;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Simulate moisture sensor reading
        int moisture_level = simulate_moisture_sensor();
        printf("Simulated moisture level: %d\n", moisture_level);

        // Check if watering is needed
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Initiating watering cycle.\n");

            // Open the valve
            if (open_valve() != 0) {
                fprintf(stderr, "Watering cycle aborted due to valve failure.\n");
                gpioDelay(CYCLE_DELAY * 1000); // Wait before next cycle
                continue;
            }

            // Set nozzle angles
            int nozzle_angles[] = {0, 45, 90, 135, 180};
            for (int i = 0; i < NOZZLE_ANGLES_LENGTH; i++) {
                if (set_nozzle_angle(nozzle_angles[i]) == 0) {
                    gpioDelay(NOOZLE_DELAY * 1000); // Delay for nozzle position
                } else {
                    fprintf(stderr, "Continuing to next nozzle position.\n");
                }
            }

            // Spray duration
            gpioDelay(SPRAY_DURATION * 1000);

            // Close the valve
            close_valve();

        } else {
            printf("Moisture level above threshold. Skipping watering cycle.\n");
        }

        // Wait before next cycle
        gpioDelay(CYCLE_DELAY * 1000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_servo_pulse(VALVE_GPIO, 0);
    set_servo_pulse(NOZZLE_GPIO, 0);
    gpioTerminate();

    return 0;
}

