int debounce_button(int gpio_pin) {
    int reading = gpioRead(gpio_pin);
    gpioDelay(50000); // 50ms delay
    if (gpioRead(gpio_pin) == reading) {
        return (reading == 0); // Return 1 if button is pressed (active low)
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    // De-energize all coils
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output for stepper motor control
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);

    // Set GPIO pins as input for buttons with pull-up resistors
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door control program started. Press LOCK button to lock, UNLOCK button to unlock. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (debounce_button(LOCK_BUTTON)) {
            if (lock_door() < 0) {
                fprintf(stderr, "Error locking door\n");
            }
        }
        if (debounce_button(UNLOCK_BUTTON)) {
            if (unlock_door() < 0) {
                fprintf(stderr, "Error unlocking door\n");
            }
        }
        gpioDelay(10000); // Small delay to prevent busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

