#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define TIMEOUT_DURATION 50 // milliseconds
#define SPEED_OF_SOUND 34300 // cm/s
#define SAMPLING_INTERVAL 1 // second

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void trigger_sensor();
long get_pulse_width();
float calculate_distance(long pulse_width);
void log_distance(float distance);
void signal_handler(int signal);
int initialize_gpio();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    return 0; // Indicate success
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long get_pulse_width() {
    long start_time = 0, end_time = 0;
    int timeout = TIMEOUT_DURATION * 1000; // Convert milliseconds to microseconds

    // Wait for the rising edge with timeout
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        if (start_time == 0) start_time = gpioTick();
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout--;
    }

    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1; // Indicate timeout
    }

    // Wait for the falling edge with timeout
    timeout = TIMEOUT_DURATION * 1000;
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout--;
    }

    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1; // Indicate timeout
    }

    end_time = gpioTick();

    return end_time - start_time;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log the distance to a file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Clean up GPIO before exiting
        return 1;
    }

    fprintf(stdout, "Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        long pulse_width = get_pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance < 0) {
            fprintf(stderr, "Error: Distance calculation failed.\n");
            fprintf(log_file, "-1\n");
            fflush(log_file);
        } else {
            log_distance(distance);
        }

        gpioDelay(SAMPLING_INTERVAL * 1000); // Delay for 1 second
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    fprintf(stdout, "Distance measurement stopped.\n");
    return 0;
}

