#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a 16-bit value from the MPU-6050
int16_t read_word_2c(int handle, uint8_t reg)
{
    int16_t high_byte, low_byte, value;
    char buf[2];

    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return 0; // Or some error value
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return 0; // Or some error value
    }

    high_byte = buf[0];
    low_byte = buf[1];

    value = (high_byte << 8) | low_byte;
    return value;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU-6050
    char buf[2];
    buf[0] = PWR_MGMT_1;
    buf[1] = 0x00; // Clear sleep mode bit
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Read gyroscope data
        int16_t gyro_x = read_word_2c(i2c_handle, GYRO_XOUT_H);
        int16_t gyro_y = read_word_2c(i2c_handle, GYRO_YOUT_H);
        int16_t gyro_z = read_word_2c(i2c_handle, GYRO_ZOUT_H);

        // Print gyroscope data
        printf("Gyro X: %d, Gyro Y: %d, Gyro Z: %d\n", gyro_x, gyro_y, gyro_z);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

