#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "watering_log.txt"

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *relay1_line = NULL;
struct gpiod_line *relay2_line = NULL;
struct gpiod_line *relay3_line = NULL;
struct gpiod_line *relay4_line = NULL;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
void activate_relay(int pin);
void deactivate_relay(int pin);
void log_cycle_start(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize the GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the line handles for each relay
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Request the lines as outputs with active-low semantics
    ret = gpiod_line_request_output(relay1_line, "watering_system", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return -1;
    }
    ret = gpiod_line_request_output(relay2_line, "watering_system", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return -1;
    }
    ret = gpiod_line_request_output(relay3_line, "watering_system", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return -1;
    }
    ret = gpiod_line_request_output(relay4_line, "watering_system", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return -1;
    }

    // Set all lines HIGH (inactive) initially
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    return 0;
}

// Function to cleanup the GPIO lines
void cleanup_gpio(void) {
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to activate a relay
void activate_relay(int pin) {
    struct gpiod_line *line = NULL;
    if (pin == RELAY1_PIN) line = relay1_line;
    else if (pin == RELAY2_PIN) line = relay2_line;
    else if (pin == RELAY3_PIN) line = relay3_line;
    else if (pin == RELAY4_PIN) line = relay4_line;

    if (line) {
        int ret = gpiod_line_set_value(line, 0); // Active low
        if (ret < 0) {
            perror("Error setting GPIO line value");
        }
    }
}

// Function to deactivate a relay
void deactivate_relay(int pin) {
    struct gpiod_line *line = NULL;
    if (pin == RELAY1_PIN) line = relay1_line;
    else if (pin == RELAY2_PIN) line = relay2_line;
    else if (pin == RELAY3_PIN) line = relay3_line;
    else if (pin == RELAY4_PIN) line = relay4_line;

    if (line) {
        int ret = gpiod_line_set_value(line, 1); // Inactive high
        if (ret < 0) {
            perror("Error setting GPIO line value");
        }
    }
}

// Function to log the start of a watering cycle
void log_cycle_start(void) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open the log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    // Write the timestamp to the log file
    fprintf(fp, "%s\n", timestamp);

    // Close the log file
    fclose(fp);
}

int main(void) {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO lines
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Log the start of the watering cycle
        log_cycle_start();

        // Activate each relay in turn for 5 seconds
        activate_relay(RELAY1_PIN);
        sleep(5);
        deactivate_relay(RELAY1_PIN);
        sleep(60 - 5); // Wait 55 seconds

        activate_relay(RELAY2_PIN);
        sleep(5);
        deactivate_relay(RELAY2_PIN);
        sleep(60 - 5); // Wait 55 seconds

        activate_relay(RELAY3_PIN);
        sleep(5);
        deactivate_relay(RELAY3_PIN);
        sleep(60 - 5); // Wait 55 seconds

        activate_relay(RELAY4_PIN);
        sleep(5);
        deactivate_relay(RELAY4_PIN);
        sleep(60 - 5); // Wait 55 seconds

        // Wait for the remaining time to complete the 24-hour cycle
        sleep(86400 - (60 * 4)); // 86400 - (60 * 4) = 86160 seconds
    }

    return 0;
}

