#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// LED GPIO pin (BCM 17, WiringPi 0)
#define LED_PIN 0

// Sampling rate (Hz)
#define SAMPLING_RATE 20

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd;
circular_buffer_t gyro_buffer;
bool running = true;

// Function prototypes
int init_i2c();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
gyro_data_t get_from_buffer(circular_buffer_t *buffer, int index);
void check_threshold(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }

    // Wake up the MPU-6050 (set PWR_MGMT_1 to 0)
    if (wiringPiI2CWriteReg8(i2c_fd, PWR_MGMT_1, 0) == -1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    int16_t x_h, x_l, y_h, y_l, z_h, z_l;

    x_h = wiringPiI2CReadReg8(i2c_fd, GYRO_XOUT_H);
    x_l = wiringPiI2CReadReg8(i2c_fd, GYRO_XOUT_L);
    y_h = wiringPiI2CReadReg8(i2c_fd, GYRO_YOUT_H);
    y_l = wiringPiI2CReadReg8(i2c_fd, GYRO_YOUT_L);
    z_h = wiringPiI2CReadReg8(i2c_fd, GYRO_ZOUT_H);
    z_l = wiringPiI2CReadReg8(i2c_fd, GYRO_ZOUT_L);

    if (x_h == -1 || x_l == -1 || y_h == -1 || y_l == -1 || z_h == -1 || z_l == -1) {
        fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
        return -1;
    }

    *x = (x_h << 8) | x_l;
    *y = (y_h << 8) | y_l;
    *z = (z_h << 8) | z_l;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get data from the circular buffer
gyro_data_t get_from_buffer(circular_buffer_t *buffer, int index) {
    if (index < 0 || index >= buffer->count) {
        fprintf(stderr, "Error: Index out of bounds\n");
        gyro_data_t empty_data = {{0, 0}, 0, 0, 0};
        return empty_data;
    }
    int actual_index = (buffer->head - buffer->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->data[actual_index];
}

// Check if any axis exceeds the threshold
void check_threshold(int16_t x, int16_t y, int16_t z) {
    if (abs(x) > 250 || abs(y) > 250 || abs(z) > 250) {
        digitalWrite(LED_PIN, HIGH); // Turn LED on
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn LED off
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = false;
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    digitalWrite(LED_PIN, LOW); // Turn LED off
    if (i2c_fd != -1) {
        // No explicit I2C close function in wiringPi, but we can reset the device.
        // wiringPiI2CWriteReg8(i2c_fd, PWR_MGMT_1, 0x40); // Put MPU6050 to sleep
        // close(i2c_fd); // This is not needed with wiringPiI2CSetup
    }
    wiringPiSetup(); // Reinitialize wiringPi to ensure proper cleanup
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW); // Ensure LED is off initially

    // Initialize I2C
    if (init_i2c() == -1) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize circular buffer
    init_buffer(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int16_t x, y, z;
        struct timespec ts;

        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == -1) {
            fprintf(stderr, "Error reading gyro data. Re-initializing I2C.\n");
            cleanup();
            if (init_i2c() == -1) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                running = false; // Exit the loop if re-initialization fails
                break;
            }
            delay(100); // Small delay before retrying
            continue;    // Skip to the next iteration
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            running = false;
            break;
        }

        // Create gyro data struct
        gyro_data_t gyro_data = {ts, x, y, z};

        // Add data to circular buffer
        add_to_buffer(&gyro_buffer, gyro_data);

        // Check threshold and control LED
        check_threshold(x, y, z);

        // Delay for sampling rate
        delay(1000 / SAMPLING_RATE); // Delay in milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

