#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 3900000 // 3.9 MHz
#define SPI_MODE 0
#define GYRO_SENSITIVITY 131.0 // LSB/deg/s for +/- 250 deg/s range
#define THRESHOLD 200.0
#define LED_GPIO 17
#define BUFFER_SIZE 64

// Data structure for gyroscope data
typedef struct {
    long long timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_spi();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(circular_buffer_t *buffer, long long timestamp, float x, float y, float z);
int check_threshold(float x, float y, float z);
void blink_led(int gpio_pin, int duration_ms);
void signal_handler(int signal);
void print_buffer(circular_buffer_t *buffer);

// Initialize the circular buffer
void init_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize SPI communication
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(float *x, float *y, float *z) {
    char tx_buffer[1] = {0x43}; // Read Gyro X register (0x43)
    char rx_buffer[6]; // 2 bytes per axis (X, Y, Z)
    int result;

    result = spiXfer(spi_handle, tx_buffer, rx_buffer, 7); // Send read command and receive data

    if (result != 7) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (rx_buffer[0] << 8) | rx_buffer[1];
    int16_t raw_y = (rx_buffer[2] << 8) | rx_buffer[3];
    int16_t raw_z = (rx_buffer[4] << 8) | rx_buffer[5];

    // Convert raw data to degrees per second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, long long timestamp, float x, float y, float z) {
    buffer->data[buffer->head].timestamp = timestamp;
    buffer->data[buffer->head].x = x;
    buffer->data[buffer->head].y = y;
    buffer->data[buffer->head].z = z;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check if any axis exceeds the threshold
int check_threshold(float x, float y, float z) {
    if (x > THRESHOLD || x < -THRESHOLD ||
        y > THRESHOLD || y < -THRESHOLD ||
        z > THRESHOLD || z < -THRESHOLD) {
        return 1;
    }
    return 0;
}

// Blink the warning LED
void blink_led(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(gpio_pin, 0); // Turn LED off
    gpioDelay(duration_ms * 1000); // Delay in microseconds
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Print the contents of the circular buffer to CSV format
void print_buffer(circular_buffer_t *buffer) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer->count; i++) {
        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE; // Calculate correct index
        printf("%lld,%.2f,%.2f,%.2f\n", buffer->data[index].timestamp, buffer->data[index].x, buffer->data[index].y, buffer->data[index].z);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    init_buffer(&gyro_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;
    struct timespec ts;

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            long long timestamp = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

            // Add data to buffer
            add_to_buffer(&gyro_buffer, timestamp, x, y, z);

            // Check for threshold violation
            if (check_threshold(x, y, z)) {
                blink_led(LED_GPIO, 500);
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        gpioDelay(10000); // Delay 10ms (adjust as needed)
    }

    // Print buffer contents before exiting
    print_buffer(&gyro_buffer);

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

