#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_CONFIG 0x1C

// LED GPIO pin
#define LED_PIN 21

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_mpu6050();
int read_raw_accel_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z);
void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch);
void log_data(float roll, float pitch);
void control_led(float roll, float pitch);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);   // Close I2C connection
    gpioTerminate();       // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (set sleep bit to 0)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Configure accelerometer range to +/- 2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range\n");
        return -1;
    }

    return 0;
}

// Read raw accelerometer data
int read_raw_accel_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Calculate roll and pitch angles
void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch) {
    float accel_x_g = (float)accel_x / 16384.0; // Assuming +/- 2g range
    float accel_y_g = (float)accel_y / 16384.0;
    float accel_z_g = (float)accel_z / 16384.0;

    *roll = atan2(accel_y_g, accel_z_g) * 180 / M_PI;
    *pitch = atan2(-accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180 / M_PI;
}

