void log_data(float roll, float pitch) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED based on roll and pitch
void control_led(float roll, float pitch) {
    if (fabs(roll) > 45.0 || fabs(pitch) > 45.0) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

