    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C connection\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t accel_x, accel_y, accel_z;
    float roll, pitch;

    // Main loop
    while (1) {
        // Read accelerometer data
        if (read_raw_accel_data(&accel_x, &accel_y, &accel_z) == 0) {
            // Calculate roll and pitch
            calculate_roll_pitch(accel_x, accel_y, accel_z, &roll, &pitch);

            // Print roll and pitch to console
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

            // Log data to file
            log_data(roll, pitch);

            // Control LED
            control_led(roll, pitch);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Continuing...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

