#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60
#define GPIO_LED 17
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Si1145 Registers
#define REG_PARTID 0x00
#define REG_REVID 0x01
#define REG_SEQID 0x02
#define REG_INTCFG 0x03
#define REG_IRQEN 0x04
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0 0x24
#define REG_PS1_DATA1 0x25
#define REG_COMMAND 0x30

// Commands
#define CMD_RESET 0x01

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity);
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity);
void control_led(int gpio, int state);
void signal_handler(int sig);
int initialize_i2c(const char *bus, int addr);
void cleanup(void);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = RETRY_COUNT;
    int result = -1;

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        result = read(fd, &reg, 1);
        if (result == 1) {
            return reg;
        } else {
            perror("Failed to read register value");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    int retries = RETRY_COUNT;
    int result = -1;

    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("Failed to write register value");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C write failed after %d retries.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Read sensor data function
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    int al_low, al_high, ps_low, ps_high;

    al_low = i2c_read_reg(fd, REG_ALS_VIS_DATA0);
    al_high = i2c_read_reg(fd, REG_ALS_VIS_DATA1);
    ps_low = i2c_read_reg(fd, REG_PS1_DATA0);
    ps_high = i2c_read_reg(fd, REG_PS1_DATA1);

    if (al_low == -1 || al_high == -1 || ps_low == -1 || ps_high == -1) {
        return -1; // Indicate failure
    }

    *ambient_light = (uint16_t)((al_high << 8) | al_low);
    *proximity = (uint16_t)((ps_high << 8) | ps_low);

    return 0; // Success
}

// Log data function
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient_light, proximity) < 0) {
        perror("Failed to write to log file");
        return -1; // Indicate failure
    }

    fflush(fp); // Ensure data is written to disk
    return 0; // Success
}

// Control LED function
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C function
int initialize_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

// Cleanup function
void cleanup(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    control_led(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    uint16_t ambient_light, proximity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = initialize_i2c(I2C_BUS, SI1145_ADDR);
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            if (log_data(log_file, ambient_light, proximity) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }

            if (proximity > 100) {
                control_led(GPIO_LED, 1); // Turn on LED
            } else {
                control_led(GPIO_LED, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

