    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set read bit (MSB)
    tx_buf[1] = 0x00;             // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) == 2) {
        *data = rx_buf[1];
        return 0; // Success
    } else {
        fprintf(stderr, "SPI transfer failed\n");
        return -1; // Failure
    }
}

