    if (spi_read_register(ADXRS290_REG_YGYRO_OUT, &y_data) != 0) {
        return -1;
    }

    *x_rate = (int16_t)((x_data << 8) | (x_data >> 8)); // Byte swap
    *y_rate = (int16_t)((y_data << 8) | (y_data >> 8)); // Byte swap

    return 0;
}

// Log data to CSV file
