    struct timespec ts;

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Failed to get timestamp\n");
        return -1;
    }

    // Convert timestamp to seconds and microseconds
    long seconds = ts.tv_sec;
    long microseconds = ts.tv_nsec / 1000; // Convert nanoseconds to microseconds

    fprintf(fp, "%ld.%06ld,%d,%d\n", seconds, microseconds, x_rate, y_rate);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;

    // Clean up resources
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();

    exit(0);
}

