#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define ALERT_DURATION_MS 2000
#define SENSOR_READ_INTERVAL_MS 100

// Global variables
static volatile int sensor1_state = 0; // 0: LOW, 1: HIGH
static volatile int sensor2_state = 0; // 0: LOW, 1: HIGH
static volatile unsigned long sensor1_last_change = 0;
static volatile unsigned long sensor2_last_change = 0;
static volatile int alert_active = 0;
static FILE *log_file = NULL;

// Function prototypes
void sensor1_callback(int gpio, int level, unsigned int tick, void *user);
void sensor2_callback(int gpio, int level, unsigned int tick, void *user);
void trigger_alert();
void log_event();
void signal_handler(int signal);

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, unsigned int tick, void *user) {
    unsigned long now = gpioTick();
    if (now - sensor1_last_change > DEBOUNCE_DELAY_MS * 1000) {
        sensor1_state = level;
        sensor1_last_change = now;
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, unsigned int tick, void *user) {
    unsigned long now = gpioTick();
    if (now - sensor2_last_change > DEBOUNCE_DELAY_MS * 1000) {
        sensor2_state = level;
        sensor2_last_change = now;
    }
}

// Function to trigger the alert
void trigger_alert() {
    if (!alert_active) {
        alert_active = 1;
        gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
        gpioDelay(ALERT_DURATION_MS * 1000); // Wait for 2 seconds
        gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
        alert_active = 0;
    }
}

// Function to log the event
void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Set alert pin LOW
    gpioWrite(ALERT_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-down resistors (already handled by the circuit)

    // Register callbacks
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor1_callback, NULL) != 0) {
        fprintf(stderr, "Error registering callback for sensor 1!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor2_callback, NULL) != 0) {
        fprintf(stderr, "Error registering callback for sensor 2!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Seismic event detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (sensor1_state == 1 && sensor2_state == 1) {
            trigger_alert();
            log_event();
        }
        gpioDelay(SENSOR_READ_INTERVAL_MS * 1000); // Check every 100ms
    }

    return 0;
}

