#include <pigpio.h>

// ADXRS290 Register Addresses
#define ADXRS290_REG_WHO_AM_I 0x00
#define ADXRS290_REG_XGYRO_OUT 0x08
#define ADXRS290_REG_TEMP_OUT 0x0A
#define ADXRS290_REG_DIAG_STAT 0x0B
#define ADXRS290_REG_GLOB_CMD 0x06
#define ADXRS290_REG_RATE_SCALE 0x05

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// GPIO Pin Definitions
#define LED_PIN 17
#define CS_PIN 8

// Circular Buffer Configuration
#define BUFFER_SIZE 100

// Threshold for angular rate
#define ANGULAR_RATE_THRESHOLD 20.0

// Structure for circular buffer entries
typedef struct {
    struct timespec timestamp;
    float angular_rate;
} buffer_entry_t;

// Circular buffer structure
typedef struct {
    buffer_entry_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int spi_handle;
circular_buffer_t circular_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_read_register(uint8_t reg_addr, uint8_t *data, int len);
int spi_write_register(uint8_t reg_addr, uint8_t data);
float read_angular_rate();
void add_to_buffer(circular_buffer_t *cb, struct timespec ts, float angular_rate);
int get_from_buffer(circular_buffer_t *cb, int index, struct timespec *ts, float *angular_rate);
void check_threshold(float angular_rate);
void signal_handler(int signal);
void cleanup();

// Function to initialize the circular buffer
void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *cb, struct timespec ts, float angular_rate) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head].timestamp = ts;
    cb->buffer[cb->head].angular_rate = angular_rate;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

// Function to get data from the circular buffer
int get_from_buffer(circular_buffer_t *cb, int index, struct timespec *ts, float *angular_rate) {
    pthread_mutex_lock(&cb->mutex);
    if (index < 0 || index >= cb->count) {
        pthread_mutex_unlock(&cb->mutex);
        return -1; // Invalid index
    }
    int actual_index = (cb->tail + index) % BUFFER_SIZE;
    *ts = cb->buffer[actual_index].timestamp;
    *angular_rate = cb->buffer[actual_index].angular_rate;
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

// Function to read data from an ADXRS290 register
int spi_read_register(uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    memset(tx_buf + 1, 0, len); // Fill with dummy data for reading

    gpioWrite(CS_PIN, 0); // Assert CS
    int result = spiXfer(spi_handle, tx_buf, rx_buf, len + 1);
    gpioWrite(CS_PIN, 1); // De-assert CS

    if (result != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Function to write data to an ADXRS290 register
int spi_write_register(uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;

    gpioWrite(CS_PIN, 0); // Assert CS
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // De-assert CS

    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read the X-axis angular rate from the ADXRS290
float read_angular_rate() {
    uint8_t data[2];
    int16_t raw_rate;
    float angular_rate;

    if (spi_read_register(ADXRS290_REG_XGYRO_OUT, data, 2) != 0) {
        fprintf(stderr, "Failed to read angular rate\n");
        return 0.0; // Return 0 on error
    }

    raw_rate = (int16_t)((data[0] << 8) | data[1]);

    // Convert raw rate to degrees per second (adjust scale factor as needed)
    angular_rate = (float)raw_rate / 14.375; // Example scale factor, adjust based on datasheet

    return angular_rate;
}

// Function to check if the angular rate exceeds the threshold
void check_threshold(float angular_rate) {
    if (angular_rate > ANGULAR_RATE_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    pthread_mutex_destroy(&circular_buffer.mutex);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Initialize CS high

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&circular_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec ts;
    float angular_rate;

    while (program_running) {
        // Read angular rate
        angular_rate = read_angular_rate();

        // Get timestamp
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Add data to circular buffer
        add_to_buffer(&circular_buffer, ts, angular_rate);

        // Check threshold and control LED
        check_threshold(angular_rate);

        // Print angular rate (for debugging)
        printf("Angular Rate: %.2f deg/s\n", angular_rate);

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

