#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// PWM frequency
#define PWM_FREQUENCY 100

// Global variable to store the total duration
int total_duration = 0;

// Function prototypes
int validate_duration(int duration);
int initialize_gpio(int gpio);
int set_pwm_duty_cycle(int gpio, int duty_cycle);
int fade_lamp(int gpio, int duration);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to turn off all lamps and terminate pigpio
void cleanup() {
    set_pwm_duty_cycle(LAMP1_GPIO, 0);
    set_pwm_duty_cycle(LAMP2_GPIO, 0);
    set_pwm_duty_cycle(LAMP3_GPIO, 0);
    gpioTerminate();
}

// Function to validate the duration input
int validate_duration(int duration) {
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Duration must be between 1 and 3600 seconds.\n");
        return 1; // Indicate an error
    }
    return 0; // Indicate success
}

// Function to initialize a GPIO pin for PWM output
int initialize_gpio(int gpio) {
    if (gpioSetMode(gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", gpio);
        return 1; // Indicate an error
    }
    if (gpioSetPWMfrequency(gpio, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency for GPIO %d.\n", gpio);
        return 1; // Indicate an error
    }
    if (gpioSetPWMrange(gpio, 255) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range for GPIO %d.\n", gpio);
        return 1; // Indicate an error
    }
    return 0; // Indicate success
}

// Function to set the PWM duty cycle for a GPIO pin
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle for GPIO %d.\n", gpio);
        return 1; // Indicate an error
    }
    return 0; // Indicate success
}

// Function to fade a lamp from full brightness to off over a given duration
int fade_lamp(int gpio, int duration) {
    int duty_cycle;
    float increment = 255.0 / duration; // Calculate the duty cycle decrement per second
    float current_duty_cycle = 255.0;

    printf("Fading lamp on GPIO %d for %d seconds...\n", gpio, duration);

    for (int i = 0; i < duration; i++) {
        duty_cycle = (int)current_duty_cycle;
        if (set_pwm_duty_cycle(gpio, duty_cycle) != 0) {
            return 1; // Indicate an error
        }
        current_duty_cycle -= increment;
        if (current_duty_cycle < 0) current_duty_cycle = 0; // Ensure duty cycle doesn't go negative
        sleep(1);
    }

    // Ensure the lamp is fully off at the end
    set_pwm_duty_cycle(gpio, 0);
    printf("Lamp on GPIO %d faded to off.\n", gpio);
    return 0; // Indicate success
}

int main(int argc, char *argv[]) {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check if the duration argument is provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_in_seconds>\n", argv[0]);
        return 1;
    }

    // Convert the duration argument to an integer
    char *endptr;
    total_duration = strtol(argv[1], &endptr, 10);

    // Check for errors during conversion
    if (*endptr != '\0' || total_duration == 0) {
        fprintf(stderr, "Error: Invalid duration argument.\n");
        return 1;
    }

    // Validate the duration
    if (validate_duration(total_duration) != 0) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Initialize GPIO pins for PWM output
    if (initialize_gpio(LAMP1_GPIO) != 0 ||
        initialize_gpio(LAMP2_GPIO) != 0 ||
        initialize_gpio(LAMP3_GPIO) != 0) {
        cleanup();
        return 1;
    }

    // Fade the lamps sequentially
    if (fade_lamp(LAMP1_GPIO, total_duration) != 0 ||
        fade_lamp(LAMP2_GPIO, total_duration) != 0 ||
        fade_lamp(LAMP3_GPIO, total_duration) != 0) {
        cleanup();
        return 1;
    }

    // Cleanup and exit
    cleanup();
    printf("Sunset simulation complete.\n");
    return 0;
}

