#include <unistd.h>

// Define GPIO pins for the traffic light
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define FLASH_PIN 24

// Define traffic light states
typedef enum {
    RED,
    RED_YELLOW,
    GREEN,
    YELLOW,
    FLASHING_YELLOW
} TrafficLightState;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

// Function to set the state of a GPIO pin
int set_gpio_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to set the traffic light state
int set_traffic_light_state(TrafficLightState state) {
    int red_state, yellow_state, green_state, flash_state;

    switch (state) {
        case RED:
            red_state = 0;   // Red on
