#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define MPR121_ADDR 0x5A
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE0 0x00
#define MPR121_ELECTRODE1 0x01
#define MPR121_ELECTRODE2 0x02
#define MPR121_ELECTRODE3 0x03
#define MPR121_ELECTRODE4 0x04
#define MPR121_ELECTRODE5 0x05
#define MPR121_ELECTRODE6 0x06
#define MPR121_ELECTRODE7 0x07
#define MPR121_ELECTRODE8 0x08
#define MPR121_ELECTRODE9 0x09
#define MPR121_ELECTRODE10 0x0A
#define MPR121_ELECTRODE11 0x0B
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

#define RELAY_PIN 17 // BCM GPIO17
#define DEBOUNCE_DELAY 100 // milliseconds

// Global variables
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;
static unsigned long last_touch_time = 0;

// Function prototypes
int init_i2c(int address);
int init_gpio(int pin);
int init_mpr121(int fd);
int read_touch_status(int fd);
void toggle_relay(int pin);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C interface
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        log_error("Failed to initialize I2C interface.");
        return -1;
    }
    return fd;
}

// Initialize GPIO pin
int init_gpio(int pin) {
    if (wiringPiSetupGpio() == -1) {
        log_error("Failed to initialize wiringPi.");
        return -1;
    }

    pinMode(pin, OUTPUT);
    digitalWrite(pin, LOW); // Initialize to LOW
    return 0;
}

// Initialize MPR121
int init_mpr121(int fd) {
    // Stop mode
    if (wiringPiI2CWriteReg8(fd, MPR121_CONFIG1, 0x00) < 0) {
        log_error("Failed to set MPR121 to stop mode.");
        return -1;
    }
    delay(1);

    // Configure Electrode 0
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0, 0x30) < 0) {
        log_error("Failed to set touch threshold for electrode 0.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0, 0x10) < 0) {
        log_error("Failed to set release threshold for electrode 0.");
        return -1;
    }

    // Configure Electrode 1
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0 + 2, 0x30) < 0) {
        log_error("Failed to set touch threshold for electrode 1.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0 + 2, 0x10) < 0) {
        log_error("Failed to set release threshold for electrode 1.");
        return -1;
    }

    // Configure Electrode 2
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0 + 4, 0x30) < 0) {
        log_error("Failed to set touch threshold for electrode 2.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0 + 4, 0x10) < 0) {
        log_error("Failed to set release threshold for electrode 2.");
        return -1;
    }

    // Configure Electrode 3
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0 + 6, 0x30) < 0) {
        log_error("Failed to set touch threshold for electrode 3.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0 + 6, 0x10) < 0) {
        log_error("Failed to set release threshold for electrode 3.");
        return -1;
    }

    // Configure Electrode 4
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0 + 8, 0x30) < 0) {
        log_error("Failed to set touch threshold for electrode 4.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0 + 8, 0x10) < 0) {
        log_error("Failed to set release threshold for electrode 4.");
        return -1;
    }

    // Configure Electrode 5
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0 + 10, 0x30) < 0) {
        log_error("Failed to set touch threshold for electrode 5.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0 + 10, 0x10) < 0) {
        log_error("Failed to set release threshold for electrode 5.");
        return -1;
    }

    // Configure Electrode 6
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0 + 12, 0x30) < 0) {
        log_error("Failed to set touch threshold for electrode 6.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0 + 12, 0x10) < 0) {
        log_error("Failed to set release threshold for electrode 6.");
        return -1;
    }

    // Configure Electrode 7
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0 + 14, 0x30) < 0) {
        log_error("Failed to set touch threshold for electrode 7.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0 + 14, 0x10) < 0) {
        log_error("Failed to set release threshold for electrode 7.");
        return -1;
    }

    // Configure Electrode 8
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0 + 16, 0x30) < 0) {
        log_error("Failed to set touch threshold for electrode 8.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0 + 16, 0x10) < 0) {
        log_error("Failed to set release threshold for electrode 8.");
        return -1;
    }

    // Configure Electrode 9
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0 + 18, 0x30) < 0) {
        log_error("Failed to set touch threshold for electrode 9.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0 + 18, 0x10) < 0) {
        log_error("Failed to set release threshold for electrode 9.");
        return -1;
    }

    // Configure Electrode 10
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0 + 20, 0x30) < 0) {
        log_error("Failed to set touch threshold for electrode 10.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0 + 20, 0x10) < 0) {
        log_error("Failed to set release threshold for electrode 10.");
        return -1;
    }

    // Configure Electrode 11
    if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0 + 22, 0x30) < 0) {
        log_error("Failed to set touch threshold for electrode 11.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0 + 22, 0x10) < 0) {
        log_error("Failed to set release threshold for electrode 11.");
        return -1;
    }

    // Start mode (enable all electrodes)
    if (wiringPiI2CWriteReg8(fd, MPR121_CONFIG1, 0x10) < 0) {
        log_error("Failed to set MPR121 to start mode.");
        return -1;
    }
    delay(1);

    return 0;
}

// Read touch status from MPR121
int read_touch_status(int fd) {
    int touch_status_l = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_L);
    int touch_status_h = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_H);

    if (touch_status_l == -1 || touch_status_h == -1) {
        log_error("Failed to read touch status from MPR121.");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Toggle the relay connected to the specified GPIO pin
void toggle_relay(int pin) {
    int current_state = digitalRead(pin);
    digitalWrite(pin, !current_state);
}

// Log errors to file with timestamp
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s (errno: %d)\n", timestamp, message, errno);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        log_error("Failed to initialize wiringPi.");
        fclose(log_file);
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(MPR121_ADDR);
    if (i2c_fd == -1) {
        fclose(log_file);
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121(i2c_fd) == -1) {
        fclose(log_file);
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(RELAY_PIN) == -1) {
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status(i2c_fd);
        if (touch_status != -1) {
            // Check if electrode 0 is touched
            if ((touch_status & (1 << MPR121_ELECTRODE0)) && (touch_status & (1 << MPR121_ELECTRODE1)) && (touch_status & (1 << MPR121_ELECTRODE2)) && (touch_status & (1 << MPR121_ELECTRODE3)) && (touch_status & (1 << MPR121_ELECTRODE4)) && (touch_status & (1 << MPR121_ELECTRODE5)) && (touch_status & (1 << MPR121_ELECTRODE6)) && (touch_status & (1 << MPR121_ELECTRODE7)) && (touch_status & (1 << MPR121_ELECTRODE8)) && (touch_status & (1 << MPR121_ELECTRODE9)) && (touch_status & (1 << MPR121_ELECTRODE10)) && (touch_status & (1 << MPR121_ELECTRODE11))) {
                unsigned long current_time = millis();
                if (current_time - last_touch_time > DEBOUNCE_DELAY) {
                    toggle_relay(RELAY_PIN);
                    last_touch_time = current_time;
                }
            }
        }
        delay(10); // Check every 10ms
    }

    // Cleanup
    digitalWrite(RELAY_PIN, LOW); // Ensure relay is off
    fclose(log_file);

    return 0;
}

