#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
void log_flame_detection();
void activate_buzzer_led();
void deactivate_buzzer_led();
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Structure to hold GPIO pin configurations
typedef struct {
    int flame_sensor_pin;
    int buzzer_pin;
    int led_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to log flame detection with timestamp
void log_flame_detection() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Flame Detected\n", timestamp);
    fflush(log_file); // Ensure immediate write to file
}

// Function to activate buzzer and LED
void activate_buzzer_led() {
    gpioWrite(BUZZER_PIN, 1);
    gpioWrite(LED_PIN, 1);
}

// Function to deactivate buzzer and LED
void deactivate_buzzer_led() {
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    deactivate_buzzer_led();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    int flame_detected = 0;
    int consecutive_reads = 0;

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) { // Flame detected (LOW signal)
            consecutive_reads++;
            if (consecutive_reads >= 3) {
                if (!flame_detected) {
                    log_flame_detection();
                    activate_buzzer_led();
                    flame_detected = 1;
                }
            }
        } else {
            consecutive_reads = 0;
            if (flame_detected) {
                deactivate_buzzer_led();
                flame_detected = 0;
            }
        }

        gpioDelay(50); // 50ms delay
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Flame detection system stopped.\n");
    return 0;
}

