// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense interval and solenoid activation duration
#define DISPENSE_INTERVAL_MS 1000
#define SOLENOID_DURATION_MS (DISPENSE_INTERVAL_MS / 2)

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_solenoid(int pin, int duration_ms);
void deactivate_solenoids();
void log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
        deactivate_solenoids();
        gpioTerminate();
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to activate a solenoid for a specified duration
void activate_solenoid(int pin, int duration_ms) {
    gpioWrite(pin, 1); // Activate solenoid
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(pin, 0); // Deactivate solenoid
}

// Function to deactivate both solenoids
void deactivate_solenoids() {
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
}

// Function to log dispense events to a file
void log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening dispense_log.txt for writing\n");
        return; // Exit if file opening fails
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Solenoid 1 Pin: %d, Solenoid 2 Pin: %d, Duration: %d ms\n",
            s, solenoid1_pin, solenoid2_pin, duration_ms);

    fclose(fp);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Main loop
    while (program_running) {
        // Activate solenoid 1 for the first half of the interval
        activate_solenoid(SOLENOID_1_PIN, SOLENOID_DURATION_MS);

        // Activate solenoid 2 for the second half of the interval
        activate_solenoid(SOLENOID_2_PIN, SOLENOID_DURATION_MS);

        // Log the dispense event
        log_dispense_event(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_INTERVAL_MS);

        // Wait for the remaining time to complete the dispense interval
        gpioDelay((DISPENSE_INTERVAL_MS - SOLENOID_DURATION_MS) * 1000);
    }

    // Deactivate solenoids and terminate pigpio before exiting
    deactivate_solenoids();
    gpioTerminate();

    return 0;
}

