// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255

#define LOG_FILE "balance_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// PID gains
float Kp = 1.0;
float Ki = 0.1;
float Kd = 0.01;

// PID variables
float integral = 0.0;
float previous_error = 0.0;

// Function prototypes
float simulate_tilt_error();
float simulate_distance();
void set_motor_speed(int motor, int speed);
void stop_motors();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Function to simulate tilt error
float simulate_tilt_error() {
    return (float)(rand() % 201 - 100); // Random float between -10.0 and 10.0
}

// Function to simulate distance
float simulate_distance() {
    return (float)(rand() % 398 + 2); // Random float between 2.0 and 400.0
}

// Function to set motor speed
void set_motor_speed(int motor, int speed) {
    if (speed > 255) speed = 255;
    if (speed < -255) speed = -255;

    int forward_pin, backward_pin, enable_pin;

    if (motor == 'A') {
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
        enable_pin = MOTOR_A_ENABLE;
    } else if (motor == 'B') {
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
        enable_pin = MOTOR_B_ENABLE;
    } else {
        fprintf(stderr, "Error: Invalid motor character: %c\n", motor);
        return;
    }

    if (speed > 0) {
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioPWM(backward_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
    }
}

// Function to stop motors
void stop_motors() {
    set_motor_speed('A', 0);
    set_motor_speed('B', 0);
}

// Function to log data
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
