#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Configuration
#define SAMPLE_RATE 8000
#define PERIOD_SIZE 1024
#define NUM_CHANNELS 1
#define FORMAT "S16_LE" // Signed 16-bit little-endian
#define DEFAULT_SENSITIVITY 1.0
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000

// GPIO pins for RGB LED
#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

// Global variables
static volatile int running = 1;
static float sensitivity = DEFAULT_SENSITIVITY;
static int gpio_initialized = 0;
static int alsa_initialized = 0;

// Structure to hold audio data and RMS
typedef struct {
    short *data;
    float rms;
} AudioBuffer;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_alsa();
AudioBuffer capture_audio();
float calculate_rms(AudioBuffer buffer);
void map_rms_to_color(float rms, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void cleanup();
void simulate_audio(AudioBuffer *buffer);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    running = 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpio_initialized = 1;

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    return 0;
}

// Initialize ALSA (Placeholder, actual ALSA initialization would go here)
int initialize_alsa() {
    // In a real implementation, this would initialize ALSA using snd_pcm_open, snd_pcm_hw_params, etc.
    // For this example, we'll just print a message.
    fprintf(stderr, "ALSA initialization placeholder called.\n");
    alsa_initialized = 1; // Mark as initialized for now
    return 0;
}

// Capture audio (Placeholder, actual ALSA capture would go here)
AudioBuffer capture_audio() {
    AudioBuffer buffer;
    buffer.data = (short *)malloc(PERIOD_SIZE * sizeof(short));
    if (buffer.data == NULL) {
        fprintf(stderr, "Failed to allocate memory for audio buffer\n");
        buffer.rms = 0.0; // Set RMS to 0 to avoid further issues
        return buffer;
    }

    // In a real implementation, this would capture audio using ALSA.
    // For this example, we'll simulate audio.
    simulate_audio(&buffer);

    return buffer;
}

// Simulate audio with a sine wave
void simulate_audio(AudioBuffer *buffer) {
    for (int i = 0; i < PERIOD_SIZE; i++) {
        // Generate a sine wave with a frequency of 440 Hz (A4)
        double time = (double)i / SAMPLE_RATE;
        double amplitude = 0.5; // Scale to avoid clipping
        buffer->data[i] = (short)(amplitude * 32767 * sin(2 * M_PI * 440 * time));
    }
}

// Calculate RMS amplitude
float calculate_rms(AudioBuffer buffer) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < PERIOD_SIZE; i++) {
        sum_of_squares += (double)buffer.data[i] * buffer.data[i];
    }
    double mean_square = sum_of_squares / PERIOD_SIZE;
    float rms = sqrt(mean_square);
    free(buffer.data);
    return rms;
}

// Map RMS amplitude to RGB color values
void map_rms_to_color(float rms, int *red, int *green, int *blue) {
    // Apply sensitivity scaling
    rms *= sensitivity;

    // Normalize RMS to a range of 0-1 (assuming a maximum possible RMS)
    float normalized_rms = rms / 10000.0; // Adjust 10000.0 based on your audio source
    if (normalized_rms > 1.0) normalized_rms = 1.0;
    if (normalized_rms < 0.0) normalized_rms = 0.0;

    // Map RMS to color using a non-linear function (e.g., logarithmic)
    float hue = normalized_rms * 360.0; // Map RMS to hue (0-360 degrees)

    // Convert hue to RGB (simplified example, using a color wheel)
    float red_val = 0.0, green_val = 0.0, blue_val = 0.0;

    if (hue < 120) {
        red_val = 1.0 - (hue / 120.0);
        green_val = hue / 120.0;
        blue_val = 0.0;
    } else if (hue < 240) {
        red_val = 0.0;
        green_val = 1.0 - ((hue - 120.0) / 120.0);
        blue_val = (hue - 120.0) / 120.0;
    } else {
        red_val = (hue - 240.0) / 120.0;
        green_val = 0.0;
        blue_val = 1.0 - ((hue - 240.0) / 120.0);
    }

    // Scale RGB values to the PWM range
    *red = (int)(red_val * PWM_RANGE);
    *green = (int)(green_val * PWM_RANGE);
    *blue = (int)(blue_val * PWM_RANGE);
}

// Set LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    if (gpio_initialized) {
        gpioPWM(RED_PIN, 0); // Turn off LED
        gpioPWM(GREEN_PIN, 0);
        gpioPWM(BLUE_PIN, 0);
        gpioTerminate();
    }

    // In a real ALSA implementation, close the PCM device here.
    fprintf(stderr, "Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        sensitivity = strtof(argv[1], &endptr);
        if (*endptr != '\0' || sensitivity <= 0) {
            fprintf(stderr, "Invalid sensitivity value. Using default: %f\n", DEFAULT_SENSITIVITY);
            sensitivity = DEFAULT_SENSITIVITY;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize ALSA (Placeholder)
    if (initialize_alsa() != 0) {
        fprintf(stderr, "ALSA initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    struct timeval start, end;
    long seconds, microseconds;
    double elapsed;

    // Main loop
    while (running) {
        gettimeofday(&start, NULL);

        // Capture audio
        AudioBuffer audio_buffer = capture_audio();

        // Calculate RMS amplitude
        float rms = calculate_rms(audio_buffer);

        // Map RMS to color
        int red, green, blue;
        map_rms_to_color(rms, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        gettimeofday(&end, NULL);
        seconds = end.tv_sec - start.tv_sec;
        microseconds = end.tv_usec - start.tv_usec;
        elapsed = seconds + microseconds*1e-6;

        // Delay to achieve 10ms processing time
        if (elapsed < 0.01) {
            usleep((0.01 - elapsed) * 1000000); // Convert seconds to microseconds
        }

        // Print status message (optional)
        // printf("RMS: %f, Red: %d, Green: %d, Blue: %d\n", rms, red, green, blue);
    }

    // Cleanup resources
    cleanup();

    return 0;
}

