#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Integration time (154ms)
#define TCS34725_INTEGRATION_TIME 0xD5 // 101ms

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold color data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} color_data_t;

// Function prototypes
int init_tcs34725();
color_data_t read_tcs34725();
void log_data(color_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

// Initialize TCS34725 sensor
int init_tcs34725() {
    // Enable the sensor (power on and enable RGBC)
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ENABLE: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, TCS34725_INTEGRATION_TIME) < 0) {
        fprintf(stderr, "Error writing to TCS34725_ATIME: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read color data from TCS34725 sensor
color_data_t read_tcs34725() {
    color_data_t data;
    data.clear = 0; data.red = 0; data.green = 0; data.blue = 0; // Initialize to zero in case of error

    // Read clear, red, green, and blue values
    int c = i2cReadWordData(i2c_handle, TCS34725_CDATA);
    int r = i2cReadWordData(i2c_handle, TCS34725_RDATA);
    int g = i2cReadWordData(i2c_handle, TCS34725_GDATA);
    int b = i2cReadWordData(i2c_handle, TCS34725_BDATA);

    if (c < 0 || r < 0 || g < 0 || b < 0) {
        fprintf(stderr, "Error reading color data: %s\n", strerror(errno));
        return data; // Return zeroed data on error
    }

    data.clear = (uint16_t)c;
    data.red = (uint16_t)r;
    data.green = (uint16_t)g;
    data.blue = (uint16_t)b;

    return data;
}

// Log data to CSV file
void log_data(color_data_t data) {
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", now, data.clear, data.red, data.green, data.blue);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (init_tcs34725() < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "timestamp,C,R,G,B\n");
    }
    fflush(fp);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read color data
        color_data_t data = read_tcs34725();

        // Log data
        log_data(data);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

