// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 52440

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a relay (active-low)
void set_relay_state(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO pin %d\n", gpio_pin);
        gpioTerminate();
        exit(1);
    }
}

// Function to simulate the sunrise phase
void sunrise_phase() {
    printf("Sunrise phase started\n");
    for (int i = 0; i <= 100; i++) {
        if (!program_running) return;
        set_relay_state(RELAY1_PIN, i == 0 ? 0 : 1);
        set_relay_state(RELAY2_PIN, i == 0 ? 0 : 1);
        set_relay_state(RELAY3_PIN, i == 0 ? 0 : 1);
        set_relay_state(RELAY4_PIN, i == 0 ? 0 : 1);
        gpioDelay(SUNRISE_DURATION / 100); // Delay for 1% of the sunrise duration
    }
    printf("Sunrise phase completed\n");
}

// Function to simulate the daytime phase
void daytime_phase() {
    printf("Daytime phase started\n");
    set_relay_state(RELAY1_PIN, 1);
    set_relay_state(RELAY2_PIN, 1);
    set_relay_state(RELAY3_PIN, 1);
    set_relay_state(RELAY4_PIN, 1);
    gpioDelay(DAYTIME_DURATION);
    printf("Daytime phase completed\n");
}

// Function to simulate the sunset phase
void sunset_phase() {
    printf("Sunset phase started\n");
    for (int i = 100; i >= 0; i--) {
        if (!program_running) return;
        set_relay_state(RELAY1_PIN, i == 100 ? 1 : 0);
        set_relay_state(RELAY2_PIN, i == 100 ? 1 : 0);
        set_relay_state(RELAY3_PIN, i == 100 ? 1 : 0);
        set_relay_state(RELAY4_PIN, i == 100 ? 1 : 0);
        gpioDelay(SUNSET_DURATION / 100); // Delay for 1% of the sunset duration
    }
    printf("Sunset phase completed\n");
}

// Function to simulate the nighttime phase
void nighttime_phase() {
    printf("Nighttime phase started\n");
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);
    gpioDelay(NIGHTTIME_DURATION);
    printf("Nighttime phase completed\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        sunrise_phase();
        daytime_phase();
        sunset_phase();
        nighttime_phase();
    }

    // Turn off all relays before exiting
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

