#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_DIR "/home/pi/logs/"
#define LOG_FILE "motion_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a motion event to the log file
int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to capture a video using raspivid
int capture_video(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s -t 5000", filename);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspivid command.\n");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid command failed with exit status %d.\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

// Function to handle motion detection and trigger actions
void handle_motion() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp.\n");
        return;
    }

    // Create video filename
    char video_filename[64];
    snprintf(video_filename, sizeof(video_filename), "%s%s.h264", VIDEO_DIR, timestamp);

    // Log the motion event
    if (log_motion_event(timestamp) != 0) {
        fprintf(stderr, "Error logging motion event.\n");
    }

    // Capture the video
    if (capture_video(video_filename) != 0) {
        fprintf(stderr, "Error capturing video.\n");
    }

    free(timestamp);
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Create log directory if it doesn't exist
    char command[64];
    snprintf(command, sizeof(command), "mkdir -p %s", LOG_DIR);
    if (system(command) == -1) {
        fprintf(stderr, "Error creating log directory.\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_DIR LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

