#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// MPU-6050 I2C address (AD0 low)
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor for +/- 250 deg/s range
#define GYRO_SCALE 131.0

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int init_mpu6050(int fd);
int read_gyro_data(int fd, float *x, float *y, float *z);
int log_data(FILE *fp, float x, float y, float z);
void signal_handler(int sig);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// I2C initialization function
int init_i2c(int bus, int addr) {
    int fd;
    char filename[20];

    snprintf(filename, 19, "/dev/i2c-%d", bus);
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU-6050 initialization function
int init_mpu6050(int fd) {
    uint8_t data;

    // Wake up the MPU-6050 (clear sleep mode bit)
    data = 0x00;
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }

    // Configure gyroscope range to +/- 250 deg/s
    data = 0x00; // 0x00 = +/- 250 deg/s
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to GYRO_CONFIG register");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    uint8_t buffer[6];

    // Read 6 bytes of data starting from GYRO_XOUT_H
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

// Function to log data to file
int log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    char timestamp[30];

    // Get current timestamp with millisecond precision
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting timestamp");
        return -1;
    }

    // Format timestamp as YYYY-MM-DD HH:MM:SS.mmm
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    // Write data to file
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written immediately

    return 0;
}

// Cleanup function
void cleanup(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    float x, y, z;
    int retry_count;
    struct timespec sleep_time = {0, 10000000}; // 10 ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    retry_count = 0;
    while (retry_count < 3) {
        i2c_fd = init_i2c(1, MPU6050_ADDR);
        if (i2c_fd != -1) {
            break;
        }
        retry_count++;
        sleep(1); // Wait before retrying
    }
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to initialize I2C after multiple retries.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize MPU-6050
    retry_count = 0;
    while (retry_count < 3) {
        if (init_mpu6050(i2c_fd) == 0) {
            break;
        }
        retry_count++;
        sleep(1); // Wait before retrying
    }
    if (retry_count == 3) {
        fprintf(stderr, "Failed to initialize MPU-6050 after multiple retries.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Log data to file
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data.\n");
        }

        // Sleep for 10 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

