#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variable for the log file pointer
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor(int zone);
void control_relay(int zone, int state);
void log_data(int zone, int moisture, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Deactivate all relays
    control_relay(1, 1);
    control_relay(2, 1);
    control_relay(3, 1);
    control_relay(4, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Ensure all relays are initially off (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0; // Indicate success
}

// Function to simulate reading the moisture sensor
int read_moisture_sensor(int zone) {
    // Seed the random number generator with the current time and zone number
    unsigned int seed = time(NULL) + zone;
    srand(seed);

    // Generate a random moisture value between 0 and 100
    return rand() % 101;
}

// Function to control the relay (activate or deactivate)
void control_relay(int zone, int state) {
    int pin;

    // Determine the GPIO pin based on the zone number
    switch (zone) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid zone number: %d\n", zone);
            return; // Exit the function if the zone number is invalid
    }

    // Set the GPIO pin to the specified state
    gpioWrite(pin, state);

    // Log the relay state change
    log_data(zone, -1, state); // -1 indicates that moisture reading is not applicable here
}

// Function to log the sensor reading and relay state to a file
void log_data(int zone, int moisture, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return; // Exit the function if the log file cannot be opened
    }

    // Write the data to the log file
    fprintf(log_file, "%s, Zone %d, Moisture: %d, Relay: %s\n", timestamp, zone, moisture, (relay_state == 0) ? "ON" : "OFF");

    // Close the log file
    fclose(log_file);
}

int main() {
    // Install signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Main loop
    while (1) {
        // Iterate through each zone (1-4)
        for (int zone = 1; zone <= 4; zone++) {
            // Read the moisture sensor value
            int moisture = read_moisture_sensor(zone);

            // Determine the relay state based on the moisture value
            int relay_state = (moisture < 30) ? 0 : 1; // 0 = ON, 1 = OFF

            // Control the relay
            control_relay(zone, relay_state);

            // Log the data
            log_data(zone, moisture, relay_state);
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds = 5000000 microseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

