#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Free-fall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Free-fall duration (seconds)
#define FREEFALL_DURATION 0.5

// Alarm GPIO pin (BCM numbering)
#define ALARM_GPIO 27

// Global variables
int i2c_handle;
bool running = true;

// Function prototypes
int init_adxl345();
int read_acceleration(float *x, float *y, float *z);
bool is_freefall(float x, float y, float z);
void trigger_alarm();
void log_freefall(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the ADXL345
int init_adxl345() {
    // Set POWER_CTL register to start measurement
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to ADXL345_REG_POWER_CTL: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char data[6];
    int16_t x_raw, y_raw, z_raw;

    // Read 6 bytes of data starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    x_raw = (int16_t)((data[1] << 8) | data[0]);
    y_raw = (int16_t)((data[3] << 8) | data[2]);
    z_raw = (int16_t)((data[5] << 8) | data[4]);

    // Convert to g-force units (assuming +/- 2g range and 10-bit resolution)
    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

