    running = false;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Set alarm GPIO low
    gpioWrite(ALARM_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure it starts low

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    accelerometer_data_t first_reading, second_reading;
    time_t start_time, current_time;

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(&first_reading.x, &first_reading.y, &first_reading.z) == 0) {
            // Check for free-fall
            if (is_freefall(first_reading.x, first_reading.y, first_reading.z)) {
                start_time = time(NULL);

                // Wait for FREEFALL_DURATION seconds
                gpioDelay(FREEFALL_DURATION * 1000); // Convert seconds to milliseconds

                // Read acceleration data again
                if (read_acceleration(&second_reading.x, &second_reading.y, &second_reading.z) == 0) {
                    // Check if still in free-fall
                    if (is_freefall(second_reading.x, second_reading.y, second_reading.z)) {
                        printf("Free-fall detected!\n");

                        // Trigger alarm
                        trigger_alarm();

                        // Log the event
                        log_freefall(first_reading.x, first_reading.y, first_reading.z);
                    }
                }
            }
        }

        // Wait 100ms
        gpioDelay(100);
    }

