#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_WIDTH 10 // microseconds
#define MAX_PULSE_WIDTH 23200  // microseconds (4 meters)
#define TIMEOUT_US 100000      // 100 ms timeout
#define MIN_DISTANCE_CM 2      // Minimum valid distance (cm)
#define MAX_DISTANCE_CM 400    // Maximum valid distance (cm)

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static pthread_mutex_t mutex;
static FILE *log_file = NULL;
static volatile int running = 1; // Flag to control the main loop

// Function prototypes
void trigger_pulse();
void echo_rising_edge_callback(int gpio, int level, uint32_t tick);
void echo_falling_edge_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(uint32_t timestamp_ns, double distance_cm);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_WIDTH);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for rising edge of ECHO signal
void echo_rising_edge_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    start_tick = tick;
    echo_received = 1; // Indicate that the rising edge has been received
    pthread_mutex_unlock(&mutex);
}

// Callback function for falling edge of ECHO signal
void echo_falling_edge_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    end_tick = tick;
    echo_received = 2; // Indicate that the falling edge has been received
    pthread_mutex_unlock(&mutex);
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    // Speed of sound in air (cm/us) = 0.0343 cm/us
    // Distance = (Time * Speed of Sound) / 2
    return (double)pulse_width * 0.0343 / 2.0;
}

// Function to log distance to file
void log_distance(uint32_t timestamp_ns, double distance_cm) {
    if (log_file != NULL) {
        fprintf(log_file, "%u,%.2f\n", timestamp_ns, distance_cm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop

    // Disable interrupts
    gpioSetAlertFuncEx(ECHO_PIN, 0, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Terminate pigpio
    gpioTerminate();

    // Destroy mutex
    pthread_mutex_destroy(&mutex);

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt callbacks
    gpioSetAlertFuncEx(ECHO_PIN, echo_rising_edge_callback, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, echo_falling_edge_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for echo or timeout
        echo_received = 0; // Reset echo_received flag
        uint32_t start_time = gpioTick();
        while (echo_received < 2 && (gpioTick() - start_time) < TIMEOUT_US && running) {
            gpioDelay(10); // Small delay to avoid busy-waiting
        }

        // Calculate pulse width and distance
        uint32_t pulse_width = 0;
        double distance_cm = -1.0; // Initialize to an invalid value

        pthread_mutex_lock(&mutex);
        if (echo_received == 2) {
            if (end_tick > start_tick) {
                pulse_width = end_tick - start_tick;
            } else {
                pulse_width = (0xFFFFFFFF - start_tick) + end_tick + 1; // Handle tick counter wrap-around
            }

            if (pulse_width > 0 && pulse_width <= MAX_PULSE_WIDTH) {
                distance_cm = calculate_distance(pulse_width);

                // Validate distance
                if (distance_cm >= MIN_DISTANCE_CM && distance_cm <= MAX_DISTANCE_CM) {
                    // Get timestamp
                    struct timespec ts;
                    clock_gettime(CLOCK_REALTIME, &ts);
                    uint32_t timestamp_ns = (uint32_t)(ts.tv_sec * 1000000000ULL + ts.tv_nsec);

                    // Log distance
                    log_distance(timestamp_ns, distance_cm);
                } else {
                    fprintf(stderr, "Invalid distance: %.2f cm\n", distance_cm);
                }
            } else {
                fprintf(stderr, "Invalid pulse width: %u us\n", pulse_width);
            }
        } else {
            fprintf(stderr, "Timeout waiting for echo\n");
        }
        pthread_mutex_unlock(&mutex);

        // Wait before next measurement
        gpioDelay(200000); // 200 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetAlertFuncEx(ECHO_PIN, 0, NULL);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&mutex);

    return 0;
}

