#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f
#define BUZZER_GPIO 17
#define ACCEL_RANGE 2.0f // +/- 2g
#define SENSITIVITY (ACCEL_RANGE / 32768.0f) // Sensitivity for +/- 2g range

// LIS3DH Registers
#define LIS3DH_REG_WHO_AM_I 0x0F
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

// Global variables
static int i2c_handle;
static volatile sig_atomic_t terminate = 0;
static float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
static float impact_threshold = DEFAULT_IMPACT_THRESHOLD;
static int lis3dh_address = 0x18; // Default I2C address

// Function prototypes
int init_i2c(int bus, int addr);
int init_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
bool detect_freefall(float magnitude, float threshold);
bool detect_impact(float magnitude, float threshold);
void activate_buzzer(int gpio_pin, int duration_ms);
void signal_handler(int signal);
void cleanup(int i2c_handle);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to initialize LIS3DH
int init_lis3dh(int i2c_handle) {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, LIS3DH_REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x33) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure CTRL1 register (ODR = 100Hz, Enable all axes)
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL1 register\n");
        return -1;
    }

    // Configure CTRL4 register (Full scale = +/-2g)
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL4 register\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char raw_data[6];
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L | 0x80, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g-force units
    *x = (float)x_raw * SENSITIVITY;
    *y = (float)y_raw * SENSITIVITY;
    *z = (float)z_raw * SENSITIVITY;

    return 0;
}

// Function to calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Function to detect freefall
bool detect_freefall(float magnitude, float threshold) {
    return magnitude < threshold;
}

// Function to detect impact
bool detect_impact(float magnitude, float threshold) {
    return magnitude > threshold;
}

// Function to activate the buzzer
void activate_buzzer(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn buzzer on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(gpio_pin, 0); // Turn buzzer off
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup(int i2c_handle) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioSetMode(BUZZER_GPIO, PI_INPUT); // Set GPIO back to input mode
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:f:i:")) != -1) {
        switch (opt) {
            case 'a':
                lis3dh_address = strtol(optarg, NULL, 0);
                break;
            case 'f':
                freefall_threshold = strtof(optarg, NULL);
                break;
            case 'i':
                impact_threshold = strtof(optarg, NULL);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-f freefall_threshold] [-i impact_threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, lis3dh_address);
    if (i2c_handle < 0) {
        cleanup(-1);
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh(i2c_handle) < 0) {
        cleanup(i2c_handle);
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is initially off

    float x, y, z, magnitude;
    bool freefall = false;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Calculate acceleration magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Detect freefall
            if (detect_freefall(magnitude, freefall_threshold)) {
                freefall = true;
            }

            // Detect impact
            if (freefall && detect_impact(magnitude, impact_threshold)) {
                printf("Impact detected!\n");
                activate_buzzer(BUZZER_GPIO, 1000); // Activate buzzer for 1 second
                freefall = false; // Reset freefall flag
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(10); // Delay for 10ms (adjust as needed)
    }

    // Cleanup and exit
    cleanup(i2c_handle);
    return 0;
}

