        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return;
    }

    for (int i = 0; i < steps; i++) {
        int step_index = (i * direction) % 4;
        if (step_index < 0) {
            step_index += 4; // Handle negative modulo
        }

        gpioWrite(in1, step_sequence[step_index][0]);
        gpioWrite(in2, step_sequence[step_index][1]);
        gpioWrite(in3, step_sequence[step_index][2]);
        gpioWrite(in4, step_sequence[step_index][3]);

        gpioDelay(STEP_DELAY);
    }
}

// Function to draw a square
void draw_square() {
    // Calculate the number of steps required to move 50mm
    float steps_per_mm = (float)STEPS_PER_REVOLUTION / (25.4 * GEAR_RATIO); // 25.4 mm/rev
    int steps = (int)(SQUARE_SIDE * steps_per_mm);

    // Move X-axis forward
    move_motor(1, steps, 1);

    // Move Y-axis forward
    move_motor(2, steps, 1);

    // Move X-axis backward
    move_motor(1, steps, -1);

    // Move Y-axis backward
    move_motor(2, steps, -1);
}

// Function to stop both motors
void stop_motors() {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);

    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    stop_motors();
    gpioTerminate();
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    stop_motors();
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Drawing a square...\n");
    draw_square();

    printf("Square drawing complete.\n");

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

