// LIS3DH Registers
#define LIS3DH_REG_CTRL1   0x20
#define LIS3DH_REG_CTRL4   0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

// Default values
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0f

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
float threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int config_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
void log_acceleration(float x, float y, float z);
void shutdown_system();
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize I2C
int init_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the LIS3DH
int config_lis3dh(int i2c_handle) {
    // CTRL_REG1: 0x27 (ODR = 100Hz, Enable X, Y, Z axes)
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL1, 0x27) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // CTRL_REG4: 0x88 (High resolution, 12-bit left justified, +/- 2g)
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL4, 0x88) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = 0.0f;
        *y = 0.0f;
        *z = 0.0f;
        return -1;
    }

    // Combine high and low bytes, left-justify 12-bit data
    raw_x = ((int16_t)buffer[1] << 8) | buffer[0];
    raw_x = raw_x << 4; // Left justify
    raw_x = raw_x >> 4; // Sign extend

    raw_y = ((int16_t)buffer[3] << 8) | buffer[2];
    raw_y = raw_y << 4;
    raw_y = raw_y >> 4;

    raw_z = ((int16_t)buffer[5] << 8) | buffer[4];
    raw_z = raw_z << 4;
    raw_z = raw_z >> 4;

    // Convert to g (assuming +/- 2g range)
    *x = (float)raw_x / 16384.0f; // 2^11 = 2048 * 2 = 4096 / 2 = 2048
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

// Function to log acceleration data
void log_acceleration(float x, float y, float z) {
    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", s, x, y, z);
    fclose(fp);
}

// Function to shutdown the system
void shutdown_system() {
    printf("Shutting down system...\n");
    system("sudo shutdown -h now");
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x03 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Using default 0x%02X\n", DEFAULT_I2C_ADDRESS);
                    i2c_address = DEFAULT_I2C_ADDRESS;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Invalid threshold. Using default 2.0 g\n");
                    threshold = DEFAULT_THRESHOLD;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 0;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 0;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) != 0) {
        gpioTerminate();
        return 0;
    }

    // Configure LIS3DH
    if (config_lis3dh(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    accelerometer_data_t accel_data;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            // Check for threshold exceedance
            if (fabs(accel_data.x) > threshold || fabs(accel_data.y) > threshold || fabs(accel_data.z) > threshold) {
                log_acceleration(accel_data.x, accel_data.y, accel_data.z);
                shutdown_system();
                break; // Exit loop after shutdown is initiated
            }
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

