// Circular buffer structure
typedef struct {
    int left[5];
    int center[5];
    int right[5];
    int index;
} CircularBuffer;

// Global variables
CircularBuffer buffer;
int running = 1;

// Function prototypes
int readSensor(int gpio);
void addToBuffer(CircularBuffer *buffer, int left, int center, int right);
int checkLineLost(CircularBuffer *buffer);
void signalHandler(int signal);

// Function to read sensor value
int readSensor(int gpio) {
    return gpioRead(gpio);
}

// Function to add sensor readings to the circular buffer
void addToBuffer(CircularBuffer *buffer, int left, int center, int right) {
    buffer->left[buffer->index] = left;
    buffer->center[buffer->index] = center;
    buffer->right[buffer->index] = right;
    buffer->index = (buffer->index + 1) % 5;
}

// Function to check if the line has been lost for 5 consecutive readings
int checkLineLost(CircularBuffer *buffer) {
    for (int i = 0; i < 5; i++) {
        if (buffer->center[i] == 0) {
            return 0; // Line detected
        }
    }
    return 1; // Line lost
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(ALERT_LED, 0); // Turn off alert LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_LED, PI_OUTPUT);

    // Initialize circular buffer
    buffer.index = 0;

    // Set up signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int left = readSensor(LEFT_SENSOR);
        int center = readSensor(CENTER_SENSOR);
        int right = readSensor(RIGHT_SENSOR);

        // Add readings to the circular buffer
        addToBuffer(&buffer, left, center, right);

        // Check if the line has been lost
        if (checkLineLost(&buffer)) {
            gpioWrite(ALERT_LED, 1); // Turn on alert LED
            gpioDelay(2000); // Wait for 2 seconds
            gpioWrite(ALERT_LED, 0); // Turn off alert LED
        } else {
            // Determine motor control based on sensor readings
            if (center == 0) {
                moveForward();
            } else if (left == 0) {
                turnLeft();
            } else if (right == 0) {
                turnRight();
            } else {
                stop();
            }
        }

        gpioDelay(10); // Delay for 10 milliseconds
    }

    return 0;
}

