#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define PORT 5000
#define BUFFER_SIZE 1024

// Global variables for signal handling
static volatile int keep_running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int create_socket();
int bind_socket(int server_fd);
int listen_socket(int server_fd);
int accept_connection(int server_fd);
int receive_command(int client_fd, char *buffer, int buffer_size);
int process_command(char *command);
int control_relay(int state);
int log_event(const char *event);
void signal_handler(int signal);

// Function to initialize the pigpio library and set the GPIO mode
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    return 0;
}

// Function to create a socket
int create_socket() {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Socket creation failed");
        return -1;
    }
    return server_fd;
}

// Function to bind the socket to a port
int bind_socket(int server_fd) {
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        return -1;
    }
    return 0;
}

// Function to listen for incoming connections
int listen_socket(int server_fd) {
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        return -1;
    }
    return 0;
}

// Function to accept an incoming connection
int accept_connection(int server_fd) {
    int client_fd;
    struct sockaddr_in client_address;
    int addrlen = sizeof(client_address);

    client_fd = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen);
    if (client_fd < 0) {
        perror("Accept failed");
        return -1;
    }
    return client_fd;
}

// Function to receive a command from the client
int receive_command(int client_fd, char *buffer, int buffer_size) {
    ssize_t bytes_received = recv(client_fd, buffer, buffer_size - 1, 0);
    if (bytes_received < 0) {
        perror("Receive failed");
        return -1;
    }
    buffer[bytes_received] = '\0'; // Null-terminate the received data
    return 0;
}

// Function to process the received command
int process_command(char *command) {
    // Remove trailing whitespace
    char *end = command + strlen(command) - 1;
    while (end > command && (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r')) {
        *end = '\0';
        end--;
    }

    if (strcasecmp(command, "ON") == 0) {
        return 1; // Turn ON
    } else if (strcasecmp(command, "OFF") == 0) {
        return 0; // Turn OFF
    } else {
        return -1; // Invalid command
    }
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Function to log events to a file
int log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }
}

// Signal handler function
void signal_handler(int signal) {
    keep_running = 0;
    printf("Signal received, shutting down...\n");

    // Turn off the relay
    control_relay(0);

    // Close the socket
    if (server_fd != -1) {
        close(server_fd);
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Create socket
    server_fd = create_socket();
    if (server_fd == -1) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Bind socket
    if (bind_socket(server_fd) != 0) {
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen_socket(server_fd) != 0) {
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    while (keep_running) {
        // Accept connection
        int client_fd = accept_connection(server_fd);
        if (client_fd == -1) {
            continue; // Continue listening for new connections
        }

        char buffer[BUFFER_SIZE];

        // Receive command
        if (receive_command(client_fd, buffer, BUFFER_SIZE) == 0) {
            // Process command
            int command_result = process_command(buffer);

            if (command_result == 1) {
                // Turn ON
                control_relay(1);
                log_event("Relay turned ON");
            } else if (command_result == 0) {
                // Turn OFF
                control_relay(0);
                log_event("Relay turned OFF");
            } else {
                // Invalid command
                log_event("Invalid command received");
            }
        }

        // Close client socket
        close(client_fd);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(server_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

