#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0f
#define START_MEASUREMENT_CMD_1 0x36
#define START_MEASUREMENT_CMD_2 0x08
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int start_measurement(int i2c_handle);
int read_sensor_data(int i2c_handle, uint8_t *data);
uint8_t calculate_crc8(const uint8_t *data, size_t len);
float convert_to_flow_rate(const uint8_t *data);
void log_flow_data(float flow1, float flow2);
void control_relay(int state);
void signal_handler(int signal);
int initialize();
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to start measurement on the sensor
int start_measurement(int i2c_handle) {
    char cmd[2] = {START_MEASUREMENT_CMD_1, START_MEASUREMENT_CMD_2};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to convert raw data to flow rate (ml/min)
float convert_to_flow_rate(const uint8_t *data) {
    int16_t raw_flow = (data[0] << 8) | data[1];
    // Conversion factor from datasheet (example value, adjust as needed)
    float flow_rate = (float)raw_flow / 120.0f; // Example conversion
    return flow_rate;
}

// Function to log flow data to file
void log_flow_data(float flow1, float flow2) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), 10, ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(log_file);
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus for sensor 1
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return -1;
    }

    // Open I2C bus for sensor 2
    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return -1;
    }

    // Start measurement on both sensors
    if (start_measurement(i2c_handle1) != 0 || start_measurement(i2c_handle2) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }

    // Configure relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // De-energize the relay
    control_relay(0);

    // Close I2C handles
