    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // De-energize the relay
    control_relay(0);

    // Close I2C handles
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
