#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control constants
#define MOTOR_FORWARD 1
#define MOTOR_BACKWARD 0
#define MOTOR_STOP 0

// Define debounce count
#define DEBOUNCE_COUNT 3

// Global variables
volatile sig_atomic_t program_running = 1;
int rain_detected = 0;
int debounce_counter = 0;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction);
void stop_motor();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to read the rain sensor
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        log_message(LOG_ERR, "Failed to read rain sensor.");
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to control the motor
void control_motor(int direction) {
    int ena_result, in1_result, in2_result;

    ena_result = gpioWrite(MOTOR_ENA_PIN, 1); // Enable motor
    if (ena_result < 0) {
        log_message(LOG_ERR, "Failed to write to ENA pin.");
        return;
    }

    in1_result = gpioWrite(MOTOR_IN1_PIN, direction);
    if (in1_result < 0) {
        log_message(LOG_ERR, "Failed to write to IN1 pin.");
        return;
    }

    in2_result = gpioWrite(MOTOR_IN2_PIN, !direction);
    if (in2_result < 0) {
        log_message(LOG_ERR, "Failed to write to IN2 pin.");
        return;
    }

    log_message(LOG_INFO, "Motor started.");
}

// Function to stop the motor
void stop_motor() {
    int ena_result, in1_result, in2_result;

    ena_result = gpioWrite(MOTOR_ENA_PIN, 0);
    if (ena_result < 0) {
        log_message(LOG_ERR, "Failed to write to ENA pin.");
        return;
    }

    in1_result = gpioWrite(MOTOR_IN1_PIN, 0);
    if (in1_result < 0) {
        log_message(LOG_ERR, "Failed to write to IN1 pin.");
        return;
    }

    in2_result = gpioWrite(MOTOR_IN2_PIN, 0);
    if (in2_result < 0) {
        log_message(LOG_ERR, "Failed to write to IN2 pin.");
        return;
    }

    log_message(LOG_INFO, "Motor stopped.");
}

