            // Error reading sensor, continue to next iteration
            gpioDelay(200000); // 200ms
            continue;
        }

        if (sensor_value == 0) { // Rain detected (sensor pulls low)
            debounce_counter++;
            if (debounce_counter >= DEBOUNCE_COUNT && !rain_detected) {
                log_message(LOG_INFO, "Rain detected!");
                rain_detected = 1;
                control_motor(MOTOR_FORWARD); // Start closing window
                gpioDelay(5000000); // 5 seconds
                stop_motor();
                debounce_counter = 0; // Reset debounce counter
            }
        } else { // Dry
            debounce_counter = 0; // Reset debounce counter
            if (rain_detected) {
                log_message(LOG_INFO, "Rain stopped.");
                rain_detected = 0;
            }
        }

        gpioDelay(200000); // 200ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();
    log_message(LOG_INFO, "pigpio terminated.");
    closelog();

    return 0;
}

