#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define pulse widths for servo control
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000
#define STOP_PULSE_WIDTH 0

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program state for signal handler
volatile sig_atomic_t program_running = 1;

// Function prototypes
int lock_door();
int unlock_door();
int stop_servo();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping servo and exiting...\n", signal);
    stop_servo();
    gpioTerminate();
    exit(0);
}

// Function to lock the door
int lock_door() {
    int result = gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to lock door. gpioServo returned %d\n", result);
        return -1;
    }
    printf("Door locked\n");
    return 0;
}

// Function to unlock the door
int unlock_door() {
    int result = gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to unlock door. gpioServo returned %d\n", result);
        return -1;
    }
    printf("Door unlocked\n");
    return 0;
}

// Function to stop the servo
int stop_servo() {
    int result = gpioServo(SERVO_PIN, STOP_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to stop servo. gpioServo returned %d\n", result);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on button pins
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check lock button
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            lock_door();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            while (gpioRead(LOCK_BUTTON_PIN) == 0) {
                gpioDelay(1000); // Wait for button release
            }
        }

        // Check unlock button
        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            unlock_door();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            while (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                gpioDelay(1000); // Wait for button release
            }
        }

        gpioDelay(1000); // Small delay to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_servo();
    gpioTerminate();
    return 0;
}

