#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>

// MPR121 I2C address
#define MPR121_ADDRESS 0x5A

// MPR121 registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_BASELINE_FILTERING_MHD 0x2B
#define MPR121_BASELINE_FILTERING_NHD 0x2C
#define MPR121_BASELINE_FILTERING_NCL 0x2D
#define MPR121_BASELINE_FILTERING_FDL 0x2E
#define MPR121_DEBOUNCE 0x2F
#define MPR121_FFI_SFI_CDT 0x30
#define MPR121_AUTO_CONFIG 0x31
#define MPR121_SOFTRESET 0x80

// GPIO pin for relay control
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
int mpr121_fd;
bool relay_state = false;
unsigned long last_touch_time = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status();
void relay_on();
void relay_off();
void signal_handler(int signal);

// Function to initialize the MPR121
int mpr121_init() {
    // Soft reset
    if (wiringPiI2CWriteReg8(mpr121_fd, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    delay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (wiringPiI2CWriteReg8(mpr121_fd, MPR121_BASELINE_FILTERING_MHD, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(mpr121_fd, MPR121_BASELINE_FILTERING_NHD, 0x01) < 0) return -1;
    if (wiringPiI2CWriteReg8(mpr121_fd, MPR121_BASELINE_FILTERING_NCL, 0x0E) < 0) return -1;
    if (wiringPiI2CWriteReg8(mpr121_fd, MPR121_BASELINE_FILTERING_FDL, 0x00) < 0) return -1;

    // Set debounce time
    if (wiringPiI2CWriteReg8(mpr121_fd, MPR121_DEBOUNCE, 0x10) < 0) return -1;

    // Configure FFI, SFI, and CDT
    if (wiringPiI2CWriteReg8(mpr121_fd, MPR121_FFI_SFI_CDT, 0x24) < 0) return -1;

    // Enable auto-config
    if (wiringPiI2CWriteReg8(mpr121_fd, MPR121_AUTO_CONFIG, 0x0B) < 0) return -1;

    // Enable all 12 electrodes
    if (wiringPiI2CWriteReg8(mpr121_fd, MPR121_ELECTRODE_CONFIG, 0x3F) < 0) return -1;

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status() {
    int touch_status_l = wiringPiI2CReadReg8(mpr121_fd, MPR121_TOUCHSTATUS_L);
    int touch_status_h = wiringPiI2CReadReg8(mpr121_fd, MPR121_TOUCHSTATUS_H);

    if (touch_status_l < 0 || touch_status_h < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to turn the relay ON
void relay_on() {
    digitalWrite(RELAY_PIN, HIGH);
    relay_state = true;
    printf("Relay ON\n");
}

// Function to turn the relay OFF
void relay_off() {
    digitalWrite(RELAY_PIN, LOW);
    relay_state = false;
    printf("Relay OFF\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    relay_off(); // Ensure relay is OFF on exit
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi\n");
        return 1;
    }

    // Initialize I2C
    mpr121_fd = wiringPiI2CSetup(MPR121_ADDRESS);
    if (mpr121_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C communication.\n");
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() == -1) {
        fprintf(stderr, "Error: Failed to initialize MPR121\n");
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    relay_off(); // Ensure relay is OFF at startup

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            delay(100); // Small delay before retrying
            continue;
        }

        // Check for touch on electrode 0
        if (touch_status & 0x01) {
            unsigned long current_time = millis();
            if (current_time - last_touch_time > DEBOUNCE_TIME) {
                // Toggle relay state
                if (relay_state) {
                    relay_off();
                } else {
                    relay_on();
                }
                last_touch_time = current_time;
            }
        }

        delay(50); // Small delay to avoid busy-waiting
    }

    return 0;
}

