#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>
#include <stdarg.h>
#include <errno.h>

// Constants
#define SERVO_PIN 17
#define PIR_PIN 4
#define PWM_FREQUENCY 50
#define PWM_RANGE 20000 // 20ms period
#define PIR_READ_DELAY_MS 100
#define TCP_PORT 5000
#define LOG_FILE "security.log"

// Global variables
static int running = 1;
static int server_socket = -1;
static FILE *log_file = NULL;

// Function prototypes
void log_message(int priority, const char *format, ...);
int initialize_gpio();
int set_servo_angle(int angle);
int read_pir_sensor();
int handle_client(int client_socket);
void signal_handler(int signal);
int setup_tcp_server(int port);
void cleanup();

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Get current timestamp
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    // Log to syslog
    vsyslog(priority, format, args);

    // Log to file
    if (log_file != NULL) {
        fprintf(log_file, "%s ", timestamp);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }

    va_end(args);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_PIN, PWM_RANGE);

    gpioSetMode(PIR_PIN, PI_INPUT);

    return 0;
}

// Set servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }

    // Calculate pulse width (1ms - 2ms)
    int pulse_width = 1000 + (int)((float)angle / 180.0 * 1000.0);

    gpioPWM(SERVO_PIN, pulse_width);

    return 0;
}

// Read PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Handle client connection
int handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    while (running) {
        bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            log_message(LOG_INFO, "Received: %s", buffer);

            if (strncmp(buffer, "the library's API call ", 25) == 0) {
                int angle = atoi(buffer + 25);
                if (set_servo_angle(angle) == 0) {
                    log_message(LOG_INFO, "Servo angle set to: %d", angle);
                } else {
                    log_message(LOG_ERR, "Failed to set servo angle");
