#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static double threshold = DEFAULT_THRESHOLD;
static double scale_factor = DEFAULT_SCALE_FACTOR;
static int duration = DEFAULT_DURATION;
static int gpio_initialized = 0;

// Function prototypes
int read_hx711();
double tare_hx711();
double read_weight();
void control_solenoid(int activate);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to log messages using syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Function to read a single value from the HX711
int read_hx711() {
    int i;
    int data = 0;
    int timeout_count = 0;

    // Wait for DOUT to go low with timeout
    while (gpioRead(HX711_DOUT) == 1) {
        gpioDelay(1); // Wait 1 ms
        timeout_count++;
        if (timeout_count > 1000) { // Timeout after 1 second
            log_message(LOG_ERR, "HX711 DOUT timeout");
            return -1; // Indicate error
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT) == 1) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Apply channel A gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000; // Sign extend
    }

    return data;
}

// Function to tare the HX711
double tare_hx711() {
    int i;
    double sum = 0.0;
    int reading;

    log_message(LOG_INFO, "Starting tare...");
    for (i = 0; i < 10; i++) {
        reading = read_hx711();
        if (reading == -1) {
            log_message(LOG_ERR, "Tare failed: HX711 read error");
            return -1.0; // Indicate error
        }
        sum += reading;
        gpioDelay(50); // Small delay between readings
    }
    log_message(LOG_INFO, "Tare complete.");
    return sum / 10.0;
}

// Function to read the weight from the HX711
double read_weight() {
    int i;
    double sum = 0.0;
    int reading;

    for (i = 0; i < 5; i++) {
        reading = read_hx711();
        if (reading == -1) {
            log_message(LOG_ERR, "Weight read failed: HX711 read error");
            return -1.0; // Indicate error
        }
        sum += reading;
        gpioDelay(50); // Small delay between readings
    }
    return (sum / 5.0) * scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(int activate) {
    if (activate) {
        gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
        log_message(LOG_INFO, "Activating solenoid");
        gpioDelay(duration); // Keep activated for specified duration
        gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
        log_message(LOG_INFO, "Deactivating solenoid");
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is deactivated
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

int main(int argc, char *argv[]) {
    int opt;
    double weight;

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale_factor = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>]\n", argv[0]);
                closelog();
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }
    gpio_initialized = 1;

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Tare the HX711
    double tare_value = tare_hx711();
    if (tare_value == -1.0) {
        gpioTerminate();
        gpio_initialized = 0;
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "Weight monitoring started");

    // Main loop
    while (running) {
        weight = read_weight();
        if (weight != -1.0) {
            char log_buffer[100];
            snprintf(log_buffer, sizeof(log_buffer), "Weight: %.2f grams", weight);
            log_message(LOG_INFO, log_buffer);

            if (weight > threshold) {
                control_solenoid(1); // Activate solenoid
            }
        } else {
            log_message(LOG_ERR, "Failed to read weight");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup
    control_solenoid(0); // Ensure solenoid is deactivated
    if (gpio_initialized) {
        gpioTerminate();
    }
    closelog();

    return 0;
}

