#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function to set the GPIO pin state
void set_gpio_state(int state) {
    gpioWrite(GPIO_PIN, state);
}

// Function to handle MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "ON") == 0) {
            set_gpio_state(1); // Turn relay ON
            syslog(LOG_INFO, "Received ON command, setting GPIO %d HIGH", GPIO_PIN);
        } else if (strcmp(payload, "OFF") == 0) {
            set_gpio_state(0); // Turn relay OFF
            syslog(LOG_INFO, "Received OFF command, setting GPIO %d LOW", GPIO_PIN);
        } else {
            syslog(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received");
    }
}

// Function to handle MQTT connection
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic: %s", mosquitto_strerror(subscribe_result));
        }
    } else {
        syslog(LOG_ERR, "Connection failed: %s", mosquitto_strerror(result));
    }
}

// Function to handle MQTT disconnection
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "Disconnected from MQTT broker");
}

// Function to handle MQTT errors
void log_callback(struct mosquitto *mosq, void *userdata, const char *message) {
    syslog(LOG_ERR, "MQTT Error: %s", message);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    running = 0;
    syslog(LOG_INFO, "Signal received, exiting...");
}

int main() {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    set_gpio_state(0); // Initialize relay to OFF

    // Initialize MQTT client
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);
    mosquitto_log_callback_set(mosq, log_callback);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Connect to MQTT broker
    int connect_result = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (connect_result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(connect_result));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        int loop_result = mosquitto_loop(mosq, -1, 1);
        if (loop_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(loop_result));
            sleep(5);
            mosquitto_reconnect(mosq);
        }
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    set_gpio_state(0); // Ensure relay is OFF on exit
    gpioTerminate();
    closelog();

    return 0;
}

