#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

#define TARGET_RPM 50.0
#define ENCODER_TICKS_PER_REV 64.0
#define PWM_FREQUENCY 10000.0 // 10 kHz
#define CONTROL_INTERVAL_MS 100
#define STALL_TIMEOUT_S 2.0

// PI controller gains
#define Kp 1.0
#define Ki 0.1

// Global variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
double integral_a = 0.0;
double integral_b = 0.0;
time_t last_update_a = 0;
time_t last_update_b = 0;

// Function prototypes
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks, double time_elapsed);
double pi_controller(double target_rpm, double actual_rpm, double *integral);
void set_motor_speed(int motor_a_pwm, int motor_a_dir, int motor_b_pwm, int motor_b_dir, int duty_cycle_a, int duty_cycle_b);
void check_stall(int encoder_a_count, int encoder_b_count, time_t *last_update_a, time_t *last_update_b);
void signal_handler(int signal);

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);

    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Register interrupt handlers
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register encoder A A ISR\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register encoder A B ISR\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register encoder B A ISR\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register encoder B B ISR\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    time_t last_control_time = time(NULL);

    while (1) {
        time_t current_time = time(NULL);
        double time_elapsed = difftime(current_time, last_control_time);

