            double rpm_a = calculate_rpm(encoder_a_count, time_elapsed);
            double rpm_b = calculate_rpm(encoder_b_count, time_elapsed);

            // PI controller
            double duty_cycle_a = pi_controller(TARGET_RPM, rpm_a, &integral_a);
            double duty_cycle_b = pi_controller(TARGET_RPM, rpm_b, &integral_b);

