#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_THRESHOLD_DARK 50
#define LUX_THRESHOLD_LIGHT 200
#define HYSTERESIS 50
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_bh1750(float *lux);
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int relay_state;
    float last_lux;
} ProgramState;

ProgramState state = {0, 0.0}; // Initialize relay off and last lux 0

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO and I2C
    if (init_gpio() != 0 || init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    while (!terminate) {
        // Read light sensor
        if (read_bh1750(&lux) == 0) {
            // Control relay based on lux value
            if (lux < LUX_THRESHOLD_DARK && state.relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                state.relay_state = 1;
            } else if (lux > LUX_THRESHOLD_LIGHT && state.relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                state.relay_state = 0;
            }

            // Log data
            log_data(lux, relay_state);
        } else {
            // Log error and turn off relay
            log_data(-1.0, -1); // Indicate error
            control_relay(0);
            relay_state = 0;
            state.relay_state = 0;
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off initially
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read BH1750 sensor
int read_bh1750(float *lux) {
    char config_cmd = 0x10; // Continuous high-resolution mode
    char buf[2];
    int result;

    result = i2cWriteDevice(i2c_handle, &config_cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return 1;
    }

    gpioDelay(180000); // Wait 180ms

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return 1;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2; // Convert to Lux

    return 0;
}

// Control relay
void control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
}

// Log data to file
void log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (lux >= 0) {
        fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state == 1 ? "ON" : "OFF");
    } else {
        fprintf(log_file, "%s: Error reading sensor, Relay = %s\n", timestamp, relay_state == 1 ? "ON" : "OFF");
    }
    fflush(log_file);
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // Turn off relay
    gpioTerminate();
}

