#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Function prototypes
int read_touch_sensor();
int debounce_touch_sensor();
int toggle_relay(int current_state);
void log_relay_state(int state);
void signal_handler(int signal);

// Global variable to store the current relay state
int relay_state = 0;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        // Turn the relay OFF
        gpioWrite(RELAY_PIN, 0);
        // Release pigpio resources
        gpioTerminate();
        // Exit the program
        exit(0);
    }
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to debounce the touch sensor
int debounce_touch_sensor() {
    int i;
    for (i = 0; i < 5; i++) { // Check 5 times within the debounce delay
        if (gpioRead(TOUCH_SENSOR_PIN) == 0) { // If sensor is LOW, return 0 immediately
            return 0;
        }
        gpioDelay(DEBOUNCE_DELAY / 5); // Divide delay for faster response
    }
    return 1; // Return 1 only if sensor is HIGH for the entire debounce period
}

// Function to toggle the relay state
int toggle_relay(int current_state) {
    return !current_state;
}

// Function to log the relay state with timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Relay is %s\n", timestamp, state ? "ON" : "OFF");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;
    log_relay_state(relay_state);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read touch sensor
        int touch_detected = read_touch_sensor();

        // If touch is detected, debounce and toggle relay
        if (touch_detected) {
            if (debounce_touch_sensor()) {
                // Toggle relay state
                relay_state = toggle_relay(relay_state);

                // Write new relay state to GPIO
