#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIMEOUT_MS 1000

// Global variables
static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulses);
void control_solenoid(double lpm);
void log_message(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine for the flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data)
{
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;

    if (diff > DEBOUNCE_TIMEOUT_MS * 1000) // Convert ms to microseconds
    {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
        last_tick = tick;
    }
}

// Function to calculate LPM from pulse count
double calculate_lpm(int pulses)
{
    return (double)pulses / PULSES_PER_LITER * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double lpm)
{
    static int solenoid_state = 1; // 1 = open, 0 = closed

    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1)
    {
        gpioWrite(SOLENOID_GPIO, 0); // Close the solenoid
        solenoid_state = 0;
        log_message("Solenoid closed");
    }
    else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0)
    {
        gpioWrite(SOLENOID_GPIO, 1); // Open the solenoid
        solenoid_state = 1;
        log_message("Solenoid opened");
    }
}

// Function to log messages to a file
void log_message(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    }
    else
    {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    char message[50];
    snprintf(message, sizeof(message), "Signal received: %d. Shutting down...", signal);
    log_message(message);
    running = 0;
}

// Initialization function
int initialize()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);

    // Set initial solenoid state to open
    gpioWrite(SOLENOID_GPIO, 1);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0)
    {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup()
{
    // Close solenoid valve
    gpioWrite(SOLENOID_GPIO, 1);

    // Close log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();
}

int main()
{
    if (initialize() != 0)
    {
        return 1;
    }

    while (running)
    {
        // Read pulse count
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate LPM
        double lpm = calculate_lpm(current_pulse_count);

        // Control solenoid
        control_solenoid(lpm);

        // Log LPM reading
        char message[50];
        snprintf(message, sizeof(message), "LPM: %.2f", lpm);
        log_message(message);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    cleanup();
    return 0;
}

