#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>
#include <jansson.h>
#include <getopt.h>
#include <stdbool.h>

// Configuration structure
typedef struct {
    int data_pin;
    int sck_pin;
    int pwm_pin;
    int pwm_range;
    int pwm_frequency;
    double calibration_factor;
    char api_endpoint[256];
    char log_file[256];
} Config;

// Global variables
static int server_fd = 0;
static int client_fd = 0;
static Config config;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int sig);
int read_config(const char *filename, Config *config);
int init_gpio(const Config *config);
int read_hx711(const Config *config);
double calibrate_weight(int raw_value, const Config *config);
int dispense_ingredient(double target_weight, const Config *config);
int send_weight_to_api(double weight, const Config *config);
int log_dispensing_event(double target_weight, double actual_weight, const char *error_message, const Config *config);
int handle_client(int client_fd, const Config *config);
int start_server(const Config *config);

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open config file: %s, using defaults", filename);
        // Set default values
        config->data_pin = 23;
        config->sck_pin = 24;
        config->pwm_pin = 18;
        config->pwm_range = 1000000; // 1 second
        config->pwm_frequency = 50; // Hz
        config->calibration_factor = 1.0;
        strcpy(config->api_endpoint, "http://localhost:5000/weight");
        strcpy(config->log_file, "dispensing_log.json");
        return -1; // Indicate failure to open file, but continue with defaults
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "data_pin") == 0) {
            config->data_pin = atoi(value);
        } else if (strcmp(key, "sck_pin") == 0) {
            config->sck_pin = atoi(value);
        } else if (strcmp(key, "pwm_pin") == 0) {
            config->pwm_pin = atoi(value);
        } else if (strcmp(key, "pwm_range") == 0) {
            config->pwm_range = atoi(value);
        } else if (strcmp(key, "pwm_frequency") == 0) {
            config->pwm_frequency = atoi(value);
        } else if (strcmp(key, "calibration_factor") == 0) {
            config->calibration_factor = atof(value);
        } else if (strcmp(key, "api_endpoint") == 0) {
            strncpy(config->api_endpoint, value, sizeof(config->api_endpoint) - 1);
            config->api_endpoint[sizeof(config->api_endpoint) - 1] = '\0';
        } else if (strcmp(key, "log_file") == 0) {
            strncpy(config->log_file, value, sizeof(config->log_file) - 1);
            config->log_file[sizeof(config->log_file) - 1] = '\0';
        }
    }

    fclose(fp);
    return 0;
}

// Initialize GPIO
int init_gpio(const Config *config) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(config->data_pin, PI_INPUT);
    gpioSetMode(config->sck_pin, PI_OUTPUT);
    gpioSetMode(config->pwm_pin, PI_OUTPUT);

    gpioSetPWMrange(config->pwm_pin, config->pwm_range);
    gpioSetPWMfrequency(config->pwm_pin, config->pwm_frequency);

    return 0;
}

// Read HX711 value
int read_hx711(const Config *config) {
    int data = 0;
    int timeout = 0;

    gpioWrite(config->sck_pin, 0);
    gpioDelay(1); // 1 us delay

    while (gpioRead(config->data_pin)) {
        timeout++;
        if (timeout > 1000) {
            syslog(LOG_ERR, "HX711 timeout");
            return -1; // Indicate timeout
        }
        gpioDelay(1); // 1 us delay
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(config->sck_pin, 1);
        gpioDelay(1); // 1 us delay
        data = data << 1;
        if (gpioRead(config->data_pin)) {
            data++;
        }
        gpioWrite(config->sck_pin, 0);
        gpioDelay(1); // 1 us delay
    }

    gpioWrite(config->sck_pin, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(config->sck_pin, 0);
    gpioDelay(1); // 1 us delay

    data = data ^ 0x800000; // Two's complement

    return data;
}

// Calibrate weight
double calibrate_weight(int raw_value, const Config *config) {
    return (double)raw_value * config->calibration_factor;
}

// Dispense ingredient
int dispense_ingredient(double target_weight, const Config *config) {
    // Map target weight to pulse width (1000-2000 us)
    double pulse_width = 1000.0 + (target_weight / 100.0) * 1000.0; // Example mapping
    if (pulse_width < 1000.0) pulse_width = 1000.0;
    if (pulse_width > 2000.0) pulse_width = 2000.0;

    int pulse_width_int = (int)pulse_width;

    gpioPWM(config->pwm_pin, pulse_width_int); // Set PWM duty cycle
    gpioDelay(1000); // Wait 1 second for stabilization

    return 0;
}

// Send weight to API
int send_weight_to_api(double weight, const Config *config) {
    // Placeholder for API call using libcurl or similar
    // This example just prints the weight to the log
    syslog(LOG_INFO, "Sending weight to API: %.2f grams", weight);
    return 0;
}

// Log dispensing event
int log_dispensing_event(double target_weight, double actual_weight, const char *error_message, const Config *config) {
    json_t *root = json_object();
    json_t *timestamp = json_string(NULL);
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    json_string_set(timestamp, buf);

    json_object_set_new(root, "timestamp", timestamp);
    json_object_set_new(root, "target_weight", json_real(target_weight));
    json_object_set_new(root, "actual_weight", json_real(actual_weight));
    json_object_set_new(root, "error_message", json_string(error_message));

    FILE *fp = fopen(config->log_file, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", config->log_file);
        json_decref(root);
        return -1;
    }

    char *json_str = json_dumps(root, JSON_INDENT(4));
    fprintf(fp, "%s\n", json_str);
    fclose(fp);
    free(json_str);
    json_decref(root);

    return 0;
}

// Handle client connection
int handle_client(int client_fd, const Config *config) {
    char buffer[1024] = {0};
    ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Receive failed");
        return -1;
    }
    if (bytes_received == 0) {
        syslog(LOG_INFO, "Client disconnected");
        return -1;
    }

    double target_weight = atof(buffer);
    syslog(LOG_INFO, "Received target weight: %.2f grams", target_weight);

    int raw_value = read_hx711(config);
    if (raw_value < 0) {
        syslog(LOG_ERR, "Failed to read HX711 value");
        log_dispensing_event(target_weight, 0.0, "Failed to read HX711 value", config);
        send(client_fd, "Error: Failed to read HX711 value", strlen("Error: Failed to read HX711 value"), 0);
        return -1;
    }

    double actual_weight = calibrate_weight(raw_value, config);
    syslog(LOG_INFO, "Actual weight: %.2f grams", actual_weight);

    if (dispense_ingredient(target_weight, config) != 0) {
        syslog(LOG_ERR, "Failed to dispense ingredient");
        log_dispensing_event(target_weight, actual_weight, "Failed to dispense ingredient", config);
        send(client_fd, "Error: Failed to dispense ingredient", strlen("Error: Failed to dispense ingredient"), 0);
        return -1;
    }

    if (send_weight_to_api(actual_weight, config) != 0) {
        syslog(LOG_ERR, "Failed to send weight to API");
    }

    char response[50];
    snprintf(response, sizeof(response), "Weight: %.2f grams", actual_weight);
    send(client_fd, response, strlen(response), 0);

    log_dispensing_event(target_weight, actual_weight, "", config);

    return 0;
}

// Start server
int start_server(const Config *config) {
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        syslog(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Forcefully attaching socket to the port 12345
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        syslog(LOG_ERR, "Setsockopt failed");
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(12345);

    // Forcefully attaching socket to the port 12345
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        syslog(LOG_ERR, "Bind failed");
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        syslog(LOG_ERR, "Listen failed");
        return -1;
    }

    syslog(LOG_INFO, "Server listening on port 12345");

    while (!terminate) {
        int addrlen = sizeof(address);
        if ((client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            syslog(LOG_ERR, "Accept failed");
            continue; // Continue listening
        }

        syslog(LOG_INFO, "Client connected");
        if (handle_client(client_fd, config) != 0) {
            syslog(LOG_ERR, "Client handling failed");
        }
        close(client_fd);
        client_fd = 0; // Reset client_fd
    }

    return 0;
