int debounce_interval = 50; // Default debounce interval in milliseconds

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the touch sensor with debouncing
int read_touch_sensor(int gpio, int debounce_ms) {
    int i;
    int stable_count = 0;
    int current_state = gpioRead(gpio);

    for (i = 0; i < debounce_ms; i += 10) {
        gpioDelay(10000); // 10 ms delay
        if (gpioRead(gpio) == current_state) {
            stable_count++;
        } else {
            stable_count = 0; // Reset if state changes
        }
        if (stable_count * 10 >= debounce_ms) {
            return current_state;
        }
    }
    return current_state; // Return the last state if debouncing fails
}

// Function to toggle the relay state
void toggle_relay(int gpio) {
    int current_state = gpioRead(gpio);
    gpioWrite(gpio, !current_state);
}

// Function to log the relay state with timestamp
void log_relay_state(int gpio) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int state = gpioRead(gpio);

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

int main(int argc, char *argv[]) {
    int i;

    // Parse command-line arguments
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            debounce_interval = atoi(argv[i + 1]);
            if (debounce_interval <= 0) {
                fprintf(stderr, "Error: Invalid debounce interval. Using default value (50ms).\n");
                debounce_interval = 50;
            }
            i++; // Skip the value
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Debounce interval: %d ms\n", debounce_interval);

    // Main loop
    while (program_running) {
        if (read_touch_sensor(TOUCH_PIN, debounce_interval) == 1) {
            toggle_relay(RELAY_PIN);
            log_relay_state(RELAY_PIN);
        }
        gpioDelay(10000); // Check every 10ms
    }

    // Cleanup
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

