#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define INITIAL_ANGLE 90

static volatile int running = 1;
static struct termios original_termios;

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (0-180)\n");
        return -1;
    }

    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle) / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (500-2500)\n");
        return -1;
    }

    int result = gpioServo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width: %d\n", result);
        return -1;
    }

    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to restore terminal settings
void restore_terminal_settings() {
    tcsetattr(STDIN_FILENO, TCSANOW, &original_termios);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Save original terminal settings
    if (tcgetattr(STDIN_FILENO, &original_termios) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return 1;
    }

    // Set terminal to raw mode
    struct termios raw_termios = original_termios;
    raw_termios.c_lflag &= ~(ICANON | ECHO);
    raw_termios.c_cc[VMIN] = 0;  // Non-blocking read
    raw_termios.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw_termios) != 0) {
        perror("tcsetattr");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize servo to 90 degrees
    if (set_servo_angle(INITIAL_ANGLE) != 0) {
        restore_terminal_settings();
        gpioTerminate();
        return 1;
    }
    printf("Servo initialized to 90 degrees\n");

    int current_angle = INITIAL_ANGLE;

    // Main loop
    while (running) {
        int c = getchar();

        if (c == '+') {
            current_angle += 10;
            if (current_angle > MAX_ANGLE) {
                current_angle = MAX_ANGLE;
            }
            if (set_servo_angle(current_angle) == 0) {
                printf("Angle: %d degrees\n", current_angle);
            }
        } else if (c == '-') {
            current_angle -= 10;
            if (current_angle < MIN_ANGLE) {
                current_angle = MIN_ANGLE;
            }
            if (set_servo_angle(current_angle) == 0) {
                printf("Angle: %d degrees\n", current_angle);
            }
        } else if (c == 'q') {
            running = 0;
        }
    }

    // Stop PWM and restore terminal settings
    gpioServo(SERVO_PIN, 0); // Stop PWM
    restore_terminal_settings();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

