#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define RPM_INTERVAL_SEC 5
#define LOG_FILE "motor_rpm.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold program state
typedef struct {
    int gpio_pin;
    int debounce_ms;
    int rpm_interval_sec;
    char *log_file_name;
} program_config;

// Function prototypes
int initialize_gpio(int gpio_pin);
void cleanup_gpio(int gpio_pin);
void handle_interrupt(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(uint32_t pulse_count, double time_interval_sec);
int log_rpm_data(const char *timestamp, double rpm);
void signal_handler(int signal);
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size);

// Global variables (minimize usage)
static uint32_t last_tick = 0;
static uint32_t pulse_count = 0;

int main() {
    program_config config = {
        .gpio_pin = GPIO_PIN,
        .debounce_ms = DEBOUNCE_MS,
        .rpm_interval_sec = RPM_INTERVAL_SEC,
        .log_file_name = LOG_FILE
    };

    if (initialize_gpio(config.gpio_pin) != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", config.log_file_name);
        cleanup_gpio(config.gpio_pin);
        return 1;
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        if (elapsed_time >= config.rpm_interval_sec) {
            double rpm = calculate_rpm(pulse_count, config.rpm_interval_sec);
            char timestamp[32];
            get_iso8601_timestamp(timestamp, sizeof(timestamp));

            if (log_rpm_data(timestamp, rpm) != 0) {
                fprintf(stderr, "Error logging RPM data.\n");
            }

            printf("RPM: %.2f\n", rpm);

            pulse_count = 0; // Reset pulse count
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    cleanup_gpio(config.gpio_pin);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

int initialize_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(gpio_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_pin, PI_PUD_UP);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(gpio_pin, RISING_EDGE, 0, handle_interrupt, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

void cleanup_gpio(int gpio_pin) {
    gpioSetISRFuncEx(gpio_pin, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    gpioTerminate();
}

void handle_interrupt(int gpio, int level, uint32_t tick, void *user_data) {
    uint32_t diff = tick - last_tick;

    if (diff > config.debounce_ms * 1000) { // Convert ms to microseconds
        pulse_count++;
        last_tick = tick;
    }
}

double calculate_rpm(uint32_t pulse_count, double time_interval_sec) {
    return (double)pulse_count / time_interval_sec * 60.0;
}

int log_rpm_data(const char *timestamp, double rpm) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_buffer;
}

