#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define LONG_PRESS_TIMEOUT_SEC 10

// Global variables
volatile sig_atomic_t program_running = 1;
int relay_state = 0; // 0 = OFF, 1 = ON
time_t touch_start_time = 0;

// Function prototypes
int read_touch_sensor();
int control_relay(int state);
void handle_touch_event();
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Ensure relay is initially OFF
    control_relay(0);

    return 0; // Indicate success
}

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int current_state = gpioRead(TOUCH_SENSOR_PIN);
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay in microseconds
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error writing to relay pin\n");
        return 1; // Indicate failure
    }
    relay_state = state; // Update global relay state
    return 0; // Indicate success
}

// Function to handle touch events
void handle_touch_event() {
    time_t current_time = time(NULL);

    if (read_touch_sensor() == 1) {
        // Touch detected
        if (touch_start_time == 0) {
            // First touch detected
            touch_start_time = current_time;
        } else {
            // Touch is still active
            if (difftime(current_time, touch_start_time) >= LONG_PRESS_TIMEOUT_SEC) {
                // Long press detected, turn relay OFF
                control_relay(0);
                touch_start_time = 0; // Reset touch start time
                printf("Long press detected, relay turned OFF\n");
            }
        }
    } else {
        // Touch released
        if (touch_start_time != 0) {
            // Toggle relay state
            control_relay(!relay_state);
            touch_start_time = 0; // Reset touch start time
            printf("Touch released, relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received, exiting gracefully...\n");
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    control_relay(0); // Ensure relay is OFF
    gpioTerminate();
    printf("GPIO resources released\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Program started, press Ctrl+C to exit\n");

    // Main loop
    while (program_running) {
        handle_touch_event();
        gpioDelay(50 * 1000); // Poll every 50ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

