    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);
    gpioWrite(VALVE_ENABLE_PIN, 1); // Enable the valve

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to set the valve position using PWM
void set_valve_position(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;
    gpioPWM(VALVE_PWM_PIN, duty_cycle);
}

// Function to read the flow rate from the pulse counter
double read_flow_rate() {
    unsigned int current_pulse_count = pulse_count;
    pulse_count = 0; // Reset the pulse count
    // Assuming a YF-S201 flow sensor with a frequency of 7.5 Hz at 1 L/min
    // and a linear relationship between frequency and flow rate.
    // The frequency is proportional to the pulse count in a 100ms interval.
    // flow_rate = (pulse_count / 100ms) / frequency_at_1Lpm * 1Lpm
    // flow_rate = pulse_count / (100 * frequency_at_1Lpm) * 1Lpm
    // frequency_at_1Lpm = 7.5 Hz
    // flow_rate = pulse_count / (100 * 7.5) * 1Lpm
    // flow_rate = pulse_count / 750 * 1Lpm
    return (double)current_pulse_count / 750.0; // L/min
}

// Function to implement the control loop
int control_loop() {
    double flow_rate = read_flow_rate();
    double error = target_flow_rate - flow_rate;
    int duty_cycle = (int)(KP * error);

    set_valve_position(duty_cycle);
    log_data(flow_rate, duty_cycle);

    return 0;
}

// Function to log data to a CSV file
void log_data(double flow_rate, int valve_position) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (log_file != NULL) {
        fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
    set_valve_position(0); // Close the valve
    gpioWrite(VALVE_ENABLE_PIN, 0); // Disable the valve
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Interrupt service routine for the flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pulse_count++;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        target_flow_rate = strtod(argv[1], &endptr);
        if (*endptr != '\0' || target_flow_rate < 0) {
            fprintf(stderr, "Error: Invalid target flow rate.  Using default value of %.2f L/min\n", TARGET_FLOW_RATE_DEFAULT);
            target_flow_rate = TARGET_FLOW_RATE_DEFAULT;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        control_loop();
        gpioDelay(100); // Sample every 100ms
    }

    return 0;
}

