#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_1_PIN 17
#define LOCK_2_PIN 27
#define BUTTON_PIN 22

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 100000 // 100 kHz

// Define valid RFID tag
const unsigned char valid_tag[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rfid(unsigned char *tag);
int verify_tag(const unsigned char *tag);
int read_button();
void control_locks(int engage);
void log_event(const char *event);
void signal_handler(int signal);

// Function to read RFID tag from SPI
int read_rfid(unsigned char *tag) {
    char tx_buf[10] = {0}; // Transmit buffer (dummy data)
    char rx_buf[10];      // Receive buffer

    if (spiXfer(spi_handle, tx_buf, rx_buf, 10) != 0) {
        log_event("RFID read failure");
        return -1; // Indicate failure
    }

    // Check for all-zero response
    int all_zero = 1;
    for (int i = 0; i < 10; i++) {
        if (rx_buf[i] != 0) {
            all_zero = 0;
            break;
        }
    }

    if (all_zero) {
        return 0; // No tag present
    }

    memcpy(tag, rx_buf, 10);
    return 1; // Tag read successfully
}

// Function to verify RFID tag
int verify_tag(const unsigned char *tag) {
    return (memcmp(tag, valid_tag, 10) == 0);
}

// Function to read button state with debouncing
int read_button() {
    int button_state = gpioRead(BUTTON_PIN);
    gpioDelay(50); // Debounce delay (50 ms)
    return (button_state == 0); // Button is active low
}

// Function to control the locks
void control_locks(int engage) {
    gpioWrite(LOCK_1_PIN, engage);
    gpioWrite(LOCK_2_PIN, engage);
}

// Function to log events to file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received termination signal");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable internal pull-up resistor

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 100kHz, mode 0
    if (spi_handle < 0) {
        log_event("SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char tag[10];
    int tag_read = 0;

    log_event("System started");

    while (!terminate) {
        // Read RFID tag
        int result = read_rfid(tag);
        if (result == 1) {
            if (verify_tag(tag)) {
                log_event("Valid tag detected");
                tag_read = 1;
            } else {
                log_event("Invalid tag detected");
                tag_read = 0;
            }
        } else if (result == -1) {
            // RFID read failure already logged in read_rfid function
        } // else result == 0, no tag present

        // Read button state
        if (read_button() && tag_read) {
            log_event("Button pressed");
            log_event("Disengaging locks");
            control_locks(0); // Disengage locks
            gpioDelay(5000);   // Wait 5 seconds
            control_locks(1); // Re-engage locks
            log_event("Re-engaging locks");
            tag_read = 0; // Reset tag read flag
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup
    log_event("System shutting down");
    control_locks(1); // Engage locks
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

