#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

#define TARGET_RPM 60.0
#define SAMPLE_TIME_MS 100
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 1000

// PID parameters (Tune these values)
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);
void set_motor_direction(int motor, int direction);
void set_motor_speed(int motor, int speed);
double calculate_rpm(int encoder_count, double sample_time);
double pid_control(double setpoint, double actual_value, double *integral, double *previous_error);
void log_data(double rpm1, double rpm2, double p1, double i1, double d1, double output1, double p2, double i2, double d2, double output2);
void signal_handler(int signal);

// Encoder 1 interrupt handler
void encoder1_isr(int gpio, int level, uint32_t tick, void *user)
{
    int b_state = gpioRead(ENCODER1_B);
    pthread_mutex_lock(&encoder1_mutex);
    if (level == RISING_EDGE) {
        if (b_state == 0) {
            encoder1_count++;
        } else {
            encoder1_count--;
        }
    } else if (level == FALLING_EDGE) {
        if (b_state == 0) {
            encoder1_count--;
        } else {
            encoder1_count++;
        }
    }
    pthread_mutex_unlock(&encoder1_mutex);
}

// Encoder 2 interrupt handler
void encoder2_isr(int gpio, int level, uint32_t tick, void *user)
{
    int b_state = gpioRead(ENCODER2_B);
    pthread_mutex_lock(&encoder2_mutex);
    if (level == RISING_EDGE) {
        if (b_state == 0) {
            encoder2_count++;
        } else {
            encoder2_count--;
        }
    } else if (level == FALLING_EDGE) {
        if (b_state == 0) {
            encoder2_count--;
        } else {
            encoder2_count++;
        }
    }
    pthread_mutex_unlock(&encoder2_mutex);
}

// Encoder 1 thread function
void *encoder1_thread(void *arg)
{
    (void)arg; // Suppress unused parameter warning
    while (running) {
        gpioDelay(10); // Small delay to prevent busy-waiting
    }
    pthread_exit(NULL);
}

// Encoder 2 thread function
void *encoder2_thread(void *arg)
{
    (void)arg; // Suppress unused parameter warning
    while (running) {
        gpioDelay(10); // Small delay to prevent busy-waiting
    }
    pthread_exit(NULL);
}

// Set motor direction (1 for forward, -1 for backward, 0 for stop)
void set_motor_direction(int motor, int direction)
{
    int in1, in2;

    if (motor == 1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
    } else if (motor == 2) {
        in1 = MOTOR2_IN3;
        in2 = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    if (direction == 1) {
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
    } else if (direction == -1) {
        gpioWrite(in1, 0);
        gpioWrite(in2, 1);
    } else {
        gpioWrite(in1, 0);
        gpioWrite(in2, 0);
    }
}

// Set motor speed using PWM
void set_motor_speed(int motor, int speed)
{
    int ena;

    if (motor == 1) {
        ena = MOTOR1_ENA;
    } else if (motor == 2) {
        ena = MOTOR2_ENB;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    if (speed < 0) {
        speed = 0;
    } else if (speed > PWM_RANGE) {
        speed = PWM_RANGE;
    }

    gpioPWM(ena, speed);
}

// Calculate RPM from encoder count
double calculate_rpm(int encoder_count, double sample_time)
{
    // Assuming 360 pulses per revolution (adjust as needed)
    double pulses_per_revolution = 360.0;
    double revolutions = (double)encoder_count / pulses_per_revolution;
    double rpm = (revolutions / (sample_time / 1000.0)) * 60.0;
    return rpm;
}

// PID control function
double pid_control(double setpoint, double actual_value, double *integral, double *previous_error)
{
    double error = setpoint - actual_value;
    *integral += error * SAMPLE_TIME_MS / 1000.0;
    double derivative = (error - *previous_error) / (SAMPLE_TIME_MS / 1000.0);
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Log data to CSV file
void log_data(double rpm1, double rpm2, double p1, double i1, double d1, double output1, double p2, double i2, double d2, double output2)
{
    if (log_file != NULL) {
        fprintf(log_file, "%lf,%lf,%lf,%lf,%lf,%lf,%lf,%lf,%lf,%lf\n",
                rpm1, rpm2, p1, i1, d1, output1, p2, i2, d2, output2);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;

    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    set_motor_direction(1, 0);
    set_motor_direction(2, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO lines
    gpioTerminate();

    exit(0);
}

int main()
{
    pthread_t encoder1_thread_id, encoder2_thread_id;
    double integral1 = 0, previous_error1 = 0;
    double integral2 = 0, previous_error2 = 0;
    double rpm1, rpm2, pid_output1, pid_output2;
    double p1, i1, d1, p2, i2, d2;
    int motor1_speed, motor2_speed;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE);

    // Set up interrupt handlers for encoders
    gpioSetISRFuncEx(ENCODER1_A, EITHER_EDGE, 0, encoder1_isr, NULL);
    gpioSetISRFuncEx(ENCODER2_A, EITHER_EDGE, 0, encoder2_isr, NULL);

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "RPM1,RPM2,P1,I1,D1,Output1,P2,I2,D2,Output2\n");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create encoder threads
    if (pthread_create(&encoder1_thread_id, NULL, encoder1_thread, NULL) != 0) {
        fprintf(stderr, "Error: Could not create encoder 1 thread\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (pthread_create(&encoder2_thread_id, NULL, encoder2_thread, NULL) != 0) {
        fprintf(stderr, "Error: Could not create encoder 2 thread\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read encoder counts
        pthread_mutex_lock(&encoder1_mutex);
        int encoder1_count_local = encoder1_count;
        encoder1_count = 0; // Reset count
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        int encoder2_count_local = encoder2_count;
        encoder2_count = 0; // Reset count
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate RPM
        rpm1 = calculate_rpm(encoder1_count_local, SAMPLE_TIME_MS);
        rpm2 = calculate_rpm(encoder2_count_local, SAMPLE_TIME_MS);

        // PID control
        pid_output1 = pid_control(TARGET_RPM, rpm1, &integral1, &previous_error1);
        pid_output2 = pid_control(TARGET_RPM, rpm2, &integral2, &previous_error2);

        // Extract PID components
        p1 = Kp * (TARGET_RPM - rpm1);
        i1 = Ki * integral1;
        d1 = Kd * (TARGET_RPM - rpm1 - previous_error1) / (SAMPLE_TIME_MS / 1000.0);

        p2 = Kp * (TARGET_RPM - rpm2);
        i2 = Ki * integral2;
        d2 = Kd * (TARGET_RPM - rpm2 - previous_error2) / (SAMPLE_TIME_MS / 1000.0);

        // Set motor speeds
        motor1_speed = (int)pid_output1;
        motor2_speed = (int)pid_output2;

        if (motor1_speed < 0) motor1_speed = 0;
        if (motor1_speed > PWM_RANGE) motor1_speed = PWM_RANGE;
        if (motor2_speed < 0) motor2_speed = 0;
        if (motor2_speed > PWM_RANGE) motor2_speed = PWM_RANGE;

        set_motor_speed(1, motor1_speed);
        set_motor_speed(2, motor2_speed);

        // Log data
        log_data(rpm1, rpm2, p1, i1, d1, pid_output1, p2, i2, d2, pid_output2);

        // Wait for the next sample time
        gpioDelay(SAMPLE_TIME_MS);
    }

    // Join threads
    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return 0;
}

