#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80

// GPIO pin for relay control
#define RELAY_GPIO 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void control_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    int result;
    // Soft reset
    result = i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63);
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity (example values)
    for (int i = 0; i < 12; i++) {
        // Touch threshold
        result = i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x30); // Example touch threshold
        if (result < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d: %d\n", i, result);
            return -1;
        }
        // Release threshold
        result = i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x10); // Example release threshold
        if (result < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d: %d\n", i, result);
            return -1;
        }
    }

    // Enable all electrodes
    result = i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C); // Enable electrodes 0-11
    if (result < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to read touch status: %d\n", result);
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log relay state to file
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    int result;
    uint16_t touch_status;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("MPR121 relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read touch status
        if (read_touch_status(&touch_status) == 0) {
            // Check if any electrode is touched
            if (touch_status > 0) {
                // If not already ON, turn relay ON
                if (relay_state == 0) {
                    control_relay(1);
                    log_relay_state(1);
                    relay_state = 1;
                }
            } else {
                // If not already OFF, turn relay OFF
                if (relay_state == 1) {
                    control_relay(0);
                    log_relay_state(0);
                    relay_state = 0;
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup
    control_relay(0); // Turn relay OFF
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

