#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define valve activation durations (in milliseconds)
#define VALVE1_DURATION 500
#define VALVE2_DURATION 1000

// Define valve pause durations (in seconds)
#define VALVE1_PAUSE 5
#define VALVE2_PAUSE 10

// Define the log file name
#define LOG_FILE "valve_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
void activate_valve(int gpio, int duration_ms);
void pause_valve(int pause_seconds);
void log_event(int valve_number, int duration_ms);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(VALVE1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE2_GPIO, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to activate a valve for a specified duration
void activate_valve(int gpio, int duration_ms) {
    gpioWrite(gpio, 1); // Set GPIO HIGH to activate the valve
    gpioDelay(duration_ms * 1000); // Delay for the specified duration (in microseconds)
