#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x4D
#define MPR121_FILTER_CONFIG 0x2B
#define MPR121_CHARGE_TIME 0x5B
#define MPR121_ELECTRODE_CURRENT 0x5C

// GPIO pin for relay control
#define RELAY_PIN 17

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;
int relay_state = 0; // 0 = off, 1 = on

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
int mpr121_write_register(uint8_t reg, uint8_t value);
int mpr121_read_register(uint8_t reg, uint8_t *value);
void relay_control(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the MPR121
int mpr121_init() {
    int status;

    // Stop mode
    status = mpr121_write_register(MPR121_ELECTRODE_CONFIG, 0x00);
    if (status != 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode\n");
        return -1;
    }

    // Configure touch and release thresholds
    for (int i = 0; i < 12; i++) {
        status = mpr121_write_register(MPR121_TOUCHTH_0 + i, 40); // Touch threshold
        if (status != 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        status = mpr121_write_register(MPR121_RELEASETH_0 + i, 20); // Release threshold
        if (status != 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure filter and charge time
    status = mpr121_write_register(MPR121_FILTER_CONFIG, 0x10); // Filter configuration
    if (status != 0) {
        fprintf(stderr, "Error: Failed to set filter configuration\n");
        return -1;
    }

    status = mpr121_write_register(MPR121_CHARGE_TIME, 0x10); // Charge time
    if (status != 0) {
        fprintf(stderr, "Error: Failed to set charge time\n");
        return -1;
    }

    status = mpr121_write_register(MPR121_ELECTRODE_CURRENT, 0x0C); // Electrode current
    if (status != 0) {
        fprintf(stderr, "Error: Failed to set electrode current\n");
        return -1;
    }

    // Run mode
    status = mpr121_write_register(MPR121_ELECTRODE_CONFIG, 0x0C); // Enable all electrodes
    if (status != 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to run mode\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(uint16_t *touch_status) {
    char buf[2];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (status != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to write a register in the MPR121
int mpr121_write_register(uint8_t reg, uint8_t value) {
    int status = i2cWriteByteData(i2c_handle, reg, value);
    if (status != 0) {
        fprintf(stderr, "Error: Failed to write to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a register in the MPR121
int mpr121_read_register(uint8_t reg, uint8_t *value) {
    int status = i2cReadByteData(i2c_handle, reg);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)status;
    return 0;
}

// Function to control the relay
void relay_control(int state) {
    gpioWrite(RELAY_PIN, state);
    relay_state = state;
    printf("Relay toggled to: %s\n", state ? "ON" : "OFF");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    // Main loop
    while (!terminate) {
        // Read touch status
        if (mpr121_read_touch_status(&touch_status) == 0) {
            // Check if any electrode is touched
            if (touch_status > 0) {
                // Toggle relay state
                relay_control(!relay_state);
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

