#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_relay();
void deactivate_relay();
void log_event(const char *event_type);
void rate_limit();
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to activate the relay
void activate_relay() {
    gpioWrite(RELAY_PIN, 1);
    log_event("Door Unlocked");
    gpioDelay(UNLOCK_DURATION_MS);
    deactivate_relay();
}

// Function to deactivate the relay
void deactivate_relay() {
    gpioWrite(RELAY_PIN, 0);
}

// Function to log events to a file
void log_event(const char *event_type) {
    if (log_file == NULL) return; // Check if log file is open

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), 10, ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to implement rate limiting
void rate_limit() {
    log_event("Rate Limited");
    gpioDelay(RATE_LIMIT_MS);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    int last_pir_state = 0; // Track the last PIR sensor state
    struct timespec last_event_time;
    clock_gettime(CLOCK_REALTIME, &last_event_time);

    printf("Door strike controller started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int current_pir_state = read_pir_sensor();

        if (current_pir_state == 1 && last_pir_state == 0) {
            // Rising edge detected
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            long time_diff_ms = (now.tv_sec - last_event_time.tv_sec) * 1000 + (now.tv_nsec - last_event_time.tv_nsec) / 1000000;

            if (time_diff_ms >= RATE_LIMIT_MS) {
                log_event("Motion Detected");
                activate_relay();
                clock_gettime(CLOCK_REALTIME, &last_event_time);
            } else {
                rate_limit();
            }
        }

        last_pir_state = current_pir_state;
        gpioDelay(POLL_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

