}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    int last_pir_state = 0; // Track the last PIR sensor state
    struct timespec last_event_time;
    clock_gettime(CLOCK_REALTIME, &last_event_time);

    printf("Door strike controller started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int current_pir_state = read_pir_sensor();

        if (current_pir_state == 1 && last_pir_state == 0) {
            // Rising edge detected
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            long time_diff_ms = (now.tv_sec - last_event_time.tv_sec) * 1000 + (now.tv_nsec - last_event_time.tv_nsec) / 1000000;

            if (time_diff_ms >= RATE_LIMIT_MS) {
                log_event("Motion Detected");
                activate_relay();
                clock_gettime(CLOCK_REALTIME, &last_event_time);
            } else {
                rate_limit();
            }
        }

        last_pir_state = current_pir_state;
        gpioDelay(POLL_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

