#define MAX_STEPS 15

// Define the duration range for each step (in milliseconds)
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define the PWM range
#define PWM_RANGE 255

// Global variable to indicate program shutdown
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    shutdown_flag = 1;
    printf("\nCaught signal %d, shutting down gracefully...\n", signal);
}

// Function to generate a random PWM duty cycle
int generate_random_duty_cycle() {
    return rand() % (PWM_RANGE + 1);
}

// Function to generate a random step duration
int generate_random_duration() {
    return (rand() % (MAX_DURATION - MIN_DURATION + 1)) + MIN_DURATION;
}

// Function to generate a random haptic feedback pattern
void generate_pattern(int *duty_cycles_motor1, int *duty_cycles_motor2, int *durations, int *num_steps) {
    *num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;

    for (int i = 0; i < *num_steps; i++) {
        duty_cycles_motor1[i] = generate_random_duty_cycle();
        duty_cycles_motor2[i] = generate_random_duty_cycle();
        durations[i] = generate_random_duration();
    }
}

// Function to play the haptic feedback pattern
void play_pattern(int *duty_cycles_motor1, int *duty_cycles_motor2, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        gpioPWM(MOTOR1_PIN, duty_cycles_motor1[i]);
        gpioPWM(MOTOR2_PIN, duty_cycles_motor2[i]);
        gpioDelay(durations[i] * 1000); // Convert milliseconds to microseconds
    }
}

