    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to PWM output mode
    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);

    // Seed the random number generator
    srand(time(NULL));

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Allocate memory for the pattern data
    int *duty_cycles_motor1 = NULL;
    int *duty_cycles_motor2 = NULL;
    int *durations = NULL;
    int num_steps = 0;

    // Main loop to generate and play patterns
    while (!shutdown_flag) {
        // Generate a new pattern
        num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;
