        duty_cycles_motor2 = (int *)malloc(num_steps * sizeof(int));
        durations = (int *)malloc(num_steps * sizeof(int));

        if (duty_cycles_motor1 == NULL || duty_cycles_motor2 == NULL || durations == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            // Attempt to free previously allocated memory
            if (duty_cycles_motor1) free(duty_cycles_motor1);
            if (duty_cycles_motor2) free(duty_cycles_motor2);
            if (durations) free(durations);
            gpioTerminate();
            return 1;
        }

        generate_pattern(duty_cycles_motor1, duty_cycles_motor2, durations, &num_steps);

        // Play the pattern
        play_pattern(duty_cycles_motor1, duty_cycles_motor2, durations, num_steps);

        // Free the allocated memory
        free(duty_cycles_motor1);
        free(duty_cycles_motor2);
        free(durations);

        // Small delay before generating the next pattern
        gpioDelay(100000); // 100ms
    }

    // Stop the motors
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

