#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define TIMEOUT_MS 500
#define NUM_CALIBRATION_READINGS 100
#define WEIGHT_THRESHOLD 10.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"

// Global variables
double scale_factor = 1.0;
double offset = 0.0;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value, double scale_factor, double offset);
void control_solenoid(double weight, double threshold);
void log_data(double weight, int solenoid_state);
void load_calibration_data();
void save_calibration_data();
void calibrate_offset();
void signal_handler(int signal);

// Function to read data from HX711 with timeout
int read_hx711() {
    int data = 0;
    int i;
    long start_time = gpioTick();

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (gpioTick() - start_time > TIMEOUT_MS * 1000) {
            fprintf(stderr, "HX711 read timeout\n");
            return -1; // Timeout
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse the clock pin 1 more time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight
double calculate_weight(int raw_value, double scale_factor, double offset) {
    return (raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight, double threshold) {
    if (weight > threshold) {
        gpioWrite(SOLENOID_PIN, 1); // Engage solenoid
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid
    }
}

// Function to log data to file
void log_data(double weight, int solenoid_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Weight: %.2f kg, Solenoid: %s\n", timestamp, weight, solenoid_state ? "Engaged" : "Disengaged");
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to load calibration data from file
void load_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp != NULL) {
        if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
            fprintf(stderr, "Error reading calibration data, using defaults\n");
            scale_factor = 1.0;
            offset = 0.0;
        }
        fclose(fp);
    } else {
        fprintf(stderr, "Calibration file not found, using defaults\n");
        scale_factor = 1.0;
        offset = 0.0;
    }
}

// Function to save calibration data to file
void save_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp != NULL) {
        fprintf(fp, "%lf %lf", scale_factor, offset);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening calibration file for writing\n");
    }
}

// Function to calibrate the offset
void calibrate_offset() {
    double sum = 0.0;
    int i;
    printf("Calibrating offset... Please ensure the load cell is at zero.\n");
    for (i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Calibration failed due to HX711 timeout\n");
            return;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    offset = sum / NUM_CALIBRATION_READINGS;
    printf("Calibration complete. Offset: %lf\n", offset);
    save_calibration_data();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially disengaged

    // Load calibration data
    load_calibration_data();

    // Calibrate offset
    calibrate_offset();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight(raw_value, scale_factor, offset);
            control_solenoid(weight, WEIGHT_THRESHOLD);
            log_data(weight, gpioRead(SOLENOID_PIN));
            printf("Weight: %.2f kg, Solenoid: %s\n", weight, gpioRead(SOLENOID_PIN) ? "Engaged" : "Disengaged");
        } else {
            fprintf(stderr, "Failed to read HX711 data\n");
        }
        gpioDelay(500); // Delay for 500ms
    }

    // Clean up
    gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid
    fclose(log_file);
    gpioTerminate();

    return 0;
}

