#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_1 4
#define RAIN_SENSOR_2 22
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_PWM 27

// Define constants
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define MOTOR_RUN_TIME_SEC 5
#define SENSOR_CHECK_INTERVAL_SEC 60
#define MOTOR_COOLDOWN_SEC 60

// Global variables
volatile sig_atomic_t program_running = 1;
int motor_cooldown_active = 0;

// Function prototypes
int read_rain_sensor(int gpio_pin);
int debounce_rain_sensor(int gpio_pin);
void control_motor(int in1_pin, int in2_pin, int pwm_pin, int action);
void log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);
void cleanup();

// Function to read the rain sensor
int read_rain_sensor(int gpio_pin) {
    int reading = gpioRead(gpio_pin);
    if (reading < 0) {
        syslog(LOG_ERR, "Error reading GPIO %d: %d", gpio_pin, reading);
        return -1; // Indicate error
    }
    return reading;
}

// Function to debounce the rain sensor
int debounce_rain_sensor(int gpio_pin) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int reading = read_rain_sensor(gpio_pin);
        if (reading == 0) {
            low_count++;
        } else if (reading < 0) {
            return -1; // Propagate error
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }
    return (low_count >= 3) ? 0 : 1; // Return 0 if rain detected (LOW), 1 otherwise
}

// Function to control the motor
void control_motor(int in1_pin, int in2_pin, int pwm_pin, int action) {
    if (action == 1) { // Start motor
        gpioWrite(in1_pin, 1);
        gpioWrite(in2_pin, 0);
        gpioPWM(pwm_pin, PWM_DUTY_CYCLE);
        log_event(0, "Motor started");
    } else if (action == 0) { // Stop motor
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 0);
        gpioPWM(pwm_pin, 0);
        log_event(0, "Motor stopped");
    }
}

// Function to log events
void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
