#define HX711_SCK 24
#define SOLENOID_PIN 17

// Define constants
#define WEIGHT_THRESHOLD 100.0  // grams
#define SOLENOID_DURATION 5      // seconds
#define HX711_TIMEOUT 1000000   // microseconds (1 second)

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double convert_to_grams(int raw_value);
void activate_solenoid();
void log_event(const char *message);
void signal_handler(int signal);

// HX711 Calibration Values (to be determined experimentally)
double scale_factor = 1.0; // Adjust this value based on calibration
double offset = 0.0;       // Adjust this value based on calibration

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for the HX711 to be ready
    int timeout_counter = 0;
    while (gpioRead(HX711_DT) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
        if (timeout_counter > HX711_TIMEOUT) {
            log_event("HX711 Timeout: Data line stuck high.");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to grams
double convert_to_grams(int raw_value) {
    return (double)(raw_value - offset) / scale_factor;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    log_event("Solenoid activated.");
    gpioDelay(SOLENOID_DURATION * 1000000); // Wait for specified duration
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
    log_event("Solenoid deactivated.");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started.");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_event("Error reading HX711.");
        } else {
            double weight = convert_to_grams(raw_value);
            char message[100];
            snprintf(message, sizeof(message), "Weight: %.2f grams", weight);
            log_event(message);

            if (weight < WEIGHT_THRESHOLD) {
                activate_solenoid();
            }
        }

        gpioDelay(1000000); // Wait for 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();

    return 0;
}

