#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0
#define SOLENOID_LOCK_TIME 5
#define TIMEOUT_DURATION 100 // milliseconds

// Global variables
double calibration_factor = 0.0;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
double read_hx711();
double calibrate_hx711(double known_weight);
double apply_calibration(double raw_value, double calibration_factor);
int control_solenoid(int lock);
int log_event(double weight);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Function to read raw data from HX711
double read_hx711() {
    int i;
    unsigned long data = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Wait for data line to go low
    while (gpioRead(HX711_DATA_PIN) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000.0;
        elapsed_time += (current_time.tv_nsec - start_time.tv_nsec) / 1000000.0;

        if (elapsed_time > TIMEOUT_DURATION) {
            fprintf(stderr, "HX711 timeout\n");
            return -1.0; // Indicate timeout
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // Apply the 25th clock pulse for gain selection (default gain = 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return (double)data;
}

// Function to calibrate HX711
double calibrate_hx711(double known_weight) {
    double raw_value = read_hx711();
    if (raw_value < 0) return -1.0; // Indicate error
    return known_weight / raw_value;
}

// Function to apply calibration factor
double apply_calibration(double raw_value, double calibration_factor) {
    return raw_value * calibration_factor;
}

// Function to control the solenoid
int control_solenoid(int lock) {
    gpioWrite(SOLENOID_PIN, lock);
    if (lock) {
        gpioDelay(SOLENOID_LOCK_TIME * 1000); // Lock for 5 seconds
        gpioWrite(SOLENOID_PIN, 0); // Unlock
    }
    return 0;
}

// Function to log events
int log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return 1;
    }

    fprintf(log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    control_solenoid(0); // Unlock solenoid
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    double raw_value, calibrated_weight;
    char input[256];

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio()) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Check if calibration file exists
    FILE *calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file != NULL) {
        if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration factor from file\n");
            fclose(calibration_file);
            gpioTerminate();
            fclose(log_file);
            return 1;
        }
        fclose(calibration_file);
        printf("Calibration factor loaded from %s: %.6f\n", CALIBRATION_FILE, calibration_factor);
    } else {
        // Calibrate HX711
        printf("Place a known weight on the load cell (in kg): ");
        if (fgets(input, sizeof(input), stdin) == NULL) {
            fprintf(stderr, "Error reading input\n");
            gpioTerminate();
            fclose(log_file);
            return 1;
        }
        double known_weight = atof(input);

        calibration_factor = calibrate_hx711(known_weight);
        if (calibration_factor < 0) {
            fprintf(stderr, "Calibration failed\n");
            gpioTerminate();
            fclose(log_file);
            return 1;
        }

        // Save calibration factor to file
        calibration_file = fopen(CALIBRATION_FILE, "w");
        if (calibration_file == NULL) {
            fprintf(stderr, "Error opening calibration file for writing\n");
            gpioTerminate();
            fclose(log_file);
            return 1;
        }
        fprintf(calibration_file, "%.6f", calibration_factor);
        fclose(calibration_file);
        printf("Calibration factor saved to %s: %.6f\n", CALIBRATION_FILE, calibration_factor);
    }

    // Main loop
    while (program_running) {
        raw_value = read_hx711();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading from HX711, retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        calibrated_weight = apply_calibration(raw_value, calibration_factor);

        printf("Raw: %.2f, Calibrated: %.2f kg\n", raw_value, calibrated_weight);

        if (calibrated_weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Activating solenoid lock.\n");
            control_solenoid(1); // Lock the solenoid
            log_event(calibrated_weight); // Log the event
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup (should not reach here if signal handler is working)
    control_solenoid(0); // Unlock solenoid
    fclose(log_file);
    gpioTerminate();

    return 0;
}

