int toggle_relay() {
    relay_state = !relay_state;
    int result = gpioWrite(RELAY_PIN, relay_state);
    if (result < 0) {
        fprintf(stderr, "Error writing to relay pin\n");
        return -1;
    }
    return 0;
}

