    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Monitoring sensor... Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            // Log the error
            log_event("Error reading sensor");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check if obstacle is detected (sensor value is LOW)
        if (sensor_value == 0) {
            if (toggle_relay() != 0) {
                log_event("Error toggling relay");
            } else {
                // Log the event
                const char *event = (relay_state == 1) ? "Relay ON" : "Relay OFF";
                log_event(event);
            }
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    cleanup();
    return 0;
}

