int read_pir_sensor();
void activate_buzzer(int duration_ms);
void log_motion();
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read the PIR sensor
int read_pir_sensor() {
    int value = gpioRead(PIR_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading PIR sensor: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to activate the buzzer
void activate_buzzer(int duration_ms) {
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Error activating buzzer\n");
        return;
    }
    gpioDelay(duration_ms * 1000); // Convert ms to microseconds
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error deactivating buzzer\n");
    }
}

// Function to log motion detection
void log_motion() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Motion detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Setup function to initialize GPIO and logging
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting PIR sensor pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    // Turn off buzzer
    gpioWrite(BUZZER_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int pir_value = read_pir_sensor();
        if (pir_value > 0) {
            log_motion();
            activate_buzzer(2000); // Activate buzzer for 2 seconds
        }
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

