        fprintf(stderr, "Error: Could not open configuration file %s\n", filename);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read from configuration file %s\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Remove newline character
    line[strcspn(line, "\n")] = 0;

    char *token = strtok(line, "=");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Error: Invalid configuration file format\n");
        return -1;
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Missing duration value in configuration file\n");
        return -1;
    }

    char *endptr;
    long duration = strtol(token, &endptr, 10);

    if (*endptr != '\0' || duration < MIN_DURATION || duration > MAX_DURATION) {
        fprintf(stderr, "Error: Invalid duration value in configuration file\n");
        return -1;
    }

    return (int)duration;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to low\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    int duration = read_duration_from_file(CONFIG_FILE);
    if (duration < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Watering duration: %d seconds\n", duration);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioWrite(GPIO_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to high\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }
    printf("Valve ON\n");

    while (!terminate) {
        sleep(1);
    }

    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to low\n", GPIO_PIN);
    }
    printf("Valve OFF\n");

    gpioTerminate();
    return 0;
}

