#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define LUX_THRESHOLD 150.0
#define RELAY_GPIO 23
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int relay_state;
} ProgramState;

ProgramState state = {0}; // Initialize relay state to OFF

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read illuminance from BH1750
int read_bh1750(float *lux) {
    char config_mode = CONTINUOUS_HIGH_RES_MODE;
    char buffer[2];
    int result;

    result = i2cWriteByteData(i2c_handle, 0x00, config_mode); // Send configuration command
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(180); // Wait for measurement (180ms)

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Function to control the relay
void control_relay(int state_to_set) {
    if (state.relay_state != state_to_set) {
        gpioWrite(RELAY_GPIO, state_to_set);
        state.relay_state = state_to_set;
        log_data(-1.0, state.relay_state); // Log relay state change
    }
}

// Function to log data to file
void log_data(float lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    char milliseconds[5];
    snprintf(milliseconds, sizeof(milliseconds), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s%s, Lux: %.2f, Relay: %s\n", timestamp, milliseconds, lux, relay_state ? "ON" : "OFF");
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float lux;
    int read_result;

    printf("Grow lamp control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        read_result = read_bh1750(&lux);
        if (read_result == 0) {
            log_data(lux, state.relay_state);

            if (lux < LUX_THRESHOLD) {
                control_relay(1); // Turn on relay
            } else {
                control_relay(0); // Turn off relay
            }
        } else {
            fprintf(stderr, "Error reading BH1750, retrying...\n");
            log_data(-1.0, -1); // Log error
            gpioDelay(1000); // Wait before retrying
        }

        gpioDelay(500); // Check every 500ms
    }

    // Cleanup
    control_relay(0); // Turn off relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

