#include <pigpio.h>

// Define GPIO pins
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18

// Define servo pulse widths (microseconds)
#define LOCK_PULSE_WIDTH 1000
#define UNLOCK_PULSE_WIDTH 2000

// Debounce delay (milliseconds)
#define DEBOUNCE_DELAY 100

// Global variable to track program state for signal handler
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_lock_button();
int read_unlock_button();
int set_servo_pulse_width(int pulse_width);
void lock_door();
void unlock_door();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
        gpioTerminate(); // Release GPIO resources
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the lock button state
int read_lock_button() {
    return (gpioRead(LOCK_BUTTON) == 0); // Active-low logic
}

