#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define pulse durations in milliseconds
#define MOTOR1_DURATION 200
#define MOTOR2_DURATION 300

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to activate a motor for a specified duration
int activate_motor(int gpio, int duration_ms)
{
    int result;

    // Set the GPIO pin HIGH to activate the motor
    result = gpioWrite(gpio, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio, result);
        return -1;
    }

    // Delay for the specified duration
    gpioDelay(duration_ms * 1000); // pigpioDelay takes microseconds

    // Set the GPIO pin LOW to deactivate the motor
    result = gpioWrite(gpio, 0);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio, result);
        return -1;
    }

    return 0;
}

int main()
{
    int result;

    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing SIGINT handler\n");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing SIGTERM handler\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    result = gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %d\n", MOTOR1_GPIO, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %d\n", MOTOR2_GPIO, result);
        gpioTerminate();
        return 1;
    }

    // Main loop to pulse the motors
    while (!terminate) {
        // Activate motor 1
        if (activate_motor(MOTOR1_GPIO, MOTOR1_DURATION) != 0) {
            fprintf(stderr, "Error activating motor 1, exiting\n");
            break;
        }

        // Activate motor 2
        if (activate_motor(MOTOR2_GPIO, MOTOR2_DURATION) != 0) {
            fprintf(stderr, "Error activating motor 2, exiting\n");
            break;
        }
    }

    // Ensure motors are off before exiting
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

