#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <getopt.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <zmq.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    int sound_sensor_gpio;
    int alarm_led_gpio;
    char zmq_endpoint[256];
    int zmq_port;
    int debounce_delay_ms;
    int alarm_duration_s;
} Config;

// Global configuration
Config config;

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
void *zmq_context = NULL;
void *zmq_socket = NULL;

// Function prototypes
void signal_handler(int signal);
int load_config(const char *filename, Config *config);
int init_gpio(int gpio_pin, int mode);
int read_gpio(int gpio_pin);
int write_gpio(int gpio_pin, int value);
int init_zmq_publisher(void);
int init_zmq_subscriber(void);
int publish_alert(void);
int subscribe_alert(void);
void cleanup(void);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
    cleanup();
    exit(0);
}

// Load configuration from file
int load_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "sound_sensor_gpio") == 0) {
            config->sound_sensor_gpio = atoi(value);
        } else if (strcmp(key, "alarm_led_gpio") == 0) {
            config->alarm_led_gpio = atoi(value);
        } else if (strcmp(key, "zmq_endpoint") == 0) {
            strncpy(config->zmq_endpoint, value, sizeof(config->zmq_endpoint) - 1);
            config->zmq_endpoint[sizeof(config->zmq_endpoint) - 1] = '\0';
        } else if (strcmp(key, "zmq_port") == 0) {
            config->zmq_port = atoi(value);
        } else if (strcmp(key, "debounce_delay_ms") == 0) {
            config->debounce_delay_ms = atoi(value);
        } else if (strcmp(key, "alarm_duration_s") == 0) {
            config->alarm_duration_s = atoi(value);
        }
    }

    fclose(fp);
    return 0;
}

// Initialize GPIO pin
int init_gpio(int gpio_pin, int mode) {
    if (gpioSetMode(gpio_pin, mode) != 0) {
        fprintf(stderr, "Error setting GPIO %d mode: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Read GPIO pin value
int read_gpio(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Write GPIO pin value
int write_gpio(int gpio_pin, int value) {
    if (gpioWrite(gpio_pin, value) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize ZeroMQ publisher
int init_zmq_publisher(void) {
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("zmq_ctx_new failed");
        return -1;
    }

    zmq_socket = zmq_socket(zmq_context, ZMQ_PUB);
    if (!zmq_socket) {
        perror("zmq_socket failed");
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    char endpoint[256];
    snprintf(endpoint, sizeof(endpoint), "tcp://*:%d", config.zmq_port);

    if (zmq_bind(zmq_socket, endpoint) < 0) {
        perror("zmq_bind failed");
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    printf("ZeroMQ publisher bound to %s\n", endpoint);
    return 0;
}

// Initialize ZeroMQ subscriber
int init_zmq_subscriber(void) {
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("zmq_ctx_new failed");
        return -1;
    }

    zmq_socket = zmq_socket(zmq_context, ZMQ_SUB);
    if (!zmq_socket) {
        perror("zmq_socket failed");
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    char endpoint[256];
    snprintf(endpoint, sizeof(endpoint), "tcp://localhost:%d", config.zmq_port);

    if (zmq_connect(zmq_socket, endpoint) < 0) {
        perror("zmq_connect failed");
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    // Subscribe to the topic
    if (zmq_setsockopt(zmq_socket, ZMQ_SUBSCRIBE, "SOUND_ALERTS", strlen("SOUND_ALERTS")) < 0) {
        perror("zmq_setsockopt failed");
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    printf("ZeroMQ subscriber connected to %s\n", endpoint);
    return 0;
}

// Publish alert message
int publish_alert(void) {
    char *message = "SOUND_ALERTS";
    zmq_msg_t zmq_message;
    zmq_msg_init_size(&zmq_message, strlen(message));
    memcpy(zmq_msg_data(&zmq_message), message, strlen(message));

    if (zmq_msg_send(&zmq_message, zmq_socket, 0) < 0) {
        perror("zmq_msg_send failed");
        zmq_msg_close(&zmq_message);
        return -1;
    }

    zmq_msg_close(&zmq_message);
    printf("Published alert: %s\n", message);
    return 0;
}

// Subscribe to alert messages
int subscribe_alert(void) {
    zmq_msg_t zmq_message;
    zmq_msg_init(&zmq_message);

    if (zmq_msg_recv(&zmq_message, zmq_socket, 0) < 0) {
        perror("zmq_msg_recv failed");
        zmq_msg_close(&zmq_message);
        return -1;
    }

    char *message = (char *)zmq_msg_data(&zmq_message);
    size_t message_size = zmq_msg_size(&zmq_message);

    char topic[256];
    strncpy(topic, message, message_size > sizeof(topic) - 1 ? sizeof(topic) - 1 : message_size);
    topic[message_size > sizeof(topic) - 1 ? sizeof(topic) - 1 : message_size] = '\0';

    if (strcmp(topic, "SOUND_ALERTS") == 0) {
        printf("Received alert: %s\n", topic);
        // Activate alarm LED
        if (write_gpio(config.alarm_led_gpio, 1) != 0) {
            fprintf(stderr, "Error activating alarm LED\n");
        }
        gpioDelay(config.alarm_duration_s * 1000000); // Delay for alarm duration
        if (write_gpio(config.alarm_led_gpio, 0) != 0) {
            fprintf(stderr, "Error deactivating alarm LED\n");
        }
    }

    zmq_msg_close(&zmq_message);
    return 0;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Release GPIO resources
    if (gpioInitialise() >= 0) {
        gpioTerminate();
    }

    // Close ZeroMQ socket and context
    if (zmq_socket) {
        zmq_close(zmq_socket);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }
}

int main(int argc, char *argv[]) {
    // Default configuration values
    config.sound_sensor_gpio = 17;
    config.alarm_led_gpio = 27;
    strncpy(config.zmq_endpoint, "tcp://localhost", sizeof(config.zmq_endpoint) - 1);
    config.zmq_endpoint[sizeof(config.zmq_endpoint) - 1] = '\0';
    config.zmq_port = 5555;
    config.debounce_delay_ms = 10;
    config.alarm_duration_s = 1;

    // Load configuration from file
    if (load_config("alarm.conf", &config) != 0) {
        fprintf(stderr, "Failed to load configuration, using default values.\n");
    }

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "m:")) != -1) {
        switch (opt) {
            case 'm': {
                if (strcmp(optarg, "sound_sensor") == 0) {
                    // Sound sensor mode
                    printf("Running in sound_sensor mode\n");

                    // Initialize pigpio
                    if (gpioInitialise() < 0) {
                        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
                        return 1;
                    }

                    // Initialize GPIO pins
                    if (init_gpio(config.sound_sensor_gpio, PI_INPUT) != 0) {
                        cleanup();
                        return 1;
                    }
                    if (init_gpio(config.alarm_led_gpio, PI_OUTPUT) != 0) {
                        cleanup();
                        return 1;
                    }

                    // Initialize ZeroMQ publisher
                    if (init_zmq_publisher() != 0) {
                        cleanup();
                        return 1;
                    }

                    // Set up signal handlers
                    signal(SIGINT, signal_handler);
                    signal(SIGTERM, signal_handler);

                    // Main loop
                    int last_state = 1; // Assume no sound initially
                    while (!terminate) {
                        int current_state = read_gpio(config.sound_sensor_gpio);

                        if (current_state == 0 && last_state == 1) {
                            // Sound detected (active low)
                            printf("Sound detected!\n");
                            if (publish_alert() != 0) {
                                fprintf(stderr, "Failed to publish alert\n");
                            }
                            gpioDelay(config.debounce_delay_ms * 1000); // Debounce delay
                        }

                        last_state = current_state;
                        gpioDelay(1000); // Check every 1ms
                    }

                } else if (strcmp(optarg, "alarm_node") == 0) {
                    // Alarm node mode
                    printf("Running in alarm_node mode\n");

                    // Initialize pigpio
                    if (gpioInitialise() < 0) {
                        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
                        return 1;
                    }

                    // Initialize GPIO pins
                    if (init_gpio(config.alarm_led_gpio, PI_OUTPUT) != 0) {
                        cleanup();
                        return 1;
                    }

                    // Initialize ZeroMQ subscriber
                    if (init_zmq_subscriber() != 0) {
                        cleanup();
                        return 1;
                    }

                    // Set up signal handlers
                    signal(SIGINT, signal_handler);
                    signal(SIGTERM, signal_handler);

                    // Main loop
                    while (!terminate) {
                        if (subscribe_alert() != 0) {
                            fprintf(stderr, "Failed to subscribe to alert\n");
                        }
                    }

                } else {
                    fprintf(stderr, "Invalid mode: %s\n", optarg);
                    return 1;
                }
                break;
            }
            default:
                fprintf(stderr, "Usage: %s -m <mode>\n", argv[0]);
                return 1;
        }
    }

    if (optind < argc) {
        fprintf(stderr, "Non-option argument(s) provided\n");
        return 1;
    }

    cleanup();
    return 0;
}

