#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define GPIO_PIN 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define PULSE_BUFFER_SIZE 100

// NEC timing constants (in microseconds)
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static int pulse_buffer[PULSE_BUFFER_SIZE];
static int pulse_count = 0;

// Function prototypes
void signal_handler(int signal);
void ir_callback(int gpio, int level, uint32_t tick, void *user);
int decode_nec(int *pulses, int pulse_count, unsigned int *address, unsigned int *command);
int validate_nec_checksum(unsigned int address, unsigned int command);
int publish_mqtt(unsigned int address, unsigned int command);
void log_message(int priority, const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// IR receiver callback function
void ir_callback(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t pulse_length;

    if (level == FALLING_EDGE) {
        pulse_length = tick - last_tick;
        last_tick = tick;

        if (pulse_count < PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_count++] = pulse_length;
        } else {
            log_message(LOG_ERR, "Pulse buffer overflow!");
            pulse_count = 0; // Reset buffer to avoid further overflows
        }
    }
}

// NEC decoding function
int decode_nec(int *pulses, int pulse_count, unsigned int *address, unsigned int *command) {
    if (pulse_count < 68) {
        log_message(LOG_ERR, "Not enough pulses for a complete NEC frame.");
        return -1;
    }

    // Validate header
    if (pulses[0] < NEC_HEADER_MARK * 0.8 || pulses[0] > NEC_HEADER_MARK * 1.2 ||
        pulses[1] < NEC_HEADER_SPACE * 0.8 || pulses[1] > NEC_HEADER_SPACE * 1.2) {
        log_message(LOG_ERR, "Invalid NEC header.");
        return -1;
    }

    unsigned int decoded_address = 0;
    unsigned int decoded_command = 0;

    // Decode address (8 bits)
    for (int i = 2; i < 10; i++) {
        decoded_address <<= 1;
        if (pulses[2 * i] < NEC_BIT_MARK * 0.8 || pulses[2 * i] > NEC_BIT_MARK * 1.2) {
            log_message(LOG_ERR, "Invalid bit mark.");
            return -1;
        }
        if (pulses[2 * i + 1] > NEC_ONE_SPACE * 0.8) {
            decoded_address |= 1;
        } else if (pulses[2 * i + 1] < NEC_ZERO_SPACE * 1.2) {
            // It's a zero, do nothing
        } else {
            log_message(LOG_ERR, "Invalid bit space.");
            return -1;
        }
    }

    // Decode command (8 bits)
    for (int i = 10; i < 18; i++) {
        decoded_command <<= 1;
        if (pulses[2 * i] < NEC_BIT_MARK * 0.8 || pulses[2 * i] > NEC_BIT_MARK * 1.2) {
            log_message(LOG_ERR, "Invalid bit mark.");
            return -1;
        }
        if (pulses[2 * i + 1] > NEC_ONE_SPACE * 0.8) {
            decoded_command |= 1;
        } else if (pulses[2 * i + 1] < NEC_ZERO_SPACE * 1.2) {
            // It's a zero, do nothing
        } else {
            log_message(LOG_ERR, "Invalid bit space.");
            return -1;
        }
    }

    *address = decoded_address;
    *command = decoded_command;

    return 0;
}

// NEC checksum validation function
int validate_nec_checksum(unsigned int address, unsigned int command) {
    unsigned int inverted_address = 0;
    unsigned int inverted_command = 0;

    // Decode inverted address (8 bits)
    for (int i = 2; i < 10; i++) {
        inverted_address <<= 1;
        if (pulse_buffer[2 * i] < NEC_BIT_MARK * 0.8 || pulse_buffer[2 * i] > NEC_BIT_MARK * 1.2) {
            log_message(LOG_ERR, "Invalid bit mark.");
            return -1;
        }
        if (pulse_buffer[2 * i + 1] > NEC_ONE_SPACE * 0.8) {
            inverted_address |= 1;
        } else if (pulse_buffer[2 * i + 1] < NEC_ZERO_SPACE * 1.2) {
            // It's a zero, do nothing
        } else {
            log_message(LOG_ERR, "Invalid bit space.");
            return -1;
        }
    }

    // Decode inverted command (8 bits)
    for (int i = 10; i < 18; i++) {
        inverted_command <<= 1;
        if (pulse_buffer[2 * i] < NEC_BIT_MARK * 0.8 || pulse_buffer[2 * i] > NEC_BIT_MARK * 1.2) {
            log_message(LOG_ERR, "Invalid bit mark.");
            return -1;
        }
        if (pulse_buffer[2 * i + 1] > NEC_ONE_SPACE * 0.8) {
            inverted_command |= 1;
        } else if (pulse_buffer[2 * i + 1] < NEC_ZERO_SPACE * 1.2) {
            // It's a zero, do nothing
        } else {
            log_message(LOG_ERR, "Invalid bit space.");
            return -1;
        }
    }

    if ((address ^ inverted_address) != 0xFF || (command ^ inverted_command) != 0xFF) {
        log_message(LOG_ERR, "NEC checksum validation failed.");
        return -1;
    }

    return 0;
}

// MQTT publishing function
int publish_mqtt(unsigned int address, unsigned int command) {
    char payload[100];
    snprintf(payload, sizeof(payload), "{\"address\": %u, \"command\": %u}", address, command);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "MQTT publish failed.");
        return -1;
    }

    return 0;
}

// Logging function
void log_message(int priority, const char *message) {
    syslog(priority, message);
    fprintf(stderr, "%s\n", message); // Also print to stderr for debugging
}

int main() {
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin mode to input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up interrupt callback for falling edge detection
    gpioSetAlertFuncEx(GPIO_PIN, ir_callback, NULL);

    // Initialize MQTT client
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "MQTT client initialisation failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "MQTT connection failed");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "IR decoder started");

    unsigned int address, command;

    while (running) {
        if (pulse_count > 67) {
            if (decode_nec(pulse_buffer, pulse_count, &address, &command) == 0) {
                if (validate_nec_checksum(address, command) == 0) {
                    char log_msg[100];
                    snprintf(log_msg, sizeof(log_msg), "Decoded: Address = %u, Command = %u", address, command);
                    log_message(LOG_INFO, log_msg);

                    if (publish_mqtt(address, command) != 0) {
                        log_message(LOG_ERR, "Failed to publish MQTT message");
                    }
                } else {
                    log_message(LOG_ERR, "NEC checksum validation failed.");
                }
            } else {
                log_message(LOG_ERR, "NEC decoding failed.");
            }
            pulse_count = 0; // Reset pulse buffer
        }
        gpioDelay(1000); // Check every 1ms
    }

    // Clean up
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

