    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "MQTT connection failed");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "IR decoder started");

    unsigned int address, command;

    while (running) {
        if (pulse_count > 67) {
            if (decode_nec(pulse_buffer, pulse_count, &address, &command) == 0) {
                if (validate_nec_checksum(address, command) == 0) {
                    char log_msg[100];
                    snprintf(log_msg, sizeof(log_msg), "Decoded: Address = %u, Command = %u", address, command);
                    log_message(LOG_INFO, log_msg);

                    if (publish_mqtt(address, command) != 0) {
                        log_message(LOG_ERR, "Failed to publish MQTT message");
                    }
                } else {
                    log_message(LOG_ERR, "NEC checksum validation failed.");
                }
            } else {
                log_message(LOG_ERR, "NEC decoding failed.");
            }
            pulse_count = 0; // Reset pulse buffer
        }
        gpioDelay(1000); // Check every 1ms
    }

    // Clean up
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

