#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Define sensor addresses
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x24
#define BH1750_ADDR_3 0x25
#define BH1750_ADDR_4 0x26

// Define I2C device
#define I2C_DEVICE "/dev/i2c-1"

// Define multicast address and port
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005

// Define sensor IDs
#define SENSOR_ID_1 1
#define SENSOR_ID_2 2
#define SENSOR_ID_3 3
#define SENSOR_ID_4 4

// Global variable for termination flag
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Function to read lux value from BH1750 sensor
float read_bh1750(int fd, int addr) {
    unsigned char buf[2];
    int ret;

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error: Could not set I2C slave address");
        return NAN;
    }

    // Send start measurement command (High Resolution Mode)
    unsigned char start_cmd = 0x10;
    if (write(fd, &start_cmd, 1) != 1) {
        perror("Error: Could not write to I2C device");
        return NAN;
    }

    // Wait for 180ms
    usleep(180000);

    // Read 2 bytes of data
    ret = read(fd, buf, 2);
    if (ret != 2) {
        perror("Error: Could not read from I2C device");
        return NAN;
    }

    // Convert data to lux value
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Function to format sensor data into a string
char* format_sensor_data(float lux1, float lux2, float lux3, float lux4) {
    char *data = malloc(100 * sizeof(char)); // Allocate memory for the string
    if (data == NULL) {
        perror("Error: Could not allocate memory");
        return NULL;
    }

    snprintf(data, 100, "%d,%.2f;%d,%.2f;%d,%.2f;%d,%.2f",
             SENSOR_ID_1, lux1,
             SENSOR_ID_2, lux2,
             SENSOR_ID_3, lux3,
             SENSOR_ID_4, lux4);

    return data;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char *data) {
    int sockfd;
    struct sockaddr_in addr;
    socklen_t addrlen = sizeof(addr);
    int ttl = 1; // Time-to-live for multicast packets

    // Create UDP socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error: Could not create socket");
        return -1;
    }

    // Set multicast TTL
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("Error: Could not set multicast TTL");
        close(sockfd);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send data
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, addrlen) < 0) {
        perror("Error: Could not send data");
        close(sockfd);
        return -1;
    }

    // Close socket
    close(sockfd);
    return 0;
}

int main() {
    int i2c_fd;
    float lux1, lux2, lux3, lux4;
    char *sensor_data;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device");
        return 1;
    }

    printf("Starting sensor data acquisition...\n");

    while (!terminate) {
        // Read lux values from sensors
        lux1 = read_bh1750(i2c_fd, BH1750_ADDR_1);
        lux2 = read_bh1750(i2c_fd, BH1750_ADDR_2);
        lux3 = read_bh1750(i2c_fd, BH1750_ADDR_3);
        lux4 = read_bh1750(i2c_fd, BH1750_ADDR_4);

        // Format sensor data
        sensor_data = format_sensor_data(lux1, lux2, lux3, lux4);
        if (sensor_data == NULL) {
            fprintf(stderr, "Error: Could not format sensor data\n");
            continue; // Continue to the next iteration
        }

        // Send data via UDP multicast
        if (send_udp_multicast(sensor_data) < 0) {
            fprintf(stderr, "Error: Could not send UDP multicast\n");
        }

        free(sensor_data); // Free allocated memory

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device
    close(i2c_fd);

    printf("Exiting...\n");
    return 0;
}

