#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define AWM7300V_ADDR 0x28
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 20.0
#define LOG_FILE "airflow_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_airflow_data(uint16_t *raw_data);
float convert_to_slpm(uint16_t raw_data);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    float min_flow;
    float max_flow;
    int i2c_address;
} sensor_config_t;

// Initialize sensor configuration
sensor_config_t sensor_config = {
    .min_flow = FLOW_RATE_MIN,
    .max_flow = FLOW_RATE_MAX,
    .i2c_address = AWM7300V_ADDR
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    uint16_t raw_data;
    float flow_rate;

    // Main loop
    while (!terminate) {
        // Read airflow data
        if (read_airflow_data(&raw_data) == 0) {
            // Convert to SLPM
            flow_rate = convert_to_slpm(raw_data);

            // Log flow rate
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Failed to log flow rate\n");
            }
        } else {
            fprintf(stderr, "Failed to read airflow data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, sensor_config.i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read airflow data from the sensor
int read_airflow_data(uint16_t *raw_data) {
    char buf[2];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            *raw_data = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", 4 - retries, strerror(errno));
            gpioDelay(100); // pigpio's delay function
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries\n");
    return -1; // Failure
}

// Convert raw data to SLPM
float convert_to_slpm(uint16_t raw_data) {
    // Mask the 14-bit flow value
    uint16_t masked_data = raw_data & 0x3FFF;

    // Convert to SLPM (example formula, adjust based on sensor datasheet)
    float flow_rate = ((float)masked_data / 16383.0) * (sensor_config.max_flow - sensor_config.min_flow) + sensor_config.min_flow;

    return flow_rate;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

