FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the AS7341 sensor
int initialize_sensor() {
    // Verify sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, AS7341_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return -1;
