#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x4C
#define DEFAULT_SAMPLE_INTERVAL 1 // seconds
#define DEFAULT_FILENAME "seismic_data.csv"
#define I2C_BUS 1
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000 // 10 ms

// D7S Register Addresses (Example - Refer to Datasheet for correct values)
#define D7S_REG_X_LSB 0x02
#define D7S_REG_X_MSB 0x03
#define D7S_REG_Y_LSB 0x04
#define D7S_REG_Y_MSB 0x05
#define D7S_REG_Z_LSB 0x06
#define D7S_REG_Z_MSB 0x07

// Global variables
static int i2c_handle = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int sample_interval = DEFAULT_SAMPLE_INTERVAL;
static char *filename = DEFAULT_FILENAME;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x_g;
    float y_g;
    float z_g;
} sensor_data_t;

// Function prototypes
int init_i2c(int address);
int read_sensor_data(int handle, sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t data);
int log_error(FILE *fp, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(int handle, sensor_data_t *data) {
    char buf[6];
    int retries = RETRY_COUNT;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadI2CBlockData(handle, D7S_REG_X_LSB, buf, 6);
        if (bytes_read == 6) {
            // Combine LSB and MSB for each axis
            int16_t x_raw = (buf[1] << 8) | buf[0];
            int16_t y_raw = (buf[3] << 8) | buf[2];
            int16_t z_raw = (buf[5] << 8) | buf[4];

            // Convert raw data to g (adjust scale factor as needed)
            data->x_g = (float)x_raw / 1000.0f; // Example scale factor
            data->y_g = (float)y_raw / 1000.0f;
            data->z_g = (float)z_raw / 1000.0f;

            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", bytes_read, retries);
            log_error(error_file, "I2C read error");
            gpioDelay(RETRY_DELAY_US);
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to log data to CSV file
int log_data(FILE *fp, sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x_g, data.y_g, data.z_g) < 0) {
        fprintf(stderr, "Error writing to data file.\n");
        log_error(error_file, "Error writing to data file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Function to log errors to error log file
int log_error(FILE *fp, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to error file.\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

// Cleanup function to close files and I2C
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sample_interval = strtol(optarg, NULL, 0);
                if (sample_interval <= 0) {
                    fprintf(stderr, "Invalid sample interval. Using default value.\n");
                    sample_interval = DEFAULT_SAMPLE_INTERVAL;
                }
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sample_interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error opening error log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) != 0) {
        log_error(error_file, "I2C initialization failed");
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file!\n");
        log_error(error_file, "Error opening data file");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
    }
    rewind(data_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            if (log_data(data_file, sensor_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        sleep(sample_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

