// Function to log errors to error log file
int log_error(FILE *fp, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to error file.\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

// Cleanup function to close files and I2C
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sample_interval = strtol(optarg, NULL, 0);
                if (sample_interval <= 0) {
                    fprintf(stderr, "Invalid sample interval. Using default value.\n");
                    sample_interval = DEFAULT_SAMPLE_INTERVAL;
                }
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sample_interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error opening error log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) != 0) {
        log_error(error_file, "I2C initialization failed");
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file!\n");
        log_error(error_file, "Error opening data file");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
    }
    rewind(data_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            if (log_data(data_file, sensor_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        sleep(sample_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

