#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MAX_RETRIES 3

int i2c_fd = -1;
int udp_socket = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read data from the BH1750 sensor
int read_bh1750(uint16_t *raw_value) {
    unsigned char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Send command to start measurement
        if (write(i2c_fd, &CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
            perror("Error writing to I2C device");
            retries++;
            sleep(1);
            continue;
        }

        // Wait for measurement to complete (at least 180ms)
        usleep(200000); // 200ms

        // Read 2 bytes of data
        if (read(i2c_fd, buf, 2) != 2) {
            perror("Error reading from I2C device");
            retries++;
            sleep(1);
            continue;
        }

        // Convert big-endian to host byte order
        *raw_value = (buf[0] << 8) | buf[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw value to lux
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send data via UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    char buffer[32];
    int ttl = 1;

    // Create socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        return -1;
    }

    // Set multicast TTL
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Convert lux value to string
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    // Send data
    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending data");
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    return 0;
}

int main() {
    uint16_t raw_value;
    float lux_value;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    printf("BH1750 sensor reading and UDP multicast started.\n");

    while (1) {
        // Read sensor data
        if (read_bh1750(&raw_value) == 0) {
            // Convert to lux
            lux_value = convert_to_lux(raw_value);

            // Send via UDP multicast
            if (send_udp_multicast(lux_value) != 0) {
                fprintf(stderr, "Failed to send UDP multicast.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

