#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <stdint.h>

// Define UART port and baud rate
#define UART_PORT "/dev/ttyS0"
#define BAUD_RATE 921600

// Define magic word
#define MAGIC_WORD_SIZE 8
const uint8_t magic_word[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

// Define TLV types
#define TLV_TYPE_RANGE 1
#define TLV_TYPE_VELOCITY 2

// Define data file
#define DATA_FILE "radar_data.csv"

// Structure to hold radar data
typedef struct {
    time_t timestamp;
    int object_index;
    float range_m;
    float velocity_mps;
} radar_data_t;

// Global variables
int uart_fd = -1;
FILE *data_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int uart_init(const char *port, int baud_rate);
int uart_read(int fd, uint8_t *buffer, size_t size);
int sync_magic_word(int fd, uint8_t *buffer, size_t buffer_size);
int parse_tlv(uint8_t *buffer, size_t size, radar_data_t *data);
int validate_tlv(uint8_t *buffer, size_t size);
int extract_range(uint8_t *buffer, size_t size, float *range);
int extract_velocity(uint8_t *buffer, size_t size, float *velocity);
int write_data_to_file(radar_data_t data);
void signal_handler(int signal);
void cleanup();

// UART initialization function
int uart_init(const char *port, int baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART port %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_iflag = 0;

    tty.c_cc[VMIN] = 0;  // Non-blocking read
    tty.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// UART read function with timeout
int uart_read(int fd, uint8_t *buffer, size_t size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 1; // Timeout after 1 second
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error in select(): %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        ssize_t bytes_read = read(fd, buffer, size);
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        return (int)bytes_read;
    }
}

// Function to synchronize on the magic word
int sync_magic_word(int fd, uint8_t *buffer, size_t buffer_size) {
    size_t magic_word_index = 0;
    uint8_t read_byte;

    while (magic_word_index < MAGIC_WORD_SIZE) {
        int bytes_read = uart_read(fd, &read_byte, 1);
        if (bytes_read == -1) {
            return -1; // Error reading from UART
        } else if (bytes_read == 0) {
            // Timeout occurred, continue waiting
            continue;
        }

        if (read_byte == magic_word[magic_word_index]) {
            magic_word_index++;
        } else {
            magic_word_index = 0; // Reset if mismatch
        }
    }

    return 0; // Synchronized successfully
}

// Function to validate TLV
int validate_tlv(uint8_t *buffer, size_t size) {
    if (size < 4) {
        fprintf(stderr, "TLV too small to contain type and length\n");
        return -1;
    }

    uint16_t type = *((uint16_t *)buffer);
    uint16_t length = *((uint16_t *)(buffer + 2));

    if (length > size) {
        fprintf(stderr, "TLV length exceeds buffer size\n");
        return -1;
    }

    return 0;
}

// Function to extract range from TLV
int extract_range(uint8_t *buffer, size_t size, float *range) {
    if (size < 8) {
        fprintf(stderr, "Range TLV too small\n");
        return -1;
    }

    *range = *((float *)(buffer + 4));
    return 0;
}

// Function to extract velocity from TLV
int extract_velocity(uint8_t *buffer, size_t size, float *velocity) {
    if (size < 8) {
        fprintf(stderr, "Velocity TLV too small\n");
        return -1;
    }

    *velocity = *((float *)(buffer + 4));
    return 0;
}

// Function to parse TLV data
int parse_tlv(uint8_t *buffer, size_t size, radar_data_t *data) {
    uint16_t type = *((uint16_t *)buffer);
    uint16_t length = *((uint16_t *)(buffer + 2));

    if (type == TLV_TYPE_RANGE) {
        if (extract_range(buffer, size, &data->range_m) != 0) {
            fprintf(stderr, "Error extracting range\n");
            return -1;
        }
    } else if (type == TLV_TYPE_VELOCITY) {
        if (extract_velocity(buffer, size, &data->velocity_mps) != 0) {
            fprintf(stderr, "Error extracting velocity\n");
            return -1;
        }
    } else {
        fprintf(stderr, "Unknown TLV type: %d\n", type);
        return -1;
    }

    return 0;
}

// Function to write data to file
int write_data_to_file(radar_data_t data) {
    if (data_file == NULL) {
        fprintf(stderr, "Data file is not open\n");
        return -1;
    }

    fprintf(data_file, "%ld,%d,%.2f,%.2f\n", data.timestamp, data.object_index, data.range_m, data.velocity_mps);
    fflush(data_file); // Ensure data is written immediately

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    // Call the provided driver library's cleanup function here
    // Example: driver_cleanup();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = uart_init(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART initialization failed\n");
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t buffer[2048]; // Buffer for UART data
    size_t buffer_index = 0;
    radar_data_t radar_data;
    int object_index = 0;

    // Main loop
    while (!terminate) {
        int bytes_read = uart_read(uart_fd, buffer + buffer_index, sizeof(buffer) - buffer_index);
        if (bytes_read > 0) {
            buffer_index += bytes_read;

            // Process the buffer
            size_t tlv_index = 0;
            while (tlv_index < buffer_index) {
                if (buffer_index - tlv_index >= 4) {
                    uint16_t tlv_length = *((uint16_t *)(buffer + tlv_index + 2));
                    if (tlv_index + 4 + tlv_length <= buffer_index) {
                        if (validate_tlv(buffer + tlv_index, 4 + tlv_length) == 0) {
                            radar_data.timestamp = time(NULL);
                            radar_data.object_index = object_index++;
                            if (parse_tlv(buffer + tlv_index, 4 + tlv_length, &radar_data) == 0) {
                                write_data_to_file(radar_data);
                            }
                        } else {
                            fprintf(stderr, "Invalid TLV, skipping\n");
                        }
                        tlv_index += 4 + tlv_length;
                    } else {
                        break; // Not enough data for the TLV, wait for more
                    }
                } else {
                    break; // Not enough data for TLV header, wait for more
                }
            }

            // Shift remaining data to the beginning of the buffer
            if (tlv_index < buffer_index) {
                memmove(buffer, buffer + tlv_index, buffer_index - tlv_index);
                buffer_index -= tlv_index;
            } else {
                buffer_index = 0; // Reset buffer index if all data processed
            }

        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting\n");
            break;
        }

        // Synchronize on magic word if no data is received for a while
        if (buffer_index == 0) {
            if (sync_magic_word(uart_fd, buffer, sizeof(buffer)) != 0) {
                fprintf(stderr, "Failed to sync magic word\n");
                break;
            }
            buffer_index = 0; // Reset buffer index after synchronization
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

