// UART initialization function
int uart_init(const char *port, int baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART port %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_iflag = 0;

    tty.c_cc[VMIN] = 0;  // Non-blocking read
    tty.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// UART read function with timeout
int uart_read(int fd, uint8_t *buffer, size_t size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 1; // Timeout after 1 second
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error in select(): %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        ssize_t bytes_read = read(fd, buffer, size);
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        return (int)bytes_read;
    }
}

// Function to synchronize on the magic word
int sync_magic_word(int fd, uint8_t *buffer, size_t buffer_size) {
    size_t magic_word_index = 0;
    uint8_t read_byte;

    while (magic_word_index < MAGIC_WORD_SIZE) {
        int bytes_read = uart_read(fd, &read_byte, 1);
        if (bytes_read == -1) {
            return -1; // Error reading from UART
        } else if (bytes_read == 0) {
            // Timeout occurred, continue waiting
            continue;
        }

        if (read_byte == magic_word[magic_word_index]) {
            magic_word_index++;
        } else {
            magic_word_index = 0; // Reset if mismatch
        }
    }

    return 0; // Synchronized successfully
}

// Function to validate TLV
int validate_tlv(uint8_t *buffer, size_t size) {
    if (size < 4) {
        fprintf(stderr, "TLV too small to contain type and length\n");
        return -1;
    }

    uint16_t type = *((uint16_t *)buffer);
    uint16_t length = *((uint16_t *)(buffer + 2));

    if (length > size) {
        fprintf(stderr, "TLV length exceeds buffer size\n");
        return -1;
    }

    return 0;
}

// Function to extract range from TLV
int extract_range(uint8_t *buffer, size_t size, float *range) {
    if (size < 8) {
        fprintf(stderr, "Range TLV too small\n");
        return -1;
    }

    *range = *((float *)(buffer + 4));
    return 0;
}

// Function to extract velocity from TLV
