#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <termios.h>
#include <sys/select.h>
#include <sys/time.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/file.h>
#include <stdbool.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUFFER_SIZE 256
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"
#define LOG_FILE "/var/log/radar_data.log"

// Global variables for signal handling and file descriptor
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure to hold radar data
typedef struct {
    time_t timestamp;
    float range;
} radar_data_t;

// Function prototypes
int configure_uart(int fd);
int read_uart_data(int fd, char *buffer, size_t buffer_size);
int parse_radar_data(const char *line, radar_data_t *data);
int log_radar_data(const radar_data_t *data);
void signal_handler(int signal);
int acquire_lock(int fd);
int release_lock(int fd);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Signal received, exiting gracefully.\n");
}

// Function to configure the UART
int configure_uart(int fd) {
    struct termios tty;

    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr failed");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 50; // Wait for 0.5 seconds (50 deciseconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr failed");
        return -1;
    }

    return 0;
}

// Function to read data from the UART with timeout
int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;
    int ret;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 2;  // 2-second timeout
    timeout.tv_usec = 0;

    ret = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (ret == -1) {
        perror("select failed");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout reading from UART.\n");
        return 0; // Timeout
    } else {
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("read failed");
            return -1;
        } else {
            buffer[bytes_read] = '\0';
            return bytes_read;
        }
    }
}

// Function to parse radar data from a line
int parse_radar_data(const char *line, radar_data_t *data) {
    char *token;
    char *line_copy = strdup(line); // Duplicate the line for strtok
    if (line_copy == NULL) {
        perror("strdup failed");
        return -1;
    }

    // Get the timestamp
    token = strtok(line_copy, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Missing timestamp in line: %s\n", line);
        free(line_copy);
        return -1;
    }
    char *endptr;
    data->timestamp = strtol(token, &endptr, 10);
    if (*endptr != '\0') {
        fprintf(stderr, "Error: Invalid timestamp format: %s\n", token);
        free(line_copy);
        return -1;
    }

    // Get the range
    token = strtok(NULL, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error: Missing range in line: %s\n", line);
        free(line_copy);
        return -1;
    }
    data->range = strtof(token, &endptr);
    if (*endptr != '\0') {
        fprintf(stderr, "Error: Invalid range format: %s\n", token);
        free(line_copy);
        return -1;
    }

    free(line_copy);
    return 0;
}

// Function to log radar data to a file
int log_radar_data(const radar_data_t *data) {
    struct tm *tm_info;
    char timestamp_str[64];

    tm_info = localtime(&data->timestamp);
    if (tm_info == NULL) {
        perror("localtime failed");
        return -1;
    }

    if (strftime(timestamp_str, sizeof(timestamp_str), TIMESTAMP_FORMAT, tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (acquire_lock(fileno(log_file)) != 0) {
        fprintf(stderr, "Failed to acquire lock on log file.\n");
        return -1;
    }

    fprintf(log_file, "Timestamp: %s, Range: %.2f meters\n", timestamp_str, data->range);
    fflush(log_file); // Ensure data is written to disk

    if (release_lock(fileno(log_file)) != 0) {
        fprintf(stderr, "Failed to release lock on log file.\n");
        return -1;
    }

    return 0;
}

// Function to acquire a file lock
int acquire_lock(int fd) {
    struct flock fl = {0};
    fl.l_type = F_WRLCK;  // Write lock (exclusive)
    fl.l_whence = SEEK_SET; // Start from the beginning of the file
    fl.l_start = 0;        // Lock the entire file
    fl.l_len = 0;          // Lock the entire file

    if (fcntl(fd, F_SETLKW, &fl) == -1) { // Blocking lock
        perror("fcntl (acquire lock) failed");
        return -1;
    }
    return 0;
}

// Function to release a file lock
int release_lock(int fd) {
    struct flock fl = {0};
    fl.l_type = F_UNLCK;  // Unlock
    fl.l_whence = SEEK_SET; // Start from the beginning of the file
    fl.l_start = 0;        // Unlock the entire file
    fl.l_len = 0;          // Unlock the entire file

    if (fcntl(fd, F_SETLKW, &fl) == -1) { // Blocking unlock
        perror("fcntl (release lock) failed");
        return -1;
    }
    return 0;
}

int main() {
    char line_buffer[LINE_BUFFER_SIZE];
    size_t line_buffer_index = 0;
    radar_data_t radar_data;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the UART device
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (uart_fd == -1) {
        perror("open failed");
        return EXIT_FAILURE;
    }

    // Configure the UART
    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen failed");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        char read_buffer[1];
        int bytes_read = read_uart_data(uart_fd, read_buffer, 1);

        if (bytes_read > 0) {
            line_buffer[line_buffer_index++] = read_buffer[0];

            if (read_buffer[0] == '\n') {
                line_buffer[line_buffer_index] = '\0';

                if (parse_radar_data(line_buffer, &radar_data) == 0) {
                    if (log_radar_data(&radar_data) != 0) {
                        fprintf(stderr, "Error logging radar data.\n");
                    }
                } else {
                    fprintf(stderr, "Error parsing radar data: %s", line_buffer);
                }

                line_buffer_index = 0; // Reset buffer index
            }

            if (line_buffer_index >= LINE_BUFFER_SIZE - 1) {
                fprintf(stderr, "Line buffer overflow.\n");
                line_buffer_index = 0; // Reset buffer index to prevent further overflow
            }
        } else if (bytes_read < 0) {
            // Error reading from UART, exit loop
            break;
        }
    }

    // Close the UART device and log file
    close(uart_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

