                    fprintf(stderr, "Error parsing radar data: %s", line_buffer);
                }

                line_buffer_index = 0; // Reset buffer index
            }

            if (line_buffer_index >= LINE_BUFFER_SIZE - 1) {
                fprintf(stderr, "Line buffer overflow.\n");
                line_buffer_index = 0; // Reset buffer index to prevent further overflow
            }
        } else if (bytes_read < 0) {
            // Error reading from UART, exit loop
            break;
        }
    }

    // Close the UART device and log file
    close(uart_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

