#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART device
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables for UART handle and program state
int uart_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
int check_emergency_stop(int left, int middle, int right);
int send_uart_message(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} SensorData;

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to check if an emergency stop is required
int check_emergency_stop(int left, int middle, int right) {
    return (left == 0 && middle == 0 && right == 0) ? 1 : 0;
}

// Function to send a message over UART
int send_uart_message(const char *message) {
    if (uart_handle < 0) {
        fprintf(stderr, "Error: UART not initialized.\n");
        return -1;
    }

    int bytes_written = gpioSerialWrite(uart_handle, message, strlen(message));
    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to UART: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Open UART
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for 8N1
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Close UART
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left_sensor, middle_sensor, right_sensor);

        // Check for emergency stop
        if (check_emergency_stop(left_sensor, middle_sensor, right_sensor)) {
            if (send_uart_message("EMERGENCY STOP!\n") != 0) {
                fprintf(stderr, "Error sending emergency stop message.\n");
            }
        }

        // Delay for 100ms (10Hz)
        gpioDelay(100000); // 100000 microseconds = 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

